; GFA_BCOM.PRG  -  GFA-BASIC Compiler 3.03 E
;
; Devpac source of the compiler, disassembled by Darren Birks, 4 November 2026.  Assembled, it gives
; GFA_BCOM.PRG byte for byte, relocations included:
;
;     vasmm68k_mot -devpac -m68000 -Ftos -o GFA_BCOM.PRG GFA_BCOM.S
;
; The compiler reads a tokenised .GFA file, checks its structure, parses each line into an intermediate
; code (IR words $8000 and up; words below $8000 are library routine numbers), optimises the IR and
; generates 68000 code from it, then writes the .O object file that GL.PRG links with GFA3BLIB.
;
; Registers through most of the compiler: a5 reads the source tokens, a4 writes the IR, a1 writes the
; generated code, a6 holds the branch list, a3 the end of the IR.  The names of the library routines
; are the 8-byte table at library_name_table (routine n at +n*8).


	section	text

;------------------------------------------------------------------------------
; Program start. Prints the title, then scans the environment strings (basepage+$2c) for the shell's settings:
; G3OBJ=path (object file name, pointer kept in object_file_name_pointer), G3WAIT=ON/OFF (prompt for disks,
; no_disk_prompt_flag) and G3MOVE=ON/OFF (no_move_flag). Each variable name is packed into d0/d1 four and two
; characters at a time and compared as longs.
;------------------------------------------------------------------------------
start:
	pea	title_message(pc)               ; Cconws(title_message)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws
	addq.l	#6,sp
	bra.s	scan_environment
title_message:
	dc.b	13,'GFA-BASIC Compiler 3.03 E',13,10,0
	dc.b	$00

scan_environment:
	movea.l	start-$d4(pc),a0                ; a0 = basepage+$2c: environment strings
.next_variable:
	tst.b	(a0)                            ; empty string: end of the environment
	beq.w	.environment_done               ; zero byte: no more strings
	moveq	#0,d0                           ; d0/d1 collect the name: four characters, then two
	moveq	#1,d1                           ; marker bit: leaves d0 as carry after four characters
.read_name_char:
	rol.w	#8,d1                           ; previous character into d1's high byte
	asl.l	#8,d0                           ; carry: the marker left d0, three characters in d0
	bcs.s	.name_read                      ; carry: four characters in d0
	move.b	d1,d0                           ; append the previous character to d0
	move.b	(a0)+,d1                        ; next name character
	bne.s	.read_name_char                 ; until the string's zero byte
	bra.s	.next_variable                  ; string too short for a setting: next one
.name_read:
	move.b	d1,d0                           ; fourth character completes d0
	move.b	(a0)+,d1                        ; d1 = characters five and six
	beq.s	.next_variable                  ; string ended
	cmpi.l	#$47334f42,d0                   ; "G3OB"
	bne.s	.not_g3obj
	cmpi.w	#$4a3d,d1                       ; "J=": G3OBJ=
	bne.s	.not_g3obj
	move.l	a0,object_file_name_pointer     ; object file name for the writer
.not_g3obj:
	cmpi.l	#$47335741,d0                   ; "G3WA"
	bne.s	.not_g3wait
	cmpi.w	#$4954,d1                       ; "IT": G3WAIT
	bne.s	.not_g3wait
	lea	no_disk_prompt_flag(pc),a1      ; a1 = the flag G3WAIT sets
.parse_on_off:
	move.b	(a0)+,d2                        ; character after the name
	beq.s	.next_variable                  ; string ended
	cmpi.b	#$3d,d2                         ; '='
	bne.s	.skip_variable                  ; no '=': ignore this string
	move.b	(a0)+,d2                        ; first character after '='
	beq.s	.next_variable
	andi.b	#$df,d2                         ; upper case
	cmpi.b	#$4f,d2                         ; 'O'
	bne.s	.skip_variable                  ; no 'O': ignore this string
	move.b	(a0)+,d2                        ; second character
	beq.s	.next_variable
	andi.b	#$df,d2                         ; upper case
	cmpi.b	#$4e,d2                         ; 'N': ON
	beq.s	.set_on
	cmpi.b	#$46,d2                         ; 'F': OFF
	bne.s	.skip_variable                  ; 'F': OFF; anything else leaves the flag
	st	(a1)                            ; OFF sets the flag
	bra.s	.skip_variable                  ; and skip the rest
.set_on:
	sf	(a1)                            ; ON clears the flag
	bra.s	.skip_variable                  ; and skip the rest
.not_g3wait:
	cmpi.l	#$47334d4f,d0                   ; "G3MO"
	bne.s	.skip_variable
	cmpi.w	#$5645,d1                       ; "VE": G3MOVE
	bne.s	.skip_variable
	lea	no_move_flag(pc),a1             ; a1 = the flag G3MOVE sets
	bra.s	.parse_on_off                   ; parse its ON/OFF
.skip_variable:
	tst.b	(a0)+                           ; skip to the end of this string
	bne.s	.skip_variable                  ; until the zero byte
	bra.w	.next_variable                  ; next environment string

;------------------------------------------------------------------------------
; Shrinks the TPA to the end of the bss (program_end), takes all free memory less 16K with Malloc, and, if the
; parent basepage belongs to the GFA shell (magic $04030201 at $80), gives the shell the address of
; source_line_number so it can show where an error is. Then: clear library name spaces, load the .GFA file,
; check its structure, set up (assign_variable_offsets), read the command-line options, compile, write the
; object file (write_object_file) and terminate with exit_code.
;------------------------------------------------------------------------------
.environment_done:
	lea	start-$100(pc),a5               ; a5 = basepage
	lea	program_end,a0                  ; a0 = end of the bss
	lea	program_end,sp                  ; stack ends at the top of the bss
	suba.l	a5,a0                           ; a0 = bytes to keep from the basepage
	pea	(a0)                            ; Mshrink(0, basepage, size)
	pea	(a5)
	clr.w	-(sp)
	move.w	#$4a,-(sp)                      ; Mshrink
	trap	#1                              ; Mshrink
	pea	$ffffffff.w                     ; Malloc(-1): size of the largest free block
	move.w	#$48,-(sp)                      ; Malloc
	trap	#1                              ; Malloc
	subi.l	#$4000,d0                       ; keep 16K free
	move.l	d0,free_memory_size             ; bytes the compiler may use
	move.l	d0,-(sp)                        ; Malloc all of it less 16K
	move.w	#$48,-(sp)                      ; Malloc
	trap	#1                              ; Malloc
	move.l	d0,free_memory_pointer          ; start of the compiler's memory
	movea.l	start-$dc(pc),a0                ; parent basepage
	move.l	a0,d0                           ; parent basepage 0?
	beq.s	.no_shell                       ; no parent basepage
	cmpi.l	#$4030201,$80(a0)               ; the GFA shell marks its basepage with $04030201
	bne.s	.no_shell                       ; not the GFA shell
	movea.l	$84(a0),a0                      ; a0 = the long at parent basepage+$84 (shell data)
	move.l	#source_line_number,2(a0)       ; tell the shell where the line number is
.no_shell:
	lea	program_end,sp                  ; reset the stack
	bsr.w	clear_library_name_spaces       ; spaces in library_name_table become zero bytes
	bsr.w	load_gfa_file                   ; read the .GFA file
	bsr.w	check_program_structure         ; N set when the structure is wrong
	bpl.s	.structure_ok
	pea	structure_error_message(pc)     ; Cconws(structure_error_message)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws
	addq.l	#6,sp
	move.w	#$ffff,exit_code                ; exit code -1
	bra.s	.terminate
.structure_ok:
	jsr	assign_variable_offsets         ; set up variable offsets
	bsr.w	parse_command_line_options      ; read the command-line options
	movea.l	program_start,a5                ; a5 = first program line
	lea	branch_offset_list,a6           ; a6 = start of branch_offset_list
	bsr.w	compile_program                 ; compile the program
	jsr	write_object_file               ; write the .O file
.terminate:
	move.w	exit_code(pc),-(sp)             ; Pterm(exit_code)
	move.w	#$4c,-(sp)                      ; Pterm
	trap	#1                              ; Pterm
structure_error_message:
	dc.b	13,10,'Program has stucture errors',13,10
	dc.b	' -- Test with interpreter! --',13,10,0
	dc.b	$00

;------------------------------------------------------------------------------
; Reports a statement the compiler cannot compile. Called with bsr followed by the command name as an inline
; string: prints the line number, then the inline string (the return address on the stack is used as the
; Cconws argument and removed with it), then " - nicht compiliert"; the rts returns to the caller's caller.
;------------------------------------------------------------------------------
report_not_compiled:
	bsr.s	print_line_number               ; print the line number
	move.w	#$9,-(sp)                       ; Cconws(inline string): the return address is the argument
	trap	#1                              ; Cconws
	addq.l	#6,sp                           ; removes the return address as well
	pea	not_compiled_message(pc)        ; Cconws(" - nicht compiliert")
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws
	addq.l	#6,sp
	rts                                     ; returns to the caller's caller
not_compiled_message:
	dc.b	' - not compiled',13,10,0
exit_code:
	dc.w	$0000

;------------------------------------------------------------------------------
; Prints source_line_number-1 as five characters (leading zeros shown as spaces, the last digit always shown)
; followed by a space, using header_and_text_buffer. Adds 1 to exit_code (the error count).
;------------------------------------------------------------------------------
print_line_number:
	moveq	#32,d1                          ; d1 = ' ': leading zeros
	moveq	#48,d2                          ; d2 = '0'
	lea	header_and_text_buffer,a0       ; a0 = text buffer
	pea	(a0)                            ; Cconws argument
	moveq	#0,d0                           ; d0 high word clear for divu
	move.w	source_line_number,d0           ; the counter is one ahead
	subq.w	#1,d0
	divu.w	#$2710,d0                       ; ten thousands
	tst.w	d0                              ; digit zero?
	beq.s	.store_ten_thousands            ; zero digit: keep the fill
	move.w	d2,d1                           ; from the first non-zero digit on, digits are shown as '0'+n
.store_ten_thousands:
	or.w	d1,d0                           ; digit as ' ' (leading zero) or '0'+n
	move.b	d0,(a0)+                        ; store the ten thousands digit
	swap	d0                              ; remainder to the low word
	ext.l	d0                              ; clear the quotient half for the next divu
	divu.w	#$3e8,d0                        ; thousands
	tst.w	d0                              ; digit zero?
	beq.s	.store_thousands                ; zero digit: keep the fill
	move.w	d2,d1                           ; from here on digits show as '0'+n
.store_thousands:
	or.w	d1,d0                           ; digit as ' ' (leading zero) or '0'+n
	move.b	d0,(a0)+                        ; store the thousands digit
	swap	d0
	ext.l	d0
	divu.w	#$64,d0                         ; hundreds
	tst.w	d0                              ; digit zero?
	beq.s	.store_hundreds                 ; zero digit: keep the fill
	move.w	d2,d1                           ; from here on digits show as '0'+n
.store_hundreds:
	or.w	d1,d0                           ; digit as ' ' (leading zero) or '0'+n
	move.b	d0,(a0)+                        ; store the hundreds digit
	swap	d0                              ; remainder to the low word
	ext.l	d0                              ; clear the quotient half for the next divu
	divu.w	#$a,d0                          ; tens
	tst.w	d0                              ; digit zero?
	beq.s	.store_tens                     ; zero digit: keep the fill
	move.w	d2,d1                           ; from here on digits show as '0'+n
.store_tens:
	or.w	d1,d0                           ; digit as ' ' (leading zero) or '0'+n
	move.b	d0,(a0)+                        ; store the tens digit
	swap	d0                              ; units
	or.w	d2,d0                           ; units digit always shown
	move.b	d0,(a0)+                        ; store the units digit
	move.b	#$20,(a0)+                      ; space after the number
	clr.b	(a0)+                           ; end of the string
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws
	addq.l	#6,sp
	addq.w	#1,exit_code                    ; one more error
	rts

;------------------------------------------------------------------------------
; Reads the options after the file name on the command line. The rest of the line is ended with CR and passed
; to the option parser parse_compiler_options (the same one that handles $ lines) with parsing_command_line_flag
; set; IR is written from statement_code_buffer through a4. irqon_at_start_flag is set when the first option word
; is library routine $33f IRQON (option I+). Also presets the M option size to -1 and clears several options.
;------------------------------------------------------------------------------
parse_command_line_options:
	move.l	#$ffffffff,option_m_memory_size ; M option: none
	clr.b	option_percent_value            ; option %: none
	clr.b	option_rc_word_flag             ; RC option off
	clr.b	flag_121d3
	clr.w	break_check_flag                ; U option (break check) off
	clr.l	option_f_flag                   ; clears the F, *, E$ and RESUME NEXT flags
	lea	start-$80(pc),a0                ; command line: length byte, then the text
	tst.b	(a0)+
	beq.s	.no_options                     ; length 0: no options
.skip_spaces:
	cmpi.b	#$20,(a0)+                      ; skip the spaces before the name
	beq.s	.skip_spaces
	subq.l	#1,a0                           ; back to the first character
.skip_file_name:
	move.b	(a0)+,d0                        ; skip the file name
	beq.s	.options_found                  ; zero: the line ends after the name
	cmpi.b	#$20,d0
	bne.s	.skip_file_name                 ; space ends the name
.options_found:
	movea.l	a0,a5                           ; a5 = option text for the parser
.find_end:
	tst.b	(a0)+                           ; find the zero at the end
	bne.s	.find_end
	move.b	#$d,-(a0)                       ; end the options with CR
	lea	statement_code_buffer,a4        ; a4 = IR output for the options
	st	parsing_command_line_flag       ; the parser reads the command line, not a $ line
	bsr.w	parse_compiler_options          ; parse the options into IR
	sf	parsing_command_line_flag
	cmpi.w	#$33f,statement_code_buffer     ; first IR word = library routine $33f IRQON (I+)
	seq	irqon_at_start_flag             ; $ff: call IRQON at the start
.no_options:
	rts

;------------------------------------------------------------------------------
; Turns the spaces in the 8-byte library routine name table at $f8a6 into zero bytes, up to the first byte with
; bit 7 set.
;------------------------------------------------------------------------------
clear_library_name_spaces:
	lea	library_name_table,a0           ; a0 = 8-byte library routine names
	moveq	#32,d0                          ; d0 = space
.next_name_byte:
	move.b	(a0),d1                         ; d1 = next name byte
	cmp.b	d0,d1                           ; a space?
	bne.s	.store_name_byte
	moveq	#0,d1                           ; space becomes a zero byte
.store_name_byte:
	move.b	d1,(a0)+                        ; store; bit 7 set ends the table
	bpl.s	.next_name_byte                 ; until a byte with bit 7 set (the table end)
	rts
gfa_file_magic:
	dc.w	$0003
	dc.b	'GFA-BASIC3'

exit_bad_gfa_file:
	move.w	#$ff9c,-(sp)                    ; Pterm(-100): not a GFA 3 file
	move.w	#$4c,-(sp)                      ; Pterm
	trap	#1                              ; Pterm

;------------------------------------------------------------------------------
; Loads the .GFA file. The command line's first word (or COMP.GFA when it is empty) is taken as the name and
; ".GFA" appended. Reads the 12-byte header (version word, "GFA-BASIC3"; version must be 4 or less) and the
; 38 section offsets (relative to $a4), turns them into addresses in gfa_section_addresses, places the
; per-identifier tables (sections 19-35) at the start of the buffer followed by six routine tables
; (label code/data offsets, procedure, function, string function code offsets, preset to -1) and reads the
; names and the program after them.
; Then a pre-pass over every line halves the command word (4 x token becomes 2 x token), copies DATA text to the
; data area (commas become zero bytes), moves INLINE data there, records each label's DATA position for
; RESTORE, drops the jump long of the loop/IF/SELECT commands, and turns REM ' . and DEFxxx lines into empty
; 4-byte lines. At the program's last line (command 45) the data area is moved down behind the program and
; the code buffer is placed $1000 bytes after it.
;------------------------------------------------------------------------------
load_gfa_file:
	move.l	#program_end,free_memory_pointer ; load at the end of the bss
	lea	start-$80(pc),a0                ; command line (length byte first)
	tst.b	(a0)+                           ; length byte 0?
	bne.s	.copy_name                      ; length byte 0: no name given
	lea	default_gfa_name,a0             ; no name: COMP.GFA
.copy_name:
	lea	program_end,a1                  ; a1 = name buffer at program_end
.skip_spaces:
	cmpi.b	#$20,(a0)+                      ; skip the spaces before the name
	beq.s	.skip_spaces
	subq.l	#1,a0                           ; back to the first character
.copy_name_char:
	move.b	(a0)+,d0                        ; next name character
	cmpi.b	#$20,d0
	beq.s	.add_extension                  ; space ends the name
	move.b	d0,(a1)+                        ; store it; the zero ends the name too
	bne.s	.copy_name_char                 ; until the zero byte
	subq.l	#1,a1                           ; back over the zero
.add_extension:
	move.b	#$2e,(a1)+                      ; append ".GFA"
	move.b	#$47,(a1)+
	move.b	#$46,(a1)+
	move.b	#$41,(a1)+
	clr.b	(a1)+                           ; end the name
	lea	program_end,a0                  ; a0 = the file name
	bsr.w	open_file                       ; open the .GFA file
	lea	header_and_text_buffer,a0       ; read the 12-byte header
	moveq	#12,d0                          ; the version word and "GFA-BASIC3"
	bsr.w	read_file                       ; read the header
	moveq	#9,d0                           ; 10 characters "GFA-BASIC3"
	lea	header_and_text_buffer,a0       ; a0 = version byte in the header
	lea	gfa_file_magic(pc),a1           ; a1 = the expected version and magic
	cmpm.b	(a0)+,(a1)+                     ; version byte above 4: not a usable file
	bcs.s	exit_bad_gfa_file               ; version above 4: not usable
.compare_magic:
	cmpm.b	(a0)+,(a1)+
	dbne	d0,.compare_magic               ; compare the ten magic characters
	bne.s	exit_bad_gfa_file               ; magic differs: not a GFA 3 file
	lea	header_and_text_buffer,a0       ; read the 38 section offsets
	move.l	#$98,d0                         ; $98 = 38 longs
	bsr.w	read_file                       ; read the section offsets
	lea	gfa_section_addresses,a0        ; a0 = section address table
	lea	gfa_section_addresses_end,a1    ; a1 = its end
	lea	header_and_text_buffer,a2       ; a2 = the offsets just read
	move.l	free_memory_pointer,d0          ; load base
.relocate_sections:
	move.l	(a2)+,d1                        ; offset + load base = address
	add.l	d0,d1                           ; d1 = address in memory
	move.l	d1,(a0)+
	cmpa.l	a0,a1                           ; until gfa_section_addresses_end
	bne.s	.relocate_sections              ; until the 38 offsets are done
	move.l	d1,(a0)+                        ; the last address again in the next entry
	move.l	4(a0),(a0)                      ; two more entries after the 38
	lea	$64(a1),a1                      ; a1 is reloaded below: this add has no effect
	movea.l	free_memory_pointer,a0          ; a0 = load base
	lea	float_variable_table,a1         ; a1 = the flag table pointers (section 19 on)
	move.l	(a1),d6                         ; d6 = size of names + program (sections 0-18)
	move.l	d6,d0                           ; d0 = d6
	sub.l	gfa_section_addresses,d6        ; d6 = bytes in sections 0-18
	sub.l	gfa_section_addresses,d0        ; d0 = distance the flag tables move down
	lea	identifier_flag_tables_end,a2   ; a2 = end of the flag table pointers
.rebase_flag_tables:
	sub.l	d0,(a1)+                        ; move the flag tables (sections 19-35) to the buffer start
	cmpa.l	a2,a1                           ; up to and including the end pointer
	bls.s	.rebase_flag_tables
	movea.l	(a2),a0                         ; a0 = end of the moved flag tables
	movea.l	a0,a1                           ; a1 = start of the routine tables
	movem.l	label_line_table,d0-d1          ; label table start / end: size of a label table
	sub.l	d0,d1                           ; d1 = size of a label table
	move.l	a0,label_address_table          ; label code address table
	adda.l	d1,a0                           ; skip the label code address table
	move.l	a0,label_data_offsets           ; label DATA offset table
	adda.l	d1,a0                           ; a0 = after the two label tables
	movem.l	procedure_line_table,d0-d1      ; procedure table start / end
	sub.l	d0,d1                           ; d1 = size of the procedure table
	move.l	a0,procedure_address_table      ; procedure code address table
	adda.l	d1,a0                           ; a0 = after the procedure table
	move.l	a0,numeric_fn_address_table     ; numeric function code address table
	movem.l	function_line_table,d0-d2       ; function, string function, end
	sub.l	d1,d2                           ; d2 = string function table size
	sub.l	d0,d1                           ; d1 = numeric function table size
	adda.l	d1,a0                           ; skip the numeric function table
	move.l	a0,string_fn_address_table      ; string function code address table
	adda.l	d2,a0                           ; skip the string function table
	move.l	a0,free_memory_pointer          ; free memory starts after the routine tables
	move.l	a0,routine_tables_end           ; end of the routine tables, for move_code_down
	moveq	#0,d0                           ; clear the flag tables up to the routine tables
	movea.l	float_variable_table,a2         ; a2 = start of the flag tables
.clear_flag_tables:
	move.l	d0,(a2)+
	cmpa.l	a1,a2
	bcs.s	.clear_flag_tables
	moveq	#-1,d0                          ; d0 = -1
.preset_routine_tables:
	move.l	d0,(a1)+                        ; routine tables start as -1 (undefined)
	cmpa.l	a0,a1                           ; until the end of the routine tables
	bcs.s	.preset_routine_tables
	lea	gfa_section_addresses,a1        ; names and program go after the tables
	move.l	(a1),d0                         ; d0 = old address of section 0
	sub.l	a0,d0                           ; d0 = distance the names move down
	lea	program_start,a2                ; a2 = last section pointer to rebase
.rebase_name_sections:
	sub.l	d0,(a1)+                        ; rebase sections 0-18 to a0
	cmpa.l	a2,a1                           ; up to and including program_start
	bls.s	.rebase_name_sections
	move.l	d6,d0                           ; d0 = bytes to read
	lea	0(a0,d0.l),a1                   ; free memory after the program
	move.l	a1,free_memory_pointer          ; free memory after the names and program
	bsr.w	read_file                       ; read names and program
	bsr.w	close_file                      ; close the .GFA file
	movea.l	free_memory_pointer,a0          ; INLINE and DATA areas start empty after the program
	move.l	a0,inline_area_start            ; INLINE area starts empty
	move.l	a0,data_text_start              ; DATA text starts empty
	move.l	a0,data_area_end                ; end of the DATA text
	move.l	a0,data_area_end_copy           ; a copy of the DATA end
	movea.l	program_start,a0                ; a0 = first program line (read pointer)
	movea.l	a0,a1                           ; a1 = write pointer: lines are compacted in place
.prepass_next_line:
	lsr.w	2(a0)                           ; command word: 4 x token becomes 2 x token
	movem.w	(a0),d0-d1                      ; d0 = line length, d1 = 2 x command
	cmpi.w	#$5a,d1                         ; 45: last line
	beq.w	.end_of_program                 ; last line: finish the pre-pass
	cmpi.w	#$ea,d1                         ; 117: DATA
	beq.w	.copy_data_line                 ; copy the DATA text
	cmpi.w	#$e4,d1                         ; 114: REM
	beq.w	.replace_with_empty_line        ; REM: empty line
	cmpi.w	#$e6,d1                         ; 115: ' (comment)
	beq.w	.replace_with_empty_line        ; ': empty line
	cmpi.w	#$1fc,d1                        ; 254: . (comment)
	beq.w	.replace_with_empty_line        ; . comment: empty line
	cmpi.w	#$342,d1                        ; 417: INLINE
	beq.w	.move_inline_data               ; move the INLINE data out
	cmpi.w	#$7e,d1                         ; 63: label line
	bne.s	.not_label                      ; not a label line
	moveq	#0,d3                           ; d3 = label index
	lea	4(a0),a2                        ; a2 = the label token
	cmpi.b	#$f0,(a2)+                      ; word index token ($f0-$ff)?
	bcs.s	.label_index_low                ; byte index
	move.b	(a2)+,d3                        ; word index: high byte
	asl.w	#8,d3                           ; into the high byte
.label_index_low:
	move.b	(a2)+,d3                        ; index low byte
	asl.w	#2,d3                           ; x4: long per label
	movea.l	label_data_offsets,a2           ; a2 = label DATA offset table
	move.l	data_area_end,d2                ; d2 = offset in the DATA text
	sub.l	data_text_start,d2              ; relative to the DATA text start
	move.l	d2,0(a2,d3.w)                   ; label's position in the DATA text, for RESTORE
.not_label:
	cmpi.w	#$2fa,d1                        ; 381-386: DEFINT ... DEFSTR
	bcs.s	.not_def_type                   ; below DEFINT
	cmpi.w	#$304,d1                        ; up to DEFSTR
	bls.w	.replace_with_empty_line        ; DEFxxx: empty line
.not_def_type:
	cmpi.w	#$62,d1                         ; 49-52: DO WHILE ... LOOP UNTIL
	bcs.s	.not_do_condition               ; below DO WHILE
	cmpi.w	#$68,d1                         ; DO WHILE / DO UNTIL / LOOP WHILE / LOOP UNTIL
	bls.s	.drop_jump_long                 ; keep them without the jump long
.not_do_condition:
	cmpi.w	#$2,d1                          ; 1 LOOP, 3 UNTIL, 4 WHILE, 5 WEND, 8 IF, 12 SELECT, 44 SELECT, 14 ELSE,
                                                ;   15 DEFAULT, 16 ELSE IF, 55 EXIT IF, 56 CASE
	beq.s	.drop_jump_long                 ; 1: LOOP
	cmpi.w	#$6,d1
	beq.s	.drop_jump_long                 ; 3: UNTIL
	cmpi.w	#$8,d1
	beq.s	.drop_jump_long                 ; 4: WHILE
	cmpi.w	#$a,d1
	beq.s	.drop_jump_long                 ; 5: WEND
	cmpi.w	#$10,d1
	beq.s	.drop_jump_long                 ; 8: IF
	cmpi.w	#$18,d1
	beq.s	.drop_jump_long                 ; 12: SELECT
	cmpi.w	#$58,d1
	beq.s	.drop_jump_long                 ; 44: SELECT (string)
	cmpi.w	#$1c,d1
	beq.s	.drop_jump_long                 ; 14: ELSE
	cmpi.w	#$1e,d1
	beq.s	.drop_jump_long                 ; 15: DEFAULT
	cmpi.w	#$20,d1
	beq.s	.drop_jump_long                 ; 16: ELSE IF
	cmpi.w	#$6e,d1
	beq.s	.drop_jump_long                 ; 55: EXIT IF
	cmpi.w	#$70,d1
	beq.s	.drop_jump_long                 ; 56: CASE
	cmpi.w	#$3e,d1                         ; 31-43: NEXT and EXIT IF
	bcs.s	.copy_line                      ; below NEXT: keep the line
	cmpi.w	#$56,d1                         ; up to 43 (EXIT IF in a FOR)
	bhi.s	.copy_line                      ; above EXIT IF: keep the line
.drop_jump_long:
	subq.w	#4,d0                           ; drop the long the interpreter keeps a jump address in
	move.l	(a0)+,(a0)                      ; move length and command over the jump long
	subq.w	#4,(a0)                         ; line length - 4
.copy_line:
	lsr.w	#2,d0                           ; copy the line in 2/4/8/16-byte steps
	bcc.s	.copy_4_byte_step               ; odd word: copy 2 bytes
	move.w	(a0)+,(a1)+                     ; copy 2 bytes
.copy_4_byte_step:
	lsr.w	#1,d0                           ; bit: 4 bytes
	bcc.s	.copy_8_byte_step               ; copy 4 bytes
	move.l	(a0)+,(a1)+                     ; copy 4 bytes
.copy_8_byte_step:
	lsr.w	#1,d0                           ; bit: 8 bytes
	bcc.s	.copy_16_byte_step              ; copy 8 bytes
	move.l	(a0)+,(a1)+                     ; copy 8 bytes
	move.l	(a0)+,(a1)+
.copy_16_byte_step:
	lsr.w	#1,d0                           ; bit: 16 bytes; d0 = 32-byte blocks
	bcc.s	.copy_loop_end                  ; no odd 16 bytes: d0 = 32-byte blocks
	bra.s	.copy_second_16_bytes           ; copy 16 bytes first, then 32 per loop
.copy_16_bytes:
	move.l	(a0)+,(a1)+                     ; 32-byte loop: first 16 bytes
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.copy_second_16_bytes:
	move.l	(a0)+,(a1)+                     ; second 16 bytes
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.copy_loop_end:
	dbra	d0,.copy_16_bytes               ; next 32 bytes
	bra.w	.prepass_next_line              ; next line
.replace_with_empty_line:
	move.w	#$4,(a1)+                       ; an empty 4-byte line with the command
	move.w	d1,(a1)+                        ; the command
	adda.w	d0,a0                           ; skip the source line
	bra.w	.prepass_next_line              ; next line
.end_of_program:
	move.l	(a0)+,(a1)+                     ; last line: copy it, then close the gap before the data area
	move.l	a0,d0                           ; d0 = bytes the pre-pass removed
	sub.l	a1,d0                           ; d0 = gap between read and write pointers
	movea.l	inline_area_start,a2            ; a2 = old INLINE area start (copy source)
	movea.l	free_memory_pointer,a0          ; a0 is reloaded below
	sub.l	d0,free_memory_pointer          ; move the data area pointers down by d0
	sub.l	d0,inline_area_start            ; lower the INLINE area start
	sub.l	d0,data_text_start              ; lower the DATA text start
	sub.l	d0,data_area_end                ; lower the DATA end
	move.l	data_area_end,d1                ; d1 = new DATA end
	move.l	d1,data_area_end_copy           ; keep a copy
	addi.l	#$1000,d1                       ; code buffer 4K after the data, even
	bclr	#$0,d1                          ; even
	movea.l	d1,a1                           ; a1 = start of the code buffer
	move.l	a1,string_pool_limit            ; strings may grow up to the code buffer
	move.l	a1,code_buffer_start            ; code is generated from here
	movea.l	a2,a0                           ; copy from the old INLINE area start
	move.l	data_area_end,d0                ; d0 = DATA end
	movea.l	inline_area_start,a1            ; to the new start; d0 = length
	sub.l	a1,d0                           ; - INLINE start: bytes to move
	addq.l	#1,d0                           ; round up to even
	bclr	#$0,d0                          ; even length
	jmp	copy_memory_forwards            ; copy the data area down; returns to the caller
.copy_data_line:
	lea	4(a0),a2                        ; DATA text after the 4-byte line header
	movea.l	data_area_end,a3                ; a3 = DATA text output
.data_item:
	cmpi.b	#$22,(a2)                       ; '"': quoted item
	beq.s	.quoted_data_item               ; quoted item
.copy_data_char:
	move.b	(a2)+,d2                        ; next DATA character
	cmpi.b	#$d,d2                          ; CR: end of the line
	beq.s	.data_line_end                  ; CR: the line ends
	cmpi.b	#$2c,d2                         ; ',' ends an item
	bne.s	.store_data_char                ; not a comma: store it
	moveq	#0,d2                           ; zero byte between items
.store_data_char:
	move.b	d2,(a3)+                        ; store the character or the item's zero
	bne.s	.copy_data_char                 ; copy until the item's zero byte
	bra.s	.data_item                      ; next item
.data_line_end:
	clr.b	(a3)+                           ; end the last item
.data_done:
	move.l	a3,data_area_end                ; new end of the DATA text
	bra.w	.replace_with_empty_line        ; the DATA line becomes an empty line
.quoted_data_item:
	addq.l	#1,a2                           ; skip the opening quote
.copy_quoted_char:
	move.b	(a2)+,d2                        ; next character inside the quotes
	cmpi.b	#$d,d2                          ; CR: the line ends
	beq.s	.quoted_line_end                ; CR: the line ends
	cmpi.b	#$2c,d2                         ; a comma?
	bne.s	.store_quoted_char              ; inside the quotes: store it
	cmpi.b	#$22,-$1(a3)                    ; a comma after a closing quote ends the item
	bne.s	.store_quoted_char              ; no closing quote before it: keep the comma
	moveq	#0,d2                           ; zero ends the item
	subq.l	#1,a3                           ; drop the closing quote
	bra.s	.store_data_char                ; store the zero
.store_quoted_char:
	move.b	d2,(a3)+                        ; store the character
	bra.s	.copy_quoted_char               ; next character
.quoted_line_end:
	cmpi.b	#$22,-$1(a3)                    ; closing quote before the CR?
	bne.s	.terminate_quoted               ; no closing quote
	subq.l	#1,a3                           ; drop it
.terminate_quoted:
	clr.b	(a3)+                           ; end the item
	bra.s	.data_done                      ; store the DATA end
.move_inline_data:
	lea	4(a0),a2                        ; INLINE: skip the variable token
	cmpi.b	#$f0,(a2)+                      ; word index token ($f0-$ff)?
	bcs.s	.skip_inline_fields             ; byte token: one index byte
	addq.l	#1,a2                           ; word token: skip the second index byte
.skip_inline_fields:
	addq.l	#4,a2                           ; skip four bytes after the variable
	move.l	a2,d1                           ; round down to even
	andi.b	#$fe,d1                         ; even address
	movea.l	d1,a2                           ; a2 = the length long
	move.l	(a2)+,d1                        ; d1 = length of the data, even
	addq.l	#1,d1                           ; round the length up
	bclr	#$0,d1                          ; to even
	addq.l	#2,a2                           ; a2 = start of the INLINE data
	move.l	data_text_start,d6              ; d6 = current end of the INLINE area
	move.l	d6,d2                           ; d2 = INLINE end
	sub.l	inline_area_start,d2            ; - INLINE start: offset of this block
	move.l	d2,-$6(a2)                      ; offset of this block in the INLINE area into the line
	move.l	data_area_end,d4                ; d4 = old end of the DATA text
	add.l	d1,data_text_start              ; INLINE area and DATA text move up by d1
	add.l	d1,data_area_end                ; DATA end moves up by d1
	move.l	a2,d7                           ; d7 = address of the data in the line
	move.l	data_area_end,d5                ; d5 = new DATA end
	addq.l	#3,d4                           ; round both ends up for the word copy
	addq.l	#3,d5                           ; round up
	andi.w	#$fffe,d4                       ; d4 even: old DATA end, rounded up
	andi.w	#$fffe,d5                       ; d5 even: new DATA end, rounded up
	movea.l	d4,a2                           ; a2 = old end (source)
	movea.l	d5,a3                           ; a3 = new end (destination)
.shift_data_text_up:
	move.w	-(a2),-(a3)                     ; make room: move the DATA text up
	cmpa.l	d6,a2                           ; down to the old INLINE end
	bhi.s	.shift_data_text_up             ; move another word
	movea.l	d6,a3                           ; a3 = where the INLINE block goes
	movea.l	d7,a2                           ; a2 = the INLINE data in the line
	lsr.w	#1,d1                           ; word count
	bra.s	.copy_inline_loop
.copy_inline_word:
	move.w	(a2)+,(a3)+                     ; copy a word
.copy_inline_loop:
	dbra	d1,.copy_inline_word            ; copy the INLINE data into the gap
	move.w	(a0),d0                         ; d0 = old line length
	sub.l	a0,d7                           ; d7 = bytes in front of the data
	move.w	d7,(a1)+                        ; new line length (data removed)
	lea	2(a0),a3                        ; copy the line up to the data
	lsr.w	#1,d7                           ; words in front of the data
	subq.w	#2,d7                           ; minus the length word, minus 1 for dbra
.copy_inline_line:
	move.w	(a3)+,(a1)+                     ; copy the rest of the line header
	dbra	d7,.copy_inline_line            ; words of the line before the data
	adda.w	d0,a0                           ; skip the source line with its data
	bra.w	.prepass_next_line              ; next source line
no_disk_prompt_flag:
	dc.w	$ffff                           ; $ff: no prompt; G3WAIT=ON clears it

;------------------------------------------------------------------------------
; Exit with a message: d0 = exit code (exit_with_message_code only), a0 = message. Prints and calls Pterm.
;------------------------------------------------------------------------------
exit_with_message_code:
	move.w	d0,-(sp)                        ; exit code for Pterm

exit_with_message:
	bsr.s	print_string                    ; print the message
	move.w	#$4c,-(sp)                      ; Pterm
	trap	#1                              ; Pterm

;------------------------------------------------------------------------------
; Waits for a key with Cconin.
;------------------------------------------------------------------------------
wait_for_key:
	move.w	#$1,-(sp)                       ; Cconin
	trap	#1                              ; Cconin
	addq.l	#2,sp
	rts

;------------------------------------------------------------------------------
; Prints the zero-ended string at a0 with Cconws.
;------------------------------------------------------------------------------
print_string:
	pea	(a0)                            ; Cconws(a0)
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws
	addq.l	#6,sp
	rts

;------------------------------------------------------------------------------
; Opens the file named at a0 for reading (Fopen, mode 0). When the G3WAIT shell setting is ON it first asks for
; the disk ("Disk: name einlegen <RETURN>") and waits for a key. Stores the handle in file_handle; on an error
; prints "Kann Datei name nicht oeffnen" and terminates with the error code.
;------------------------------------------------------------------------------
open_file:
	moveq	#61,d0                          ; 61 = Fopen
	bra.s	open_or_create_file             ; open with Fopen

;------------------------------------------------------------------------------
; Creates the file named at a0 (Fcreate, attribute 0); otherwise as open_file.
;------------------------------------------------------------------------------
create_file:
	moveq	#60,d0                          ; 60 = Fcreate

open_or_create_file:
	clr.w	-(sp)                           ; mode/attribute 0, name, GEMDOS function
	pea	(a0)                            ; name
	move.w	d0,-(sp)                        ; Fopen / Fcreate
	move.b	no_disk_prompt_flag(pc),d0      ; prompt for the disk first?
	bne.s	.no_disk_prompt                 ; no prompt wanted
	lea	insert_disk_message(pc),a0      ; "Disk: "
	bsr.s	print_string
	movea.l	2(sp),a0                        ; a0 = the file name
	bsr.s	print_string                    ; the file name
	lea	insert_disk_return_message(pc),a0 ; " einlegen <RETURN>"
	bsr.s	print_string
	bsr.s	wait_for_key                    ; wait for a key
	lea	newline_text(pc),a0             ; new line
	bsr.s	print_string
.no_disk_prompt:
	trap	#1                              ; GEMDOS, Fopen / Fcreate
	movea.l	2(sp),a0                        ; a0 = the file name again
	addq.l	#8,sp                           ; drop the arguments
	tst.l	d0                              ; handle or error code
	bmi.s	.open_failed                    ; negative: error
	move.w	d0,file_handle                  ; keep the handle
	rts
.open_failed:
	move.w	d0,-(sp)                        ; error code for Pterm
	pea	(a0)                            ; keep the name
	lea	cannot_open_message(pc),a0      ; "Kann Datei "
	bsr.s	print_string                    ; print it
	movea.l	(sp)+,a0                        ; a0 = the file name
	bsr.s	print_string                    ; the file name
	lea	cannot_open_message_end(pc),a0  ; " nicht oeffnen" (with the umlaut)
	bra.s	exit_with_message               ; print it and Pterm(error code)
cannot_open_message:
	dc.b	'Cannot open ',0
cannot_open_message_end:
	dc.b	$00
insert_disk_message:
	dc.b	'Insert Disk: ',0
insert_disk_return_message:
	dc.b	' <RETURN>',0
newline_text:
	dc.w	$0d0a,$0000

;------------------------------------------------------------------------------
; Reads d0.l bytes to a0 from file_handle (nothing when d0 = 0). Terminates with "Lesefehler" on an error.
;------------------------------------------------------------------------------
read_file:
	pea	(a0)                            ; Fread(handle, d0, a0)
	move.l	d0,-(sp)
	beq.s	.read_checked                   ; nothing to read
	move.w	file_handle,-(sp)               ; the handle
	move.w	#$3f,-(sp)                      ; Fread
	trap	#1                              ; Fread
	addq.l	#4,sp                           ; drop handle and function
.read_checked:
	addq.l	#8,sp                           ; drop length and buffer
	tst.l	d0                              ; negative: error
	bmi.s	.read_failed                    ; negative: read error
	rts
.read_failed:
	lea	msg_read_error,a0               ; "Lesefehler"
	bra.w	exit_with_message_code          ; Pterm(d0)

;------------------------------------------------------------------------------
; Writes d0.l bytes from a0 to file_handle (nothing when d0 = 0). A short write terminates with "Diskette voll"
; (exit code -1), an error with "Schreibfehler".
;------------------------------------------------------------------------------
write_file:
	pea	(a0)                            ; Fwrite(handle, d0, a0)
	move.l	d0,-(sp)
	beq.s	.write_ok                       ; nothing to write
	move.w	file_handle,-(sp)
	move.w	#$40,-(sp)                      ; Fwrite
	trap	#1                              ; Fwrite
	addq.l	#4,sp                           ; drop handle and function
	cmp.l	(sp),d0                         ; all bytes written?
	bne.s	.write_short                    ; short write: disk full or error
.write_ok:
	addq.l	#8,sp                           ; drop length and buffer
	rts
.write_short:
	tst.l	d0
	bmi.s	.write_failed                   ; negative: write error
	moveq	#-1,d0                          ; exit code -1
	lea	msg_disk_full,a0                ; "Diskette voll"
	bra.w	exit_with_message_code          ; Pterm(-1)
.write_failed:
	lea	msg_write_error,a0              ; "Schreibfehler"
	bra.w	exit_with_message_code          ; Pterm(error code)

; Unreferenced code kept as data: clr.w -(sp) / move.w file_handle,-(sp) / move.l d0,-(sp) / move.w #$42,-(sp) /
; trap #1 / adda.w #10,sp / rts, an Fseek to offset d0 from the start.
	dc.b	'Bg?9'                          ; unreferenced: an Fseek routine (see header)
	dc.l	file_handle
	dc.w	$2f00,$3f3c,$0042,$4e41,$defc,$000a,$4e75

;------------------------------------------------------------------------------
; Closes file_handle (Fclose).
;------------------------------------------------------------------------------
close_file:
	move.w	file_handle,-(sp)
	move.w	#$3e,-(sp)                      ; Fclose(handle)
	trap	#1                              ; Fclose
	addq.l	#4,sp
	rts

;------------------------------------------------------------------------------
; Clears the longs from (a0) to 4(a0): a0 points at a pair of section addresses (start, end).
;------------------------------------------------------------------------------
clear_long_range:
	movea.l	4(a0),a1                        ; a1 = end address
	movea.l	(a0),a0                         ; a0 = start address
	bra.s	.clear_test
.clear_long:
	clr.l	(a0)+                           ; clear a long
.clear_test:
	cmpa.l	a0,a1                           ; until the end address
	bne.s	.clear_long
	rts

;------------------------------------------------------------------------------
; Checks the program's structure before compiling, using the stack for open structures (6-byte entries: word
; 2 x command, long line address; a word with bit 7 set marks an EXIT IF waiting for its loop). Every
; loop/IF/SELECT end must match its opening line, NEXT must match the FOR's type and variable, ELSE/ELSE IF/CASE
; must be inside IF/SELECT, RETURN/ENDFUNC inside a FUNCTION, LOCAL inside a routine, labels and routines may
; only be defined once. Fills label_line_table, procedure_line_table and the function line tables, marks
; ABSOLUTE, LOCAL and parameter variables in identifier_flag_tables, and rewrites EXIT IF to command 43 (in a
; FOR) or 55 (in a DO/REPEAT/WHILE loop). A second pass checks that GOTO does not jump into or out of a
; procedure or function and that RESUME label targets lie outside loops.
; Exit: d7 = 0 and N clear when the structure is right; d7 = -1 (N set) and a0 = the offending line otherwise.
;------------------------------------------------------------------------------
check_program_structure:
	lea	label_line_table,a0
	bsr.s	clear_long_range                ; clear the label line table
	lea	procedure_line_table,a0
	bsr.s	clear_long_range                ; clear the procedure line table
	lea	function_line_table,a0
	bsr.s	clear_long_range                ; clear the function line table
	lea	string_function_line_table,a0
	bsr.s	clear_long_range                ; clear the string function line table
	movea.l	program_start,a0                ; first program line
	clr.l	-(sp)                           ; stack bottom marker: line address 0
	clr.w	-(sp)                           ; stack bottom marker (6 bytes)
	lea	(sp),a5                         ; a5 = stack bottom
	moveq	#0,d0                           ; d0 high word stays clear

structure_check_loop:
	move.w	2(a0),d0                        ; d0 = 2 x command
	cmpi.w	#$80,d0                         ; commands 64 and up
	bcs.s	structure_check_dispatch        ; commands 0-63 go through the table
	cmpi.w	#$1fa,d0                        ; 253: ABSOLUTE
	beq.s	mark_absolute_variable          ; ABSOLUTE: mark the variable
	cmpi.w	#$d8,d0                         ; 106-108: RESUME with a label
	bhi.s	structure_check_next_line       ; above 108: nothing to check
	cmpi.w	#$d4,d0                         ; $d4-$d8: RESUME label
	bcc.w	check_inside_procedure          ; RESUME label: must be inside a procedure

structure_check_next_line:
	adda.w	(a0),a0                         ; next line
	bra.s	structure_check_loop            ; check the next line
	bra.w	check_structure_stack_empty     ; never reached

mark_absolute_variable:
	lea	4(a0),a2                        ; a2 = identifier token after the line header
	move.b	(a2)+,d1                        ; d1 = identifier token
	moveq	#0,d2                           ; d2 = index
	bclr	#$4,d1                          ; bit 4: word index follows
	beq.s	.absolute_index_low             ; byte index
	move.b	(a2)+,d2                        ; index high byte
	asl.w	#8,d2                           ; into the high byte
.absolute_index_low:
	move.b	(a2)+,d2                        ; index (low byte)
	btst	#$2,d1                          ; bit 2: alignment byte
	beq.s	.absolute_type                  ; no alignment byte
	addq.l	#1,a2                           ; skip it
.absolute_type:
	andi.w	#$f,d1                          ; identifier type 0-15
	asl.w	#2,d1                           ; x4: offset of the table pointer
	lea	float_variable_table,a3         ; a3 = flag table pointers
	adda.w	d1,a3                           ; + type x 4
	movea.l	(a3),a3                         ; a3 = flag table for this type
	asl.w	#2,d2                           ; x4: long per identifier
	st	0(a3,d2.w)                      ; mark the variable
	bra.s	structure_check_next_line       ; next line

structure_check_dispatch:
	move.w	structure_check_table(pc,d0.w),d1 ; offset for 2 x command
	jmp	structure_check_table(pc,d1.w)  ; jump to the check

; Word offsets from the table, indexed by 2 x command for commands 0-63 (DO ... LABEL).
structure_check_table:
	dc.w	.push_structure-structure_check_table
	dc.w	.check_loop-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.check_until-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.check_wend-structure_check_table
	dc.w	check_procedure_header-structure_check_table
	dc.w	check_endproc-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.check_endif-structure_check_table
	dc.w	check_function_header-structure_check_table
	dc.w	check_endfunc-structure_check_table
	dc.w	.push_select-structure_check_table
	dc.w	check_endselect-structure_check_table
	dc.w	.check_else-structure_check_table
	dc.w	check_case_in_select-structure_check_table
	dc.w	.check_else_if-structure_check_table
	dc.w	check_return_in_function-structure_check_table
	dc.w	check_return_in_function-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.check_next_float-structure_check_table
	dc.w	.check_next_float-structure_check_table
	dc.w	.check_next_float-structure_check_table
	dc.w	.check_next_int-structure_check_table
	dc.w	.check_next_int-structure_check_table
	dc.w	.check_next_int-structure_check_table
	dc.w	.check_next_word-structure_check_table
	dc.w	.check_next_word-structure_check_table
	dc.w	.check_next_word-structure_check_table
	dc.w	.check_next_byte-structure_check_table
	dc.w	.check_next_byte-structure_check_table
	dc.w	.check_next_byte-structure_check_table
	dc.w	.check_exit_if-structure_check_table
	dc.w	.push_select-structure_check_table
	dc.w	check_structure_stack_empty-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.push_structure-structure_check_table
	dc.w	.check_loop-structure_check_table
	dc.w	.check_loop-structure_check_table
	dc.w	check_local-structure_check_table
	dc.w	check_procedure_header-structure_check_table
	dc.w	.check_exit_if-structure_check_table
	dc.w	check_case_in_select-structure_check_table
	dc.w	record_deffn_line-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	structure_check_next_line-structure_check_table
	dc.w	record_label_line-structure_check_table
.push_select:
	moveq	#24,d0                          ; 44 SELECT pushed as 12 SELECT
.push_structure:
	pea	(a0)                            ; push the opening: line address, 2 x command
	move.w	d0,-(sp)                        ; and 2 x command
	bra.w	structure_check_next_line
.check_until:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$84,d0                         ; $84: an EXIT IF entry of a REPEAT
	bne.s	.until_entry                    ; not an exit entry
	addq.l	#4,sp                           ; drop its line address
	bra.s	.check_until                    ; and look at the next entry
.until_entry:
	cmpi.w	#$4,d0                          ; 4: REPEAT
	beq.s	.pop_and_next                   ; REPEAT matches
	bra.w	structure_error                 ; UNTIL without REPEAT
.pop_and_next:
	addq.l	#4,sp                           ; drop the line address
	bra.w	structure_check_next_line
.check_loop:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$e2,d0                         ; $e2/$e4/$80: EXIT IF entries of DO WHILE / DO UNTIL / DO
	beq.s	.skip_do_exit_entry             ; exit entry: drop it
	cmpi.w	#$e4,d0                         ; $e4: EXIT IF entry of a DO UNTIL
	beq.s	.skip_do_exit_entry
	cmpi.w	#$80,d0                         ; $80: EXIT IF entry of a DO
	bne.s	.loop_entry
.skip_do_exit_entry:
	addq.l	#4,sp                           ; drop its line address
	bra.s	.check_loop
.loop_entry:
	tst.l	(sp)                            ; line address 0: the bottom marker
	beq.s	.loop_mismatch                  ; LOOP with no open structure
	cmpi.w	#$62,d0                         ; $62/$64: DO WHILE / DO UNTIL
	beq.s	.drop_and_next                  ; LOOP of a DO WHILE
	cmpi.w	#$64,d0                         ; $64: DO UNTIL
	beq.s	.drop_and_next                  ; LOOP of a DO UNTIL
	tst.w	d0                              ; 0: DO
	beq.s	.pop_and_next                   ; LOOP of a DO
.loop_mismatch:
	bra.w	structure_error
.check_wend:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$88,d0                         ; $88: an EXIT IF entry of a WHILE
	bne.s	.wend_entry                     ; not an exit entry
	addq.l	#4,sp                           ; drop the exit's line address
	bra.s	.check_wend
.wend_entry:
	cmpi.w	#$8,d0                          ; 8: WHILE
	bne.w	structure_error                 ; WEND without WHILE
.drop_and_next:
	addq.l	#4,sp
	bra.w	structure_check_next_line
.check_next_int:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$ac,d0                         ; $ac/$ae/$b0: EXIT IF entries of FOR %
	beq.s	.skip_for_int_exit_entry        ; exit entry: drop it
	cmpi.w	#$ae,d0
	beq.s	.skip_for_int_exit_entry
	cmpi.w	#$b0,d0
	bne.s	.next_int_entry
.skip_for_int_exit_entry:
	addq.l	#4,sp                           ; drop its line address
	bra.s	.check_next_int
.next_int_entry:
	cmpi.w	#$2c,d0                         ; $2c-$30: FOR % (TO / DOWNTO / STEP)
	beq.s	.next_matches_for
	cmpi.w	#$2e,d0
	beq.s	.next_matches_for
	cmpi.w	#$30,d0
	beq.s	.next_matches_for
	bra.s	.next_mismatch                  ; NEXT % without its FOR
.check_next_float:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$a6,d0                         ; $a6/$a8/$aa: EXIT IF entries of FOR (float)
	beq.s	.skip_for_float_exit_entry      ; exit entry: drop it
	cmpi.w	#$a8,d0
	beq.s	.skip_for_float_exit_entry
	cmpi.w	#$aa,d0
	bne.s	.next_float_entry
.skip_for_float_exit_entry:
	addq.l	#4,sp                           ; drop its line address
	bra.s	.check_next_float
.next_float_entry:
	cmpi.w	#$26,d0                         ; $26-$2a: FOR (float)
	beq.s	.next_matches_for
	cmpi.w	#$28,d0
	beq.s	.next_matches_for
	cmpi.w	#$2a,d0
	bne.s	.next_mismatch                  ; NEXT without its FOR
.next_matches_for:
	addi.w	#$18,d0                         ; NEXT command = FOR command + $18
	move.w	d0,2(a0)                        ; rewrite the NEXT to the FOR's form
	movea.l	(sp),a1                         ; a1 = the FOR line
	move.w	4(a0),d1                        ; same variable as the FOR?
	cmp.w	4(a1),d1                        ; same variable as the FOR?
	beq.w	.pop_and_next                   ; yes: drop the FOR entry
.next_mismatch:
	bra.w	structure_error                 ; NEXT does not match
.check_next_word:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$b2,d0                         ; $b2-$b6: EXIT IF entries of FOR &
	beq.s	.skip_for_word_exit_entry       ; exit entry: drop it
	cmpi.w	#$b4,d0
	beq.s	.skip_for_word_exit_entry
	cmpi.w	#$b6,d0
	bne.s	.next_word_entry
.skip_for_word_exit_entry:
	addq.l	#4,sp                           ; drop its line address
	bra.s	.check_next_word
.next_word_entry:
	cmpi.w	#$32,d0                         ; $32-$36: FOR & (TO / DOWNTO / STEP)
	beq.s	.test_for_word_match
	cmpi.w	#$34,d0
	beq.s	.test_for_word_match
	cmpi.w	#$36,d0
.test_for_word_match:
	beq.s	.next_matches_for               ; FOR & found
	bra.s	.next_mismatch                  ; NEXT & without its FOR
.check_next_byte:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$b8,d0                         ; $b8-$bc: EXIT IF entries of FOR |
	beq.s	.skip_for_byte_exit_entry       ; exit entry: drop it
	cmpi.w	#$ba,d0
	beq.s	.skip_for_byte_exit_entry
	cmpi.w	#$bc,d0
	bne.s	.next_byte_entry
.skip_for_byte_exit_entry:
	addq.l	#4,sp                           ; drop its line address
	bra.s	.check_next_byte
.next_byte_entry:
	cmpi.w	#$38,d0                         ; $38-$3c: FOR | (TO / DOWNTO / STEP)
	beq.s	.test_for_byte_match
	cmpi.w	#$3a,d0
	beq.s	.test_for_byte_match
	cmpi.w	#$3c,d0
.test_for_byte_match:
	beq.s	.next_matches_for               ; FOR | found
	bra.s	.next_mismatch                  ; NEXT | without its FOR
.check_endif:
	move.w	(sp)+,d0                        ; pop 2 x command
	cmpi.w	#$10,d0                         ; ENDIF: top must be IF ($10) or ELSE ($1c)
	beq.s	.pop_if_entry
	cmpi.w	#$1c,d0                         ; $1c: ELSE
	bne.w	structure_error                 ; ENDIF without IF
.pop_if_entry:
	addq.l	#4,sp                           ; drop the line address
	bra.w	structure_check_next_line
.check_else:
	cmpi.w	#$10,(sp)+                      ; ELSE: top must be IF
	bne.w	structure_error                 ; ELSE without IF
	move.l	a0,(sp)                         ; the ELSE line replaces the IF entry
	move.w	#$1c,-(sp)                      ; ELSE entry $1c
	bra.w	structure_check_next_line
.check_else_if:
	cmpi.w	#$10,(sp)+                      ; ELSE IF: top must be IF, stays IF
	bne.w	structure_error                 ; ELSE IF without IF
	move.l	a0,(sp)                         ; the ELSE IF line replaces the IF entry
	move.w	#$10,-(sp)                      ; still an IF entry
	bra.w	structure_check_next_line
.check_exit_if:
	movea.l	sp,a1                           ; a1 walks the stack from the top
.find_exit_loop:
	move.w	(a1),d1                         ; d1 = this entry's 2 x command
	tst.l	2(a1)                           ; the bottom marker: EXIT IF outside a loop
	beq.w	structure_error                 ; EXIT IF outside a loop
	cmpi.w	#$10,d1                         ; IF, ELSE, SELECT entries are passed over
	beq.s	.skip_if_entry
	cmpi.w	#$1c,d1
	beq.s	.skip_if_entry
	cmpi.w	#$18,d1                         ; $18: SELECT
	bne.s	.loop_found                     ; a loop entry
.skip_if_entry:
	addq.l	#6,a1                           ; next entry
	bra.s	.find_exit_loop
.loop_found:
	cmp.l	a1,d7                           ; d7 is not loaded in this routine: unclear what it holds
	beq.s	.loop_on_top                    ; the loop entry is on top
	subq.l	#6,sp                           ; open a 6-byte slot above the loop entry
	movea.l	sp,a2                           ; a2 = new top
.open_slot:
	move.w	6(a2),(a2)+                     ; move the entries above it down
	cmpa.l	a2,a1                           ; up to the loop entry
	bne.s	.open_slot
	andi.w	#$7f,d1                         ; DO, REPEAT, WHILE, DO WHILE, DO UNTIL
	beq.s	.exit_from_do_loop              ; 0: DO
	cmpi.w	#$4,d1                          ; 4: REPEAT
	beq.s	.exit_from_do_loop
	cmpi.w	#$8,d1                          ; 8: WHILE
	beq.s	.exit_from_do_loop
	cmpi.w	#$62,d1                         ; $62: DO WHILE
	beq.s	.exit_from_do_loop
	cmpi.w	#$64,d1                         ; $64: DO UNTIL
	beq.s	.exit_from_do_loop
	cmpi.w	#$26,d1                         ; FOR $26-$3c
	bcs.s	structure_error                 ; not a FOR: EXIT IF has no loop
	cmpi.w	#$3c,d1
	bhi.s	structure_error                 ; not a FOR: EXIT IF has no loop
	move.w	#$56,2(a0)                      ; rewrite EXIT IF as command 43 (FOR)
.insert_exit_entry:
	move.l	a0,-(a1)                        ; EXIT IF entry above its loop
	ori.w	#$80,d1                         ; bit 7: EXIT IF entry of that loop
	move.w	d1,-(a1)                        ; its 2 x command
	bra.w	structure_check_next_line       ; next line
.exit_from_do_loop:
	move.w	#$6e,2(a0)                      ; rewrite EXIT IF as command 55 (DO loops)
	bra.s	.insert_exit_entry              ; insert the entry
.loop_on_top:
	andi.w	#$7f,d1                         ; loop type without the EXIT IF bit
	beq.s	.exit_on_top_do_loop
	cmpi.w	#$4,d1                          ; 4: REPEAT
	beq.s	.exit_on_top_do_loop
	cmpi.w	#$8,d1                          ; 8: WHILE
	beq.s	.exit_on_top_do_loop
	cmpi.w	#$62,d1                         ; $62: DO WHILE
	beq.s	.exit_on_top_do_loop
	cmpi.w	#$64,d1                         ; $64: DO UNTIL
	beq.s	.exit_on_top_do_loop
	cmpi.w	#$26,d1                         ; FOR $26-$3c
	bcs.s	structure_error                 ; not a loop: error
	cmpi.w	#$3c,d1
	bhi.s	structure_error                 ; not a loop: error
	move.w	#$56,2(a0)                      ; rewrite EXIT IF as command 43 (FOR)
.push_exit_entry:
	pea	(a0)                            ; push the EXIT IF entry
	ori.w	#$80,d1                         ; bit 7: EXIT IF entry of that loop
	move.w	d1,-(sp)                        ; its 2 x command
	bra.w	structure_check_next_line
.exit_on_top_do_loop:
	move.w	#$6e,2(a0)                      ; rewrite EXIT IF as command 55 (DO loops)
	bra.s	.push_exit_entry                ; push the entry

structure_error:
	bra.s	structure_error_exit

check_structure_stack_empty:
	cmpa.l	a5,sp                           ; 45: last line, the stack must be empty
	beq.w	check_jump_targets              ; empty: start the second pass
	move.w	(sp)+,d0                        ; drop the top entry
	move.l	(sp)+,d1                        ; and its line address

structure_error_exit:
	movea.l	(sp)+,a0                        ; a0 = the line address on the stack
	lea	6(a5),sp                        ; drop everything
	moveq	#-1,d7                          ; error
	rts                                     ; N set: structure error

check_case_in_select:
	cmpi.w	#$18,(sp)+                      ; CASE / DEFAULT: top must be SELECT
	bne.s	structure_error
	move.l	a0,(sp)                         ; the CASE line replaces the SELECT entry
	move.w	#$18,-(sp)                      ; still a SELECT entry
	bra.w	structure_check_next_line

check_endselect:
	cmpi.w	#$18,(sp)+                      ; ENDSELECT
	bne.s	structure_error
	addq.l	#4,sp                           ; drop the line address
	bra.w	structure_check_next_line

check_procedure_header:
	moveq	#12,d0                          ; PROCEDURE: only outside every structure
	cmpa.l	sp,a5                           ; stack empty?
	bne.s	structure_error
	pea	(a0)                            ; push the PROCEDURE entry
	move.w	d0,-(sp)                        ; and 2 x command
	move.w	4(a0),d1                        ; procedure index
	asl.w	#2,d1                           ; x4: long per procedure
	movea.l	procedure_line_table,a1         ; a1 = procedure line table
	tst.l	0(a1,d1.w)                      ; already recorded?
	bne.s	structure_error                 ; defined twice
	move.l	a0,0(a1,d1.w)                   ; record the PROCEDURE line
	moveq	#0,d0                           ; d0 high word clear
	move.w	(a0),d0                         ; d0 = line length
	cmpi.b	#$46,6(a0)                      ; $46 straight after the name: no parameters
	beq.s	.parameters_marked
	bsr.s	mark_parameter_variables        ; mark the parameters
.parameters_marked:
	bra.w	procedure_header_checked        ; check the next line

;------------------------------------------------------------------------------
; Marks the variables named in the line at a0 from offset 4 (see mark_variables_in_tokens).
;------------------------------------------------------------------------------
mark_variables_from_field:
	lea	4(a0),a2
	bra.s	mark_variables_in_tokens

;------------------------------------------------------------------------------
; Marks the variables named in the line at a0 from offset 6 (after the routine's identifier).
;------------------------------------------------------------------------------
mark_parameter_variables:
	lea	6(a0),a2

;------------------------------------------------------------------------------
; Walks the expression tokens at a2 up to $46 (end of line), $45 or $20 and, for every identifier token
; ($e0-$ef + byte index, $f0-$ff + word index, bit 2 of the token = an alignment byte follows), sets the top
; byte of the identifier's long in identifier_flag_tables (marks it local / a parameter).
;------------------------------------------------------------------------------
mark_variables_in_tokens:
	move.b	(a2)+,d1                        ; token; bit 7 set: identifier
	bmi.s	.identifier_token               ; identifier token
	cmpi.b	#$46,d1                         ; $46: end of the line
	beq.s	.tokens_end                     ; end of the line
	cmpi.b	#$45,d1                         ; $45 ends the list
	beq.s	.tokens_end
	cmpi.b	#$20,d1                         ; $20 ends the list too
	bne.s	mark_variables_in_tokens        ; next token
.tokens_end:
	rts
.identifier_token:
	moveq	#0,d2                           ; d2 = index
	bclr	#$4,d1                          ; bit 4: word index follows
	beq.s	.token_index_low                ; byte index
	move.b	(a2)+,d2                        ; index high byte
	asl.w	#8,d2                           ; into the high byte
.token_index_low:
	move.b	(a2)+,d2                        ; index (low byte)
	btst	#$2,d1                          ; bit 2: alignment byte
	beq.s	.token_type                     ; no alignment byte
	addq.l	#1,a2                           ; skip it
.token_type:
	andi.w	#$f,d1                          ; identifier type 0-15
	asl.w	#2,d1                           ; x4: offset of the table pointer
	lea	float_variable_table,a3         ; a3 = flag table pointers
	adda.w	d1,a3                           ; + type x 4
	movea.l	(a3),a3                         ; a3 = flag table for this type
	asl.w	#2,d2                           ; x4: long per identifier
	st	0(a3,d2.w)                      ; mark the identifier
	bra.s	mark_variables_in_tokens        ; next token

check_endproc:
	cmpi.w	#$c,(sp)+                       ; RETURN (end of procedure): top must be PROCEDURE
	bne.w	structure_error                 ; RETURN outside a PROCEDURE
	addq.l	#4,sp                           ; drop the line address
	bra.w	structure_check_next_line

record_label_line:
	moveq	#0,d1                           ; label index (byte or word)
	move.b	5(a0),d1                        ; byte index after the $e0-$ef token
	cmpi.b	#$f0,4(a0)                      ; word index token ($f0-$ff)?
	bcs.s	.label_index_read               ; byte index
	asl.w	#8,d1                           ; into the high byte
	move.b	6(a0),d1                        ; word index: low byte
.label_index_read:
	asl.w	#2,d1                           ; x4: long per label
	movea.l	label_line_table,a1             ; a1 = label line table
	adda.w	d1,a1                           ; + index x 4
	tst.l	(a1)                            ; already defined?
	bne.w	structure_error                 ; label defined twice
	move.l	a0,(a1)                         ; record the label line
	move.w	(a0),d0                         ; d0 = line length
	add.l	d0,(a1)                         ; store the address of the line after the label
	tst.w	(sp)                            ; inside a structure?
	beq.w	structure_check_next_line       ; outside every structure
	bset	#$0,3(a1)                       ; bit 0: label inside a structure
	bra.w	structure_check_next_line

check_local:
	bsr.w	mark_variables_from_field       ; LOCAL: only in a PROCEDURE ($c) or FUNCTION ($22/$24)
	cmpi.w	#$c,(sp)                        ; $c: PROCEDURE
	beq.w	structure_check_next_line
	cmpi.w	#$22,(sp)                       ; $22: numeric FUNCTION
	beq.w	structure_check_next_line
	cmpi.w	#$24,(sp)                       ; $24: string FUNCTION
	beq.w	structure_check_next_line
	bra.w	structure_error                 ; LOCAL outside a routine

record_deffn_line:
	lea	4(a0),a2                        ; a2 = the function token
	move.b	(a2)+,d1                        ; d1 = function token
	moveq	#0,d2                           ; d2 = index
	move.b	(a2)+,d2                        ; d2 = index (first byte)
	bclr	#$4,d1                          ; bit 4: word index
	beq.s	.deffn_type                     ; byte index
	asl.w	#8,d2                           ; into the high byte
	move.b	(a2)+,d2                        ; word index: second byte
.deffn_type:
	lsr.b	#1,d1                           ; bit 0 of the type: string function
	bcs.s	.string_deffn_table             ; string function
	movea.l	function_line_table,a1          ; a1 = numeric function lines
	bra.s	.record_deffn
.string_deffn_table:
	movea.l	string_function_line_table,a1   ; a1 = string function lines
.record_deffn:
	asl.w	#2,d2                           ; x4: long per function
	tst.l	0(a1,d2.w)                      ; defined twice?
	bne.w	structure_error                 ; DEFFN defined twice
	move.l	a0,0(a1,d2.w)                   ; record the DEFFN line
	bsr.w	mark_variables_in_tokens        ; mark its parameters
	bra.w	structure_check_next_line

check_function_header:
	cmpa.l	a5,sp                           ; FUNCTION: only outside every structure
	bne.w	structure_error                 ; FUNCTION inside a structure
	move.b	4(a0),d1                        ; d1 = function token
	moveq	#0,d2                           ; d2 = index
	move.b	5(a0),d2                        ; d2 = index (first byte)
	bclr	#$4,d1                          ; bit 4: word index
	beq.s	.function_type                  ; byte index
	asl.w	#8,d2                           ; into the high byte
	move.b	6(a0),d2                        ; word index: second byte
.function_type:
	lsr.b	#1,d1                           ; bit 0: string function
	bcs.s	.string_function_entry          ; string function
	movea.l	function_line_table,a1          ; a1 = numeric function lines
	moveq	#34,d3                          ; 34 = numeric function entry
	bra.s	.record_function_header
.string_function_entry:
	movea.l	string_function_line_table,a1   ; a1 = string function lines
	moveq	#36,d3                          ; 36 = string function entry
.record_function_header:
	asl.w	#2,d2                           ; x4: long per function
	tst.l	0(a1,d2.w)                      ; defined twice?
	bne.w	structure_error                 ; FUNCTION defined twice
	move.l	a0,0(a1,d2.w)                   ; record the FUNCTION line
	pea	(a0)                            ; push the FUNCTION entry
	move.w	d3,-(sp)                        ; and its 2 x command
	bsr.w	mark_parameter_variables        ; mark the parameters
	bra.w	structure_check_next_line

check_endfunc:
	move.w	(sp),d1                         ; ENDFUNC: top must be a FUNCTION
	cmpi.w	#$22,d1                         ; $22: numeric FUNCTION
	beq.s	.pop_function_entry             ; matches
	cmpi.w	#$24,d1                         ; $24: string FUNCTION
	bne.w	structure_error                 ; ENDFUNC without FUNCTION
.pop_function_entry:
	addq.l	#6,sp                           ; drop the entry
	bra.w	structure_check_next_line

check_return_in_function:
	movea.l	sp,a1                           ; RETURN value: its 2 x command ($22/$24) must be on the stack
.find_function_entry:
	cmp.w	(a1)+,d0                        ; this entry's type?
	beq.w	structure_check_next_line       ; found: fine
	tst.l	(a1)+                           ; skip its line; 0: the bottom marker
	bne.s	.find_function_entry            ; until the bottom marker
	bra.w	structure_error                 ; RETURN value outside a FUNCTION

check_inside_procedure:
	movea.l	sp,a1                           ; must be inside a PROCEDURE
.find_procedure_entry:
	cmpi.w	#$c,(a1)+                       ; PROCEDURE entry?
	beq.w	structure_check_next_line       ; found: fine
	addq.l	#4,a1                           ; skip its line address
	cmpa.l	a5,a1                           ; until the stack bottom
	bcs.s	.find_procedure_entry           ; until the stack bottom
	bra.w	structure_error                 ; not inside a PROCEDURE

check_jump_targets:
	movea.l	program_start,a0                ; second pass: GOTO and RESUME targets
	moveq	#0,d0                           ; d0 high word clear

jump_check_loop:
	move.w	2(a0),d1                        ; d1 = 2 x command
	cmpi.w	#$5a,d1                         ; $5a: 45, the last line
	beq.s	structure_check_done            ; last line: the check is done
	cmpi.w	#$74,d1                         ; 58: GOTO
	beq.s	check_goto_target               ; check the GOTO
	cmpi.w	#$d4,d1                         ; 106/107: RESUME label
	beq.w	check_resume_label              ; check the RESUME
	cmpi.w	#$d6,d1                         ; $d6: 107
	beq.w	check_resume_label

jump_check_next_line:
	adda.w	(a0),a0                         ; next line
	bra.s	jump_check_loop

structure_check_done:
	moveq	#0,d7                           ; d7 = 0: structure right
	lea	6(a5),sp                        ; drop the stack entries
	movea.l	label_line_table,a0             ; a0 = label lines
	movea.l	procedure_line_table,a1         ; a1 = their end (the procedure table follows)
	bra.s	.inside_bits_test               ; clear bit 0 of every label line
.clear_inside_bit:
	addq.l	#3,a0                           ; to the low byte of the long
	bclr	#$0,(a0)+                       ; clear the inside-structure bit
.inside_bits_test:
	cmpa.l	a1,a0                           ; until the procedure table
	bcs.s	.clear_inside_bit
	rts

;------------------------------------------------------------------------------
; Gets the label named in the line at a0 (token at offset 4, byte or word index) from label_line_table.
; Exit: d3 = address of the line after the label (bit 0 removed), d4 = 1 when the label lies inside a
; structure, else 0; Z set when the label was never defined.
;------------------------------------------------------------------------------
get_label_line:
	moveq	#0,d3                           ; d3 = label index
	lea	4(a0),a1                        ; a1 = the label token
	cmpi.b	#$f0,(a1)+                      ; word index token ($f0-$ff)?
	bcs.s	.get_index_low                  ; byte index
	move.b	(a1)+,-(sp)                     ; high byte via the stack
	move.w	(sp)+,d3                        ; d3 = high byte << 8
.get_index_low:
	move.b	(a1)+,d3                        ; index low byte
	asl.w	#2,d3                           ; x4: long per label
	movea.l	label_line_table,a1             ; a1 = label line table
	move.l	0(a1,d3.w),d3                   ; d3 = line address, bit 0 = inside a structure
	moveq	#1,d4                           ; d4 = bit 0
	and.l	d3,d4                           ; d4 = 1: label inside a structure
	sub.w	d4,d3                           ; d3 = line address; Z from the low word
	rts

check_goto_target:
	bsr.s	get_label_line
	beq.s	jump_check_next_line            ; label not defined: nothing to check
	movea.l	d3,a1                           ; a1 = the label's line
	cmpa.l	a0,a1                           ; GOTO to its own line?
	beq.s	jump_check_next_line            ; same line: fine
	pea	(a0)                            ; keep the GOTO line
	cmpa.l	a0,a1                           ; a0 = lower line, a1 = higher line
	bhi.s	.lower_line_first               ; label after the GOTO
	exg	a1,a0                           ; label before: swap so a0 < a1
.lower_line_first:
	moveq	#0,d7                           ; d7 = open procedures and FORs
	moveq	#0,d6                           ; d6 = open functions
.count_structures:
	movem.w	(a0),d1-d2                      ; d1 = length, d2 = 2 x command
	cmpi.w	#$c,d2                          ; between GOTO and label: count PROCEDURE ($c), > PROCEDURE ($6c)
	beq.s	.count_open                     ; PROCEDURE: opens
	cmpi.w	#$6c,d2                         ; $6c: > PROCEDURE
	beq.s	.count_open                     ; opens
	cmpi.w	#$e,d2                          ; RETURN ($e)
	beq.s	.count_close                    ; RETURN: closes
	cmpi.w	#$14,d2                         ; FUNCTION ($14) / ENDFUNC ($16)
	beq.s	.count_function                 ; FUNCTION: opens
	cmpi.w	#$16,d2                         ; $16: ENDFUNC
	beq.s	.count_endfunc                  ; closes
	cmpi.w	#$26,d2                         ; FOR $26-$3c opens, NEXT $3e-$54 closes
	bcs.s	.count_next_line                ; below FOR: not counted
	cmpi.w	#$3e,d2                         ; $26-$3c: FOR
	bcs.s	.count_open                     ; FOR opens
	cmpi.w	#$54,d2                         ; $3e-$54: NEXT
	bls.s	.count_next                     ; NEXT closes
.count_next_line:
	adda.w	d1,a0                           ; next line
	cmpa.l	a1,a0                           ; up to the higher line
	bcs.s	.count_structures               ; until the higher line
.count_done:
	movea.l	(sp)+,a0                        ; a0 = the GOTO line
	or.l	d6,d7                           ; nothing crossed: fine
	beq.w	jump_check_next_line            ; nothing crossed: next line
	clr.l	-(sp)                           ; error with line address 0
	bra.w	structure_error                 ; GOTO into or out of a structure
.count_function:
	addq.l	#1,d6                           ; FUNCTION: counted in d6 and d7
.count_open:
	addq.l	#1,d7                           ; one more open
	bra.s	.count_next_line
.count_endfunc:
	subq.l	#1,d6                           ; ENDFUNC: counted in d6 and d7
.count_close:
	subq.l	#1,d7                           ; one less open
	bra.s	.count_next_line
.count_next:
	subq.l	#1,d7                           ; NEXT closes a FOR
	bpl.s	.count_next_line                ; more NEXTs than FORs: stop
	bra.s	.count_done                     ; stop: d7 is negative

check_resume_label:
	bsr.w	get_label_line
	beq.w	jump_check_next_line            ; label not defined: nothing to check
	asl.w	#1,d4                           ; d4 = 0 or 2
	addi.w	#$d4,d4                         ; RESUME label: command 106 or 107 from the label's bit 0
	move.w	d4,2(a0)                        ; rewrite the command
	moveq	#0,d7                           ; d7 = FOR nesting
	movea.l	d3,a1                           ; a1 = the label's line
.scan_to_label:
	movem.w	(a1),d1-d2                      ; d1 = length, d2 = 2 x command
	cmpi.w	#$5a,d2                         ; stop at the last line, a routine or its end
	beq.s	.scan_stop                      ; last line
	cmpi.w	#$5c,d2                         ; $5c: command 46
	beq.s	.scan_stop                      ; command 46
	cmpi.w	#$c,d2                          ; $c: PROCEDURE
	beq.s	.scan_stop                      ; PROCEDURE
	cmpi.w	#$6c,d2                         ; $6c: > PROCEDURE
	beq.s	.scan_stop                      ; > PROCEDURE
	cmpi.w	#$e,d2                          ; $e: RETURN
	beq.s	.scan_stop                      ; RETURN
	cmpi.w	#$14,d2                         ; $14: FUNCTION
	beq.s	.scan_stop                      ; FUNCTION
	cmpi.w	#$16,d2                         ; $16: ENDFUNC is an error at once
	beq.s	.endfunc_crossed                ; ENDFUNC: error
	cmpi.w	#$26,d2                         ; FOR $26-$3c opens, NEXT $3e-$54 closes
	bcs.s	.scan_next_line                 ; below FOR: not counted
	cmpi.w	#$3e,d2                         ; $26-$3c: FOR
	bcs.s	.scan_open                      ; FOR opens
	cmpi.w	#$54,d2                         ; $3e-$54: NEXT
	bls.s	.scan_close                     ; NEXT closes
.scan_next_line:
	adda.w	d1,a1                           ; next line
	bra.s	.scan_to_label
.scan_stop:
	tst.l	d7                              ; label inside a FOR: error
	beq.w	jump_check_next_line            ; not inside a FOR: fine
	clr.l	-(sp)                           ; error with line address 0
.endfunc_crossed:
	bra.w	structure_error                 ; RESUME into a loop
.scan_open:
	addq.l	#1,d7                           ; FOR
	bra.s	.scan_next_line
.scan_close:
	subq.l	#1,d7                           ; NEXT
	bpl.s	.scan_next_line                 ; until the label's loop closes
	bra.s	.scan_stop                      ; more NEXTs than FORs: stop

procedure_header_checked:
	moveq	#0,d0                           ; d0 high word clear again
	bra.w	structure_check_next_line       ; check the next line
next_line_pointer:
	dc.w	$0000,$0000
compile_start_sp:
	dc.w	$0000,$0000
break_check_flag:
	dc.w	$0000
option_f_flag:
	dc.b	$00
option_star_flag:
	dc.b	$00
error_names_flag:
	dc.b	$00
resume_next_used_flag:
	dc.b	$00
irqon_at_start_flag:
	dc.b	$00
parsing_command_line_flag:
	dc.b	$00
statement_sp:
	dc.w	$0000,$0000
unreclaimed_source_line:
	dc.w	$0000,$0000
keep_source_flag:
	dc.b	$00
no_move_flag:
	dc.b	$01
option_n_flag:
	dc.w	$0000

;------------------------------------------------------------------------------
; Compiles the program, one source line at a time. Starts the code with lea *-$100(pc),a0 (the basepage),
; lea $100(a0),sp and a jsr to library routine $3a INIT, plus a call of IRQON when option I+ was on the command
; line. For each line: counts the line number, sets a4 to ir_buffer and a5 to the line's tokens, and calls the
; handler for its command through statement_dispatch_table. A handler either returns (the IR is then optimised
; by optimise_ir and turned into 68000 code in statement_code_buffer by generate_code) or jumps to
; copy_statement_code or next_statement itself. Open structures are kept on the stack as entries: word type, long
; code offset.
;------------------------------------------------------------------------------
compile_program:
	movea.l	code_buffer_start,a0            ; a0 = code buffer
	move.l	sp,compile_start_sp             ; kept for the error exit
	move.l	#$41fafefe,(a0)+                ; lea $fefe(pc),a0: the basepage
	move.l	#$4fe80100,(a0)+                ; lea $100(a0),sp
	move.l	#$4eb9ffff,(a0)+                ; jsr to library routine $003a INIT ($ffff: library call to resolve)
	move.w	#$3a,(a0)+                      ; routine number of INIT
	tst.w	irqon_at_start_flag             ; option I+ on the command line?
	beq.s	.no_irqon
	move.w	#$6101,(a0)+                    ; $6101 + routine: library call, here $33f IRQON
	move.w	#$33f,(a0)+                     ; routine number of IRQON
.no_irqon:
	move.l	a0,code_write_pointer           ; code continues here
	move.l	a5,next_line_pointer            ; a5 = first program line
	move.l	a5,unreclaimed_source_line      ; no source reclaimed yet

compile_next_line:
	addq.w	#1,source_line_number           ; count the source line
	lea	ir_buffer,a4                    ; a4 = IR buffer
	movea.l	next_line_pointer(pc),a5        ; a5 = this line
	movea.l	a5,a0                           ; a0 = this line
	adda.w	(a5)+,a0                        ; next line = line + length
	move.l	a0,next_line_pointer            ; keep the next line
	move.w	(a5)+,d6                        ; d6 = 2 x command
	lea	statement_dispatch_table(pc,d6.w),a0 ; self-relative entry
	adda.w	(a0),a0                         ; a0 = handler
	move.l	sp,statement_sp                 ; kept for the error exit
	jsr	(a0)                            ; call the statement handler

generate_statement_code:
	bsr.w	optimise_ir                     ; optimise the IR
	movea.l	a3,a4                           ; a4 = a3 as the optimiser leaves it
	jsr	generate_code                   ; generate the code

copy_statement_code:
	bsr.s	copy_code_to_output             ; append the code

next_statement:
	bra.s	compile_next_line               ; next line
	stop	#$1                             ; never reached

;------------------------------------------------------------------------------
; Appends the statement's code (statement_code_buffer to a1) to the program code at code_write_pointer, with a
; jsr (a6) after it when option U+ (break check) is on.
;------------------------------------------------------------------------------
copy_code_to_output:
	movea.l	code_write_pointer,a0           ; a0 = end of the program code
	lea	statement_code_buffer,a2        ; a2 = the statement's code
	move.l	a1,d0                           ; d0 = code bytes
	sub.l	a2,d0                           ; d0 = bytes of code
	beq.s	.nothing_to_copy                ; no code
	move.b	break_check_flag(pc),d1         ; option U+ on?
	beq.s	.no_break_check                 ; no break check
	move.w	#$4e96,(a1)+                    ; jsr (a6): break check (option U+)
	addq.w	#2,d0                           ; two more bytes
.no_break_check:
	lsr.w	#1,d0                           ; word count
	bra.s	.copy_loop                      ; copy d0 words
.copy_word:
	move.w	(a2)+,(a0)+                     ; copy a word
.copy_loop:
	dbra	d0,.copy_word                   ; copy the code
	move.l	a0,code_write_pointer           ; new end of the program code
.nothing_to_copy:
	rts

compile_end_of_program:
	addq.l	#4,sp                           ; last line (command 45)
	bsr.w	shorten_branches                ; shorten the branches
	bsr.w	reclaim_compiled_source         ; give back the source memory
	move.w	#$3b,(a4)+                      ; IR: library routine $3b END
	tst.b	error_names_flag                ; option E$ on?
	beq.s	.no_error_names
	move.w	#$350,(a4)+                     ; IR: library routine $350 ERRNAMES (option E$)
.no_error_names:
	clr.w	(a4)                            ; end of the IR
	bra.w	generate_and_append             ; generate and copy

compile_end:
	bra.w	emit_end_unless_returned        ; END (124) and command 46

compile_nothing:
	rts                                     ; commands that make no code

; Statement dispatch table: one word per command, indexed by 2 x command, each entry relative to its own address.
; Commands 0-255 are written as labels; the entries for commands 256-453 continue as raw words from $1196 to $133a.
statement_dispatch_table:
	dc.w	compile_do_repeat-statement_dispatch_table
	dc.w	compile_loop_end-(statement_dispatch_table+2)
	dc.w	compile_do_repeat-(statement_dispatch_table+4)
	dc.w	compile_until-(statement_dispatch_table+6)
	dc.w	compile_while-(statement_dispatch_table+8)
	dc.w	compile_wend-(statement_dispatch_table+10)
	dc.w	stmt_procedure-(statement_dispatch_table+12)
	dc.w	stmt_return-(statement_dispatch_table+14)
	dc.w	compile_if-(statement_dispatch_table+16)
	dc.w	compile_endif-(statement_dispatch_table+18)
	dc.w	compile_function-(statement_dispatch_table+20)
	dc.w	stmt_endfunc-(statement_dispatch_table+22)
	dc.w	stmt_select-(statement_dispatch_table+24)
	dc.w	stmt_endselect-(statement_dispatch_table+26)
	dc.w	compile_else-(statement_dispatch_table+28)
	dc.w	stmt_case-(statement_dispatch_table+30)
	dc.w	compile_else_if-(statement_dispatch_table+32)
	dc.w	stmt_return_value-(statement_dispatch_table+34)
	dc.w	stmt_return_string-(statement_dispatch_table+36)
	dc.w	compile_for_float_to-(statement_dispatch_table+38)
	dc.w	compile_for_float_downto-(statement_dispatch_table+40)
