	dc.w	compile_for_word_step-(statement_dispatch_table+54)
	dc.w	compile_for_byte_to-(statement_dispatch_table+56)
	dc.w	compile_for_byte_downto-(statement_dispatch_table+58)
	dc.w	compile_for_byte_step-(statement_dispatch_table+60)
	dc.w	compile_next_float_to-(statement_dispatch_table+62)
	dc.w	compile_next_float_downto-(statement_dispatch_table+64)
	dc.w	compile_next_float_step-(statement_dispatch_table+66)
	dc.w	compile_next_int_to-(statement_dispatch_table+68)
	dc.w	compile_next_int_downto-(statement_dispatch_table+70)
	dc.w	compile_next_int_step-(statement_dispatch_table+72)
	dc.w	compile_next_word_to-(statement_dispatch_table+74)
	dc.w	compile_next_word_downto-(statement_dispatch_table+76)
	dc.w	compile_next_word_step-(statement_dispatch_table+78)
