	dc.w	compile_end_of_program-(statement_dispatch_table+90)
	dc.w	compile_end-(statement_dispatch_table+92)
	dc.w	unsupported_statement_token-(statement_dispatch_table+94)
	dc.w	stmt_monitor-(statement_dispatch_table+96)
	dc.w	compile_do_while-(statement_dispatch_table+98)
	dc.w	compile_do_until-(statement_dispatch_table+100)
	dc.w	compile_loop_while-(statement_dispatch_table+102)
