	dc.w	stmt_gosub-(statement_dispatch_table+122)
	dc.w	stmt_gosub-(statement_dispatch_table+124)
	dc.w	stmt_label-(statement_dispatch_table+126)
	dc.w	stmt_let_float-(statement_dispatch_table+128)
	dc.w	stmt_let_string-(statement_dispatch_table+130)
	dc.w	stmt_let_int-(statement_dispatch_table+132)
