;------------------------------------------------------------------------------
; Shortens the branches recorded in branch_offset_list (a6 = end of the list; offsets relative to
; code_buffer_start). jmp abs.l ($4ef9) becomes bra.s or bra.w, or disappears when it jumps to the next
; instruction; Bcc.w becomes Bcc.s; the conditional form with $ff in the low byte followed by a long target
; becomes Bcc.w/Bcc.s with the condition inverted (bit 0 of the condition flipped); a nop ($4e71) entry is removed.
; Repeats until a pass changes nothing, puts $11111111 after the code, and resets a6 to the list start.
;------------------------------------------------------------------------------
shorten_branches:
	movea.l	code_write_pointer,a0           ; a0 = end of the code
	move.l	#$11111111,(a0)                 ; end marker after the code
	lea	branch_offset_list,a0           ; a0 walks the branch list
	cmpa.l	a0,a6                           ; empty list
	beq.w	.shortening_done                ; no branches recorded
	move.l	code_buffer_start,d6            ; d6 = code buffer base
	moveq	#0,d7                           ; d7 = nothing changed yet
.next_branch:
	movea.l	(a0)+,a1                        ; a1 = the recorded branch
	adda.l	d6,a1                           ; + code buffer base
	move.w	(a1)+,d0                        ; d0 = its opcode
	cmpi.w	#$4ef9,d0                       ; $4ef9: jmp abs.l
	beq.s	.absolute_jump                  ; jmp abs.l
	cmpi.w	#$4e71,d0                       ; $4e71 nop
	beq.s	.remove_nop                     ; nop: remove it
	cmpi.b	#$ff,d0                         ; low byte $ff: conditional with a long target
	bne.s	.not_long_branch                ; low byte not $ff
	addq.l	#2,a1                           ; Bcc over a jmp: skip the jmp opcode
	bra.w	.long_conditional               ; Bcc over a jmp
.not_long_branch:
	tst.b	d0                              ; low byte 0: Bcc.w / bra.w
	beq.s	.word_branch                    ; Bcc.w / bra.w
.branch_checked:
	cmpa.l	a6,a0                           ; more entries?
	bcs.s	.next_branch                    ; next entry
	tst.w	d7                              ; changed anything?
	bne.s	shorten_branches                ; something changed: another pass
	bra.w	.shortening_done                ; nothing changed: done
.word_branch:
	move.w	(a1)+,d0                        ; d0 = word displacement
	bmi.s	.test_byte_distance             ; backward: keeps its value
	subq.w	#2,d0                           ; forward: 2 bytes closer once shortened
.test_byte_distance:
	move.w	d0,d2                           ; fits in a byte?
	ext.w	d0                              ; extend the low byte
	cmp.w	d0,d2                           ; fits in a byte?
	bne.s	.branch_checked                 ; no: keep the word form
	moveq	#2,d0                           ; remove the displacement word
	bsr.w	remove_code_bytes               ; remove 2 bytes
	move.b	d2,-(a1)                        ; byte displacement into the opcode
	bra.s	.branch_checked                 ; next entry
.absolute_jump:
	tst.b	(a1)                            ; high byte of the target must be 0
	bne.s	.branch_checked                 ; not a code address: keep it
	move.l	(a1)+,d0                        ; d0 = target offset
	add.l	d6,d0                           ; + code base
	sub.l	a1,d0                           ; - address after the jmp: the distance
	move.l	d0,d2                           ; d2 = distance
	ext.w	d0                              ; fits in a byte?
	ext.l	d0                              ; extended from the low byte
	cmp.l	d0,d2                           ; fits in a byte?
	beq.s	.jump_fits_byte                 ; yes: bra.s
	move.l	d2,d0                           ; fits in a word?
	bmi.s	.test_word_distance             ; backward: corrected below
	addq.l	#2,d2                           ; forward: displacement = distance + 2
	addq.l	#2,d0                           ; d0 the same, for the compare
.test_word_distance:
	ext.l	d0                              ; extended from the low word
	cmp.l	d0,d2                           ; fits in a word?
	bne.s	.branch_checked                 ; no: keep the jmp
	moveq	#2,d0                           ; remove 2 bytes: the long becomes the displacement
	bsr.w	remove_code_bytes               ; remove 2 bytes
	move.w	d2,-(a1)                        ; store the displacement
	bpl.s	.store_bra_w                    ; forward: done
	addq.w	#4,(a1)                         ; backward: 4 more, counted from the bra.w
.store_bra_w:
	move.w	#$6000,-(a1)                    ; $6000: bra.w
	bra.s	.branch_checked                 ; next entry
.jump_fits_byte:
	tst.b	d2                              ; distance 0: jump to the next instruction
	beq.s	.remove_jump                    ; remove the jmp
	moveq	#4,d0                           ; remove the long: the jmp word becomes bra.s
	bsr.s	remove_code_bytes               ; remove 4 bytes
	move.b	d2,-(a1)                        ; byte displacement
	bpl.s	.store_bra_s                    ; forward: done
	addq.b	#4,(a1)                         ; backward: 4 more, counted from the bra.s
.store_bra_s:
	move.b	#$60,-(a1)                      ; $60xx: bra.s
	bra.s	.branch_checked                 ; next entry
.remove_nop:
	moveq	#2,d0                           ; nop: remove its 2 bytes
	bra.s	.remove_entry                   ; remove the entry
.remove_jump:
	moveq	#6,d0                           ; jmp to the next instruction: remove all 6
.remove_entry:
	bsr.s	remove_code_bytes               ; remove the bytes
	subq.l	#4,a0                           ; back to this entry
.close_list_gap:
	move.l	4(a0),(a0)+                     ; remove the entry from the list
	cmpa.l	a6,a0                           ; until the list end
	bcs.s	.close_list_gap                 ; move the next entry down
	subq.l	#4,a6                           ; list one entry shorter
	bra.w	shorten_branches                ; start over
.long_conditional:
	tst.b	(a1)                            ; target high byte must be 0
	bne.w	.branch_checked                 ; not a code address: keep it
	move.l	(a1)+,d0                        ; d0 = target offset
	add.l	d6,d0                           ; + code base
	sub.l	a1,d0                           ; - address after the long: the distance
	move.l	d0,d2                           ; d2 = distance
	ext.w	d0                              ; fits in a byte?
	ext.l	d0                              ; extended from the low byte
	cmp.l	d0,d2                           ; fits in a byte?
	beq.s	.conditional_fits_byte          ; yes: Bcc.s
	addq.l	#2,d2                           ; Bcc.w displacement = distance + 2 (+4 more backward)
	move.w	d2,d0                           ; fits in a word?
	ext.l	d0                              ; extended from the low word
	cmp.l	d0,d2                           ; fits in a word?
	bne.w	.branch_checked                 ; no: keep the long form
	moveq	#4,d0                           ; remove the long: the jmp word becomes the displacement
	bsr.s	remove_code_bytes               ; remove 4 bytes
	move.w	d2,-(a1)                        ; store the displacement
	bpl.s	.store_bcc_w                    ; forward: done
	addq.w	#4,(a1)                         ; backward: 4 more
.store_bcc_w:
	clr.b	-(a1)                           ; low byte 0: word form
	bchg	#$0,-(a1)                       ; invert the condition
	bra.w	.branch_checked                 ; next entry
.conditional_fits_byte:
	tst.b	d2                              ; distance 0: the Bcc skips nothing
	beq.s	.remove_conditional             ; nothing to skip: remove all
	moveq	#6,d0                           ; remove jmp and long: Bcc.s remains
	bsr.s	remove_code_bytes               ; remove 6 bytes
	move.b	d2,-(a1)                        ; byte displacement
	bpl.s	.invert_bcc_s                   ; forward: done
	addq.b	#6,(a1)                         ; backward: 6 more
.invert_bcc_s:
	bchg	#$0,-(a1)                       ; invert the condition
	bra.w	.branch_checked                 ; next entry
.remove_conditional:
	moveq	#8,d0                           ; remove all 8 bytes
	bra.s	.remove_entry                   ; remove the entry
.shortening_done:
	lea	branch_offset_list,a6           ; reset a6 to the list start
	rts                                     ; rts

;------------------------------------------------------------------------------
; Removes d0 bytes before a1 from the code (a0 = the list entry being shortened), moves the code after them down
; and corrects every other recorded branch whose distance crosses the removed bytes (a byte branch that becomes
; 0 is turned into a nop) and every absolute jump target beyond them. Sets d7 to say something changed.
;------------------------------------------------------------------------------
remove_code_bytes:
	suba.l	d0,a1                           ; a1 = start of the bytes to remove
	exg	a1,a0                           ; move_code_down takes the address in a0
	bsr.w	move_code_down                  ; move the code after them down
	exg	a1,a0                           ; a1 = the removed position, a0 = the list entry
	lea	branch_offset_list,a2           ; a2 walks the list from the start
	subq.l	#4,a0                           ; a0 = this entry
	move.l	a1,d3                           ; d3 = offset of the removed bytes
	sub.l	code_buffer_start,d3            ; relative to the code buffer
	bra.s	.earlier_checked                ; fix the entries before this one
.fix_earlier_branch:
	movea.l	(a2)+,a3                        ; a3 = an earlier branch
	adda.l	d6,a3                           ; + code buffer base
	move.w	(a3)+,d4                        ; d4 = its opcode
	cmpi.w	#$4ef9,d4                       ; jmp abs.l
	beq.s	.fix_earlier_absolute           ; fix its absolute target
	cmpi.w	#$4e71,d4                       ; nop: nothing to fix
	beq.s	.earlier_checked                ; nop: nothing
	tst.b	d4                              ; low byte 0: word displacement
	beq.s	.fix_earlier_word_branch        ; word branch
	cmpi.b	#$ff,d4                         ; $ff: conditional over a jmp
	bne.s	.fix_earlier_byte_branch        ; byte branch
	addq.l	#2,a3                           ; to the long target
	bra.s	.fix_earlier_absolute           ; fix the jmp's target
.fix_earlier_byte_branch:
	ext.w	d4                              ; byte displacement
	adda.w	d4,a3                           ; a3 = its target
	cmpa.l	a1,a3                           ; target not beyond the removed bytes: unchanged
	bls.s	.earlier_checked                ; target not beyond: unchanged
	movea.l	-$4(a2),a3                      ; a3 = the branch again
	adda.l	d6,a3                           ; + code buffer base
	sub.b	d0,1(a3)                        ; byte branch over the removed bytes: shorter
	bne.s	.earlier_checked                ; still non-zero: done
	move.w	#$4e71,(a3)                     ; branch to the next instruction: nop
	bra.s	.earlier_checked                ; next entry
.fix_earlier_word_branch:
	adda.w	(a3),a3                         ; a3 = target of the word branch
	cmpa.l	a1,a3                           ; not beyond the removed bytes: unchanged
	bls.s	.earlier_checked                ; target not beyond: unchanged
	movea.l	-$4(a2),a3                      ; a3 = the branch again
	adda.l	d6,a3                           ; + code buffer base
	sub.w	d0,2(a3)                        ; displacement shorter by d0
	bra.s	.earlier_checked                ; next entry
.fix_earlier_absolute:
	move.l	(a3),d4                         ; absolute target offset
	cmp.l	d3,d4                           ; before the removed bytes: unchanged
	bcs.s	.earlier_checked                ; before: unchanged
	sub.l	d0,(a3)                         ; lower it by d0
.earlier_checked:
	cmpa.l	a0,a2                           ; until this entry
	bne.s	.fix_earlier_branch             ; next earlier entry
	pea	(a1)                            ; keep a1
	movea.l	(a2)+,a1                        ; a1 = this entry's offset
	move.l	a1,d4                           ; d4 = offset (not used)
	adda.l	d6,a1                           ; a1 = address of this branch
	addq.l	#4,a0                           ; a0 back to the next entry
	bra.s	.later_checked                  ; fix the entries after this one
.fix_later_branch:
	movea.l	(a2)+,a3                        ; a3 = a later branch
	adda.l	d6,a3                           ; + code buffer base
	move.w	(a3)+,d4                        ; d4 = its opcode
	cmpi.w	#$4ef9,d4                       ; jmp abs.l
	beq.s	.fix_later_absolute             ; fix its absolute target
	cmpi.w	#$4e71,d4                       ; nop: nothing to fix
	beq.s	.later_checked                  ; nop: nothing
	tst.b	d4                              ; low byte 0: word displacement
	beq.s	.fix_later_word_branch          ; word branch
	cmpi.b	#$ff,d4                         ; $ff: conditional over a jmp
	bne.s	.fix_later_byte_branch          ; byte branch
	addq.l	#2,a3                           ; to the long target
	bra.s	.fix_later_absolute             ; fix the jmp's target
.fix_later_byte_branch:
	ext.w	d4                              ; byte displacement
	adda.w	d4,a3                           ; a3 = its target
	cmpa.l	a1,a3                           ; target after this branch: unchanged
	bcc.s	.later_checked                  ; target after this branch: unchanged
	movea.l	-$4(a2),a3                      ; a3 = the branch again
	adda.l	d6,a3                           ; + code buffer base
	add.b	d0,1(a3)                        ; backward over the removed bytes: shorter
	bne.s	.later_checked                  ; still non-zero: done
	move.w	#$4e71,(a3)                     ; becomes 0: nop
	bra.s	.later_checked                  ; next entry
.fix_later_word_branch:
	adda.w	(a3),a3                         ; a3 = target of the word branch
	cmpa.l	a1,a3                           ; target after this branch: unchanged
	bcc.s	.later_checked                  ; target after this branch: unchanged
	movea.l	-$4(a2),a3                      ; a3 = the branch again
	adda.l	d6,a3                           ; + code buffer base
	add.w	d0,2(a3)                        ; backward displacement corrected by d0
	bra.s	.later_checked                  ; next entry
.fix_later_absolute:
	move.l	(a3),d4                         ; absolute target offset
	cmp.l	d3,d4                           ; not beyond the removed bytes: unchanged
	bls.s	.later_checked                  ; not beyond: unchanged
	sub.l	d0,(a3)                         ; lower it by d0
.later_checked:
	cmpa.l	a6,a2                           ; until the end of the list
	bcs.s	.fix_later_branch               ; next later entry
	st	d7                              ; d7: something changed
	movea.l	(sp)+,a1                        ; a1 restored
	rts

;------------------------------------------------------------------------------
; Moves the code from a0+d0 up to code_write_pointer down to a0 and lowers by d0 every label and function code
; offset and every branch_offset_list entry beyond a0. Lowers code_write_pointer. Keeps a0-a3.
;------------------------------------------------------------------------------
move_code_down:
	movem.l	a0-a3,-(sp)                     ; keep a0-a3
	movem.l	label_address_table,a1-a2       ; a1 = label code offsets, a2 = their end
	bra.s	.label_offset_checked           ; lower the label offsets
.fix_label_offset:
	move.l	(a1)+,d1                        ; d1 = offset; -1: undefined
	bmi.s	.label_offset_checked           ; undefined
	add.l	d6,d1                           ; + code base
	cmpa.l	d1,a0                           ; not beyond a0: unchanged
	bcc.s	.label_offset_checked           ; not beyond a0
	sub.l	d0,-$4(a1)                      ; lower it by d0
.label_offset_checked:
	cmpa.l	a2,a1                           ; until the end of the table
	bcs.s	.fix_label_offset               ; next label offset
	movea.l	numeric_fn_address_table,a1     ; a1 = numeric function offsets (procedures not included)
	movea.l	routine_tables_end,a2           ; a2 = end of the routine tables
	bra.s	.function_offset_checked        ; lower the function offsets
.fix_function_offset:
	move.l	(a1)+,d1                        ; d1 = offset; -1: undefined
	bmi.s	.function_offset_checked        ; undefined
	add.l	d6,d1                           ; + code base
	cmpa.l	d1,a0                           ; not beyond a0: unchanged
	bcc.s	.function_offset_checked        ; not beyond a0
	sub.l	d0,-$4(a1)                      ; lower it by d0
.function_offset_checked:
	cmpa.l	a2,a1                           ; until the end of the tables
	bcs.s	.fix_function_offset            ; next function offset
	lea	0(a0,d0.l),a1                   ; a1 = source: a0 + d0
	movea.l	a1,a3                           ; a3 = start of the moved part
	movea.l	code_write_pointer,a2           ; a2 = end of the code
.move_28_bytes:
	move.l	(a1)+,(a0)+                     ; copy 28 bytes per pass
	move.l	(a1)+,(a0)+
	move.l	(a1)+,(a0)+
	move.l	(a1)+,(a0)+
	move.l	(a1)+,(a0)+
	move.l	(a1)+,(a0)+
	move.l	(a1)+,(a0)+
	cmpa.l	a2,a1                           ; up to the end of the code
	bls.s	.move_28_bytes                  ; until past the end of the code
	move.l	(a1)+,(a0)+                     ; one more long
	sub.l	d0,code_write_pointer           ; the code is d0 bytes shorter
	suba.l	code_buffer_start,a3            ; offset of the moved part
	lea	branch_offset_list,a0           ; a0 walks the branch list
	bra.s	.branch_entry_checked           ; lower the branch list entries
.fix_branch_entry:
	cmpa.l	(a0)+,a3                        ; entry before the moved part: unchanged
	bhi.s	.branch_entry_checked           ; before the moved part: unchanged
	sub.l	d0,-$4(a0)                      ; lower it by d0
.branch_entry_checked:
	cmpa.l	a6,a0                           ; until the end of the list
	bcs.s	.fix_branch_entry               ; next entry
	movem.l	(sp)+,a0-a3                     ; a0-a3 back
	rts
reclaimed_source_bytes:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Gives back the memory of the source lines compiled so far: moves the code buffer (and the data area pointers)
; down over the lines from unreclaimed_source_line to the current line, so code can grow into the source's
; place. Called at PROCEDURE, FUNCTION and the end of the program. The procedure and function line tables are
; corrected. After DEFFN (keep_source_flag) nothing is moved once.
;------------------------------------------------------------------------------
reclaim_compiled_source:
	lea	-$4(a5),a0                      ; a0 = the current line (a5 is past its header)
	tst.w	keep_source_flag                ; DEFFN set it: keep the source once
	beq.s	.reclaim                        ; not set: reclaim
	clr.b	keep_source_flag                ; only once
	move.l	a0,unreclaimed_source_line      ; the next reclaim starts here
	rts
.reclaim:
	movea.l	unreclaimed_source_line(pc),a1  ; a1 = the last line left unreclaimed
	adda.w	(a1),a1                         ; a1 = the line after it
	cmpi.w	#$336,2(a1)                     ; skip a $ line (411) after the routine line
	bne.s	.start_found                    ; no $ line
	adda.w	(a1),a1                         ; skip the $ line
.start_found:
	move.l	code_write_pointer,d0           ; d0 = bytes from a0 to the code end
	sub.l	a0,d0                           ; d0 = bytes to move
	move.l	a0,d1                           ; d1 = bytes to give back
	sub.l	a1,d1                           ; d1 = distance: the reclaimed bytes
	beq.s	.nothing_to_reclaim             ; nothing to give back
	add.l	d1,reclaimed_source_bytes       ; total given back
	jsr	copy_memory_forwards            ; memory move a0 -> a1, d0 bytes
	sub.l	d1,code_write_pointer           ; move every pointer down by d1
	sub.l	d1,code_buffer_start            ; lower the code buffer start
	sub.l	d1,next_line_pointer            ; lower the next line
	sub.l	d1,inline_area_start            ; lower the INLINE area
	sub.l	d1,data_text_start              ; lower the DATA text
	sub.l	d1,data_area_end
	sub.l	d1,string_pool_limit            ; lower the string pool limit
	suba.l	d1,a5                           ; a5 follows the move
	lea	-$4(a5),a2                      ; the current line is the next start
	move.l	a2,unreclaimed_source_line      ; next reclaim starts at this line
	movea.l	procedure_line_table,a0         ; procedure line table, up to the next section
	movea.l	word_array_table,a1             ; a1 = end: start of the next section
	bsr.s	adjust_line_pointer_table       ; lower its moved lines
	movea.l	function_line_table,a0          ; function line tables, up to the end of the flag tables
	movea.l	identifier_flag_tables_end,a1   ; a1 = end of the flag tables
	bra.s	adjust_line_pointer_table       ; lower its moved lines
.nothing_to_reclaim:
	move.l	next_line_pointer(pc),unreclaimed_source_line ; nothing moved: start from the next line
	rts

adjust_line_pointer:
	cmp.l	a2,d0                           ; not above a2: unchanged
	bls.s	adjust_line_pointer_table       ; not in the moved part: next
	sub.l	d1,-$4(a0)                      ; lower it by d1

;------------------------------------------------------------------------------
; Lowers by d1 every long in the table a0..a1 that is above a2 (a source line address in the moved part).
;------------------------------------------------------------------------------
adjust_line_pointer_table:
	move.l	(a0)+,d0                        ; d0 = next table long
	cmpa.l	a1,a0                           ; until a1
	bls.s	adjust_line_pointer             ; until the end of the table
	rts

;------------------------------------------------------------------------------
; DO and REPEAT: pushes the loop start (type 0, current code offset) under the return address.
;------------------------------------------------------------------------------
compile_do_repeat:
	movea.l	(sp)+,a0                        ; a0 = return address
	move.l	code_write_pointer,d0           ; d0 = code offset of the loop start
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,-(sp)                        ; push the loop start offset
	clr.w	-(sp)                           ; type 0: loop start
	jmp	(a0)                            ; return

;------------------------------------------------------------------------------
; DO WHILE (IR $80bd, branch when false) and DO UNTIL (IR $80be, branch when true): pushes the loop start, then
; the condition with a placeholder target $0f0f0f0f, kept as an exit (type $8000) patched at LOOP.
;------------------------------------------------------------------------------
compile_do_while:
	move.w	#$80bd,d1                       ; $80bd: IR branch when false
	bra.s	compile_do_condition            ; push the loop start, parse the condition

compile_do_until:
	move.w	#$80be,d1                       ; $80be: IR branch when true

compile_do_condition:
	move.l	code_write_pointer,d0           ; d0 = code offset of the loop start
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,(sp)                         ; replaces the return address: the DO entry
	clr.w	-(sp)                           ; type 0: loop start
	move.w	d1,-(sp)                        ; keep the branch IR code
	bsr.w	parse_expression                ; parse the condition
	move.w	(sp)+,(a4)+                     ; IR branch code
	move.l	#$f0f0f0f,(a4)+                 ; placeholder target
	bsr.w	optimise_and_generate           ; optimise and generate the condition
	cmpa.l	#statement_code_buffer_plus_6,a1 ; only the 6-byte jump made: the condition is constant
	bhi.s	.do_condition_code              ; condition code made
	move.l	code_write_pointer,d0           ; offset of the jump, not yet copied
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,-(sp)                        ; push the exit offset
	move.w	#$8000,-(sp)                    ; $8000: an exit to patch at LOOP
	bra.w	copy_statement_code             ; copy the jump and go on
.do_condition_code:
	bsr.w	copy_code_to_output             ; copy the code
	move.l	code_write_pointer,d0           ; d0 = end of the code
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	subq.l	#8,d0                           ; offset of the 8-byte branch
	move.l	d0,-(sp)                        ; push the exit offset
	move.w	#$8000,-(sp)                    ; $8000: an exit to patch at LOOP
	bra.w	next_statement                  ; next line

;------------------------------------------------------------------------------
; LOOP WHILE ($80be) / LOOP UNTIL ($80bd): parses the condition and branches back to the DO's start offset.
;------------------------------------------------------------------------------
compile_loop_while:
	move.w	#$80be,d0                       ; $80be: IR branch when true
	bra.s	compile_loop_condition

compile_loop_until:
	move.w	#$80bd,d0                       ; $80bd: IR branch when false

compile_loop_condition:
	move.w	d0,-(sp)                        ; keep the branch IR code
	bsr.w	parse_expression                ; parse the condition
	move.w	(sp)+,(a4)+                     ; IR branch code
	bra.s	jump_back_to_loop_start         ; branch back to the DO

;------------------------------------------------------------------------------
; LOOP: IR $8049 (jump) to the start of the innermost DO, then patches every pending exit (entries with bit 15
; set) to the code after the loop and drops the DO entry.
;------------------------------------------------------------------------------
compile_loop_end:
	move.w	#$8049,(a4)+                    ; $8049: IR jump

jump_back_to_loop_start:
	lea	4(sp),a0                        ; a0 = entries past the return address
.find_loop_start:
	move.w	(a0)+,d0                        ; find the DO entry (type 0)
	addq.l	#4,a0                           ; skip its offset
	bne.s	.find_loop_start                ; until a type 0 entry
	move.l	-(a0),(a4)+                     ; IR target: the loop start offset
	bsr.w	optimise_generate_and_append    ; generate and append the jump

patch_loop_exits:
	addq.l	#4,sp                           ; drop the return address / the patched offset
	tst.w	(sp)+                           ; pending exits have bit 15 set
	bpl.s	.loop_start_dropped             ; not an exit: the DO entry
	movea.l	(sp),a0                         ; a0 = the exit's code
	adda.l	code_buffer_start,a0            ; + code buffer base
	move.l	code_write_pointer,d0           ; d0 = code offset after the loop
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	bsr.w	patch_jump_target               ; patch the exit to after the loop
	bra.s	patch_loop_exits                ; next entry
.loop_start_dropped:
	addq.l	#4,sp                           ; drop the DO entry's offset
	bra.w	next_statement                  ; next line

;------------------------------------------------------------------------------
; UNTIL: parses the condition with IR $80bd (branch when false) back to the REPEAT's start, then patches exits.
;------------------------------------------------------------------------------
compile_until:
	bsr.w	parse_expression                ; parse the condition
	move.w	#$80bd,(a4)+                    ; $80bd: IR branch when false
	lea	4(sp),a0                        ; a0 = entries past the return address
.find_repeat_start:
	cmpi.w	#$0,(a0)+                       ; find the type 0 entry
	addq.l	#4,a0                           ; skip its offset
	bne.s	.find_repeat_start              ; until a type 0 entry
	move.l	-(a0),(a4)+                     ; IR target: the REPEAT's offset
	bsr.w	optimise_generate_and_append    ; generate and append the branch
	bra.s	patch_loop_exits                ; patch the exits

;------------------------------------------------------------------------------
; IF: parses the condition with IR $80bd (branch when false) and a placeholder target. When the generated code is
; only the 6-byte jump (condition always false) the lines up to the matching ELSE/ELSE IF/ENDIF are skipped
; (skip_dead_lines; stopped by a label); an always-true condition leaves a nop. Pushes type 1 with the offset of
; the branch to patch.
;------------------------------------------------------------------------------
compile_if:
	bsr.w	parse_expression                ; parse the condition
	move.w	#$80bd,(a4)+                    ; $80bd: IR branch when false
	move.l	#$f0f0f0f,(a4)+                 ; placeholder target
	bsr.w	optimise_and_generate           ; optimise and generate
	cmpa.l	#statement_code_buffer_plus_6,a1 ; only the jump: condition always false
	bne.s	.condition_code                 ; real code: compile the IF
	bsr.w	skip_dead_lines                 ; skip the lines of the dead branch
	cmpi.w	#$3f,d1                         ; 63: stopped at a label, compile normally
	bne.s	.skip_to_else                   ; no label: skip the dead lines
	move.w	d6,source_line_number           ; restore the line number
	bra.s	.condition_code                 ; compile the IF normally
.skip_to_else:
	adda.w	d0,a0                           ; a0 = the line after the stop line
	move.l	a0,next_line_pointer            ; compiling goes on from there
	suba.w	d0,a0                           ; a0 = the stop line again
	subq.l	#4,a6                           ; the branch is not recorded
	addq.l	#4,sp                           ; drop the return address
	cmpi.w	#$9,d1                          ; 9: ENDIF found
	beq.w	next_statement                  ; ENDIF: the whole IF is dead
	cmpi.w	#$7,d1                          ; 7: no command in skip_nesting_table returns 7 (ELSE is 14), so this
                                                ;   test is never true (cannot work out why)
	beq.s	.else_found                     ; never taken (see above)
	lea	ir_buffer,a4                    ; ELSE IF: compile its condition as a new IF
	lea	4(a0),a5                        ; a5 = its tokens
	suba.w	d0,a0                           ; a0 lowered again (compile_if does not use it)
	subq.l	#4,sp                           ; back to the return address slot
	bra.s	compile_if                      ; compile the ELSE IF's condition
.else_found:
	subq.l	#4,sp                           ; keep a stack slot for the entry
	lea	statement_code_buffer,a1        ; a1 = statement code
	move.w	#$4e71,(a1)+                    ; nop in place of the branch
	addq.l	#4,a6                           ; entry kept: shorten_branches removes the nop
.condition_code:
	cmpi.w	#$4e71,-$2(a1)                  ; nop: condition always true
	bne.s	.conditional_branch             ; a real branch
	bsr.w	copy_code_to_output             ; copy the code
	move.l	code_write_pointer,d0           ; offset of the nop
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	subq.l	#2,d0                           ; back to the nop
	move.l	d0,(sp)                         ; the IF entry replaces the return address
	move.w	#$1,-(sp)                       ; type 1: IF
	bra.w	next_statement                  ; next line
.conditional_branch:
	bsr.w	copy_code_to_output             ; copy the code
	move.l	code_write_pointer,d0           ; d0 = end of the code
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	subq.l	#8,d0                           ; offset of the 8-byte branch
	move.l	d0,(sp)                         ; the IF entry replaces the return address
	move.w	#$1,-(sp)                       ; type 1: IF
	bra.w	next_statement                  ; next line

;------------------------------------------------------------------------------
; Scans the lines after next_line_pointer for the end of the dead branch, counting nesting with
; skip_nesting_table and adding to source_line_number. Exit: a0 = the line found, d0 = its length, d1 = its
; command (63 = a label was met, the caller then restores the line number from d6).
;------------------------------------------------------------------------------
skip_dead_lines:
	moveq	#0,d7                           ; d7 = nesting depth
	move.w	source_line_number,d6           ; d6 = line number, for a stop at a label
	movea.l	next_line_pointer(pc),a0        ; a0 = the line after the IF
.scan_line:
	movem.w	(a0),d0-d1                      ; d0 = length, d1 = 2 x command
	addq.w	#1,source_line_number           ; count the line
	cmpi.w	#$80,d1                         ; commands 0-63
	bcs.s	.structure_command              ; a structure command
.scan_next:
	adda.w	d0,a0                           ; next line
	bra.s	.scan_line                      ; next line
.structure_command:
	lsr.w	#1,d1                           ; command number
	move.b	skip_nesting_table(pc,d1.w),d2  ; index by command
	beq.s	.scan_next                      ; 0: ignored
	bmi.s	.scan_stop                      ; $ff: label, stop
	subq.b	#2,d2                           ; 1 -> -1, 2 -> 0, 3 -> 1
	bmi.s	.scan_open                      ; 1: opens
	beq.s	.scan_close                     ; 2: closes
	tst.l	d7                              ; ELSE / DEFAULT / ELSE IF: stop at level 0 only
	bne.s	.scan_next                      ; inside a nested structure: go on
.scan_stop:
	rts                                     ; stop: a label, or ELSE etc. at level 0
.scan_open:
	addq.l	#2,d7                           ; +2 then -1: one level deeper
.scan_close:
	subq.l	#1,d7                           ; closing: one level up
	bpl.s	.scan_next                      ; still inside: go on
	rts                                     ; the dead branch is closed: stop

; One byte per command 0-63 for skip_dead_lines: 1 = opens a structure, 2 = closes one, 3 = ELSE / DEFAULT /
; ELSE IF (stops at level 0), 0 = ignored, $ff = label (stops).
skip_nesting_table:
	dc.w	$0102,$0102,$0102,$0000,$0102,$0000,$0102,$0303
	dc.w	$0300,$0001,$0101,$0101,$0101,$0101,$0101,$0102
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0100,$0000
	dc.w	$0001,$0102,$0200,$0000,$0300,$0000,$0000,$00ff

;------------------------------------------------------------------------------
; ELSE: pushes type 4 with an IR $8049 jump (to ENDIF) and patches the IF's branch to the code after it. When the
; IF's branch was a nop (condition always true) the ELSE part is skipped up to ENDIF.
;------------------------------------------------------------------------------
compile_else:
	move.l	code_write_pointer,d0           ; d0 = code offset of the jump
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,(sp)                         ; the ELSE entry replaces the return address
	move.w	#$4,-(sp)                       ; type 4: ELSE
	move.w	#$8049,(a4)+                    ; $8049: IR jump to ENDIF
	move.l	#$f0f0f0f,(a4)+                 ; placeholder target
	addq.l	#6,d0                           ; the IF's false branch goes after this jump
	lea	2(sp),a2                        ; a2 = entries below the ELSE entry
.find_if_entry:
	addq.l	#4,a2                           ; skip an entry's offset
	cmpi.w	#$1,(a2)+                       ; find the IF entry (type 1)
	bne.s	.find_if_entry                  ; until the IF entry
	movea.l	code_buffer_start,a0            ; a0 = the IF's branch
	adda.l	(a2)+,a0                        ; + the branch offset
	cmpi.w	#$4e71,(a0)                     ; IF branch was a nop: the ELSE part is dead
	beq.s	.if_always_true                 ; the IF branch is a nop
.patch_if:
	bsr.s	patch_jump_target               ; patch the IF's branch to after the jump
	bra.w	generate_statement_code         ; compile the jump
.restore_and_patch:
	movem.l	(sp)+,d0/a0                     ; d0 / a0 back
	bra.s	.patch_if                       ; patch and compile
.if_always_true:
	movem.l	d0/a0,-(sp)                     ; keep d0 / a0
.skip_else_part:
	bsr.w	skip_dead_lines                 ; skip the next dead line
	cmpi.w	#$3f,d1                         ; 63: stopped at a label
	bne.s	.else_line_skipped              ; no label
	move.w	d6,source_line_number           ; restore the line number and compile on
	bra.s	.restore_and_patch              ; label: compile from there
.else_line_skipped:
	move.l	a0,next_line_pointer            ; compiling resumes at the line found
	cmpi.w	#$9,d1                          ; 9: ENDIF
	bne.s	.skip_else_part                 ; not ENDIF: skip on
	adda.w	#$e,sp                          ; drop d0/a0 and the ELSE entry
	bra.w	next_statement                  ; the ENDIF line compiles next

;------------------------------------------------------------------------------
; Puts the target offset d0 into the jump at a0: at 2(a0) for jmp abs.l ($4ef9), at 4(a0) for the conditional
; form, nothing for a nop.
;------------------------------------------------------------------------------
patch_jump_target:
	cmpi.w	#$4e71,(a0)                     ; nop?
	beq.s	.no_patch                       ; nop: nothing to patch
	cmpi.w	#$4ef9,(a0)                     ; $4ef9: jmp abs.l
	beq.s	.patch_absolute                 ; jmp abs.l?
	move.l	d0,4(a0)                        ; conditional: Bcc then jmp, the long at 4
	rts                                     ; rts
.patch_absolute:
	move.l	d0,2(a0)                        ; jmp: the long at 2
.no_patch:
	rts                                     ; rts

;------------------------------------------------------------------------------
; ELSE IF: pushes type 3 with an IR $8049 jump (to ENDIF), patches the previous branch to here, then parses the
; new condition with IR $80bd and stores its branch offset in the IF entry.
;------------------------------------------------------------------------------
compile_else_if:
	move.l	code_write_pointer,d0           ; d0 = code offset of the jump
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,(sp)                         ; the ELSE IF entry replaces the return address
	move.w	#$3,-(sp)                       ; type 3: ELSE IF
	move.w	#$8049,(a4)+                    ; $8049: IR jump to ENDIF
	move.l	#$f0f0f0f,(a4)+                 ; placeholder target
	addq.l	#6,d0                           ; the previous branch goes after this jump
	lea	2(sp),a2                        ; a2 = entries below
.find_if_entry:
	addq.l	#4,a2                           ; skip an entry's offset
	cmpi.w	#$1,(a2)+                       ; find the IF entry (type 1)
	bne.s	.find_if_entry                  ; until the IF entry
	movea.l	(a2),a0                         ; a0 = the IF's or last ELSE IF's branch
	adda.l	code_buffer_start,a0            ; + code buffer base
	bsr.s	patch_jump_target               ; patch it to here
	pea	(a2)                            ; keep the IF entry's offset address
	bsr.w	parse_expression                ; the new condition
	move.w	#$80bd,(a4)+                    ; $80bd: IR branch when false
	move.l	#$f0f0f0f,(a4)+                 ; placeholder target
	bsr.w	optimise_and_generate           ; optimise and generate
	cmpa.l	#statement_code_buffer_plus_6,a1 ; only the jump: always false
	bne.s	.else_if_condition              ; real code
	bsr.w	copy_code_to_output             ; copy it
	movea.l	(sp)+,a2                        ; pops a2 here and again at .store_branch_offset
	moveq	#-6,d0                          ; offset of the 6-byte jump
	bra.s	.store_branch_offset            ; store it
.else_if_condition:
	cmpi.w	#$4e71,-$2(a1)                  ; nop: always true
	bne.s	.else_if_branch                 ; a real branch
	bsr.w	copy_code_to_output             ; copy it
	moveq	#-2,d0                          ; offset of the nop
	bra.s	.store_branch_offset            ; store it
.else_if_branch:
	bsr.w	copy_code_to_output             ; copy it
	moveq	#-8,d0                          ; offset of the 8-byte branch
.store_branch_offset:
	movea.l	(sp)+,a2                        ; a2 = the IF entry's offset
	add.l	code_write_pointer,d0           ; d0 = code offset of the branch
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,(a2)                         ; the IF entry now holds this branch
	bra.w	next_statement                  ; next line

;------------------------------------------------------------------------------
; ENDIF: patches every jump of the IF / ELSE IF / ELSE entries down to the IF to the current code offset.
;------------------------------------------------------------------------------
compile_endif:
	move.l	code_write_pointer,d0           ; d0 = code offset after the IF
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	addq.l	#4,sp                           ; drop the return address
	cmpi.w	#$4,(sp)                        ; top entry ELSE?
	seq	d7                              ; d7 = $ff: an ELSE was met
.patch_if_chain:
	cmpi.w	#$1,(sp)+                       ; type 1?
	movea.l	code_buffer_start,a0            ; a0 = the entry's jump
	adda.l	(sp)+,a0                        ; + the entry's offset
	beq.s	.chain_done                     ; type 1 (IF) ends the chain
	bsr.w	patch_jump_target               ; patch an ELSE / ELSE IF jump
	bra.s	.patch_if_chain                 ; next entry
.chain_done:
	tst.b	d7                              ; ELSE met: the IF's branch was patched at ELSE
	bmi.w	next_statement                  ; next line
	bsr.w	patch_jump_target               ; patch the IF's branch
	bra.w	next_statement                  ; next line

;------------------------------------------------------------------------------
; WHILE: pushes the line's condition pointer (a5), the offset of an IR $8049 jump to the test and type 2. The
; test is compiled at WEND.
;------------------------------------------------------------------------------
compile_while:
	move.l	code_write_pointer,d0           ; d0 = code offset of the jump
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	movea.l	(sp)+,a0                        ; a0 = return address
	move.l	a5,-(sp)                        ; condition tokens for WEND
	move.l	d0,-(sp)                        ; offset of the jump
	move.w	#$2,-(sp)                       ; type 2: WHILE
	move.w	#$8049,(a4)+                    ; $8049: IR jump to the test
	move.l	#$f0f0f0f,(a4)+                 ; placeholder target
	jmp	(a0)                            ; return

;------------------------------------------------------------------------------
; WEND: patches the WHILE's jump to here, parses the WHILE condition again from the saved a5 with IR $80be (branch
; when true) back to the loop body (WHILE offset + 6) and patches pending exits.
;------------------------------------------------------------------------------
compile_wend:
	movea.l	sp,a0                           ; a0 walks the entries
.find_while_entry:
	addq.l	#4,a0                           ; skip an entry's offset
	cmpi.w	#$2,(a0)+                       ; find the WHILE entry (type 2)
	bne.s	.find_while_entry               ; until the WHILE entry
	movem.l	(a0),a0/a5                      ; a0 = jump offset, a5 = the condition tokens
	pea	(a0)                            ; keep the jump offset
	adda.l	code_buffer_start,a0            ; a0 = the jump
	move.l	code_write_pointer,d0           ; d0 = offset of the test here
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	bsr.w	patch_jump_target               ; patch the jump to the test
	bsr.w	parse_expression                ; parse the condition again
	move.w	#$80be,(a4)+                    ; $80be: IR branch when true back to the body
	move.l	(sp)+,(a4)                      ; target: the jump offset
	addq.l	#6,(a4)+                        ; body starts after the 6-byte jump
	bsr.w	optimise_generate_and_append    ; generate and append the branch
.patch_wend_exits:
	addq.l	#4,sp                           ; drop the return address / patched offset
	tst.w	(sp)+                           ; pending exit?
	bpl.s	.while_dropped                  ; not an exit: the WHILE entry
	movea.l	(sp),a0                         ; a0 = the exit's code
	adda.l	code_buffer_start,a0            ; + code buffer base
	move.l	code_write_pointer,d0           ; d0 = code offset after the loop
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	bsr.w	patch_jump_target               ; patch the exit to after the loop
	bra.s	.patch_wend_exits               ; next entry
.while_dropped:
	addq.l	#8,sp                           ; drop offset and condition pointer
	bra.w	next_statement                  ; next line

;------------------------------------------------------------------------------
; EXIT IF: condition with IR $80be and a placeholder target; the branch is inserted as a pending exit
; (type | $8000) under the entries of the enclosing IF / ELSE IF / ELSE (and the SELECT entries, $4d 6 bytes,
; $4e 10 bytes) so the loop's end patches it. The return address is dropped: it ends with next_statement.
;------------------------------------------------------------------------------
compile_exit_if:
	bsr.w	parse_expression                ; parse the condition
	move.w	#$80be,(a4)+                    ; $80be: IR branch when true
	move.l	#$f0f0f0f,(a4)+                 ; placeholder target
	bsr.w	optimise_and_generate           ; optimise and generate
	moveq	#8,d5                           ; d5 = 8: the branch form
	cmpa.l	#statement_code_buffer_plus_6,a1 ; only the jump?
	bne.s	.exit_branch_made               ; a real branch
	moveq	#6,d5                           ; d5 = 6: just the jmp
.exit_branch_made:
	bsr.w	append_line_code                ; append the code
	move.l	code_write_pointer,d0           ; d0 = offset of the branch
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	sub.l	d5,d0                           ; d0 = offset of the branch's start
	subq.l	#2,sp                           ; 2 bytes + the return address: a 6-byte slot
	lea	6(sp),a0                        ; a0 = first entry
.find_enclosing_loop:
	move.w	(a0),d1                         ; d1 = entry type
	cmpi.w	#$1,d1                          ; IF, ELSE, ELSE IF entries
	beq.s	.skip_if_entry
	cmpi.w	#$4,d1                          ; 4: ELSE
	beq.s	.skip_if_entry
	cmpi.w	#$3,d1                          ; 3: ELSE IF
	beq.s	.skip_if_entry
	cmpi.w	#$4d,d1                         ; $4d: SELECT entry (6 bytes)
	beq.s	.skip_if_entry
	cmpi.w	#$4e,d1                         ; $4e: SELECT entry (10 bytes)
	beq.s	.skip_select_entry
	ori.w	#$8000,d1                       ; pending exit of that loop
	move.l	d0,-(a0)                        ; insert the exit in the slot
	move.w	d1,-(a0)                        ; its type with bit 15
	bra.w	next_statement                  ; next line
.skip_if_entry:
	move.w	(a0),-$6(a0)                    ; move the entry up into the slot
	move.l	2(a0),-$4(a0)                   ; and its offset
	addq.l	#6,a0                           ; next entry
	bra.s	.find_enclosing_loop
.skip_select_entry:
	move.w	(a0),-$6(a0)                    ; move the 10-byte entry up
	move.l	2(a0),-$4(a0)                   ; and its offset
	move.l	6(a0),(a0)                      ; its extra long
	adda.w	#$a,a0                          ; next entry
	bra.s	.find_enclosing_loop

compile_for_int_downto:
	moveq	#-1,d0                          ; -1: DOWNTO
	bra.s	compile_for_int

compile_for_int_to:
	moveq	#1,d0                           ; +1: TO

;------------------------------------------------------------------------------
; FOR i% = start TO/DOWNTO end (d0 = +1 / -1): compiles i% = start (stmt_let_int, IR $8042 store), then the end
; as an integer expression. With both constant (IR $8007 constant) and the loop never running, the body is
; skipped; with a constant end the entry is type 10; otherwise library routine $5d FORI1 keeps the end on the a3
; stack (type 11).
;------------------------------------------------------------------------------
compile_for_int:
	move.l	d0,-(sp)                        ; keep the direction
	bsr.w	stmt_let_int                    ; i% = start (IR $8042)
	bsr.w	optimise_ir                     ; optimise the start assignment
	move.l	a4,-(sp)                        ; IR position of the end
	bsr.w	parse_integer_expression        ; end value
	bsr.w	optimise_ir
	movea.l	(sp)+,a0                        ; a0 = the end's IR
	cmpi.w	#$8007,(a0)+                    ; $8007: integer constant
	bne.w	for_int_variable_end
	move.l	(a0)+,d0                        ; d0 = constant end
	cmpa.l	a4,a0                           ; nothing else in the end's IR?
	bne.w	for_int_variable_end
	subq.l	#6,a4                           ; drop the constant from the IR
	lea	ir_buffer,a0                    ; a0 = the start assignment's IR
	cmpi.w	#$8007,(a0)+                    ; start constant?
	bne.s	.start_not_constant
	move.l	(a0)+,d1                        ; d1 = start
	cmpi.w	#$8042,(a0)+                    ; start constant stored to the variable?
	bne.s	.start_not_constant
	move.l	d0,d2                           ; d2 = end
	tst.w	(sp)                            ; DOWNTO?
	bpl.s	.compare_bounds                 ; TO: compare as it is
	exg	d1,d2                           ; DOWNTO: compare the other way
.compare_bounds:
	cmp.l	d2,d1                           ; start beyond the end?
	bgt.s	.loop_never_runs                ; start beyond end: the loop never runs
	addq.l	#4,sp                           ; drop the direction
	move.l	d0,(sp)                         ; the end replaces the return address
	clr.w	(a4)                            ; end of the IR
	bsr.w	generate_and_append             ; generate and copy i% = start
	move.l	code_write_pointer,d0           ; the body starts here
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,-(sp)                        ; push the body offset
	move.w	#$a,-(sp)                       ; type 10: constant end
	bra.w	next_statement
.loop_never_runs:
	bsr.w	skip_dead_lines                 ; skip the body up to the NEXT
	adda.w	d0,a0                           ; compiling resumes after the NEXT
	move.l	a0,next_line_pointer
	suba.w	d0,a0                           ; a0 = the NEXT line again
	addq.l	#8,sp                           ; drop direction and return address
	bra.w	next_statement
.start_not_constant:
	moveq	#10,d7                          ; type 10: constant end
	addq.l	#4,sp                           ; drop the direction
	move.l	d0,(sp)                         ; the end replaces the return address

;------------------------------------------------------------------------------
; Common end of a FOR header (d7 = entry type): generates the code, pushes (code offset, type) and an IR $8049 jump
; to the loop test at NEXT, kept as an entry with type | $80; the loop body starts after it.
;------------------------------------------------------------------------------
finish_for_header:
	move.w	d7,-(sp)                        ; keep the type
	clr.w	(a4)                            ; end of the IR
	bsr.w	generate_and_append             ; generate and copy the header code
	move.l	code_write_pointer,d0           ; offset of the jump to come
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.w	(sp)+,d7                        ; restore the type
	move.l	d0,-(sp)                        ; push the FOR entry: offset, type
	move.w	d7,-(sp)
	lea	ir_buffer,a4                    ; new IR for the jump
	move.w	#$8049,(a4)+                    ; $8049: IR jump to the test at NEXT
	move.l	#$f0f0f0f,(a4)+
	clr.w	(a4)                            ; end of the IR
	bsr.w	generate_code                   ; generate the jump, copied below
	move.l	2(sp),-(sp)                     ; copy of the jump's offset
	move.l	a1,d0                           ; d0 = size of the jump code
	subi.l	#statement_code_buffer,d0       ; minus the buffer start
	add.l	d0,6(sp)                        ; the FOR entry's offset moves after the jump
	move.w	4(sp),d0                        ; d0 = type
	ori.b	#$80,d0                         ; bit 7: the jump to the test
	move.w	d0,-(sp)                        ; push the jump entry
	bra.w	copy_statement_code             ; copy the jump

for_int_variable_end:
	move.w	#$5d,(a4)+                      ; IR: library routine $5d FORI1 (end on the a3 stack)
	moveq	#11,d7                          ; type 11: end on the a3 stack
	addq.l	#8,sp                           ; drop direction and return address
	bra.s	finish_for_header

compile_next_int_to:
	moveq	#1,d0                           ; +1: TO
	move.w	#$80d1,(a4)+                    ; $80d1: IR i% + 1
	bra.s	compile_next_int

compile_next_int_downto:
	moveq	#-1,d0                          ; -1: DOWNTO
	move.w	#$80d5,(a4)+                    ; $80d5: IR i% - 1

;------------------------------------------------------------------------------
; NEXT i% (TO: IR $80d1, DOWNTO: $80d5, variable index follows). With option N+ an IR $8208 check is added and its
; jump kept as an exit. Patches the FOR's jump to the test, then compares i% ($803f) with the end (constant
; $8008 or the a3-stack value $80e8), branches back ($80c0 + offset) with $807d (down) or $807f (up), patches
; exits and, for type 11, removes the end value from the a3 stack (subq.l #6,a3).
;------------------------------------------------------------------------------
compile_next_int:
	move.w	(a5),(a4)+                      ; variable index
	move.l	d0,-(sp)                        ; keep the direction
	move.b	option_n_flag(pc),d1            ; option N+?
	beq.s	.no_n_option
	move.w	#$8208,(a4)+                    ; $8208: IR check (option N+)
	bsr.w	optimise_generate_and_append    ; generate and copy the step and check
	movem.l	(sp)+,d0-d1                     ; d0 = direction, d1 = return address
	move.l	code_write_pointer,d2           ; d2 = offset of the check's branch
	sub.l	code_buffer_start,d2
	subq.l	#8,d2                           ; back to the check's 8-byte branch
	move.w	(sp),d3                         ; d3 = type of the top entry
	move.l	d2,-(sp)                        ; push the check as a pending exit
	ori.w	#$8000,d3                       ; bit 15: pending exit
	move.w	d3,-(sp)
	movem.l	d0-d1,-(sp)                     ; direction and return address back
	bra.s	.find_for_entry
.no_n_option:
	bsr.w	optimise_generate_and_append    ; generate and copy the step
.find_for_entry:
	lea	ir_buffer,a4                    ; new IR for the test
	lea	8(sp),a0                        ; a0 = entries past direction and return address
.skip_exit_entries:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.skip_exit_entries              ; pending exit: skip it
	tst.b	d7                              ; bit 7: the FOR's jump to the test?
	bpl.s	.compare_with_end
	pea	(a0)                            ; keep a0
	movea.l	-$4(a0),a0                      ; a0 = the jump's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = offset of the test here
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; patch the jump to the test
	movea.l	(sp)+,a0                        ; a0 back to the entry
	move.w	(a0)+,d7                        ; d7 = the FOR entry's type
	addq.l	#4,a0                           ; a0 = after its offset
.compare_with_end:
	move.l	(sp)+,d0                        ; d0 = direction
	move.w	#$803f,(a4)+                    ; $803f: IR load int variable
	move.w	(a5),(a4)+                      ; variable index
	cmpi.w	#$b,d7                          ; type 11: end on the a3 stack
	bne.s	.constant_end
	move.w	#$80e8,(a4)+                    ; $80e8: compare with the end on the a3 stack
	bra.s	.choose_condition
.constant_end:
	move.w	#$8008,(a4)+                    ; $8008: compare with a constant
	move.l	(a0),(a4)+                      ; the end constant
.choose_condition:
	tst.l	d0                              ; DOWNTO?
	bpl.s	.count_up
	move.w	#$807d,(a4)+                    ; $807d: condition for DOWNTO
	bra.s	.branch_back
.count_up:
	move.w	#$807f,(a4)+                    ; $807f: condition for TO
.branch_back:
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	move.l	-(a0),(a4)+                     ; target: the loop body offset
	bsr.w	optimise_generate_and_append    ; generate and append the test
.patch_exits:
	addq.l	#4,sp                           ; drop the return address / patched offset
	move.w	(sp)+,d7                        ; d7 = entry type
	bpl.s	.exits_patched                  ; not a pending exit: done
	movea.l	(sp),a0                         ; a0 = the exit's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = code offset after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target
	bra.s	.patch_exits
.exits_patched:
	tst.b	d7                              ; the FOR's jump entry?
	bpl.s	.drop_for_entry
	addq.l	#4,sp                           ; drop its offset
	move.w	(sp)+,d7                        ; d7 = the FOR entry's type
.drop_for_entry:
	cmpi.w	#$b,d7                          ; type 11 keeps its end on the a3 stack
	beq.s	.pop_end_value
	addq.l	#8,sp                           ; drop offset and end
	bra.w	next_statement
.pop_end_value:
	addq.l	#4,sp                           ; drop the offset
	lea	statement_code_buffer,a1        ; a1 = statement code
	move.w	#$5d8b,(a1)+                    ; $5d8b: subq.l #6,a3 (drop the end value)
	bsr.w	copy_code_to_output             ; copy the subq
	bra.w	next_statement

;------------------------------------------------------------------------------
; FOR i% = a TO b STEP c: like compile_for_int with a step. Types: 12 = end and step constant, 13 = end variable
; (FORI1), step constant, 14 = both variable (IR $8017/$801b, routine $1ad FORI2), 15 = end constant, step variable
; (FORI1).
;------------------------------------------------------------------------------
compile_for_int_step:
	bsr.w	stmt_let_int                    ; i% = start
	bsr.w	optimise_ir                     ; optimise the start assignment
	move.l	a4,(sp)                         ; IR position of the end (over the return address)
	bsr.w	parse_integer_expression        ; the end
	bsr.w	optimise_ir
	movea.l	(sp)+,a0
	cmpi.w	#$8007,(a0)+
	bne.w	.step_end_variable
	move.l	(a0)+,d0                        ; d0 = constant end
	cmpa.l	a4,a0                           ; nothing else in the end's IR?
	bne.s	.step_end_variable
	subq.l	#6,a4                           ; drop the constant
	move.l	d0,-(sp)                        ; push the end
	move.l	a4,-(sp)                        ; IR position of the step
	bsr.w	parse_integer_expression        ; the step
	bsr.w	optimise_ir
	movea.l	(sp)+,a0
	cmpi.w	#$8007,(a0)+
	bne.w	.end_constant_step_variable
	move.l	(a0)+,d0                        ; d0 = constant step
	cmpa.l	a4,a0                           ; nothing else in the step's IR?
	bne.w	.end_constant_step_variable
	subq.l	#6,a4                           ; drop the constant
	move.l	d0,-(sp)                        ; push the step
	lea	ir_buffer,a0
	cmpi.w	#$8007,(a0)+                    ; start constant?
	bne.s	.step_start_not_constant
	move.l	(a0)+,d1                        ; d1 = start
	cmpi.w	#$8042,(a0)+                    ; stored to i%?
	bne.s	.step_start_not_constant
	move.l	4(sp),d2                        ; d2 = end
	tst.w	(sp)                            ; negative step?
	bpl.s	.compare_step_bounds            ; positive step: compare as it is
	exg	d1,d2                           ; counting down: compare the other way
.compare_step_bounds:
	cmp.l	d2,d1                           ; start beyond the end?
	bgt.s	.step_loop_never_runs           ; start beyond end: the loop never runs
	clr.w	(a4)                            ; end of the IR
	bsr.w	generate_and_append             ; generate and copy i% = start
	move.l	code_write_pointer,d0           ; the body starts here
	sub.l	code_buffer_start,d0            ; relative to the code buffer
	move.l	d0,-(sp)                        ; push the body offset
	move.w	#$c,-(sp)                       ; type 12: end and step constant
	bra.w	next_statement
.step_loop_never_runs:
	bsr.w	skip_dead_lines                 ; skip the body up to the NEXT
	adda.w	d0,a0                           ; compiling resumes after the NEXT
	move.l	a0,next_line_pointer
	suba.w	d0,a0                           ; a0 = the NEXT line again
	addq.l	#8,sp                           ; drop step and end
	bra.w	next_statement
.step_start_not_constant:
	moveq	#12,d7                          ; type 12: end and step constant
	bra.w	finish_for_header
.step_end_variable:
	move.w	#$7fff,(a4)+                    ; placeholder; becomes $8017 for a variable step
	pea	(a4)                            ; IR position of the step
	bsr.w	parse_integer_expression        ; the step
	bsr.w	optimise_ir
	movea.l	(sp)+,a0
	cmpi.w	#$8007,(a0)+
	bne.s	.step_variable
	move.l	(a0)+,d0                        ; d0 = constant step
	cmpa.l	a4,a0                           ; nothing else in the step's IR?
	bne.s	.step_not_constant
	subq.l	#8,a4                           ; drop the constant and the placeholder
	move.l	d0,-(sp)                        ; push the step
	move.w	#$5d,(a4)+                      ; IR: $5d FORI1
	moveq	#13,d7                          ; type 13: end variable, step constant
	bra.w	finish_for_header
.step_not_constant:
	subq.l	#4,a0                           ; a0 back to after the $8007 word
.step_variable:
	move.w	#$8017,-$4(a0)                  ; $8017 push long: the end
	move.w	#$801b,(a4)+                    ; $801b pop into d1: the step
	move.w	#$1ad,(a4)+                     ; IR: $1ad FORI2
	bsr.w	optimise_ir
	moveq	#14,d7                          ; type 14: end and step on the a3 stack
	bra.w	finish_for_header
.end_constant_step_variable:
	move.w	#$5d,(a4)+                      ; IR: $5d FORI1 (the step variable)
	moveq	#15,d7                          ; type 15: end constant, step variable
	bra.w	finish_for_header

;------------------------------------------------------------------------------
; NEXT i% of a FOR ... STEP: adds the step ($8007 constant or $80fb/$80fc from the a3 stack, IR $80dc add), then the
; same test as compile_next_int ($8084/$8009/$80fd/$80fe for a variable step); removes 6 or 10 bytes from the a3
; stack at the end.
;------------------------------------------------------------------------------
compile_next_int_step:
	lea	4(sp),a0                        ; a0 = entries past the return address
.find_step_entry:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.find_step_entry                ; skip pending exits
	tst.b	d7                              ; bit 7: the FOR's jump entry
	bmi.s	.find_step_entry                ; skip the FOR's jump entry
	cmpi.w	#$c,d7                          ; 12 / 13: constant step in the entry
	beq.s	.constant_step
	cmpi.w	#$d,d7                          ; 13: end variable, step constant
	beq.s	.constant_step
	move.w	#$80fb,d0                       ; $80fb / $80fc: step from the a3 stack
	cmpi.w	#$e,d7                          ; type 14: end and step on the a3 stack
	bne.s	.store_step_code
	move.w	#$80fc,d0                       ; type 14: $80fc
.store_step_code:
	move.w	d0,(a4)+                        ; IR: the step operand
	bra.s	.add_step
.constant_step:
	move.w	#$8007,(a4)+                    ; $8007: constant step
	move.l	(a0)+,(a4)+                     ; the step
.add_step:
	move.w	#$80dc,(a4)+                    ; $80dc: IR add step to i%
	move.w	(a5),(a4)+                      ; variable index
	move.b	option_n_flag(pc),d1            ; option N+?
	beq.s	.no_n_option
	move.w	#$8208,(a4)+                    ; $8208: IR check (option N+)
	bsr.w	optimise_generate_and_append    ; generate and copy the step and check
	move.l	(sp)+,d0                        ; d0 = return address
	move.l	code_write_pointer,d2           ; d2 = offset of the check's branch
	sub.l	code_buffer_start,d2
	subq.l	#8,d2                           ; back to the check's 8-byte branch
	move.w	(sp),d3                         ; d3 = type of the top entry
	move.l	d2,-(sp)                        ; push the check as a pending exit
	ori.w	#$8000,d3                       ; bit 15: pending exit
	move.w	d3,-(sp)
	move.l	d0,-(sp)                        ; return address back
	bra.s	.find_for_entry
.no_n_option:
	bsr.w	optimise_generate_and_append    ; generate and copy the step
.find_for_entry:
	lea	ir_buffer,a4                    ; new IR for the test
	lea	4(sp),a0                        ; a0 = entries past the return address
.skip_exit_entries:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.skip_exit_entries              ; pending exit: skip it
	tst.b	d7                              ; bit 7: the FOR's jump to the test?
	bpl.s	.compare_with_end
	pea	(a0)                            ; keep a0
	movea.l	-$4(a0),a0                      ; a0 = the jump's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = offset of the test here
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; patch the jump to the test
	movea.l	(sp)+,a0                        ; a0 back to the entry
	move.w	(a0)+,d7                        ; d7 = the FOR entry's type
	addq.l	#4,a0                           ; a0 = after its offset
.compare_with_end:
	move.l	(a0)+,d0                        ; d0 = step (types 12/13), for the direction
	move.w	#$803f,(a4)+                    ; $803f: IR load int variable
	move.w	(a5),(a4)+                      ; variable index
	cmpi.w	#$c,d7                          ; type 12: constant end
	beq.s	.constant_end
	cmpi.w	#$d,d7                          ; type 13: end on the a3 stack
	bne.s	.variable_step
	move.w	#$80e8,(a4)+                    ; $80e8: compare with the end on the a3 stack
	bra.s	.choose_condition
.variable_step:
	move.w	#$8084,-$4(a4)                  ; $8084 replaces $803f: variable step form
	cmpi.w	#$e,d7                          ; type 14: end on the a3 stack
	beq.s	.step_on_stack
	move.w	#$8009,(a4)+                    ; $8009: compare with the constant end
	move.l	-$4(a0),(a4)+                   ; the end (type 15)
	bra.s	.step_compare
.step_on_stack:
	move.w	#$80fd,(a4)+                    ; $80fd: end from the a3 stack
.step_compare:
	move.w	#$80fe,(a4)+                    ; $80fe: ends the variable-step test (exact meaning unknown)
	bra.s	.branch_back
.constant_end:
	move.w	#$8008,(a4)+                    ; $8008: compare with a constant
	move.l	(a0),(a4)+                      ; the end constant
.choose_condition:
	tst.l	d0                              ; negative step?
	bpl.s	.count_up
	move.w	#$807d,(a4)+                    ; $807d: condition for a negative step
	bra.s	.branch_back
.count_up:
	move.w	#$807f,(a4)+                    ; $807f: condition for a positive step
.branch_back:
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	move.l	-$8(a0),(a4)+                   ; target: the loop body offset
	bsr.w	optimise_generate_and_append    ; generate and append the test
.patch_exits:
	addq.l	#4,sp                           ; drop the return address / patched offset
	move.w	(sp)+,d7                        ; d7 = entry type
	bpl.s	.exits_patched                  ; not a pending exit: done
	movea.l	(sp),a0                         ; a0 = the exit's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = code offset after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target
	bra.s	.patch_exits
.exits_patched:
	tst.b	d7                              ; the FOR's jump entry?
	bpl.s	.drop_for_entry
	addq.l	#4,sp                           ; drop its offset
	move.w	(sp)+,d7                        ; d7 = the FOR entry's type
.drop_for_entry:
	cmpi.w	#$c,d7                          ; type 12: nothing on the a3 stack
	bne.s	.pop_stack_values
	lea	$c(sp),sp                       ; drop offset, step and end
	bra.w	next_statement
.pop_stack_values:
	cmpi.w	#$e,d7                          ; type 14: end and step on the a3 stack
	beq.s	.pop_end_and_step
	addq.l	#8,sp                           ; drop offset and the constant
	lea	statement_code_buffer,a1        ; a1 = statement code
	move.w	#$5d8b,(a1)+                    ; $5d8b: subq.l #6,a3
.copy_pop_code:
	bsr.w	copy_code_to_output
	bra.w	next_statement
.pop_end_and_step:
	addq.l	#4,sp                           ; drop the offset
	lea	statement_code_buffer,a1        ; a1 = statement code
	move.w	#$47eb,(a1)+                    ; $47eb $fff6: lea -10(a3),a3
	move.w	#$fff6,(a1)+                    ; displacement -10
	bra.s	.copy_pop_code

compile_for_word_downto:
	moveq	#-1,d0                          ; -1: DOWNTO
	bra.s	compile_for_word

compile_for_word_to:
	moveq	#1,d0                           ; +1: TO

;------------------------------------------------------------------------------
; FOR i& (word variable): as compile_for_int with stmt_let_word (IR $8043 store), routine $1ae FORW1 / $1af FORW2.
;------------------------------------------------------------------------------
compile_for_word:
	move.l	d0,-(sp)                        ; keep the direction
	bsr.w	stmt_let_word                   ; i& = start (IR $8043)
	bsr.w	optimise_ir                     ; optimise the start assignment
	move.l	a4,-(sp)                        ; IR position of the end
	bsr.w	parse_integer_expression        ; end value
	bsr.w	optimise_ir
	movea.l	(sp)+,a0                        ; a0 = the end's IR
	cmpi.w	#$8007,(a0)+                    ; $8007: integer constant
	bne.s	.word_end_variable
	move.l	(a0)+,d0                        ; d0 = constant end
	cmpa.l	a4,a0                           ; nothing else in the end's IR?
	bne.s	.word_end_variable
	subq.l	#6,a4                           ; drop the constant from the IR
	lea	ir_buffer,a0                    ; a0 = the start assignment's IR
	cmpi.w	#$8007,(a0)+                    ; start constant?
	bne.s	.word_start_not_constant
	move.l	(a0)+,d1                        ; d1 = start
	cmpi.w	#$8043,(a0)+                    ; $8043: IR store word variable
	bne.s	.word_start_not_constant
	move.l	d0,d2                           ; d2 = end
	tst.w	(sp)                            ; DOWNTO?
	bpl.s	.compare_word_bounds            ; TO: compare as it is
	exg	d1,d2                           ; DOWNTO: compare the other way
.compare_word_bounds:
	cmp.l	d2,d1                           ; start beyond the end?
	bgt.s	.word_loop_never_runs           ; start beyond end: the loop never runs
	addq.l	#4,sp                           ; drop the direction
	move.l	d0,(sp)                         ; the end replaces the return address
	clr.w	(a4)                            ; end of the IR
	bsr.w	generate_and_append             ; generate and copy i& = start
	move.l	code_write_pointer,d0           ; the body starts here
	sub.l	code_buffer_start,d0
	move.l	d0,-(sp)
	move.w	#$a,-(sp)                       ; type 10: constant end
	bra.w	next_statement
.word_loop_never_runs:
	bsr.w	skip_dead_lines                 ; skip the body up to the NEXT
	adda.w	d0,a0                           ; compiling resumes after the NEXT
	move.l	a0,next_line_pointer
	suba.w	d0,a0                           ; a0 = the NEXT line again
	addq.l	#8,sp                           ; drop direction and return address
	bra.w	next_statement
.word_start_not_constant:
	moveq	#10,d7                          ; type 10: constant end
	addq.l	#4,sp                           ; drop the direction
	move.l	d0,(sp)                         ; the end replaces the return address
	bra.w	finish_for_header
.word_end_variable:
	move.w	#$1ae,(a4)+                     ; IR: $1ae FORW1 (end on the a3 stack)
	moveq	#11,d7                          ; type 11: end on the a3 stack
	addq.l	#8,sp                           ; drop direction and return address
	bra.w	finish_for_header

compile_next_word_to:
	moveq	#1,d0                           ; +1: TO
	move.w	#$80d2,(a4)+                    ; $80d2: IR i& + 1
	bra.s	compile_next_word

compile_next_word_downto:
	moveq	#-1,d0                          ; -1: DOWNTO
	move.w	#$80d6,(a4)+                    ; $80d6: IR i& - 1

;------------------------------------------------------------------------------
; NEXT i& (TO $80d2 / DOWNTO $80d6): as compile_next_int with IR $8040 load, $811c/$811d/$811e.
;------------------------------------------------------------------------------
compile_next_word:
	move.w	(a5),(a4)+                      ; variable index
	move.l	d0,-(sp)                        ; keep the direction
	move.b	option_n_flag(pc),d1            ; option N+?
	beq.s	.word_no_n_option
	move.w	#$8208,(a4)+                    ; $8208: IR check (option N+)
	bsr.w	optimise_generate_and_append    ; generate and copy the step and check
	movem.l	(sp)+,d0-d1                     ; d0 = direction, d1 = return address
	move.l	code_write_pointer,d2           ; d2 = offset of the check's branch
	sub.l	code_buffer_start,d2
	subq.l	#8,d2                           ; back to the check's 8-byte branch
	move.w	(sp),d3                         ; d3 = type of the top entry
	move.l	d2,-(sp)                        ; push the check as a pending exit
	ori.w	#$8000,d3                       ; bit 15: pending exit
	move.w	d3,-(sp)
	movem.l	d0-d1,-(sp)                     ; direction and return address back
	bra.s	.find_word_for_entry
.word_no_n_option:
	bsr.w	optimise_generate_and_append    ; generate and copy the step
.find_word_for_entry:
	lea	ir_buffer,a4                    ; new IR for the test
	lea	8(sp),a0                        ; a0 = entries past direction and return address
.skip_word_exit_entries:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.skip_word_exit_entries         ; pending exit: skip it
	tst.b	d7                              ; bit 7: the FOR's jump to the test?
	bpl.s	.compare_word_with_end
	pea	(a0)                            ; keep a0
	movea.l	-$4(a0),a0                      ; a0 = the jump's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = offset of the test here
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; patch the jump to the test
	movea.l	(sp)+,a0                        ; a0 back to the entry
	move.w	(a0)+,d7                        ; d7 = the FOR entry's type
	addq.l	#4,a0                           ; a0 = after its offset
.compare_word_with_end:
	move.l	(sp)+,d0                        ; d0 = direction
	move.w	#$8040,(a4)+                    ; $8040: IR load word variable
	move.w	(a5),(a4)+                      ; variable index
	cmpi.w	#$b,d7                          ; type 11: end on the a3 stack
	bne.s	.word_constant_end
	move.w	#$811c,(a4)+                    ; $811c: compare with the end on the a3 stack
	bra.s	.choose_word_condition
.word_constant_end:
	move.w	#$8008,(a4)+                    ; $8008: compare with a constant
	move.l	(a0),(a4)+                      ; the end constant
.choose_word_condition:
	tst.w	d0                              ; DOWNTO?
	bpl.s	.word_count_up
	move.w	#$811d,(a4)+                    ; $811d: condition for DOWNTO
	bra.s	.word_branch_back
.word_count_up:
	move.w	#$811e,(a4)+                    ; $811e: condition for TO
.word_branch_back:
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	move.l	-(a0),(a4)+                     ; target: the loop body offset
	bsr.w	optimise_generate_and_append    ; generate and copy the test
.patch_word_exits:
	addq.l	#4,sp                           ; drop the return address / patched offset
	move.w	(sp)+,d7                        ; d7 = entry type
	bpl.s	.word_exits_patched             ; not a pending exit: done
	movea.l	(sp),a0                         ; a0 = the exit's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = code offset after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target
	bra.s	.patch_word_exits
.word_exits_patched:
	tst.b	d7                              ; the FOR's jump entry?
	bpl.s	.drop_word_for_entry
	addq.l	#4,sp                           ; drop its offset
	move.w	(sp)+,d7                        ; d7 = the FOR entry's type
.drop_word_for_entry:
	cmpi.w	#$b,d7                          ; type 11 keeps its end on the a3 stack
	beq.s	.pop_word_end_value
	addq.l	#8,sp                           ; drop offset and end
	bra.w	next_statement
.pop_word_end_value:
	addq.l	#4,sp                           ; drop the offset
	lea	statement_code_buffer,a1        ; a1 = statement code
	move.w	#$598b,(a1)+                    ; $598b: subq.l #4,a3
	bsr.w	copy_code_to_output             ; copy the subq
	bra.w	next_statement

;------------------------------------------------------------------------------
; FOR i& ... STEP: as compile_for_int_step for a word variable ($8043, FORW1/FORW2).
;------------------------------------------------------------------------------
compile_for_word_step:
	bsr.w	stmt_let_word                   ; i& = start
	bsr.w	optimise_ir                     ; optimise the start assignment
	move.l	a4,(sp)                         ; IR position of the end (over the return address)
	bsr.w	parse_integer_expression        ; the end
	bsr.w	optimise_ir
	movea.l	(sp)+,a0
	cmpi.w	#$8007,(a0)+                    ; $8007: integer constant
	bne.w	.word_step_end_variable
	move.l	(a0)+,d0                        ; d0 = constant end
	cmpa.l	a4,a0                           ; nothing else in the end's IR?
	bne.s	.word_step_end_variable
	subq.l	#6,a4                           ; drop the constant
	move.l	d0,-(sp)                        ; push the end
	move.l	a4,-(sp)                        ; IR position of the step
	bsr.w	parse_integer_expression        ; the step
	bsr.w	optimise_ir
	movea.l	(sp)+,a0
	cmpi.w	#$8007,(a0)+                    ; $8007: integer constant
	bne.w	.word_end_constant_step_variable
	move.l	(a0)+,d0                        ; d0 = constant step
	cmpa.l	a4,a0                           ; nothing else in the step's IR?
	bne.w	.word_end_constant_step_variable
	subq.l	#6,a4                           ; drop the constant
	move.l	d0,-(sp)                        ; push the step
	lea	ir_buffer,a0
	cmpi.w	#$8007,(a0)+                    ; start constant?
	bne.s	.word_step_start_not_constant
	move.l	(a0)+,d1                        ; d1 = start
	cmpi.w	#$8043,(a0)+                    ; $8043: stored to i&?
	bne.s	.word_step_start_not_constant
	move.l	4(sp),d2                        ; d2 = end
	tst.w	(sp)                            ; negative step?
	bpl.s	.compare_word_step_bounds       ; positive step: compare as it is
	exg	d1,d2                           ; counting down: compare the other way
.compare_word_step_bounds:
	cmp.l	d2,d1                           ; start beyond the end?
	bgt.s	.word_step_loop_never_runs      ; start beyond end: the loop never runs
	clr.w	(a4)                            ; end of the IR
	bsr.w	generate_and_append             ; generate and copy i& = start
	move.l	code_write_pointer,d0           ; the body starts here
	sub.l	code_buffer_start,d0
	move.l	d0,-(sp)
	move.w	#$c,-(sp)                       ; type 12: end and step constant
	bra.w	next_statement
.word_step_loop_never_runs:
	bsr.w	skip_dead_lines                 ; skip the body up to the NEXT
	adda.w	d0,a0                           ; compiling resumes after the NEXT
	move.l	a0,next_line_pointer
	suba.w	d0,a0                           ; a0 = the NEXT line again
	addq.l	#8,sp                           ; drop step and end
	bra.w	next_statement
.word_step_start_not_constant:
	moveq	#12,d7                          ; type 12: end and step constant
	bra.w	finish_for_header
.word_step_end_variable:
	move.w	#$7fff,(a4)+                    ; placeholder; becomes $8017 for a variable step
	pea	(a4)                            ; IR position of the step
	bsr.w	parse_integer_expression        ; the step
	bsr.w	optimise_ir
	movea.l	(sp)+,a0
	cmpi.w	#$8007,(a0)+                    ; $8007: integer constant
	bne.s	.word_step_variable
	move.l	(a0)+,d0                        ; d0 = constant step
	cmpa.l	a4,a0                           ; nothing else in the step's IR?
	bne.s	.word_step_not_constant
	subq.l	#8,a4                           ; drop the constant and the placeholder
	move.l	d0,-(sp)                        ; push the step
	move.w	#$1ae,(a4)+                     ; IR: $1ae FORW1
	moveq	#13,d7                          ; type 13: end variable, step constant
	bra.w	finish_for_header
.word_step_not_constant:
	subq.l	#4,a0                           ; a0 back to after the $8007 word
.word_step_variable:
	move.w	#$8017,-$4(a0)                  ; $8017 push long: the end
	move.w	#$801b,(a4)+                    ; $801b pop into d1: the step
	move.w	#$1af,(a4)+                     ; IR: $1af FORW2 (end and step on the a3 stack)
	bsr.w	optimise_ir
	moveq	#14,d7                          ; type 14: end and step on the a3 stack
	bra.w	finish_for_header
.word_end_constant_step_variable:
	move.w	#$1ae,(a4)+                     ; IR: $1ae FORW1 (the step variable)
	moveq	#15,d7                          ; type 15: end constant, step variable
	bra.w	finish_for_header

;------------------------------------------------------------------------------
; NEXT i& of a FOR ... STEP ($811f/$8120 step from the stack, $80e0 add, $808d/$8121/$8122).
;------------------------------------------------------------------------------
compile_next_word_step:
	lea	4(sp),a0                        ; a0 = entries past the return address
.find_word_step_entry:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.find_word_step_entry           ; skip pending exits
	tst.b	d7                              ; bit 7: the FOR's jump entry
	bmi.s	.find_word_step_entry           ; skip the FOR's jump entry
	cmpi.w	#$c,d7                          ; 12 / 13: constant step in the entry
	beq.s	.word_constant_step
	cmpi.w	#$d,d7                          ; 13: end variable, step constant
	beq.s	.word_constant_step
	move.w	#$811f,d0                       ; $811f / $8120: step from the a3 stack
	cmpi.w	#$e,d7                          ; type 14: end and step on the a3 stack
	bne.s	.store_word_step_code
	move.w	#$8120,d0                       ; type 14: $8120
.store_word_step_code:
	move.w	d0,(a4)+                        ; IR: the step operand
	bra.s	.add_word_step
.word_constant_step:
	move.w	#$8007,(a4)+                    ; $8007: constant step
	move.l	(a0)+,(a4)+                     ; the step
.add_word_step:
	move.w	#$80e0,(a4)+                    ; $80e0: IR add step to i&
	move.w	(a5),(a4)+                      ; variable index
	move.b	option_n_flag(pc),d1            ; option N+?
	beq.s	.word_step_no_n_option
	move.w	#$8208,(a4)+                    ; $8208: IR check (option N+)
	bsr.w	optimise_generate_and_append    ; generate and copy the step and check
	move.l	(sp)+,d0                        ; d0 = return address
	move.l	code_write_pointer,d2           ; d2 = offset of the check's branch
	sub.l	code_buffer_start,d2
	subq.l	#8,d2                           ; back to the check's 8-byte branch
	move.w	(sp),d3                         ; d3 = type of the top entry
	move.l	d2,-(sp)                        ; push the check as a pending exit
	ori.w	#$8000,d3                       ; bit 15: pending exit
	move.w	d3,-(sp)
	move.l	d0,-(sp)                        ; return address back
	bra.s	.find_word_step_for_entry
.word_step_no_n_option:
	bsr.w	optimise_generate_and_append    ; generate and copy the step
.find_word_step_for_entry:
	lea	ir_buffer,a4                    ; new IR for the test
	lea	4(sp),a0                        ; a0 = entries past the return address
.skip_word_step_exits:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.skip_word_step_exits           ; pending exit: skip it
	tst.b	d7                              ; bit 7: the FOR's jump to the test?
	bpl.s	.compare_word_step_end
	pea	(a0)                            ; keep a0
	movea.l	-$4(a0),a0                      ; a0 = the jump's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = offset of the test here
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; patch the jump to the test
	movea.l	(sp)+,a0                        ; a0 back to the entry
	move.w	(a0)+,d7                        ; d7 = the FOR entry's type
	addq.l	#4,a0                           ; a0 = after its offset
.compare_word_step_end:
	move.l	(a0)+,d0                        ; d0 = step (types 12/13), for the direction
	move.w	#$8040,(a4)+                    ; $8040: IR load word variable
	move.w	(a5),(a4)+                      ; variable index
	cmpi.w	#$c,d7                          ; type 12: constant end
	beq.s	.word_step_constant_end
	cmpi.w	#$d,d7                          ; type 13: end on the a3 stack
	bne.s	.word_variable_step
	move.w	#$811c,(a4)+                    ; $811c: compare with the end on the a3 stack
	bra.s	.choose_word_step_condition
.word_variable_step:
	move.w	#$808d,-$4(a4)                  ; $808d replaces $8040: variable step form
	cmpi.w	#$e,d7                          ; type 14: end on the a3 stack
	beq.s	.word_step_on_stack
	move.w	#$8009,(a4)+                    ; $8009: compare with the constant end
	move.l	-$4(a0),(a4)+                   ; the end (type 15)
	bra.s	.word_step_compare
.word_step_on_stack:
	move.w	#$8121,(a4)+                    ; $8121: end from the a3 stack
.word_step_compare:
	move.w	#$8122,(a4)+                    ; $8122: ends the variable-step test (exact meaning unknown)
	bra.s	.word_step_branch_back
.word_step_constant_end:
	move.w	#$8008,(a4)+                    ; $8008: compare with a constant
	move.l	(a0),(a4)+                      ; the end constant
.choose_word_step_condition:
	tst.l	d0                              ; negative step?
	bpl.s	.word_step_count_up
	move.w	#$811d,(a4)+                    ; $811d: condition for a negative step
	bra.s	.word_step_branch_back
.word_step_count_up:
	move.w	#$811e,(a4)+                    ; $811e: condition for a positive step
.word_step_branch_back:
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	move.l	-$8(a0),(a4)+                   ; target: the loop body offset
	bsr.w	optimise_generate_and_append    ; generate and copy the test
.patch_word_step_exits:
	addq.l	#4,sp                           ; drop the return address / patched offset
	move.w	(sp)+,d7                        ; d7 = entry type
	bpl.s	.word_step_exits_patched        ; not a pending exit: done
	movea.l	(sp),a0                         ; a0 = the exit's code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = code offset after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target
	bra.s	.patch_word_step_exits
.word_step_exits_patched:
	tst.b	d7                              ; the FOR's jump entry?
	bpl.s	.drop_word_step_entry
	addq.l	#4,sp                           ; drop its offset
	move.w	(sp)+,d7                        ; d7 = the FOR entry's type
.drop_word_step_entry:
	cmpi.w	#$c,d7                          ; type 12: nothing on the a3 stack
	bne.s	.pop_word_step_values
	lea	$c(sp),sp                       ; drop offset, step and end
	bra.w	next_statement
.pop_word_step_values:
	cmpi.w	#$e,d7                          ; type 14: end and step on the a3 stack
	beq.s	.pop_word_end_and_step
	addq.l	#8,sp                           ; drop offset and the constant
	lea	statement_code_buffer,a1        ; a1 = statement code
	move.w	#$598b,(a1)+                    ; $598b: subq.l #4,a3 (drop one value)
.copy_word_pop_code:
	bsr.w	copy_code_to_output             ; copy the stack correction
	bra.w	next_statement
.pop_word_end_and_step:
	addq.l	#4,sp                           ; drop the offset
	lea	statement_code_buffer,a1        ; a1 = statement code
	move.w	#$5d8b,(a1)+                    ; $5d8b: subq.l #6,a3 (drop end and step)
	bra.s	.copy_word_pop_code

compile_for_byte_downto:
	moveq	#-1,d0                          ; d0 = -1: DOWNTO
	bra.s	compile_for_byte

compile_for_byte_to:
	moveq	#1,d0                           ; d0 = +1: TO

;------------------------------------------------------------------------------
; FOR i| (byte variable) TO / DOWNTO, d0 = +1 / -1: i| = start (stmt_let_byte, IR $8044), then the end. Both
; constant and the loop never running: the body is skipped; constant end: type 10; otherwise library routine
; $1b2 FORC1 keeps the end on the a3 stack (type 11).
;------------------------------------------------------------------------------
compile_for_byte:
	move.l	d0,-(sp)                        ; keep the direction
	bsr.w	stmt_let_byte                   ; i| = start (IR $8044 store byte variable)
	bsr.w	optimise_ir
	move.l	a4,-(sp)                        ; start of the end expression's IR
	bsr.w	parse_integer_expression        ; end value
	bsr.w	optimise_ir
	movea.l	(sp)+,a0                        ; a0 = the end's IR
	cmpi.w	#$8007,(a0)+                    ; $8007: integer constant?
	bne.s	.byte_end_variable
	move.l	(a0)+,d0                        ; d0 = constant end
	cmpa.l	a4,a0                           ; nothing after the constant?
	bne.s	.byte_end_variable
	subq.l	#6,a4                           ; remove the constant from the IR
	lea	ir_buffer,a0                    ; look at the start assignment
	cmpi.w	#$8007,(a0)+                    ; start an integer constant?
	bne.s	.byte_start_not_constant
	move.l	(a0)+,d1                        ; d1 = constant start
	cmpi.w	#$8044,(a0)+                    ; $8044: start constant stored to i|?
	bne.s	.byte_start_not_constant
	move.l	d0,d2                           ; d2 = end
	tst.w	(sp)                            ; high word of the direction: DOWNTO?
	bpl.s	.compare_byte_start_end
	exg	d1,d2                           ; DOWNTO: compare the other way round
.compare_byte_start_end:
	cmp.l	d2,d1
	bgt.s	.byte_loop_never_runs           ; start beyond end: the loop never runs
	addq.l	#4,sp                           ; drop the direction
	move.l	d0,(sp)                         ; end constant into the slot below the entry
	clr.w	(a4)                            ; end the IR
	bsr.w	generate_and_append             ; code for i| = start
	move.l	code_write_pointer,d0           ; d0 = code offset of the loop body
	sub.l	code_buffer_start,d0
	move.l	d0,-(sp)                        ; FOR entry: body offset
	move.w	#$a,-(sp)                       ; type 10: constant end
	bra.w	next_statement
.byte_loop_never_runs:
	bsr.w	skip_dead_lines                 ; skip the body; a0 = the NEXT line, d0 = its length
	adda.w	d0,a0                           ; continue after the NEXT
	move.l	a0,next_line_pointer
	suba.w	d0,a0
	addq.l	#8,sp                           ; drop the direction and the slot
	bra.w	next_statement
.byte_start_not_constant:
	moveq	#10,d7                          ; type 10
	addq.l	#4,sp                           ; drop the direction
	move.l	d0,(sp)                         ; end constant into the slot
	bra.w	finish_for_header               ; generate and push the entry
.byte_end_variable:
	move.w	#$1b2,(a4)+                     ; IR: $1b2 FORC1
	moveq	#11,d7                          ; type 11: end on the a3 stack (FORC1)
	addq.l	#8,sp                           ; drop the direction and the slot
	bra.w	finish_for_header

compile_next_byte_to:
	moveq	#1,d0                           ; d0 = +1: TO
	move.w	#$80d3,(a4)+                    ; $80d3: IR i| + 1
	bra.s	compile_next_byte

compile_next_byte_downto:
	moveq	#-1,d0                          ; d0 = -1: DOWNTO
	move.w	#$80d7,(a4)+                    ; $80d7: IR i| - 1

;------------------------------------------------------------------------------
; NEXT i| (TO $80d3 / DOWNTO $80d7, check $8207 with N+): IR $803d load, $8123/$8124/$8125.
;------------------------------------------------------------------------------
compile_next_byte:
	move.w	(a5),(a4)+                      ; variable index
	move.l	d0,-(sp)                        ; keep the direction
	move.b	option_n_flag(pc),d1            ; option N+?
	beq.s	.no_byte_n_check
	move.w	#$8207,(a4)+                    ; $8207: IR check (option N+)
	bsr.w	optimise_generate_and_append    ; code for the increment and the check
	movem.l	(sp)+,d0-d1                     ; d0 = direction, d1 = return address
	move.l	code_write_pointer,d2           ; d2 = code offset of the check's jump
	sub.l	code_buffer_start,d2
	subq.l	#8,d2
	move.w	(sp),d3                         ; d3 = type of the FOR entry
	move.l	d2,-(sp)                        ; push an exit entry for the check's jump
	ori.w	#$8000,d3                       ; bit 15: exit entry
	move.w	d3,-(sp)
	movem.l	d0-d1,-(sp)                     ; direction and return address back on top
	bra.s	.find_byte_for_entry
.no_byte_n_check:
	bsr.w	optimise_generate_and_append    ; code for the increment
.find_byte_for_entry:
	lea	ir_buffer,a4                    ; new IR
	lea	8(sp),a0                        ; a0 = first entry below direction and return address
.skip_byte_exit_entries:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.skip_byte_exit_entries         ; bit 15: an exit entry, skip it
	tst.b	d7                              ; bit 7: the FOR's jump to the test?
	bpl.s	.compare_byte_with_end
	pea	(a0)                            ; keep the scan pointer
	movea.l	-$4(a0),a0                      ; a0 = that jump in the code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = here: the test
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; jump to the test lands here
	movea.l	(sp)+,a0                        ; restore the scan pointer
	move.w	(a0)+,d7                        ; d7 = type of the FOR entry itself
	addq.l	#4,a0                           ; skip its offset
.compare_byte_with_end:
	move.l	(sp)+,d0                        ; d0 = direction
	move.w	#$803d,(a4)+                    ; $803d: IR load byte variable
	move.w	(a5),(a4)+                      ; variable index
	cmpi.w	#$b,d7                          ; type 11: end on the a3 stack?
	bne.s	.byte_constant_end
	move.w	#$8123,(a4)+                    ; $8123: cmp.b -4(a3),d0, the end on the a3 stack
	bra.s	.choose_byte_condition
.byte_constant_end:
	move.w	#$8008,(a4)+                    ; $8008: compare with a constant
	move.l	(a0),(a4)+                      ; the end constant from the slot below the entry
.choose_byte_condition:
	tst.w	d0                              ; DOWNTO?
	bpl.s	.byte_count_up
	move.w	#$8124,(a4)+                    ; $8124: i| >= end (DOWNTO)
	bra.s	.byte_branch_back
.byte_count_up:
	move.w	#$8125,(a4)+                    ; $8125: i| <= end (TO)
.byte_branch_back:
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	move.l	-(a0),(a4)+                     ; to the loop body offset of the entry
	bsr.w	optimise_generate_and_append    ; code for the test and branch
.patch_byte_exits:
	addq.l	#4,sp                           ; drop the return address / exit offset
	move.w	(sp)+,d7                        ; d7 = next entry type
	bpl.s	.byte_exits_patched             ; not an exit: done
	movea.l	(sp),a0                         ; a0 = the exit jump in the code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = here: after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; exit jumps land after the NEXT
	bra.s	.patch_byte_exits
.byte_exits_patched:
	tst.b	d7                              ; jump-to-test entry?
	bpl.s	.drop_byte_for_entry
	addq.l	#4,sp                           ; drop it
	move.w	(sp)+,d7                        ; d7 = type of the FOR entry
.drop_byte_for_entry:
	cmpi.w	#$b,d7                          ; type 11 left a value on the a3 stack?
	beq.s	.pop_byte_end_value
	addq.l	#8,sp                           ; drop the entry offset and the end slot
	bra.w	next_statement
.pop_byte_end_value:
	addq.l	#4,sp                           ; drop the entry offset
	lea	statement_code_buffer,a1
	move.w	#$598b,(a1)+                    ; $598b: subq.l #4,a3 (drop the end value)
	bsr.w	copy_code_to_output             ; append it
	bra.w	next_statement

;------------------------------------------------------------------------------
; FOR i| ... STEP: as compile_for_int_step for a byte variable ($8044, FORC1/FORC2).
;------------------------------------------------------------------------------
compile_for_byte_step:
	bsr.w	stmt_let_byte                   ; i| = start (IR $8044)
	bsr.w	optimise_ir
	move.l	a4,(sp)                         ; start of the end expression (in the return address slot)
	bsr.w	parse_integer_expression        ; end value
	bsr.w	optimise_ir
	movea.l	(sp)+,a0                        ; a0 = the end's IR
	cmpi.w	#$8007,(a0)+                    ; $8007: integer constant?
	bne.w	.step_end_variable
	move.l	(a0)+,d0                        ; d0 = constant end
	cmpa.l	a4,a0                           ; nothing after the constant?
	bne.s	.step_end_variable
	subq.l	#6,a4                           ; remove it from the IR
	move.l	d0,-(sp)                        ; keep the end constant
	move.l	a4,-(sp)                        ; start of the step expression
	bsr.w	parse_integer_expression        ; step value
	bsr.w	optimise_ir
	movea.l	(sp)+,a0                        ; a0 = the step's IR
	cmpi.w	#$8007,(a0)+                    ; constant step?
	bne.w	.step_variable_end_constant
	move.l	(a0)+,d0                        ; d0 = constant step
	cmpa.l	a4,a0                           ; nothing after it?
	bne.w	.step_variable_end_constant     ; end constant, step variable
	subq.l	#6,a4                           ; remove it from the IR
	move.l	d0,-(sp)                        ; keep the step constant
	lea	ir_buffer,a0                    ; look at the start assignment
	cmpi.w	#$8007,(a0)+                    ; start an integer constant?
	bne.s	.step_start_not_constant
	move.l	(a0)+,d1                        ; d1 = constant start
	cmpi.w	#$8044,(a0)+                    ; $8044: stored to i|?
	bne.s	.step_start_not_constant
	move.l	4(sp),d2                        ; d2 = end
	tst.w	(sp)                            ; high word of the step: negative step?
	bpl.s	.compare_step_start_end
	exg	d1,d2                           ; counting down: compare the other way round
.compare_step_start_end:
	cmp.l	d2,d1
	bgt.s	.step_loop_never_runs           ; start beyond end: the loop never runs
	clr.w	(a4)                            ; end the IR
	bsr.w	generate_and_append             ; code for i| = start
	move.l	code_write_pointer,d0           ; d0 = code offset of the loop body
	sub.l	code_buffer_start,d0
	move.l	d0,-(sp)                        ; FOR entry: body offset
	move.w	#$c,-(sp)                       ; type 12: end and step constant
	bra.w	next_statement
.step_loop_never_runs:
	bsr.w	skip_dead_lines                 ; skip the body; a0 = the NEXT line, d0 = its length
	adda.w	d0,a0                           ; continue after the NEXT
	move.l	a0,next_line_pointer
	suba.w	d0,a0
	addq.l	#8,sp                           ; drop the step and end constants
	bra.w	next_statement
.step_start_not_constant:
	moveq	#12,d7                          ; type 12
	bra.w	finish_for_header
.step_end_variable:
	move.w	#$7fff,(a4)+                    ; $7fff: room for $8017 if the step is variable
	pea	(a4)                            ; start of the step expression
	bsr.w	parse_integer_expression        ; step value
	bsr.w	optimise_ir
	movea.l	(sp)+,a0                        ; a0 = the step's IR
	cmpi.w	#$8007,(a0)+                    ; constant step?
	bne.s	.step_variable
	move.l	(a0)+,d0                        ; d0 = constant step
	cmpa.l	a4,a0                           ; nothing after it?
	bne.s	.step_not_constant
	subq.l	#8,a4                           ; remove the constant and the $7fff word
	move.l	d0,-(sp)                        ; keep the step constant
	move.w	#$1b2,(a4)+                     ; IR: $1b2 FORC1 (end on the a3 stack)
	moveq	#13,d7                          ; type 13: end variable, step constant
	bra.w	finish_for_header
.step_not_constant:
	subq.l	#4,a0                           ; back to the start of the step's IR
.step_variable:
	move.w	#$8017,-$4(a0)                  ; $8017 push long: the end over the step
	move.w	#$801b,(a4)+                    ; $801b: pop the end into d1
	move.w	#$1b3,(a4)+                     ; IR: $1b3 FORC2 (end and step on the a3 stack)
	bsr.w	optimise_ir
	moveq	#14,d7                          ; type 14: end and step variable
	bra.w	finish_for_header
.step_variable_end_constant:
	move.w	#$1b2,(a4)+                     ; IR: $1b2 FORC1 (step on the a3 stack)
	moveq	#15,d7                          ; type 15: end constant, step variable
	bra.w	finish_for_header

;------------------------------------------------------------------------------
; NEXT i| of a FOR ... STEP ($8126/$8127, constant step sign-extended from a byte, $80e4 add, $8099/$8128/$8129).
;------------------------------------------------------------------------------
compile_next_byte_step:
	lea	4(sp),a0                        ; a0 = first entry below the return address
.find_step_entry:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.find_step_entry                ; skip exit entries
	tst.b	d7                              ; skip the jump-to-test entry
	bmi.s	.find_step_entry
	cmpi.w	#$c,d7                          ; type 12 or 13: constant step
	beq.s	.constant_step
	cmpi.w	#$d,d7
	beq.s	.constant_step
	move.w	#$8126,d0                       ; $8126: move.b -4(a3),d0, the step of a FORC1 frame
	cmpi.w	#$e,d7                          ; type 14?
	bne.s	.store_step_code
	move.w	#$8127,d0                       ; $8127: move.b -3(a3),d0, the step of a FORC2 frame
.store_step_code:
	move.w	d0,(a4)+
	bra.s	.add_step
.constant_step:
	move.w	#$8007,(a4)+                    ; $8007: integer constant
	move.l	(a0)+,d0                        ; the step from the slot below the entry
	ext.w	d0                              ; sign-extend the byte step
	ext.l	d0
	move.l	d0,(a4)+
.add_step:
	move.w	#$80e4,(a4)+                    ; $80e4: IR add d0 to the byte variable
	move.w	(a5),(a4)+                      ; variable index
	move.b	option_n_flag(pc),d1            ; option N+?
	beq.s	.no_step_n_check
	move.w	#$8207,(a4)+                    ; $8207: IR check (option N+)
	bsr.w	optimise_generate_and_append    ; code for the add and the check
	move.l	(sp)+,d0                        ; d0 = return address
	move.l	code_write_pointer,d2           ; d2 = code offset of the check's jump
	sub.l	code_buffer_start,d2
	subq.l	#8,d2
	move.w	(sp),d3                         ; d3 = type of the FOR entry
	move.l	d2,-(sp)                        ; push an exit entry for the check's jump
	ori.w	#$8000,d3                       ; bit 15: exit entry
	move.w	d3,-(sp)
	move.l	d0,-(sp)                        ; return address back on top
	bra.s	.find_step_for_entry
.no_step_n_check:
	bsr.w	optimise_generate_and_append    ; code for the add
.find_step_for_entry:
	lea	ir_buffer,a4                    ; new IR
	lea	4(sp),a0                        ; a0 = first entry below the return address
.skip_step_exit_entries:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.skip_step_exit_entries         ; skip exit entries
	tst.b	d7                              ; bit 7: the FOR's jump to the test?
	bpl.s	.compare_step_with_end
	pea	(a0)                            ; keep the scan pointer
	movea.l	-$4(a0),a0                      ; a0 = that jump in the code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = here: the test
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; jump to the test lands here
	movea.l	(sp)+,a0                        ; restore the scan pointer
	move.w	(a0)+,d7                        ; d7 = type of the FOR entry itself
	addq.l	#4,a0                           ; skip its offset
.compare_step_with_end:
	move.l	(a0)+,d0                        ; d0 = first slot: step (type 12/13) or end (type 15)
	move.w	#$803d,(a4)+                    ; $803d: IR load byte variable
	move.w	(a5),(a4)+                      ; variable index
	cmpi.w	#$c,d7                          ; type 12: constant end
	beq.s	.step_constant_end
	cmpi.w	#$d,d7                          ; type 13: end on the a3 stack?
	bne.s	.variable_step_test
	move.w	#$8123,(a4)+                    ; $8123: compare i| with the end on the a3 stack
	bra.s	.choose_step_condition
.variable_step_test:
	move.w	#$8099,-$4(a4)                  ; $8099 replaces the load: i| as the operand
	cmpi.w	#$e,d7                          ; type 14: end on the a3 stack too?
	beq.s	.end_on_a3_stack
	move.w	#$8009,(a4)+                    ; type 15: $8009 constant end into d2
	move.l	-$4(a0),d0                      ; the end constant
	ext.w	d0                              ; sign-extend from a byte
	ext.l	d0
	move.l	d0,(a4)+
	bra.s	.variable_step_branch
.end_on_a3_stack:
	move.w	#$8128,(a4)+                    ; $8128: move.b -4(a3),d2, the end of a FORC2 frame
.variable_step_branch:
	move.w	#$8129,(a4)+                    ; $8129: compare for a step whose sign is known at run time
	bra.s	.step_branch_back
.step_constant_end:
	move.w	#$8008,(a4)+                    ; $8008: compare with a constant
	move.l	(a0),(a4)+                      ; the end constant from the second slot
.choose_step_condition:
	tst.l	d0                              ; negative step?
	bpl.s	.step_count_up
	move.w	#$8124,(a4)+                    ; $8124: i| >= end (counting down)
	bra.s	.step_branch_back
.step_count_up:
	move.w	#$8125,(a4)+                    ; $8125: i| <= end (counting up)
.step_branch_back:
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	move.l	-$8(a0),(a4)+                   ; to the loop body offset of the entry
	bsr.w	optimise_generate_and_append    ; code for the test and branch
.patch_step_exits:
	addq.l	#4,sp                           ; drop the return address / exit offset
	move.w	(sp)+,d7                        ; d7 = next entry type
	bpl.s	.step_exits_patched             ; not an exit: done
	movea.l	(sp),a0                         ; a0 = the exit jump in the code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = here: after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; exit jumps land after the NEXT
	bra.s	.patch_step_exits
.step_exits_patched:
	tst.b	d7                              ; jump-to-test entry?
	bpl.s	.drop_step_for_entry
	addq.l	#4,sp                           ; drop it
	move.w	(sp)+,d7                        ; d7 = type of the FOR entry
.drop_step_for_entry:
	cmpi.w	#$c,d7                          ; type 12: nothing on the a3 stack
	bne.s	.pop_step_values
	lea	$c(sp),sp                       ; drop the offset and both constants
	bra.w	next_statement
.pop_step_values:
	cmpi.w	#$e,d7                          ; type 14?
	beq.s	.pop_end_and_step
	addq.l	#8,sp                           ; types 13/15: drop the offset and the slot
	lea	statement_code_buffer,a1
	move.w	#$598b,(a1)+                    ; $598b: subq.l #4,a3
.copy_a3_drop:
	bsr.w	copy_code_to_output             ; append it
	bra.w	next_statement
.pop_end_and_step:
	addq.l	#4,sp                           ; type 14: drop the entry offset
	lea	statement_code_buffer,a1
	move.w	#$598b,(a1)+                    ; $598b: subq.l #4,a3
	bra.s	.copy_a3_drop

compile_for_float_downto:
	move.w	#$1df,-(sp)                     ; library routine $1df FORF1D
	bra.s	compile_for_float

compile_for_float_to:
	move.w	#$1dd,-(sp)                     ; library routine $1dd FORF1

;------------------------------------------------------------------------------
; FOR x (float) TO / DOWNTO: x = start (stmt_let_float, IR $8041), the end, IR $80ee + variable index + routine
; $1dd FORF1 (TO) or $1df FORF1D (DOWNTO), then $80c0 with a placeholder target; pushes type 10.
;------------------------------------------------------------------------------
compile_for_float:
	move.w	(a5),-(sp)                      ; variable index of x
	bsr.w	stmt_let_float                  ; x = start (IR $8041)
	bsr.w	parse_expression                ; end value
	move.w	#$80ee,(a4)+                    ; $80ee: IR float FOR, variable index and routine follow
	move.w	(sp)+,(a4)+                     ; variable index
	move.w	(sp)+,(a4)+                     ; the routine pushed by the entry point
	move.w	#$80c0,(a4)+                    ; $80c0: IR branch, placeholder target
	move.l	#$f0f0f0f,(a4)+                 ; placeholder: patched to after the NEXT
	bsr.w	optimise_generate_and_append    ; code for the header
	move.l	code_write_pointer,d0           ; d0 = code offset of the $80c0 branch
	sub.l	code_buffer_start,d0
	subq.l	#8,d0
	move.l	d0,(sp)                         ; entry offset (return address slot)
	move.w	#$a,-(sp)                       ; type 10
	bra.w	next_statement

compile_next_float_downto:
	move.w	#$1e0,(a4)+                     ; library routine $1e0 NEXTF1D
	bra.s	compile_next_float

compile_next_float_to:
	move.w	#$1de,(a4)+                     ; library routine $1de NEXTF1

;------------------------------------------------------------------------------
; NEXT x (float): routine $1de NEXTF1 / $1e0 NEXTF1D, then $80c0 back to FOR offset + 8; patches exits and removes
; the 14-byte FOR frame from the a3 stack (lea -14(a3),a3).
;------------------------------------------------------------------------------
compile_next_float:
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	lea	4(sp),a0                        ; a0 = first entry below the return address
.find_float_for_entry:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.find_float_for_entry           ; skip exit entries
	move.l	-(a0),d0                        ; offset of the FOR's branch
	addq.l	#8,d0                           ; +8: the loop body after it
	move.l	d0,(a4)+
	bsr.w	optimise_generate_and_append    ; code for NEXTF1 and the branch
.patch_float_jumps:
	addq.l	#4,sp                           ; drop the return address / previous offset
	movea.l	2(sp),a0                        ; a0 = the entry's jump in the code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = here: after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; the FOR's branch and exits land here
	tst.w	(sp)+                           ; exit entry (bit 15)? patch the next one
	bmi.s	.patch_float_jumps
	addq.l	#4,sp                           ; drop the FOR entry's offset
	lea	statement_code_buffer,a1
	move.w	#$47eb,(a1)+                    ; $47eb $fff2: lea -14(a3),a3
	move.w	#$fff2,(a1)+
	bsr.w	copy_code_to_output
	bra.w	next_statement

;------------------------------------------------------------------------------
; FOR x ... STEP (float): start, end and step expressions (IR $8002 / $8004 between), $80ee + routine $1e1 FORFX.
;------------------------------------------------------------------------------
compile_for_float_step:
	move.w	(a5),-(sp)                      ; variable index of x
	bsr.w	stmt_let_float                  ; x = start (IR $8041)
	bsr.w	parse_expression                ; end value
	move.w	#$8002,(a4)+                    ; $8002: push float
	bsr.w	parse_expression                ; step value
	move.w	#$8004,(a4)+                    ; $8004: pop float into d3-d5
	move.w	#$80ee,(a4)+                    ; $80ee: IR float FOR, variable index and routine follow
	move.w	(sp)+,(a4)+                     ; variable index
	move.w	#$1e1,(a4)+                     ; library routine $1e1 FORFX
	move.w	#$80c0,(a4)+                    ; $80c0: IR branch, placeholder target
	move.l	#$f0f0f0f,(a4)+                 ; placeholder: patched to after the NEXT
	bsr.w	optimise_generate_and_append    ; code for the header
	move.l	code_write_pointer,d0           ; d0 = code offset of the $80c0 branch
	sub.l	code_buffer_start,d0
	subq.l	#8,d0
	move.l	d0,(sp)                         ; entry offset (return address slot)
	move.w	#$a,-(sp)                       ; type 10
	bra.w	next_statement

;------------------------------------------------------------------------------
; NEXT x of a float FOR ... STEP: routine $1e2 NEXTFX, branch back, lea -22(a3),a3.
;------------------------------------------------------------------------------
compile_next_float_step:
	move.w	#$1e2,(a4)+                     ; library routine $1e2 NEXTFX
	move.w	#$80c0,(a4)+                    ; $80c0: IR conditional branch back
	lea	4(sp),a0                        ; a0 = first entry below the return address
.find_float_step_entry:
	move.w	(a0)+,d7                        ; d7 = entry type
	addq.l	#4,a0                           ; skip its offset
	bmi.s	.find_float_step_entry          ; skip exit entries
	move.l	-(a0),d0                        ; offset of the FOR's branch
	addq.l	#8,d0                           ; +8: the loop body after it
	move.l	d0,(a4)+
	bsr.w	optimise_generate_and_append    ; code for NEXTFX and the branch
.patch_float_step_jumps:
	addq.l	#4,sp                           ; drop the return address / previous offset
	movea.l	2(sp),a0                        ; a0 = the entry's jump in the code
	adda.l	code_buffer_start,a0
	move.l	code_write_pointer,d0           ; d0 = here: after the loop
	sub.l	code_buffer_start,d0
	bsr.w	patch_jump_target               ; the FOR's branch and exits land here
	tst.w	(sp)+                           ; exit entry (bit 15)? patch the next one
	bmi.s	.patch_float_step_jumps
	addq.l	#4,sp                           ; drop the FOR entry's offset
	lea	statement_code_buffer,a1
	move.w	#$47eb,(a1)+                    ; $47eb $ffea: lea -22(a3),a3
	move.w	#$ffea,(a1)+
	bsr.w	copy_code_to_output
	bra.w	next_statement
option_p_flag:
	dc.w	$0000                           ; default of the GOSUB-frame flag (option P)
routine_gosub_frame_flag:
	dc.w	$0000                           ; set when the routine uses the library GOSUB frame

;------------------------------------------------------------------------------
; DEFFN: ends the previous code with END when it could fall through (emit_end_unless_returned) and turns that
; call into a bra.w around the function body (marker $6101 $7fff in the code), records the function's code
; offset (record_function_address), then compiles the expression: numeric functions end with rts (or library
; $27a RETURN when the routine uses a GOSUB frame), string functions are wrapped in $279 GOSUB / $294 RETSTR.
;------------------------------------------------------------------------------
compile_deffn:
	st	keep_source_flag                ; DEFFN: keep the source of this line
	move.b	routine_gosub_frame_flag(pc),-(sp) ; save the GOSUB-frame flag
	sf	routine_gosub_frame_flag
	clr.w	-(sp)                           ; code word to end with: none yet
	btst	#$0,(a5)                        ; bit 0 of the type: string function
	seq	-(sp)                           ; flag: numeric function
	bsr.w	emit_end_unless_returned        ; END guard in front of the function
	beq.s	.record_address                 ; nothing emitted
	move.w	#$7fff,-$2(a4)                  ; the END becomes $7fff: a bra.w around the function
	moveq	#4,d1                           ; the bra.w is 4 bytes: function starts after it
.record_address:
	bsr.w	record_function_address         ; store the code offset, parameters
	tst.b	(sp)+                           ; numeric function?
	beq.s	.string_function
	bsr.w	parse_expression                ; the function expression
	tst.w	routine_gosub_frame_flag        ; GOSUB frame in use?
	bne.s	.return_via_library
	move.w	#$4e75,(sp)                     ; $4e75 rts at the end
	bra.s	.generate_function
.return_via_library:
	move.w	#$27a,(a4)+                     ; IR: library routine $27a RETURN
	bra.s	.generate_function
.string_function:
	cmpa.l	#ir_buffer_second_word,a4
	bne.s	.parse_string_result
	move.w	#$279,(a4)+                     ; IR: library routine $279 GOSUB
.parse_string_result:
	bsr.w	parse_expression
	move.w	#$294,(a4)+                     ; IR: library routine $294 RETSTR
.generate_function:
	bsr.w	optimise_and_generate           ; code for the function
	move.w	(sp)+,(a1)+                     ; append rts or nothing
	bne.s	.check_placeholder_call         ; a word was appended
	subq.l	#2,a1                           ; take the zero word back
.check_placeholder_call:
	lea	statement_code_buffer,a0
	cmpi.l	#$61017fff,(a0)                 ; $6101 $7fff: the placeholder call
	bne.s	.restore_frame_flag             ; no guard in front
	move.l	a1,d0                           ; d0 = distance to the end of the function
	sub.l	a0,d0
	subq.w	#2,d0                           ; minus 2: relative to the displacement word
	move.w	#$6000,(a0)+                    ; $6000: bra.w over the function body
	move.w	d0,(a0)+                        ; displacement
.restore_frame_flag:
	move.b	(sp)+,routine_gosub_frame_flag  ; restore the caller's flag
	addq.l	#4,sp                           ; drop the return address
	bra.w	copy_statement_code

;------------------------------------------------------------------------------
; FUNCTION: shortens branches and reclaims source memory, then looks at a $ line straight after it: "$X" skips the
; whole function up to ENDFUNC, "$F%" sets function_returns_int_flag. Emits END when needed and records the
; function's code offset; falls into record_function_address.
;------------------------------------------------------------------------------
compile_function:
	sf	routine_gosub_frame_flag
	bsr.w	shorten_branches                ; previous routine done: shorten its branches
	bsr.w	reclaim_compiled_source         ; free the source already compiled
	clr.b	function_returns_int_flag
	movea.l	next_line_pointer(pc),a2        ; look at the next line
	addq.l	#2,a2                           ; skip the line length
	cmpi.w	#$336,(a2)+                     ; 411: a $ line after FUNCTION?
	bne.s	.emit_end_guard
.skip_option_spaces:
	moveq	#-33,d1                         ; upper-case the option letter
	and.b	(a2)+,d1
	cmpi.b	#$20,d1                         ; skip spaces
	beq.s	.skip_option_spaces
	cmpi.b	#$58,d1                         ; $X: skip the function
	bne.s	.check_int_result
	movea.l	next_line_pointer(pc),a5        ; a5 = the next line
.find_endfunc:
	cmpi.w	#$16,2(a5)                      ; find ENDFUNC ($16)
	beq.s	.skip_endfunc_line
	addq.w	#1,source_line_number           ; count the skipped line
	adda.w	(a5),a5                         ; next line
	bra.s	.find_endfunc
.skip_endfunc_line:
	adda.w	(a5),a5                         ; skip the ENDFUNC line too
	move.l	a5,next_line_pointer            ; continue after ENDFUNC
	rts
.check_int_result:
	cmpi.b	#$46,d1                         ; $F%
	bne.s	.emit_end_guard
	cmpi.b	#$25,(a2)+                      ; followed by '%'?
	seq	function_returns_int_flag       ; $F%: FUNCTION returns an integer
.emit_end_guard:
	moveq	#0,d1                           ; no offset adjustment yet
	bsr.s	emit_end_unless_returned        ; END guard; d1 = 4 when emitted

;------------------------------------------------------------------------------
; Reads the routine identifier token at a5 (type byte, bit 4 = word index, bit 0 = string) and stores the code
; offset (+ d1) in numeric_fn_address_table or string_fn_address_table. For a string function, when the IR is
; still at its start, also writes IR $279 GOSUB and sets routine_gosub_frame_flag.
;------------------------------------------------------------------------------
record_function_address:
	moveq	#0,d0                           ; clear the index
	move.b	(a5)+,d2                        ; d2 = type byte of the routine identifier
	btst	#$4,d2                          ; bit 4: word index
	beq.s	.read_index_low
	move.b	(a5)+,d0                        ; high byte of a word index
	asl.w	#8,d0
.read_index_low:
	move.b	(a5)+,d0                        ; low byte of the index
	movea.l	numeric_fn_address_table,a0     ; numeric function table
	lsr.b	#1,d2                           ; bit 0: string function
	bcc.s	store_routine_address           ; numeric: store and return
	movea.l	string_fn_address_table,a0      ; string function table
	bsr.s	store_routine_address           ; store the address, parameters
	cmpa.l	#ir_buffer,a4                   ; still at the start of the IR?
	bne.s	.address_recorded
	st	routine_gosub_frame_flag        ; string function: GOSUB frame
	move.w	#$279,(a4)+                     ; IR: library routine $279 GOSUB
.address_recorded:
	rts

;------------------------------------------------------------------------------
; Stores code_write_pointer - code_buffer_start + d1 at (a0 + 4 x d0); when the next token is 35 (bracket
; before the parameters) the parameter list is compiled at parse_procedure_parameters.
;------------------------------------------------------------------------------
store_routine_address:
	asl.w	#2,d0                           ; 4 bytes per entry
	movea.l	code_write_pointer,a1           ; a1 = code offset
	suba.l	code_buffer_start,a1
	adda.l	d1,a1                           ; plus the END guard size
	move.l	a1,0(a0,d0.w)                   ; store the routine's address
	cmpi.b	#$23,(a5)+                      ; token 35: bracket before numeric parameters
	beq.w	parse_procedure_parameters
	rts

;------------------------------------------------------------------------------
; Before a PROCEDURE/FUNCTION body: if the code so far did not end with a call of the library routine END ($3b),
; RETURN ($27a) or ENDFUNC ($293), emits a call of END ($3b) so execution cannot run into the procedure.
; Compares last_library_routine with statement_code_routine_word.
; Exit: d1 = 0 and Z set if nothing was emitted, d1 = 4 (size of the bsr) and Z clear if END was emitted.
;------------------------------------------------------------------------------
emit_end_unless_returned:
	moveq	#0,d1
	move.w	last_library_routine,d0
	cmp.w	statement_code_routine_word,d0
	bne.s	.emit_end_call
	cmpi.w	#$3b,d0                         ; $3b = library END
	beq.s	.done
	cmpi.w	#$27a,d0                        ; $27a = library RETURN
	beq.s	.done
	cmpi.w	#$293,d0                        ; $293 = library ENDFUNC
	beq.s	.done
.emit_end_call:
	move.w	#$3b,(a4)+                      ; IR: call END
	moveq	#4,d1                           ; the procedure starts 4 bytes later
.done:
	rts

;------------------------------------------------------------------------------
; Statement PROCEDURE (token 6) and "> PROCEDURE" (token $36).
; Sets routine_gosub_frame_flag from its default option_p_flag, closes the previous routine and emits END in
; front of the body if needed (emit_end_unless_returned). If the next line is a "$X" option line the whole
; procedure is skipped up to ENDPROC. Otherwise records the procedure address in procedure_address_table and
; falls into parse_procedure_parameters.
;------------------------------------------------------------------------------
stmt_procedure:
	move.w	option_p_flag(pc),routine_gosub_frame_flag
	bsr.w	shorten_branches
	bsr.w	reclaim_compiled_source
	bsr.s	emit_end_unless_returned
	movea.l	next_line_pointer(pc),a2        ; dat_00ea2 = next source line
	addq.l	#2,a2
	cmpi.w	#$336,(a2)+                     ; $336 = token word of a "$" compiler option line
	bne.s	.store_address
.skip_option_spaces:
	moveq	#-33,d2                         ; skip spaces, upper-case the option letter
	and.b	(a2)+,d2
	cmpi.b	#$20,d2
	beq.s	.skip_option_spaces
	cmpi.b	#$58,d2                         ; "$X": do not compile this procedure
	bne.s	.store_address
	subq.l	#4,a5
.skip_to_endproc:
	adda.w	(a5),a5                         ; skip lines up to ENDPROC, counting them
	addq.w	#1,source_line_number
	cmpi.w	#$e,2(a5)                       ; $e = token word of ENDPROC
	bne.s	.skip_to_endproc
	adda.w	(a5),a5
	move.l	a5,next_line_pointer            ; continue after ENDPROC
	rts
.store_address:
	move.w	(a5)+,d0                        ; procedure number
	asl.w	#2,d0
	movea.l	procedure_address_table,a0      ; var_118b6 = procedure address table
	movea.l	code_write_pointer,a1           ; current code offset (var_118cc - var_118d0) + d1
	suba.l	code_buffer_start,a1
	adda.l	d1,a1
	move.l	a1,0(a0,d0.w)

;------------------------------------------------------------------------------
; Parses the formal parameter list of a PROCEDURE/FUNCTION header (a5 after the name).
; No list ($46 end of line, or $9d): only emits the library GOSUB call ($279) when the frame flag is already set.
; Otherwise sets the frame flag, emits GOSUB ($279) and one IR entry per parameter: $8163-$8168 for value
; parameters (# $ % ! & |), and after VAR ($32) $8169-$8174 for VAR parameters (scalars and arrays), each
; followed by the variable index. The entries are then reversed (reverse_parameter_ir) so they pop the
; arguments in stack order.
;------------------------------------------------------------------------------
parse_procedure_parameters:
	cmpi.b	#$46,(a5)                       ; $46 = end of line
	beq.w	no_procedure_parameters
	cmpi.b	#$9d,(a5)                       ; $9d also means no parameter list (exact meaning of $9d here not worked
                                                ;   out)
	beq.w	no_procedure_parameters
	st	routine_gosub_frame_flag        ; procedure uses the library GOSUB/RETURN frame
	move.w	#$279,(a4)+                     ; IR: call library GOSUB ($279)
	move.l	a4,-(sp)                        ; remember start of the parameter IR
.next_value_param:
	move.b	(a5)+,d0                        ; variable token ($e0-$ff) or end of list
	bpl.s	parse_var_parameters            ; positive: not a variable, VAR or end
	moveq	#31,d1                          ; type in bits 0-3, bit 4 = two-byte variable index
	and.w	d1,d0                           ; keep type and the word-index bit
	bclr	#$4,d0                          ; bit 4: two-byte index
	beq.s	.read_value_index_low
	move.b	(a5)+,d1                        ; high byte of the index
	asl.w	#8,d1
.read_value_index_low:
	move.b	(a5)+,d1                        ; d1 = variable index
	add.w	d0,d0                           ; word table index
	move.w	value_param_ir_table(pc,d0.w),d0 ; offset of the handler for this type
	jsr	value_param_ir_table(pc,d0.w)   ; emit the entry for this type
	addq.l	#1,a5                           ; skip the separator
	bra.s	.next_value_param
value_param_ir_table:
	dc.w	emit_value_param_float-value_param_ir_table
	dc.w	emit_value_param_string-value_param_ir_table
	dc.w	emit_value_param_int-value_param_ir_table
	dc.w	emit_value_param_bool-value_param_ir_table
	dc.w	$0000
	dc.w	$0000
	dc.w	$0000
	dc.w	$0000
	dc.w	emit_value_param_word-value_param_ir_table
	dc.w	emit_value_param_byte-value_param_ir_table

parse_var_parameters:
	cmpi.b	#$32,d0                         ; $32 = VAR
	bne.s	reverse_parameter_ir
.next_var_param:
	move.b	(a5)+,d0                        ; next VAR parameter token
	bpl.s	reverse_parameter_ir            ; positive: end of the list
	moveq	#31,d1                          ; keep type and the word-index bit
	and.w	d1,d0
	bclr	#$4,d0                          ; bit 4: two-byte index
	beq.s	.read_var_index_low
	move.b	(a5)+,d1                        ; high byte of the index
	asl.w	#8,d1
.read_var_index_low:
	move.b	(a5)+,d1                        ; low byte of the index
	btst	#$2,d0                          ; bit 2 = array: skip the "()" byte
	beq.s	.emit_var_entry
	addq.l	#1,a5                           ; skip it
.emit_var_entry:
	add.w	d0,d0                           ; word table index
	move.w	var_param_ir_table(pc,d0.w),d0  ; offset of the handler for this type
	jsr	var_param_ir_table(pc,d0.w)     ; emit the entry for this type
	addq.l	#1,a5                           ; skip the separator
	bra.s	.next_var_param
var_param_ir_table:
	dc.w	emit_var_param_float-var_param_ir_table
	dc.w	emit_var_param_string-var_param_ir_table
	dc.w	emit_var_param_int-var_param_ir_table
	dc.w	emit_var_param_bool-var_param_ir_table
	dc.w	emit_var_param_float_array-var_param_ir_table
	dc.w	emit_var_param_string_array-var_param_ir_table
	dc.w	emit_var_param_int_array-var_param_ir_table
	dc.w	emit_var_param_bool_array-var_param_ir_table
	dc.w	emit_var_param_word-var_param_ir_table
	dc.w	emit_var_param_byte-var_param_ir_table
	dc.w	$0000
	dc.w	$0000
	dc.w	emit_var_param_word_array-var_param_ir_table
	dc.w	emit_var_param_byte_array-var_param_ir_table

;------------------------------------------------------------------------------
; Reverses the longs (IR code word + index word) written since the start pointer on the stack, so the
; parameters are taken from the stack last argument first. Exit: a4 unchanged (end of IR).
;------------------------------------------------------------------------------
reverse_parameter_ir:
	movea.l	(sp)+,a0                        ; a0 = start of the parameter IR
	movea.l	a4,a1                           ; keep the end
.swap_loop:
	cmpa.l	a0,a4                           ; pointers met?
	bls.s	.reversed
	move.l	-(a4),d0                        ; swap the longs at both ends
	move.l	(a0),(a4)
	move.l	d0,(a0)+
	bra.s	.swap_loop
.reversed:
	movea.l	a1,a4                           ; a4 back to the end of the IR
	rts

no_procedure_parameters:
	tst.w	routine_gosub_frame_flag        ; GOSUB frame wanted (option P)?
	beq.s	.no_frame_call
	move.w	#$279,(a4)+                     ; library GOSUB ($279)
.no_frame_call:
	rts

emit_value_param_int:
	move.w	#$8165,(a4)+                    ; IR $8165: value parameter %
	bra.s	emit_param_var_index

emit_value_param_bool:
	move.w	#$8166,(a4)+                    ; IR $8166: value parameter !
	bra.s	emit_param_var_index

emit_value_param_word:
	move.w	#$8167,(a4)+                    ; IR $8167: value parameter &
	bra.s	emit_param_var_index

emit_value_param_byte:
	move.w	#$8168,(a4)+                    ; IR $8168: value parameter |
	bra.s	emit_param_var_index

emit_value_param_string:
	move.w	#$8164,(a4)+                    ; IR $8164: value parameter $
	bra.s	emit_param_var_index

emit_value_param_float:
	move.w	#$8163,(a4)+                    ; IR $8163: value parameter #

emit_param_var_index:
	move.w	d1,(a4)+                        ; variable index
	rts

emit_var_param_int:
	move.w	#$816b,(a4)+                    ; IR $816b: VAR parameter %
	bra.s	emit_param_var_index

emit_var_param_bool:
	move.w	#$816c,(a4)+                    ; IR $816c: VAR parameter !
	bra.s	emit_param_var_index

emit_var_param_word:
	move.w	#$816d,(a4)+                    ; IR $816d: VAR parameter &
	bra.s	emit_param_var_index

emit_var_param_byte:
	move.w	#$816e,(a4)+                    ; IR $816e: VAR parameter |
	bra.s	emit_param_var_index

emit_var_param_string:
	move.w	#$816a,(a4)+                    ; IR $816a: VAR parameter $
	bra.s	emit_param_var_index

emit_var_param_float:
	move.w	#$8169,(a4)+                    ; IR $8169: VAR parameter #
	bra.s	emit_param_var_index

emit_var_param_int_array:
	move.w	#$8171,(a4)+                    ; IR $8171: VAR parameter %()
	bra.s	emit_param_var_index

emit_var_param_bool_array:
	move.w	#$8172,(a4)+                    ; IR $8172: VAR parameter !()
	bra.s	emit_param_var_index

emit_var_param_word_array:
	move.w	#$8173,(a4)+                    ; IR $8173: VAR parameter &()
	bra.s	emit_param_var_index

emit_var_param_byte_array:
	move.w	#$8174,(a4)+                    ; IR $8174: VAR parameter |()
	bra.s	emit_param_var_index

emit_var_param_string_array:
	move.w	#$8170,(a4)+                    ; IR $8170: VAR parameter $()
	bra.s	emit_param_var_index

emit_var_param_float_array:
	move.w	#$816f,(a4)+                    ; IR $816f: VAR parameter #()
	bra.s	emit_param_var_index

;------------------------------------------------------------------------------
; Statement RETURN / ENDPROC (token 7). Emits the library RETURN ($27a) when the procedure used the GOSUB frame,
; otherwise writes rts ($4e75) straight into the code area. Marks the last call as END so the next PROCEDURE
; needs no END guard.
;------------------------------------------------------------------------------
stmt_return:
	bsr.w	shorten_branches                ; routine done: shorten its branches
	tst.w	routine_gosub_frame_flag        ; GOSUB frame in use?
	beq.s	.write_rts
	move.w	#$27a,(a4)+                     ; IR: call library RETURN
	clr.b	routine_gosub_frame_flag        ; frame closed
	bra.s	.mark_end_called
.write_rts:
	movea.l	code_write_pointer,a0
	move.w	#$4e75,(a0)+                    ; rts written straight to the code area
	move.l	a0,code_write_pointer           ; past the rts
.mark_end_called:
	move.w	#$3b,last_library_routine       ; pretend the last call was END ($3b)
	move.w	#$3b,statement_code_routine_word
	rts
msg_procedure_undefined:
	dc.b	'Procedure undefined',13,10,0
msg_function_undefined:
	dc.b	'Function undefined',13,10,0
msg_too_many_parameters:
	dc.b	'Parameter too much',13,10,0
msg_parameter_missing:
	dc.b	'Parameter missing',13,10,0
msg_parameter_must_be_string:
	dc.b	'Parameter should be string',13,10,0
msg_parameter_must_be_number:
	dc.b	'Parameter should be number',13,10,0
msg_wrong_variable_type:
	dc.b	'Variable type mismatch',13,10,0
	dc.b	$00

error_function_undefined:
	lea	msg_function_undefined(pc),a0
	bra.s	report_error_and_skip_line

error_procedure_undefined:
	lea	msg_procedure_undefined(pc),a0

;------------------------------------------------------------------------------
; Prints the source line number (print_line_number) and the message at a0 with Cconws, restores the statement
; stack pointer saved by the main loop (statement_sp) and continues with the next line (next_statement).
;------------------------------------------------------------------------------
report_error_and_skip_line:
	pea	(a0)                            ; message for Cconws
	bsr.w	print_line_number
	move.w	#$9,-(sp)
	trap	#1                              ; Cconws
	movea.l	statement_sp(pc),sp             ; back to the main loop's stack
	bra.w	next_statement

error_too_many_parameters:
	lea	msg_too_many_parameters(pc),a0
	bra.s	report_error_and_skip_line

error_parameter_missing:
	lea	msg_parameter_missing(pc),a0
	bra.s	report_error_and_skip_line

error_parameter_must_be_string:
	lea	msg_parameter_must_be_string(pc),a0
	bra.s	report_error_and_skip_line

error_parameter_must_be_number:
	lea	msg_parameter_must_be_number(pc),a0
	bra.s	report_error_and_skip_line

error_wrong_variable_type:
	lea	msg_wrong_variable_type(pc),a0
	bra.s	report_error_and_skip_line

;------------------------------------------------------------------------------
; Expression tokens FN ($9e) and @ ($9f): call of a FUNCTION / DEFFN.
; Next byte: bit 0 = string function, bit 4 = two-byte function number. Looks the definition up in
; function_line_table (numeric) or string_function_line_table (string); a numeric FUNCTION marked "$X" or
; "$F%" in the line after its header returns an integer, so $8006 (int to float) is appended. Arguments are
; parsed against the header by parse_call_arguments. Writes IR $818d (numeric) / $818e (string), the function
; number, then optionally $8006.
;------------------------------------------------------------------------------
parse_function_call:
	clr.w	-(sp)                           ; third word: conversion after the call (0 = none)
	moveq	#0,d0
	move.b	(a5)+,d2                        ; d2 = type byte of the function identifier
	btst	#$4,d2                          ; bit 4: two-byte function number
	beq.s	.read_function_number_low
	move.b	(a5)+,d0                        ; high byte of the number
	asl.w	#8,d0
.read_function_number_low:
	move.b	(a5)+,d0                        ; low byte
	move.w	d0,-(sp)                        ; second word: function number
	asl.w	#2,d0                           ; 4 bytes per table entry
	movea.l	function_line_table,a0          ; var_1187e = numeric function definition lines
	move.w	#$818d,-(sp)                    ; IR $818d: call numeric function
	lsr.b	#1,d2                           ; bit 0: string function
	bcc.s	.look_up_definition
	movea.l	string_function_line_table,a0   ; var_11882 = string function definition lines
	move.w	#$818e,(sp)                     ; IR $818e: call string function
.look_up_definition:
	movea.l	0(a0,d0.w),a0                   ; a0 = the definition's header line
	move.l	a0,d0
	beq.s	error_function_undefined        ; no definition
	movea.l	a0,a1                           ; a1 = the header line too
	addq.l	#2,a0                           ; skip the line length
	cmpi.w	#$72,(a0)+                      ; $72 = token word of DEFFN: no option line to check
	beq.s	.skip_header_name
	adda.w	(a1)+,a1                        ; a1 = the line after the header
	cmpi.w	#$336,(a1)+                     ; next line a "$" option line?
	bne.s	.skip_header_name
.skip_option_spaces:
	moveq	#-33,d1                         ; upper-case the option letter
	and.b	(a1)+,d1
	cmpi.b	#$20,d1                         ; skip spaces
	beq.s	.skip_option_spaces
	cmpi.b	#$58,d1                         ; "$X"
	beq.s	.int_result
	cmpi.b	#$46,d1                         ; "$F%": function returns an integer
	bne.s	.skip_header_name
	cmpi.b	#$25,(a1)+                      ; followed by '%'?
	bne.s	.skip_header_name
.int_result:
	cmpi.w	#$818e,(sp)                     ; IR $818e: call string function
	beq.s	.skip_header_name
	move.w	#$8006,4(sp)                    ; IR $8006 after the call: int result to float
.skip_header_name:
	cmpi.b	#$f0,(a0)+                      ; skip the function name in the header
	bcs.s	.skip_name_low_byte             ; below $f0: one-byte index
	addq.l	#1,a0                           ; skip the high byte of the name index
.skip_name_low_byte:
	addq.l	#1,a0                           ; skip the low byte
	cmpi.b	#$23,(a0)+                      ; $23 = "(": header has parameters
	beq.s	.with_arguments
	cmpi.b	#$23,(a5)                       ; call has arguments but the header has none
	beq.w	error_too_many_parameters
	cmpi.b	#$9d,(a5)                       ; $9d: '(' of a string argument
	beq.w	error_too_many_parameters
.write_call:
	move.w	(sp)+,(a4)+                     ; IR call code
	move.w	(sp)+,(a4)+                     ; function number
	move.w	(sp)+,(a4)+                     ; conversion word
	bne.s	.done                           ; drop the conversion word when it is 0
	subq.l	#2,a4
.done:
	rts
.with_arguments:
	cmpi.b	#$23,(a5)+                      ; the call needs '(' too
	beq.s	.parse_arguments
	cmpi.b	#$9d,-$1(a5)                    ; or $9d, '(' before a string argument
	bne.w	error_parameter_missing
.parse_arguments:
	subq.l	#1,a5                           ; back to the '('
	bsr.s	parse_call_arguments            ; arguments against the formal list
	addq.l	#1,a5                           ; skip the ')'
	bra.s	.write_call

;------------------------------------------------------------------------------
; Statements GOSUB / @ / CALL of a procedure (tokens $3c-$3e). Reads the procedure number, looks up its header
; in procedure_line_table, parses the arguments (parse_call_arguments) and writes IR $80b3 + procedure number.
;------------------------------------------------------------------------------
stmt_gosub:
	move.w	(a5)+,d0                        ; procedure number
	move.w	d0,-(sp)                        ; keep it for the IR
	asl.w	#2,d0                           ; 4 bytes per table entry
	movea.l	procedure_line_table,a0         ; var_11872 = procedure header lines
	movea.l	0(a0,d0.w),a0                   ; a0 = the header line
	move.l	a0,d0
	beq.w	error_procedure_undefined       ; no PROCEDURE line
	addq.l	#6,a0                           ; first byte after the procedure name
	cmpi.b	#$46,(a0)                       ; header has no parameters?
	bne.s	.parse_procedure_arguments
	cmpi.b	#$46,(a5)                       ; then the call must have none either
	beq.s	.write_procedure_call
	bra.w	error_too_many_parameters
.parse_procedure_arguments:
	bsr.s	parse_call_arguments            ; arguments against the formal list
.write_procedure_call:
	move.w	#$80b3,(a4)+                    ; IR $80b3: call procedure
	move.w	(sp)+,(a4)+                     ; procedure number
	rts

;------------------------------------------------------------------------------
; Parses the actual arguments of a procedure/function call against the formal list.
; Entry: a0 = formal parameter list in the header, a5 at the "(" of the call.
; The tokeniser writes "(" and "," as $9d / $9c (bit 7 set) in front of a string argument, $23 / $21 otherwise,
; so the sign of the separator tells the argument kind. Per value parameter: float -> parse_expression + $8002
; (push float), string -> parse_expression + $8018 (push string), int -> parse_int_and_push, bool ->
; parse_expression + $80ef + $8027, word/byte -> parse_int_and_push_word. After VAR ($32) continues in
; parse_var_arguments. Errors: too many / missing parameters, must be string / number.
;------------------------------------------------------------------------------
parse_call_arguments:
	pea	(a0)                            ; keep the formal list pointer
	cmpi.b	#$46,(a5)+                      ; call without arguments?
	beq.w	error_parameter_missing
.next_argument:
	move.b	-$1(a5),d1                      ; d1 = separator before this argument
	movea.l	(sp)+,a0                        ; a0 = next formal parameter
	move.b	(a0)+,d0                        ; next formal parameter
	bpl.s	.end_of_formal_list
	cmpi.b	#$20,d1                         ; ")": call ended early
	beq.w	error_parameter_missing
	andi.w	#$1f,d0                         ; type, bit 4 = two-byte index
	bclr	#$4,d0                          ; two-byte index?
	beq.s	.check_argument_type
	addq.l	#1,a0                           ; skip its high byte
.check_argument_type:
	pea	2(a0)                           ; keep the next formal parameter
	subq.b	#1,d0                           ; type 1 = string
	beq.s	.string_argument
	tst.b	d1                              ; numeric parameter but string argument
	bmi.w	error_parameter_must_be_number
	tst.b	d0                              ; type 0 = float
	bmi.s	.float_argument
	subq.b	#2,d0                           ; type 2 = int
	bmi.s	.int_argument
	beq.s	.bool_argument                  ; type 3 = bool
	bsr.w	parse_int_and_push_word         ; types 8/9 (word, byte): pushed as a word
	bra.s	.next_argument
.int_argument:
	bsr.w	parse_int_and_push              ; type 2 = int
	bra.s	.next_argument
.float_argument:
	bsr.w	parse_expression
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	bra.s	.next_argument
.string_argument:
	tst.b	d1
	bpl.w	error_parameter_must_be_string
	bsr.w	parse_expression
	move.w	#$8018,(a4)+                    ; IR $8018: push string
	bra.s	.next_argument
.bool_argument:
	bsr.w	parse_expression
	move.w	#$80ef,(a4)+                    ; IR $80ef: make boolean
	move.w	#$8027,(a4)+                    ; IR $8027: push word
	bra.s	.next_argument
.end_of_formal_list:
	cmpi.b	#$32,d0                         ; $32 = VAR: VAR parameters follow
	beq.s	start_var_arguments
	subq.l	#1,a5
	cmpi.b	#$20,(a5)                       ; end of formal list: the call must end too
	bne.w	error_too_many_parameters

store_parameter_list_end:
	move.l	a0,parameter_list_end           ; where the formal list ended
	rts
parameter_list_end:
	dc.w	$0000,$0000                     ; end of the formal parameter list

start_var_arguments:
	subq.l	#1,a5                           ; back to the separator before the VAR arguments

;------------------------------------------------------------------------------
; VAR arguments: each actual argument must be a variable (or array) of the same type as the formal VAR
; parameter (a one-byte or two-byte index may differ). Writes $8175-$817a (scalars # $ % ! & |) or
; $817b-$8180 (arrays) + variable index.
;------------------------------------------------------------------------------
parse_var_arguments:
	cmpi.b	#$20,(a5)+                      ; ')': no more arguments in the call
	beq.s	.call_list_ended
	move.b	(a0)+,d0                        ; next formal VAR parameter
	bpl.s	.formal_list_ended              ; positive: end of the formal list
	andi.w	#$1f,d0                         ; type, bit 4 = two-byte index
	bclr	#$4,d0                          ; two-byte index?
	beq.s	.dispatch_on_var_type
	addq.l	#1,a0                           ; skip its high byte
.dispatch_on_var_type:
	move.w	d0,d1                           ; d1 = formal type
	add.w	d0,d0                           ; word table index
	move.w	var_argument_ir_table(pc,d0.w),d2 ; offset of the handler
	jmp	var_argument_ir_table(pc,d2.w)  ; to the handler for the type
.formal_list_ended:
	subq.l	#2,a5                           ; back to the separator
	cmpi.b	#$20,(a5)                       ; the call must end too
	bne.w	error_too_many_parameters
	bra.s	store_parameter_list_end
.call_list_ended:
	subq.l	#1,a5                           ; back to the ')'
	cmpi.b	#$20,-$1(a0)                    ; the formal list must end here too
	bne.w	error_parameter_missing
	bra.s	store_parameter_list_end
var_argument_ir_table:
	dc.w	.float_var-var_argument_ir_table
	dc.w	.string_var-var_argument_ir_table
	dc.w	.int_var-var_argument_ir_table
	dc.w	.bool_var-var_argument_ir_table
	dc.w	.float_array-var_argument_ir_table
	dc.w	.string_array-var_argument_ir_table
	dc.w	.int_array-var_argument_ir_table
	dc.w	.bool_array-var_argument_ir_table
	dc.w	.word_var-var_argument_ir_table
	dc.w	.byte_var-var_argument_ir_table
	dc.w	.bad_type-var_argument_ir_table
	dc.w	.bad_type-var_argument_ir_table
	dc.w	.word_array-var_argument_ir_table
	dc.w	.byte_array-var_argument_ir_table
	dc.w	.bad_type-var_argument_ir_table
	dc.w	.bad_type-var_argument_ir_table
.bad_type:
	illegal                                 ; types without a VAR form: cannot happen
.string_var:
	move.w	#$8176,d6                       ; IR $8176: VAR argument $
	bra.s	.check_scalar_type
.bool_var:
	move.w	#$8178,d6                       ; IR $8178: VAR argument !
	bra.s	.check_scalar_type
.byte_var:
	move.w	#$817a,d6                       ; IR $817a: VAR argument |
	bra.s	.check_scalar_type
.word_var:
	move.w	#$8179,d6                       ; IR $8179: VAR argument &
	bra.s	.check_scalar_type
.int_var:
	move.w	#$8177,d6                       ; IR $8177: VAR argument %
	bra.s	.check_scalar_type
.float_var:
	move.w	#$8175,d6                       ; IR $8175: VAR argument #
.check_scalar_type:
	move.b	(a0)+,d0                        ; skip the formal's index
	moveq	#31,d2                          ; actual argument's type bits
	and.b	(a5)+,d2
	eor.b	d1,d2                           ; same type?
	beq.s	.read_scalar_index_low
	eori.b	#$10,d2                         ; differs only in the two-byte index bit
	bne.w	error_wrong_variable_type
	move.b	(a5)+,-(sp)                     ; two-byte index: high byte into d2
	move.w	(sp)+,d2
.read_scalar_index_low:
	move.b	(a5)+,d2                        ; low byte of the index
.write_var_argument:
	move.w	d6,(a4)+                        ; IR: VAR argument code
	move.w	d2,(a4)+                        ; variable index
	addq.l	#1,a0                           ; skip the formal's separator
	bra.w	parse_var_arguments
.byte_array:
	move.w	#$8180,d6                       ; IR $8180: VAR argument |()
.check_array_type:
	move.b	(a0)+,d0                        ; skip the formal's index
	moveq	#31,d2                          ; actual argument's type bits
	and.b	(a5)+,d2
	eor.b	d1,d2                           ; same type?
	beq.s	.read_array_index_low
	eori.b	#$10,d2                         ; differs only in the two-byte index bit
	bne.w	error_wrong_variable_type
	move.b	(a5)+,-(sp)                     ; two-byte index: high byte into d2
	move.w	(sp)+,d2
.read_array_index_low:
	move.b	(a5)+,d2                        ; low byte of the index
	addq.l	#1,a5                           ; skip the "()" byte of the array
	addq.l	#1,a0                           ; skip the formal's '()' byte
	bra.s	.write_var_argument
.float_array:
	move.w	#$817b,d6                       ; IR $817b: VAR argument #()
	bra.s	.check_array_type
.string_array:
	move.w	#$817c,d6                       ; IR $817c: VAR argument $()
	bra.s	.check_array_type
.int_array:
	move.w	#$817d,d6                       ; IR $817d: VAR argument %()
	bra.s	.check_array_type
.bool_array:
	move.w	#$817e,d6                       ; IR $817e: VAR argument !()
	bra.s	.check_array_type
.word_array:
	move.w	#$817f,d6                       ; IR $817f: VAR argument &()
	bra.s	.check_array_type

;------------------------------------------------------------------------------
; Tokens and statements the compiler does not handle: illegal (the compiler stops with an exception).
;------------------------------------------------------------------------------
unsupported_statement_token:
	illegal

;------------------------------------------------------------------------------
; Label definition line (token $3f): stores the current code offset in label_address_table.
;------------------------------------------------------------------------------
stmt_label:
	moveq	#0,d0                           ; clear the label number
	btst	#$4,(a5)+                       ; bit 4 of the type: two-byte label number
	beq.s	.read_label_low
	move.b	(a5)+,d0                        ; high byte
	asl.w	#8,d0
.read_label_low:
	move.b	(a5)+,d0                        ; low byte
	asl.w	#2,d0                           ; 4 bytes per table entry
	movea.l	label_address_table,a0
	movea.l	code_write_pointer,a1           ; a1 = current code offset
	suba.l	code_buffer_start,a1
	move.l	a1,0(a0,d0.w)                   ; label address
	rts

;------------------------------------------------------------------------------
; GOTO label: writes IR $80cf + label number. Also used after RESUME label.
;------------------------------------------------------------------------------
stmt_goto:
	move.w	#$80cf,(a4)+                    ; IR $80cf: jump to label
	moveq	#0,d0
	btst	#$4,(a5)+                       ; bit 4: two-byte label number
	beq.s	.read_goto_label_low
	move.b	(a5)+,d0                        ; high byte
	asl.w	#8,d0
.read_goto_label_low:
	move.b	(a5)+,d0                        ; low byte
	move.w	d0,(a4)+                        ; label number
	rts

;------------------------------------------------------------------------------
; Statement ENDFUNC: emits the library ENDFUNC ($293), or, when option_f_flag is set, only records it as the
; last call.
;------------------------------------------------------------------------------
stmt_endfunc:
	bsr.w	shorten_branches
	move.w	#$293,d0                        ; library ENDFUNC ($293)
	tst.b	option_f_flag                   ; option F set?
	beq.s	.emit_endfunc
	move.w	d0,last_library_routine         ; only record it as the last call
	move.w	d0,statement_code_routine_word
	rts
.emit_endfunc:
	move.w	d0,(a4)+                        ; IR: call ENDFUNC
	rts
select_compare_size:
	dc.b	$00                             ; option $S% 0, $S& 1, $S| -1: CASE compare size
select_chain_case_exits:
	dc.b	$00                             ; option $S< set, $S> clear: chain the CASE exits

;------------------------------------------------------------------------------
; Statement SELECT with a string (token $2c): parses the string and calls SELSTR ($334), then as SELECT.
;------------------------------------------------------------------------------
stmt_select_string:
	bsr.w	parse_expression                ; the selector string
	move.w	#$334,(a4)+                     ; library SELSTR ($334)
	bra.s	emit_select_jump

;------------------------------------------------------------------------------
; Statement SELECT (token $0c): parses the integer selector into d0, then emit_select_jump.
;------------------------------------------------------------------------------
stmt_select:
	bsr.w	parse_integer_expression        ; the selector into d0

;------------------------------------------------------------------------------
; Writes IR $8049 with a placeholder long ($0f0f0f0f): a jump to the CASE tests that ENDSELECT generates.
; Generates the line, then turns the statement return slot into a SELECT block frame: code offset of the jump
; and the marker word $4d. If the next line is a CASE it is processed at once (no jump in front of it).
; Ends with bra next_statement (the frame stays on the stack).
;------------------------------------------------------------------------------
emit_select_jump:
	move.w	#$8049,(a4)+                    ; IR $8049: jmp to the CASE tests, target patched by ENDSELECT
	move.l	#$f0f0f0f,(a4)+
	bsr.w	optimise_generate_and_append    ; code for the selector and the jump
	move.l	code_write_pointer,d0
	sub.l	code_buffer_start,d0
	subq.l	#6,d0                           ; offset of the jmp (6 bytes) in the code
	move.l	d0,(sp)                         ; frame: offset of the jump target (return address slot)
	move.w	#$4d,-(sp)                      ; block marker $4d = SELECT
	movea.l	next_line_pointer(pc),a5        ; look at the next line
	addq.l	#2,a5                           ; skip the line length
	cmpi.w	#$70,(a5)                       ; $70 = token word of CASE
	beq.s	select_enter_first_case
	bra.w	next_statement                  ; frame stays on the stack

;------------------------------------------------------------------------------
; Statement CONT (command 317) inside a SELECT block: if the next line is CASE (token word $70) or
; DEFAULT ($1e) that line is taken over at once, so control falls into the next CASE body without a
; jump; otherwise returns and nothing is written. Entry a5 = token pointer after the command word.
;------------------------------------------------------------------------------
stmt_cont_in_select:
	subq.l	#4,a5                           ; back to the line length word; a5 = next line
	adda.w	(a5)+,a5
	cmpi.w	#$70,(a5)                       ; $70 = token word of CASE
	beq.s	take_over_case_line
	cmpi.w	#$1e,(a5)                       ; $1e = token word of DEFAULT
	beq.s	take_over_case_line
	rts

;------------------------------------------------------------------------------
; Reached from emit_select_jump when the line after SELECT is a CASE: makes room for the CASE frame
; long on the stack and falls into take_over_case_line.
;------------------------------------------------------------------------------
select_enter_first_case:
	subq.l	#4,sp                           ; room for the CASE frame long

;------------------------------------------------------------------------------
; Consumes the CASE/DEFAULT line at a5 (advances next_line_pointer and source_line_number), puts a nop
; ($4e71) into statement_code_buffer instead of the jump to ENDSELECT, then opens the CASE frame
; (open_case_block).
;------------------------------------------------------------------------------
take_over_case_line:
	move.w	-(a5),d0                        ; consume the CASE line
	ext.l	d0                              ; line length
	add.l	d0,next_line_pointer            ; skip the line
	addq.w	#1,source_line_number           ; count it
	lea	statement_code_buffer,a1
	move.w	#$4e71,(a1)+                    ; nop instead of the jump to ENDSELECT
	addq.l	#4,a5                           ; skip length and command: a5 = the CASE values
	bra.s	open_case_block

;------------------------------------------------------------------------------
; Statements CASE and DEFAULT (tokens $38, $0f): the previous CASE body ends with jmp $0f0f0f0f (to the end of
; the SELECT, patched by ENDSELECT), put into statement_code_buffer. Then opens a CASE frame: code offset of the
; body, pointer to the case values, marker word $4e.
;------------------------------------------------------------------------------
stmt_case:
	lea	statement_code_buffer,a1
	move.w	#$4ef9,(a1)+                    ; jmp abs.l (placeholder target)
	move.l	#$f0f0f0f,(a1)+

open_case_block:
	move.l	code_write_pointer,d4           ; d4 = code offset of the CASE body (its jmp or nop)
	sub.l	code_buffer_start,d4
	move.l	d4,(a6)+                        ; a6 = fixup list of code positions
	move.l	d4,(sp)                         ; frame: body offset (return address slot)
	pea	-$2(a5)                         ; frame: pointer to the CASE command word
	move.w	#$4e,-(sp)                      ; block marker $4e = CASE
	bra.w	copy_statement_code

;------------------------------------------------------------------------------
; Statement ENDSELECT. Emits jmp $0f0f0f0f over the tests, patches the SELECT jump to point after it and
; generates the CASE tests from the frames on the stack, in source order: for each value cmp with d0
; (emit_case_compare) and beq.w to the body; "x TO y" gives cmp x / blt.s / cmp y / ble.w, "TO y" ble.w,
; "x TO" bge.w; DEFAULT gives bra.w. Then pops the frames and patches every CASE exit jump to the end
; (chained through each other when select_chain_case_exits is set) and the jump over the tests.
;------------------------------------------------------------------------------
stmt_endselect:
	moveq	#0,d5                           ; d3's upper bytes not known to be zero
	movea.l	code_write_pointer,a1           ; a1 = end of the code: tests written in place
	move.l	a1,d4                           ; d4 = the jmp over the tests
	move.w	#$4ef9,(a1)+                    ; jmp abs.l
	move.l	#$f0f0f0f,(a1)+
	sub.l	code_buffer_start,d4            ; d4 = its code offset
	move.l	d4,(a6)+                        ; into the fixup list
	addq.l	#6,d4                           ; d4 = offset after it: start of the tests
	lea	-$4(sp),a4                      ; a4 + 8 = the first frame's marker
.find_select_frame:
	addq.l	#8,a4                           ; find the SELECT frame (skip CASE frames)
	move.w	(a4)+,d0
	cmpi.w	#$4e,d0                         ; marker $4e = CASE frame
	beq.s	.find_select_frame
	movea.l	(a4),a0                         ; a0 = the SELECT jmp in the code
	adda.l	code_buffer_start,a0
	move.l	d4,2(a0)                        ; SELECT jmp now goes to the tests
.next_case_frame:
	subq.l	#2,a4                           ; back to the marker; walk to newer frames
	movea.l	-(a4),a3                        ; a3 = CASE body
	adda.l	code_buffer_start,a3
	movea.l	-(a4),a5                        ; a5 = CASE values
	cmpa.l	sp,a4                           ; below sp: all CASE frames done
	bcs.s	.tests_done
	cmpi.w	#$70,(a5)+                      ; CASE line (otherwise DEFAULT)
	beq.s	.next_case_value
	move.w	#$6000,(a1)+                    ; DEFAULT: bra.w body
	bra.s	.write_branch
.next_case_value:
	move.b	(a5)+,d1                        ; d1 = next token in the value list
	bpl.s	.value_not_constant             ; positive: not a constant or variable
	bsr.w	emit_case_compare               ; cmp of d0 with this value
	cmpi.b	#$47,(a5)                       ; $47 = TO
	beq.s	.value_range
	move.w	#$6700,(a1)+                    ; beq.w body
.write_branch:
	move.l	a1,d0                           ; d0 = offset of the displacement word
	sub.l	code_buffer_start,d0
	subq.l	#2,d0
	move.l	d0,(a6)+                        ; record the branch position in the fixup list
	move.l	a3,d0                           ; displacement from the word to the body
	sub.l	a1,d0
	addq.w	#2,d0                           ; +2: past the nop
	cmpi.w	#$4e71,(a3)                     ; body starts after a nop (2 bytes) or a jmp (6 bytes)
	beq.s	.store_displacement
	addq.w	#4,d0                           ; +6: past the jmp
.store_displacement:
	move.w	d0,(a1)+
	bra.s	.next_case_value
.value_not_constant:
	cmpi.b	#$46,d1                         ; $46 = end of the value list
	beq.s	.next_case_frame
	bcs.s	.next_case_value                ; below $46: separator, next value
	move.b	(a5)+,d1                        ; TO y: the upper value
	bsr.w	emit_case_compare
	move.w	#$6f00,(a1)+                    ; ble.w body ("CASE TO y")
	bra.s	.write_branch
.value_range:
	addq.l	#1,a5                           ; skip the TO
	move.b	(a5)+,d1                        ; the upper value
	bpl.s	.open_range                     ; none: x TO
	move.l	a1,d0                           ; address of the blt.s
	move.w	#$6d00,(a1)+                    ; blt.s over the upper test (displacement patched below)
	movea.l	a1,a2                           ; a2 = after it
	sub.l	code_buffer_start,d0            ; into the fixup list
	move.l	d0,(a6)+
	bsr.s	emit_case_compare               ; cmp of d0 with the upper value
	move.l	a1,d0                           ; displacement past the cmp and the ble.w
	sub.l	a2,d0
	addq.b	#4,d0
	move.b	d0,-(a2)                        ; into the blt.s
	move.w	#$6f00,(a1)+                    ; ble.w body
	bra.s	.write_branch
.open_range:
	subq.l	#1,a5                           ; back to the token after TO
	move.w	#$6c00,(a1)+                    ; bge.w body ("x TO")
	bra.s	.write_branch
.tests_done:
	move.l	a1,d0                           ; d0 = offset of the end of the tests
	sub.l	code_buffer_start,d0
	move.l	d0,d3                           ; d3 = chain target: the end
	addq.l	#4,sp                           ; drop the return address
.patch_case_exits:
	cmpi.w	#$4e,(sp)+                      ; pop the CASE frames
	bne.s	.select_frame
	movem.l	(sp)+,a2-a3                     ; a2 = values pointer, a3 = body offset
	adda.l	code_buffer_start,a3            ; a3 = the body's jmp in the code
	cmpi.w	#$4e71,(a3)+                    ; first CASE has a nop, nothing to patch
	beq.s	.patch_case_exits
	tst.b	select_chain_case_exits         ; option $S<: chain the exits
	beq.s	.exit_to_end
	move.l	d3,(a3)                         ; chain: this exit jumps to the next exit jmp
	move.l	a3,d3                           ; the next one chains to this jmp
	sub.l	code_buffer_start,d3
	subq.l	#2,d3                           ; offset of the jmp opcode
	bra.s	.patch_case_exits
.exit_to_end:
	move.l	d0,(a3)+                        ; exit jumps straight to the end
	bra.s	.patch_case_exits
.select_frame:
	addq.l	#4,sp                           ; drop the SELECT jmp's offset
	movea.l	code_write_pointer,a0           ; a0 = the jmp over the tests
	move.l	d0,2(a0)                        ; patch the jmp over the tests
	move.l	a1,code_write_pointer           ; the tests stay in the code
	bra.w	next_statement

;------------------------------------------------------------------------------
; Emits a compare of d0 with one CASE value. Entry: d1 = value token, a5 after it, a1 = code pointer.
; Constants: tst.l d0, moveq + cmp.l, cmpi.l, or cmpi.w when select_compare_size is set ($S& / $S|).
; Variables: int (tokens $e0-$e7 all taken as %), word & and byte | variables, direct or through a pointer
; (negative offset). d5 <> 0 means d3 is known to hold zero in its upper bytes.
;------------------------------------------------------------------------------
emit_case_compare:
	cmpi.b	#$e0,d1                         ; variable token ($e0 and up)?
	bcc.s	.variable
	lsr.b	#1,d1                           ; bit 0 of the token: a byte to skip
	bcc.s	.read_constant
	addq.l	#1,a5                           ; skip it (meaning not worked out)
.read_constant:
	move.l	(a5)+,d2                        ; d2 = the constant
	beq.s	.compare_zero                   ; zero: tst.l d0
	tst.b	select_compare_size             ; option $S& / $S|: compare as word?
	bne.s	.compare_word_constant
	move.b	d2,d3                           ; d3 = the byte sign-extended
	ext.w	d3
	ext.l	d3
	cmp.l	d2,d3                           ; fits a moveq?
	bne.s	.compare_long_constant
	tst.b	d3                              ; negative: use d2
	bmi.s	.moveq_negative
	moveq	#1,d5                           ; d3's upper bytes are now zero
	move.b	#$76,(a1)+                      ; moveq #n,d3
	move.b	d3,(a1)+                        ; the value
	move.w	#$b083,(a1)+                    ; cmp.l d3,d0
	rts
.moveq_negative:
	move.b	#$74,(a1)+                      ; moveq #n,d2
	move.b	d3,(a1)+                        ; the value
	move.w	#$b082,(a1)+                    ; cmp.l d2,d0
	rts
.compare_long_constant:
	move.w	#$c80,(a1)+                     ; cmpi.l #n,d0
	move.l	d2,(a1)+                        ; the value
	rts
.compare_zero:
	move.w	#$4a80,(a1)+                    ; tst.l d0
	rts
.compare_word_constant:
	move.w	#$c40,(a1)+                     ; cmpi.w #n,d0
	move.w	d2,(a1)+                        ; the value
	rts
.variable:
	moveq	#0,d2                           ; d2 = index * 4
	bclr	#$4,d1                          ; bit 4: two-byte index
	beq.s	.read_case_index_low
	move.b	(a5)+,-(sp)                     ; high byte into d2
	move.w	(sp)+,d2
.read_case_index_low:
	move.b	(a5)+,d2                        ; low byte
	asl.w	#2,d2                           ; 4 bytes per table entry
	subi.b	#$e8,d1                         ; $e8 = word variable, above = byte
	bmi.w	.int_variable
	beq.s	.word_variable                  ; $e8 exactly
	movea.l	byte_variable_table,a0          ; var_1186a = byte variable offsets
	tst.b	d5                              ; d3's upper bytes known to be zero?
	bne.s	.load_byte_variable
	move.w	#$7600,(a1)+                    ; moveq #0,d3
.load_byte_variable:
	adda.w	d2,a0                           ; a0 = the variable's entry
	move.l	(a0),d0                         ; d0 low word = offset from a5
	move.w	(a0),d7                         ; high word negative?
	bmi.s	.byte_through_pointer           ; negative offset: variable reached through a pointer
	move.w	#$162d,(a1)+                    ; move.b d16(a5),d3
	move.w	d0,(a1)+                        ; offset
	move.w	#$b083,(a1)+                    ; cmp.l d3,d0
	rts
.byte_through_pointer:
	move.w	#$246d,(a1)+                    ; movea.l d16(a5),a2
	move.w	d0,(a1)+                        ; offset
	move.w	#$1412,(a1)+                    ; move.b (a2),d2
.compare_d2:
	tst.b	select_compare_size             ; option $S& / $S|?
	bne.s	.compare_d2_word
	move.w	#$b082,(a1)+                    ; cmp.l d2,d0
	rts
.compare_d2_word:
	move.w	#$b042,(a1)+                    ; cmp.w d2,d0
	rts
.word_variable:
	movea.l	word_variable_table,a0          ; var_11866 = word variable offsets
	adda.w	d2,a0                           ; a0 = the variable's entry
	move.l	(a0),d0                         ; d0 low word = offset from a5
	move.w	(a0),d7                         ; high word negative?
	bmi.s	.word_through_pointer           ; through a pointer
	tst.b	select_compare_size             ; option $S& / $S|: compare as word?
	bne.s	.compare_word_direct
	move.w	#$342d,(a1)+                    ; move.w d16(a5),d2
	move.w	d0,(a1)+                        ; offset
.extend_word:
	move.w	#$48c2,(a1)+                    ; ext.l d2
	bra.s	.compare_d2
.compare_word_direct:
	move.w	#$b06d,(a1)+                    ; cmp.w d16(a5),d0
	move.w	d0,(a1)+                        ; offset
	rts
.word_through_pointer:
	move.w	#$246d,(a1)+                    ; movea.l d16(a5),a2
	move.w	d0,(a1)+                        ; offset
	tst.b	select_compare_size             ; option $S& / $S|?
	bne.s	.compare_word_through_pointer
	move.w	#$3412,(a1)+                    ; move.w (a2),d2
	bra.s	.extend_word
.compare_word_through_pointer:
	move.w	#$b052,(a1)+                    ; cmp.w (a2),d0
	rts
.int_variable:
	movea.l	int_variable_table,a0           ; var_1184e = int variable offsets
	adda.w	d2,a0                           ; a0 = the variable's entry
	move.l	(a0),d0                         ; d0 low word = offset from a5
	move.w	(a0),d7                         ; high word negative?
	bmi.s	.int_through_pointer            ; through a pointer
	move.w	#$b0ad,(a1)+                    ; cmp.l d16(a5),d0
	move.w	d0,(a1)+                        ; offset
	rts
.int_through_pointer:
	move.w	#$246d,(a1)+                    ; movea.l d16(a5),a2
	move.w	d0,(a1)+                        ; offset
	move.w	#$b092,(a1)+                    ; cmp.l (a2),d0
	rts

;------------------------------------------------------------------------------
; RETURN value in a FUNCTION (token $11): integer expression when the function is "$F%"
; (function_returns_int_flag), float otherwise. Then the library RETURN ($27a), or rts written straight after
; generating the line.
;------------------------------------------------------------------------------
stmt_return_value:
	tst.b	function_returns_int_flag       ; $F%: the function returns an integer?
	beq.s	.float_result
	bsr.w	parse_integer_expression        ; integer result
	bra.s	.emit_return
.float_result:
	bsr.w	parse_expression                ; float result
.emit_return:
	tst.w	routine_gosub_frame_flag        ; GOSUB frame in use?
	beq.s	.emit_rts
	move.w	#$27a,(a4)+                     ; library RETURN ($27a)
	rts
.emit_rts:
	bsr.w	optimise_and_generate           ; code for the line
	move.w	#$4e75,(a1)+                    ; rts
	addq.l	#4,sp                           ; drop the return address
	bra.w	copy_statement_code

;------------------------------------------------------------------------------
; RETURN string in a FUNCTION (token $12): string expression, then the library RETSTR ($294).
;------------------------------------------------------------------------------
stmt_return_string:
	bsr.w	parse_expression                ; the string result
	move.w	#$294,(a4)+                     ; library RETSTR ($294)
	rts

;------------------------------------------------------------------------------
; Statement LOCAL: makes sure the library GOSUB frame is set up ($279), then IR $8181-$8186 (# $ % ! & |)
; + variable index per local variable.
;------------------------------------------------------------------------------
stmt_local:
	tst.b	routine_gosub_frame_flag        ; GOSUB frame already set up?
	bne.s	.next_local
	move.w	#$279,(a4)+                     ; library GOSUB ($279)
	st	routine_gosub_frame_flag        ; it is now
.next_local:
	move.b	(a5)+,d0                        ; variable token
	bpl.s	.locals_done                    ; positive: end of the list
	moveq	#31,d1                          ; keep type and the word-index bit
	and.w	d1,d0
	bclr	#$4,d0                          ; bit 4: two-byte index
	beq.s	.read_local_index_low
	move.b	(a5)+,d1                        ; high byte of the index
	asl.w	#8,d1
.read_local_index_low:
	move.b	(a5)+,d1                        ; low byte
	add.w	d0,d0                           ; word table index
	move.w	local_ir_table(pc,d0.w),d0      ; offset of the handler for this type
	jsr	local_ir_table(pc,d0.w)         ; emit the entry
	cmpi.b	#$46,(a5)+                      ; end of statement, or a comma
	bne.s	.next_local
.locals_done:
	rts
local_ir_table:
	dc.w	.local_float-local_ir_table
	dc.w	.local_string-local_ir_table
	dc.w	.local_int-local_ir_table
	dc.w	.local_bool-local_ir_table
	dc.w	$0000
	dc.w	$0000
	dc.w	$0000
	dc.w	$0000
	dc.w	.local_word-local_ir_table
	dc.w	.local_byte-local_ir_table
.local_int:
	move.w	#$8183,(a4)+                    ; IR $8183: LOCAL %
	bra.s	.write_index
.local_bool:
	move.w	#$8184,(a4)+                    ; IR $8184: LOCAL !
	bra.s	.write_index
.local_word:
	move.w	#$8185,(a4)+                    ; IR $8185: LOCAL &
	bra.s	.write_index
.local_byte:
	move.w	#$8186,(a4)+                    ; IR $8186: LOCAL |
	bra.s	.write_index
.local_string:
	move.w	#$8182,(a4)+                    ; IR $8182: LOCAL $
	bra.s	.write_index
.local_float:
	move.w	#$8181,(a4)+                    ; IR $8181: LOCAL #
.write_index:
	move.w	d1,(a4)+                        ; variable index
	rts

;------------------------------------------------------------------------------
; Statement ABSOLUTE var,address: IR from absolute_ir_table ($81c2-$81c7 for # $ % ! & |) and the variable
; index, written after the integer address expression.
;------------------------------------------------------------------------------
stmt_absolute:
	moveq	#31,d0                          ; variable token: keep the type bits
	and.b	(a5)+,d0
	moveq	#0,d1                           ; clear the index
	bclr	#$4,d0                          ; bit 4: two-byte index
	beq.s	.read_absolute_index_low
	move.b	(a5)+,d1                        ; high byte
	asl.w	#8,d1
.read_absolute_index_low:
	move.b	(a5)+,d1                        ; low byte
	add.w	d0,d0                           ; word table index
	move.w	d1,-(sp)                        ; keep the index
	move.w	absolute_ir_table(pc,d0.w),-(sp) ; and the IR code for the type
	addq.l	#1,a5                           ; skip the comma
	bsr.w	parse_integer_expression        ; the address
	move.l	(sp)+,(a4)+                     ; IR code and variable index
	rts
absolute_ir_table:
	dc.w	$81c2,$81c3,$81c4,$81c5,$0000,$0000,$0000,$0000
	dc.w	$81c6,$81c7

;------------------------------------------------------------------------------
; Statement CLR var,var,... (command 314). Per variable token: type in the low 5 bits (bit 4 = two-byte
; variable number), IR clr_ir_table[type] followed by the variable number. Loops until token $46 (end
; of statement).
;------------------------------------------------------------------------------
stmt_clr:
	move.b	(a5)+,d0                        ; variable token: type in bits 0-3, bit 4 = two-byte number
	moveq	#31,d1
	and.w	d1,d0
	bclr	#$4,d0
	beq.s	.read_clr_index_low             ; one-byte number
	move.b	(a5)+,d1                        ; high byte of the number
	asl.w	#8,d1
.read_clr_index_low:
	move.b	(a5)+,d1                        ; low byte
	add.w	d0,d0                           ; word table index
	move.w	clr_ir_table(pc,d0.w),(a4)+
	move.w	d1,(a4)+                        ; variable number
	cmpi.b	#$46,(a5)+                      ; $46 = end of statement, otherwise a comma follows
	bne.s	stmt_clr
	rts

; IR word per variable type for CLR: float $81c8, string $81c9, int $81ca, bool $81cb, (4-7 unused),
; word $81cc, byte $81cd.
clr_ir_table:
	dc.w	$81c8,$81c9,$81ca,$81cb,$0000,$0000,$0000,$0000
	dc.w	$81cc,$81cd

;------------------------------------------------------------------------------
; Statement RESTORE [label]: IR $81ce + the DATA position of the label (label_data_offsets), 0 without a label.
;------------------------------------------------------------------------------
stmt_restore:
	moveq	#0,d3                           ; no label: data position 0
	move.b	(a5)+,d0                        ; label token or end of statement
	bpl.s	.write_restore                  ; no label
	cmpi.b	#$f0,d0                         ; $f0 and up: two-byte label number
	bcs.s	.read_label_low
	move.b	(a5)+,d3                        ; high byte
	asl.w	#8,d3
.read_label_low:
	move.b	(a5)+,d3                        ; low byte
	asl.w	#2,d3                           ; 4 bytes per table entry
	movea.l	label_data_offsets,a2
	move.l	0(a2,d3.w),d3                   ; d3 = DATA position of the label
.write_restore:
	move.w	#$81ce,(a4)+                    ; IR $81ce: RESTORE (data position follows)
	move.l	d3,(a4)+                        ; data position
	rts

;------------------------------------------------------------------------------
; Statement RESUME: library RESUME ($353), or RESUNEXT ($354) for RESUME NEXT (sets resume_next_used_flag).
;------------------------------------------------------------------------------
stmt_resume:
	move.w	#$353,d0                        ; library RESUME ($353)
	cmpi.b	#$46,(a5)                       ; RESUME alone?
	beq.s	.write_resume_call
	move.w	#$354,d0                        ; library RESUNEXT ($354)
	st	resume_next_used_flag           ; RESUME NEXT was used
.write_resume_call:
	move.w	d0,(a4)+                        ; IR: library call
	rts

;------------------------------------------------------------------------------
; RESUME label (token $6a): library RESUMAIN ($355), then a GOTO to the label.
;------------------------------------------------------------------------------
stmt_resume_label:
	move.w	#$355,(a4)+                     ; library RESUMAIN ($355)

emit_resume_target:
	bra.w	stmt_goto

;------------------------------------------------------------------------------
; RESUME label (token $6b, label inside a procedure): library RESUPROC ($356), then a GOTO to the label.
;------------------------------------------------------------------------------
stmt_resume_label_in_procedure:
	move.w	#$356,(a4)+                     ; library RESUPROC ($356)
	bra.s	emit_resume_target

;------------------------------------------------------------------------------
; Statement ON n GOSUB proc1,proc2,...: integer expression, generates the line, then writes code directly:
; moveq #count,d7, a call of the library ONGOSUB ($34a) and per procedure the word $7f06 + procedure number
; ($7f06 is not a valid opcode: a marker resolved later).
;------------------------------------------------------------------------------
stmt_on_gosub:
	bsr.w	parse_integer_expression        ; the selector
	pea	(a5)                            ; keep the token pointer over code generation
	bsr.w	optimise_and_generate           ; code for the selector
	movea.l	a1,a2                           ; a2 = the moveq, count patched below
	move.w	#$7e00,(a1)+                    ; moveq #0,d7 (count incremented per procedure)
	move.w	#$34a,d0                        ; library ONGOSUB ($34a)
	jsr	emit_library_call               ; emit bsr to ONGOSUB
	movea.l	(sp)+,a5                        ; a5 = the procedure list
	moveq	#0,d7                           ; not worked out: d7 is not used below
.next_procedure:
	addq.w	#1,(a2)                         ; count one more procedure in the moveq
	move.w	#$7f06,(a1)+                    ; marker word $7f06, procedure number follows
	moveq	#0,d1                           ; clear the number
	btst	#$4,(a5)+                       ; bit 4 of the token: two-byte number
	beq.s	.read_procedure_low
	move.b	(a5)+,d1                        ; high byte
	asl.w	#8,d1
.read_procedure_low:
	move.b	(a5)+,d1                        ; low byte
	move.w	d1,(a1)+                        ; procedure number
	cmpi.b	#$46,(a5)+                      ; end of statement, or a comma
	bne.s	.next_procedure
	addq.l	#4,sp                           ; drop the return address
	bra.w	copy_statement_code

;------------------------------------------------------------------------------
; Statement VOID expr (tokens $7f, $f0): expression then IR $8047 (result discarded).
;------------------------------------------------------------------------------
stmt_void:
	bsr.w	parse_expression                ; the expression
	move.w	#$8047,(a4)+                    ; IR $8047: discard result (VOID)
	rts

;------------------------------------------------------------------------------
; Statement ~ expr (token $f1): integer expression then IR $8048 (result discarded).
;------------------------------------------------------------------------------
stmt_void_int:
	bsr.w	parse_integer_expression        ; the integer expression
	move.w	#$8048,(a4)+                    ; IR $8048: discard int result (~)
	rts

;------------------------------------------------------------------------------
; LET / assignment to a float (#) variable. Entry a5 at the variable index word. Parses the value, writes IR $8041 +
; variable index.
;------------------------------------------------------------------------------
stmt_let_float:
	move.w	(a5)+,-(sp)                     ; variable index
	bsr.w	parse_expression                ; the value
	move.w	#$8041,(a4)+                    ; IR $8041: store float variable
	move.w	(sp)+,(a4)+                     ; variable index
	rts

;------------------------------------------------------------------------------
; LET / assignment to a int (%) variable. Entry a5 at the variable index word. Parses the value, writes IR $8042 +
; variable index.
;------------------------------------------------------------------------------
stmt_let_int:
	move.w	(a5)+,-(sp)                     ; variable index
	bsr.w	parse_integer_expression        ; the value
	move.w	#$8042,(a4)+                    ; IR $8042: store int variable
	move.w	(sp)+,(a4)+                     ; variable index
	rts

;------------------------------------------------------------------------------
; LET / assignment to a word (&) variable. Entry a5 at the variable index word. Parses the value, writes IR $8043 +
; variable index.
;------------------------------------------------------------------------------
stmt_let_word:
	move.w	(a5)+,-(sp)                     ; variable index
	bsr.w	parse_integer_expression        ; the value
	move.w	#$8043,(a4)+                    ; IR $8043: store word variable
	move.w	(sp)+,(a4)+                     ; variable index
	rts

;------------------------------------------------------------------------------
; LET / assignment to a byte (|) variable. Entry a5 at the variable index word. Parses the value, writes IR $8044 +
; variable index.
;------------------------------------------------------------------------------
stmt_let_byte:
	move.w	(a5)+,-(sp)                     ; variable index
	bsr.w	parse_integer_expression        ; the value
	move.w	#$8044,(a4)+                    ; IR $8044: store byte variable
	move.w	(sp)+,(a4)+                     ; variable index
	rts

;------------------------------------------------------------------------------
; LET / assignment to a bool (!) variable: expression, $80ef (make boolean), IR $8045 + variable index.
;------------------------------------------------------------------------------
stmt_let_bool:
	move.w	(a5)+,-(sp)                     ; variable index
	bsr.w	parse_expression                ; the value
	move.w	#$80ef,(a4)+                    ; IR $80ef: make boolean
	move.w	#$8045,(a4)+                    ; IR $8045: store bool variable
	move.w	(sp)+,(a4)+                     ; variable index
	rts

;------------------------------------------------------------------------------
; LET / assignment to a string ($) variable: string expression, IR $8046 + variable index.
;------------------------------------------------------------------------------
stmt_let_string:
	move.w	(a5)+,-(sp)                     ; variable index
	bsr.w	parse_expression                ; the string value
	move.w	#$8046,(a4)+                    ; IR $8046: store string variable
	move.w	(sp)+,(a4)+                     ; variable index
	rts

;------------------------------------------------------------------------------
; Statement POKE addr,value and BYTE{addr}=value: address pushed ($8017), value; a constant value is cut to a
; sign-extended byte. Then $8022 (pop address into a0) and IR $8096.
;------------------------------------------------------------------------------
stmt_poke:
	bsr.w	parse_integer_expression        ; the address
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))
	pea	(a4)                            ; start of the value's IR
	bsr.w	parse_integer_expression        ; the value
	movea.l	(sp)+,a0                        ; a0 = the value's IR
	cmpi.w	#$8007,(a0)+                    ; IR $8007: integer constant (long follows)
	bne.s	.pop_poke_address               ; not a constant
	move.l	(a0)+,d0                        ; d0 = the constant
	cmpa.l	a0,a4                           ; nothing after it?
	bne.s	.pop_poke_address
	ext.w	d0                              ; sign-extend the low byte
	ext.l	d0
	move.l	d0,-(a0)                        ; write it back
.pop_poke_address:
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	#$8096,(a4)+                    ; IR $8096: POKE
	rts

;------------------------------------------------------------------------------
; Statement DPOKE addr,value, INT{}= and CARD{}=: like POKE with a word; IR $8097.
;------------------------------------------------------------------------------
stmt_dpoke:
	bsr.w	parse_integer_expression        ; the address
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))
	pea	(a4)                            ; start of the value's IR
	bsr.w	parse_integer_expression        ; the value
	movea.l	(sp)+,a0                        ; a0 = the value's IR
	cmpi.w	#$8007,(a0)+                    ; IR $8007: integer constant (long follows)
	bne.s	.pop_dpoke_address              ; not a constant
	move.l	(a0)+,d0                        ; d0 = the constant
	cmpa.l	a0,a4                           ; nothing after it?
	bne.s	.pop_dpoke_address
	ext.l	d0                              ; sign-extend the low word
	move.l	d0,-(a0)                        ; write it back
.pop_dpoke_address:
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	#$8097,(a4)+                    ; IR $8097: DPOKE
	rts

;------------------------------------------------------------------------------
; Statement LPOKE addr,value, {}= and LONG{}=: two integers, $8022, IR $8098.
;------------------------------------------------------------------------------
stmt_lpoke:
	bsr.w	parse_two_int_args              ; address pushed, value in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	#$8098,(a4)+                    ; IR $8098: LPOKE
	rts

;------------------------------------------------------------------------------
; Statement MONITOR [n]: optional integer, IR $81af.
;------------------------------------------------------------------------------
stmt_monitor:
	cmpi.b	#$46,(a5)                       ; MONITOR without a number?
	beq.s	.emit_monitor
	bsr.w	parse_integer_expression        ; the number
.emit_monitor:
	move.w	#$81af,(a4)+                    ; IR $81af: MONITOR
	rts
print_channel_set:
	dc.w	$0000                           ; flag: output channel already set (P0R routines used)

;------------------------------------------------------------------------------
; Statement LPRINT (command 303): writes library routine $25f LP0Init (printer channel), sets
; print_channel_set and joins stmt_print at print_item_list.
;------------------------------------------------------------------------------
stmt_lprint:
	move.w	#$25f,(a4)+                     ; IR: call LP0Init (printer)
	st	print_channel_set               ; channel set
	bra.s	print_item_list                 ; join the item loop

;------------------------------------------------------------------------------
; Statement PRINT (tokens $93, $94; LPRINT enters at $339e). PRINT #n calls PXInit ($25e) after the channel.
; Items: AT( -> LOCATE, TAB( -> PRTAB, SPC( -> PRSPC, "," -> PRKOMMA, "'" -> PRTICK, ";" nothing,
; numbers (marked by token $37) -> PRNUM, strings -> PRSTR, USING -> PUSIinit/PUSINUM/PUSISTR/PUSIexit,
; end of line -> PRCR. Until the output channel is set (print_channel_set) the first item uses the P0R
; variant of the routine, which also selects the screen.
;------------------------------------------------------------------------------
stmt_print:
	cmpi.b	#$4d,(a5)                       ; $4d = "#"
	beq.s	.with_channel
	sf	print_channel_set               ; screen: first item uses the P0R routine
	bra.s	print_item_list
.with_channel:
	st	print_channel_set               ; channel set by PXInit
	addq.l	#1,a5                           ; skip the '#'
	bsr.w	parse_integer_expression        ; the channel number
	move.w	#$25e,(a4)+                     ; IR: call PXInit

;------------------------------------------------------------------------------
; Item loop of stmt_print, entered after the channel has been set up (PRINT, PRINT #n, LPRINT).
;------------------------------------------------------------------------------
print_item_list:
	cmpi.b	#$46,-(a5)                      ; back one: is it the end mark (PRINT alone)?
	beq.s	.next_item
	addq.l	#1,a5                           ; no: forward again
.next_item:
	move.b	(a5),d0                         ; d0 = next item token
	cmpi.b	#$59,d0                         ; $59 = AT(
	beq.w	.at
	cmpi.b	#$46,d0                         ; end of the statement
	beq.w	.newline
	cmpi.b	#$21,d0                         ; $21 = ","
	beq.w	.comma
	cmpi.b	#$22,d0                         ; $22 = ";"
	beq.w	.skip_separator
	cmpi.b	#$57,d0                         ; $57 = "'"
	beq.s	.tick
	cmpi.b	#$a1,d0                         ; $a1 = TAB(
	beq.w	.tab
	cmpi.b	#$a2,d0                         ; $a2 = SPC(
	beq.w	.spc
	cmpi.b	#$a3,d0                         ; $a3 = USING
	beq.w	.using
	cmpi.b	#$37,(a5)                       ; $37 marks a numeric item
	bne.s	.string_item
	addq.l	#1,a5                           ; skip the $37
	bsr.w	parse_expression                ; the number
	move.w	#$3f,d0                         ; PRNUM
	tst.b	print_channel_set               ; channel already set?
	bne.s	.emit_number
	st	print_channel_set               ; now it is
	move.w	#$262,d0                        ; P0RNUM (first item)
.emit_number:
	move.w	d0,(a4)+                        ; IR: library call
	subq.l	#1,a5                           ; back to the token after the item
	bra.s	.next_item
.string_item:
	bsr.w	parse_expression                ; the string
	move.w	#$a8,d0                         ; PRSTR
	tst.b	print_channel_set               ; channel already set?
	bne.s	.emit_string
	st	print_channel_set               ; now it is
	move.w	#$271,d0                        ; P0RSTR
.emit_string:
	move.w	d0,(a4)+                        ; IR: library call
	subq.l	#1,a5                           ; back to the token after the item
	bra.w	.next_item
.tick:
	move.w	#$3e,d0                         ; PRTICK
	tst.b	print_channel_set               ; channel already set?
	bne.s	.emit_tick
	st	print_channel_set               ; now it is
	move.w	#$259,d0                        ; P0RTICK
.emit_tick:
	move.w	d0,(a4)+                        ; IR: library call
	bra.s	.skip_separator
.comma:
	move.w	#$3d,d0                         ; PRKOMMA
	tst.b	print_channel_set               ; channel already set?
	bne.s	.emit_comma
	st	print_channel_set               ; now it is
	move.w	#$25c,d0                        ; P0RKOMMA
.emit_comma:
	move.w	d0,(a4)+                        ; IR: library call
.skip_separator:
	addq.l	#1,a5                           ; skip the separator
	cmpi.b	#$46,(a5)                       ; end of the statement: no newline
	bne.w	.next_item
	rts
.newline:
	move.w	#$3c,d0                         ; PRCR
	tst.b	print_channel_set               ; channel already set?
	bne.s	.emit_newline
	st	print_channel_set               ; now it is
	move.w	#$255,d0                        ; P0RCR
.emit_newline:
	move.w	d0,(a4)+                        ; IR: library call
	rts
.at:
	addq.l	#1,a5                           ; skip the AT(
	move.w	#$8c,d0                         ; LOCATE with two integers
	bsr.w	emit_code_after_two_ints        ; both coordinates, then LOCATE
	bra.w	.next_item
.tab:
	addq.l	#1,a5                           ; skip the TAB(
	move.w	#$107,d0                        ; PRTAB
	tst.b	print_channel_set               ; channel already set?
	bne.s	.emit_tab
	st	print_channel_set               ; now it is
	move.w	#$273,d0                        ; P0RTAB
.emit_tab:
	bsr.w	emit_code_after_one_int         ; the column, then the routine
	bra.w	.next_item
.spc:
	addq.l	#1,a5                           ; skip the SPC(
	move.w	#$106,d0                        ; PRSPC
	tst.b	print_channel_set               ; channel already set?
	bne.s	.emit_spc
	st	print_channel_set               ; now it is
	move.w	#$274,d0                        ; P0RSPC
.emit_spc:
	bsr.w	emit_code_after_one_int         ; the count, then the routine
	bra.w	.next_item
.using:
	tst.b	print_channel_set               ; channel already set?
	bne.s	.parse_format
	st	print_channel_set               ; now it is
	move.w	#$25d,(a4)+                     ; P0Init
.parse_format:
	addq.l	#1,a5                           ; skip the USING
	bsr.w	parse_expression                ; the format string
	move.w	#$32f,(a4)+                     ; PUSIinit (format string parsed)
.next_using_item:
	cmpi.b	#$22,-$1(a5)                    ; ';' before: USING item list ended
	beq.s	.using_ends_with_semicolon
	cmpi.b	#$46,-$1(a5)                    ; end of the statement before?
	beq.s	.using_ends_with_line
	cmpi.b	#$37,(a5)+                      ; $37 marks a numeric item
	bne.s	.using_string
	bsr.w	parse_expression                ; the number
	move.w	#$331,(a4)+                     ; PUSINUM
	bra.s	.next_using_item
.using_string:
	subq.l	#1,a5                           ; back to the item
	bsr.w	parse_expression                ; the string
	move.w	#$330,(a4)+                     ; PUSISTR
	bra.s	.next_using_item
.using_ends_with_semicolon:
	move.w	#$332,(a4)+                     ; PUSIexit (ended with ";")
	rts
.using_ends_with_line:
	move.w	#$333,(a4)+                     ; PUSIexCR (ended with the line)
	rts

stmt_inc_float:
	move.w	#$80d0,(a4)+                    ; IR for INC# var
	bra.s	emit_var_index_word

stmt_inc_int:
	move.w	#$80d1,(a4)+                    ; IR for INC% var
	bra.s	emit_var_index_word

stmt_inc_word:
	move.w	#$80d2,(a4)+                    ; IR for INC& var
	bra.s	emit_var_index_word

stmt_inc_byte:
	move.w	#$80d3,(a4)+                    ; IR for INC| var

;------------------------------------------------------------------------------
; Writes the variable index word from the source after the IR code. INC/DEC: IR $80d0-$80d3 (INC # % & |),
; $80d4-$80d7 (DEC # % & |).
;------------------------------------------------------------------------------
emit_var_index_word:
	move.w	(a5)+,(a4)+                     ; variable index
	rts

stmt_dec_float:
	move.w	#$80d4,(a4)+                    ; IR for DEC# var
	bra.s	emit_var_index_word

stmt_dec_int:
	move.w	#$80d5,(a4)+                    ; IR for DEC% var
	bra.s	emit_var_index_word

stmt_dec_word:
	move.w	#$80d6,(a4)+                    ; IR for DEC& var
	bra.s	emit_var_index_word

stmt_dec_byte:
	move.w	#$80d7,(a4)+                    ; IR for DEC| var
	bra.s	emit_var_index_word

stmt_add_float:
	move.w	#$80d8,d0                       ; IR $80d8: ADD# variable
	bra.s	emit_float_var_update

stmt_sub_float:
	move.w	#$80d9,d0                       ; IR $80d9: SUB# variable
	bra.s	emit_float_var_update

stmt_mul_float:
	move.w	#$80da,d0                       ; IR $80da: MUL# variable
	bra.s	emit_float_var_update

stmt_div_float:
	move.w	#$80db,d0                       ; IR $80db: DIV# variable

;------------------------------------------------------------------------------
; ADD/SUB/MUL/DIV on a float variable: d0 = IR ($80d8-$80db), parses the float value, writes IR + index.
;------------------------------------------------------------------------------
emit_float_var_update:
	move.w	(a5)+,-(sp)                     ; variable index
	move.w	d0,-(sp)                        ; the IR code
	bsr.w	parse_expression                ; the float value
	move.w	(sp)+,(a4)+                     ; IR code
	move.w	(sp)+,(a4)+                     ; variable index
	rts

stmt_add_int:
	move.w	#$80dc,d0                       ; IR $80dc: ADD% variable
	bra.s	emit_int_var_update

stmt_sub_int:
	move.w	#$80dd,d0                       ; IR $80dd: SUB% variable
	bra.s	emit_int_var_update

stmt_mul_int:
	move.w	#$80de,d0                       ; IR $80de: MUL% variable
	bra.s	emit_int_var_update

stmt_div_int:
	move.w	#$80df,d0                       ; IR $80df: DIV% variable

;------------------------------------------------------------------------------
; ADD/SUB/MUL/DIV on an int/word/byte variable: d0 = IR ($80dc-$80e7), parses the integer value, writes IR + index.
;------------------------------------------------------------------------------
emit_int_var_update:
	move.w	(a5)+,-(sp)                     ; variable index
	move.w	d0,-(sp)                        ; the IR code
	bsr.w	parse_integer_expression        ; the integer value
	move.w	(sp)+,(a4)+                     ; IR code
	move.w	(sp)+,(a4)+                     ; variable index
	rts

stmt_add_word:
	move.w	#$80e0,d0                       ; IR $80e0: ADD& variable
	bra.s	emit_int_var_update

stmt_sub_word:
	move.w	#$80e1,d0                       ; IR $80e1: SUB& variable
	bra.s	emit_int_var_update

stmt_mul_word:
	move.w	#$80e2,d0                       ; IR $80e2: MUL& variable
	bra.s	emit_int_var_update

stmt_div_word:
	move.w	#$80e3,d0                       ; IR $80e3: DIV& variable
	bra.s	emit_int_var_update

stmt_add_byte:
	move.w	#$80e4,d0                       ; IR $80e4: ADD| variable
	bra.s	emit_int_var_update

stmt_sub_byte:
	move.w	#$80e5,d0                       ; IR $80e5: SUB| variable
	bra.s	emit_int_var_update

stmt_mul_byte:
	move.w	#$80e6,d0                       ; IR $80e6: MUL| variable
	bra.s	emit_int_var_update

stmt_div_byte:
	move.w	#$80e7,d0                       ; IR $80e7: DIV| variable
	bra.s	emit_int_var_update

stmt_dec_float_array:
	move.w	#$8136,d1                       ; IR $8136: DEC#() element
	bra.s	use_float_element

stmt_inc_float_array:
	move.w	#$8132,d1                       ; IR $8132: INC#() element

use_float_element:
	move.w	#$812e,d2                       ; IR $812e: float element address
	bra.s	emit_array_inc_dec

stmt_dec_int_array:
	move.w	#$8137,d1                       ; IR $8137: DEC%() element
	bra.s	use_int_element

stmt_inc_int_array:
	move.w	#$8133,d1                       ; IR $8133: INC%() element

use_int_element:
	move.w	#$812f,d2                       ; IR $812f: int element address
	bra.s	emit_array_inc_dec

stmt_dec_word_array:
	move.w	#$8138,d1                       ; IR $8138: DEC&() element
	bra.s	use_word_element

stmt_inc_word_array:
	move.w	#$8134,d1                       ; IR $8134: INC&() element

use_word_element:
	move.w	#$8130,d2                       ; IR $8130: word element address
	bra.s	emit_array_inc_dec

stmt_dec_byte_array:
	move.w	#$8139,d1                       ; IR $8139: DEC|() element
	bra.s	use_byte_element

stmt_inc_byte_array:
	move.w	#$8135,d1                       ; IR $8135: INC|() element

use_byte_element:
	move.w	#$8131,d2                       ; IR $8131: byte element address

;------------------------------------------------------------------------------
; INC/DEC on an array element. Entry: d1 = operation IR ($8132-$8139), d2 = element access IR ($812e float,
; $812f int, $8130 word, $8131 byte). Pushes every index, then emit_array_element_update.
;------------------------------------------------------------------------------
emit_array_inc_dec:
	move.w	(a5)+,d0                        ; d0 = array variable index
	move.w	d1,-(sp)                        ; keep the operation IR
	move.w	d0,-(sp)                        ; the variable index
	move.w	d2,-(sp)                        ; the element access IR
	clr.w	-(sp)                           ; index count
.next_inc_dec_index:
	bsr.w	parse_int_and_push              ; next index, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another index
	beq.s	.next_inc_dec_index

;------------------------------------------------------------------------------
; Ends an array element update: one index -> $801e (pop into d4), two -> $801f $801e (d5, d4), more stay on
; the stack; then access IR, variable index, index count, and the operation IR.
;------------------------------------------------------------------------------
emit_array_element_update:
	movem.w	(sp)+,d0-d2                     ; d0 = count, d1 = access IR, d2 = variable index
	move.w	d0,d3                           ; d3 = index count
	subq.w	#1,d0
	beq.s	.update_one_index               ; one index
	subq.w	#1,d0
	beq.s	.update_two_indexes             ; two indexes
	bra.s	.write_update                   ; three or more: all stay on the stack
.update_two_indexes:
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
.update_one_index:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
.write_update:
	move.w	d1,(a4)+                        ; element access IR
	move.w	d2,(a4)+                        ; variable index
	move.w	d3,(a4)+                        ; index count
	move.w	(sp)+,(a4)+                     ; operation IR
	rts

stmt_div_word_array:
	move.w	#$8148,d1                       ; IR $8148: DIV&() element
	bra.s	word_element_with_int_value

stmt_mul_word_array:
	move.w	#$8144,d1                       ; IR $8144: MUL&() element
	bra.s	word_element_with_int_value

stmt_sub_word_array:
	move.w	#$8140,d1                       ; IR $8140: SUB&() element
	bra.s	word_element_with_int_value

stmt_add_word_array:
	move.w	#$813c,d1                       ; IR $813c: ADD&() element

word_element_with_int_value:
	move.w	#$8130,d2                       ; IR $8130: word element address
	bra.s	emit_array_update_int_value

stmt_div_byte_array:
	move.w	#$8149,d1                       ; IR $8149: DIV|() element
	bra.s	byte_element_with_int_value

stmt_mul_byte_array:
	move.w	#$8145,d1                       ; IR $8145: MUL|() element
	bra.s	byte_element_with_int_value

stmt_sub_byte_array:
	move.w	#$8141,d1                       ; IR $8141: SUB|() element
	bra.s	byte_element_with_int_value

stmt_add_byte_array:
	move.w	#$813d,d1                       ; IR $813d: ADD|() element

byte_element_with_int_value:
	move.w	#$8131,d2                       ; IR $8131: byte element address
	bra.s	emit_array_update_int_value

stmt_div_float_array:
	move.w	#$8146,d1                       ; IR $8146: DIV#() element
	bra.s	float_element_with_float_value

stmt_mul_float_array:
	move.w	#$8142,d1                       ; IR $8142: MUL#() element
	bra.s	float_element_with_float_value

stmt_sub_float_array:
	move.w	#$813e,d1                       ; IR $813e: SUB#() element
	bra.s	float_element_with_float_value

stmt_add_float_array:
	move.w	#$813a,d1                       ; IR $813a: ADD#() element

float_element_with_float_value:
	move.w	#$812e,d2                       ; IR $812e: float element address
	bra.s	emit_array_update_float_value

stmt_div_int_array:
	move.w	#$8147,d1                       ; IR $8147: DIV%() element
	bra.s	int_element_with_int_value

stmt_mul_int_array:
	move.w	#$8143,d1                       ; IR $8143: MUL%() element
	bra.s	int_element_with_int_value

stmt_sub_int_array:
	move.w	#$813f,d1                       ; IR $813f: SUB%() element
	bra.s	int_element_with_int_value

stmt_add_int_array:
	move.w	#$813b,d1                       ; IR $813b: ADD%() element

int_element_with_int_value:
	move.w	#$812f,d2                       ; IR $812f: int element address

;------------------------------------------------------------------------------
; ADD/SUB/MUL/DIV on an int/word/byte array element ($813a-$8149 in d1, access IR in d2): indices, optional ",",
; integer value, then emit_array_element_update.
;------------------------------------------------------------------------------
emit_array_update_int_value:
	move.w	(a5)+,d0                        ; d0 = array variable index
	move.w	d1,-(sp)                        ; keep the operation IR
	move.w	d0,-(sp)                        ; the variable index
	move.w	d2,-(sp)                        ; the element access IR
	clr.w	-(sp)                           ; index count
.next_int_update_index:
	bsr.w	parse_int_and_push              ; next index, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another index
	beq.s	.next_int_update_index
	cmpi.b	#$21,(a5)+                      ; optional ',' before the value
	beq.s	.parse_int_value
	subq.l	#1,a5                           ; none: back
.parse_int_value:
	bsr.w	parse_integer_expression        ; the integer value
	bra.w	emit_array_element_update

;------------------------------------------------------------------------------
; ADD/SUB/MUL/DIV on a float array element: indices, optional ",", float value, emit_array_element_update.
;------------------------------------------------------------------------------
emit_array_update_float_value:
	move.w	(a5)+,d0                        ; d0 = array variable index
	move.w	d1,-(sp)                        ; keep the operation IR
	move.w	d0,-(sp)                        ; the variable index
	move.w	d2,-(sp)                        ; the element access IR
	clr.w	-(sp)                           ; index count
.next_float_update_index:
	bsr.w	parse_int_and_push              ; next index, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another index
	beq.s	.next_float_update_index
	cmpi.b	#$21,(a5)+                      ; optional ',' before the value
	beq.s	.parse_float_value
	subq.l	#1,a5                           ; none: back
.parse_float_value:
	bsr.w	parse_expression                ; the float value
	bra.w	emit_array_element_update

stmt_let_word_array:
	move.w	#$80c8,d1                       ; IR $80c8: store word element
	bra.s	emit_array_store_int_value

stmt_let_byte_array:
	move.w	#$80c9,d1                       ; IR $80c9: store byte element
	bra.s	emit_array_store_int_value

stmt_let_float_array:
	move.w	#$80cb,d1                       ; IR $80cb: store float element
	bra.s	emit_array_store_value

stmt_let_bool_array:
	move.w	#$80ca,d1                       ; IR $80ca: store bool element
	bra.s	emit_array_store_bool_value

stmt_let_string_array:
	move.w	#$80cc,d1                       ; IR $80cc: store string element
	bra.s	emit_array_store_value

stmt_let_int_array:
	move.w	#$80c7,d1                       ; IR $80c7: store int element

;------------------------------------------------------------------------------
; Assignment to an int/word/byte array element (d1 = $80c7 int, $80c8 word, $80c9 byte): indices pushed,
; integer value, then emit_array_store.
;------------------------------------------------------------------------------
emit_array_store_int_value:
	move.w	(a5)+,d0                        ; d0 = array variable index
	move.w	d0,-(sp)                        ; keep it
	move.w	d1,-(sp)                        ; keep the store IR
	clr.w	-(sp)                           ; index count
.next_int_store_index:
	bsr.w	parse_int_and_push              ; next index, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another index
	beq.s	.next_int_store_index
	bsr.w	parse_integer_expression        ; the integer value

;------------------------------------------------------------------------------
; Pops one index into d4 ($801e) or two into d5/d4 ($801f $801e), then writes store IR, variable index, count.
;------------------------------------------------------------------------------
emit_array_store:
	movem.w	(sp)+,d0-d2                     ; d0 = count, d1 = store IR, d2 = variable index
	move.w	d0,d3                           ; d3 = index count
	subq.w	#1,d0
	beq.s	.store_one_index                ; one index
	subq.w	#1,d0
	beq.s	.store_two_indexes              ; two indexes
	bra.s	.write_store                    ; three or more: all stay on the stack
.store_two_indexes:
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
.store_one_index:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
.write_store:
	move.w	d1,(a4)+                        ; store IR
	move.w	d2,(a4)+                        ; variable index
	move.w	d3,(a4)+                        ; index count
	rts

;------------------------------------------------------------------------------
; Assignment to a float ($80cb) or string ($80cc) array element: indices, value by parse_expression.
;------------------------------------------------------------------------------
emit_array_store_value:
	move.w	(a5)+,d0                        ; d0 = array variable index
	move.w	d0,-(sp)                        ; keep it
	move.w	d1,-(sp)                        ; keep the store IR
	clr.w	-(sp)                           ; index count
.next_value_store_index:
	bsr.w	parse_int_and_push              ; next index, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another index
	beq.s	.next_value_store_index
	bsr.w	parse_expression                ; the float or string value
	bra.s	emit_array_store

;------------------------------------------------------------------------------
; Assignment to a bool array element ($80ca): indices, expression, $80ef (make boolean).
;------------------------------------------------------------------------------
emit_array_store_bool_value:
	move.w	(a5)+,d0                        ; d0 = array variable index
	move.w	d0,-(sp)                        ; keep it
	move.w	d1,-(sp)                        ; keep the store IR
	clr.w	-(sp)                           ; index count
.next_bool_store_index:
	bsr.w	parse_int_and_push              ; next index, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another index
	beq.s	.next_bool_store_index
	bsr.w	parse_expression                ; the value
	move.w	#$80ef,(a4)+                    ; IR $80ef: make boolean
	bra.s	emit_array_store

;------------------------------------------------------------------------------
; Statement BMOVE src,dst,len: three integers, $8023 (pop into a1), $8022 (pop into a0), library BMOVE ($41).
;------------------------------------------------------------------------------
stmt_bmove:
	bsr.w	parse_three_int_args            ; source, destination, length pushed / in d0
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	#$41,(a4)+                      ; library BMOVE ($41)
	rts

;------------------------------------------------------------------------------
; Statement DIM: per array the dimensions are pushed, the last stays in d0 (the last $8017 is removed), the
; others are popped into d1.. ($801b-$8020). IR from dim_ir_table ($80f0-$80f5 for # $ % ! & |), dimension
; count, array index.
;------------------------------------------------------------------------------
stmt_dim:
	move.b	(a5)+,d0                        ; d0 = array token
	moveq	#0,d1
	move.b	(a5)+,d1                        ; d1 = array number (low byte, or high)
	bclr	#$4,d0                          ; bit 4: two-byte number
	beq.s	.push_type_and_index
	asl.w	#8,d1                           ; first byte was the high byte
	move.b	(a5)+,d1                        ; low byte
.push_type_and_index:
	andi.w	#$b,d0                          ; type & %1011: array bit removed
	add.w	d0,d0                           ; word table index
	movem.w	d0-d1,-(sp)                     ; keep type and number
	clr.w	-(sp)                           ; dimension count
.next_dimension:
	bsr.w	parse_int_and_push              ; next dimension, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another dimension
	beq.s	.next_dimension
	subq.l	#2,a4                           ; remove the push of the last dimension
	move.w	(sp)+,d2                        ; d2 = dimension count
	movem.w	(sp)+,d0-d1                     ; d0 = table index, d1 = array number
	move.w	d2,d3                           ; pop all but the last dimension
	subq.w	#1,d3
	beq.s	.write_dim                      ; one dimension: nothing to pop
	subq.w	#1,d3
	beq.s	.two_dimensions
	subq.w	#1,d3
	beq.s	.three_dimensions
	subq.w	#1,d3
	beq.s	.four_dimensions
	subq.w	#1,d3
	beq.s	.five_dimensions
	subq.w	#1,d3
	beq.s	.six_dimensions
	subq.w	#1,d3
	beq.s	.seven_dimensions
	illegal                                 ; more than 7 dimensions
.seven_dimensions:
	move.w	#$8020,(a4)+                    ; IR $8020: pop into d6
.six_dimensions:
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
.five_dimensions:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
.four_dimensions:
	move.w	#$801d,(a4)+                    ; IR $801d: pop into d3
.three_dimensions:
	move.w	#$801c,(a4)+                    ; IR $801c: pop into d2
.two_dimensions:
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
.write_dim:
	move.w	dim_ir_table(pc,d0.w),d0        ; d0 = IR for the type
	move.w	d0,(a4)+
	move.w	d2,(a4)+                        ; dimension count
	move.w	d1,(a4)+                        ; array number
	cmpi.b	#$46,(a5)+                      ; end of statement, or a comma
	bne.s	stmt_dim
	rts
dim_ir_table:
	dc.w	$80f0,$80f1,$80f2,$80f3,$0000,$0000,$0000,$0000
	dc.w	$80f4,$80f5

;------------------------------------------------------------------------------
; Statement ARRAYFILL a(),value (command 397). Array token (type & $0b, bit 4 = two-byte number),
; then the value: float arrays parse_expression, the others parse_integer_expression. Writes
; arrayfill_ir_table[type] and the array number.
;------------------------------------------------------------------------------
stmt_arrayfill:
	move.b	(a5)+,d0                        ; d0 = array token
	moveq	#0,d1
	move.b	(a5)+,d1                        ; d1 = array number (low byte, or high)
	bclr	#$4,d0                          ; bit 4: two-byte number
	beq.s	.keep_type_and_index
	asl.w	#8,d1                           ; first byte was the high byte
	move.b	(a5)+,d1                        ; low byte
.keep_type_and_index:
	andi.w	#$b,d0                          ; type & %1011: 0 float, 2 int, 3 bool, 8 word, 9 byte
	movem.w	d0-d1,-(sp)                     ; keep type and number
	addq.l	#2,a5                           ; skip '()' and ','
	subq.w	#2,d0                           ; float array: general expression
	bmi.s	.arrayfill_float_value
	bsr.w	parse_integer_expression        ; integer value
	bra.s	.write_arrayfill
.arrayfill_float_value:
	bsr.w	parse_expression                ; float value
.write_arrayfill:
	movem.w	(sp)+,d0-d1
	add.w	d0,d0                           ; word table index
	move.w	arrayfill_ir_table(pc,d0.w),d0  ; IR for the type
	move.w	d0,(a4)+
	move.w	d1,(a4)+                        ; array number
	rts

; IR word per array type for ARRAYFILL: float $80f6, (string 0), int $80f7, bool $80f8, word $80f9,
; byte $80fa.
arrayfill_ir_table:
	dc.w	$80f6,$0000,$80f7,$80f8,$0000,$0000,$0000,$0000
	dc.w	$80f9,$80fa

;------------------------------------------------------------------------------
; Statement ERASE a(),b$(),... (command 322): sets flag_121d3, then per array IR erase_ir_table[type]
; and the array number, until token $46.
;------------------------------------------------------------------------------
stmt_erase:
	st	flag_121d3                      ; ERASE: flag_121d3 set
	move.b	(a5)+,d0                        ; d0 = array token
	moveq	#0,d1
	move.b	(a5)+,d1                        ; d1 = array number (low byte, or high)
	bclr	#$4,d0                          ; bit 4: two-byte number
	beq.s	.write_erase
	asl.w	#8,d1                           ; first byte was the high byte
	move.b	(a5)+,d1                        ; low byte
.write_erase:
	andi.w	#$b,d0                          ; type & %1011
	add.w	d0,d0                           ; word table index
	move.w	erase_ir_table(pc,d0.w),d0      ; IR for the type
	move.w	d0,(a4)+
	move.w	d1,(a4)+                        ; array number
	addq.l	#1,a5                           ; skip the '()'
	cmpi.b	#$46,(a5)+                      ; end of statement, or a comma
	bne.s	stmt_erase
	rts

; IR word per array type for ERASE: float $8187, string $8188, int $8189, bool $818a, word $818b,
; byte $818c.
erase_ir_table:
	dc.w	$8187,$8188,$8189,$818a,$0000,$0000,$0000,$0000
	dc.w	$818b,$818c

;------------------------------------------------------------------------------
; Statement MOUSE x,y,k (command 332): library routine $ed MOUSE, then the three results (d7 = %1110)
; are stored into the variables with d5 = 0 (no final $801a pop in the stacked form).
;------------------------------------------------------------------------------
stmt_mouse:
	move.w	#$ed,(a4)+                      ; library routine $ed MOUSE
	moveq	#14,d7                          ; d7 = results 1-3 (x, y, k)
	moveq	#0,d5                           ; d5 = 0: no final IR $801a
	bra.s	store_results_no_final_pop
	moveq	#14,d7                          ; no label: unreferenced (results 1-3, d5 = 1)
	bra.s	store_results

;------------------------------------------------------------------------------
; Code entered as the return address pushed by parse_fn_evnt_multi: moveq #$7e,d7 / bra store_results
; (six result variables). $394e: moveq #$1e,d7 / bra store_results (four; no reference found).
;------------------------------------------------------------------------------
store_evnt_multi_results:
	moveq	#126,d7
	bra.s	store_results
	moveq	#30,d7                          ; no label: unreferenced (results 1-4)
	bra.s	store_results

;------------------------------------------------------------------------------
; Stores GEM results into the variables that follow in the source (a5): four results (d7 = bits 1-4).
;------------------------------------------------------------------------------
store_four_results:
	moveq	#30,d7
	bra.s	store_results

;------------------------------------------------------------------------------
; Stores two results (d7 = bits 1-2).
;------------------------------------------------------------------------------
store_two_results:
	moveq	#6,d7
	bra.s	store_results

;------------------------------------------------------------------------------
; Stores one result (d7 = bit 1).
;------------------------------------------------------------------------------
store_one_result:
	moveq	#2,d7

;------------------------------------------------------------------------------
; Stores the results selected by the bit mask d7 (bit n = result n) into the variables listed at a5.
; While the variables are int/bool/word/byte scalars: IR $8100 + 4*(n-1) + type code (result_type_codes:
; 0 int, 1 bool, 2 word, 3 byte) + variable index. A float variable or an array switches to the stacked form
; (switch_to_stacked_results). Stops at ")".
;------------------------------------------------------------------------------
store_results:
	moveq	#1,d5                           ; d5 = 1: the stacked form ends with $801a

;------------------------------------------------------------------------------
; Entry into store_results with d5 already set by the caller (d5 = 0: the stacked form ends without
; IR $801a). d7 = bit mask of the results to store, a5 = first result variable.
;------------------------------------------------------------------------------
store_results_no_final_pop:
	moveq	#1,d6                           ; d6 = result number
.next_result:
	cmpi.b	#$20,-$1(a5)
	beq.s	store_results_done              ; ")" ends the list
	moveq	#0,d3                           ; d3 = variable index
	move.b	(a5)+,d0                        ; d0 = variable token
	btst	#$2,d0                          ; array?
	bne.w	switch_to_stacked_results
	moveq	#11,d1                          ; type & %1011: 0 = float
	and.b	d0,d1
	beq.w	switch_to_stacked_results
	move.b	(a5)+,d3                        ; low byte of the index
	bclr	#$4,d0                          ; bit 4: two-byte index
	beq.s	.write_result_store
	asl.w	#8,d3                           ; first byte was the high byte
	move.b	(a5)+,d3                        ; low byte
.write_result_store:
	move.b	result_type_codes(pc,d1.w),d1   ; d1 = type code 0-3
	add.w	d6,d1                           ; + 4 * result number
	add.w	d6,d1
	add.w	d6,d1
	add.w	d6,d1
	subq.w	#4,d1                           ; - 4: result 1 is $8100-$8103
	addi.w	#$8100,d1                       ; IR $8100 + 4*(n-1) + type code
	move.w	d1,(a4)+
	move.w	d3,(a4)+
	bclr	d6,d7
	addq.l	#1,a5                           ; skip the separator
	addq.w	#1,d6                           ; next result number
	tst.w	d7                              ; more results to store?
	bne.s	.next_result

store_results_done:
	rts
result_type_codes:
	dc.w	$0000,$0001,$0000,$0000,$0203   ; byte per type & %1011: 2 int 0, 3 bool 1, 8 word 2, 9 byte 3

;------------------------------------------------------------------------------
; Stacked form: the remaining results are on the stack; each one is popped ($801b) and stored with
; IR $8100 + type code + index. Ends with $801a when the d5 flag is set.
;------------------------------------------------------------------------------
store_stacked_results:
	moveq	#0,d3                           ; d3 = variable index
	move.b	(a5)+,d0                        ; d0 = variable token
	btst	#$2,d0                          ; array?
	bne.s	store_stacked_result_float
	moveq	#11,d1                          ; type & %1011: 0 = float
	and.b	d0,d1
	beq.s	store_stacked_result_float
	move.b	(a5)+,d3                        ; low byte of the index
	bclr	#$4,d0                          ; bit 4: two-byte index
	beq.s	.pop_and_store
	asl.w	#8,d3                           ; first byte was the high byte
	move.b	(a5)+,d3                        ; low byte
.pop_and_store:
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.b	result_type_codes(pc,d1.w),d1   ; type code 0-3
	addi.w	#$8100,d1                       ; $8100-$8103: store d1 into the variable
	move.w	d1,(a4)+
	move.w	d3,(a4)+                        ; variable index
	bclr	d6,d7                           ; this result done

next_stacked_result:
	addq.l	#1,a5                           ; skip the separator
	addq.w	#1,d6                           ; next result number
	tst.w	d7                              ; more results?
	bne.s	store_stacked_results
	tst.w	d5                              ; final pop wanted?
	beq.s	store_results_done
	move.w	#$801a,(a4)+                    ; IR $801a: pop into d0
	rts

store_stacked_result_float:
	bclr	d6,d7                           ; this result done
	moveq	#11,d1                          ; non-float array?
	and.w	d0,d1
	bne.s	store_result_array_element
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	btst	#$2,d0                          ; float array?
	bne.s	.push_stacked_float
	move.w	#$801a,-$2(a4)                  ; float variable: the $8006 becomes $801a pop into d0
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	move.w	#$8041,(a4)+                    ; IR $8041: store float variable
	moveq	#0,d1                           ; d1 = variable index
	move.b	(a5)+,d1
	btst	#$4,d0                          ; bit 4: two-byte index
	beq.s	.write_stacked_float_index
	asl.w	#8,d1                           ; first byte was the high byte
	move.b	(a5)+,d1                        ; low byte
.write_stacked_float_index:
	move.w	d1,(a4)+                        ; variable index
	bra.s	next_stacked_result
.push_stacked_float:
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	bra.s	store_result_array_element

;------------------------------------------------------------------------------
; Writes IR $80cd (mask of the remaining results + d5, result number) so the remaining results are pushed,
; then stores the current result: float -> $8006 + $8041 (store float var), arrays -> store_result_array_element.
;------------------------------------------------------------------------------
switch_to_stacked_results:
	bclr	d6,d7                           ; this result done
	move.w	#$80cd,(a4)+                    ; IR $80cd: push remaining results
	move.w	d7,(a4)                         ; mask of the results still to come
	add.w	d5,(a4)+                        ; + d5 (bit 0: final $801a pop)
	move.w	d6,(a4)+                        ; current result number
	moveq	#11,d1                          ; non-float: an array
	and.w	d0,d1
	bne.s	.push_int_for_element
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	btst	#$2,d0                          ; float array?
	bne.s	.push_float_for_element
	move.w	#$8041,(a4)+                    ; IR $8041: store float variable
	moveq	#0,d1                           ; d1 = variable index
	move.b	(a5)+,d1
	btst	#$4,d0                          ; bit 4: two-byte index
	beq.s	.write_float_index
	asl.w	#8,d1                           ; first byte was the high byte
	move.b	(a5)+,d1                        ; low byte
.write_float_index:
	move.w	d1,(a4)+                        ; variable index
	bra.s	next_stacked_result
.push_float_for_element:
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	bra.s	store_result_array_element
.push_int_for_element:
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))

;------------------------------------------------------------------------------
; Stores a result into an array element: IR from array_result_ir_table ($80cb #, $80c7 %, $80ca !, $80c8 &,
; $80c9 |), indices by emit_result_array_store.
;------------------------------------------------------------------------------
store_result_array_element:
	movem.w	d5-d7,-(sp)                     ; keep the result state
	moveq	#0,d1                           ; clear the array number
	bclr	#$4,d0                          ; bit 4: two-byte number
	beq.s	.read_array_number_low
	move.b	(a5)+,d1                        ; high byte
	asl.w	#8,d1
.read_array_number_low:
	move.b	(a5)+,d1                        ; low byte
	exg	d1,d0                           ; d0 = array number, d1 = token
	andi.w	#$f,d1                          ; array type 4-13
	add.w	d1,d1                           ; word table index
	move.w	array_result_ir_table(pc,d1.w),d1 ; d1 = store IR (table from $3a50)
	bsr.s	emit_result_array_store         ; indexes, pop and store

array_result_ir_table:
	movem.w	(sp)+,d5-d7                     ; table base: array types 4-13 index the words at $3a50
	bra.w	next_stacked_result             ; on with the next result
	dc.w	$80cb,$0000,$80c7,$80ca,$0000,$0000,$0000,$0000
	dc.w	$80c8,$80c9

;------------------------------------------------------------------------------
; Pushes the indices, pops one or two into d4/d5, then $801a (pop the value into d0), store IR, index, count.
;------------------------------------------------------------------------------
emit_result_array_store:
	move.w	d0,-(sp)                        ; keep the array number
	move.w	d1,-(sp)                        ; and the store IR
	clr.w	-(sp)                           ; index count
.next_result_index:
	bsr.w	parse_int_and_push              ; next index, pushed
	addq.w	#1,(sp)                         ; count it
	cmpi.b	#$21,-$1(a5)                    ; a comma: another index
	beq.s	.next_result_index
	movem.w	(sp)+,d0-d2                     ; d0 = count, d1 = store IR, d2 = array number
	move.w	d0,d3                           ; d3 = index count
	subq.w	#1,d0
	beq.s	.result_one_index               ; one index
	subq.w	#1,d0
	beq.s	.result_two_indexes
	subq.w	#1,d0
	beq.s	.result_two_indexes
	subq.w	#1,d0
	beq.s	.result_two_indexes
	subq.w	#1,d0
	beq.s	.result_two_indexes
	subq.w	#1,d0
	beq.s	.result_two_indexes
	subq.w	#1,d0
	beq.s	.result_two_indexes
	illegal                                 ; more than 7 indexes
.result_two_indexes:
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
.result_one_index:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
	move.w	#$801a,(a4)+                    ; IR $801a: pop into d0
	move.w	d1,(a4)+                        ; store IR
	move.w	d2,(a4)+                        ; array number
	move.w	d3,(a4)+                        ; index count
	rts

;------------------------------------------------------------------------------
; Ends a line in the middle of a statement: optimises the IR (optimise_ir), generates code (generate_code) and
; appends it to the program (append_line_code).
;------------------------------------------------------------------------------
optimise_generate_and_append:
	bsr.w	optimise_ir                     ; optimise the IR first

;------------------------------------------------------------------------------
; Generates code from the IR (generate_code) and appends it (append_line_code).
;------------------------------------------------------------------------------
generate_and_append:
	bsr.w	generate_code                   ; code into statement_code_buffer, a1 = its end

;------------------------------------------------------------------------------
; Appends the line code buffer to the program (copy_code_to_output). When break_check_flag is set (option U+,
; a jsr (a6) is appended to every line) that call is removed again (subq.l #2,code_write_pointer).
;------------------------------------------------------------------------------
append_line_code:
	bsr.w	copy_code_to_output             ; append it to the program
	move.b	break_check_flag(pc),d0         ; option U+: a jsr (a6) was appended?
	beq.s	.no_break_check
	subq.l	#2,code_write_pointer           ; take it back: no break check mid-statement
.no_break_check:
	rts

;------------------------------------------------------------------------------
; Optimises the IR and generates code into the line buffer (a1 = end of the generated code on exit).
;------------------------------------------------------------------------------
optimise_and_generate:
	bsr.w	optimise_ir                     ; optimise the IR
	bra.w	generate_code                   ; and generate the code

;------------------------------------------------------------------------------
; General (float and string) expression parser, precedence 0. IR words: $80xx are IR operations, words below $8000 are
; library routine calls (routine number, names in the table at $f8a6).
; Entry: a5 = tokens, a4 = IR write pointer. Exit: a5 after the terminating token (")", ",", ";", $46...),
; result float in d0-d2 style registers or a string, as the IR describes.
; Operator precedence parsing: each operand handler (expression_token_table, indexed by the token byte) writes
; its IR; each operator handler compares its precedence with the word on the stack, and either returns
; (addq.l #2,sp / rts) or parses its right operand with parse_expression_above and then jumps to the handler
; of the token that ended it (a3).
;------------------------------------------------------------------------------
parse_expression:
	moveq	#0,d7                           ; precedence 0: the whole expression

;------------------------------------------------------------------------------
; Parses an expression whose operators bind tighter than the precedence in d7 (pushed as the stack word).
; Exit: a3 = handler of the operator that ended the operand, which the caller jumps to.
;------------------------------------------------------------------------------
parse_expression_above:
	move.w	d7,-(sp)                        ; precedence word of this level
	move.b	(a5)+,d7                        ; d7 = operand token
	move.w	d7,d6                           ; d6 = the token for the handler
	add.w	d7,d7                           ; word table index

dispatch_operand:
	lea	expression_token_table(pc,d7.w),a0 ; operand: d7 = token * 2
	moveq	#0,d0                           ; d0 = 0 for the handler
	adda.w	(a0),a0                         ; a0 = the handler
	jsr	(a0)                            ; operand handler
	moveq	#0,d7                           ; clear the high byte
	move.b	(a5)+,d7                        ; operator token
	add.w	d7,d7                           ; word table index

dispatch_operator:
	lea	expression_token_table(pc,d7.w),a0
	adda.w	(a0),a0                         ; a0 = the handler
	movea.l	a0,a3                           ; a3 = handler of this operator
	moveq	#0,d0                           ; d0 = 0 for the handler
	jmp	(a0)                            ; operator handler (returns or chains with jmp (a3))

; Self-relative handlers for every token byte of the general expression parser. Operators 0-$1f
; (precedence 4 AND OR XOR IMP EQV, 10 float compares, 30 + -, 35 MOD DIV, 40 * /, 50 ^, 60 string compares,
; 65 string +), functions $24-$c4, constants $b8-$dd, string literal $de, variables $e0-$ff, $d0 = secondary
; function prefix. Terminators (")" "," ";" $46 ...) point at $3cf8 (end of expression).
expression_token_table:
	dc.w	parse_op_and-expression_token_table
	dc.w	parse_op_or-(expression_token_table+2)
	dc.w	parse_op_xor-(expression_token_table+4)
	dc.w	parse_op_imp-(expression_token_table+6)
