;------------------------------------------------------------------------------
; Integer parser met a token it does not handle itself: replaces the return address with emit_float_to_int_result
; and lets the general parser parse the whole expression from this token (precedence 0).
;------------------------------------------------------------------------------
int_operand_to_float_parser:
	move.l	#emit_float_to_int_result,(sp)  ; on return: convert the float result to int
	clr.w	-(sp)                           ; precedence 0 for the general parser
	bra.w	dispatch_operand                ; same token through the general parser

emit_float_to_int_result:
	move.w	#$8005,(a4)+                    ; IR $8005: float to int (FFTOI)
	rts

;------------------------------------------------------------------------------
; Integer parser met a binary operator: converts the operand so far to float ($8006) and continues in the
; general parser with this operator; the result is converted back with $8005 (float to int).
;------------------------------------------------------------------------------
int_operator_to_float_parser:
	pea	emit_float_to_int_after_operator(pc) ; on return: convert the result to int
	clr.w	-(sp)                           ; precedence 0 for the general parser
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	bra.w	dispatch_operator               ; the operator in the general parser

emit_float_to_int_after_operator:
	move.w	#$8005,(a4)+                    ; IR $8005: float to int (FFTOI)
	rts

;------------------------------------------------------------------------------
; Integer expression parser (result in d0). Handles integer operands itself (integer constants, %, &, |, !
; variables and arrays, secondary functions); anything else falls back to the general parser wrapped in
; $8006 (int to float) ... $8005 (float to int). Entry: a5 = tokens, a4 = IR. Exit: a5 after the terminator.
;------------------------------------------------------------------------------
parse_integer_expression:
	moveq	#0,d7                           ; clear the high byte
	move.b	(a5)+,d7                        ; d7 = operand token
	move.w	d7,d6                           ; d6 = the token for the handler
	add.w	d7,d7                           ; word table index
	lea	integer_token_table(pc,d7.w),a0
	adda.w	(a0),a0                         ; a0 = the handler
	moveq	#0,d0                           ; d0 = 0 for the handler
	jsr	(a0)                            ; operand
	moveq	#0,d7                           ; clear the high byte
