; Option $C+ / $C- (set by the option parser at $6330, read at $670e, $67a8, $67b4, $681a).
option_c_flag:
	dc.w	$0000                           ; option $C+ / $C-

;------------------------------------------------------------------------------
; Unary minus: operand (with a following ^), then IR $802d (negate float).
;------------------------------------------------------------------------------
parse_unary_minus:
	bsr.s	parse_unary_operand             ; the operand, with a following ^
	move.w	#$802d,(a4)+                    ; IR $802d: negate float
	rts

;------------------------------------------------------------------------------
; Parses one operand of the general parser; a following ^ is applied first ($8002, operand, $8004, $8055),
; since ^ binds tighter than the sign.
;------------------------------------------------------------------------------
parse_unary_operand:
	moveq	#0,d7                           ; clear the high byte
	move.b	(a5)+,d7                        ; d7 = operand token
	add.w	d7,d7                           ; word table index
	lea	expression_token_table(pc),a0
	adda.w	d7,a0
	adda.w	(a0),a0                         ; a0 = the handler
	moveq	#0,d0                           ; d0 = 0 for the handler
	jsr	(a0)                            ; the operand
	cmpi.b	#$9,(a5)                        ; $09 = ^
	beq.s	.apply_power
	rts
.apply_power:
	addq.l	#1,a5                           ; skip the ^
	moveq	#0,d7                           ; clear the high byte
	move.b	(a5)+,d7                        ; d7 = exponent operand token
	add.w	d7,d7                           ; word table index
	lea	expression_token_table(pc),a0
	adda.w	d7,a0
	adda.w	(a0),a0                         ; a0 = the handler
	movea.l	a0,a3                           ; a3 = the handler
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	jsr	(a0)                            ; the exponent operand
	move.w	#$8004,(a4)+                    ; IR $8004: pop float into d3-d5
	move.w	#$8055,(a4)+                    ; IR $8055: float ^
	rts

parse_long_constant_padded_as_float:
	addq.l	#1,a5                           ; odd token: skip the pad byte

;------------------------------------------------------------------------------
; Integer constant in a float expression: IR $8007 + long, then $8006.
;------------------------------------------------------------------------------
parse_long_constant_as_float:
	bsr.s	parse_long_constant             ; IR $8007 + the long
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	rts

parse_long_constant_padded:
	addq.l	#1,a5                           ; odd token: skip the pad byte

;------------------------------------------------------------------------------
; Integer constant: the long after the token, IR $8007 + long.
;------------------------------------------------------------------------------
parse_long_constant:
	move.l	(a5)+,d0                        ; d0 = the constant

emit_int_constant_ir:
	move.w	#$8007,(a4)+                    ; IR $8007: integer constant (long follows)
	move.l	d0,(a4)+                        ; the constant
	rts

emit_int_zero:
	moveq	#0,d0                           ; 0
	bra.s	emit_int_constant_ir

emit_int_one:
	moveq	#1,d0                           ; 1
	bra.s	emit_int_constant_ir

emit_int_two:
	moveq	#2,d0                           ; 2
	bra.s	emit_int_constant_ir

emit_int_three:
	moveq	#3,d0                           ; 3
	bra.s	emit_int_constant_ir

emit_int_true:
	moveq	#-1,d0                          ; TRUE = -1
	bra.s	emit_int_constant_ir

parse_float_constant_padded:
	addq.l	#1,a5                           ; odd token: skip the pad byte

;------------------------------------------------------------------------------
; Float constant: IR $8000 + 8 bytes (mantissa, exponent word); a zero exponent clears the mantissa.
;------------------------------------------------------------------------------
parse_float_constant:
	move.w	#$8000,(a4)+                    ; IR $8000: float constant (8 bytes follow)
	move.l	(a5)+,(a4)+                     ; mantissa high long
	move.w	(a5)+,(a4)+                     ; mantissa low word
	move.w	(a5)+,(a4)+                     ; exponent word
	bne.s	.constant_written               ; non-zero exponent: keep the mantissa
	clr.l	-$8(a4)                         ; zero exponent: 0.0
	clr.w	-$4(a4)
.constant_written:
	rts

emit_float_zero:
	move.w	#$8000,(a4)+                    ; IR $8000: float constant (8 bytes follow)
	clr.l	(a4)+                           ; mantissa 0
	clr.l	(a4)+                           ; mantissa and exponent 0
	rts

emit_float_one:
	move.w	#$8000,(a4)+                    ; IR $8000: float constant 1.0
	move.w	#$8000,(a4)+                    ; mantissa $8000 0000 0000
	clr.l	(a4)+
	move.w	#$3ff,(a4)+                     ; exponent $3ff: 1.0
	rts

emit_float_two:
	move.w	#$8000,(a4)+                    ; IR $8000: float constant 2.0
	move.w	#$8000,(a4)+                    ; mantissa $8000 0000 0000
	clr.l	(a4)+
	move.w	#$400,(a4)+                     ; exponent $400: 2.0
	rts

emit_float_three:
	move.w	#$8000,(a4)+                    ; IR $8000: float constant 3.0
	move.w	#$c000,(a4)+                    ; mantissa $c000 0000 0000
	clr.l	(a4)+
	move.w	#$400,(a4)+                     ; exponent $400: 3.0
	rts

emit_float_true:
	move.w	#$8000,(a4)+                    ; IR $8000: float constant -1.0 (TRUE)
	move.w	#$8000,(a4)+                    ; mantissa $8000 0000 0000
	clr.l	(a4)+
	move.w	#$fc01,(a4)+                    ; exponent $fc01 = -$3ff: negative, so -1.0
	rts

;------------------------------------------------------------------------------
; String + (precedence 65): $8018, right operand, $8023, library SADD ($13f).
;------------------------------------------------------------------------------
parse_op_string_concat:
	moveq	#65,d7                          ; precedence 65
	move.w	#$13f,d6                        ; library SADD ($13f)
	cmp.w	(sp),d7                         ; binds tighter than the level on the stack?
	bhi.s	.concat_right_operand
	addq.l	#2,sp                           ; no: drop the precedence word, return
	rts
.concat_right_operand:
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	move.w	d6,-(sp)                        ; routine for after the right operand
	bsr.w	parse_expression_above          ; right operand
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	(sp)+,(a4)+                     ; IR: library routine
	jmp	(a3)                            ; on with the operator that ended it

parse_op_string_equal:
	moveq	#60,d7                          ; precedence 60
	move.w	#$144,d6                        ; library SEQ ($144)
	bra.s	emit_string_compare

parse_op_string_not_equal:
	moveq	#60,d7                          ; precedence 60
	move.w	#$145,d6                        ; library SNE ($145)
	bra.s	emit_string_compare

parse_op_string_greater:
	moveq	#60,d7                          ; precedence 60
	move.w	#$142,d6                        ; library SGT ($142)
	bra.s	emit_string_compare

parse_op_string_greater_equal:
	moveq	#60,d7                          ; precedence 60
	move.w	#$140,d6                        ; library SGE ($140)
	bra.s	emit_string_compare

parse_op_string_less_equal:
	moveq	#60,d7                          ; precedence 60
	move.w	#$141,d6                        ; library SLE ($141)
	bra.s	emit_string_compare

parse_op_string_less:
	moveq	#60,d7                          ; precedence 60
	move.w	#$143,d6                        ; library SLT ($143)

;------------------------------------------------------------------------------
; String compare operators (precedence 60): $8018 (push left string), right operand, $8023 (pop left into a1),
; library SGE/SLE/SGT/SLT/SEQ/SNE in d6, then $8006 (int result to float).
;------------------------------------------------------------------------------
emit_string_compare:
	cmp.w	(sp),d7                         ; binds tighter than the level on the stack?
	bhi.s	.compare_right_string
	addq.l	#2,sp                           ; no: drop the precedence word, return
	rts
.compare_right_string:
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	move.w	d6,-(sp)                        ; compare routine for after the right operand
	bsr.w	parse_expression_above          ; right operand
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	(sp)+,(a4)+                     ; IR: library compare routine
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	jmp	(a3)                            ; on with the operator that ended it

parse_op_and:
	move.w	#$8060,d0                       ; IR $8060: int AND
	bra.s	emit_logical_operator

parse_op_or:
	move.w	#$8061,d0                       ; IR $8061: int OR
	bra.s	emit_logical_operator

parse_op_xor:
	move.w	#$8062,d0                       ; IR $8062: int XOR
	bra.s	emit_logical_operator

parse_op_eqv:
	move.w	#$8066,d0                       ; IR $8066: int EQV
	bra.s	emit_logical_operator

parse_op_imp:
	move.w	#$8067,d0                       ; IR $8067: int IMP

;------------------------------------------------------------------------------
; AND OR XOR IMP EQV (precedence 4): left to int ($8005) and pushed ($8017), right operand to int, $801b
; (pop left into d1), operation IR ($8060 AND, $8061 OR, $8062 XOR, $8066 EQV, $8067 IMP), $8006.
;------------------------------------------------------------------------------
emit_logical_operator:
	moveq	#4,d7                           ; precedence 4
	cmp.w	(sp),d7                         ; binds tighter than the level on the stack?
	bhi.s	.logical_right_operand
	addq.l	#2,sp                           ; no: drop the precedence word, return
	rts
.logical_right_operand:
	move.w	d0,-(sp)                        ; operation IR for after the right operand
	move.w	#$8005,(a4)+                    ; IR $8005: float to int (FFTOI)
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))
	bsr.w	parse_expression_above          ; right operand
	move.w	#$8005,(a4)+                    ; IR $8005: float to int (FFTOI)
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	(sp)+,(a4)+                     ; operation IR
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	jmp	(a3)                            ; on with the operator that ended it

;------------------------------------------------------------------------------
; NOT: integer expression, then IR $8032 (NOT) and $8006. The terminator is given back (subq.l #1,a5).
;------------------------------------------------------------------------------
parse_op_not:
	bsr.w	parse_integer_expression        ; the operand as an integer
	subq.l	#1,a5                           ; give the terminator back
	move.w	#$8032,(a4)+                    ; IR $8032: NOT
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	rts

parse_fn_mul:
	move.w	#$805e,d0                       ; IR $805e: int MUL
	bra.s	emit_int_operation

parse_fn_div:
	move.w	#$805f,d0                       ; IR $805f: int DIV
	bra.s	emit_swapped_int_operation

parse_fn_mod:
	move.w	#$8065,d0                       ; IR $8065: int MOD
	bra.s	emit_swapped_int_operation

parse_fn_shl:
	move.w	#$8068,d0                       ; IR $8068: SHL
	bra.s	emit_swapped_int_operation

parse_fn_shr:
	move.w	#$8069,d0                       ; IR $8069: SHR
	bra.s	emit_swapped_int_operation

parse_fn_rol:
	move.w	#$806a,d0                       ; IR $806a: ROL
	bra.s	emit_swapped_int_operation

parse_fn_ror:
	move.w	#$806b,d0                       ; IR $806b: ROR
	bra.s	emit_swapped_int_operation

parse_fn_shl_word:
	move.w	#$806c,d0                       ; IR $806c: SHL&
	bra.s	emit_swapped_int_operation

parse_fn_shr_word:
	move.w	#$806d,d0                       ; IR $806d: SHR&
	bra.s	emit_swapped_int_operation

parse_fn_rol_word:
	move.w	#$806e,d0                       ; IR $806e: ROL&
	bra.s	emit_swapped_int_operation

parse_fn_ror_word:
	move.w	#$806f,d0                       ; IR $806f: ROR&
	bra.s	emit_swapped_int_operation

parse_fn_shl_byte:
	move.w	#$8070,d0                       ; IR $8070: SHL|
	bra.s	emit_swapped_int_operation

parse_fn_shr_byte:
	move.w	#$8071,d0                       ; IR $8071: SHR|
	bra.s	emit_swapped_int_operation

parse_fn_rol_byte:
	move.w	#$8072,d0                       ; IR $8072: ROL|
	bra.s	emit_swapped_int_operation

parse_fn_ror_byte:
	move.w	#$8073,d0                       ; IR $8073: ROR|
	bra.s	emit_swapped_int_operation

parse_fn_btst:
	move.w	#$8074,d0                       ; IR $8074: BTST
	bra.s	emit_swapped_int_operation

parse_fn_bset:
	move.w	#$8075,d0                       ; IR $8075: BSET
	bra.s	emit_swapped_int_operation

parse_fn_bclr:
	move.w	#$8076,d0                       ; IR $8076: BCLR
	bra.s	emit_swapped_int_operation

parse_fn_bchg:
	move.w	#$8077,d0                       ; IR $8077: BCHG

;------------------------------------------------------------------------------
; Integer function with two arguments where the order matters: writes $8083 after the arguments (exchanges
; the two operands, as far as can be told) and then the operation IR from the stack.
;------------------------------------------------------------------------------
emit_swapped_int_operation:
	move.w	d0,-(sp)
	move.w	#$8083,d0                       ; IR $8083: exchange operands
	bsr.w	emit_code_after_two_ints        ; both arguments, then $8083
	move.w	(sp)+,(a4)+                     ; then the operation IR
	rts

parse_fn_and:
	move.w	#$8060,d0                       ; IR $8060: int AND

;------------------------------------------------------------------------------
; Integer function with two commutative arguments: emit_code_after_two_ints with the operation IR in d0
; ($805e MUL, $8060 AND, $8061 OR, $8062 XOR, $8063 ADD, $8066 EQV, $8067 IMP).
;------------------------------------------------------------------------------
emit_int_operation:
	bra.w	emit_code_after_two_ints        ; both arguments, then the operation IR

parse_fn_or:
	move.w	#$8061,d0                       ; IR $8061: int OR
	bra.s	emit_int_operation

parse_fn_xor:
	move.w	#$8062,d0                       ; IR $8062: int XOR
	bra.s	emit_int_operation

parse_fn_eqv:
	move.w	#$8066,d0                       ; IR $8066: int EQV
	bra.s	emit_int_operation

parse_fn_imp:
	move.w	#$8067,d0                       ; IR $8067: int IMP
	bra.s	emit_int_operation

parse_fn_add:
	move.w	#$8063,d0                       ; IR $8063: int ADD
	bra.s	emit_int_operation

parse_fn_sub:
	move.w	#$8064,d0                       ; IR $8064: int SUB
	bra.s	emit_swapped_int_operation

parse_op_add:
	moveq	#30,d7                          ; precedence 30
	move.w	#$804a,d6                       ; IR $804a: float +
	bra.s	emit_float_operator

parse_op_subtract:
	moveq	#30,d7                          ; precedence 30
	move.w	#$804c,d6                       ; IR $804c: float -
	bra.s	emit_float_operator

parse_op_multiply:
	moveq	#40,d7                          ; precedence 40
	move.w	#$804d,d6                       ; IR $804d: float *
	bra.s	emit_float_operator

parse_op_divide:
	moveq	#40,d7                          ; precedence 40
	move.w	#$804f,d6                       ; IR $804f: float /
	bra.s	emit_float_operator

parse_op_mod:
	moveq	#35,d7                          ; precedence 35
	move.w	#$8053,d6                       ; IR $8053: float MOD
	bra.s	emit_float_operator

parse_op_int_divide:
	moveq	#35,d7                          ; precedence 35
	move.w	#$8051,d6                       ; IR $8051: float DIV
	bra.s	emit_float_operator

parse_op_power:
	moveq	#50,d7                          ; precedence 50
	move.w	#$8055,d6                       ; IR $8055: float ^

;------------------------------------------------------------------------------
; Float operators: $8002 (push left), right operand at precedence d7, $8004 (pop left into d3-d5), operation
; IR in d6 ($804a +, $804c -, $804d *, $804f /, $8051 DIV, $8053 MOD, $8055 ^).
;------------------------------------------------------------------------------
emit_float_operator:
	cmp.w	(sp),d7                         ; binds tighter than the level on the stack?
	bhi.s	.float_right_operand
	addq.l	#2,sp                           ; no: drop the precedence word, return
	rts
.float_right_operand:
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	move.w	d6,-(sp)                        ; operation IR for after the right operand
	bsr.w	parse_expression_above          ; right operand
	move.w	#$8004,(a4)+                    ; IR $8004: pop float into d3-d5
	move.w	(sp)+,(a4)+                     ; operation IR
	jmp	(a3)                            ; on with the operator that ended it

parse_op_approx_equal:
	moveq	#10,d7                          ; precedence 10
	move.w	#$805c,d6                       ; IR $805c: float ==
	bra.s	emit_float_compare

parse_op_equal:
	moveq	#10,d7                          ; precedence 10
	move.w	#$805a,d6                       ; IR $805a: float =
	bra.s	emit_float_compare

parse_op_not_equal:
	moveq	#10,d7                          ; precedence 10
	move.w	#$805b,d6                       ; IR $805b: float <>
	bra.s	emit_float_compare

parse_op_greater:
	moveq	#10,d7                          ; precedence 10
	move.w	#$8058,d6                       ; IR $8058: float >
	bra.s	emit_float_compare

parse_op_greater_equal:
	moveq	#10,d7                          ; precedence 10
	move.w	#$8059,d6                       ; IR $8059: float >=
	bra.s	emit_float_compare

parse_op_less_equal:
	moveq	#10,d7                          ; precedence 10
	move.w	#$8057,d6                       ; IR $8057: float <=
	bra.s	emit_float_compare

parse_op_less:
	moveq	#10,d7                          ; precedence 10
	move.w	#$8056,d6                       ; IR $8056: float <

;------------------------------------------------------------------------------
; Float compares (precedence 10): like emit_float_operator, IR $8056 <, $8057 <=, $8058 >, $8059 >=, $805a =,
; $805b <>, $805c ==, then $8006 (int result to float).
;------------------------------------------------------------------------------
emit_float_compare:
	cmp.w	(sp),d7                         ; binds tighter than the level on the stack?
	bhi.s	.compare_right_operand
	addq.l	#2,sp                           ; no: drop the precedence word, return
	rts
.compare_right_operand:
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	move.w	d6,-(sp)                        ; compare IR for after the right operand
	bsr.w	parse_expression_above          ; right operand
	move.w	#$8004,(a4)+                    ; IR $8004: pop float into d3-d5
	move.w	(sp)+,(a4)+                     ; compare IR
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	jmp	(a3)                            ; on with the operator that ended it

;------------------------------------------------------------------------------
; SUCC(n): a constant is incremented in place, otherwise IR $8008 1 (constant operand) and $8063 (ADD).
;------------------------------------------------------------------------------
parse_fn_succ:
	bsr.s	parse_int_test_constant         ; Z: the argument is one constant
	bne.s	.add_one                        ; not a constant
	addq.l	#1,-(a0)                        ; fold: constant + 1
	rts
.add_one:
	move.w	#$8008,(a4)+                    ; IR $8008: constant second operand (long follows)
	moveq	#1,d0                           ; 1
	move.l	d0,(a4)+
	move.w	#$8063,(a4)+                    ; IR $8063: int ADD
	rts

;------------------------------------------------------------------------------
; PRED(n): a constant is decremented in place, otherwise IR $8008 1 and $8064 (SUB).
;------------------------------------------------------------------------------
parse_fn_pred:
	bsr.s	parse_int_test_constant         ; Z: the argument is one constant
	bne.s	.subtract_one                   ; not a constant
	subq.l	#1,-(a0)                        ; fold: constant - 1
	rts
.subtract_one:
	move.w	#$8008,(a4)+                    ; IR $8008: constant second operand (long follows)
	moveq	#1,d0                           ; 1
	move.l	d0,(a4)+
	move.w	#$8064,(a4)+                    ; IR $8064: int SUB
	rts

;------------------------------------------------------------------------------
; Parses an integer expression and tests whether its IR is just one constant.
; Exit: Z set when it is; then d0 = value, a0 = a4 (after the constant).
;------------------------------------------------------------------------------
parse_int_test_constant:
	pea	(a4)                            ; start of the argument's IR
	bsr.w	parse_integer_expression        ; the argument
	movea.l	(sp)+,a0                        ; a0 = the argument's IR
	cmpi.w	#$8007,(a0)+                    ; IR $8007: integer constant (long follows)
	bne.s	.constant_tested
	move.l	(a0)+,d0                        ; d0 = the constant
	cmpa.l	a0,a4                           ; Z: nothing after it
.constant_tested:
	rts

;------------------------------------------------------------------------------
; CARD(n): constant folded, otherwise IR $8030.
;------------------------------------------------------------------------------
parse_fn_card:
	bsr.s	parse_int_test_constant         ; Z: the argument is one constant
	bne.s	.emit_card                      ; not a constant
	clr.w	-$4(a0)                         ; fold: clear the high word
	rts
.emit_card:
	move.w	#$8030,(a4)+                    ; IR $8030: CARD()
	rts

;------------------------------------------------------------------------------
; WORD(n): constant folded, otherwise IR $802f.
;------------------------------------------------------------------------------
parse_fn_word:
	bsr.s	parse_int_test_constant         ; Z: the argument is one constant
	bne.s	.emit_word                      ; not a constant
	ext.l	d0                              ; fold: sign-extend the low word
	move.l	d0,-(a0)                        ; write it back
	rts
.emit_word:
	move.w	#$802f,(a4)+                    ; IR $802f: WORD()
	rts

;------------------------------------------------------------------------------
; BYTE(n): constant folded, otherwise IR $802e.
;------------------------------------------------------------------------------
parse_fn_byte:
	bsr.s	parse_int_test_constant         ; Z: the argument is one constant
	bne.s	.emit_byte                      ; not a constant
	andi.l	#$ff,d0                         ; fold: keep the low byte
	move.l	d0,-(a0)                        ; write it back
	rts
.emit_byte:
	move.w	#$802e,(a4)+                    ; IR $802e: BYTE()
	rts

;------------------------------------------------------------------------------
; SWAP(n): constant folded, otherwise IR $8031.
;------------------------------------------------------------------------------
parse_fn_swap:
	bsr.s	parse_int_test_constant         ; Z: the argument is one constant
	bne.s	.emit_swap                      ; not a constant
	swap	d0                              ; fold: swap the words
	move.l	d0,-(a0)                        ; write it back
	rts
.emit_swap:
	move.w	#$8031,(a4)+                    ; IR $8031: SWAP()
	rts

parse_float_var_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

;------------------------------------------------------------------------------
; Variable loads: IR $803e float, $803b string, $803f int, $803c bool, $8040 word, $803d byte + index.
; Tokens $e0-$ef have a one-byte index, $f0-$ff a two-byte index (the _wide entries read the high byte).
; In the general parser integer types are followed by $8006.
;------------------------------------------------------------------------------
parse_float_var:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803e,(a4)+                    ; IR $803e: load float variable
	move.w	d0,(a4)+                        ; variable index
	rts

parse_string_var_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_string_var:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803b,(a4)+                    ; IR $803b: load string variable
	move.w	d0,(a4)+                        ; variable index
	rts

parse_int_var_as_float_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_int_var_as_float:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803f,(a4)+                    ; IR $803f: load int variable
	move.w	d0,(a4)+                        ; variable index
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	rts

parse_word_var_as_float_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_word_var_as_float:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$8040,(a4)+                    ; IR $8040: load word variable
	move.w	d0,(a4)+                        ; variable index
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	rts

parse_byte_var_as_float_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_byte_var_as_float:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803d,(a4)+                    ; IR $803d: load byte variable
	move.w	d0,(a4)+                        ; variable index
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	rts

parse_bool_var_as_float_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_bool_var_as_float:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803c,(a4)+                    ; IR $803c: load bool variable
	move.w	d0,(a4)+                        ; variable index
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	rts

parse_int_var_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_int_var:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803f,(a4)+                    ; IR $803f: load int variable
	move.w	d0,(a4)+                        ; variable index
	rts

parse_word_var_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_word_var:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$8040,(a4)+                    ; IR $8040: load word variable
	move.w	d0,(a4)+                        ; variable index
	rts

parse_byte_var_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_byte_var:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803d,(a4)+                    ; IR $803d: load byte variable
	move.w	d0,(a4)+                        ; variable index
	rts

parse_bool_var_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_bool_var:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$803c,(a4)+                    ; IR $803c: load bool variable
	move.w	d0,(a4)+                        ; variable index
	rts

parse_word_element_as_float_wide:
	move.b	(a5)+,-(sp)                     ; high byte of a two-byte index
	move.w	(sp)+,d0                        ; into the high byte of d0

parse_word_element_as_float:
	move.b	(a5)+,d0                        ; low byte of the index
	move.w	#$80c2,d1                       ; IR $80c2: load word element
	bra.s	emit_element_as_float

parse_byte_element_as_float_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_byte_element_as_float:
	move.b	(a5)+,d0
	move.w	#$80c3,d1                       ; IR $80c3: load byte element
	bra.s	emit_element_as_float

parse_bool_element_as_float_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_bool_element_as_float:
	move.b	(a5)+,d0
	move.w	#$80c4,d1                       ; IR $80c4: load bool element
	bra.s	emit_element_as_float

parse_int_element_as_float_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_int_element_as_float:
	move.b	(a5)+,d0
	move.w	#$80c1,d1                       ; IR $80c1: load int element

emit_element_as_float:
	bsr.s	emit_array_element              ; element load IR
	move.w	#$8006,(a4)+                    ; IR $8006: int to float
	rts

parse_float_element_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_float_element:
	move.b	(a5)+,d0
	move.w	#$80c5,d1                       ; IR $80c5: load float element
	bra.s	emit_array_element

parse_string_element_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_string_element:
	move.b	(a5)+,d0
	move.w	#$80c6,d1                       ; IR $80c6: load string element
	bra.s	emit_array_element

parse_word_element_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_word_element:
	move.b	(a5)+,d0
	move.w	#$80c2,d1                       ; IR $80c2: load word element
	bra.s	emit_array_element

parse_byte_element_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_byte_element:
	move.b	(a5)+,d0
	move.w	#$80c3,d1                       ; IR $80c3: load byte element
	bra.s	emit_array_element

parse_bool_element_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_bool_element:
	move.b	(a5)+,d0
	move.w	#$80c4,d1                       ; IR $80c4: load bool element
	bra.s	emit_array_element

parse_int_element_wide:
	move.b	(a5)+,-(sp)
	move.w	(sp)+,d0

parse_int_element:
	move.b	(a5)+,d0
	move.w	#$80c1,d1                       ; IR $80c1: load int element

;------------------------------------------------------------------------------
; Array element load. Entry: d0 = array index, d1 = IR ($80c1 int, $80c2 word, $80c3 byte, $80c4 bool,
; $80c5 float, $80c6 string). Pushes every index, pops one into d4 ($801e) or two into d5/d4, writes IR,
; array index, index count. Gives the terminator back unless it is ")=" ($39).
;------------------------------------------------------------------------------
emit_array_element:
	move.w	d0,-(sp)                        ; d0 = array number
	move.w	d1,-(sp)                        ; d1 = element load IR
	clr.w	-(sp)                           ; index count = 0
.next_index:
	bsr.w	parse_int_and_push              ; each index parsed as an integer and pushed
	addq.w	#1,(sp)                         ; count this index
	cmpi.b	#$21,-$1(a5)                    ; token $21 = ",": another index follows
	beq.s	.next_index
	cmpi.b	#$39,-(a5)                      ; token $39 = ")=" is left for the caller to read
	beq.s	.indices_done
	addq.l	#1,a5                           ; otherwise step past the terminator again
.indices_done:
	movem.w	(sp)+,d0-d2                     ; d0 = index count, d1 = load IR, d2 = array number
	move.w	d0,d3                           ; d3 = index count for the IR
	subq.w	#1,d0                           ; one index: pop it into d4 only
	beq.s	.pop_one_index
	subq.w	#1,d0                           ; two indices: pop into d5 and d4
	bne.s	.write_element_ir               ; more than two: they stay on the stack
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
.pop_one_index:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
.write_element_ir:
	move.w	d1,(a4)+                        ; element load IR
	move.w	d2,(a4)+                        ; array number
	move.w	d3,(a4)+                        ; number of indices
	rts

parse_fn_gemdos:
	move.w	#$8024,d0                       ; IR $8024: trap #1 GEMDOS (stack bytes follow)
	bra.s	emit_trap_call

parse_fn_bios:
	move.w	#$8025,d0                       ; IR $8025: trap #13 BIOS
	bra.s	emit_trap_call

parse_fn_xbios:
	move.w	#$8026,d0                       ; IR $8026: trap #14 XBIOS

;------------------------------------------------------------------------------
; GEMDOS( BIOS( XBIOS(: d0 = $8024 / $8025 / $8026 (trap #1 / #13 / #14). Each argument (L: long, W: or none
; word) is parsed and its IR moved onto the CPU stack, so the IR comes out in reverse order; then the trap IR
; and the number of argument bytes.
;------------------------------------------------------------------------------
emit_trap_call:
	move.w	d0,-(sp)                        ; trap IR kept on the stack under the arguments
	movea.l	sp,a1                           ; a1 = stack mark where the moved IR ends
	moveq	#0,d1                           ; d1 = argument bytes on the 68000 stack
.next_argument:
	cmpi.b	#$8b,(a5)+                      ; $8b = W:
	beq.s	.word_argument
	cmpi.b	#$8a,-(a5)                      ; $8a = L:
	beq.s	.long_argument
	cmpi.b	#$20,-$1(a5)                    ; token $20 = ")" was read: call ended
	beq.s	.arguments_done
	cmpi.b	#$20,(a5)                       ; ")" next: step past it and finish
	bne.s	.word_argument                  ; anything else: a word argument without W:
	addq.l	#1,a5
	bra.s	.arguments_done
.word_argument:
	movem.l	d1/a0-a2/a4,-(sp)               ; a4 saved so that it comes back as a3
	bsr.w	parse_int_and_push_word
	movem.l	(sp)+,d1/a0-a3                  ; a3 = start of this argument's IR
	addq.w	#2,d1                           ; word argument: 2 bytes
	bra.s	.move_argument_to_stack
.long_argument:
	addq.l	#1,a5                           ; skip the L: token
	movem.l	d1/a0-a2/a4,-(sp)               ; a4 saved so that it comes back as a3
	bsr.w	parse_int_and_push
	movem.l	(sp)+,d1/a0-a3                  ; a3 = start of this argument's IR
	addq.l	#4,d1                           ; long argument: 4 bytes
.move_argument_to_stack:
	move.w	-(a4),-(sp)                     ; move this argument's IR to the stack
	cmpa.l	a3,a4                           ; until all of the argument's IR is on the stack
	bne.s	.move_argument_to_stack
	bra.s	.next_argument                  ; back for the next argument
.arguments_done:
	move.w	(sp)+,(a4)+                     ; IR back, last argument first
	cmpa.l	a1,sp                           ; until the stack mark
	bne.s	.arguments_done
	move.w	(sp)+,(a4)+                     ; trap IR ($8024/$8025/$8026)
	move.w	d1,(a4)+                        ; number of argument bytes
	rts

parse_fn_malloc:
	moveq	#72,d0                          ; GEMDOS 72 = Malloc
	bra.s	emit_gemdos_one_arg

parse_fn_mfree:
	moveq	#73,d0                          ; GEMDOS 73 = Mfree
	bra.s	emit_gemdos_one_arg

parse_fn_fsetdta:
	moveq	#26,d0                          ; GEMDOS 26 = Fsetdta

;------------------------------------------------------------------------------
; GEMDOS call with one long argument: IR long pushed, $8007 function number, $8027 (push word), $8024 6
; (trap #1, 6 bytes). MALLOC 72, MFREE 73, FSETDTA 26.
;------------------------------------------------------------------------------
emit_gemdos_one_arg:
	move.l	d0,-(sp)                        ; save the function number
	bsr.w	parse_int_and_push              ; the long argument, pushed
	move.w	#$8007,(a4)+                    ; IR $8007: integer constant (long follows)
	move.l	(sp)+,(a4)+                     ; function number as the constant
	move.w	#$8027,(a4)+                    ; IR $8027: push word (move.w d0,-(sp))
	move.w	#$8024,(a4)+                    ; IR $8024: trap #1 GEMDOS (stack bytes follow)
	move.w	#$6,(a4)+                       ; 6 bytes: function word + long
	rts

;------------------------------------------------------------------------------
; MSHRINK(a,n): two longs pushed, word 0, function 74, trap #1 with 12 bytes.
;------------------------------------------------------------------------------
parse_fn_mshrink:
	bsr.w	parse_int_and_push              ; first argument pushed
	bsr.w	parse_int_and_push              ; second argument pushed
	move.w	#$8007,(a4)+                    ; IR $8007: integer constant (long follows)
	clr.l	(a4)+                           ; constant 0: the reserved word
	move.w	#$8027,(a4)+                    ; IR $8027: push word (move.w d0,-(sp))
	move.w	#$8007,(a4)+                    ; IR $8007: integer constant (long follows)
	moveq	#74,d0                          ; GEMDOS 74 = Mshrink
	move.l	d0,(a4)+                        ; function number as the constant
	move.w	#$8027,(a4)+                    ; IR $8027: push word (move.w d0,-(sp))
	move.w	#$8024,(a4)+                    ; IR $8024: trap #1 GEMDOS (stack bytes follow)
	move.w	#$c,(a4)+                       ; 12 bytes: two words and two longs
	rts

parse_fn_fsnext:
	moveq	#79,d0                          ; GEMDOS 79 = Fsnext
	bra.s	emit_gemdos_no_arg

parse_fn_fgetdta:
	moveq	#47,d0                          ; GEMDOS 47 = Fgetdta

;------------------------------------------------------------------------------
; GEMDOS call without arguments: function number in d0 (FSNEXT 79, FGETDTA 47), trap #1 with 2 bytes.
;------------------------------------------------------------------------------
emit_gemdos_no_arg:
	move.w	#$8007,(a4)+                    ; IR $8007: integer constant (long follows)
	move.l	d0,(a4)+                        ; function number as the constant
	move.w	#$8027,(a4)+                    ; IR $8027: push word (move.w d0,-(sp))
	move.w	#$8024,(a4)+                    ; IR $8024: trap #1 GEMDOS (stack bytes follow)
	move.w	#$2,(a4)+                       ; 2 bytes: the function word only
	rts

;------------------------------------------------------------------------------
; String literal (token $de, length byte): IR $80e9 empty, $80ea one char, $80eb two chars, $80ec four chars
; (the characters follow), otherwise $80ed + length + pointer to the text in the source.
;------------------------------------------------------------------------------
parse_string_constant:
	moveq	#0,d0
	move.b	(a5)+,d0                        ; d0 = string length
	beq.s	.empty_string                   ; length 0
	subq.w	#1,d0                           ; length 1
	beq.s	.one_char_string
	subq.w	#1,d0                           ; length 2
	beq.s	.two_char_string
	subq.w	#2,d0                           ; length 4
	beq.s	.four_char_string
	addq.w	#4,d0                           ; any other length: d0 back to the length
	move.w	#$80ed,(a4)+                    ; IR $80ed: string literal (length, pointer)
	move.w	d0,(a4)+                        ; length
	move.l	a5,(a4)+                        ; pointer to the characters in the source
	adda.w	d0,a5                           ; skip the characters
	rts
.empty_string:
	move.w	#$80e9,(a4)+                    ; IR $80e9: empty string
	rts
.one_char_string:
	move.w	#$80ea,(a4)+                    ; IR $80ea: one-char string
	move.b	(a5)+,d0                        ; the character, written as a word
	move.w	d0,(a4)+
	rts
.two_char_string:
	move.w	#$80eb,(a4)+                    ; IR $80eb: two-char string
	move.b	(a5)+,(a4)+                     ; the two characters
	move.b	(a5)+,(a4)+
	rts
.four_char_string:
	move.w	#$80ec,(a4)+                    ; IR $80ec: four-char string
	move.b	(a5)+,(a4)+                     ; the four characters
	move.b	(a5)+,(a4)+
	move.b	(a5)+,(a4)+
	move.b	(a5)+,(a4)+
	rts

;------------------------------------------------------------------------------
; Integer argument: parse_integer_expression, then IR $8017 (push d0 as a long).
;------------------------------------------------------------------------------
parse_int_and_push:
	bsr.w	parse_integer_expression
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))
	rts

;------------------------------------------------------------------------------
; Integer argument pushed as a word: parse_integer_expression, IR $8027 (move.w d0,-(sp)).
;------------------------------------------------------------------------------
parse_int_and_push_word:
	bsr.w	parse_integer_expression
	move.w	#$8027,(a4)+                    ; IR $8027: push word (move.w d0,-(sp))
	rts

;------------------------------------------------------------------------------
; d0 = routine / IR code. Parses one argument and throws its IR away (dummy arguments such as RND(x), POS(x)),
; then writes d0.
;------------------------------------------------------------------------------
emit_code_ignoring_argument:
	move.w	d0,-(sp)                        ; save the code
	pea	(a4)                            ; save the IR position
	bsr.w	parse_expression                ; the argument, parsed only to skip it
	movea.l	(sp)+,a4                        ; IR position back: the argument's IR is dropped
	move.w	(sp)+,(a4)+                     ; write the code
	rts

;------------------------------------------------------------------------------
; d0 = routine / IR code. One general argument (parse_expression), then writes d0.
;------------------------------------------------------------------------------
emit_code_after_value:
	move.w	d0,-(sp)                        ; save the code
	bsr.w	parse_expression                ; the argument
	move.w	(sp)+,(a4)+                     ; write the code
	rts

;------------------------------------------------------------------------------
; d0 = routine. Two strings: first, $8018 (push), second, $8023 (pop first into a1), then d0.
;------------------------------------------------------------------------------
emit_code_after_two_strings:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_expression                ; first string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; second string
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; d0 = routine. String, $8018, integer in d0, $8022 (pop string into a0), then d0.
;------------------------------------------------------------------------------
emit_code_after_string_and_int:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_expression                ; the string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_integer_expression        ; the integer, in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; d0 = routine. Integer pushed, general argument, $801b (integer into d1), then d0.
;------------------------------------------------------------------------------
emit_code_after_int_and_value:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_int_and_push              ; the integer, pushed
	bsr.w	parse_expression                ; the general argument
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; d0 = routine. Two integers pushed, general argument, $801c $801b, then d0.
;------------------------------------------------------------------------------
emit_code_after_two_ints_and_value:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_int_and_push              ; first integer, pushed
	bsr.s	parse_int_and_push              ; second integer, pushed
	bsr.w	parse_expression                ; the general argument
	move.w	#$801c,(a4)+                    ; IR $801c: pop into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; d0 = routine. String pushed, integer pushed, integer in d0, $801b, $8022 (string into a0), then d0.
;------------------------------------------------------------------------------
emit_code_after_string_and_two_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_expression                ; the string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_int_and_push              ; first integer, pushed
	bsr.w	parse_integer_expression        ; second integer, in d0
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; d0 = routine. Integer pushed, integer in d0, $8022 (first into a0), then d0 (OB_ADR( and friends).
;------------------------------------------------------------------------------
emit_code_after_address_and_int:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_int_and_push              ; address, pushed
	bsr.w	parse_integer_expression        ; integer, in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; d0 = routine. Two integers pushed, one in d0, $801b, $8022, then d0 (OB_xxx( assignments).
;------------------------------------------------------------------------------
emit_code_after_address_and_two_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_int_and_push              ; address, pushed
	bsr.w	parse_int_and_push              ; first integer, pushed
	bsr.w	parse_integer_expression        ; second integer, in d0
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; INSTR(a$,b$): two strings ($8018, $8023), then d0.
;------------------------------------------------------------------------------
emit_instr_call:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_expression                ; first string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; second string
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; INSTR(n,a$,b$): integer pushed, two strings, $801b, then d0.
;------------------------------------------------------------------------------
emit_instr_call_start_first:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_int_and_push              ; start position, pushed
	bsr.w	parse_expression                ; first string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; second string
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; INSTR(a$,b$,n): two strings pushed, integer, $8022 $8023, then d0.
;------------------------------------------------------------------------------
emit_instr_call_start_last:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_expression                ; first string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; second string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_integer_expression        ; start position, in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	(sp)+,(a4)+                     ; write the routine number
	rts

;------------------------------------------------------------------------------
; Integer argument lists: each entry pushes one argument (parse_int_and_push) and falls into the next;
; parse_one_int_arg leaves the last argument in d0. parse_eight_int_args = 7 pushed + d0, ...,
; parse_two_int_args = 1 pushed + d0.
;------------------------------------------------------------------------------
parse_eight_int_args:
	bsr.w	parse_int_and_push

;------------------------------------------------------------------------------
; Parses seven integer arguments: all but the last pushed ($8017), the last left in d0.
;------------------------------------------------------------------------------
parse_seven_int_args:
	bsr.w	parse_int_and_push

;------------------------------------------------------------------------------
; Parses six integer arguments: all but the last pushed ($8017), the last left in d0.
;------------------------------------------------------------------------------
parse_six_int_args:
	bsr.w	parse_int_and_push

;------------------------------------------------------------------------------
; Parses five integer arguments: all but the last pushed ($8017), the last left in d0.
;------------------------------------------------------------------------------
parse_five_int_args:
	bsr.w	parse_int_and_push

;------------------------------------------------------------------------------
; Parses four integer arguments: all but the last pushed ($8017), the last left in d0.
;------------------------------------------------------------------------------
parse_four_int_args:
	bsr.w	parse_int_and_push

;------------------------------------------------------------------------------
; Parses three integer arguments: all but the last pushed ($8017), the last left in d0.
;------------------------------------------------------------------------------
parse_three_int_args:
	bsr.w	parse_int_and_push

;------------------------------------------------------------------------------
; Parses two integer arguments: all but the last pushed ($8017), the last left in d0.
;------------------------------------------------------------------------------
parse_two_int_args:
	bsr.w	parse_int_and_push

;------------------------------------------------------------------------------
; Parses one integer argument into d0 (parse_integer_expression).
;------------------------------------------------------------------------------
parse_one_int_arg:
	bra.w	parse_integer_expression

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses n integer arguments (one_int .. eight_ints), pops the pushed ones
; into d1-d7 (IR $801b-$8021, the first argument ends in d1, the last stays in d0) and writes the routine.
;------------------------------------------------------------------------------
emit_code_after_one_int:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_one_int_arg
	bra.s	emit_saved_code_word

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses two integer arguments, pops the pushed ones ($801b, first argument
; into d1, last in d0) and writes d0.
;------------------------------------------------------------------------------
emit_code_after_two_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_two_int_args
	bra.s	pop_arg_to_d1

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses three integer arguments, pops the pushed ones ($801c $801b, first argument
; into d1, last in d0) and writes d0.
;------------------------------------------------------------------------------
emit_code_after_three_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_three_int_args
	bra.s	pop_args_from_d2

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses four integer arguments, pops the pushed ones ($801d-$801b, first argument
; into d1, last in d0) and writes d0.
;------------------------------------------------------------------------------
emit_code_after_four_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_four_int_args
	bra.s	pop_args_from_d3

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses five integer arguments, pops the pushed ones ($801e-$801b, first argument
; into d1, last in d0) and writes d0.
;------------------------------------------------------------------------------
emit_code_after_five_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_five_int_args
	bra.s	pop_args_from_d4

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses six integer arguments, pops the pushed ones ($801f-$801b, first argument
; into d1, last in d0) and writes d0.
;------------------------------------------------------------------------------
emit_code_after_six_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_six_int_args
	bra.s	pop_args_from_d5

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses seven integer arguments, pops the pushed ones ($8020-$801b, first argument
; into d1, last in d0) and writes d0.
;------------------------------------------------------------------------------
emit_code_after_seven_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_seven_int_args
	bra.s	pop_args_from_d6

;------------------------------------------------------------------------------
; d0 = library routine (or IR code). Parses eight integer arguments, pops the pushed ones ($8021-$801b, first argument
; into d1, last in d0) and writes d0.
;------------------------------------------------------------------------------
emit_code_after_eight_ints:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.s	parse_eight_int_args

;------------------------------------------------------------------------------
; Pop chain: writes $8021 (pop into d7) ... $801b (pop into d1), entered at the right register, then the
; routine word from the stack (emit_saved_code_word).
;------------------------------------------------------------------------------
pop_args_from_d7:
	move.w	#$8021,(a4)+                    ; IR $8021: pop into d7

pop_args_from_d6:
	move.w	#$8020,(a4)+                    ; IR $8020: pop into d6

pop_args_from_d5:
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5

pop_args_from_d4:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4

pop_args_from_d3:
	move.w	#$801d,(a4)+                    ; IR $801d: pop into d3

pop_args_from_d2:
	move.w	#$801c,(a4)+                    ; IR $801c: pop into d2

pop_arg_to_d1:
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1

emit_saved_code_word:
	move.w	(sp)+,(a4)+                     ; write the routine number saved by the caller
	rts

parse_fn_long_peek:
	move.w	#$80a6,d0                       ; IR $80a6: LONG{} peek
	bra.s	emit_code_after_one_int

parse_fn_word_peek:
	move.w	#$80a4,d0                       ; IR $80a4: WORD{} peek
	bra.s	emit_code_after_one_int

parse_fn_card_peek:
	move.w	#$80a5,d0                       ; IR $80a5: CARD{} peek
	bra.s	emit_code_after_one_int

parse_fn_byte_peek:
	move.w	#$80a3,d0                       ; IR $80a3: BYTE{} peek
	bra.s	emit_code_after_one_int

parse_fn_timer:
	move.w	#$2f,(a4)+                      ; library TIMER ($2f)
	rts

parse_fn_addrin:
	move.w	#$5e,(a4)+                      ; library ADDRIN ($5e)
	rts

parse_fn_addrout:
	move.w	#$5f,(a4)+                      ; library ADDROUT ($5f)
	rts

parse_fn_contrl:
	move.w	#$60,(a4)+                      ; library CONTRL ($60)
	rts

parse_fn_gcontrl:
	move.w	#$61,(a4)+                      ; library GCONTRL ($61)
