	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push              ; 15th argument: a long (the buffer address)
	bsr.w	parse_integer_expression        ; last argument in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop into a0
	pea	store_evnt_multi_results(pc)    ; the pop chain returns to the result stores
