;------------------------------------------------------------------------------
; RC_INTERSECT(x1,y1,w1,h1,x2,y2,w2,h2): eight integers, library RCW_INTE ($2eb) when option_rc_word_flag is set (option
; RC&) or RC_INTER ($1c1) (option RC%); the second rectangle's variables get the result (store_rc_intersect_results).
;------------------------------------------------------------------------------
parse_fn_rc_intersect:
	bsr.w	parse_four_int_args             ; first rectangle: three pushed, one in d0
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))
	pea	(a5)                            ; token position of the second rectangle, for the stores
	bsr.w	parse_four_int_args             ; second rectangle: three pushed, one in d0
	pea	store_rc_intersect_results(pc)  ; the pop chain returns to the result stores
	tst.b	option_rc_word_flag             ; flag negative: word rectangle variant
	bpl.s	.rc_intersect_long
	move.w	#$2eb,-(sp)                     ; library RCW_INTE ($2eb)
	bra.s	.pop_arguments
.rc_intersect_long:
	move.w	#$1c1,-(sp)                     ; library RC_INTER ($1c1)
.pop_arguments:
	bra.w	pop_args_from_d7                ; pop seven into d7-d1, then write the routine

store_rc_intersect_results:
	movea.l	(sp)+,a5                        ; a5 = second rectangle: its variables get the result
	bra.w	store_four_results              ; store into the four variables

