	bsr.w	parse_two_int_args              ; x pushed, y in d0
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))
	bsr.w	parse_expression                ; the text
	bra.w	pop_args_from_d2                ; pop into d2-d1, then write the routine

stmt_text_length:
	move.w	#$1ac,-(sp)                     ; library TEXTXYL ($1ac)
	bra.s	emit_text_call

stmt_atext:
	move.w	#$43,-(sp)                      ; library ATEXT ($43)

emit_text_call:
	bsr.w	parse_three_int_args            ; x, y, length: two pushed, one in d0
	move.w	#$8017,(a4)+                    ; IR $8017: push int (move.l d0,-(sp))
	bsr.w	parse_expression                ; the text
	bra.w	pop_args_from_d3                ; pop into d3-d1, then write the routine

;------------------------------------------------------------------------------
; MIN(a,b,...) float: IR $812a between each pair ($8002 / $8004 around the next value). MAX: $812b.
;------------------------------------------------------------------------------
parse_fn_min:
	bsr.w	parse_expression                ; first value
.next_min_argument:
	cmpi.b	#$20,-$1(a5)                    ; token $20 = ")" ended the last value
	beq.s	.min_done
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	bsr.w	parse_expression                ; next value
	move.w	#$8004,(a4)+                    ; IR $8004: pop float into d3-d5
	move.w	#$812a,(a4)+                    ; IR $812a: MIN of two floats
	bra.s	.next_min_argument              ; next pair
.min_done:
	rts

parse_fn_max:
	bsr.w	parse_expression                ; first value
.next_max_argument:
	cmpi.b	#$20,-$1(a5)                    ; token $20 = ")" ended the last value
	beq.s	.max_done
	move.w	#$8002,(a4)+                    ; IR $8002: push float
	bsr.w	parse_expression                ; next value
	move.w	#$8004,(a4)+                    ; IR $8004: pop float into d3-d5
	move.w	#$812b,(a4)+                    ; IR $812b: MAX of two floats
	bra.s	.next_max_argument              ; next pair
.max_done:
	rts

;------------------------------------------------------------------------------
; MIN(a$,b$,...) string: library SMIN ($1d9) between each pair; MAX: SMAX ($1da).
;------------------------------------------------------------------------------
parse_fn_min_str:
	bsr.w	parse_expression                ; first string
.next_min_string:
	cmpi.b	#$20,-$1(a5)                    ; token $20 = ")" ended the last string
	beq.s	.min_string_done
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; next string
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	#$1d9,(a4)+                     ; library SMIN ($1d9)
	bra.s	.next_min_string                ; next pair
.min_string_done:
	rts

parse_fn_max_str:
	bsr.w	parse_expression                ; first string
.next_max_string:
	cmpi.b	#$20,-$1(a5)                    ; token $20 = ")" ended the last string
	beq.s	.max_string_done
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; next string
	move.w	#$8023,(a4)+                    ; IR $8023: pop into a1
	move.w	#$1da,(a4)+                     ; library SMAX ($1da)
	bra.s	.next_max_string                ; next pair
.max_string_done:
	rts

;------------------------------------------------------------------------------
; Parses "integer expression , expression" for the SINGLE{}/FLOAT{}/DOUBLE{} stores.
; Writes the integer (address) followed by IR $8017 (push long), the value expression, then IR $8022
; (pop the pushed long into an argument register). The caller appends the library routine number.
;------------------------------------------------------------------------------
parse_address_and_value:
	bsr.w	parse_int_and_push              ; the address, pushed
	bsr.w	parse_expression                ; the value
	move.w	#$8022,(a4)+                    ; IR $8022: pop the address into a0
	rts

parse_ksingle:
	bsr.s	parse_address_and_value
	move.w	#$35b,(a4)+                     ; library routine $35b KSINGLE
	rts

parse_kfloat:
	bsr.s	parse_address_and_value
	move.w	#$35c,(a4)+                     ; library routine $35c KFLOAT
	rts

parse_kdouble:
	bsr.s	parse_address_and_value
	move.w	#$35a,(a4)+                     ; library routine $35a KDOUBLE
	rts

parse_menu:
	moveq	#0,d0                           ; MENU m$(): read the string array number (bit 4 of the token = two-byte
                                                ;   number)
	btst	#$4,(a5)+
	beq.s	.read_array_number_low
	move.b	(a5)+,d0                        ; high byte of the array number
	asl.w	#8,d0
.read_array_number_low:
	move.b	(a5)+,d0                        ; low byte of the array number
	move.w	#$814f,(a4)+                    ; IR $814f = string array reference, followed by its number
	move.w	d0,(a4)+                        ; string array number
	move.w	#$244,(a4)+                     ; library routine $244 MENU
	rts

parse_menu_off:
	move.w	#$245,(a4)+                     ; library routine $245 MENUOFF
	rts

parse_menu_kill:
	move.w	#$246,(a4)+                     ; library routine $246 MENUKILL
	rts

parse_menu_item:
	cmpi.b	#$37,(a5)                       ; token $37 after the number selects the string form
	beq.s	.menu_item_string
	move.w	#$247,d0                        ; library routine $247 MENUXY, two integer arguments
	bra.w	emit_code_after_two_ints
.menu_item_string:
	addq.l	#1,a5                           ; skip the $37 token
	move.w	#$248,d0                        ; library routine $248 MENUXSTR, integer and string argument
	bra.w	emit_code_after_int_and_value

parse_seek:
	move.w	#$249,d0                        ; library routine $249 SEEK
	bra.w	emit_code_after_two_ints

parse_relseek:
	move.w	#$24a,d0                        ; library routine $24a RELSEEK
	bra.w	emit_code_after_two_ints

parse_set2color:
	move.w	#$1bc,d0                        ; library routine $1bc SET2COLO (SETCOLOR with two arguments)
	bra.w	emit_code_after_two_ints

parse_set4color:
	move.w	#$1bd,d0                        ; library routine $1bd SET4COLO (SETCOLOR with four arguments)
	bra.w	emit_code_after_four_ints

;------------------------------------------------------------------------------
; Statement ALERT icon,text$,default,buttons$,result (command 256): int pushed, string ($8018), int
; pushed, string, then IR $801b $8023 $801c and library routine $1c2 ALERT; the result goes into the
; last variable (store_one_result).
;------------------------------------------------------------------------------
stmt_alert:
	bsr.w	parse_int_and_push              ; icon
	bsr.w	parse_expression                ; text$
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_int_and_push              ; default button, pushed
	bsr.w	parse_expression                ; buttons$
	move.w	#$801b,(a4)+                    ; IR $801b: pop default button into d1
	move.w	#$8023,(a4)+                    ; IR $8023: pop text$ into a1
	move.w	#$801c,(a4)+                    ; IR $801c: pop icon into d2
	move.w	#$1c2,(a4)+                     ; library routine $1c2 ALERT
	bra.w	store_one_result                ; then store the result variable

;------------------------------------------------------------------------------
; Statement GET x1,y1,x2,y2,a$ (command 257): four integers, the string ($8017 before it), IR
; $801e $801f $8020 $8021 and library routine $1be SGET.
;------------------------------------------------------------------------------
stmt_get:
	bsr.w	parse_four_int_args             ; x1,y1,x2,y2
	move.w	#$8017,(a4)+                    ; IR $8017: push y2 as well
	bsr.w	parse_expression                ; the string variable
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
	move.w	#$8020,(a4)+                    ; IR $8020: pop into d6
	move.w	#$8021,(a4)+                    ; IR $8021: pop into d7
	move.w	#$1be,(a4)+                     ; library routine $1be SGET (graphics GET)
	rts

;------------------------------------------------------------------------------
; Statement PUT x,y,a$ (command 260): two integers, the string, routine $1bf SPUT through
; pop_args_from_d2.
;------------------------------------------------------------------------------
stmt_put:
	bsr.w	parse_two_int_args              ; handler (SPUT): routine $1bf
	move.w	#$8017,(a4)+                    ; IR $8017: push y as well
	bsr.w	parse_expression                ; the string
	move.w	#$1bf,-(sp)                     ; routine word for the pop chain
	bra.w	pop_args_from_d2                ; pop into d2-d1, then write SPUT

;------------------------------------------------------------------------------
; Statement PUT x,y,a$,mode (command 261): two integers, string, mode, IR $8022 and routine $1c0 SPUTM
; through pop_args_from_d2.
;------------------------------------------------------------------------------
stmt_put_mode:
	bsr.w	parse_two_int_args              ; handler (SPUT with mode): routine $1c0 SPUTM
	move.w	#$8017,(a4)+                    ; IR $8017: push y as well
	bsr.w	parse_expression                ; the string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_integer_expression        ; the mode, in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop the string into a0
	move.w	#$1c0,-(sp)                     ; routine word for the pop chain
	bra.w	pop_args_from_d2                ; pop into d2-d1, then write SPUTM

;------------------------------------------------------------------------------
; Statement OPENW n (command 266): library routine $209 OPENW; with OPENW n,x,y (more arguments
; after the first) routine $20b OPENWXY.
;------------------------------------------------------------------------------
stmt_openw:
	bsr.w	parse_integer_expression        ; window number
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: plain OPENW n
	beq.s	.openw_plain
	move.w	#$8017,(a4)+                    ; IR $8017: push the window number
	bsr.w	parse_int_and_push              ; x, pushed
	bsr.w	parse_integer_expression        ; y, in d0
	move.w	#$801c,(a4)+                    ; IR $801c: pop x into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the window number into d1
	move.w	#$20b,(a4)+                     ; library routine $20b OPENWXY
	rts
.openw_plain:
	move.w	#$209,(a4)+                     ; library routine $209 OPENW
	rts

;------------------------------------------------------------------------------
; Statement OPENW #n,x,y,w,h,attr (command 267): routine $20a OPENW6, six integer arguments.
;------------------------------------------------------------------------------
stmt_openw_channel:
	move.w	#$20a,d0                        ; library routine $20a OPENW6
	bra.w	emit_code_after_six_ints

;------------------------------------------------------------------------------
; Statement CLOSEW n / CLOSEW #n (commands 269, 270): routine $20f CLOSEW, one integer argument.
;------------------------------------------------------------------------------
stmt_closew:
	move.w	#$20f,d0                        ; library routine $20f CLOSEW
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement CLEARW n / CLEARW #n (commands 272, 273): routine $211 NCLEARW, one integer argument.
;------------------------------------------------------------------------------
stmt_clearw:
	move.w	#$211,d0                        ; library routine $211 NCLEARW
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement TOPW n (command 274): routine $20c TOPW, one integer argument.
;------------------------------------------------------------------------------
stmt_topw:
	move.w	#$20c,d0                        ; library routine $20c TOPW
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement TITLEW n,a$ (command 275): routine $20d TITLEW, integer and string.
;------------------------------------------------------------------------------
stmt_titlew:
	move.w	#$20d,d0                        ; library routine $20d TITLEW
	bra.w	emit_code_after_int_and_value

;------------------------------------------------------------------------------
; Statement INFOW n,a$ (command 276): routine $20e INFOW, integer and string.
;------------------------------------------------------------------------------
stmt_infow:
	move.w	#$20e,d0                        ; library routine $20e INFOW
	bra.w	emit_code_after_int_and_value

;------------------------------------------------------------------------------
; Statement DEFMOUSE n (command 279): routine $219 DEFMOUSE, one integer argument.
;------------------------------------------------------------------------------
stmt_defmouse:
	move.w	#$219,d0                        ; library routine $219 DEFMOUSE
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement DEFMOUSE a$ (command 280): routine $21a DEFSMOUS, one string argument.
;------------------------------------------------------------------------------
stmt_defmouse_string:
	move.w	#$21a,d0                        ; library routine $21a DEFSMOUS
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement HIDEM (command 302): routine $1cb HIDEM.
;------------------------------------------------------------------------------
stmt_hidem:
	move.w	#$1cb,(a4)+                     ; library routine $1cb HIDEM
	rts

;------------------------------------------------------------------------------
; Statements QUIT and SYSTEM (commands 309, 341): with an argument routine $1cc SYSTEMN, one integer;
; without one routine $3b END.
;------------------------------------------------------------------------------
stmt_quit:
	cmpi.b	#$46,(a5)                       ; no argument: compiled as END
	beq.s	.quit_as_end
	move.w	#$1cc,d0                        ; library routine $1cc SYSTEMN
	bra.w	emit_code_after_one_int
.quit_as_end:
	move.w	#$3b,(a4)+                      ; library routine $3b END
	rts

;------------------------------------------------------------------------------
; Statement CHDIR a$ (command 311): routine $1c3 CHDIR, string argument.
;------------------------------------------------------------------------------
stmt_chdir:
	move.w	#$1c3,d0                        ; library routine $1c3 CHDIR
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement CHDRIVE n (command 312): routine $1c8 CHDRIVE, integer argument.
;------------------------------------------------------------------------------
stmt_chdrive:
	move.w	#$1c8,d0                        ; library routine $1c8 CHDRIVE
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement CHDRIVE a$ (command 313): routine $1c9 SCHDRIVE, string argument.
;------------------------------------------------------------------------------
stmt_chdrive_string:
	move.w	#$1c9,d0                        ; library routine $1c9 SCHDRIVE
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement NAME a$ AS b$ / RENAME (commands 330, 352): routine $1c7 RENAME, two strings.
;------------------------------------------------------------------------------
stmt_rename:
	move.w	#$1c7,d0                        ; library routine $1c7 RENAME
	bra.w	emit_code_after_two_strings

;------------------------------------------------------------------------------
; Statement MKDIR a$ (command 331): routine $1c4 MKDIR, string argument.
;------------------------------------------------------------------------------
stmt_mkdir:
	move.w	#$1c4,d0                        ; library routine $1c4 MKDIR
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement KILL a$ (command 333): routine $1c6 KILL, string argument.
;------------------------------------------------------------------------------
stmt_kill:
	move.w	#$1c6,d0                        ; library routine $1c6 KILL
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement RMDIR a$ (command 334): routine $1c5 RMDIR, string argument.
;------------------------------------------------------------------------------
stmt_rmdir:
	move.w	#$1c5,d0                        ; library routine $1c5 RMDIR
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement SGET a$ (command 337): routine $1d4 SAGET, string argument.
;------------------------------------------------------------------------------
stmt_sget:
	move.w	#$1d4,d0                        ; library routine $1d4 SAGET
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement SHOWM (command 338): routine $1ca SHOWM.
;------------------------------------------------------------------------------
stmt_showm:
	move.w	#$1ca,(a4)+                     ; library routine $1ca SHOWM
	rts

;------------------------------------------------------------------------------
; Statement SPUT a$ (command 339): routine $1d3 SAPUT, string argument.
;------------------------------------------------------------------------------
stmt_sput:
	move.w	#$1d3,d0                        ; library routine $1d3 SAPUT
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement VSYNC (command 342): routine $1d0 VSYNC.
;------------------------------------------------------------------------------
stmt_vsync:
	move.w	#$1d0,(a4)+                     ; library routine $1d0 VSYNC
	rts

;------------------------------------------------------------------------------
; Statement HARDCOPY (command 343): routine $1cf HARDCOPY.
;------------------------------------------------------------------------------
stmt_hardcopy:
	move.w	#$1cf,(a4)+                     ; library routine $1cf HARDCOPY
	rts

parse_pause:
	move.w	#$1d1,d0                        ; library routine $1d1 PAUSE; also used after SOUND/WAVE for the
                                                ;   trailing duration
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement CLIP OFF (command 356): routine $216 CLIPOFF.
;------------------------------------------------------------------------------
stmt_clip_off:
	move.w	#$216,(a4)+                     ; library routine $216 CLIPOFF
	rts

;------------------------------------------------------------------------------
; Statement CLIP #n [OFFSET x,y] (command 357): optional # skipped, routine $212 CLIPW, then the optional OFFSET part.
;------------------------------------------------------------------------------
stmt_clip_channel:
	cmpi.b	#$4d,(a5)+                      ; token $4d = "#": skip it
	beq.s	.parse_window_number
	subq.l	#1,a5                           ; no "#": give the token back
.parse_window_number:
	bsr.s	parse_clipw
	bra.s	parse_clip_offset               ; then the optional OFFSET x,y

;------------------------------------------------------------------------------
; CLIP #n: one integer argument, library routine $212 CLIPW (via emit_code_after_one_int).
;------------------------------------------------------------------------------
parse_clipw:
	move.w	#$212,d0                        ; library routine $212 CLIPW
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement CLIP x,y,w,h [OFFSET x,y] (command 358): routine $214 CLIPXYWH, then the optional OFFSET part.
;------------------------------------------------------------------------------
stmt_clip_xywh:
	bsr.s	parse_clip_xywh
	bra.s	parse_clip_offset               ; then the optional OFFSET x,y

;------------------------------------------------------------------------------
; CLIP x,y,w,h: four integer arguments, library routine $214 CLIPXYWH (via emit_code_after_four_ints).
;------------------------------------------------------------------------------
parse_clip_xywh:
	move.w	#$214,d0                        ; library routine $214 CLIPXYWH
	bra.w	emit_code_after_four_ints

;------------------------------------------------------------------------------
; Statement CLIP x1,y1 TO x2,y2 [OFFSET x,y] (command 359): routine $213 CLIPXYXY, then the optional OFFSET part.
;------------------------------------------------------------------------------
stmt_clip_xyxy:
	bsr.s	parse_clip_xyxy
	bra.s	parse_clip_offset               ; then the optional OFFSET x,y

;------------------------------------------------------------------------------
; CLIP x1,y1 TO x2,y2: four integer arguments, library routine $213 CLIPXYXY (via emit_code_after_four_ints).
;------------------------------------------------------------------------------
parse_clip_xyxy:
	move.w	#$213,d0                        ; library routine $213 CLIPXYXY
	bra.w	emit_code_after_four_ints

parse_clip_offset:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no OFFSET part
	bne.s	stmt_clip_offset                ; OFFSET follows
	rts

;------------------------------------------------------------------------------
; Statement CLIP OFFSET x,y (command 360), also the tail of the other CLIP forms: routine $215 CLIPOFFS, two integer
; arguments.
;------------------------------------------------------------------------------
stmt_clip_offset:
	move.w	#$215,d0                        ; library routine $215 CLIPOFFS, two integer arguments
	bra.w	emit_code_after_two_ints

;------------------------------------------------------------------------------
; Statement FULLW n (command 361): routine $217 FULLW, or $218 FULLWN after # ($4d); one integer argument.
;------------------------------------------------------------------------------
stmt_fullw:
	cmpi.b	#$4d,(a5)                       ; token $4d = "#": FULLW #n
	beq.s	.fullw_channel
	move.w	#$217,d0                        ; library routine $217 FULLW
	bra.w	emit_code_after_one_int
.fullw_channel:
	addq.l	#1,a5                           ; skip the "#"
	move.w	#$218,d0                        ; library routine $218 FULLWN
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement DRAW [TO] x,y [TO x,y ...] (command 370). IR $802a, or $802b when it starts with TO (token
; $47: draw from the last point). First pass parses the pairs as longs (parse_int_and_push) and counts
; them: for $802a, one pair is rewritten as PLOT ($2c) and two pairs as LINE ($24). Otherwise the IR is
; thrown away (a4/a5 restored) and the pairs are parsed again as words (parse_int_and_push_word), then
; IR $802a/$802b and the word count (4 per pair) are written.
;------------------------------------------------------------------------------
stmt_draw_points:
	move.w	#$802a,d0                       ; IR $802a: DRAW point list
	cmpi.b	#$47,(a5)                       ; token $47 = TO: continue from the last point
	bne.s	.count_pairs
	addq.l	#1,a5                           ; skip the TO token
	move.w	#$802b,d0                       ; IR $802b: DRAW TO point list
.count_pairs:
	movem.l	a4-a5,-(sp)                     ; saved so the list can be parsed again as words
	move.w	d0,-(sp)                        ; IR code on the stack
	clr.w	-(sp)                           ; pair count on the stack
.next_long_pair:
	bsr.w	parse_int_and_push              ; x, pushed as a long
	bsr.w	parse_int_and_push              ; y, pushed as a long
	addq.w	#1,(sp)                         ; one more pair
	cmpi.b	#$46,-$1(a5)                    ; until token $46 = end of statement
	bne.s	.next_long_pair
	movem.w	(sp)+,d0/d7                     ; d0 = pair count, d7 = IR code
	cmpi.w	#$802a,d7                       ; DRAW TO is never shortened
	bne.s	.reparse_as_words
	cmpi.w	#$1,d0                          ; one pair: PLOT x,y
	beq.s	.one_pair_as_plot
	cmpi.w	#$2,d0                          ; two pairs: LINE x1,y1,x2,y2
	beq.s	.two_pairs_as_line
.reparse_as_words:
	movem.l	(sp)+,a4-a5                     ; back to the start of the list; drop the long IR
	move.w	d7,-(sp)                        ; IR code on the stack again
	clr.w	-(sp)                           ; byte count on the stack
.next_word_pair:
	bsr.w	parse_int_and_push_word         ; x, pushed as a word
	bsr.w	parse_int_and_push_word         ; y, pushed as a word
	addq.w	#4,(sp)                         ; 4 bytes per pair
	cmpi.b	#$46,-$1(a5)                    ; until token $46 = end of statement
	bne.s	.next_word_pair
	movem.w	(sp)+,d0/d7                     ; d0 = byte count, d7 = IR code
	move.w	d7,(a4)+                        ; $802a or $802b
	move.w	d0,(a4)+                        ; bytes of points on the stack
	rts
.one_pair_as_plot:
	move.w	#$801b,-$2(a4)                  ; one pair: last push becomes pop x into d1; PLOT ($2c)
	move.w	#$2c,(a4)+                      ; library PLOT ($2c)
	addq.l	#8,sp                           ; drop the saved a4/a5
	rts
.two_pairs_as_line:
	move.w	#$801d,-$2(a4)                  ; two pairs: last push becomes pop x2 into d3; LINE ($24)
	move.w	#$801c,(a4)+                    ; IR $801c: pop y1 into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop x1 into d1
	move.w	#$24,(a4)+                      ; library LINE ($24)
	addq.l	#8,sp                           ; drop the saved a4/a5
	rts

;------------------------------------------------------------------------------
; Statement BOUNDARY n (command 387): routine $1d2 BOUNDARY, one integer argument.
;------------------------------------------------------------------------------
stmt_boundary:
	move.w	#$1d2,d0                        ; library routine $1d2 BOUNDARY
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement RC_COPY src,x,y,w,h TO dst,x,y[,mode] (command 413): eight integers, routine $1ce RC_COPY8;
; with a ninth (mode) argument routine $225 RC_COPY9 and IR $8021. Then the pops $8020 ... $801b, $8022.
;------------------------------------------------------------------------------
stmt_rc_copy:
	bsr.w	parse_eight_int_args            ; seven pushed, the eighth in d0
	move.w	#$1ce,d0                        ; library routine $1ce RC_COPY8
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no mode argument
	beq.s	.pop_rc_copy_args
	move.w	#$8017,(a4)+                    ; IR $8017: push the eighth as well
	bsr.w	parse_integer_expression        ; the mode, in d0
	move.w	#$225,d0                        ; library routine $225 RC_COPY9
	move.w	#$8021,(a4)+                    ; IR $8021: pop into d7
.pop_rc_copy_args:
	move.w	#$8020,(a4)+                    ; IR $8020: pop into d6
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
	move.w	#$801d,(a4)+                    ; IR $801d: pop into d3
	move.w	#$801c,(a4)+                    ; IR $801c: pop into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	#$8022,(a4)+                    ; IR $8022: pop the first argument into a0
	move.w	d0,(a4)+                        ; RC_COPY8 or RC_COPY9
	rts

;------------------------------------------------------------------------------
; Statement MODE n (command 414): routine $1cd MODE, one integer argument.
;------------------------------------------------------------------------------
stmt_mode:
	move.w	#$1cd,d0                        ; library routine $1cd MODE
	bra.w	emit_code_after_one_int

parse_on_menu_gosub:
	move.w	#$21c,d0                        ; library routine $21c ONM_MEN
	bra.s	emit_procedure_call

parse_on_menu_message_gosub:
	move.w	#$21f,d0                        ; library routine $21f ONM_MSG
	bra.s	emit_procedure_call

parse_on_menu_key_gosub:
	move.w	#$21d,d0                        ; library routine $21d ONM_KEY
	bra.s	emit_procedure_call

parse_on_menu_button_gosub:
	bsr.w	emit_code_after_three_ints      ; three integers; the d0 word written after them is dropped
	subq.l	#2,a4                           ; drop that routine word
	move.w	#$21e,d0                        ; library routine $21e ONM_BUT
	bra.s	emit_procedure_call

parse_on_menu:
	move.w	#$222,(a4)+                     ; library routine $222 POLLMENU (ON MENU with no argument)
	rts

parse_on_menu_timer:
	move.w	#$223,d0                        ; library routine $223 TPOLLMEN (ON MENU t)
	bra.w	emit_code_after_one_int

parse_on_menu_ibox_gosub:
	bsr.w	emit_code_after_five_ints
	move.w	#$220,d0                        ; library routine $220 ONM_IBX
	bra.s	emit_procedure_call_replacing_last

parse_on_menu_obox_gosub:
	bsr.w	emit_code_after_five_ints
	move.w	#$221,d0                        ; library routine $221 ONM_OBX

emit_procedure_call_replacing_last:
	subq.l	#2,a4                           ; drop the routine word the argument parser just wrote

emit_procedure_call:
	moveq	#0,d1                           ; procedure number from the token stream (bit 4 = two-byte number)
	btst	#$4,(a5)+
	beq.s	.read_procedure_number_low
	move.b	(a5)+,d1                        ; high byte of the procedure number
	asl.w	#8,d1
.read_procedure_number_low:
	move.b	(a5)+,d1                        ; low byte of the procedure number
	move.w	#$80ff,(a4)+                    ; IR $80ff = procedure address, followed by the procedure number
	move.w	d1,(a4)+
	move.w	d0,(a4)+                        ; then the library routine in d0
	rts

;------------------------------------------------------------------------------
; Statement DEFNUM n (command 283): routine $21b DEFNUM, one integer argument.
;------------------------------------------------------------------------------
stmt_defnum:
	move.w	#$21b,d0                        ; library routine $21b DEFNUM
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement DEFMARK [colour],[type],[size] (command 282): each present argument writes DEFMA1/2/3
; ($226-$228) through emit_optional_int_argument.
;------------------------------------------------------------------------------
stmt_defmark:
	move.w	#$226,d0                        ; library routine $226 DEFMA1: colour
	bsr.s	emit_optional_int_argument
	move.w	#$227,d0                        ; library routine $227 DEFMA2: type
	bsr.s	emit_optional_int_argument
	move.w	#$228,d0                        ; library routine $228 DEFMA3: size
	bsr.s	emit_optional_int_argument
	rts

;------------------------------------------------------------------------------
; Statement DEFTEXT [colour],[style],[angle],[height],[font] (command 284): optional arguments to DEFTX1-
; DEFTX5 ($229-$22d), then routine $22e DEFTXX.
;------------------------------------------------------------------------------
stmt_deftext:
	move.w	#$229,d0                        ; library routine $229 DEFTX1: colour
	bsr.s	emit_optional_int_argument
	move.w	#$22a,d0                        ; library routine $22a DEFTX2: style
	bsr.s	emit_optional_int_argument
	move.w	#$22b,d0                        ; library routine $22b DEFTX3: angle
	bsr.s	emit_optional_int_argument
	move.w	#$22c,d0                        ; library routine $22c DEFTX4: height
	bsr.s	emit_optional_int_argument
	move.w	#$22d,d0                        ; library routine $22d DEFTX5: font
	bsr.s	emit_optional_int_argument
	move.w	#$22e,(a4)+                     ; library routine $22e DEFTXX
	rts

;------------------------------------------------------------------------------
; Statement DEFFILL [colour],[style],[pattern] (command 285): optional arguments to DEFFI1-DEFFI3
; ($230-$232).
;------------------------------------------------------------------------------
stmt_deffill:
	move.w	#$230,d0                        ; library routine $230 DEFFI1: colour
	bsr.s	emit_optional_int_argument
	move.w	#$231,d0                        ; library routine $231 DEFFI2: style
	bsr.s	emit_optional_int_argument
	move.w	#$232,d0                        ; library routine $232 DEFFI3: pattern
	bsr.s	emit_optional_int_argument
	rts

;------------------------------------------------------------------------------
; Statement DEFFILL [colour],a$ (command 286): optional colour (DEFFI1 $230), then the pattern string
; with routine $22f DEFSFILL.
;------------------------------------------------------------------------------
stmt_deffill_pattern:
	move.w	#$230,d0                        ; library routine $230 DEFFI1: colour
	bsr.s	emit_optional_int_argument
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no pattern string
	beq.s	.deffill_done
	move.w	#$22f,d0                        ; library routine $22f DEFSFILL
	bra.w	emit_code_after_value
.deffill_done:
	rts

;------------------------------------------------------------------------------
; One optional integer argument of DEFLINE/DEFMARK/DEFTEXT/DEFFILL. Entry d0 = library routine.
; Nothing is written when the statement has ended (token $46 at a5 or just before it) or the argument
; is empty (comma, token $21, consumed); otherwise emit_code_after_one_int writes the argument and d0.
;------------------------------------------------------------------------------
emit_optional_int_argument:
	cmpi.b	#$46,(a5)                       ; statement ended: argument omitted
	beq.s	.argument_omitted
	cmpi.b	#$46,-$1(a5)                    ; statement ended on the token before
	beq.s	.argument_omitted
	cmpi.b	#$21,(a5)+                      ; token $21 = comma: empty argument
	beq.s	.argument_omitted
	subq.l	#1,a5                           ; give the token back
	bra.w	emit_code_after_one_int         ; the argument, then the routine in d0
.argument_omitted:
	rts

;------------------------------------------------------------------------------
; Statement DEFLINE [style],[width],[begin,end] (command 277): optional style DEFLI1 ($53) and width DEFLI2 ($54); the
; end-shape pair goes to DEFLI34 ($55), a missing end given as IR $8007 0 (d0) and a missing begin as $8008 0 (constant
; operand).
;------------------------------------------------------------------------------
stmt_defline:
	move.w	#$53,d0                         ; library routine $53 DEFLI1: style
	bsr.s	emit_optional_int_argument
	move.w	#$54,d0                         ; library routine $54 DEFLI2: width
	bsr.s	emit_optional_int_argument
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no end shapes
	beq.s	.defline_done
	cmpi.b	#$21,(a5)+                      ; token $21 = comma: begin shape empty
	beq.s	.begin_missing
	cmpi.b	#$46,-(a5)                      ; token $46 = end of statement: done
	beq.s	.defline_done
	bsr.w	parse_integer_expression        ; begin shape
	move.w	#$8017,(a4)+                    ; IR $8017: push begin shape
	cmpi.b	#$46,-$1(a5)                    ; statement ended: end shape missing
	beq.s	.end_missing
	cmpi.b	#$46,(a5)                       ; next token is the end: end shape missing
	beq.s	.end_missing
	bsr.w	parse_integer_expression        ; end shape, in d0
.pop_begin_into_d1:
	move.w	#$801b,(a4)+                    ; IR $801b: pop begin shape into d1
.write_defli34:
	move.w	#$55,(a4)+                      ; library routine $55 DEFLI34
.defline_done:
	rts
.end_missing:
	move.w	#$8007,(a4)+                    ; IR $8007: constant 0 as the end shape in d0
	clr.l	(a4)+
	bra.s	.pop_begin_into_d1
.begin_missing:
	cmpi.b	#$46,-$1(a5)                    ; statement ended after the comma: done
	beq.s	.defline_done
	cmpi.b	#$46,(a5)                       ; next token is the end: done
	beq.s	.defline_done
	bsr.w	parse_integer_expression        ; end shape, in d0
	move.w	#$8008,(a4)+                    ; IR $8008: constant 0 as the begin shape operand
	clr.l	(a4)+
	bra.s	.write_defli34                  ; then DEFLI34

;------------------------------------------------------------------------------
; Statement READ var,var,... (command 372). Per variable the low 4 bits of the token select a handler in
; read_variable_type_table; loops until token $46. Scalars: READNUM $242 / READINT $243 / READSTR $241
; and a store IR ($8041 float, $8042 int, $8043 word, $8044 byte, $8045 bool after $80ef) + variable
; number. Array elements: indices pushed and counted, then the element store IR ($80cb float, $80c7
; int, $80c8 word, $80c9 byte, $80ca bool), the array number and the index count.
;------------------------------------------------------------------------------
stmt_read:
	moveq	#15,d0                          ; low 4 bits of the variable token = type
	and.b	(a5),d0
	add.w	d0,d0                           ; word offset into the table
	move.w	read_variable_type_table(pc,d0.w),d1 ; d1 = handler offset
	jsr	read_variable_type_table(pc,d1.w) ; handler for this variable type
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement, otherwise the next variable
	bne.s	stmt_read
	rts

; Offsets of the READ handlers per variable type (token & $0f): 0 float, 1 string, 2 int, 3 bool, 4 float
; array, 5 string array, 6 int array, 7 bool array, 8 word, 9 byte, 12 word array, 13 byte array.
read_variable_type_table:
	dc.w	.read_float-read_variable_type_table
	dc.w	.read_string-read_variable_type_table
	dc.w	.read_int-read_variable_type_table
	dc.w	.read_bool-read_variable_type_table
	dc.w	.read_float_element-read_variable_type_table
	dc.w	.read_string-read_variable_type_table
	dc.w	.read_int_element-read_variable_type_table
	dc.w	.read_bool_element-read_variable_type_table
	dc.w	.read_word-read_variable_type_table
	dc.w	.read_byte-read_variable_type_table
	dc.w	$0000
	dc.w	$0000
	dc.w	.read_word_element-read_variable_type_table
	dc.w	.read_byte_element-read_variable_type_table
.read_string:
	bsr.w	parse_expression                ; string: the variable is parsed as a string target
	move.w	#$241,(a4)+                     ; library routine $241 READSTR
	rts
.read_float:
	move.w	#$242,(a4)+                     ; library routine $242 READNUM
	move.w	#$8041,d7                       ; IR $8041: store float variable
	bra.s	.read_store_scalar
.read_bool:
	move.w	#$242,(a4)+                     ; library routine $242 READNUM
	move.w	#$80ef,(a4)+                    ; IR $80ef: make boolean
	move.w	#$8045,d7                       ; IR $8045: store bool variable
	bra.s	.read_store_scalar
.read_word:
	move.w	#$8043,d7                       ; IR $8043: store word variable
	bra.s	.read_int_call
.read_byte:
	move.w	#$8044,d7                       ; IR $8044: store byte variable
	bra.s	.read_int_call
.read_int:
	move.w	#$8042,d7                       ; IR $8042: store int variable
.read_int_call:
	move.w	#$243,(a4)+                     ; library routine $243 READINT
.read_store_scalar:
	btst	#$4,(a5)+                       ; bit 4 of the token: two-byte variable number
	beq.s	.read_scalar_number_low
	move.b	(a5)+,d0                        ; high byte of the variable number
	asl.w	#8,d0
.read_scalar_number_low:
	move.b	(a5)+,d0                        ; low byte of the variable number
	move.w	d7,(a4)+                        ; store IR
	move.w	d0,(a4)+                        ; variable number
	addq.l	#1,a5                           ; skip the separator after the variable
	rts
.read_float_element:
	move.w	#$242,-(sp)                     ; library routine $242 READNUM, written after the indices
	move.w	#$80cb,d1                       ; IR $80cb: store float element
	bra.s	.read_element_indices
.read_int_element:
	move.w	#$80c7,d1                       ; IR $80c7: store int element
	bra.s	.push_readint
.read_bool_element:
	move.w	#$80ef,-(sp)                    ; marker: READNUM, then make boolean
	move.w	#$80ca,d1                       ; IR $80ca: store bool element
	bra.s	.read_element_indices
.read_word_element:
	move.w	#$80c8,d1                       ; IR $80c8: store word element
	bra.s	.push_readint
.read_byte_element:
	move.w	#$80c9,d1                       ; IR $80c9: store byte element
.push_readint:
	move.w	#$243,-(sp)                     ; library routine $243 READINT, written after the indices
.read_element_indices:
	btst	#$4,(a5)+                       ; bit 4 of the token: two-byte array number
	beq.s	.read_array_number_low
	move.b	(a5)+,d0                        ; high byte of the array number
	asl.w	#8,d0
.read_array_number_low:
	move.b	(a5)+,d0                        ; low byte of the array number
	move.w	d0,-(sp)                        ; array number on the stack
	move.w	d1,-(sp)                        ; store IR on the stack
	clr.w	-(sp)                           ; index count = 0
.next_read_index:
	bsr.w	parse_int_and_push              ; each index parsed and pushed
	addq.w	#1,(sp)                         ; count this index
	cmpi.b	#$21,-$1(a5)                    ; token $21 = ",": another index follows
	beq.s	.next_read_index
	movem.w	(sp)+,d0-d3                     ; d0 count, d1 store IR, d2 array, d3 call word
	cmpi.w	#$80ef,d3                       ; $80ef marker: bool element
	bne.s	.write_read_call
	move.w	#$242,(a4)+                     ; library routine $242 READNUM first
.write_read_call:
	move.w	d3,(a4)+                        ; READNUM / READINT, or $80ef make boolean
	move.w	d0,d3                           ; d3 = index count for the IR
	subq.w	#1,d0                           ; one index: pop into d4 only
	beq.s	.pop_one_read_index
	subq.w	#1,d0                           ; two indices: pop into d5 and d4
	bne.s	.write_store_element            ; more than two: they stay on the stack
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
.pop_one_read_index:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
.write_store_element:
	move.w	d1,(a4)+                        ; element store IR
	move.w	d2,(a4)+                        ; array number
	move.w	d3,(a4)+                        ; index count
	addq.l	#1,a5                           ; skip the separator after the variable
	rts

;------------------------------------------------------------------------------
; Statement OPEN mode$,#n,name$[,len] (command 265). The mode expression is parsed and optimised; when it
; is a constant string (IR $80ea-$80ed) its first letter picks OPENI $24c, OPENO $24d, OPENA $24f or
; OPENU $24e (IR rewritten from ir_buffer: channel and name). Otherwise (or "R") the mode is pushed and
; routine $24b OPENX, or $252 OPENXN with a record length, is called at run time.
;------------------------------------------------------------------------------
stmt_open:
	bsr.w	parse_expression                ; mode expression
	bsr.w	optimise_ir                     ; optimise so a constant mode shows up as a string constant
	lea	ir_buffer,a0
	move.w	(a0)+,d0                        ; d0 = first IR word of the optimised mode
	cmpi.w	#$80ea,d0                       ; IR $80ea: one-char string
	beq.s	.one_char_mode
	cmpi.w	#$80eb,d0                       ; IR $80eb: two-char string
	beq.s	.inline_chars_mode
	cmpi.w	#$80ec,d0                       ; IR $80ec: four-char string
	beq.s	.inline_chars_mode
	cmpi.w	#$80ed,d0                       ; IR $80ed: string literal (length, pointer)
	beq.s	.literal_mode
	bra.s	.mode_at_run_time               ; not a constant: mode decided at run time
.one_char_mode:
	move.w	(a0)+,d0                        ; the character word
	bra.s	.check_mode_letter
.inline_chars_mode:
	move.b	(a0)+,d0                        ; first of the inline characters
	bra.s	.check_mode_letter
.literal_mode:
	movea.l	(a0)+,a0                        ; long after $80ed: but the length word comes first, looks wrong
	move.b	(a0),d0                         ; first mode character
.check_mode_letter:
	andi.w	#$df,d0                         ; upper case the first mode letter
	cmpi.b	#$49,d0                         ; 'I': input
	beq.s	.mode_input
	cmpi.b	#$4f,d0                         ; 'O': output
	beq.s	.mode_output
	cmpi.b	#$41,d0                         ; 'A': append
	beq.s	.mode_append
	cmpi.b	#$55,d0                         ; 'U': update
	beq.s	.mode_update
	cmpi.b	#$52,d0                         ; 'R': random access, run-time call
	beq.s	.mode_at_run_time
	bra.s	.mode_at_run_time
.mode_input:
	move.w	#$24c,d0                        ; library routine $24c OPENI
	bra.s	.open_with_fixed_mode
.mode_output:
	move.w	#$24d,d0                        ; library routine $24d OPENO
	bra.s	.open_with_fixed_mode
.mode_append:
	move.w	#$24f,d0                        ; library routine $24f OPENA
	bra.s	.open_with_fixed_mode
.mode_update:
	move.w	#$24e,d0                        ; library routine $24e OPENU
.open_with_fixed_mode:
	addq.l	#1,a5                           ; skip the token after the mode
	lea	ir_buffer,a4                    ; discard the mode IR; parse channel and name again
	bra.w	emit_code_after_int_and_value   ; channel pushed, name, $801b, routine
.mode_at_run_time:
	move.w	#$8018,(a4)+                    ; IR $8018: push the mode string
	addq.l	#1,a5                           ; skip the token after the mode
	bsr.w	parse_int_and_push              ; channel number, pushed
	bsr.w	parse_expression                ; file name
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no record length
	beq.s	.no_record_length
	move.w	#$8018,(a4)+                    ; IR $8018: push the file name
	bsr.w	parse_integer_expression        ; record length, in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop the name into a0
	move.w	#$801b,(a4)+                    ; IR $801b: pop the channel into d1
	move.w	#$8023,(a4)+                    ; IR $8023: pop the mode into a1
	move.w	#$252,(a4)+                     ; library routine $252 OPENXN
	rts
.no_record_length:
	move.w	#$801b,(a4)+                    ; IR $801b: pop the channel into d1
	move.w	#$8023,(a4)+                    ; IR $8023: pop the mode into a1
	move.w	#$24b,(a4)+                     ; library routine $24b OPENX
	rts

parse_inp_query:
	move.w	#$28c,d0                        ; library routine $28c INPQ
	bra.w	emit_code_after_one_int

parse_out_query:
	move.w	#$28d,d0                        ; library routine $28d OUTQ
	bra.w	emit_code_after_one_int

parse_instr:
	move.w	#$2b6,d0                        ; library routine $2b6 INSTR: string, string
	bra.w	emit_instr_call

parse_instr_start_first:
	move.w	#$2b8,d0                        ; library routine $2b8 INSTR1: integer start, string, string
	bra.w	emit_instr_call_start_first

parse_instr_start_last:
	move.w	#$2b7,d0                        ; library routine $2b7 INSTR0: string, string, integer start
	bra.w	emit_instr_call_start_last

parse_rinstr:
	move.w	#$2b9,d0                        ; library routine $2b9 RINSTR: string, string
	bra.w	emit_instr_call

parse_rinstr_start_first:
	move.w	#$2b5,d0                        ; library routine $2b5 RINSTR1: integer start, string, string
	bra.w	emit_instr_call_start_first

parse_rinstr_start_last:
	move.w	#$2ba,d0                        ; library routine $2ba RINSTR0: string, string, integer start
	bra.w	emit_instr_call_start_last

parse_unreserve:
	move.w	#$2c2,(a4)+                     ; library routine $2c2 UNRESERV
	rts

parse_reserve:
	move.w	#$2c1,d0                        ; library routine $2c1 RESERVE
	bra.w	emit_code_after_one_int

parse_bget:
	addq.l	#1,a5                           ; skip the # token; library routine $2c3 BGET, three integer arguments
	move.w	#$2c3,d0
	bra.w	emit_code_after_three_ints

parse_bput:
	addq.l	#1,a5                           ; skip the # token; library routine $2c4 BPUT, three integer arguments
	move.w	#$2c4,d0
	bra.w	emit_code_after_three_ints

unsupported_function_token:
	illegal                                 ; table entry for a token the compiler never expects

;------------------------------------------------------------------------------
; Statement CLOSE [#n] (command 268): with # routine $253 CLOSE, one integer; without, $254 CLOSEALL.
;------------------------------------------------------------------------------
stmt_close:
	cmpi.b	#$4d,(a5)+                      ; token $4d = #
	bne.s	.close_all
	move.w	#$253,d0                        ; library routine $253 CLOSE
	bra.w	emit_code_after_one_int
.close_all:
	move.w	#$254,(a4)+                     ; library routine $254 CLOSEALL
	rts

;------------------------------------------------------------------------------
; Statement CLEAR (command 271): routine $2c5 CLEAR.
;------------------------------------------------------------------------------
stmt_clear:
	move.w	#$2c5,(a4)+                     ; library routine $2c5 CLEAR
	rts

;------------------------------------------------------------------------------
; Statement LSET a$=b$ (command 304): two strings, IR $8018 / $8023, routine $288 LSET.
;------------------------------------------------------------------------------
stmt_lset:
	bsr.w	parse_expression                ; target string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; source string
	move.w	#$8023,(a4)+                    ; IR $8023: pop the target into a1
	move.w	#$288,(a4)+                     ; library routine $288 LSET
	rts

;------------------------------------------------------------------------------
; Statement RSET a$=b$ (command 335): two strings, IR $8018 / $8023, routine $289 RSET.
;------------------------------------------------------------------------------
stmt_rset:
	bsr.w	parse_expression                ; target string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; source string
	move.w	#$8023,(a4)+                    ; IR $8023: pop the target into a1
	move.w	#$289,(a4)+                     ; library routine $289 RSET
	rts

;------------------------------------------------------------------------------
; Statement MID$(a$,start[,len])=b$ (command 305): routine $28b MID3SET with a length, $28a MID2SET
; without.
;------------------------------------------------------------------------------
stmt_mid_str:
	bsr.w	parse_expression                ; target string
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_int_and_push              ; start position, pushed
	cmpi.b	#$21,-$1(a5)                    ; token $21 = ",": a length follows
	bne.s	.mid_without_length
	bsr.w	parse_int_and_push              ; length, pushed
	addq.l	#1,a5                           ; skip the "=" token
	bsr.w	parse_expression                ; source string
	move.w	#$801c,(a4)+                    ; IR $801c: pop the length into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the start into d1
	move.w	#$8023,(a4)+                    ; IR $8023: pop the target into a1
	move.w	#$28b,(a4)+                     ; library routine $28b MID3SET
	rts
.mid_without_length:
	addq.l	#1,a5                           ; skip the "=" token
	bsr.w	parse_expression                ; source string
	move.w	#$801b,(a4)+                    ; IR $801b: pop the start into d1
	move.w	#$8023,(a4)+                    ; IR $8023: pop the target into a1
	move.w	#$28a,(a4)+                     ; library routine $28a MID2SET
	rts

;------------------------------------------------------------------------------
; Statement NEW (command 306): compiled as routine $3b END.
;------------------------------------------------------------------------------
stmt_new:
	move.w	#$3b,(a4)+                      ; library routine $3b END
	rts

;------------------------------------------------------------------------------
; Statement CLS [#n] (command 315): routine $234 CLS, or $2c6 CLSN with a channel.
;------------------------------------------------------------------------------
stmt_cls:
	cmpi.b	#$46,(a5)+                      ; token $46 = end of statement: plain CLS
	beq.s	.cls_screen
	move.w	#$2c6,d0                        ; library routine $2c6 CLSN
	bra.w	emit_code_after_one_int
.cls_screen:
	move.w	#$234,(a4)+                     ; library routine $234 CLS
	rts

;------------------------------------------------------------------------------
; Statement HTAB n (command 320): routine $26a HTAB, one integer argument.
;------------------------------------------------------------------------------
stmt_htab:
	move.w	#$26a,d0                        ; library routine $26a HTAB
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement VTAB n (command 321): routine $26b VTAB, one integer argument.
;------------------------------------------------------------------------------
stmt_vtab:
	move.w	#$26b,d0                        ; library routine $26b VTAB
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement TOUCH [#]n (command 326): routine $270 TOUCH, one integer argument.
;------------------------------------------------------------------------------
stmt_touch:
	move.w	#$270,d0                        ; library routine $270 TOUCH
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement FILESELECT path$,name$,result$ (command 329): three strings, routine $26c FILESEL; after #
; ($4d) four strings (title first) and routine $32d XFILESEL.
;------------------------------------------------------------------------------
stmt_fileselect:
	cmpi.b	#$4d,(a5)                       ; handler (FILESELECT): $26c FILESEL, or after # the four-argument $32d
                                                ;   XFILESEL
	beq.s	.xfileselect
	bsr.w	parse_expression                ; path$
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; name$
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; result variable
	move.w	#$8023,(a4)+                    ; IR $8023: pop name$ into a1
	move.w	#$8020,(a4)+                    ; IR $8020: pop path$ into d6 (how it is used is not worked out)
	move.w	#$26c,(a4)+                     ; library routine $26c FILESEL
	rts
.xfileselect:
	addq.l	#1,a5                           ; skip the "#"
	bsr.w	parse_expression                ; title$
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; path$
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; name$
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; result variable
	move.w	#$8023,(a4)+                    ; IR $8023: pop name$ into a1
	move.w	#$8020,(a4)+                    ; IR $8020: pop path$ into d6
	move.w	#$801f,(a4)+                    ; IR $801f: pop title$ into d5
	move.w	#$32d,(a4)+                     ; library routine $32d XFILESEL
	rts

;------------------------------------------------------------------------------
; Statement SETTIME time$,date$ (command 336): TIMESET $2ca for the time and DATESET $2cb for the date;
; either may be left empty (comma, token $21).
;------------------------------------------------------------------------------
stmt_settime:
	cmpi.b	#$21,(a5)+                      ; token $21 = comma: no time, only a date
	beq.s	stmt_date_str_assign
	cmpi.b	#$46,-(a5)                      ; token $46 = end of statement: nothing to set
	bne.s	stmt_time_str_assign            ; time string follows
	rts

;------------------------------------------------------------------------------
; Statement TIME$=a$ (command 407): routine $2ca TIMESET, then DATESET if a date follows (shared with SETTIME).
;------------------------------------------------------------------------------
stmt_time_str_assign:
	move.w	#$2ca,d0                        ; library routine $2ca TIMESET
	bsr.w	emit_code_after_value           ; the time string, then on to the date

;------------------------------------------------------------------------------
; Statement DATE$=a$ (command 408): routine $2cb DATESET unless the statement has ended.
;------------------------------------------------------------------------------
stmt_date_str_assign:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no date
	bne.s	.set_date
	rts
.set_date:
	move.w	#$2cb,d0                        ; library routine $2cb DATESET
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement SETMOUSE x,y[,k] (command 374): routine $2ad SET3MOUS with three arguments, $2ae SET2MOUS
; with two.
;------------------------------------------------------------------------------
stmt_setmouse:
	bsr.w	parse_int_and_push              ; handler (SETMOUSE): three arguments SET3MOUS $2ad, two SET2MOUS $2ae
	bsr.w	parse_int_and_push              ; y, pushed
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no button state
	beq.s	.two_arguments
	bsr.w	parse_integer_expression        ; button state, in d0
	move.w	#$801c,(a4)+                    ; IR $801c: pop y into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop x into d1
	move.w	#$2ad,(a4)+                     ; library routine $2ad SET3MOUS
	rts
.two_arguments:
	move.w	#$801b,-$2(a4)                  ; y's push becomes pop x into d1; y stays in d0
	move.w	#$2ae,(a4)+                     ; library routine $2ae SET2MOUS
	rts

;------------------------------------------------------------------------------
; Statement KEYPAD n (command 375): routine $2af KEYPAD, one integer argument.
;------------------------------------------------------------------------------
stmt_keypad:
	move.w	#$2af,d0                        ; library routine $2af KEYPAD
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement KEYTEST var (command 376): routine $2b0 KEYTEST, result into the variable.
;------------------------------------------------------------------------------
stmt_keytest:
	move.w	#$2b0,(a4)+                     ; library routine $2b0 KEYTEST

;------------------------------------------------------------------------------
; Shared tail of KEYTEST/KEYGET/KEYLOOK: bra store_one_result.
;------------------------------------------------------------------------------
store_key_result:
	bra.w	store_one_result

;------------------------------------------------------------------------------
; Statement KEYGET var (command 377): routine $2b1 KEYGET, result into the variable.
;------------------------------------------------------------------------------
stmt_keyget:
	move.w	#$2b1,(a4)+                     ; library routine $2b1 KEYGET
	bra.s	store_key_result

;------------------------------------------------------------------------------
; Statement KEYLOOK var (command 378): routine $2b2 KEYLOOK, result into the variable.
;------------------------------------------------------------------------------
stmt_keylook:
	move.w	#$2b2,(a4)+                     ; library routine $2b2 KEYLOOK
	bra.s	store_key_result

;------------------------------------------------------------------------------
; Statement KEYPRESS n (command 379): routine $2b3 KEYPRESS, one integer argument.
;------------------------------------------------------------------------------
stmt_keypress:
	move.w	#$2b3,d0                        ; library routine $2b3 KEYPRESS
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement KEYDEF n,a$ (command 380): routine $2b4 KEYDEF, integer and string.
;------------------------------------------------------------------------------
stmt_keydef:
	move.w	#$2b4,d0                        ; library routine $2b4 KEYDEF
	bra.w	emit_code_after_int_and_value

;------------------------------------------------------------------------------
; Statement BSAVE name$,addr,len (command 404): routine $2c9 BSAVE, string and two integers.
;------------------------------------------------------------------------------
stmt_bsave:
	move.w	#$2c9,d0                        ; library routine $2c9 BSAVE
	bra.w	emit_code_after_string_and_two_ints

;------------------------------------------------------------------------------
; Statement BLOAD name$[,addr] (command 405): routine $2c8 BLOAD with an address, $2cd BLOAD0 without.
;------------------------------------------------------------------------------
stmt_bload:
	bsr.w	parse_expression                ; handler (BLOAD): with address BLOAD $2c8, without BLOAD0 $2cd
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no address
	beq.s	.bload_without_address
	move.w	#$8018,(a4)+                    ; IR $8018: push the file name
	bsr.w	parse_integer_expression        ; address, in d0
	move.w	#$8022,(a4)+                    ; IR $8022: pop the name into a0
	move.w	#$2c8,(a4)+                     ; library routine $2c8 BLOAD
	rts
.bload_without_address:
	move.w	#$2cd,(a4)+                     ; library routine $2cd BLOAD0
	rts

;------------------------------------------------------------------------------
; Statement SPRITE a$[,x,y] (command 409): routine $2e3 SPRITEXY with a position, $2e2 SPRITE without.
;------------------------------------------------------------------------------
stmt_sprite:
	bsr.w	parse_expression                ; handler (SPRITE): with x,y SPRITEXY $2e3, without SPRITE $2e2
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no position
	beq.s	.sprite_without_position
	move.w	#$8018,(a4)+                    ; IR $8018: push the sprite string
	bsr.w	parse_int_and_push              ; x, pushed
	bsr.w	parse_integer_expression        ; y, in d0
	move.w	#$801b,(a4)+                    ; IR $801b: pop x into d1
	move.w	#$8022,(a4)+                    ; IR $8022: pop the string into a0
	move.w	#$2e3,(a4)+                     ; library routine $2e3 SPRITEXY
	rts
.sprite_without_position:
	move.w	#$2e2,(a4)+                     ; library routine $2e2 SPRITE
	rts

;------------------------------------------------------------------------------
; Statement WINDTAB(i,j)=value (command 412): routine 109 SWINDTAB, three integer arguments.
;------------------------------------------------------------------------------
stmt_windtab:
	moveq	#109,d0                         ; library routine 109 SWINDTAB
	bra.w	emit_code_after_three_ints

parse_form_input:
	bsr.w	parse_int_and_push              ; length, pushed
	cmpi.b	#$21,-$1(a5)                    ; token $21 (comma) after the length: FORM INPUT n,a$; otherwise FORM
                                                ;   INPUT n AS a$
	seq	-(sp)                           ; flag on the stack: comma form
	bsr.w	parse_expression                ; the string variable
	move.w	#$801b,(a4)+                    ; IR $801b: pop the length into d1
	tst.b	(sp)+                           ; which form?
	bne.s	.form_input_comma
	move.w	#$276,(a4)+                     ; library routine $276 FORMIAS
	rts
.form_input_comma:
	move.w	#$275,(a4)+                     ; library routine $275 FORMINP
	rts

parse_line_input:
	cmpi.b	#$4d,(a5)                       ; token $4d (#): LINE INPUT #n
	beq.s	.line_input_channel
	cmpi.b	#$e0,(a5)                       ; tokens above $e0 are variables: no prompt string
	bhi.s	.next_unprompted_variable
	bsr.w	parse_expression                ; the prompt string
	move.w	#$271,(a4)+                     ; library routine $271 P0RSTR prints the prompt
.next_prompted_variable:
	bsr.w	parse_expression                ; the variable
	move.w	#$277,(a4)+                     ; library routine $277 LINEINP, once per variable
	cmpi.b	#$46,-$1(a5)                    ; until token $46 = end of statement
	bne.s	.next_prompted_variable
	rts
.next_unprompted_variable:
	bsr.w	parse_expression                ; the variable
	move.w	#$2a2,(a4)+                     ; library routine $2a2 LINEINQ
	cmpi.b	#$46,-$1(a5)                    ; until token $46 = end of statement
	bne.s	.next_unprompted_variable
	rts
.line_input_channel:
	bsr.w	parse_channel_init              ; channel number
.next_channel_variable:
	bsr.w	parse_expression                ; the variable
	move.w	#$2a3,(a4)+                     ; library routine $2a3 LINEINF (from a channel)
	cmpi.b	#$46,-$1(a5)                    ; until token $46 = end of statement
	bne.s	.next_channel_variable
	rts

parse_varptr_bracketed:
	bsr.s	emit_varptr
	addq.l	#1,a5                           ; skip the closing bracket token
	rts

;------------------------------------------------------------------------------
; Emits the address of a variable (appears to be VARPTR / V:). Token: low 4 bits = variable type, bit 4 = two-byte
; variable number. Scalars write IR $8150+type and the number; array elements ($8156-$815b) go through
; emit_array_element to parse the index list.
;------------------------------------------------------------------------------
emit_varptr:
	moveq	#31,d0                          ; mask for type and the two-byte bit
	moveq	#0,d1
	and.b	(a5)+,d0                        ; d0 = variable token bits
	bclr	#$4,d0                          ; bit 4 set: two-byte variable number
	beq.s	.read_varptr_number_low
	move.b	(a5)+,d1                        ; high byte of the variable number
	asl.w	#8,d1
.read_varptr_number_low:
	move.b	(a5)+,d1                        ; low byte of the variable number
	add.w	d0,d0                           ; word offset into the table
	move.w	varptr_type_table(pc,d0.w),d0   ; d0 = handler offset for the type
	jmp	varptr_type_table(pc,d0.w)      ; handler for this variable type
varptr_type_table:
	dc.w	.varptr_float-varptr_type_table ; offsets per variable type 0-13 (0 float, 1 string, 2 int, 3 bool, 4-7
                                                ;   arrays, 8 word, 9 byte, 12-13 word/byte arrays)
	dc.w	.varptr_string-varptr_type_table
	dc.w	.varptr_int-varptr_type_table
	dc.w	.varptr_bool-varptr_type_table
	dc.w	.varptr_float_element-varptr_type_table
	dc.w	.varptr_string_element-varptr_type_table
	dc.w	.varptr_int_element-varptr_type_table
	dc.w	.varptr_bool_element-varptr_type_table
	dc.w	.varptr_word-varptr_type_table
	dc.w	.varptr_byte-varptr_type_table
	dc.w	$0000
	dc.w	$0000
	dc.w	.varptr_word_element-varptr_type_table
	dc.w	.varptr_byte_element-varptr_type_table
.varptr_float:
	move.w	#$8150,(a4)+                    ; IR $8150: address of float variable
.write_varptr_number:
	move.w	d1,(a4)+                        ; variable number
	rts
.varptr_int:
	move.w	#$8152,(a4)+                    ; IR $8152: address of int variable
	bra.s	.write_varptr_number
.varptr_string:
	move.w	#$8151,(a4)+                    ; IR $8151: address of string variable
	bra.s	.write_varptr_number
.varptr_bool:
	move.w	#$8153,(a4)+                    ; IR $8153: address of bool variable
	bra.s	.write_varptr_number
.varptr_word:
	move.w	#$8154,(a4)+                    ; IR $8154: address of word variable
	bra.s	.write_varptr_number
.varptr_byte:
	move.w	#$8155,(a4)+                    ; IR $8155: address of byte variable
	bra.s	.write_varptr_number
.varptr_float_element:
	move.w	#$8156,d0                       ; IR $8156: address of float element
	bra.s	.varptr_element_indices
.varptr_int_element:
	move.w	#$8158,d0                       ; IR $8158: address of int element
	bra.s	.varptr_element_indices
.varptr_word_element:
	move.w	#$815a,d0                       ; IR $815a: address of word element
	bra.s	.varptr_element_indices
.varptr_string_element:
	move.w	#$8157,d0                       ; IR $8157: address of string element
	bra.s	.varptr_element_indices
.varptr_bool_element:
	move.w	#$8159,d0                       ; IR $8159: address of bool element
	bra.s	.varptr_element_indices
.varptr_byte_element:
	move.w	#$815b,d0                       ; IR $815b: address of byte element
.varptr_element_indices:
	exg	d1,d0                           ; d0 = array number, d1 = IR for emit_array_element
	bra.w	emit_array_element              ; indices, IR, array number, count

parse_arrptr_bracketed:
	bsr.s	emit_arrptr
	addq.l	#1,a5                           ; skip the closing bracket token
	rts

;------------------------------------------------------------------------------
; Like emit_varptr but for the descriptor address (appears to be ARRPTR): a string gives IR $815c
; instead of $8151, a whole array ($815d-$8162) skips the "()" token after its number.
;------------------------------------------------------------------------------
emit_arrptr:
	moveq	#31,d0                          ; mask for type and the two-byte bit
	moveq	#0,d1
	and.b	(a5)+,d0                        ; d0 = variable token bits
	bclr	#$4,d0                          ; bit 4 set: two-byte variable number
	beq.s	.read_arrptr_number_low
	move.b	(a5)+,d1                        ; high byte of the variable number
	asl.w	#8,d1
.read_arrptr_number_low:
	move.b	(a5)+,d1                        ; low byte of the variable number
	add.w	d0,d0                           ; word offset into the table
	move.w	arrptr_type_table(pc,d0.w),d0   ; d0 = handler offset for the type
	jmp	arrptr_type_table(pc,d0.w)      ; handler for this variable type
arrptr_type_table:
	dc.w	.arrptr_float-arrptr_type_table ; offsets per variable type 0-13, as varptr_type_table
	dc.w	.arrptr_string-arrptr_type_table
	dc.w	.arrptr_int-arrptr_type_table
	dc.w	.arrptr_bool-arrptr_type_table
	dc.w	.arrptr_float_array-arrptr_type_table
	dc.w	.arrptr_string_array-arrptr_type_table
	dc.w	.arrptr_int_array-arrptr_type_table
	dc.w	.arrptr_bool_array-arrptr_type_table
	dc.w	.arrptr_word-arrptr_type_table
	dc.w	.arrptr_byte-arrptr_type_table
	dc.w	$0000
	dc.w	$0000
	dc.w	.arrptr_word_array-arrptr_type_table
	dc.w	.arrptr_byte_array-arrptr_type_table
.arrptr_float:
	move.w	#$8150,(a4)+                    ; IR $8150: address of float variable
.write_arrptr_number:
	move.w	d1,(a4)+                        ; variable or array number
	rts
.arrptr_int:
	move.w	#$8152,(a4)+                    ; IR $8152: address of int variable
	bra.s	.write_arrptr_number
.arrptr_string:
	move.w	#$815c,(a4)+                    ; IR $815c: string descriptor address
	bra.s	.write_arrptr_number
.arrptr_bool:
	move.w	#$8153,(a4)+                    ; IR $8153: address of bool variable
	bra.s	.write_arrptr_number
.arrptr_word:
	move.w	#$8154,(a4)+                    ; IR $8154: address of word variable
	bra.s	.write_arrptr_number
.arrptr_byte:
	move.w	#$8155,(a4)+                    ; IR $8155: address of byte variable
	bra.s	.write_arrptr_number
.arrptr_float_array:
	move.w	#$815d,(a4)+                    ; IR $815d: float array descriptor
	bra.s	.skip_array_brackets
.arrptr_int_array:
	move.w	#$815f,(a4)+                    ; IR $815f: int array descriptor
	bra.s	.skip_array_brackets
.arrptr_word_array:
	move.w	#$8161,(a4)+                    ; IR $8161: word array descriptor
	bra.s	.skip_array_brackets
.arrptr_string_array:
	move.w	#$815e,(a4)+                    ; IR $815e: string array descriptor
	bra.s	.skip_array_brackets
.arrptr_bool_array:
	move.w	#$8160,(a4)+                    ; IR $8160: bool array descriptor
	bra.s	.skip_array_brackets
.arrptr_byte_array:
	move.w	#$8162,(a4)+                    ; IR $8162: byte array descriptor
.skip_array_brackets:
	addq.l	#1,a5                           ; skip the "()" token after the array number
	bra.s	.write_arrptr_number

parse_float_even:
	move.w	#$814a,d0                       ; IR $814a after the expression: float EVEN (becomes $8079 after an
                                                ;   int-to-float, NOT turns it into $814b)
	bra.w	emit_code_after_value

parse_float_odd:
	move.w	#$814b,d0                       ; IR $814b: float ODD
	bra.w	emit_code_after_value

parse_float_function_802c:
	move.w	#$802c,d0                       ; IR $802c after the expression (becomes integer $8082 after an
                                                ;   int-to-float); keyword not worked out
	bra.w	emit_code_after_value

parse_swap:
	moveq	#11,d0                          ; SWAP a,b: IR code from the type of the first variable
	and.b	(a5),d0                         ; type with bit 2 cleared: arrays share the scalar entry
	add.w	d0,d0                           ; word offset into swap_ir_by_type
	move.w	swap_ir_by_type(pc,d0.w),d0
	move.w	d0,-(sp)                        ; SWAP IR kept on the stack
	moveq	#0,d7                           ; d7 counts array operands
	bsr.w	emit_swap_operand               ; first operand
	add.w	d7,d7                           ; first operand an array: d7 = 2
	pea	(a4)                            ; where the push goes, for a later rewrite
	move.w	#$8018,(a4)+                    ; IR $8018: push the first operand
	addq.l	#1,a5                           ; skip the "," token
	bsr.w	emit_swap_operand               ; second operand; an array adds 1 to d7
	move.w	#$8023,(a4)+                    ; IR $8023: pop it into an argument register
	movea.l	(sp)+,a2                        ; a2 = the $8018 word
	move.w	(sp)+,d0                        ; d0 = SWAP IR
	cmpi.w	#$81aa,d0                       ; $81aa = boolean SWAP: an array operand needs a library routine
	bne.s	.write_swap_code
	tst.b	d7                              ; no array operand: plain SWAP IR
	beq.s	.write_swap_code
	move.w	#$34c,d0                        ; library routine $34c + d7: SWPBVA/SWPBAV/SWPBAA
	add.w	d7,d0                           ; 1 SWPBVA, 2 SWPBAV, 3 SWPBAA
	lsr.w	#1,d7                           ; first operand an array?
	beq.s	.write_swap_code
	move.w	#$81fd,(a2)                     ; first operand an array: rewrite the push/pop as $81fd/$81fe
	move.w	#$81fe,-$2(a4)                  ; IR $81fe in place of the pop
.write_swap_code:
	move.w	d0,(a4)+                        ; SWAP IR or the library routine
	rts
swap_ir_by_type:
	dc.w	$81a7,$81a8,$81a9,$81aa,$0000,$0000,$0000,$0000 ; IR word per variable type: float $81a7, string $81a8,
                                                ;   int $81a9, bool $81aa, word $81ab, byte $81ac
	dc.w	$81ab,$81ac

parse_swap_arrays:
	moveq	#31,d0                          ; SWAP a(),b(): two whole-array references then IR $81ad
	and.b	(a5)+,d0                        ; d0 = variable token bits
	moveq	#0,d1
	bclr	#$4,d0                          ; bit 4 set: two-byte array number
	beq.s	.read_first_array_low
	move.b	(a5)+,d1                        ; high byte of the array number
	asl.w	#8,d1
.read_first_array_low:
	move.b	(a5)+,d1                        ; low byte of the array number
	add.w	d0,d0                           ; word offset into the table
	move.w	array_ir_by_type(pc,d0.w),(a4)+ ; first array: $818f+ by type
	move.w	d1,(a4)+                        ; first array number
	addq.l	#2,a5                           ; skip the "()" and "," tokens
	moveq	#31,d0                          ; mask for type and the two-byte bit
	and.b	(a5)+,d0                        ; d0 = variable token bits
	moveq	#0,d1
	bclr	#$4,d0                          ; bit 4 set: two-byte array number
	beq.s	.read_second_array_low
	move.b	(a5)+,d1                        ; high byte of the array number
	asl.w	#8,d1
.read_second_array_low:
	move.b	(a5)+,d1                        ; low byte of the array number
	add.w	d0,d0                           ; word offset into the table
	move.w	second_array_ir_base(pc,d0.w),(a4)+ ; second array: same table read 8 bytes earlier, so array types 4-7
                                                ;   give $8195-$8198

second_array_ir_base:
	move.w	d1,(a4)+                        ; second array number
	move.w	#$81ad,(a4)+                    ; IR $81ad: swap the two arrays
	rts
array_ir_by_type:
	dc.w	$8195,$8196,$8197,$8198,$818f,$8190,$8191,$8192
	dc.w	$8199,$819a,$0000,$0000,$8193,$8194

;------------------------------------------------------------------------------
; Reads one SWAP operand variable token. Scalars write IR $819b+type and the number; array elements write $81a1-$81a6
; through emit_array_element (index list) and add 1 to d7, the array-operand count.
;------------------------------------------------------------------------------
emit_swap_operand:
	moveq	#31,d0                          ; mask for type and the two-byte bit
	moveq	#0,d1
	and.b	(a5)+,d0                        ; d0 = variable token bits
	bclr	#$4,d0                          ; bit 4 set: two-byte variable number
	beq.s	.read_swap_number_low
	move.b	(a5)+,d1                        ; high byte of the variable number
	asl.w	#8,d1
.read_swap_number_low:
	move.b	(a5)+,d1                        ; low byte of the variable number
	add.w	d0,d0                           ; word offset into the table
	move.w	swap_operand_type_table(pc,d0.w),d0 ; d0 = handler offset for the type
	jmp	swap_operand_type_table(pc,d0.w) ; handler for this variable type
swap_operand_type_table:
	dc.w	.swap_float-swap_operand_type_table
	dc.w	.swap_string-swap_operand_type_table
	dc.w	.swap_int-swap_operand_type_table
	dc.w	.swap_bool-swap_operand_type_table
	dc.w	.swap_float_element-swap_operand_type_table
	dc.w	.swap_string_element-swap_operand_type_table
	dc.w	.swap_int_element-swap_operand_type_table
	dc.w	.swap_bool_element-swap_operand_type_table
	dc.w	.swap_word-swap_operand_type_table
	dc.w	.swap_byte-swap_operand_type_table
	dc.w	$0000
	dc.w	$0000
	dc.w	.swap_word_element-swap_operand_type_table
	dc.w	.swap_byte_element-swap_operand_type_table
.swap_float:
	move.w	#$819b,(a4)+                    ; IR $819b: float variable operand
.write_swap_number:
	move.w	d1,(a4)+                        ; variable number
	rts
.swap_int:
	move.w	#$819d,(a4)+                    ; IR $819d: int variable operand
	bra.s	.write_swap_number
.swap_string:
	move.w	#$819c,(a4)+                    ; IR $819c: string variable operand
	bra.s	.write_swap_number
.swap_bool:
	move.w	#$819e,(a4)+                    ; IR $819e: bool variable operand
	bra.s	.write_swap_number
.swap_word:
	move.w	#$819f,(a4)+                    ; IR $819f: word variable operand
	bra.s	.write_swap_number
.swap_byte:
	move.w	#$81a0,(a4)+                    ; IR $81a0: byte variable operand
	bra.s	.write_swap_number
.swap_float_element:
	move.w	#$81a1,d0                       ; IR $81a1: float element operand
	bra.s	.swap_element_indices
.swap_int_element:
	move.w	#$81a3,d0                       ; IR $81a3: int element operand
	bra.s	.swap_element_indices
.swap_word_element:
	move.w	#$81a5,d0                       ; IR $81a5: word element operand
	bra.s	.swap_element_indices
.swap_string_element:
	move.w	#$81a2,d0                       ; IR $81a2: string element operand
	bra.s	.swap_element_indices
.swap_bool_element:
	move.w	#$81a4,d0                       ; IR $81a4: bool element operand
	bra.s	.swap_element_indices
.swap_byte_element:
	move.w	#$81a6,d0                       ; IR $81a6: byte element operand
.swap_element_indices:
	exg	d1,d0                           ; d0 = array number, d1 = IR for emit_array_element
	addq.w	#1,d7                           ; one more array operand
	move.w	d7,-(sp)                        ; d7 saved across the index parse
	bsr.w	emit_array_element              ; indices, IR, array number, count
	move.w	(sp)+,d7
	rts

parse_type:
	st	flag_121d3                      ; sets flag_121d3; library routine $2cc TYPE
	move.w	#$2cc,d0
	bra.w	emit_code_after_one_int

parse_swapia:
	addq.l	#1,a5                           ; skip one token before the integer (which one is not worked out)
	bsr.w	parse_integer_expression
	bsr.w	parse_dim_query                 ; DIM? of the array: reference + DIMQ, d1 = 2 * array type
	lsr.w	#1,d1                           ; d1 = array type
	move.w	#$8008,-$2(a4)                  ; replace the DIMQ routine word with IR $8008 (constant into argument
                                                ;   register 1) holding d1
	move.l	d1,(a4)+                        ; the array type as the constant
	st	flag_121d3                      ; also sets flag_121d3
	move.w	#$316,(a4)+                     ; library routine $316 SWAPIA
	rts

parse_starln:
	bsr.s	parse_starl_arguments
	move.w	#$314,(a4)+                     ; library routine $314 STARLN
	rts

parse_starls:
	bsr.s	parse_starl_arguments
	move.w	#$315,(a4)+                     ; library routine $315 STARLS
	rts

;------------------------------------------------------------------------------
; Integer expression pushed ($8017), then an expression and IR $801d; sets var_121d3.
;------------------------------------------------------------------------------
parse_starl_arguments:
	bsr.w	parse_int_and_push              ; first argument, pushed
	bsr.w	parse_expression                ; second argument
	move.w	#$801d,(a4)+                    ; IR $801d: pop the first into d3
	st	flag_121d3                      ; mark flag_121d3
	rts

;------------------------------------------------------------------------------
; Statement FIELD #n,len AS a$,... (command 324): routine $2a4 FIELDSET with the channel, then per field
; the length pushed and either a string variable (FIELDS $2a6) or, after AS (token $7a), an integer
; (FIELDN $2a5); until token $46.
;------------------------------------------------------------------------------
stmt_field:
	addq.l	#1,a5                           ; handler (FIELD #n,len AS a$...): FIELDSET $2a4, FIELDN $2a5 / FIELDS
                                                ;   $2a6; token $7a = AS
	move.w	#$2a4,d0                        ; library routine $2a4 FIELDSET
	bsr.w	emit_code_after_one_int         ; the channel number, then FIELDSET
.next_field:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement: no more fields
	beq.s	.fields_done
	bsr.w	parse_int_and_push              ; field length, pushed
	cmpi.b	#$7a,-$1(a5)                    ; token $7a = AS: integer field
	beq.s	.field_as_integer
	bsr.w	parse_expression                ; the string variable
	move.w	#$801b,(a4)+                    ; IR $801b: pop the length into d1
	move.w	#$2a6,(a4)+                     ; library routine $2a6 FIELDS
	bra.s	.next_field
.field_as_integer:
	bsr.w	parse_integer_expression        ; the integer
	addq.l	#1,a5                           ; skip the separator
	move.w	#$801b,(a4)+                    ; IR $801b: pop the length into d1
	move.w	#$2a5,(a4)+                     ; library routine $2a5 FIELDN
	bra.s	.next_field
.fields_done:
	rts

;------------------------------------------------------------------------------
; Statement GET #n (command 258): routine $2a9 FGET, one integer argument.
;------------------------------------------------------------------------------
stmt_get_record:
	addq.l	#1,a5                           ; handlers (GET/PUT #n): FGET $2a9, FGETX $2aa, FPUT $2ab, FPUTX $2ac
	move.w	#$2a9,d0                        ; library routine $2a9 FGET
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement GET #n,r (command 259): routine $2aa FGETX, two integer arguments.
;------------------------------------------------------------------------------
stmt_get_record_number:
	addq.l	#1,a5                           ; skip the # token
	move.w	#$2aa,d0                        ; library routine $2aa FGETX
	bra.w	emit_code_after_two_ints

;------------------------------------------------------------------------------
; Statement PUT #n (command 262): routine $2ab FPUT, one integer argument.
;------------------------------------------------------------------------------
stmt_put_record:
	addq.l	#1,a5                           ; skip the # token
	move.w	#$2ab,d0                        ; library routine $2ab FPUT
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement PUT #n,r (command 263): routine $2ac FPUTX, two integer arguments.
;------------------------------------------------------------------------------
stmt_put_record_number:
	addq.l	#1,a5                           ; skip the # token
	move.w	#$2ac,d0                        ; library routine $2ac FPUTX
	bra.w	emit_code_after_two_ints

parse_recordx:
	addq.l	#1,a5                           ; skip #; library routine $2a8 RECORDX
	move.w	#$2a8,d0
	bra.w	emit_code_after_two_ints

parse_exec:
	bsr.w	parse_int_and_push              ; mode, pushed
	bsr.w	parse_expression                ; file name
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; command line
	move.w	#$8018,(a4)+                    ; IR $8018: push string (a0)
	bsr.w	parse_expression                ; environment
	move.w	#$8023,(a4)+                    ; IR $8023: pop the command line into a1
	move.w	#$801c,(a4)+                    ; IR $801c: pop the name into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the mode into d1
	move.w	#$2bb,(a4)+                     ; library routine $2bb EXEC
	rts

;------------------------------------------------------------------------------
; Requires the # token ($4d), then parses the channel number and writes library routine $25e PXInit.
; Any other token reaches an illegal instruction.
;------------------------------------------------------------------------------
parse_channel_init:
	cmpi.b	#$4d,(a5)+                      ; token $4d = #
	beq.s	.channel_number
	illegal                                 ; no # here: the compiler stops on an illegal instruction
.channel_number:
	move.w	#$25e,d0                        ; library routine $25e PXInit
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement INPUT (commands 368, 369). INPUT #n: channel and routine $2bf IXInit. Otherwise an
; optional prompt string (P0RSTR $271) followed by INPUT0 $278 when a comma follows, else INPUTQ $2c0.
; Then per variable a handler from input_variable_type_table, like READ: INPUTN $2bc / INPUTI $2be /
; INPUTS $2bd and the same store IR ($8041-$8045 scalars, $80c7-$80cb elements); until token $46.
; What separates command 368 from 369 was not worked out (both use this handler).
;------------------------------------------------------------------------------
stmt_input:
	cmpi.b	#$4d,(a5)                       ; token $4d = #: INPUT #n
	bne.s	.screen_input
	addq.l	#1,a5                           ; skip the #
	bsr.w	parse_integer_expression        ; the channel number
	move.w	#$2bf,(a4)+                     ; library routine $2bf IXInit
	bra.s	.next_variable                  ; straight to the variables
.screen_input:
	cmpi.b	#$e0,(a5)                       ; tokens >= $e0 are variables: no prompt string
	bcc.s	.question_prompt
	bsr.w	parse_expression                ; the prompt string
	move.w	#$271,(a4)+                     ; library routine $271 P0RSTR
	cmpi.b	#$21,-$1(a5)                    ; comma after the prompt: no "?"
	beq.s	.no_question_mark
.question_prompt:
	move.w	#$2c0,(a4)+                     ; library routine $2c0 INPUTQ
	bra.s	.next_variable
.no_question_mark:
	move.w	#$278,(a4)+                     ; library routine $278 INPUT0
.next_variable:
	moveq	#15,d0                          ; low 4 bits of the variable token = type
	and.b	(a5),d0
	add.w	d0,d0                           ; word offset into the table
	move.w	input_variable_type_table(pc,d0.w),d1 ; d1 = handler offset
	jsr	input_variable_type_table(pc,d1.w) ; handler for this variable type
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement, otherwise the next variable
	bne.s	.next_variable
	rts

; Offsets of the INPUT handlers per variable type (token & $0f), same layout as read_variable_type_table.
input_variable_type_table:
	dc.w	.input_float-input_variable_type_table
	dc.w	.input_string-input_variable_type_table
	dc.w	.input_int-input_variable_type_table
	dc.w	.input_bool-input_variable_type_table
	dc.w	.input_float_element-input_variable_type_table
	dc.w	.input_string-input_variable_type_table
	dc.w	.input_int_element-input_variable_type_table
	dc.w	.input_bool_element-input_variable_type_table
	dc.w	.input_word-input_variable_type_table
	dc.w	.input_byte-input_variable_type_table
	dc.w	$0000
	dc.w	$0000
	dc.w	.input_word_element-input_variable_type_table
	dc.w	.input_byte_element-input_variable_type_table
.input_string:
	bsr.w	parse_expression                ; string: the variable is parsed as a string target
	move.w	#$2bd,(a4)+                     ; library routine $2bd INPUTS
	rts
.input_float:
	move.w	#$2bc,(a4)+                     ; library routine $2bc INPUTN
	move.w	#$8041,d7                       ; IR $8041: store float variable
	bra.s	.input_store_scalar
.input_bool:
	move.w	#$2bc,(a4)+                     ; library routine $2bc INPUTN
	move.w	#$80ef,(a4)+                    ; IR $80ef: make boolean
	move.w	#$8045,d7                       ; IR $8045: store bool variable
	bra.s	.input_store_scalar
.input_word:
	move.w	#$8043,d7                       ; IR $8043: store word variable
	bra.s	.input_int_call
.input_byte:
	move.w	#$8044,d7                       ; IR $8044: store byte variable
	bra.s	.input_int_call
.input_int:
	move.w	#$8042,d7                       ; IR $8042: store int variable
.input_int_call:
	move.w	#$2be,(a4)+                     ; library routine $2be INPUTI
.input_store_scalar:
	btst	#$4,(a5)+                       ; bit 4 of the token: two-byte variable number
	beq.s	.input_scalar_number_low
	move.b	(a5)+,d0                        ; high byte of the variable number
	asl.w	#8,d0
.input_scalar_number_low:
	move.b	(a5)+,d0                        ; low byte of the variable number
	move.w	d7,(a4)+                        ; store IR
	move.w	d0,(a4)+                        ; variable number
	addq.l	#1,a5                           ; skip the separator after the variable
	rts
.input_float_element:
	move.w	#$2bc,-(sp)                     ; library routine $2bc INPUTN, written after the indices
	move.w	#$80cb,d1                       ; IR $80cb: store float element
	bra.s	.input_element_indices
.input_int_element:
	move.w	#$80c7,d1                       ; IR $80c7: store int element
	bra.s	.push_inputi
.input_bool_element:
	move.w	#$80ef,-(sp)                    ; marker: INPUTN, then make boolean
	move.w	#$80ca,d1                       ; IR $80ca: store bool element
	bra.s	.input_element_indices
.input_word_element:
	move.w	#$80c8,d1                       ; IR $80c8: store word element
	bra.s	.push_inputi
.input_byte_element:
	move.w	#$80c9,d1                       ; IR $80c9: store byte element
.push_inputi:
	move.w	#$2be,-(sp)                     ; library routine $2be INPUTI, written after the indices
.input_element_indices:
	btst	#$4,(a5)+                       ; bit 4 of the token: two-byte array number
	beq.s	.input_array_number_low
	move.b	(a5)+,d0                        ; high byte of the array number
	asl.w	#8,d0
.input_array_number_low:
	move.b	(a5)+,d0                        ; low byte of the array number
	move.w	d0,-(sp)                        ; array number on the stack
	move.w	d1,-(sp)                        ; store IR on the stack
	clr.w	-(sp)                           ; index count = 0
.next_input_index:
	bsr.w	parse_int_and_push              ; each index parsed and pushed
	addq.w	#1,(sp)                         ; count this index
	cmpi.b	#$21,-$1(a5)                    ; token $21 = ",": another index follows
	beq.s	.next_input_index
	movem.w	(sp)+,d0-d3                     ; d0 count, d1 store IR, d2 array, d3 call word
	cmpi.w	#$80ef,d3                       ; $80ef marker: bool element
	bne.s	.write_input_call
	move.w	#$2bc,(a4)+                     ; library routine $2bc INPUTN first
.write_input_call:
	move.w	d3,(a4)+                        ; INPUTN / INPUTI, or $80ef make boolean
	move.w	d0,d3                           ; d3 = index count for the IR
	subq.w	#1,d0                           ; one index: pop into d4 only
	beq.s	.pop_one_input_index
	subq.w	#1,d0                           ; two indices: pop into d5 and d4
	bne.s	.write_input_element            ; more than two: they stay on the stack
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5
.pop_one_input_index:
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
.write_input_element:
	move.w	d1,(a4)+                        ; element store IR
	move.w	d2,(a4)+                        ; array number
	move.w	d3,(a4)+                        ; index count
	addq.l	#1,a5                           ; skip the separator
	rts

;------------------------------------------------------------------------------
; Statement OUT [#]n,byte,... (commands 307, 308): routine $2d1 OUTF after # or $2ce OUTB, two integer
; arguments; each further value writes routine $a9 PRCHR.
;------------------------------------------------------------------------------
stmt_out:
	move.w	#$2d1,d0                        ; library routine $2d1 OUTF (OUT #n)
	cmpi.b	#$4d,(a5)+                      ; token $4d = #
	beq.s	.out_channel_and_value
	subq.w	#3,d0                           ; $2ce OUTB without #
	subq.l	#1,a5                           ; no #: give the token back
.out_channel_and_value:
	bsr.w	emit_code_after_two_ints        ; channel/device and first value, then the routine
	bra.s	.check_out_end
.next_out_byte:
	bsr.w	parse_integer_expression        ; next value
	move.w	#$a9,(a4)+                      ; library routine $a9 PRCHR
.check_out_end:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement, otherwise another value
	bne.s	.next_out_byte
	rts

;------------------------------------------------------------------------------
; Statement OUT& [#]n,word,... (command 420): routine $2d2 OUTWF or $2cf OUTWB; each further value
; routine $aa PRMKI.
;------------------------------------------------------------------------------
stmt_out_word:
	move.w	#$2d2,d0                        ; library routine $2d2 OUTWF (OUT& #n)
	cmpi.b	#$4d,(a5)+                      ; token $4d = #
	beq.s	.out_word_channel_and_value
	subq.l	#1,a5                           ; no #: give the token back
	subq.w	#3,d0                           ; $2cf OUTWB without #
.out_word_channel_and_value:
	bsr.w	emit_code_after_two_ints        ; channel/device and first value, then the routine
	bra.s	.check_out_word_end
.next_out_word:
	bsr.w	parse_integer_expression        ; next value
	move.w	#$aa,(a4)+                      ; library routine $aa PRMKI
.check_out_word_end:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement, otherwise another value
	bne.s	.next_out_word
	rts

;------------------------------------------------------------------------------
; Statement OUT% [#]n,long,... (command 421): routine $2d3 OUTLF or $2d0 OUTLB; each further value
; routine $ab PRMKL.
;------------------------------------------------------------------------------
stmt_out_long:
	move.w	#$2d3,d0                        ; library routine $2d3 OUTLF (OUT% #n)
	cmpi.b	#$4d,(a5)+                      ; token $4d = #
	beq.s	.out_long_channel_and_value
	subq.l	#1,a5                           ; no #: give the token back
	subq.w	#3,d0                           ; $2d0 OUTLB without #
.out_long_channel_and_value:
	bsr.w	emit_code_after_two_ints        ; channel/device and first value, then the routine
	bra.s	.check_out_long_end
.next_out_long:
	bsr.w	parse_integer_expression        ; next value
	move.w	#$ab,(a4)+                      ; library routine $ab PRMKL
.check_out_long_end:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement, otherwise another value
	bne.s	.next_out_long
	rts

;------------------------------------------------------------------------------
; Scans the ASCII text of a $ option line through a5 until CR ($0d) or "!" and acts on each option:
;  %n  option_percent_value = n          M n  option_m_memory_size = n, at least 1000
;  *& *%  option_star_flag set/clear     S% S& S|  select_compare_size = 0/1/-1
;  S< S>  select_chain_case_exits set/clear
;  U+ U-  break_check_flag (U is ignored while parsing_command_line_flag is set); U alone puts jsr (a6) into
;         statement_code_buffer and returns through copy_statement_code
;  I+ I-  write IRQON $33f / IRQOFF $340   B+  writes BOMBON $357
;  F< F>  option_f_flag set/clear          P< P>  option_p_flag clear/set
;  E$ E#  error_names_flag set/clear       C+ C-  option_c_flag   N+ N-  option_n_flag
;  RC% RC&  option_rc_word_flag clear/set
; Anything else is skipped up to a comma or a control character. Letters are case-folded.
;------------------------------------------------------------------------------
parse_compiler_options:
	move.b	(a5)+,d0
	cmpi.b	#$d,d0                          ; CR ends the line
	beq.w	options_end
	cmpi.b	#$21,d0                         ; "!" starts a comment
	beq.w	options_end
	cmpi.b	#$25,d0                         ; "%"
	beq.w	option_percent
	cmpi.b	#$2a,d0                         ; "*"
	beq.w	option_star
	cmpi.b	#$41,d0                         ; skip punctuation below "A"
	bcs.s	parse_compiler_options
	andi.w	#$df,d0                         ; fold to upper case
	cmpi.b	#$4d,d0                         ; "M": memory size
	beq.s	option_memory
	cmpi.b	#$53,d0                         ; "S": SELECT options
	beq.w	option_s
	cmpi.b	#$55,d0                         ; "U": break checks
	beq.w	option_u
	cmpi.b	#$4e,d0                         ; "N"
	beq.w	option_n
	cmpi.b	#$49,d0                         ; "I": interrupts on/off
	beq.w	option_i
	cmpi.b	#$46,d0                         ; "F"
	beq.w	option_f
	cmpi.b	#$50,d0                         ; "P"
	beq.w	option_p
	cmpi.b	#$42,d0                         ; "B": bombs on
	beq.w	option_b
	cmpi.b	#$45,d0                         ; "E": error texts
	beq.w	option_e
	cmpi.b	#$43,d0                         ; "C"
	beq.w	option_c
	cmpi.b	#$52,d0                         ; "R": only RC is an option
	bne.s	.skip_unknown_option
	cmpi.b	#$43,(a5)                       ; "C" after the R
	beq.s	option_rc
	cmpi.b	#$63,(a5)                       ; "c" after the R
	beq.s	option_rc
.skip_unknown_option:
	move.b	(a5)+,d0                        ; skip the rest of an unknown option
	cmpi.b	#$2c,d0                         ; "," ends it
	beq.s	options_loop
	cmpi.b	#$20,d0                         ; so does a space or control character
	bhi.s	.skip_unknown_option

options_back_one:
	subq.l	#1,a5                           ; give back the character that ended the option

options_loop:
	bra.w	parse_compiler_options

options_end:
	rts

option_memory:
	bsr.s	parse_option_number             ; n
	beq.s	options_loop                    ; zero: nothing to set
	move.l	#$3e8,d1                        ; memory size at least 1000
	cmp.l	d1,d0
	bhi.s	.store_memory_size              ; more than 1000: keep n
	move.l	d1,d0
.store_memory_size:
	move.l	d0,option_m_memory_size
	bra.s	options_back_one

option_percent:
	bsr.s	parse_option_number             ; n
	move.b	d0,option_percent_value
	bra.s	options_back_one

option_rc:
	addq.l	#1,a5                           ; skip the "C" (and spaces after it)
	move.b	(a5),d0                         ; next character
	cmpi.b	#$20,d0                         ; space: keep skipping
	beq.s	option_rc
	cmpi.b	#$25,d0                         ; "%": RC% = long rectangles
	beq.s	.rc_long
	cmpi.b	#$26,d0                         ; "&": RC& = word rectangles
	beq.s	.rc_word
	bra.s	options_back_one
.rc_word:
	st	option_rc_word_flag             ; RC&: RCW_INTE for RC_INTERSECT
	bra.s	options_back_one
.rc_long:
	sf	option_rc_word_flag             ; RC%: RC_INTER for RC_INTERSECT
	bra.s	options_back_one

;------------------------------------------------------------------------------
; Reads a signed decimal ASCII number through a5 (spaces and "+" skipped, each "-" toggles the sign).
; Exit: d0 = value, flags from tst.l d0; a5 one past the first non-digit.
;------------------------------------------------------------------------------
parse_option_number:
	moveq	#0,d0                           ; d0 = value
	moveq	#0,d1                           ; d1 = digit, upper bytes kept 0
	moveq	#-1,d3                          ; sign flag, made 0 by the not below
.toggle_sign:
	not.l	d3                              ; d3 = sign flag
.skip_sign_and_spaces:
	move.b	(a5)+,d1                        ; next character
	cmpi.b	#$20,d1                         ; space: skipped
	beq.s	.skip_sign_and_spaces
	cmpi.b	#$2b,d1                         ; "+": skipped
	beq.s	.skip_sign_and_spaces
	cmpi.b	#$2d,d1                         ; "-": toggle the sign
	beq.s	.toggle_sign
	bra.s	.add_digit                      ; the first digit is in d1 already
.next_digit:
	move.b	(a5)+,d1                        ; next character
.add_digit:
	subi.b	#$30,d1                         ; digit value
	cmpi.b	#$a,d1                          ; not 0-9 (unsigned compare): number ended
	bhi.s	.number_ended
	move.l	d0,d2                           ; d0 = d0*10 + digit
	asl.l	#2,d0                           ; d0*4
	add.l	d2,d0                           ; d0*5
	add.l	d0,d0                           ; d0*10
	add.l	d1,d0                           ; plus the digit
	bra.s	.next_digit
.number_ended:
	tst.l	d3                              ; negative?
	beq.s	.set_flags
	neg.l	d0                              ; negate the value
.set_flags:
	tst.l	d0
	rts

option_s:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_s
	cmpi.b	#$25,d0                         ; "%"
	beq.s	option_s_percent
	cmpi.b	#$26,d0                         ; "&"
	beq.s	option_s_ampersand
	cmpi.b	#$7c,d0                         ; "|"
	beq.s	option_s_bar
	cmpi.b	#$3c,d0                         ; "<"
	beq.s	option_s_less
	cmpi.b	#$3e,d0                         ; ">"
	beq.s	option_s_greater

option_s_back_one:
	subq.l	#1,a5                           ; give the character back

option_s_done:
	bra.w	options_loop

option_s_percent:
	clr.b	select_compare_size             ; S%: select_compare_size 0
	bra.s	option_s_done

option_s_ampersand:
	move.b	#$1,select_compare_size         ; S&: select_compare_size 1
	bra.s	option_s_done

option_s_bar:
	st	select_compare_size             ; S|: select_compare_size -1
	bra.s	option_s_done

option_s_less:
	st	select_chain_case_exits         ; S<: set select_chain_case_exits
	bra.s	option_s_done

option_s_greater:
	sf	select_chain_case_exits         ; S>: clear select_chain_case_exits
	bra.s	option_s_done

option_u:
	tst.b	parsing_command_line_flag       ; U is ignored while the command line is parsed
	bne.s	option_s_back_one
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_u
	cmpi.b	#$2b,d0                         ; "+"
	beq.s	option_u_plus
	cmpi.b	#$2d,d0                         ; "-"
	beq.s	option_u_minus
	addq.l	#4,sp                           ; U alone: drop the caller's return address (see header)
	pea	copy_statement_code(pc)         ; return through copy_statement_code instead
	lea	statement_code_buffer,a1        ; a1 = statement code buffer
	move.w	#$4e96,(a1)+                    ; $4e96 = jsr (a6), the break check call

option_u_done:
	bra.s	option_s_back_one

option_u_minus:
	clr.b	break_check_flag                ; U-: no break checks
	bra.s	option_u_done

option_u_plus:
	st	break_check_flag                ; U+: break checks on
	bra.s	option_u_done

option_i:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_i
	cmpi.b	#$2b,d0                         ; "+"
	beq.s	.irq_on
	cmpi.b	#$2d,d0                         ; "-"
	bne.s	option_u_done
	move.w	#$340,(a4)+                     ; I-: library routine $340 IRQOFF
	bra.s	option_u_done
.irq_on:
	move.w	#$33f,(a4)+                     ; I+: library routine $33f IRQON
	bra.s	option_u_done

option_b:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_b
	cmpi.b	#$2b,d0                         ; "+" only
	bne.s	option_u_done
	move.w	#$357,(a4)+                     ; B+: library routine $357 BOMBON
	bra.s	option_u_done

option_f:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_f
	cmpi.b	#$3e,d0                         ; ">"
	beq.s	.option_f_greater
	cmpi.b	#$3c,d0                         ; "<"
	bne.s	option_u_done
	st	option_f_flag                   ; F<: set option_f_flag
	bra.s	option_u_done
.option_f_greater:
	sf	option_f_flag                   ; F>: clear option_f_flag

option_f_done:
	bra.s	option_u_done

option_p:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_p
	cmpi.b	#$3c,d0                         ; "<"
	beq.s	option_p_less
	cmpi.b	#$3e,d0                         ; ">"
	bne.s	option_p_done
	st	option_p_flag                   ; P>: set option_p_flag

option_p_done:
	bra.s	option_f_done

option_p_less:
	sf	option_p_flag                   ; P<: clear option_p_flag
	bra.s	option_p_done

option_star:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_star
	cmpi.b	#$26,d0                         ; "&"
	beq.s	.star_ampersand
	cmpi.b	#$25,d0                         ; "%"
	bne.s	option_p_done
	sf	option_star_flag                ; *%: clear option_star_flag
	bra.s	option_p_done
.star_ampersand:
	st	option_star_flag                ; *&: set option_star_flag
	bra.s	option_p_done

option_e:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_e
	cmpi.b	#$24,d0                         ; "$"
	beq.s	.error_names_on
	cmpi.b	#$23,d0                         ; "#"
	bne.s	option_p_done
	sf	error_names_flag                ; E#: clear error_names_flag
	bra.s	option_p_done
.error_names_on:
	st	error_names_flag                ; E$: set error_names_flag
	bra.s	option_p_done

option_c:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_c
	cmpi.b	#$2b,d0                         ; "+"
	beq.s	.option_c_on
	cmpi.b	#$2d,d0                         ; "-"
	bne.s	option_p_done
	sf	option_c_flag                   ; C-: clear option_c_flag
	bra.s	option_p_done
.option_c_on:
	st	option_c_flag                   ; C+: set option_c_flag

option_c_done:
	bra.s	option_p_done

option_n:
	move.b	(a5)+,d0                        ; next character
	cmpi.b	#$20,d0                         ; spaces are skipped
	beq.s	option_n
	cmpi.b	#$2b,d0                         ; "+"
	beq.s	.option_n_on
	cmpi.b	#$2d,d0                         ; "-"
	bne.s	option_c_done
	sf	option_n_flag                   ; N-: clear option_n_flag
	bra.s	option_c_done
.option_n_on:
	st	option_n_flag                   ; N+: set option_n_flag
	bra.s	option_c_done

;------------------------------------------------------------------------------
; Statement SOUND [channel,volume,note,octave[,duration]] (command 354): SOUND0-SOUND4 ($2d8-$2dc) by
; argument count, SOUNDP $2dd for a # (period) form; a trailing duration goes to PAUSE (parse_pause).
;------------------------------------------------------------------------------
stmt_sound:
	cmpi.b	#$46,(a5)                       ; handler (SOUND): picks SOUND0-SOUND4 / SOUNDP by argument count,
                                                ;   trailing duration = PAUSE
	beq.s	sound_no_arguments              ; token $46 = end of statement: SOUND alone
	bsr.w	parse_int_and_push              ; first argument, pushed
	cmpi.b	#$46,-$1(a5)                    ; statement ended after one argument
	beq.s	sound_one_argument
	bsr.w	parse_int_and_push              ; second argument, pushed
	cmpi.b	#$46,-$1(a5)                    ; statement ended after two arguments
	beq.s	sound_two_arguments
	cmpi.b	#$4d,(a5)+                      ; token $4d = #: period form
	beq.s	.sound_period
	subq.l	#1,a5                           ; give the token back
	bsr.w	parse_int_and_push              ; third argument, pushed
	cmpi.b	#$46,-$1(a5)                    ; statement ended after three arguments
	beq.s	sound_three_arguments
	bsr.s	sound_four_arguments            ; fourth argument and SOUND4
.check_duration:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement, otherwise a duration
	bne.w	parse_pause                     ; the duration: PAUSE n
	rts
.sound_period:
	bsr.w	parse_integer_expression        ; the period, in d0
	move.w	#$801c,(a4)+                    ; IR $801c: pop the second into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the first into d1
	move.w	#$2dd,(a4)+                     ; library routine $2dd SOUNDP
	bra.s	.check_duration                 ; then the optional duration

sound_no_arguments:
	move.w	#$2d8,(a4)+                     ; library routine $2d8 SOUND0
	rts

sound_one_argument:
	move.w	#$2d9,-$2(a4)                   ; overwrite the $8017 push with library routine $2d9 SOUND1
	rts

sound_two_arguments:
	move.w	#$801b,-$2(a4)                  ; last push becomes pop the first into d1
	move.w	#$2da,(a4)+                     ; library routine $2da SOUND2
	rts

sound_three_arguments:
	move.w	#$801c,-$2(a4)                  ; last push becomes pop the second into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the first into d1
	move.w	#$2db,(a4)+                     ; library routine $2db SOUND3
	rts

;------------------------------------------------------------------------------
; Parses the last SOUND argument and writes IR $801d $801c $801b and library routine $2dc SOUND4.
;------------------------------------------------------------------------------
sound_four_arguments:
	bsr.w	parse_integer_expression        ; fourth argument, in d0
	move.w	#$801d,(a4)+                    ; IR $801d: pop the third into d3
	move.w	#$801c,(a4)+                    ; IR $801c: pop the second into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the first into d1
	move.w	#$2dc,(a4)+                     ; library routine $2dc SOUND4
	rts

;------------------------------------------------------------------------------
; Statement WAVE voice,env,form,period[,duration] (command 355): WAVE1-WAVE4 ($2de-$2e1) by argument
; count (none: SOUND0); a trailing duration goes to PAUSE.
;------------------------------------------------------------------------------
stmt_wave:
	cmpi.b	#$46,(a5)                       ; handler (WAVE): WAVE1-WAVE4 by argument count
	beq.s	sound_no_arguments              ; no arguments: SOUND0
	bsr.w	parse_int_and_push              ; first argument, pushed
	cmpi.b	#$46,-$1(a5)                    ; statement ended after one argument
	beq.s	.wave_one_argument
	bsr.w	parse_int_and_push              ; second argument, pushed
	cmpi.b	#$46,-$1(a5)                    ; statement ended after two arguments
	beq.s	.wave_two_arguments
	bsr.w	parse_int_and_push              ; third argument, pushed
	cmpi.b	#$46,-$1(a5)                    ; statement ended after three arguments
	beq.s	.wave_three_arguments
	bsr.s	wave_four_arguments             ; fourth argument and WAVE4
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of statement, otherwise a duration
	bne.w	parse_pause                     ; the duration: PAUSE n
	rts
.wave_one_argument:
	move.w	#$2de,-$2(a4)                   ; the $8017 push becomes library routine $2de WAVE1
	rts
.wave_two_arguments:
	move.w	#$801b,-$2(a4)                  ; last push becomes pop the first into d1
	move.w	#$2df,(a4)+                     ; library routine $2df WAVE2
	rts
.wave_three_arguments:
	move.w	#$801c,-$2(a4)                  ; last push becomes pop the second into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the first into d1
	move.w	#$2e0,(a4)+                     ; library routine $2e0 WAVE3
	rts

;------------------------------------------------------------------------------
; Parses the last WAVE argument and writes IR $801d $801c $801b and library routine $2e1 WAVE4.
;------------------------------------------------------------------------------
wave_four_arguments:
	bsr.w	parse_integer_expression        ; fourth argument, in d0
	move.w	#$801d,(a4)+                    ; IR $801d: pop the third into d3
	move.w	#$801c,(a4)+                    ; IR $801c: pop the second into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop the first into d1
	move.w	#$2e1,(a4)+                     ; library routine $2e1 WAVE4
	rts

parse_cint:
	move.w	#$317,d0                        ; library routine $317 CINT
	bra.w	emit_code_after_value

parse_v_opnwk:
	move.w	#$318,d0                        ; library routine $318 V_OPNWK
	bra.s	parse_open_workstation

parse_v_opnvwk:
	move.w	#$31a,d0                        ; library routine $31a V_OPNVWK

parse_open_workstation:
	move.w	d0,-(sp)                        ; save the routine number
	bsr.w	parse_integer_expression        ; the device id
	cmpi.b	#$20,-$1(a5)                    ; token $20 after the device id: no further arguments
	beq.s	.device_id_only
	move.w	#$8027,(a4)+                    ; IR $8027 = push word; ten more word arguments follow
	bsr.w	parse_int_and_push_word         ; nine more words pushed
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_int_and_push_word
	bsr.w	parse_integer_expression        ; the last one, in d0
	move.w	#$801f,(a4)+                    ; IR $801f: pop into d5; the five long pops take the words in pairs
	move.w	#$801e,(a4)+                    ; IR $801e: pop into d4
	move.w	#$801d,(a4)+                    ; IR $801d: pop into d3
	move.w	#$801c,(a4)+                    ; IR $801c: pop into d2
	move.w	#$801b,(a4)+                    ; IR $801b: pop into d1
	move.w	(sp)+,(a4)                      ; routine number
	addq.w	#1,(a4)+                        ; routine + 1 = VxOPNWK / VxOPNVWK (long form)
	rts
.device_id_only:
	move.w	(sp)+,(a4)+                     ; short form: routine number only
	rts

parse_v_clswk:
	move.w	#$31d,(a4)+                     ; library routine $31d V_CLSWK
	rts

parse_v_clsvwk:
	move.w	#$31e,(a4)+                     ; library routine $31e V_CLSVWK
	rts

parse_v_updwk:
	move.w	#$31c,(a4)+                     ; library routine $31c V_UPDWK
	rts

parse_vst_load:
	move.w	#$31f,d0                        ; library routine $31f VST_LOAD
	bra.w	emit_code_after_one_int

parse_vst_unload:
	move.w	#$320,d0                        ; library routine $320 VST_UNLO(AD)
	bra.w	emit_code_after_one_int

parse_vqt_name:
	move.w	#$321,d0                        ; library routine $321 VQT_NAME
	bra.w	emit_code_after_int_and_value

parse_vqt_extent:
	bsr.w	parse_expression                ; the text string
	move.w	#$322,(a4)+                     ; library routine $322 VQT_EXTE(NT)
	cmpi.b	#$20,-$1(a5)                    ; token $20 = end of arguments: no result arrays
	beq.s	.no_result_arrays
	move.w	#$8209,(a4)+                    ; optional result arrays bracketed by IR $8209 / $820a
	bsr.w	store_four_results
	move.w	#$820a,(a4)+
	bra.w	store_four_results              ; second four results, then return
.no_result_arrays:
	rts

parse_kchar:
	move.w	#$323,d0                        ; library routine $323 KCHAR
	bra.w	emit_code_after_int_and_value

;------------------------------------------------------------------------------
; Statement DIR [path$ [TO file$]] (command 319): DIR0/DIR1/DIR2 ($324-$326) by argument count.
;------------------------------------------------------------------------------
stmt_dir:
	move.w	#$324,-(sp)                     ; library routine $324 DIR0 (+ argument count)
	bra.s	emit_dir_files_call

;------------------------------------------------------------------------------
; Statement FILES [path$ [TO file$]] (command 325): FILES0/FILES1/FILES2 ($327-$329) by argument count.
;------------------------------------------------------------------------------
stmt_files:
	move.w	#$327,-(sp)                     ; library routine $327 FILES0 (+ argument count)

;------------------------------------------------------------------------------
; Shared by DIR and FILES. Entry: base routine on the stack. Parses up to two strings ($8018 / $8023
; between them), adds 1 per argument and writes the routine.
;------------------------------------------------------------------------------
emit_dir_files_call:
	cmpi.b	#$46,(a5)                       ; token $46 = end of line: no arguments
	beq.s	.write_routine
	bsr.w	parse_expression                ; first string
	addq.w	#1,(sp)                         ; routine + 1
	cmpi.b	#$46,-$1(a5)                    ; only one string?
	beq.s	.write_routine
	move.w	#$8018,(a4)+                    ; IR $8018: push the first string
	bsr.w	parse_expression                ; second string
	move.w	#$8023,(a4)+                    ; IR $8023: pop the first string into a1
	addq.w	#1,(sp)                         ; routine + 2
.write_routine:
	move.w	(sp)+,(a4)+                     ; write DIRn / FILESn
	rts

;------------------------------------------------------------------------------
; Statement STOP (command 340): compiled like END (bra compile_end).
;------------------------------------------------------------------------------
stmt_stop:
	bra.w	compile_end                     ; STOP = END

;------------------------------------------------------------------------------
; Statement DRAW "commands",x,... (command 371): each group is a string, optionally followed by numbers
; marked with token $37: string only DRAWS0 $32a, string+number DRAWS1 $32b, string+two numbers
; DRAWS2 $32c (float pushed with $8002). Further numbers in a group are parsed and dropped.
;------------------------------------------------------------------------------
stmt_draw_string:
	bsr.w	parse_expression                ; handler (DRAW): token $37 separates arguments; DRAWS0/1/2 per group
	cmpi.b	#$46,-$1(a5)                    ; end of line: string only
	beq.s	emit_draws0
	cmpi.b	#$37,(a5)                       ; token $37 = number follows
	beq.s	.second_argument
	bsr.s	emit_draws0                     ; another group: emit DRAWS0 and parse the next string
	bra.s	stmt_draw_string
.second_argument:
	addq.l	#1,a5                           ; skip the $37
	move.w	#$8018,(a4)+                    ; IR $8018: push the string
	bsr.w	parse_expression                ; first number
	cmpi.b	#$46,-$1(a5)                    ; end of line: string + one number
	beq.s	emit_draws1
	cmpi.b	#$37,(a5)                       ; second number follows?
	beq.s	.third_argument
	bsr.s	emit_draws1                     ; another group: emit DRAWS1 and continue
	bra.s	stmt_draw_string
.third_argument:
	addq.l	#1,a5                           ; skip the $37
	move.w	#$8002,(a4)+                    ; IR $8002 push float
	bsr.w	parse_expression                ; second number
	bsr.s	emit_draws2                     ; string + two numbers: DRAWS2
.skip_extra_numbers:
	cmpi.b	#$46,-$1(a5)                    ; end of line: done
	beq.s	.done
	cmpi.b	#$37,(a5)                       ; no further number: next group
	bne.s	stmt_draw_string
	pea	(a4)                            ; keep the IR pointer: extra number is parsed and dropped
	bsr.w	parse_expression                ; parse the extra number
	movea.l	(sp)+,a4                        ; discard its IR
	bra.s	.skip_extra_numbers
.done:
	rts

;------------------------------------------------------------------------------
; Writes library routine $32a DRAWS0 (DRAW command string only).
;------------------------------------------------------------------------------
emit_draws0:
	move.w	#$32a,(a4)+                     ; library routine $32a DRAWS0
	rts

;------------------------------------------------------------------------------
; Writes IR $8022 (pop the pushed long) and library routine $32b DRAWS1.
;------------------------------------------------------------------------------
emit_draws1:
	move.w	#$8022,(a4)+                    ; IR $8022 then library routine $32b DRAWS1
	move.w	#$32b,(a4)+
	rts

;------------------------------------------------------------------------------
; Writes IR $8004 (pop float), IR $8022 and library routine $32c DRAWS2.
;------------------------------------------------------------------------------
emit_draws2:
	move.w	#$8004,(a4)+                    ; IR $8004 $8022 then library routine $32c DRAWS2
	move.w	#$8022,(a4)+
	move.w	#$32c,(a4)+
	rts

;------------------------------------------------------------------------------
; Statement SETDRAW x,y,angle (command 396): SETXDRAW $2c7, SETYDRAW $2e4 and SETHDRAW $2e5, one value each.
;------------------------------------------------------------------------------
stmt_setdraw:
	bsr.w	parse_expression
	move.w	#$2c7,(a4)+                     ; library routine $2c7 SETXDRAW
	bsr.w	parse_expression
	move.w	#$2e4,(a4)+                     ; library routine $2e4 SETYDRAW
	move.w	#$2e5,d0                        ; library routine $2e5 SETHDRAW after the third value
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement STORE #n,a$()[,count [TO last]] (command 402): routine $2ec STORE1 or $2ed STORE2.
;------------------------------------------------------------------------------
stmt_store:
	bsr.s	parse_store_recall_arguments    ; d0 = 0 short form, 1 with TO
	addi.w	#$2ec,d0                        ; $2ec STORE1 / $2ed STORE2
	move.w	d0,(a4)+
	rts

;------------------------------------------------------------------------------
; Statement RECALL #n,a$(),count[ TO last],var (command 403): routine $2ee RECALL1 or $2ef RECALL2, result into the last
; variable.
;------------------------------------------------------------------------------
stmt_recall:
	bsr.s	parse_store_recall_arguments    ; handler (RECALL): RECALL1/RECALL2 ($2ee + d0)
	addi.w	#$2ee,d0                        ; $2ee RECALL1 / $2ef RECALL2
	move.w	d0,(a4)+
	bra.w	store_one_result                ; store the result into the last variable

;------------------------------------------------------------------------------
; Parses "#n, a$(), count [TO last]" for STORE/RECALL.
; Writes the channel push, the count (or IR $8007 -1 when absent), optional second value,
; IR $801c and the string array reference $814f n. Exit: d0 = 0 short form, 1 with the extra value.
;------------------------------------------------------------------------------
parse_store_recall_arguments:
	addq.l	#1,a5                           ; skip the '#' token
	bsr.w	parse_int_and_push              ; channel number pushed
	moveq	#0,d0                           ; d0 = string array number
	cmpi.b	#$f0,(a5)+                      ; variable tokens $f0-$ff carry a two-byte number
	bcs.s	.array_number_low
	move.b	(a5)+,d0                        ; high byte of the number
	asl.w	#8,d0
.array_number_low:
	move.b	(a5)+,d0
	move.w	d0,-(sp)                        ; keep the array number
	addq.l	#1,a5                           ; skip the '(' ')' token
	cmpi.b	#$46,(a5)+                      ; token $46 = end of line: no count
	bne.s	.parse_count
	moveq	#0,d0                           ; short form
	move.w	#$8007,(a4)+                    ; no count: IR $8007 integer constant -1
	move.l	#$ffffffff,(a4)+
	bra.s	.write_array_reference
.parse_count:
	bsr.w	parse_integer_expression        ; count
	moveq	#0,d0                           ; short form unless TO follows
	cmpi.b	#$47,-$1(a5)                    ; token $47 = TO
	bne.s	.write_array_reference
	move.w	#$8017,(a4)+                    ; IR $8017 push long: count
	bsr.w	parse_integer_expression        ; last element
	move.w	#$801b,(a4)+                    ; IR $801b: pop the count into d1
	moveq	#1,d0                           ; form with TO
.write_array_reference:
	move.w	#$801c,(a4)+                    ; IR $801c: pop the channel into d2
	move.w	#$814f,(a4)+                    ; IR $814f = string array reference
	move.w	(sp)+,(a4)+                     ; array number
	rts

;------------------------------------------------------------------------------
; Statement V~H=n (command 406): routine $312 V_HSET, one integer argument.
;------------------------------------------------------------------------------
stmt_v_h_assign:
	move.w	#$312,d0
	bra.w	emit_code_after_one_int         ; one integer, then the routine

;------------------------------------------------------------------------------
; Statement WRITE [#n,]item,... (command 416): channel PXInit $25e or screen P0Init $25d; numbers (token
; $37) PRNUM $3f, strings WRITESTR $2e8, WRKOMMA $2e9 between items, PRCR $3c at the end unless it ends
; with ";" (token $22).
;------------------------------------------------------------------------------
stmt_write:
	cmpi.b	#$4d,(a5)+                      ; token $4d = #
	bne.s	.screen_output
	bsr.w	parse_integer_expression        ; channel number
	move.w	#$25e,(a4)+                     ; library routine $25e PXInit (output to channel)
	bra.s	.next_item
.screen_output:
	subq.l	#1,a5                           ; no '#': put the token back
	move.w	#$25d,(a4)+                     ; library routine $25d P0Init (output to screen)
.next_item:
	cmpi.b	#$37,(a5)                       ; token $37 = numeric item
	bne.s	.string_item
	addq.l	#1,a5                           ; skip the $37
	bsr.w	parse_expression                ; numeric item
	move.w	#$3f,(a4)+                      ; library routine $3f PRNUM
	bra.s	.item_written
.string_item:
	bsr.w	parse_expression                ; string item
	move.w	#$2e8,(a4)+                     ; library routine $2e8 WRITESTR
.item_written:
	cmpi.b	#$46,-$1(a5)                    ; token $46 = end of line
	beq.s	.new_line
	cmpi.b	#$22,-$1(a5)                    ; token $22 = ";": no new line at the end
	beq.s	.done
	move.w	#$2e9,(a4)+                     ; library routine $2e9 WRKOMMA between items
	bra.s	.next_item
.new_line:
	move.w	#$3c,(a4)+                      ; library routine $3c PRCR: new line
.done:
	rts

;------------------------------------------------------------------------------
; Statement VSETCOLOR index,r,g,b / VSETCOLOR index,rgb (command 419): routine $2e7 VSET4COL with four
; arguments, $2e6 VSET2COL with two.
;------------------------------------------------------------------------------
stmt_vsetcolor:
	bsr.w	parse_int_and_push              ; colour index
	bsr.w	parse_int_and_push              ; second argument
	cmpi.b	#$46,-$1(a5)                    ; only two arguments?
	beq.s	.two_arguments
	bsr.w	parse_int_and_push              ; third argument
	bsr.w	parse_integer_expression        ; fourth argument
	move.w	#$801d,(a4)+                    ; IR $801d/$801c/$801b: pop the arguments into d3/d2/d1
	move.w	#$801c,(a4)+
	move.w	#$801b,(a4)+
	move.w	#$2e7,(a4)+                     ; library routine $2e7 VSET4COL
	rts
.two_arguments:
	move.w	#$801b,-$2(a4)                  ; overwrite the last push with IR $801b pop into d1
	move.w	#$2e6,(a4)+                     ; library routine $2e6 VSET2COL
	rts

;------------------------------------------------------------------------------
; RCALL addr,regs%(): the address, then the int register array ($81ae n) and library routine $2ea RCALL.
;------------------------------------------------------------------------------
parse_rcall:
	bsr.w	parse_integer_expression        ; address
	moveq	#0,d0                           ; d0 = int array number
	cmpi.b	#$f0,(a5)+                      ; variable tokens $f0-$ff carry a two-byte number
	bcs.s	.array_number_low
	move.b	(a5)+,d0                        ; high byte of the number
	asl.w	#8,d0
.array_number_low:
	move.b	(a5)+,d0                        ; low byte
	move.w	#$81ae,(a4)+                    ; IR $81ae = integer array reference
	move.w	d0,(a4)+
	move.w	#$2ea,(a4)+                     ; library routine $2ea RCALL
	rts

;------------------------------------------------------------------------------
; Parses a call argument list in which every argument is a long. Each argument's IR is moved
; to the stack and written back in reverse order, so the last argument is pushed first.
; Then IR $8022 and IR $8016 with the argument byte count. With option C+ (dat_04146) the call
; is bracketed by IR $8206 ... $8205.
;------------------------------------------------------------------------------
parse_call_long_arguments:
	move.b	option_c_flag(pc),d0            ; option C+: bracket the call
	beq.s	.first_argument
	move.w	#$8206,(a4)+                    ; IR $8206 before the call
.first_argument:
	moveq	#-4,d1                          ; d1 = argument byte count (-4 + 4 per argument)
	movea.l	sp,a1                           ; a1 = stack mark: end of the saved IR
	bra.s	.parse_argument                 ; first argument has no separator
.next_argument:
	cmpi.b	#$20,-(a5)                      ; token $20 before: end of the argument list
	beq.s	.restore_argument_ir
	cmpi.b	#$46,(a5)+                      ; token $46 = end of line
	beq.s	.restore_argument_ir
.parse_argument:
	movem.l	d1/a0-a2/a4,-(sp)               ; save registers; a4 saved goes back into a3
	bsr.w	parse_int_and_push              ; parse and push the long argument
	movem.l	(sp)+,d1/a0-a3                  ; a3 = start of this argument's IR
	addq.l	#4,d1                           ; 4 bytes per long argument
.save_argument_ir:
	move.w	-(a4),-(sp)                     ; copy this argument's IR words to the stack
	cmpa.l	a3,a4                           ; back at the argument's start?
	bne.s	.save_argument_ir
	bra.s	.next_argument                  ; next argument
.restore_argument_ir:
	move.w	(sp)+,(a4)+                     ; write the saved IR back, reversed by argument
	cmpa.l	a1,sp                           ; all saved IR written back?
	bne.s	.restore_argument_ir
	move.w	#$8022,(a4)+                    ; IR $8022: pop the address into a0
	move.w	#$8016,(a4)+                    ; IR $8016: call with the argument byte count
	move.w	d1,(a4)+                        ; byte count
	move.b	option_c_flag(pc),d0            ; option C+: close the bracket
	beq.s	.done
	move.w	#$8205,(a4)+                    ; IR $8205 after the call
.done:
	rts

;------------------------------------------------------------------------------
; Like parse_call_long_arguments, but token $8b before an argument makes it a word ($8027 push, 2 bytes)
; and $8a a long (4 bytes); ends with IR $8022 and IR $8015 with the byte count (C: style call).
;------------------------------------------------------------------------------
parse_c_call_arguments:
	move.b	option_c_flag(pc),d0            ; option C+: bracket the call
	beq.s	.first_argument
	move.w	#$8206,(a4)+                    ; IR $8206 before the call
.first_argument:
	moveq	#-4,d1                          ; d1 = argument byte count (-4 + size per argument)
	movea.l	sp,a1                           ; a1 = stack mark: end of the saved IR
	bra.s	.parse_long_argument            ; first argument: parse as a long
.next_argument:
	cmpi.b	#$8b,(a5)+                      ; token $8b = word argument (W:)
	beq.s	.word_argument
	cmpi.b	#$8a,-(a5)                      ; token $8a = long argument (L:)
	beq.s	.long_argument
	cmpi.b	#$20,-$1(a5)                    ; token $20 just read: end of the argument list
	beq.s	.restore_argument_ir
	cmpi.b	#$20,(a5)                       ; token $20 next: skip it and end
	bne.s	.word_argument                  ; anything else: a word argument
	addq.l	#1,a5
	bra.s	.restore_argument_ir
.word_argument:
	movem.l	d1/a0-a2/a4,-(sp)               ; save registers; a4 saved goes back into a3
	bsr.w	parse_int_and_push_word         ; parse and push the word argument
	movem.l	(sp)+,d1/a0-a3                  ; a3 = start of this argument's IR
	addq.w	#2,d1                           ; 2 bytes per word argument
	bra.s	.save_argument_ir
.long_argument:
	addq.l	#1,a5                           ; skip the $8a
.parse_long_argument:
	movem.l	d1/a0-a2/a4,-(sp)               ; save registers; a4 saved goes back into a3
	bsr.w	parse_int_and_push              ; parse and push the long argument
	movem.l	(sp)+,d1/a0-a3                  ; a3 = start of this argument's IR
	addq.l	#4,d1                           ; 4 bytes per long argument
.save_argument_ir:
	move.w	-(a4),-(sp)                     ; copy this argument's IR words to the stack
	cmpa.l	a3,a4                           ; back at the argument's start?
	bne.s	.save_argument_ir
	bra.s	.next_argument                  ; next argument
.restore_argument_ir:
	move.w	(sp)+,(a4)+                     ; write the saved IR back, reversed by argument
	cmpa.l	a1,sp                           ; all saved IR written back?
	bne.s	.restore_argument_ir
	move.w	#$8022,(a4)+                    ; IR $8022: pop the address into a0
	move.w	#$8015,(a4)+                    ; IR $8015 C: call with the argument byte count
	move.w	d1,(a4)+                        ; byte count
	move.b	option_c_flag(pc),d0            ; option C+: close the bracket
	beq.s	.done
	move.w	#$8205,(a4)+                    ; IR $8205 after the call
.done:
	rts

;------------------------------------------------------------------------------
; Statement INSERT a(i)=value (command 350). Array token (type & $0f; token >= $f0 two-byte number),
; the index pushed, the value (float/string arrays parse_expression, the others integer), IR $801e,
; then IR $81ac+type ($81b0-$81b9) and the array number.
;------------------------------------------------------------------------------
stmt_insert:
	moveq	#0,d0                           ; d0 = array number
	move.b	(a5)+,d1                        ; d1 = array token
	cmpi.b	#$f0,d1                         ; tokens $f0-$ff carry a two-byte number
	bcs.s	.array_number_low
	move.b	(a5)+,-(sp)                     ; high byte via the stack
	move.w	(sp)+,d0
.array_number_low:
	move.b	(a5)+,d0                        ; low byte
	andi.w	#$f,d1                          ; d1 = array type
	move.w	d0,-(sp)                        ; keep the array number
	move.w	d1,-(sp)                        ; keep the type
	bsr.w	parse_int_and_push              ; index pushed
	cmpi.w	#$5,(sp)                        ; type 4 float / 5 string: full expression
	bhi.s	.integer_value
	bsr.w	parse_expression
	bra.s	.write_insert
.integer_value:
	bsr.w	parse_integer_expression        ; other types: integer value
.write_insert:
	move.w	#$801e,(a4)+                    ; IR $801e: pop the index into d4
	move.w	#$81ac,d0                       ; IR $81ac + type: INSERT into the array
	add.w	(sp)+,d0                        ; + type
	move.w	d0,(a4)+
	move.w	(sp)+,(a4)+                     ; array number
	rts

;------------------------------------------------------------------------------
; Statement DELETE a(i) (command 351): the index, IR $81b0+type ($81b4-$81bd) and the array number.
;------------------------------------------------------------------------------
stmt_delete:
	moveq	#0,d0                           ; handler: integer expression, IR $81b0+type and the variable number
	move.b	(a5)+,d1                        ; d1 = array token
	cmpi.b	#$f0,d1                         ; tokens $f0-$ff carry a two-byte number
	bcs.s	.array_number_low
	move.b	(a5)+,-(sp)                     ; high byte via the stack
	move.w	(sp)+,d0
.array_number_low:
	move.b	(a5)+,d0                        ; low byte
	andi.w	#$f,d1                          ; d1 = array type
	move.w	d0,-(sp)                        ; keep the array number
	move.w	d1,-(sp)                        ; keep the type
	bsr.w	parse_integer_expression        ; index
	move.w	#$81b0,d0                       ; IR $81b0 + type: DELETE from the array
	add.w	(sp)+,d0                        ; + type
	move.w	d0,(a4)+
	move.w	(sp)+,(a4)+                     ; array number
	rts

;------------------------------------------------------------------------------
; Reads a variable token through a5. Exit: d1 = type (bit 4 cleared), d0 = variable number
; (two-byte when bit 4 of the token is set).
;------------------------------------------------------------------------------
read_variable_token:
	moveq	#0,d0
	moveq	#31,d1                          ; d1 = low five bits of the token
	and.b	(a5)+,d1
	bclr	#$4,d1                          ; bit 4 set: two-byte number
	beq.s	.number_low
	move.b	(a5)+,d0                        ; high byte
	asl.w	#8,d0
.number_low:
	move.b	(a5)+,d0                        ; low byte
	rts

;------------------------------------------------------------------------------
; Statement QSORT (command 345): compiled by stmt_ssort, then the routine word written last is moved
; from the SSORT group ($2fa-$305) to the QSORT group ($306-$311) by adding $0c.
;------------------------------------------------------------------------------
stmt_qsort:
	bsr.s	stmt_ssort                      ; untraced code: QSORT/SSORT handlers (N_SS $2fa ... S_SSKX $305)
	addi.w	#$c,-$2(a4)                     ; SSORT routine -> QSORT routine ($2fa+n -> $306+n)
	rts

;------------------------------------------------------------------------------
; Statement SSORT a(s)[,n[,m%()]] and the string forms with OFFSET / WITH (command 346; also the body of
; QSORT). d1/d0 = array type/number (read_variable_token); the sign token after "(" gives the order flag
; d2 (written as IR $800e flag). Count: integer expression, or IR $8007 -1 for all. String arrays: optional
; offset (token $6d, else $8007 0) pushed; WITH table (after token $72: int $81ae, word $81ba, byte
; $81bb, element size code via $81c1 $8008) selects S_SSK; a companion int array ($81ae n $81c0) gives
; S_SSX / S_SSKX. Other arrays: array_reference_ir_by_type, $800e, routine $2fa + type index (N/S/I/W/C)
; + 5 with a companion array (..._SSX). Token meanings $6d, $72, $e6, $f6 are inferred, not confirmed.
;------------------------------------------------------------------------------
stmt_ssort:
	bsr.s	read_variable_token
	move.b	(a5)+,d2                        ; sign token after the array name
	subq.b	#6,d2                           ; sign token after the array name: order flag
	bgt.s	.order_flag                     ; token above 6: it was the sign
	addq.l	#1,a5                           ; otherwise skip one more token
.order_flag:
	tst.b	d2
	smi	d2                              ; d2 = -1 or 0: sort order
	move.b	(a5)+,d3                        ; d3 = token after the array
	cmpi.b	#$46,d3                         ; token $46 = end of line: no arguments
	bne.s	.has_arguments
	cmpi.w	#$5,d1                          ; string array without arguments: offset 0
	bne.s	.no_offset
	move.w	#$8009,(a4)+                    ; IR $8009 constant into d2: offset 0
	clr.l	(a4)+
.no_offset:
	bra.w	.count_all                      ; sort the whole array
.has_arguments:
	cmpi.b	#$5,d1                          ; string array?
	bne.w	.parse_count                    ; no: numeric array sort
	cmpi.b	#$6d,d3                         ; token $6d before the offset (assumed OFFSET)
	bne.s	.default_offset
	movem.l	d0-d2,-(sp)                     ; offset value
	bsr.w	parse_integer_expression
	movem.l	(sp)+,d0-d2
	bra.s	.push_offset
.default_offset:
	move.w	#$8007,(a4)+                    ; no offset: IR $8007 integer constant 0
	clr.l	(a4)+
.push_offset:
	move.w	#$8017,(a4)+                    ; IR $8017 push long: offset
	moveq	#0,d4                           ; d4 = key table token (0 = none)
	cmpi.b	#$72,-$1(a5)                    ; token $72 (assumed WITH): key table array follows
	bne.s	.parse_string_count
	move.b	(a5)+,d4                        ; d4 = key table array token
	moveq	#0,d5                           ; d5 = key table array number
	cmpi.b	#$f0,d4                         ; tokens $f0-$ff carry a two-byte number
	bcs.s	.key_number_low
	move.b	(a5)+,d5                        ; high byte
	asl.w	#8,d5
.key_number_low:
	move.b	(a5)+,d5                        ; low byte
	addq.l	#2,a5                           ; skip the '(' ')' tokens
.parse_string_count:
	move.w	#$2fb,d7                        ; library routine $2fb S_SS
	cmpi.b	#$46,-$1(a5)                    ; end of line: sort all elements
	beq.w	.string_sort_all
	movem.l	d0-d7,-(sp)                     ; count
	bsr.w	parse_integer_expression
	movem.l	(sp)+,d0-d7
	tst.w	d4                              ; key table given?
	beq.s	.check_companion
	andi.w	#$f,d4                          ; key table array type
	cmpi.w	#$6,d4                          ; 6 = int array
	beq.s	.int_key_table
	cmpi.w	#$c,d4                          ; 12 = word array
	beq.s	.word_key_table
	move.w	#$81bb,(a4)+                    ; byte array: IR $81bb, size code 0
	moveq	#0,d6
	bra.s	.write_key_table
.word_key_table:
	move.w	#$81ba,(a4)+                    ; word array: IR $81ba, size code 1
	moveq	#1,d6
	bra.s	.write_key_table
.int_key_table:
	move.w	#$81ae,(a4)+                    ; int array: IR $81ae, size code 3
	moveq	#3,d6
.write_key_table:
	move.w	d5,(a4)+                        ; key table array number
	move.w	#$81c1,(a4)+                    ; IR $81c1 separator
	move.w	#$8008,(a4)+                    ; IR $8008 then the element size code (long)
	move.l	d6,(a4)+
	move.w	#$304,d7                        ; library routine $304 S_SSK (with key table)
.check_companion:
	moveq	#0,d3                           ; d3 = companion array number
	cmpi.b	#$46,-$1(a5)                    ; end of line: no companion array
	beq.s	.write_string_sort
	move.b	(a5)+,d3                        ; companion int array: tokens $e6 / $f6 checked (meaning not confirmed)
	cmpi.b	#$e6,d3                         ; single-byte array token
	beq.s	.companion_number_low
	cmpi.b	#$f6,d3                         ; $f6: no companion array (meaning not confirmed)
	beq.s	.write_string_sort
	move.b	(a5)+,d3                        ; high byte
	asl.w	#8,d3
.companion_number_low:
	move.b	(a5)+,d3                        ; low byte
	move.w	#$81ae,(a4)+                    ; IR $81ae int array reference: companion array
	move.w	d3,(a4)+
	move.w	#$81c0,(a4)+                    ; IR $81c0 separator
	move.w	#$305,d7                        ; library routine $305 S_SSKX
	tst.w	d4                              ; with a key table keep S_SSKX
	bne.s	.write_string_sort
	move.w	#$300,d7                        ; library routine $300 S_SSX
.write_string_sort:
	move.w	#$814f,(a4)+                    ; IR $814f string array reference
	move.w	d0,(a4)+                        ; array number
	move.w	#$800e,(a4)+                    ; IR $800e: sort order flag (long follows)
	ext.w	d2                              ; flag sign-extended to a long
	ext.l	d2
	move.l	d2,(a4)+
	move.w	#$801c,(a4)+                    ; IR $801c: pop the offset into d2
	move.w	d7,(a4)+                        ; S_SS / S_SSK / S_SSX / S_SSKX
	rts
.string_sort_all:
	tst.w	d4                              ; key table given?
	beq.s	.string_no_key_table
	andi.w	#$f,d4                          ; key table array type
	cmpi.w	#$6,d4                          ; 6 = int array
	beq.s	.all_int_key_table
	cmpi.w	#$c,d4                          ; 12 = word array
	beq.s	.all_word_key_table
	move.w	#$81bb,(a4)+                    ; byte array: IR $81bb, size code 0
	moveq	#0,d6
	bra.s	.all_write_key_table
.all_word_key_table:
	move.w	#$81ba,(a4)+                    ; word array: IR $81ba, size code 1
	moveq	#1,d6
	bra.s	.all_write_key_table
.all_int_key_table:
	move.w	#$81ae,(a4)+                    ; int array: IR $81ae, size code 3
	moveq	#3,d6
.all_write_key_table:
	move.w	d5,(a4)+                        ; key table array number
	move.w	#$81c1,(a4)+                    ; IR $81c1 separator
	move.w	#$8008,(a4)+                    ; IR $8008 then the element size code (long)
	move.l	d6,(a4)+
	move.w	#$304,d7                        ; library routine $304 S_SSK
	move.w	#$8007,(a4)+                    ; count: IR $8007 integer constant -1 (all)
	move.l	#$ffffffff,(a4)+
	bra.s	.write_string_sort
.string_no_key_table:
	move.w	#$801c,(a4)+                    ; IR $801c: pop the offset into d2
	bra.s	.count_all                      ; count -1, then the array reference
.parse_count:
	movem.l	d0-d2,-(sp)                     ; count
	bsr.w	parse_integer_expression
	movem.l	(sp)+,d0-d2
	bra.s	.check_companion_array
.count_all:
	move.w	#$8007,(a4)+                    ; count: IR $8007 integer constant -1 (all)
	move.l	#$ffffffff,(a4)+
.check_companion_array:
	moveq	#0,d3                           ; d3 = 0: no companion array
	cmpi.b	#$46,-$1(a5)                    ; end of line: no companion array
	beq.s	.write_array_sort
	cmpi.b	#$e6,(a5)+                      ; single-byte array token
	beq.s	.companion_array_number_low
	cmpi.b	#$f6,-$1(a5)                    ; $f6: no companion array (meaning not confirmed)
	beq.s	.write_array_sort
	move.b	(a5)+,d3                        ; high byte
	asl.w	#8,d3
.companion_array_number_low:
	move.b	(a5)+,d3                        ; low byte
	move.w	#$81ae,(a4)+                    ; IR $81ae int array reference: companion array
	move.w	d3,(a4)+
	move.w	#$81c0,(a4)+                    ; IR $81c0 separator
	moveq	#5,d3                           ; +5: the ..._SSX routine
.write_array_sort:
	add.w	d1,d1                           ; word index into the table
	move.w	array_reference_ir_by_type(pc,d1.w),(a4)+ ; array reference IR for the type
	move.w	d0,(a4)+                        ; array number
	move.w	#$800e,(a4)+                    ; IR $800e: sort order flag (long follows)
	ext.w	d2                              ; flag sign-extended to a long
	ext.l	d2
	move.l	d2,(a4)+
	lsr.w	#1,d1                           ; d1 = type - 4
	subq.w	#4,d1
	cmpi.w	#$4,d1                          ; 4 float .. 7 bool give 0-3
	bcs.s	.add_routine_base
	subq.w	#5,d1                           ; 12 word / 13 byte give 3-4
.add_routine_base:
	addi.w	#$2fa,d1                        ; routine $2fa + type index (+5 with a companion array)
	add.w	d3,d1                           ; +5 with a companion array
	move.w	d1,(a4)+                        ; the sort routine
	rts
array_reference_ir_by_type:
	dc.w	$0000,$0000,$0000,$0000,$81be,$814f,$81ae,$820b ; array types: 4 float $81be, 5 string $814f, 6 int
                                                ;   $81ae, 7 bool $820b, 12 word $81ba, 13 byte $81bb
	dc.w	$0000,$0000,$0000,$0000,$81ba,$81bb

;------------------------------------------------------------------------------
; DIM?(a()): array reference from array_reference_ir_by_type and library routine $313 DIMQ.
;------------------------------------------------------------------------------
parse_dim_query:
	bsr.w	read_variable_token
	addq.l	#2,a5                           ; skip the '(' ')' tokens
	add.w	d1,d1                           ; word index into the table
	move.w	array_reference_ir_by_type(pc,d1.w),(a4)+ ; array reference IR for the type
	move.w	d0,(a4)+                        ; array number
	move.w	#$313,(a4)+                     ; library routine $313 DIMQ
	rts

;------------------------------------------------------------------------------
; Statement BITBLT s%(),d%(),p%() (command 399): three int array references ($81ae n, separated by
; $81c1 and $81c0) and routine $26d BITBLT.
;------------------------------------------------------------------------------
stmt_bitblt_arrays:
	bsr.w	read_variable_token             ; handler (BITBLT with three int arrays): $81ae / $81c1 / $81c0, routine
                                                ;   $26d BITBLT
	addq.l	#2,a5                           ; skip the separator tokens
	move.w	#$81ae,(a4)+                    ; IR $81ae int array reference: source
	move.w	d0,(a4)+
	move.w	#$81c1,(a4)+                    ; IR $81c1 separator
	bsr.w	read_variable_token             ; destination array
	addq.l	#2,a5                           ; skip the separator tokens
	move.w	#$81ae,(a4)+                    ; IR $81ae int array reference: destination
	move.w	d0,(a4)+
	move.w	#$81c0,(a4)+                    ; IR $81c0 separator
	bsr.w	read_variable_token             ; parameter array
	move.w	#$81ae,(a4)+                    ; IR $81ae int array reference: parameters
	move.w	d0,(a4)+
	move.w	#$26d,(a4)+                     ; library routine $26d BITBLT
	rts

;------------------------------------------------------------------------------
; Statement BITBLT a%() (command 400): one int array reference and routine $26e BITABLT.
;------------------------------------------------------------------------------
stmt_bitblt_array:
	bsr.w	read_variable_token
	move.w	#$81ae,(a4)+                    ; IR $81ae int array reference
	move.w	d0,(a4)+                        ; array number
	move.w	#$26e,(a4)+                     ; library routine $26e BITABLT
	rts

;------------------------------------------------------------------------------
; Statement BITBLT adr (command 401): routine $26f BITXBLT, one integer argument.
;------------------------------------------------------------------------------
stmt_bitblt_address:
	move.w	#$26f,d0                        ; library routine $26f BITXBLT
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement INLINE var%,len (command 417): the variable number, then the long at the next even address
; in the token stream (offset of the inline data) is turned into an address relative to the data
; section (+ inline_area_start - data_text_start): IR $81bf long, then $8042 (store int) + variable.
;------------------------------------------------------------------------------
stmt_inline:
	moveq	#0,d3                           ; d3 = variable number
	cmpi.b	#$f0,(a5)+                      ; tokens $f0-$ff carry a two-byte number
	bcs.s	.variable_number_low
	move.b	(a5)+,-(sp)                     ; high byte via the stack
	move.w	(sp)+,d3
.variable_number_low:
	move.b	(a5)+,d3                        ; low byte
	move.l	a5,d1                           ; align to the long that follows the token
	addq.l	#3,d1
	andi.w	#$fffe,d1
	movea.l	d1,a5
	move.l	(a5)+,d1                        ; d1 = offset of the inline data
	add.l	inline_area_start,d1            ; make the inline data offset relative to the data section
	sub.l	data_text_start,d1
	move.w	#$81bf,(a4)+                    ; IR $81bf: address constant (long follows)
	move.l	d1,(a4)+
	move.w	#$8042,(a4)+                    ; IR $8042: store into the int variable
	move.w	d3,(a4)+                        ; variable number
	rts

;------------------------------------------------------------------------------
; Statement POLYLINE n,x(),y()[ OFFSET dx,dy] (command 347): routine $347 through emit_polygon_call.
;------------------------------------------------------------------------------
stmt_polyline:
	move.w	#$347,-(sp)                     ; library routine $347 (POLYLINE)
	bra.s	emit_polygon_call

;------------------------------------------------------------------------------
; Statement POLYFILL n,x(),y()[ OFFSET dx,dy] (command 348): routine $346 through emit_polygon_call.
;------------------------------------------------------------------------------
stmt_polyfill:
	move.w	#$346,-(sp)                     ; library routine $346 (POLYFILL)
	bra.s	emit_polygon_call

;------------------------------------------------------------------------------
; Statement POLYMARK n,x(),y()[ OFFSET dx,dy] (command 349): routine $348 through emit_polygon_call.
;------------------------------------------------------------------------------
stmt_polymark:
	move.w	#$348,-(sp)                     ; library routine $348 (POLYMARK)

;------------------------------------------------------------------------------
; Shared by POLYLINE/POLYFILL/POLYMARK. Entry: routine word on the stack. Count pushed, then the x and y
; arrays; the offset pair (or IR $8008 0 / $8007 0). Each array reference by type: float $81be (flag
; -1), int $81ae (1), word $81ba (0), written with IR $800a / $800b and the flag long; $81c0 between,
; then $801c and the routine.
;------------------------------------------------------------------------------
emit_polygon_call:
	bsr.w	parse_int_and_push              ; point count pushed
	moveq	#31,d0                          ; d0 = x array token, low five bits
	and.b	(a5)+,d0
	moveq	#0,d1                           ; d1 = x array number
	bclr	#$4,d0                          ; bit 4: two-byte number
	beq.s	.x_array_number_low
	move.b	(a5)+,d1                        ; high byte
	asl.w	#8,d1
.x_array_number_low:
	move.b	(a5)+,d1                        ; low byte
	addq.l	#2,a5                           ; skip the '(' ')' and comma tokens
	moveq	#31,d2                          ; d2 = y array token, low five bits
	and.b	(a5)+,d2
	moveq	#0,d3                           ; d3 = y array number
	bclr	#$4,d2                          ; bit 4: two-byte number
	beq.s	.y_array_number_low
	move.b	(a5)+,d3                        ; high byte
	asl.w	#8,d3
.y_array_number_low:
	move.b	(a5)+,d3                        ; low byte
	addq.l	#1,a5                           ; skip the '(' ')' token
	cmpi.b	#$46,(a5)+                      ; token $46 = end: no OFFSET, offsets 0
	bne.s	.parse_offsets
	move.w	#$8008,(a4)+                    ; IR $8008 constant 0: x offset
	clr.l	(a4)+
	move.w	#$8007,(a4)+                    ; IR $8007 integer constant 0: y offset
	clr.l	(a4)+
	bra.s	.write_x_array
.parse_offsets:
	movem.w	d0-d3,-(sp)                     ; keep the array tokens across the parse
	bsr.w	parse_int_and_push              ; x offset pushed
	bsr.w	parse_integer_expression        ; y offset
	move.w	#$801b,(a4)+                    ; IR $801b: pop the x offset into d1
	movem.w	(sp)+,d0-d3
.write_x_array:
	subq.w	#6,d0                           ; x array type: below 6 float, 6 int, above word
	beq.s	.x_int_array
	bgt.s	.x_word_array
	move.w	#$81be,(a4)+                    ; float array: IR $81be, flag -1
	moveq	#-1,d0
	bra.s	.x_array_number
.x_int_array:
	move.w	#$81ae,(a4)+                    ; int array: IR $81ae, flag 1
	moveq	#1,d0
	bra.s	.x_array_number
.x_word_array:
	move.w	#$81ba,(a4)+                    ; word array: IR $81ba, flag 0
	moveq	#0,d0
.x_array_number:
	move.w	d1,(a4)+                        ; x array number
	move.w	#$800a,(a4)+                    ; IR $800a then the element-type flag (long)
	move.l	d0,(a4)+
	subq.w	#6,d2                           ; y array type: below 6 float, 6 int, above word
	beq.s	.y_int_array
	bgt.s	.y_word_array
	move.w	#$81be,(a4)+                    ; float array: IR $81be, flag -1
	moveq	#-1,d0
	bra.s	.y_array_number
.y_int_array:
	move.w	#$81ae,(a4)+                    ; int array: IR $81ae, flag 1
	moveq	#1,d0
	bra.s	.y_array_number
.y_word_array:
	move.w	#$81ba,(a4)+                    ; word array: IR $81ba, flag 0
	moveq	#0,d0
.y_array_number:
	move.w	d3,(a4)+                        ; y array number
	move.w	#$81c0,(a4)+                    ; IR $81c0 separator
	move.w	#$800b,(a4)+                    ; IR $800b then the element-type flag (long)
	move.l	d0,(a4)+
	move.w	#$801c,(a4)+                    ; IR $801c: pop the point count into d2
	move.w	(sp)+,(a4)+                     ; POLYLINE / POLYFILL / POLYMARK
	rts

;------------------------------------------------------------------------------
; Statement STICK n (command 353): routine $349 XSTICK, one integer argument.
;------------------------------------------------------------------------------
stmt_stick:
	move.w	#$349,d0                        ; library routine $349 XSTICK
	bra.w	emit_code_after_one_int

;------------------------------------------------------------------------------
; Statement EVERY STOP (command 363): routine $33a EVEHOLD.
;------------------------------------------------------------------------------
stmt_every_stop:
	move.w	#$33a,(a4)+                     ; library routine $33a EVEHOLD
	rts

;------------------------------------------------------------------------------
; Statement EVERY CONT (command 364): routine $33b EVECONT.
;------------------------------------------------------------------------------
stmt_every_cont:
	move.w	#$33b,(a4)+                     ; library routine $33b EVECONT
	rts

;------------------------------------------------------------------------------
; Statement AFTER STOP (command 366): routine $33d AFTHOLD.
;------------------------------------------------------------------------------
stmt_after_stop:
	move.w	#$33d,(a4)+                     ; library routine $33d AFTHOLD
	rts

;------------------------------------------------------------------------------
; Statement AFTER CONT (command 367): routine $33e AFTCONT.
;------------------------------------------------------------------------------
stmt_after_cont:
	move.w	#$33e,(a4)+                     ; library routine $33e AFTCONT
	rts

;------------------------------------------------------------------------------
; Statement EVERY t GOSUB proc (command 362): the interval, then IR $80ff + procedure and routine $339 EVERY.
;------------------------------------------------------------------------------
stmt_every:
	bsr.w	parse_integer_expression        ; the interval
	move.w	#$339,d0                        ; library routine $339 EVERY with the procedure

emit_procedure_call_jump:
	bra.w	emit_procedure_call             ; IR $80ff + procedure, then routine d0

;------------------------------------------------------------------------------
; Statement AFTER t GOSUB proc (command 365): the time, then IR $80ff + procedure and routine $33c AFTER.
;------------------------------------------------------------------------------
stmt_after:
	bsr.w	parse_integer_expression        ; the time
	move.w	#$33c,d0                        ; library routine $33c AFTER with the procedure
	bra.s	emit_procedure_call_jump

parse_on_error:
	move.w	#$344,(a4)+                     ; library routine $344 OFFERR
	rts

parse_on_error_gosub:
	move.w	#$345,d0                        ; library routine $345 ONERROR with the procedure
	bra.s	emit_procedure_call_jump

parse_on_break:
	move.w	#$342,(a4)+                     ; library routine $342 OFFBRK
	rts

parse_on_break_cont:
	move.w	#$341,(a4)+                     ; library routine $341 ONBRKCON
	rts

parse_on_break_gosub:
	move.w	#$343,d0                        ; library routine $343 ONBREAK with the procedure
	bra.s	emit_procedure_call_jump

;------------------------------------------------------------------------------
; Statement OPTION BASE 0/1 (command 410): bit 0 of the next token word goes into option_base_flag
; and selects routine $34b OPTB0 or $34c OPTB1.
;------------------------------------------------------------------------------
stmt_option_base:
	moveq	#1,d0                           ; bit 0 of the next token word = base 0/1
	and.w	(a5)+,d0
	move.l	d0,option_base_flag             ; base kept for the array code
	addi.w	#$34b,d0                        ; library routine $34b OPTB0 / $34c OPTB1
	move.w	d0,(a4)+
	rts

;------------------------------------------------------------------------------
; Statement LIST (command 388): not compiled; report_not_compiled prints "LIST - nicht compiliert" (name string follows
; the bsr).
;------------------------------------------------------------------------------
reject_list:
	bsr.w	report_not_compiled             ; prints the name below and does not return here
	dc.b	'LIST',0
	dc.b	$00

;------------------------------------------------------------------------------
; Statement LLIST (command 389): not compiled; report_not_compiled prints "LLIST - nicht compiliert" (name string
; follows the bsr).
;------------------------------------------------------------------------------
reject_llist:
	bsr.w	report_not_compiled             ; prints the name below and does not return here
	dc.b	'LLIST',0

;------------------------------------------------------------------------------
; Statement SAVE (command 390): not compiled; report_not_compiled prints "SAVE - nicht compiliert" (name string follows
; the bsr).
;------------------------------------------------------------------------------
reject_save:
	bsr.w	report_not_compiled             ; prints the name below and does not return here
	dc.b	'SAVE',0
	dc.b	$00

;------------------------------------------------------------------------------
; Statement PSAVE (command 391): not compiled; report_not_compiled prints "PSAVE - nicht compiliert" (name string
; follows the bsr).
;------------------------------------------------------------------------------
reject_psave:
	bsr.w	report_not_compiled             ; prints the name below and does not return here
	dc.b	'PSAVE',0

;------------------------------------------------------------------------------
; Statement RUN [file$] (command 393): routine $351 RUN alone, with a file name as CHAIN.
;------------------------------------------------------------------------------
stmt_run:
	cmpi.b	#$46,(a5)                       ; RUN alone
	bne.s	stmt_chain                      ; with a file name: CHAIN
	move.w	#$351,(a4)+                     ; library routine $351 RUN
	rts

;------------------------------------------------------------------------------
; Statement CHAIN file$ (commands 392, 394; also RUN file$): routine $352 CHAIN, string argument.
;------------------------------------------------------------------------------
stmt_chain:
	move.w	#$352,d0                        ; library routine $352 CHAIN after the file name
	bra.w	emit_code_after_value

;------------------------------------------------------------------------------
; Statement LOAD (command 395): not compiled; report_not_compiled prints "LOAD - nicht compiliert" (name string follows
; the bsr).
;------------------------------------------------------------------------------
reject_load:
	bsr.w	report_not_compiled             ; prints the name below and does not return here
	dc.b	'LOAD',0
	dc.b	$00

;------------------------------------------------------------------------------
; Statement DUMP (command 398): not compiled; report_not_compiled prints "DUMP - nicht compiliert" (name string follows
; the bsr).
;------------------------------------------------------------------------------
reject_dump:
	bsr.w	report_not_compiled             ; prints the name below and does not return here
	dc.b	'DUMP',0
	dc.b	$00

reject_trace_string:
	bsr.w	report_not_compiled             ; prints "TRACE$ - nicht compiliert"
	dc.b	'TRACE$',0
	dc.b	$00

reject_tron:
	bsr.w	report_not_compiled             ; prints "TRON - nicht compiliert"
	dc.b	'TRON',0
	dc.b	$00

reject_troff:
	bsr.w	report_not_compiled             ; prints "TROFF - nicht compiliert"
	dc.b	'TROFF',0

;------------------------------------------------------------------------------
; Statement DEFLIST (command 281): not compiled; report_not_compiled prints "DEFLIST - nicht compiliert" (name string
; follows the bsr).
;------------------------------------------------------------------------------
reject_deflist:
	bsr.w	report_not_compiled             ; prints the name below and does not return here
	dc.b	'DEFLIST',0

;------------------------------------------------------------------------------
; Statement CURVE x0,y0,x1,y1,x2,y2,x3,y3 (command 422): routine $359 CURVE, eight integer arguments.
;------------------------------------------------------------------------------
stmt_curve:
	move.w	#$359,d0                        ; library routine $359 CURVE
	bra.w	emit_code_after_eight_ints

;------------------------------------------------------------------------------
; Pre-pass over the IR buffer (var_119e2): a sign/zero extension ($802f/$8030 word, $802e byte)
; directly before IR $8022 and a byte/word store ($8096/$8097) is deleted, since the store
; truncates anyway. Restarts after each deletion. Uses ir_operand_size_table to step over operands.
;------------------------------------------------------------------------------
remove_extends_before_poke:
	lea	ir_buffer,a4
.next_word:
	move.w	(a4)+,d0
	bgt.s	.next_word                      ; library routine words (positive) have no operand
	beq.s	.done                           ; 0 = end of the IR
	cmpi.w	#$8030,d0                       ; $8030 CARD()
	beq.s	.check_word_extend
	cmpi.w	#$802f,d0                       ; $802f WORD()
	bne.s	.check_byte_extend
.check_word_extend:
	cmpi.w	#$8022,(a4)                     ; followed by IR $8022 pop into a0?
	bne.s	.check_byte_extend
	cmpi.w	#$8097,2(a4)                    ; then $8097 word store?
	beq.s	.delete_extend
	cmpi.w	#$8096,2(a4)                    ; or $8096 byte store?
	bne.s	.check_byte_extend
.delete_extend:
	movea.l	a4,a0                           ; delete the extension word
	moveq	#2,d0
	bsr.w	ir_delete_bytes                 ; and start again from the top
	bra.s	remove_extends_before_poke
.check_byte_extend:
	cmpi.w	#$802e,d0                       ; $802e BYTE()
	bne.s	.skip_operand
	cmpi.w	#$8022,(a4)                     ; followed by IR $8022 pop into a0?
	bne.s	.skip_operand
	cmpi.w	#$8096,2(a4)                    ; then $8096 byte store: delete
	beq.s	.delete_extend
.skip_operand:
	lea	ir_operand_size_table(pc),a0    ; operand size by IR code: >= 0 bytes to skip; $ff: 4 bytes when the
                                                ;   code is $8080 or above
	andi.w	#$3ff,d0                        ; index by the low ten bits of the code
	move.b	0(a0,d0.w),d1                   ; d1 = operand size
	bpl.s	.step_operand
	not.b	d1                              ; $ff: no operand unless code $8080 or above
	bne.s	.next_word
	cmpi.w	#$80,d0                         ; below $8080: no operand
	bcs.s	.next_word
	moveq	#4,d1                           ; otherwise a long operand
.step_operand:
	ext.w	d1
	adda.w	d1,a4                           ; skip the operand
	bra.s	.next_word
.done:
	rts

;------------------------------------------------------------------------------
; Second pre-pass, run when the optimiser loop changed nothing:
;  CHR$/MKI$/MKL$ then PRSTR -> PRCHR/PRMKI/PRMKL; FTRUNC before $8005 (float to int) deleted;
;  PRNUM/PRINUM/PRSTR/P0RNUM/P0RINUM/P0RSTR followed by PRCR -> the newline forms;
;  integer constant then CHR$/MKI$/MKL$ -> constant strings $80ea/$80eb/$80ec;
;  integer constant then $8006 (int to float) -> float constant $8000;
;  NOT ($8032) after a comparison or EVEN/ODD -> the opposite test.
;------------------------------------------------------------------------------
peephole_library_calls:
	lea	ir_buffer,a4

peephole_loop:
	move.w	(a4)+,d0
	ble.s	.ir_code                        ; 0 = end, negative = IR code
	cmpi.w	#$a7,d0                         ; MKL$ then PRSTR becomes PRMKL ($ab)
	bne.s	.check_mki
	cmpi.w	#$a8,(a4)                       ; followed by PRSTR ($a8)?
	bne.s	.check_ftrunc
	move.w	#$ab,(a4)                       ; PRSTR becomes PRMKL
	bra.s	.delete_prstr
.check_mki:
	cmpi.w	#$a6,d0                         ; MKI$ then PRSTR becomes PRMKI ($aa)
	bne.s	.check_chr
	cmpi.w	#$a8,(a4)                       ; followed by PRSTR ($a8)?
	bne.s	.check_ftrunc
	move.w	#$aa,(a4)                       ; PRSTR becomes PRMKI
	bra.s	.delete_prstr
.check_chr:
	cmpi.w	#$a5,d0                         ; CHR$ then PRSTR becomes PRCHR ($a9)
	bne.s	.check_ftrunc
	cmpi.w	#$a8,(a4)                       ; followed by PRSTR ($a8)?
	bne.s	.check_ftrunc
	move.w	#$a9,(a4)                       ; PRSTR becomes PRCHR
.delete_prstr:
	bra.w	peephole_delete_word            ; delete the CHR$/MKI$/MKL$ / FTRUNC word
.check_ftrunc:
	cmpi.w	#$b3,d0                         ; FTRUNC ($b3) before float-to-int is redundant
	bne.s	.check_prcr
	cmpi.w	#$8005,(a4)                     ; followed by IR $8005 float to int?
	beq.s	.delete_prstr
.check_prcr:
	tst.w	d0                              ; library routine word?
	ble.s	.ir_code
	cmpi.w	#$3c,(a4)                       ; next word PRCR ($3c)?
	bne.s	peephole_loop
	bra.w	peephole_print_newline
.ir_code:
	bne.s	peephole_int_constant           ; IR code; 0 = end of the IR
	rts

;------------------------------------------------------------------------------
; Peephole helper: steps a4 over the operand of IR code d0 (ir_operand_size_table) and continues the scan.
;------------------------------------------------------------------------------
peephole_skip_operand:
	lea	ir_operand_size_table(pc),a0    ; step over the operand of the IR code in d0
	andi.w	#$3ff,d0                        ; index by the low ten bits of the code
	move.b	0(a0,d0.w),d1                   ; d1 = operand size
	bpl.s	.step_operand
	not.b	d1                              ; $ff: no operand unless code $8080 or above
	bne.s	peephole_loop
	cmpi.w	#$80,d0                         ; below $8080: no operand
	bcs.s	peephole_loop
	moveq	#4,d1                           ; otherwise a long operand
.step_operand:
	ext.w	d1
	adda.w	d1,a4                           ; skip the operand
	bra.s	peephole_loop

;------------------------------------------------------------------------------
; Peephole for IR $8007 c: followed by CHR$/MKI$/MKL$ ($a5-$a7) it becomes the constant string $80ea/$80eb/$80ec;
; followed by $8006 and a float use ($805d, $8001, $8002) it becomes the float constant $8000. Otherwise checks for
; a NOT ($8032) after an EVEN/ODD or comparison code and writes the opposite test.
;------------------------------------------------------------------------------
peephole_int_constant:
	cmpi.w	#$8007,d0                       ; IR $8007 = integer constant, long operand
	bne.s	.check_not
	move.l	(a4)+,d1                        ; d1 = the constant
	movem.w	(a4),d2-d3                      ; d2/d3 = the next two IR words
	cmpi.w	#$a5,d2                         ; library routine $a5 CHRSTR (CHR$)
	beq.w	peephole_chr_constant
	cmpi.w	#$a6,d2                         ; library routine $a6 MKISTR (MKI$)
	beq.w	peephole_mki_constant
	cmpi.w	#$a7,d2                         ; library routine $a7 MKLSTR (MKL$)
	beq.w	peephole_mkl_constant
	cmpi.w	#$8006,d2                       ; IR $8006 = int to float; then float use $805d/$8001/$8002
	bne.w	peephole_loop
	cmpi.w	#$805d,d3                       ; IR $805d float variable as operand
	beq.s	.make_float_constant
	cmpi.w	#$8001,d3                       ; IR $8001 float constant as operand
	beq.s	.make_float_constant
	cmpi.w	#$8002,d3                       ; IR $8002 push float
	bne.w	peephole_loop
.make_float_constant:
	move.l	d1,-(sp)                        ; keep the constant
	movea.l	a4,a0                           ; make room for the 8-byte float in place of 6 bytes
	moveq	#2,d0
	bsr.w	ir_insert_bytes
	move.l	(sp)+,d0                        ; the constant
	bsr.w	int_to_float                    ; sub_0e91e: convert the long in d0 to a float
	movem.w	d1-d2,(a4)                      ; replace the $8006 and the next word
	move.l	d0,-(a4)                        ; float mantissa high long
	move.w	#$8000,-(a4)                    ; IR $8000 = float constant (8 bytes)
	bra.w	peephole_loop
.check_not:
	cmpi.w	#$8032,(a4)                     ; IR $8032 = NOT
	bne.w	peephole_skip_operand
	cmpi.w	#$814a,d0                       ; $814a float EVEN
	beq.s	.swap_float_even_odd
	cmpi.w	#$814b,d0                       ; $814b float ODD
	bne.s	.check_compare
.swap_float_even_odd:
	eori.w	#$1,d0                          ; $814a <-> $814b (float EVEN/ODD)
	move.w	d0,(a4)                         ; write the opposite test over the NOT
	bra.w	peephole_delete_word
.check_compare:
	cmpi.w	#$8056,d0                       ; comparison codes are $8056-$8080
	bcs.w	peephole_skip_operand
	cmpi.w	#$8080,d0
	bhi.w	peephole_skip_operand
	cmpi.w	#$8079,d0                       ; $8079-$8080 integer compares
	bcs.s	peephole_not_float_compare
	subi.w	#$8079,d0                       ; index into int_compare_not_table
	add.w	d0,d0
	move.w	int_compare_not_table(pc,d0.w),(a4) ; write the opposite test over the NOT
	bra.s	peephole_delete_word            ; and delete the original code word
int_compare_not_table:
	dc.w	$807a,$8079,$807c,$807b,$8080,$807f,$807e,$807d ; NOT replacements for $8079-$8080: EVEN/ODD swap, = <>
                                                ;   swap, >= <-> <, > <-> <=
float_compare_not_table:
	dc.w	$8059,$8058,$8057,$8056,$805b,$805a ; NOT replacements for $8056-$805b

peephole_not_float_compare:
	cmpi.w	#$805b,d0                       ; $8056-$805b float compares
	bhi.w	peephole_skip_operand
	subi.w	#$8056,d0                       ; index into float_compare_not_table
	add.w	d0,d0
	move.w	float_compare_not_table(pc,d0.w),(a4) ; write the opposite test over the NOT
	bra.s	peephole_delete_word            ; and delete the original code word

;------------------------------------------------------------------------------
; Peephole: a print routine followed by PRCR ($3c) becomes its newline form: PRNUM $3f -> PXNUM $f1,
; PRINUM $40 -> PXINUM $f2, PRSTR $a8 -> PXSTR $f3, P0RNUM $262 -> P0XNUM $263, P0RINUM $261 -> P0XINUM $260,
; P0RSTR $271 -> P0XSTR $272; the PRCR word is deleted.
;------------------------------------------------------------------------------
peephole_print_newline:
	cmpi.w	#$3f,d0                         ; library routine $3f PRNUM
	beq.s	.prnum_newline
	cmpi.w	#$40,d0                         ; library routine $40 PRINUM
	beq.s	.prinum_newline
	cmpi.w	#$a8,d0                         ; library routine $a8 PRSTR
	beq.s	.prstr_newline
	cmpi.w	#$262,d0                        ; library routine $262 P0RNUM
	beq.s	.p0rnum_newline
	cmpi.w	#$261,d0                        ; library routine $261 P0RINUM
	beq.s	.p0rinum_newline
	cmpi.w	#$271,d0                        ; library routine $271 P0RSTR
	bne.w	peephole_loop
	move.w	#$272,(a4)                      ; P0RSTR -> P0XSTR $272
	bra.s	peephole_delete_word
.p0rnum_newline:
	move.w	#$263,(a4)                      ; P0RNUM -> P0XNUM $263
	bra.s	peephole_delete_word
.p0rinum_newline:
	move.w	#$260,(a4)                      ; P0RINUM -> P0XINUM $260
	bra.s	peephole_delete_word
.prnum_newline:
	move.w	#$f1,(a4)                       ; PRNUM -> PXNUM $f1
	bra.s	peephole_delete_word
.prinum_newline:
	move.w	#$f2,(a4)                       ; PRINUM -> PXINUM $f2
	bra.s	peephole_delete_word
.prstr_newline:
	move.w	#$f3,(a4)                       ; PRSTR -> PXSTR $f3

peephole_delete_word:
	moveq	#2,d0                           ; delete the word before a4

peephole_delete:
	movea.l	a4,a0                           ; delete the d0 bytes that end at a4
	bsr.w	ir_delete_bytes
	bra.w	peephole_library_calls          ; and start the peephole pass again

peephole_chr_constant:
	move.w	d1,(a4)                         ; the character code as the operand
	move.w	#$80ea,-(a4)                    ; IR $80ea = constant CHR$, word operand

peephole_delete_long:
	moveq	#4,d0                           ; delete the remaining long
	bra.s	peephole_delete                 ; and restart

peephole_mki_constant:
	move.w	d1,(a4)                         ; the two bytes as the operand
	move.w	#$80eb,-(a4)                    ; IR $80eb = constant MKI$, word operand
	bra.s	peephole_delete_long

peephole_mkl_constant:
	subq.l	#2,a4                           ; back over the $8007 operand
	move.l	d1,(a4)                         ; the long as the operand
	move.w	#$80ec,-(a4)                    ; IR $80ec = constant MKL$, long operand
	bra.s	peephole_delete_word

;------------------------------------------------------------------------------
; IR optimiser. Entry: a4 = end of the IR in var_119e2. Terminates the IR with 0, a3 = end,
; runs remove_extends_before_poke, then loops over the IR dispatching on each IR code
; (constant folding, operand reordering, deleting no-op pairs). var_117f8 is set at the start
; of a pass and cleared by every insert/delete; passes repeat until one changes nothing, then
; peephole_library_calls runs and the loop repeats if it changed anything.
; Exit: a4 = end of the optimised IR.
;------------------------------------------------------------------------------
optimise_ir:
	clr.w	(a4)                            ; IR terminator
	movea.l	a4,a3                           ; a3 = end of the IR for ir_delete_bytes / ir_insert_bytes
	bsr.w	remove_extends_before_poke

optimise_restart:
	st	optimise_no_change_flag         ; var_117f8: $ff = no change in this pass
	lea	ir_buffer_second_word,a4        ; IR start + 2; optimise_reread steps back to the first word

optimise_reread:
	subq.l	#2,a4                           ; back one word to re-read it

optimise_next:
	move.w	(a4)+,d0
	beq.w	.end_of_pass                    ; 0 = end of the IR
	bpl.s	optimise_next                   ; library routine words are skipped
	cmpi.w	#$8000,d0                       ; $8000 float constant
	beq.w	.float_constant
	cmpi.w	#$8001,d0                       ; $8001 float constant as the second operand
	beq.w	optimise_float_constant_operand
	cmpi.w	#$803e,d0                       ; $803e load float variable
	beq.w	optimise_float_variable_load
	cmpi.w	#$803b,d0                       ; $803b load string variable
	beq.w	optimise_ir_803b
	cmpi.w	#$8007,d0                       ; $8007 integer constant
	beq.w	optimise_int_constant
	cmpi.w	#$8008,d0                       ; $8008 constant into argument register 1
	beq.w	optimise_second_constant
	bcs.s	.check_exchange                 ; below $8008: not a constant code
	cmpi.w	#$8010,d0                       ; $8009-$8010 constant into argument registers 2-9: just skip the
                                                ;   operand
	bls.w	optimise_skip_long_operand
.check_exchange:
	cmpi.w	#$8083,d0                       ; $8083 exchange operands
	beq.w	optimise_exchange_operands
	cmpi.w	#$8002,d0                       ; $8002 push float
	beq.w	optimise_push_float
	cmpi.w	#$8017,d0                       ; $8017 push long
	beq.w	optimise_push_int
	cmpi.w	#$8018,d0                       ; $8018 push
	beq.w	optimise_ir_8018
	cmpi.w	#$8006,d0                       ; $8006 int to float
	beq.w	optimise_int_to_float
	cmpi.w	#$8040,d0                       ; $8040 load word variable
	beq.w	optimise_load_word_var
	cmpi.w	#$803d,d0                       ; $803d load byte variable
	beq.w	optimise_load_byte_var
	cmpi.w	#$803c,d0                       ; $803c load boolean variable
	beq.w	optimise_load_boolean_var
	cmpi.w	#$803f,d0                       ; $803f load integer variable
	beq.w	optimise_load_long_var
	cmpi.w	#$808d,d0                       ; $808d word variable as operand
	beq.w	optimise_word_var_operand
	cmpi.w	#$8099,d0                       ; $8099 byte variable as operand
	beq.w	optimise_byte_var_operand
	cmpi.w	#$8084,d0                       ; $8084 integer variable as operand
	beq.w	optimise_long_var_operand
	cmpi.w	#$805d,d0                       ; $805d float variable as operand
	beq.w	optimise_float_var_operand
	cmpi.w	#$802f,d0                       ; $802f sign-extend word
	beq.w	optimise_word_cast
	cmpi.w	#$802e,d0                       ; $802e extend byte
	beq.w	optimise_byte_cast
	cmpi.w	#$8078,d0                       ; $8078 negate
	beq.w	optimise_double_negate
	cmpi.w	#$8063,d0                       ; $8063 integer add
	beq.w	optimise_int_add
	cmpi.w	#$8064,d0                       ; $8064 integer subtract
	beq.w	optimise_int_sub
	cmpi.w	#$805e,d0                       ; $805e integer multiply
	beq.w	optimise_int_mul
	cmpi.w	#$8032,d0                       ; $8032 NOT
	beq.w	optimise_double_not
	cmpi.w	#$80ed,d0                       ; $80ed string constant
	beq.w	optimise_string_constant
	cmpi.w	#$80e9,d0                       ; $80e9 empty string
	beq.w	optimise_empty_string
	cmpi.w	#$80ea,d0                       ; $80ea one-character string constant
	beq.w	optimise_one_char_string
	cmpi.w	#$80eb,d0                       ; $80eb two-character string constant (MKI$)
	beq.w	optimise_two_char_string
	cmpi.w	#$80ec,d0                       ; $80ec four-character string constant (MKL$)
	beq.w	optimise_four_char_string
	cmpi.w	#$8038,d0                       ; $8038 INKEY$
	beq.w	optimise_inkey_string
	lea	ir_operand_size_table(pc),a0    ; any other code: step over its operand
	andi.w	#$3ff,d0                        ; index by the low ten bits of the code
	move.b	0(a0,d0.w),d1                   ; d1 = operand size
	bpl.s	.step_operand
	not.b	d1                              ; $ff: no operand unless code $8080 or above
	bne.w	optimise_next
	cmpi.w	#$80,d0                         ; below $8080: no operand
	bcs.w	optimise_next
	moveq	#4,d1                           ; otherwise a long operand
.step_operand:
	ext.w	d1
	adda.w	d1,a4                           ; skip the operand
	bra.w	optimise_next
.end_of_pass:
	tst.b	optimise_no_change_flag
	bpl.w	optimise_restart                ; something changed: another pass
	bsr.w	peephole_library_calls          ; pass without change: try the library-call peepholes
	tst.b	optimise_no_change_flag
	bpl.w	optimise_restart
	subq.l	#2,a4                           ; a4 = the terminator: end of the optimised IR
	rts
.fold_float_negate:
	neg.w	-$4(a4)                         ; $8000 c then $802d (float negate): negate the exponent word of c
	movea.l	a4,a0                           ; delete the $802d
	moveq	#2,d0
	bsr.w	ir_delete_bytes
	bra.w	optimise_reread
.fold_float_truth:
	tst.w	d5                              ; $8000 c then $80ef (truth test): integer constant TRUE when the
                                                ;   exponent is non-zero
	sne	d0                              ; d0 = -1 when non-zero
	ext.w	d0
	ext.l	d0
	move.l	d0,-(a4)                        ; the truth value
	move.w	#$8007,-(a4)                    ; IR $8007 integer constant
	bra.w	ir_delete_six_bytes             ; delete the six bytes left over
.float_constant:
	move.l	(a4)+,d3                        ; d3/d4 = mantissa, d5 = exponent word of the float constant
	move.w	(a4)+,d4
	move.w	(a4)+,d5
	move.w	(a4)+,d1                        ; d1 = the next IR code
	cmpi.w	#$80ef,d1                       ; $80ef truth test of the constant
	beq.s	.fold_float_truth
	cmpi.w	#$805d,d1                       ; $805d float variable as operand
	beq.w	fold_float_constant_with_variable
	cmpi.w	#$8001,d1                       ; $8001: second float constant, fold the operation
	beq.w	fold_float_binary
	cmpi.w	#$8002,d1                       ; $8002 push float
	beq.s	fold_float_constant_push
	cmpi.w	#$8005,d1                       ; $8005 float to int
	beq.w	fold_float_constant_to_int
	cmpi.w	#$802d,d1                       ; $802d float negate
	beq.s	.fold_float_negate
	cmpi.w	#$80bd,d1                       ; $80bd: meaning not worked out here
	beq.s	.constant_test_80bd
	cmpi.w	#$80be,d1                       ; $80be: meaning not worked out here
	beq.s	.constant_test_80be
	cmpi.w	#$5a,d1                         ; library routine $5a RANDOM with a constant argument
	beq.w	optimise_random_constant
	bra.w	optimise_reread                 ; nothing to fold
.constant_test_80bd:
	move.w	#$80bf,d1                       ; $80bd becomes $80bf
	bra.s	.write_constant_test
.constant_test_80be:
	move.w	#$80c0,d1                       ; $80be becomes $80c0
.write_constant_test:
	tst.w	d5                              ; $80bd/$80be with a constant: $8007 (c <> 0) then $80bf/$80c0
	sne	d0                              ; d0 = -1 when non-zero
	ext.w	d0
	ext.l	d0
	move.w	d1,-(a4)                        ; the code after the constant
	move.l	d0,-(a4)                        ; the truth value
	move.w	#$8007,-(a4)                    ; IR $8007 integer constant
	bra.w	ir_delete_four_bytes            ; delete the four bytes left over

optimise_retry_word:
	bra.w	optimise_reread

;------------------------------------------------------------------------------
; $8000 c followed by $8002 (push float): if the consumer of the pushed value can be found
; (measure_ir_operand) the load and push are deleted and the consuming pop becomes $8001 c
; (float constant as the second operand).
;------------------------------------------------------------------------------
fold_float_constant_push:
	bsr.w	measure_ir_operand              ; find the instruction that pops the push
	not.l	d0                              ; -1: not found
	beq.s	optimise_retry_word
	movea.l	a4,a0                           ; delete $8000 c and $8002 (12 bytes)
	moveq	#12,d0
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 = consumer, moved back by the deleted bytes
	subq.l	#2,a2                           ; back to the consumer's code word
	moveq	#8,d0                           ; make room for the 8-byte constant
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	#$8001,(a2)+                    ; IR $8001: float constant as the second operand
	move.l	d3,(a2)+
	move.w	d4,(a2)+
	move.w	d5,(a2)+
	bra.w	optimise_restart

;------------------------------------------------------------------------------
; $8000 c, $805d v (float variable as operand), op: when sub_07c7c gives the reversed operator,
; rewrite as $803e v (load variable), $8001 c, reversed op.
;------------------------------------------------------------------------------
fold_float_constant_with_variable:
	move.w	(a4)+,d1                        ; d1 = variable number
	move.w	(a4)+,d0                        ; d0 = the operator
	bsr.w	swapped_float_operator          ; d0 = the operator with the operands swapped
	bne.s	.write_swapped                  ; found: rewrite
	subq.l	#6,a4                           ; no swapped form: back to the $805d
	bra.w	optimise_next
.write_swapped:
	move.w	d0,-(a4)                        ; swapped operator
	move.w	d5,-(a4)                        ; the float constant
	move.w	d4,-(a4)
	move.l	d3,-(a4)
	move.w	#$8001,-(a4)                    ; IR $8001 float constant as the second operand
	move.w	d1,-(a4)                        ; variable number
	move.w	#$803e,-(a4)                    ; IR $803e load float variable
	sf	optimise_no_change_flag         ; mark the pass as changed
	bra.w	optimise_next

;------------------------------------------------------------------------------
; $8000 c then $8005 (float to int): the constant is converted at compile time and written as $8007 n.
;------------------------------------------------------------------------------
fold_float_constant_to_int:
	move.l	d3,d0                           ; $8000 c then $8005 (float to int): sub_0e8e0 converts, rewritten as
                                                ;   $8007
	move.w	d4,d1                           ; d0-d2 = the float constant
	move.w	d5,d2
	bsr.w	float_to_int                    ; d0 = the integer value
	move.w	#$8007,-$c(a4)                  ; IR $8007 over the $8000
	move.l	d0,-$a(a4)                      ; the integer constant
	moveq	#6,d0                           ; delete the remaining six bytes
	movea.l	a4,a0
	bsr.w	ir_delete_bytes
	bra.w	optimise_restart

;------------------------------------------------------------------------------
; $8000 c1 $8001 c2 op with two float constants: computes the result at compile time.
;  $804a c1+c2 (sub_0e634)  $804b c1-c2  $804c c2-c1  $804d c1*c2 (sub_0ea3a)
;  $804e and $804f divide (sub_0e71e, skipped when the divisor is 0)
;  $805a = and $805b <> give integer constants; $8056-$8059 order tests: $8056 computes c1>c2,
;  $8057 c1>=c2, $8058 c1<=c2, $8059 c1<c2 (exponent first, then mantissa).
;------------------------------------------------------------------------------
fold_float_binary:
	move.l	(a4)+,d0                        ; d0-d2 = the second constant
	move.w	(a4)+,d1
	move.w	(a4)+,d2
	move.w	(a4)+,d6                        ; d6 = the operator
	cmpi.w	#$804a,d6                       ; $804a float add
	beq.s	.add
	cmpi.w	#$804b,d6                       ; $804b float subtract
	beq.s	.subtract
	cmpi.w	#$804c,d6                       ; $804c reversed subtract
	beq.s	.reverse_subtract
	cmpi.w	#$804d,d6                       ; $804d float multiply
	beq.s	.multiply
	cmpi.w	#$804e,d6                       ; $804e reversed divide
	beq.s	.reverse_divide
	cmpi.w	#$804f,d6                       ; $804f float divide
	beq.s	.divide
	cmpi.w	#$805a,d6                       ; $805a =
	beq.s	.compare_equal
	cmpi.w	#$805b,d6                       ; $805b <>
	beq.s	.compare_not_equal
	cmpi.w	#$8057,d6                       ; $8057
	beq.w	.greater_or_equal
	cmpi.w	#$8056,d6                       ; $8056
	beq.w	.greater_than
	cmpi.w	#$8059,d6                       ; $8059
	beq.w	.less_than
	cmpi.w	#$8058,d6                       ; $8058
	beq.s	.less_or_equal
	suba.w	#$c,a4                          ; no fold: back to the operator
	bra.w	optimise_next
.reverse_subtract:
	neg.w	d5                              ; c2 - c1
	bra.s	.add
.subtract:
	neg.w	d2                              ; c1 - c2
.add:
	bsr.w	float_add                       ; d0-d2 = d0-d2 + d3-d5
.write_float_result:
	move.w	d2,-(a4)                        ; result written as $8000 float constant, 12 bytes deleted
	move.w	d1,-(a4)
	move.l	d0,-(a4)
	move.w	#$8000,-(a4)
	moveq	#12,d0
	bra.w	ir_delete_bytes_restart
.multiply:
	bsr.w	float_multiply                  ; d0-d2 = d0-d2 * d3-d5
	bra.s	.write_float_result
.reverse_divide:
	exg	d3,d0                           ; swap the operands for the reversed divide
	exg	d4,d1
	exg	d5,d2
.divide:
	tst.w	d5                              ; divisor zero: leave the division to run time
	beq.w	optimise_next
	bsr.w	float_divide                    ; d0-d2 = d0-d2 / d3-d5
	bra.s	.write_float_result
.compare_equal:
	cmp.w	d2,d5                           ; compare exponent words
	bne.s	.equal_result
	cmp.w	d1,d4                           ; then mantissa low words
	bne.s	.equal_result
	cmp.l	d0,d3                           ; then mantissa high longs
.equal_result:
	seq	d0                              ; comparison result as integer constant TRUE/FALSE
.write_truth_constant:
	ext.w	d0
	ext.l	d0
	move.l	d0,-(a4)                        ; the truth value
	move.w	#$8007,-(a4)                    ; IR $8007 integer constant
	moveq	#16,d0                          ; delete the 16 bytes of the two constants
	bra.w	ir_delete_bytes_restart         ; and restart
.compare_not_equal:
	cmp.w	d2,d5                           ; compare exponent words
	bne.s	.not_equal_result
	cmp.w	d1,d4                           ; then mantissa low words
	bne.s	.not_equal_result
	cmp.l	d0,d3                           ; then mantissa high longs
.not_equal_result:
	sne	d0                              ; TRUE when the constants differ
	bra.s	.write_truth_constant
.less_or_equal:
	exg	d3,d0                           ; <=: swap the constants and test >=
	exg	d4,d1
	exg	d5,d2
.greater_or_equal:
	cmp.w	d2,d5                           ; exponents differ: the larger exponent wins
	beq.s	.compare_mantissas_ge
.exponent_decides:
	sgt	d0                              ; c1 exponent greater
	bra.s	.write_truth_constant
.compare_mantissas_ge:
	move.w	d2,d6                           ; same exponent: test its sign
	bgt.s	.mantissa_ge
	beq.s	.equal_result                   ; both exponents 0: equal, so TRUE
	exg	d3,d0                           ; negative constants (exponent word sign): mantissas the other way
	exg	d4,d1
.mantissa_ge:
	cmp.l	d0,d3                           ; compare mantissas, high long first
	bne.s	.ge_result
	cmp.w	d1,d4
.ge_result:
	scc	d0                              ; c1 >= c2
	bra.s	.write_truth_constant
.less_than:
	exg	d3,d0                           ; <: swap the constants and test >
	exg	d4,d1
	exg	d5,d2
.greater_than:
	cmp.w	d2,d5                           ; exponents differ: the larger exponent wins
	bne.s	.exponent_decides
	move.w	d2,d6                           ; same exponent: test its sign
	bgt.s	.mantissa_gt
	beq.s	.not_equal_result               ; both exponents 0: equal, so FALSE
	exg	d3,d0                           ; negative constants (exponent word sign): mantissas the other way
	exg	d4,d1
.mantissa_gt:
	cmp.l	d0,d3                           ; compare mantissas, high long first
	bne.s	.gt_result
	cmp.w	d1,d4
.gt_result:
	shi	d0                              ; c1 > c2
	bra.s	.write_truth_constant

;------------------------------------------------------------------------------
; $803e v: "$803e v $8001 c $804a $8041 v" (v = v + constant) becomes $8000 c $80d8 v (add constant
; to the variable in place). "$803e v $8002" with a findable consumer becomes $805d v at the consumer.
;------------------------------------------------------------------------------
optimise_float_variable_load:
	move.w	(a4)+,d3                        ; d3 = variable number
	cmpi.w	#$8001,(a4)                     ; followed by $8001 c (float constant operand)?
	bne.s	.check_push_float
	cmpi.w	#$8041,$c(a4)                   ; $8041 = store float variable
	bne.s	.check_push_float
	cmp.w	$e(a4),d3                       ; into the same variable?
	bne.s	.check_push_float
	cmpi.w	#$804a,$a(a4)                   ; and the operator is $804a float add?
	bne.s	.check_push_float
	move.w	#$8000,(a4)                     ; $8001 becomes $8000 (constant load)
	move.w	#$80d8,$a(a4)                   ; IR $80d8: add float constant to variable
	move.w	$e(a4),$c(a4)                   ; variable number over the $8041
	lea	$e(a4),a0                       ; delete the duplicate variable number
	moveq	#2,d0
	bsr.s	ir_delete_bytes
	bra.w	ir_delete_four_bytes            ; and the $803e v in front
.check_push_float:
	cmpi.w	#$8002,(a4)                     ; followed by $8002 push float?
	bne.w	optimise_next
	addq.l	#2,a4                           ; a4 = past the push
	bsr.s	measure_ir_operand              ; find the instruction that pops it
	not.l	d0                              ; -1: not found
	beq.w	optimise_retry_word
	movea.l	a4,a0                           ; delete $803e v $8002 (6 bytes)
	moveq	#6,d0
	bsr.s	ir_delete_bytes
	suba.w	d0,a2                           ; a2 = consumer, moved back by the deleted bytes
	subq.l	#2,a2                           ; back to the consumer's code word
	moveq	#2,d0                           ; make room for the variable number
	movea.l	a2,a0
	bsr.s	ir_insert_bytes
	move.w	#$805d,(a2)+                    ; IR $805d: float variable as the operand
	move.w	d3,(a2)+
	bra.w	optimise_restart

;------------------------------------------------------------------------------
; Deletes the d0 bytes that end at a0 by moving the IR from a0 up to a3 down.
; Exit: a3 -= d0, IR terminated with 0, var_117f8 cleared (pass changed something).
;------------------------------------------------------------------------------
ir_delete_bytes:
	movea.l	a0,a1                           ; a1 = source, a0 = destination d0 bytes lower
	suba.w	d0,a0
.move_down_loop:
	move.w	(a1)+,(a0)+
	cmpa.l	a3,a1                           ; up to the end of the IR
	bcs.s	.move_down_loop
	suba.w	d0,a3                           ; a3 = new end of the IR
	clr.w	(a3)                            ; terminator
	sf	optimise_no_change_flag         ; mark the pass as changed
	rts

;------------------------------------------------------------------------------
; Opens a gap of d0 bytes at a0 by moving the IR from a0 to a3 up.
; Exit: a3 += d0, IR terminated with 0, var_117f8 cleared.
;------------------------------------------------------------------------------
ir_insert_bytes:
	movea.l	a3,a1                           ; move from the end of the IR backwards
.move_up_loop:
	move.w	(a1),0(a1,d0.w)                 ; word moves d0 bytes up
	subq.l	#2,a1
	cmpa.l	a0,a1                           ; down to the gap
	bcc.s	.move_up_loop
	adda.w	d0,a3                           ; a3 = new end of the IR
	clr.w	(a3)                            ; terminator
	sf	optimise_no_change_flag         ; mark the pass as changed
	rts

;------------------------------------------------------------------------------
; Walks forward from a4 adding up each IR code's stack effect (ir_operand_size_table) until the
; value pushed at a4 is consumed. Exit: a2 = past the consuming IR word, d1 = that word, d7 = the
; word before it, d0 = remaining balance (negative). d0 = -1 when $80b3, $818d or $818e is met
; (cannot be followed). The end of the IR is an illegal instruction (cannot happen).
;------------------------------------------------------------------------------
measure_ir_operand:
	movea.l	a4,a2                           ; a2 = scan pointer
	moveq	#0,d0                           ; d0 = stack balance in bytes
	move.w	#$3ff,d6                        ; mask for the table index
.next_word:
	move.w	d1,d7                           ; d7 = the previous word
	move.w	(a2)+,d1                        ; d1 = next IR word
	beq.s	.end_of_ir                      ; 0 = end of the IR
	bpl.s	.next_word                      ; library routine words: no stack effect counted
	move.w	d1,d2
	and.w	d6,d2                           ; d2 = table index
	cmpi.w	#$80b3,d1                       ; $80b3: cannot be followed
	beq.s	.cannot_follow
	cmpi.w	#$818d,d1                       ; $818d: cannot be followed
	beq.s	.cannot_follow
	cmpi.w	#$818e,d1                       ; $818e: cannot be followed
	beq.s	.cannot_follow
	lea	ir_operand_size_table(pc),a0
	move.b	0(a0,d2.w),d2
	ext.w	d2                              ; negative entry: ~entry+1 = byte count, bit 0 set = pop, clear = push
	bpl.s	.skip_operand                   ; positive: operand bytes to skip
	not.w	d2
	beq.s	.variable_effect                ; $ff: variable effect
	addq.w	#1,d2                           ; d2 = byte count with the pop/push bit
	bclr	#$0,d2                          ; bit 0 set: pop
	beq.s	.count_push
	sub.w	d2,d0                           ; pop: subtract from the balance
	bpl.s	.next_word                      ; balance still >= 0: keep walking
	rts                                     ; consumer found: d0 negative
.count_push:
	add.w	d2,d0                           ; push: add to the balance
	bra.s	.next_word
.skip_operand:
	adda.w	d2,a2                           ; skip the operand bytes
	bra.s	.next_word
.end_of_ir:
	illegal                                 ; end of the IR reached: should not happen
.variable_effect:
	cmpi.w	#$8080,d1                       ; $ff entry: codes below $8080 pop their word operand of bytes, others
                                                ;   pop 4 per long argument above 2
	bcs.s	.pop_word_count
	move.l	(a2)+,d2                        ; d2 = long argument count
	cmpi.w	#$2,d2                          ; two or fewer: no stack arguments
	bls.s	.next_word
	asl.w	#2,d2                           ; 4 bytes per long argument
	sub.w	d2,d0                           ; popped from the balance
	bra.s	.check_balance
.pop_word_count:
	sub.w	(a2)+,d0                        ; the word operand gives the bytes popped
.check_balance:
	bpl.s	.next_word                      ; balance still >= 0: keep walking
.cannot_follow:
	moveq	#-1,d0                          ; d0 = -1: cannot be followed
	rts

; One byte per IR code ($8000+n, n = code & $3ff): >= 0 = operand bytes following the code;
; $fc/$fe/$f8 = no operand, pushes 4/2/8 bytes; $fb/$f7 = pops 4/8; $ff = variable (operand gives
; the count). E.g. $8000/$8001 8 bytes, $8007-$8010 4, $8017 push long, $801b-$8023 pop long.
ir_operand_size_table:
	dc.w	$0808,$f8f7,$f700,$0004,$0404,$0404,$0404,$0404
	dc.w	$0400,$0000,$00ff,$fffc,$fcfc,$fbfb,$fbfb,$fbfb
	dc.w	$fbfb,$fbfb,$ffff,$fffe,$0002,$ffff,$0000,$0000
	dc.w	$0000,$0000,$0002,$0202,$0000,$0002,$0202,$0202
	dc.w	$0202,$0202,$0202,$0200,$0004,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0002,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0202,$0202,$0202,$0202,$0202,$0202
	dc.w	$0202,$0202,$0200,$0000,$0002,$0202,$0202,$0202
	dc.w	$0202,$0000,$0000,$0002,$0202,$0200,$0000,$0002
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0204,$0404
	dc.w	$04ff,$ffff,$ffff,$ffff,$ffff,$ffff,$ffff,$0202
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0202,$0406,$0200
	dc.w	$0404,$0404,$0404,$0202,$0202,$0200,$0000,$0002
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0202,$0202
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$ffff
	dc.w	$ffff,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0002
	dc.w	$0202,$0202,$02ff,$ffff,$ffff,$ffff,$0202,$0202
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0202,$0202
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0202,$0202
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0202,$0202
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0202,$0202
	dc.w	$02ff,$ffff,$ffff,$ff00,$0000,$0000,$0000,$0200
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0202,$0204
	dc.w	$0000,$0202,$0202,$0202,$0202,$0202,$0202,$0404
	dc.w	$0404,$0404,$0404,$0404,$0202,$0202,$0202,$0202
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0202,$0202
	dc.w	$0202,$0202,$0202,$0202,$0202,$0202,$0000,$0002
	dc.w	$0002,$0202,$0200,$0000,$0000,$0002,$0000,$0000

;------------------------------------------------------------------------------
; Unary folds for $8007 c (d3 = c, a4 past the operator): negate, NOT, BYTE, WORD, CARD, EVEN, ODD and SWAP
; are computed and written back into the constant, then the operator word is deleted.
;------------------------------------------------------------------------------
fold_int_negate:
	neg.l	d3                              ; -c
	bra.s	fold_int_unary_store

fold_int_not:
	not.l	d3                              ; NOT c
	bra.s	fold_int_unary_store

fold_int_byte_extend:
	andi.w	#$ff,d3                         ; BYTE(c)

fold_int_word_extend:
	ext.l	d3                              ; WORD(c): sign-extend

fold_int_unary_store:
	move.l	d3,-$6(a4)                      ; write the result back into the $8007 operand and delete the operator
	moveq	#2,d0                           ; delete the operator word
	movea.l	a4,a0

ir_delete_and_reread:
	bsr.w	ir_delete_bytes
	bra.w	optimise_reread

fold_int_unsigned_word:
	andi.l	#$ffff,d3                       ; CARD(c)
	bra.s	fold_int_unary_store

fold_int_even:
	addq.l	#1,d3                           ; EVEN(c): test bit 0 of c+1

fold_int_odd:
	andi.w	#$1,d3                          ; ODD(c): bit 0 of c
	neg.w	d3                              ; as TRUE (-1) / FALSE (0)
	bra.s	fold_int_word_extend

fold_int_swap_words:
	swap	d3                              ; SWAP(c)
	bra.s	fold_int_unary_store

;------------------------------------------------------------------------------
; $8007 c followed by: a unary operator ($8078 neg, $8032 NOT, $802f/$802e/$8030 extends, $8079 EVEN,
; $807a ODD, $8031 word swap) - folded; $8017 push - turned into a $8008-$8010 constant load at
; the consuming pop; $8008 c2 - binary fold; $8084/$808d/$8099 variable operand - reordered;
; $8027 word push - adjacent word pushes of constants merged into one long push.
;------------------------------------------------------------------------------
optimise_int_constant:
	move.l	(a4)+,d3                        ; d3 = the constant
	move.w	(a4)+,d1                        ; d1 = the next IR code
	cmpi.w	#$8078,d1                       ; $8078 negate
	beq.s	fold_int_negate
	cmpi.w	#$8032,d1                       ; $8032 NOT
	beq.s	fold_int_not
	cmpi.w	#$802f,d1                       ; $802f WORD()
	beq.s	fold_int_word_extend
	cmpi.w	#$802e,d1                       ; $802e BYTE()
	beq.s	fold_int_byte_extend
	cmpi.w	#$8030,d1                       ; $8030 CARD()
	beq.s	fold_int_unsigned_word
	cmpi.w	#$8079,d1                       ; $8079 EVEN
	beq.s	fold_int_even
	cmpi.w	#$807a,d1                       ; $807a ODD
	beq.s	fold_int_odd
	cmpi.w	#$8031,d1                       ; $8031 SWAP()
	beq.s	fold_int_swap_words
	cmpi.w	#$8017,d1                       ; $8017 push long
	beq.w	.constant_push
	cmpi.w	#$8084,d1                       ; $8084 integer variable as operand
	beq.w	reorder_constant_int_variable
	cmpi.w	#$808d,d1                       ; $808d word variable as operand
	beq.w	reorder_constant_word_variable
	cmpi.w	#$8099,d1                       ; $8099 byte variable as operand
	beq.w	reorder_constant_byte_variable
	cmpi.w	#$8008,d1                       ; $8008 second constant: fold the operation
	beq.w	fold_int_binary
	cmpi.w	#$800f,d1                       ; $800f constant: check for a POKE/DPOKE
	beq.w	fold_constant_for_store
	cmpi.w	#$8027,d1                       ; $8027 push word
	beq.s	.word_push
	cmpi.w	#$8084,d1                       ; $8085-$808c: integer variable operations
	bls.s	.check_word_variable_ops
	cmpi.w	#$808c,d1
	bls.s	.move_variable_first
.check_word_variable_ops:
	cmpi.w	#$808d,d1                       ; $808e-$8095: word variable operations
	bls.s	.check_byte_variable_ops
	cmpi.w	#$8095,d1
	bls.s	.move_variable_first
.check_byte_variable_ops:
	cmpi.w	#$8099,d1                       ; $809a-$809f: byte variable operations
	bls.s	.check_register_constant
	cmpi.w	#$809f,d1
	bls.s	.move_variable_first
.check_register_constant:
	cmpi.w	#$8009,d1                       ; $800a-$8010: constant into a register
	bls.s	.no_fold
	cmpi.w	#$8010,d1
	bls.s	.move_register_constant_first
.no_fold:
	bra.w	optimise_reread
.move_variable_first:
	subq.l	#2,a4                           ; constant then variable-operand op: write the variable op first, then
                                                ;   the constant
	move.l	(a4),d1                         ; d1 = the variable op and its number
	move.l	-(a4),d0                        ; d0 = the constant
	move.w	-(a4),d2                        ; d2 = $8007
	move.l	d1,(a4)+                        ; variable op first
	move.w	d2,(a4)+                        ; then $8007 c
	move.l	d0,(a4)+
	bra.w	optimise_restart
.move_register_constant_first:
	move.l	(a4),d1                         ; d1 = the following long
	move.w	-(a4),d5                        ; d5 = the register constant code
	move.l	-(a4),d0                        ; d0 = the first constant
	move.w	-(a4),d2                        ; d2 = $8007
	move.w	d5,(a4)+                        ; register constant first
	move.l	d1,(a4)+
	move.w	d2,(a4)+                        ; then $8007 c
	move.l	d0,(a4)+
	bra.w	optimise_restart
.word_push:
	ext.l	d3                              ; word push of a constant: sign-extend
	move.l	d3,-$6(a4)                      ; store it back as a long
	cmpi.w	#$8007,(a4)+                    ; another $8007 constant next?
	bne.s	.back_to_constant
	move.l	(a4)+,d4                        ; d4 = second constant
	cmpi.w	#$8027,(a4)+                    ; followed by another $8027 word push?
	bne.s	.not_merged
	bsr.w	measure_ir_operand              ; find the instruction that pops the two words
	not.l	d0                              ; -1: not followed, merge anyway
	beq.s	.merge_word_pushes
	subq.w	#3,d0                           ; merge only when both words are popped together
	bne.s	.not_merged
.merge_word_pushes:
	move.w	#$8017,-(a4)                    ; two constant word pushes become one long push $8007 hi:lo $8017
	move.w	d3,-(a4)                        ; first word pushed is the low word
	move.w	d4,-(a4)                        ; second word pushed is the high word
	bra.w	ir_delete_eight_bytes           ; delete the first $8007 c $8027
.not_merged:
	subq.l	#6,a4                           ; not merged: back over the second constant
.back_to_constant:
	subq.l	#4,a4                           ; back to the operand of the first $8007
	bra.w	optimise_next
.constant_push:
	bsr.w	measure_ir_operand              ; find the instruction that pops the push
	not.l	d0                              ; -1: not found
	beq.w	optimise_retry_word
	move.w	-$2(a2),-(sp)                   ; keep the consuming pop code
	movea.l	a4,a0                           ; delete $8007 c $8017 (8 bytes)
	moveq	#8,d0
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 = consumer, moved back by the deleted bytes
	subq.l	#2,a2                           ; back to the consumer's code word
	moveq	#4,d0                           ; make room for the long constant
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d0
	addi.w	#$ffed,d0                       ; pop $801b-$8023 minus $13 = constant load $8008-$8010
	move.w	d0,(a2)+                        ; the constant load in place of the pop
	move.l	d3,(a2)+                        ; the constant
	bra.w	optimise_restart

;------------------------------------------------------------------------------
; Calls sub_08e5c for the operator in d0. Exit: d0 = operator to use with the operands
; exchanged, Z set (d1 = 0) when that is possible.
;------------------------------------------------------------------------------
test_operator_swappable:
	bsr.w	swapped_int_operator
	tst.w	d1                              ; Z set when the swapped operator exists
	rts

;------------------------------------------------------------------------------
; $8007 c $8084 v op (constant, then an int variable as operand). With $8083 after it, or when the operator can
; take its operands swapped (test_operator_swappable), becomes $803f v $8008 c op'. Otherwise the variable operand
; is moved in front of the constant.
;------------------------------------------------------------------------------
reorder_constant_int_variable:
	move.w	(a4)+,d2                        ; $8007 c $8084 v op
	move.w	(a4)+,d0                        ; d0 = the operator
	cmpi.w	#$8083,d0                       ; $8083: operands exchanged anyway
	beq.s	.load_variable_exchange
	bsr.s	test_operator_swappable         ; can the operator take its operands swapped?
	beq.s	.load_variable_swapped
	subq.l	#2,a4                           ; no: $8084 v first, then $8007 c, then op
	move.l	d3,-(a4)
	move.w	#$8007,-(a4)
	move.w	d2,-(a4)
	move.w	#$8084,-(a4)
	bra.w	optimise_restart
	bra.w	optimise_next                   ; unreachable
.load_variable_swapped:
	move.w	d0,-(a4)                        ; swapped operator
	move.l	d3,-(a4)                        ; the constant
	move.w	#$8008,-(a4)                    ; IR $8008: constant as the second operand
	move.w	d2,-(a4)                        ; variable number
	move.w	#$803f,-(a4)                    ; $803f v (load int variable) then $8008 c
	sf	optimise_no_change_flag         ; mark the pass as changed
	bra.w	optimise_next
.load_variable_exchange:
	movea.l	a4,a0                           ; a0 = past the $8083, to be deleted
	subq.l	#2,a4                           ; write over $8084 v $8083
	move.l	d3,-(a4)                        ; the constant
	move.w	#$8008,-(a4)                    ; IR $8008: constant as the second operand
	move.w	d2,-(a4)                        ; variable number
	move.w	#$803f,-(a4)                    ; IR $803f load integer variable
	moveq	#2,d0                           ; delete the $8083
	bsr.w	ir_delete_bytes
	bra.w	optimise_next

;------------------------------------------------------------------------------
; $8007 c $808d v op: like reorder_constant_int_variable for a word variable ($8040 v $8008 c op'); left alone
; when the operator cannot be swapped.
;------------------------------------------------------------------------------
reorder_constant_word_variable:
	move.w	(a4)+,d2                        ; d2 = variable number
	move.w	(a4)+,d0                        ; d0 = the operator
	cmpi.w	#$8083,d0                       ; $8083: operands exchanged anyway
	beq.s	.load_variable_exchange
	bsr.s	test_operator_swappable         ; can the operator take its operands swapped?
	beq.s	.load_variable_swapped
	subq.l	#6,a4                           ; no: leave it
	bra.w	optimise_next
.load_variable_swapped:
	move.w	d0,-(a4)                        ; swapped operator
	move.l	d3,-(a4)                        ; the constant
	move.w	#$8008,-(a4)                    ; IR $8008: constant as the second operand
	move.w	d2,-(a4)                        ; variable number
	move.w	#$8040,-(a4)                    ; $8040 v (load word variable) then $8008 c
	sf	optimise_no_change_flag         ; mark the pass as changed
	bra.w	optimise_next
.load_variable_exchange:
	movea.l	a4,a0                           ; a0 = past the $8083, to be deleted
	subq.l	#2,a4                           ; write over $808d v $8083
	move.l	d3,-(a4)                        ; the constant
	move.w	#$8008,-(a4)                    ; IR $8008: constant as the second operand
	move.w	d2,-(a4)                        ; variable number
	move.w	#$8040,-(a4)                    ; IR $8040 load word variable
	moveq	#2,d0                           ; delete the $8083
	bsr.w	ir_delete_bytes
	bra.w	optimise_next

;------------------------------------------------------------------------------
; $8007 c $8099 v op: like reorder_constant_int_variable for a byte variable ($803d v $8008 c op'); left alone
; when the operator cannot be swapped.
;------------------------------------------------------------------------------
reorder_constant_byte_variable:
	move.w	(a4)+,d2                        ; d2 = variable number
	move.w	(a4)+,d0                        ; d0 = the operator
	cmpi.w	#$8083,d0                       ; $8083: operands exchanged anyway
	beq.s	.load_variable_exchange
	bsr.w	test_operator_swappable         ; can the operator take its operands swapped?
	beq.s	.load_variable_swapped
	subq.l	#6,a4                           ; no: leave it
	bra.w	optimise_next
.load_variable_swapped:
	move.w	d0,-(a4)                        ; swapped operator
	move.l	d3,-(a4)                        ; the constant
	move.w	#$8008,-(a4)                    ; IR $8008: constant as the second operand
	move.w	d2,-(a4)                        ; variable number
	move.w	#$803d,-(a4)                    ; $803d v (load byte variable) then $8008 c
	sf	optimise_no_change_flag         ; mark the pass as changed
	bra.w	optimise_next
.load_variable_exchange:
	movea.l	a4,a0                           ; a0 = past the $8083, to be deleted
	subq.l	#2,a4                           ; write over $8099 v $8083
	move.l	d3,-(a4)                        ; the constant
	move.w	#$8008,-(a4)                    ; IR $8008: constant as the second operand
	move.w	d2,-(a4)                        ; variable number
	move.w	#$803d,-(a4)                    ; IR $803d load byte variable
	moveq	#2,d0                           ; delete the $8083
	bsr.w	ir_delete_bytes
	bra.w	optimise_next

;------------------------------------------------------------------------------
; $8007 c $800f c2 followed by DPOKE $8097 or POKE $8096: c is cut to a sign-extended word or byte.
;------------------------------------------------------------------------------
fold_constant_for_store:
	cmpi.w	#$8097,4(a4)                    ; $8007 c $800f c2 followed by DPOKE $8097 / POKE $8096: truncate c to
                                                ;   word/byte
	beq.s	.word_store
	cmpi.w	#$8096,4(a4)                    ; $8096 POKE: truncate to a byte
	bne.s	.done
	ext.w	d3                              ; byte sign-extended to a word
.word_store:
	ext.l	d3                              ; word sign-extended to a long
	move.l	d3,-$6(a4)                      ; the truncated constant back into the $8007
.done:
	bra.w	optimise_reread

;------------------------------------------------------------------------------
; $8008 c (constant as second operand) followed by an operator: add/sub of 0 deleted, consecutive
; constant adds merged, constant offsets folded into address IR ($80a3-$80b2, $8035-$8037),
; multiply/divide by 0, 1, 2, -1, -2 simplified.
;------------------------------------------------------------------------------
optimise_second_constant:
	move.l	(a4)+,d3                        ; d3 = the constant
	move.w	(a4)+,d1                        ; d1 = the operator
	cmpi.w	#$8063,d1                       ; $8063 integer add
	beq.s	fold_add_constant
	cmpi.w	#$805e,d1                       ; $805e integer multiply
	beq.w	fold_multiply_constant
	cmpi.w	#$805f,d1                       ; $805f integer divide
	beq.w	fold_divide_constant
	cmpi.w	#$8064,d1                       ; $8064 integer subtract
	beq.s	fold_subtract_constant
	cmpi.w	#$814c,d1                       ; $814c word add: folded like an add
	beq.s	fold_add_constant
	cmpi.w	#$814e,d1                       ; $814e word multiply: folded like a multiply
	beq.w	fold_multiply_constant
	cmpi.w	#$814d,d1                       ; $814d word subtract: folded like a subtract
	beq.s	fold_subtract_constant
	cmpi.w	#$8083,d1                       ; $8083 exchange operands
	beq.w	fold_swapped_subtract_zero

optimise_no_constant_fold:
	subq.l	#6,a4                           ; back to the operand

optimise_skip_long_operand:
	addq.l	#4,a4                           ; step over the long operand
	bra.w	optimise_next

fold_subtract_constant:
	neg.l	d3                              ; x - c = x + (-c)

;------------------------------------------------------------------------------
; $8008 c add (subtract arrives here with c negated): + 0 is deleted; a second $8008 c2 add/subtract is merged into
; one constant; before a $8017 push the constant goes into the store address; before an address code $80a3-$80b2
; it becomes (or is added to) the code's word displacement when it fits in a word.
;------------------------------------------------------------------------------
fold_add_constant:
	tst.l	d3
	beq.s	ir_delete_eight_bytes           ; x + 0: delete
	move.w	(a4),d1                         ; d1 = the next IR code
	cmpi.w	#$8008,d1                       ; another $8008 constant next?
	bne.s	.check_push
	cmpi.w	#$8063,6(a4)                    ; followed by an add?
	beq.s	.merge_constants
	cmpi.w	#$8064,6(a4)                    ; or a subtract?
	bne.s	.no_fold
	neg.l	2(a4)                           ; subtract: negate the second constant
.merge_constants:
	add.l	2(a4),d3                        ; d3 = the sum of both constants
	move.w	#$8063,-(a4)                    ; first operator becomes an add
	move.l	d3,-(a4)                        ; with the sum as its constant
	adda.w	#$e,a4                          ; past the second $8008 c op
	bra.s	ir_delete_eight_bytes           ; delete the second constant and operator
.check_push:
	cmpi.w	#$8017,d1                       ; $8017 push: fold into the store address
	beq.s	fold_constant_into_store_address
	subi.w	#$80a3,d1                       ; $80a3-$80b2: address IR; bit 2 = the form with a word displacement
	cmpi.w	#$f,d1                          ; not an address IR code: no fold
	bhi.s	.no_fold
	btst	#$2,d1                          ; bit 2 set: already has a word displacement
	beq.s	.try_displacement_form
	move.w	2(a4),d0                        ; add the constant to the displacement
	ext.l	d0
	add.l	d3,d0
	move.w	d0,d3                           ; still fits in a word?
	ext.l	d0
	cmp.l	d0,d3
	bne.s	.no_fold
	move.w	d0,2(a4)                        ; yes: new displacement
	bra.s	ir_delete_eight_bytes           ; delete the $8008 c op
.try_displacement_form:
	move.l	d3,d0                           ; constant fits in a word?
	ext.l	d0
	cmp.l	d0,d3
	beq.s	.make_displacement_form
.no_fold:
	bra.s	optimise_no_constant_fold
.make_displacement_form:
	addq.w	#4,(a4)                         ; switch to the displacement form (code + 4)
	move.w	(a4),-$8(a4)                    ; the address code over the $8008
	move.w	d0,-$6(a4)                      ; the displacement
	addq.l	#2,a4                           ; past the old address code

ir_delete_six_bytes:
	moveq	#6,d0
	bra.s	ir_delete_bytes_restart

ir_delete_eight_bytes:
	moveq	#8,d0

ir_delete_bytes_restart:
	movea.l	a4,a0                           ; delete d0 bytes ending at a4 and restart
	bsr.w	ir_delete_bytes
	bra.w	optimise_restart

ir_delete_four_bytes:
	moveq	#4,d0
	bra.s	ir_delete_bytes_restart

ir_delete_ten_bytes:
	moveq	#10,d0
	bra.s	ir_delete_bytes_restart

;------------------------------------------------------------------------------
; $8008 c add then $8017 push: when the pushed address is popped by $8022 for a POKE/DPOKE/LPOKE ($8096-$8098)
; the store becomes $8035-$8037 with c as a word displacement; an existing displacement gets c added.
;------------------------------------------------------------------------------
fold_constant_into_store_address:
	addq.l	#2,a4                           ; past the $8017
	bsr.w	measure_ir_operand              ; find the instruction that pops the address
	subq.l	#2,a4                           ; back to the $8017
	not.l	d0                              ; -1: not found
	beq.s	.no_fold
	cmpi.w	#$8022,d1                       ; popped with $8022 into a0?
	bne.s	.no_fold
	move.w	(a2)+,d0                        ; consumer $8096-$8098 (POKE/DPOKE/LPOKE) becomes $8035-$8037 with a
                                                ;   word displacement
	cmpi.w	#$8096,d0                       ; $8096 POKE
	beq.s	.make_displacement_store
	cmpi.w	#$8097,d0                       ; $8097 DPOKE
	beq.s	.make_displacement_store
	cmpi.w	#$8098,d0                       ; $8098 LPOKE
	beq.s	.make_displacement_store
	cmpi.w	#$8035,d0                       ; $8035: POKE with a displacement already
	beq.s	.add_to_displacement
	cmpi.w	#$8036,d0                       ; $8036: DPOKE with a displacement
	beq.s	.add_to_displacement
	cmpi.w	#$8037,d0                       ; $8037: LPOKE with a displacement
	beq.s	.add_to_displacement
.no_fold:
	bra.w	optimise_reread
.make_displacement_store:
	move.l	d3,d0                           ; constant fits in a word?
	ext.l	d0
	cmp.l	d0,d3
	bne.s	.no_fold
	movea.l	a2,a0                           ; make room for the displacement after the store
	moveq	#2,d0
	bsr.w	ir_insert_bytes
	move.w	d3,(a2)                         ; the displacement
	addi.w	#$ff9f,-(a2)                    ; $8096-$8098 - $61 = $8035-$8037
	bra.s	ir_delete_eight_bytes           ; delete the $8008 c op
.add_to_displacement:
	move.w	(a2),d0                         ; add the constant to the displacement
	ext.l	d0
	add.l	d3,d0
	move.w	d0,d3
	ext.l	d0                              ; still fits in a word?
	cmp.l	d0,d3
	bne.s	.no_fold
	move.w	d0,(a2)                         ; yes: new displacement
	bra.s	ir_delete_eight_bytes           ; delete the $8008 c op

;------------------------------------------------------------------------------
; $8008 c multiply: x*0 -> $8007 0, x*1 deleted, x*2 -> $8012 (add.l d0,d0), x*-1 -> $8078, x*-2 -> $8012 $8078.
;------------------------------------------------------------------------------
fold_multiply_constant:
	tst.l	d3                              ; x*0 -> 0, x*1 deleted, x*2 -> $8012, x*-1 -> $8078 negate, x*-2 ->
                                                ;   $8012 $8078
	beq.s	.multiply_zero
	subq.l	#1,d3                           ; constant 1: delete the multiply
	beq.w	ir_delete_eight_bytes
	subq.l	#1,d3                           ; constant 2
	beq.s	.multiply_two
	addq.l	#3,d3                           ; constant -1
	beq.s	.multiply_minus_one
	addq.l	#1,d3                           ; constant -2
	bne.w	optimise_no_constant_fold       ; anything else: no fold
	move.w	#$8078,-(a4)                    ; x*-2: double then negate
	move.w	#$8012,-(a4)                    ; IR $8012: add.l d0,d0
	bra.w	ir_delete_four_bytes
.multiply_minus_one:
	move.w	#$8078,-(a4)                    ; x*-1: IR $8078 negate
	bra.w	ir_delete_six_bytes
.multiply_two:
	move.w	#$8012,-(a4)                    ; x*2: IR $8012 add.l d0,d0
	bra.w	ir_delete_six_bytes
.multiply_zero:
	clr.l	-(a4)                           ; x*0: IR $8007 integer constant 0
	move.w	#$8007,-(a4)

ir_delete_two_bytes:
	moveq	#2,d0                           ; delete two bytes ending at a4 and restart
	bra.w	ir_delete_bytes_restart

;------------------------------------------------------------------------------
; $8008 c divide: x/1 deleted, x/-1 -> $8078 negate.
;------------------------------------------------------------------------------
fold_divide_constant:
	subq.l	#1,d3                           ; x/1 deleted, x/-1 -> $8078 negate
	beq.w	ir_delete_eight_bytes           ; constant 1: delete the divide
	addq.l	#2,d3                           ; constant -1?
	bne.w	optimise_no_constant_fold       ; anything else: no fold
	move.w	#$8078,-(a4)                    ; x/-1: IR $8078 negate
	bra.w	ir_delete_six_bytes

;------------------------------------------------------------------------------
; $8008 0 $8083 $8064 (0 exchanged then subtracted): becomes $8078 negate.
;------------------------------------------------------------------------------
fold_swapped_subtract_zero:
	cmpi.w	#$8064,(a4)                     ; 0 exchanged then subtracted = negate
	bne.w	optimise_no_constant_fold
	tst.l	d3                              ; and the constant is 0?
	bne.w	optimise_no_constant_fold
	move.w	#$8078,(a4)                     ; 0 - x: IR $8078 negate over the subtract
	bra.w	ir_delete_eight_bytes           ; delete $8008 0 $8083

;------------------------------------------------------------------------------
; IR $8083 (exchange operands): $8083 $8083 cancel; before a subtract ($8064/$814d) it becomes the subtract then
; $8078 negate; before an operator that can take swapped operands it is deleted and the operator swapped.
;------------------------------------------------------------------------------
optimise_exchange_operands:
	move.w	(a4),d0                         ; $8083 $8083 cancel; $8083 before subtract -> subtract then negate;
                                                ;   else swap the operator
	cmpi.w	#$8083,d0                       ; $8083 $8083: both cancel
	beq.s	delete_operator_pair
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.subtract_then_negate
	cmpi.w	#$8064,d0                       ; $8064 subtract
	bne.s	.swap_operator
.subtract_then_negate:
	move.w	#$8078,(a4)                     ; negate the result after the subtract
	move.w	#$8064,-(a4)                    ; subtract in place of the $8083
	bra.w	optimise_restart
.swap_operator:
	bsr.w	test_operator_swappable         ; d0 = the operator for swapped operands
	beq.s	ir_delete_two_bytes             ; swappable: delete the $8083
	bra.w	optimise_next                   ; not swappable: keep the $8083

;------------------------------------------------------------------------------
; $8032 NOT twice or $8078 negate twice: both words are deleted.
;------------------------------------------------------------------------------
optimise_double_not:
	cmpi.w	#$8032,(a4)                     ; NOT NOT?
	bra.s	delete_pair_if_repeated

optimise_double_negate:
	cmpi.w	#$8078,(a4)                     ; negate negate?

delete_pair_if_repeated:
	bne.w	optimise_next                   ; not repeated: leave it

delete_operator_pair:
	addq.l	#2,a4                           ; past the second word
	bra.w	ir_delete_four_bytes            ; delete both words

;------------------------------------------------------------------------------
; $8007 c1 $8008 c2 op with two integer constants: computes the result.
;  $8063/$814c add, $8064/$814d subtract, $805e/$814e multiply (sub_0eb7a), $805f divide (sub_0ebba),
;  $8065 MOD (sub_0ec20), $8060 AND, $8061 OR, $8062 XOR, $8066 EQV, $8067 c1 OR NOT c2,
;  $8074-$8077 BTST/BSET/BCLR/BCHG, $8068-$806b long SHL/SHR/ROL/ROR, $806c-$806f word,
;  $8070-$8073 byte shifts and rotates, $807b = $807c <> $807d >= $807e > $807f <= $8080 <.
;  $8083 swaps the two constants.
;------------------------------------------------------------------------------
fold_int_binary:
	move.l	(a4)+,d4                        ; d4 = second constant, d3 = first
	move.w	(a4)+,d0                        ; d0 = the operator
	cmpi.w	#$8083,d0                       ; $8083 exchange operands
	beq.w	.exchange_constants
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.w	.add
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.w	.subtract
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.w	.add
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.w	.subtract
	cmpi.w	#$8075,d0                       ; $8075 BSET
	beq.w	.bit_set
	cmpi.w	#$8077,d0                       ; $8077 BCHG
	beq.w	.bit_change
	cmpi.w	#$8076,d0                       ; $8076 BCLR
	beq.w	.bit_clear
	cmpi.w	#$8074,d0                       ; $8074 BTST
	beq.w	.bit_test
	cmpi.w	#$8068,d0                       ; $8068 SHL long
	beq.w	.shift_left_long
	cmpi.w	#$8069,d0                       ; $8069 SHR long
	beq.w	.shift_right_long
	cmpi.w	#$806a,d0                       ; $806a ROL long
	beq.w	.rotate_left_long
	cmpi.w	#$806b,d0                       ; $806b ROR long
	beq.w	.rotate_right_long
	cmpi.w	#$806c,d0                       ; $806c SHL word
	beq.w	.shift_left_word
	cmpi.w	#$806d,d0                       ; $806d SHR word
	beq.w	.shift_right_word
	cmpi.w	#$806e,d0                       ; $806e ROL word
	beq.w	.rotate_left_word
	cmpi.w	#$806f,d0                       ; $806f ROR word
	beq.w	.rotate_right_word
	cmpi.w	#$8070,d0                       ; $8070 SHL byte
	beq.w	.shift_left_byte
	cmpi.w	#$8071,d0                       ; $8071 SHR byte
	beq.w	.shift_right_byte
	cmpi.w	#$8072,d0                       ; $8072 ROL byte
	beq.w	.rotate_left_byte
	cmpi.w	#$8073,d0                       ; $8073 ROR byte
	beq.w	.rotate_right_byte
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.w	.multiply
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.w	.multiply
	cmpi.w	#$805f,d0                       ; $805f divide
	beq.w	.divide
	cmpi.w	#$8065,d0                       ; $8065 MOD
	beq.w	.modulo
	cmpi.w	#$807b,d0                       ; $807b =
	beq.w	.compare_equal
	cmpi.w	#$807c,d0                       ; $807c <>
	beq.w	.compare_not_equal
	cmpi.w	#$807e,d0                       ; $807e
	beq.w	.compare_greater
	cmpi.w	#$807d,d0                       ; $807d
	beq.w	.compare_greater_equal
	cmpi.w	#$8080,d0                       ; $8080
	beq.w	.compare_less
	cmpi.w	#$807f,d0                       ; $807f
	beq.w	.compare_less_equal
	cmpi.w	#$8060,d0                       ; $8060 AND
	beq.w	.and
	cmpi.w	#$8061,d0                       ; $8061 OR
	beq.w	.or
	cmpi.w	#$8062,d0                       ; $8062 XOR
	beq.w	.xor
	cmpi.w	#$8066,d0                       ; $8066 EQV
	beq.w	.eqv
	cmpi.w	#$8067,d0                       ; $8067 c1 OR NOT c2
	beq.w	.imp
	subq.l	#8,a4                           ; no fold: back to the $8008 operand
	bra.w	optimise_next
.exchange_constants:
	move.l	d4,-$c(a4)                      ; swap the two constants in place
	move.l	d3,-$6(a4)                      ; first constant gets the second
	bra.w	ir_delete_two_bytes             ; delete the $8083
.add:
	add.l	d4,d3
	bra.s	.store_result
.subtract:
	sub.l	d4,d3
	bra.s	.store_result
.bit_set:
	bset	d4,d3
	bra.s	.store_result
.bit_change:
	bchg	d4,d3
	bra.s	.store_result
.bit_clear:
	bclr	d4,d3
	bra.s	.store_result
.bit_test:
	btst	d4,d3
	sne	d3                              ; bit set: TRUE
.extend_truth:
	ext.w	d3                              ; truth value sign-extended to a long
	ext.l	d3
	bra.s	.store_result
.shift_left_long:
	lsl.l	d4,d3
	bra.s	.store_result
.shift_right_long:
	lsr.l	d4,d3
	bra.s	.store_result
.rotate_left_long:
	rol.l	d4,d3
	bra.s	.store_result
.rotate_right_long:
	ror.l	d4,d3
	bra.s	.store_result
.shift_left_word:
	lsl.w	d4,d3
	bra.s	.extend_word_result
.shift_right_word:
	lsr.w	d4,d3
	bra.s	.extend_word_result
.rotate_left_word:
	rol.w	d4,d3
	bra.s	.extend_word_result
.rotate_right_word:
	ror.w	d4,d3
.extend_word_result:
	ext.l	d3                              ; word result sign-extended
.store_result:
	move.l	d3,-$c(a4)                      ; result into the $8007 operand
	moveq	#8,d0                           ; delete the $8008 c2 op
	movea.l	a4,a0
	bsr.w	ir_delete_bytes
	subq.l	#8,a4                           ; back to the $8007 for another look
	bra.w	optimise_next
.shift_left_byte:
	lsl.b	d4,d3
	bra.s	.byte_result
.shift_right_byte:
	lsr.b	d4,d3
	bra.s	.byte_result
.rotate_left_byte:
	rol.b	d4,d3
	bra.s	.byte_result
.rotate_right_byte:
	ror.b	d4,d3
.byte_result:
	andi.w	#$ff,d0                         ; masks d0, not d3, so the byte shift result is not truncated
	bra.s	.extend_word_result
.multiply:
	move.l	d4,d0                           ; d0 = second constant
	bsr.w	int_multiply                    ; d0 = c1 * c2
	move.l	d0,d3
	bra.s	.store_result
.divide:
	move.l	d4,d0
	bsr.w	int_divide                      ; d0 = c1 / c2
	move.l	d0,d3
	bra.s	.store_result
.modulo:
	move.l	d4,d0
	bsr.w	int_modulo                      ; d0 = c1 MOD c2
	move.l	d0,d3
	bra.s	.store_result
.compare_equal:
	cmp.l	d4,d3
	seq	d3
	bra.s	.extend_truth
.compare_not_equal:
	cmp.l	d4,d3
	sne	d3
	bra.s	.extend_truth
.compare_greater:
	cmp.l	d4,d3
	sgt	d3
	bra.s	.extend_truth
.compare_greater_equal:
	cmp.l	d4,d3
	sge	d3
	bra.w	.extend_truth
.compare_less:
	cmp.l	d4,d3
	slt	d3
	bra.w	.extend_truth
.compare_less_equal:
	cmp.l	d4,d3
	sle	d3
	bra.w	.extend_truth
.and:
	and.l	d4,d3
	bra.s	.store_result
.or:
	or.l	d4,d3
	bra.s	.store_result
.xor:
	eor.l	d4,d3
	bra.s	.store_result
.eqv:
	eor.l	d4,d3
	not.l	d3
	bra.s	.store_result
.imp:
	eor.l	d3,d4                           ; c1 OR NOT (c1 XOR c2), the same as c1 OR NOT c2
	not.l	d4
	or.l	d4,d3
	bra.w	.store_result

;------------------------------------------------------------------------------
; $8002 (push float): a float add/sub of two converted integers that is converted back to integer
; ($8006 ... $804a/$804b ... $8005) becomes the integer $8063/$8064; $8002 $8000 c $8004 op becomes
; $8001 c with the reversed operator; $8002 $803e v $8004 op becomes $805d v. The integer rewrite is
; also allowed without the $8006 when option %n is below 6 (var_121d0).
;------------------------------------------------------------------------------
optimise_push_float:
	bsr.w	measure_ir_operand              ; find the instruction that pops the push
	not.l	d0                              ; -1: not found
	beq.s	.check_push_operand
	cmpi.w	#$8005,2(a2)                    ; operator followed by $8005 float to int?
	bne.s	.check_push_operand
	cmpi.w	#$812a,(a2)                     ; $812a float MIN
	beq.s	.int_min
	cmpi.w	#$812b,(a2)                     ; $812b float MAX
	bne.s	.check_push_operand
	move.w	#$812d,2(a2)                    ; $812d integer MAX over the $8005
	bra.s	.rewrite_min_max
.int_min:
	move.w	#$812c,2(a2)                    ; $812c integer MIN over the $8005
.rewrite_min_max:
	move.w	#$801b,(a2)                     ; $801b over the float operator
	move.w	#$8005,-(a2)                    ; $8005 over the $8004 pop: right operand to integer
	move.w	#$8017,-(a4)                    ; $8017 integer push over the $8002
	movea.l	a4,a0                           ; make room before the push
	moveq	#2,d0
	bsr.w	ir_insert_bytes
	move.w	#$8005,(a4)                     ; $8005: left operand to integer first
	bra.w	optimise_restart
.check_push_operand:
	cmpi.w	#$8000,(a4)                     ; $8002 then a float constant?
	beq.w	.push_float_constant
	cmpi.w	#$803e,(a4)                     ; $8002 then a float variable load?
	beq.w	.push_float_variable
	cmpi.w	#$8006,-$2(a4)                  ; -2(a4) is the $8002 itself, so this test never succeeds
	beq.s	.check_int_operands
	cmpi.b	#$6,option_percent_value        ; otherwise only with option %n below 6
	bcc.w	optimise_next
.check_int_operands:
	bsr.w	measure_ir_operand              ; find the instruction that pops the push
	not.l	d0                              ; -1: not found
	beq.w	optimise_next
	cmpi.w	#$8006,d7                       ; right operand converted from integer?
	bne.w	optimise_next
	cmpi.w	#$8005,2(a2)                    ; result converted back to integer?
	bne.w	optimise_next
	cmpi.w	#$804a,(a2)                     ; $804a float add
	beq.s	.int_add
	cmpi.w	#$804b,(a2)                     ; $804b float subtract
	beq.s	.int_subtract
	cmpi.w	#$804b,(a2)                     ; tests $804b a second time, so the branch to .l07ee4 is never taken
	beq.s	.exchange_then_subtract
	bra.w	optimise_next
.exchange_then_subtract:
	move.w	#$8064,d1                       ; $8064 subtract after an exchange
	subq.l	#2,a2                           ; back to the $8004 pop
	movea.l	a2,a0
	move.w	#$801b,(a2)+                    ; $801b over the $8004 pop
	move.w	#$8083,(a2)+                    ; $8083 over the float operator
	move.w	d1,(a2)+                        ; $8064 over the $8005
	moveq	#2,d0
	bra.s	.delete_conversion
.int_add:
	move.w	#$8063,d1                       ; $8063 integer add
	bra.s	.write_int_operator
.int_subtract:
	move.w	#$8064,d1                       ; $8064 integer subtract
.write_int_operator:
	movea.l	a2,a0                           ; a0 = end of the bytes to delete
	move.w	#$801b,(a2)+                    ; $801b over the float operator
	move.w	d1,(a2)+                        ; integer operator over the $8005
	moveq	#4,d0                           ; delete the $8006 and $8004 before it
.delete_conversion:
	bsr.w	ir_delete_bytes
	move.w	#$8017,-(a4)                    ; $8017 integer push over the $8002
	movea.l	a4,a0                           ; make room before the push
	moveq	#2,d0
	bsr.w	ir_insert_bytes
	move.w	#$8005,(a0)                     ; $8005: left operand to integer first
	bra.w	optimise_restart
.push_float_constant:
	cmpi.w	#$8004,$a(a4)                   ; $8002 $8000 c $8004 op?
	bne.w	optimise_next
	move.w	$c(a4),d0                       ; d0 = the operator
	bsr.s	swapped_float_operator          ; swapped form of the operator
	beq.w	optimise_next                   ; none: leave it
	move.w	#$8001,-$2(a4)                  ; $8001 constant operand over the $8002
	move.l	2(a4),(a4)+                     ; move the constant down over the $8000
	move.l	2(a4),(a4)+
	move.w	d0,(a4)+                        ; swapped operator
	lea	4(a4),a0                        ; delete the four bytes left over
	moveq	#4,d0
	bsr.w	ir_delete_bytes
	bra.w	optimise_next
.push_float_variable:
	cmpi.w	#$8004,4(a4)                    ; $8002 $803e v $8004 op?
	bne.w	optimise_next
	move.w	6(a4),d0                        ; d0 = the operator
	bsr.s	swapped_float_operator          ; swapped form of the operator
	beq.w	optimise_next                   ; none: leave it
	move.w	#$805d,-$2(a4)                  ; $805d float variable operand over the $8002
	move.w	2(a4),(a4)+                     ; variable number
	move.w	d0,(a4)+                        ; swapped operator
	lea	4(a4),a0                        ; delete the four bytes left over
	moveq	#4,d0
	bsr.w	ir_delete_bytes
	bra.w	optimise_next

;------------------------------------------------------------------------------
; Gives the float operator to use when the two operands of a float binary operator change places.
; Entry d0 = float operator IR code. Exit d0 = operator for swapped operands, Z set (d0 = 0) when it cannot be swapped.
; Commutative ones are returned unchanged: $804a (+), $804d (*), $805a (=), $805b (<>), $805c, $812a, $812b.
; Pairs toggled: $804b/$804c (- / reversed -), $804e/$804f (/), $8050/$8051 (DIV), $8052/$8053 (MOD), $8054/$8055 (^),
; $8057/$8059 (>= / <=) and $8056/$8058 (> / <).
;------------------------------------------------------------------------------
swapped_float_operator:
	cmpi.w	#$804a,d0                       ; $804a + is commutative
	beq.w	.swapped_result
	cmpi.w	#$804b,d0                       ; $804b subtract
	bne.s	.check_reversed_subtract
.toggle_subtract:
	eori.w	#$7,d0                          ; $804b <-> $804c
	bra.w	.swapped_result
.check_reversed_subtract:
	cmpi.w	#$804c,d0                       ; $804c reversed subtract
	beq.s	.toggle_subtract
	cmpi.w	#$804d,d0                       ; $804d * is commutative
	beq.w	.swapped_result
	cmpi.w	#$804e,d0                       ; $804e reversed divide
	bne.s	.check_reversed_divide
.toggle_divide:
	eori.w	#$1,d0                          ; $804e <-> $804f
	bra.w	.swapped_result
.check_reversed_divide:
	cmpi.w	#$804f,d0                       ; $804f divide
	beq.s	.toggle_divide
	cmpi.w	#$8052,d0                       ; $8052 reversed MOD
	bne.s	.check_reversed_mod
.toggle_mod:
	eori.w	#$1,d0                          ; $8052 <-> $8053 (MOD)
	bra.s	.swapped_result
.check_reversed_mod:
	cmpi.w	#$8053,d0                       ; $8053 MOD
	beq.s	.toggle_mod
	cmpi.w	#$8050,d0                       ; $8050 reversed DIV
	bne.s	.check_reversed_div
.toggle_div:
	eori.w	#$1,d0                          ; $8050 <-> $8051 (DIV)
	bra.s	.swapped_result
.check_reversed_div:
	cmpi.w	#$8051,d0                       ; $8051 DIV
	beq.s	.toggle_div
	cmpi.w	#$8054,d0                       ; $8054 reversed ^
	bne.s	.check_reversed_power
.toggle_power:
	eori.w	#$1,d0                          ; $8054 <-> $8055 (^)
	bra.s	.swapped_result
.check_reversed_power:
	cmpi.w	#$8055,d0                       ; $8055 ^
	beq.s	.toggle_power
	cmpi.w	#$8057,d0                       ; $8057
	bne.s	.check_less_equal
.toggle_greater_equal:
	eori.w	#$e,d0                          ; $8057 (>=) <-> $8059 (<=)
	bra.s	.swapped_result
.check_less_equal:
	cmpi.w	#$8059,d0                       ; $8059
	beq.s	.toggle_greater_equal
	cmpi.w	#$8056,d0                       ; $8056
	bne.s	.check_less
.toggle_greater:
	eori.w	#$e,d0                          ; $8056 (>) <-> $8058 (<)
	bra.s	.swapped_result
.check_less:
	cmpi.w	#$8058,d0                       ; $8058
	beq.s	.toggle_greater
	cmpi.w	#$805a,d0                       ; $805a = is commutative
	beq.s	.swapped_result
	cmpi.w	#$805c,d0                       ; $805c == is commutative
	beq.s	.swapped_result
	cmpi.w	#$805b,d0                       ; $805b <> is commutative
	beq.s	.swapped_result
	cmpi.w	#$812a,d0                       ; $812a MIN is commutative
	beq.s	.swapped_result
	cmpi.w	#$812b,d0                       ; $812b MAX is commutative
	beq.s	.swapped_result
	moveq	#0,d0                           ; not swappable
.swapped_result:
	tst.w	d0                              ; Z set when not swappable
	rts

;------------------------------------------------------------------------------
; Optimiser handler for IR $8006 (convert the integer in d0 to float). a4 points after the $8006.
; Folds the conversion into what follows: $8006 $8005 (back to integer) and $8006 $80ef are deleted; $8045 -> $8029;
; library calls $3f PRNUM -> $40 PRINUM and $262 P0RNUM -> $261 P0RINUM; $80bd/$80be -> $80bf/$80c0 (float branch ->
; integer
; branch); $814a -> $8079, $814b -> $807a, $802c -> $8082, $802d -> $8006 $8078 (negate as integer first), $8200 ->
; $8006 $81fc;
; $8047/$8048 drop the $8006. $8001 (float constant operand) and $8002 (push float) go to the integer-operator rewrites
; below.
;------------------------------------------------------------------------------
optimise_int_to_float:
	move.w	(a4)+,d0                        ; IR word after the $8006
	cmpi.w	#$80ef,d0                       ; $80ef truth test: delete with the $8006
	beq.w	.delete_conversion_pair
	cmpi.w	#$8045,d0                       ; $8045 becomes $8029
	beq.w	.int_8045
	cmpi.w	#$3f,d0                         ; library routine $3f PRNUM
	beq.w	.print_integer
	cmpi.w	#$262,d0                        ; library routine $262 P0RNUM
	beq.w	.print_integer_channel
	cmpi.w	#$80bd,d0                       ; $80bd branch when false
	beq.w	.int_branch_false
	cmpi.w	#$80be,d0                       ; $80be branch when true
	beq.w	.int_branch_true
	cmpi.w	#$8047,d0                       ; $8047: drop the $8006
	beq.w	.drop_conversion
	cmpi.w	#$8048,d0                       ; $8048: drop the $8006
	beq.w	.drop_conversion
	cmpi.w	#$814a,d0                       ; $814a float EVEN
	beq.s	.int_even
	cmpi.w	#$814b,d0                       ; $814b float ODD
	beq.s	.int_odd
	cmpi.w	#$802c,d0                       ; $802c becomes $8082
	beq.s	.int_802c
	cmpi.w	#$802d,d0                       ; $802d float negate
	beq.s	.int_negate
	cmpi.w	#$8200,d0                       ; $8200 becomes $8006 $81fc
	beq.s	.int_8200
	cmpi.w	#$8005,d0                       ; $8005 back to integer: delete both
	beq.s	.delete_conversion_pair
	cmpi.w	#$8001,d0                       ; $8001 float constant operand
	beq.w	.int_then_float_constant
	cmpi.w	#$8002,d0                       ; $8002 push float
	beq.s	.int_then_float_push
	cmpi.w	#$8011,d0                       ; $8011 (float DOUBLE) then $8005: becomes $8012 (add.l d0,d0)
	bne.s	.no_rewrite
	cmpi.w	#$8005,(a4)
	bne.s	.no_rewrite
	move.w	#$8012,(a4)                     ; $8012 add.l d0,d0 over the $8005
	bra.w	ir_delete_four_bytes            ; delete $8006 $8011
.no_rewrite:
	bra.w	optimise_reread
.int_even:
	move.w	#$8079,-(a4)                    ; integer EVEN $8079 over the $8006
	bra.s	.delete_conversion_word
.int_odd:
	move.w	#$807a,-(a4)                    ; integer ODD $807a over the $8006
	bra.s	.delete_conversion_word
.int_802c:
	move.w	#$8082,-(a4)                    ; $8082 over the $8006
	bra.s	.delete_conversion_word
.int_negate:
	move.w	#$8006,-(a4)                    ; unary minus: negate as integer before converting
	move.w	#$8078,-(a4)                    ; IR $8078 integer negate over the $8006
	bra.w	optimise_restart
.int_8200:
	move.w	#$8006,-(a4)                    ; $8006 moved after it
	move.w	#$81fc,-(a4)                    ; $81fc over the $8006
	bra.w	optimise_restart
.int_branch_false:
	move.w	#$80bf,-(a4)                    ; integer branch when false $80bf over the $8006
	bra.s	.delete_conversion_word
.int_branch_true:
	move.w	#$80c0,-(a4)                    ; integer branch when true $80c0 over the $8006
	bra.s	.delete_conversion_word
.drop_conversion:
	subq.l	#2,a4                           ; drop the $8006
.delete_conversion_word:
	bra.w	ir_delete_two_bytes             ; delete the word after the new code
.print_integer:
	move.w	#$40,-(a4)                      ; lib $3f PRNUM -> $40 PRINUM (print integer)
	bra.s	.delete_conversion_word
.print_integer_channel:
	move.w	#$261,-(a4)                     ; lib $262 P0RNUM -> $261 P0RINUM
	bra.s	.delete_conversion_word
.int_8045:
	move.w	#$8029,-(a4)                    ; $8029 over the $8006
	bra.s	.delete_conversion_word
.delete_conversion_pair:
	bra.w	ir_delete_four_bytes            ; delete $8006 and the following word
	dc.w	$0000
.int_then_float_push:
	cmpi.b	#$6,option_percent_value        ; $8006 $8002: integer pushed as left operand of a float operator. Only
                                                ;   when byte var_121d0 < 6 (setting, meaning not worked out here); the
                                                ;   operator after the matching pop is turned into an integer operator
	bcc.w	optimise_retry_word
	bsr.w	measure_ir_operand              ; find the pop ($8004) that ends the right operand; a2 = after it, d7 =
                                                ;   IR word before it
	not.l	d0
	beq.w	optimise_retry_word
	cmpi.w	#$8006,d7                       ; right operand also an integer converted to float?
	beq.w	.int_operands_both_sides
	movem.w	(a2),d0-d1                      ; d0 = float operator, d1 = word after it
	cmpi.w	#$8005,d1
	bne.s	.check_compare
	cmpi.w	#$804a,d0                       ; followed by $8005 (result converted back to integer): +, -, reversed -
                                                ;   are exact
	beq.s	.to_int_add
	cmpi.w	#$804b,d0
	beq.s	.to_int_subtract
	cmpi.w	#$804c,d0
	beq.s	.to_int_reversed_subtract
.check_compare:
	cmpi.w	#$805a,d0                       ; $805a =
	beq.s	.to_int_equal
	cmpi.w	#$805b,d0                       ; $805b <>
	beq.s	.to_int_not_equal
	cmpi.w	#$8057,d0                       ; $8057
	beq.s	.to_int_807d
	cmpi.w	#$8056,d0                       ; $8056
	beq.s	.to_int_807e
	cmpi.w	#$8059,d0                       ; $8059
	beq.s	.to_int_807f
	cmpi.w	#$8058,d0                       ; $8058
	beq.s	.to_int_8080
	bra.w	.no_int_operator                ; anything else: no rewrite
.to_int_add:
	move.w	#$8063,d0                       ; $804a + -> $8063 add
.write_int_operator:
	move.w	d0,2(a2)
	move.w	#$801b,(a2)                     ; $801b = pop the pushed value and apply the operator
.convert_right_operand:
	move.w	#$8005,-(a2)
	bra.w	.insert_push
.to_int_subtract:
	move.w	#$8064,d0                       ; $804b - -> $8064 sub
	bra.s	.write_int_operator
.to_int_equal:
	move.w	#$807b,d0                       ; comparisons: $805a -> $807b (=)
	bra.s	.insert_pop_and_operator
.to_int_807d:
	move.w	#$807d,d0                       ; $8057 -> $807d (>=)
	bra.s	.insert_pop_and_operator
.to_int_807f:
	move.w	#$807f,d0                       ; $8059 -> $807f (<=)
	bra.s	.insert_pop_and_operator
.to_int_807e:
	move.w	#$807e,d0                       ; $8056 -> $807e (>)
	bra.s	.insert_pop_and_operator
.to_int_8080:
	move.w	#$8080,d0                       ; $8058 -> $8080 (<)
	bra.s	.insert_pop_and_operator
.to_int_not_equal:
	move.w	#$807c,d0                       ; $805b -> $807c (<>)
.insert_pop_and_operator:
	move.w	d0,(a2)                         ; integer operator over the float one
	movea.l	a2,a0                           ; make room for the pop
	moveq	#2,d0
	bsr.w	ir_insert_bytes
	move.w	#$801b,(a2)                     ; IR $801b: pop the left operand into d1
	bra.s	.convert_right_operand          ; $8005 over the $8004: right operand to integer
.to_int_reversed_subtract:
	move.w	#$8064,2(a2)                    ; $804c reversed - -> $8083 (exg d0,d1) then $8064
	move.w	#$8083,d0                       ; $8083 exchange, then $8064
	bra.s	.insert_pop_and_operator
.int_operands_both_sides:
	move.w	(a2),d4                         ; d4 = the float operator
	move.w	2(a2),d1                        ; d1 = the word after it
	cmpi.w	#$8005,d1                       ; result converted back to integer?
	beq.s	.check_divide
	cmpi.b	#$3,option_percent_value        ; '/' becomes integer division only when converted back to integer or
                                                ;   var_121d0 >= 3
	bcs.s	.check_operator
.check_divide:
	cmpi.w	#$804e,d4                       ; $804e reversed divide
	beq.w	.both_divide
	cmpi.w	#$804f,d4                       ; $804f divide
	beq.w	.both_reversed_divide
.check_operator:
	cmpi.w	#$804a,d4                       ; $804a add
	beq.s	.both_add
	cmpi.w	#$804b,d4                       ; $804b subtract
	beq.w	.both_subtract
	cmpi.w	#$804c,d4                       ; $804c reversed subtract
	beq.s	.both_reversed_subtract
	cmpi.w	#$804d,d4                       ; $804d multiply
	beq.w	.both_multiply
	cmpi.w	#$8050,d4                       ; $8050 reversed DIV
	beq.w	.both_divide
	cmpi.w	#$8051,d4                       ; $8051 DIV
	beq.w	.both_reversed_divide
	cmpi.w	#$8052,d4                       ; $8052 reversed MOD
	beq.w	.both_mod
	cmpi.w	#$8053,d4                       ; $8053 MOD
	beq.w	.both_reversed_mod
	cmpi.w	#$805a,d4                       ; $805a =
	beq.w	.both_equal
	cmpi.w	#$805b,d4                       ; $805b <>
	beq.w	.both_not_equal
	cmpi.w	#$8059,d4                       ; $8059
	beq.w	.both_807f
	cmpi.w	#$8058,d4                       ; $8058
	beq.w	.both_8080
	cmpi.w	#$8057,d4                       ; $8057
	beq.w	.both_807d
	cmpi.w	#$8056,d4                       ; $8056
	beq.s	.both_807e
.no_int_operator:
	bra.w	optimise_reread
.both_add:
	move.w	#$8063,d3                       ; + -> $8063
.write_int_operator_both:
	move.w	#$8006,(a2)                     ; $8006 over the operator: result back to float
	move.w	d3,-(a2)                        ; integer operator over the $8004 pop
	move.w	#$801b,-(a2)                    ; $801b over the right $8006
.insert_push:
	move.w	#$8017,-(a4)                    ; the $8002 becomes $8017 (push integer)
	bra.w	ir_delete_two_bytes             ; delete the $8006 before the push
.both_reversed_subtract:
	move.w	#$8064,d3                       ; reversed - -> $8083 $8064
.write_exchanged_operator:
	movea.l	a2,a0                           ; a0 = the operator
	moveq	#2,d0
	move.w	#$8006,(a0)                     ; $8006 over the float operator: result back to float
	bsr.w	ir_insert_bytes                 ; make room for the $8083
	move.w	d3,(a0)                         ; integer operator
	move.w	#$8083,-(a0)                    ; $8083 exchange operands
	move.w	#$801b,-(a0)                    ; $801b pop into d1
	bra.s	.insert_push
.both_subtract:
	move.w	#$8064,d3                       ; - -> $8064
	bra.s	.write_int_operator_both
.both_multiply:
	move.w	#$805e,d3                       ; * -> $805e
	bra.s	.write_int_operator_both
.both_divide:
	move.w	#$805f,d3                       ; / or DIV -> $805f
	bra.s	.write_int_operator_both
.both_reversed_divide:
	move.w	#$805f,d3                       ; reversed / or DIV -> $8083 $805f
	bra.s	.write_exchanged_operator
.both_mod:
	move.w	#$8065,d3                       ; MOD -> $8065
	bra.s	.write_int_operator_both
.both_reversed_mod:
	move.w	#$8065,d3                       ; reversed MOD -> $8083 $8065
	bra.s	.write_exchanged_operator
.both_equal:
	move.w	#$807b,d3
.write_int_compare:
	move.w	#$8017,-(a4)                    ; comparisons keep their result as an integer: no $8006 after
	move.w	d3,-(a2)                        ; integer compare over the $8004 pop
	move.w	#$801b,-(a2)                    ; $801b over the right $8006
	lea	6(a2),a0                        ; a0 = past the float compare
	moveq	#2,d0
	bsr.w	ir_delete_bytes                 ; delete the float compare
	bra.w	ir_delete_two_bytes             ; and the $8006 before the push
.both_not_equal:
	move.w	#$807c,d3
	bra.s	.write_int_compare
.both_807e:
	move.w	#$807e,d3                       ; $8056 -> $807e
	bra.s	.write_int_compare
.both_807d:
	move.w	#$807d,d3                       ; $8057 -> $807d
	bra.s	.write_int_compare
.both_8080:
	move.w	#$8080,d3                       ; $8058 -> $8080
	bra.s	.write_int_compare
.both_807f:
	move.w	#$807f,d3                       ; $8059 -> $807f
	bra.s	.write_int_compare
.int_then_float_constant:
	move.l	(a4)+,d0                        ; $8006 $8001 c op: d0/d1/d2 = float constant (mantissa long, mantissa
                                                ;   low word, exponent), d3 = operator
	move.w	(a4)+,d1
	move.w	(a4)+,d2
	move.w	(a4)+,d3
	cmpi.w	#$8002,(a4)                     ; followed by a float push: see .float_constant_then_push
	beq.w	.float_constant_then_push
	cmpi.w	#$8005,(a4)                     ; followed by $8005 (back to integer)?
	bne.s	.check_constant_compare
	cmpi.w	#$804a,d3                       ; $804a add
	beq.w	.constant_add
	cmpi.w	#$804b,d3                       ; $804b subtract
	beq.w	.constant_subtract
	cmpi.w	#$804c,d3                       ; $804c reversed subtract
	beq.w	.constant_reversed_subtract
	cmpi.w	#$804d,d3                       ; $804d multiply
	beq.w	.constant_multiply
	cmpi.w	#$804e,d3                       ; $804e reversed divide
	beq.w	.constant_divide
	cmpi.w	#$804f,d3                       ; $804f divide
	beq.w	.constant_reversed_divide
	cmpi.w	#$8050,d3                       ; $8050 reversed DIV
	beq.w	.constant_divide
	cmpi.w	#$8051,d3                       ; $8051 DIV
	beq.w	.constant_reversed_divide
	cmpi.w	#$8052,d3                       ; $8052 reversed MOD
	beq.w	.constant_mod
	cmpi.w	#$8053,d3                       ; $8053 MOD
	beq.w	.constant_reversed_mod
.check_constant_compare:
	cmpi.w	#$805a,d3                       ; $805a =
	beq.w	.constant_equal
	cmpi.w	#$805b,d3                       ; $805b <>
	beq.w	.constant_not_equal
	cmpi.w	#$8059,d3                       ; $8059
	beq.w	.constant_807f
	cmpi.w	#$8058,d3                       ; $8058
	beq.w	.constant_8080
	cmpi.w	#$8057,d3                       ; $8057
	beq.w	.constant_807d
	cmpi.w	#$8056,d3                       ; $8056
	beq.w	.constant_807e
.keep_float_constant:
	suba.w	#$c,a4                          ; no rewrite: step back over the 12 bytes read
	bra.w	optimise_next
.constant_add:
	bsr.w	float_to_int                    ; constant to integer (truncated)
	move.w	#$8063,(a4)                     ; $8063 integer add over the $8005
.write_int_constant:
	move.l	d0,-(a4)                        ; write $8008 c op: integer constant operand
	move.w	#$8008,-(a4)
	bra.w	ir_delete_eight_bytes
.constant_subtract:
	bsr.w	float_to_int
	move.w	#$8064,(a4)                     ; $8064 integer subtract over the $8005
	bra.s	.write_int_constant
.constant_reversed_subtract:
	bsr.w	float_to_int
	move.w	#$8064,(a4)                     ; $8064 integer subtract over the $8005
.write_exchanged_constant:
	move.w	#$8083,-(a4)                    ; $8083 exchange before it
	move.l	d0,-(a4)                        ; the integer constant
	move.w	#$8008,-(a4)                    ; IR $8008 constant as the second operand
	bra.w	ir_delete_six_bytes             ; delete the six bytes left over
.constant_multiply:
	bsr.w	float_constant_to_integer       ; the others need an exact integer constant
	bne.s	.keep_float_constant            ; not integral: keep the float operation
	move.w	#$805e,(a4)                     ; $805e integer multiply
	bra.s	.write_int_constant
.constant_divide:
	bsr.w	float_constant_to_integer
	bne.s	.keep_float_constant            ; not integral: keep the float operation
	move.w	#$805f,(a4)                     ; $805f integer divide
	bra.s	.write_int_constant
.constant_reversed_divide:
	bsr.w	float_constant_to_integer
	bne.s	.keep_float_constant            ; not integral: keep the float operation
	move.w	#$805f,(a4)                     ; $805f, with $8083 before it
	bra.s	.write_exchanged_constant
.constant_mod:
	bsr.w	float_constant_to_integer
	bne.s	.keep_float_constant            ; not integral: keep the float operation
	move.w	#$8065,(a4)                     ; $8065 integer MOD
	bra.s	.write_int_constant
.constant_reversed_mod:
	bsr.w	float_constant_to_integer
	bne.s	.keep_float_constant            ; not integral: keep the float operation
	move.w	#$8065,(a4)                     ; $8065, with $8083 before it
	bra.s	.write_exchanged_constant
.constant_equal:
	bsr.w	float_constant_to_integer       ; comparisons: integral constant -> integer compare
	bne.s	.equal_never
	move.w	#$807b,-(a4)                    ; $807b integer = over the float operator
.write_compare_constant:
	move.l	d0,-(a4)                        ; the integer constant
	move.w	#$8008,-(a4)                    ; IR $8008 constant as the second operand
	bra.w	ir_delete_six_bytes             ; delete the six bytes left over
.equal_never:
	moveq	#0,d0                           ; not integral: x = c is false, result constant 0
.write_truth_constant:
	move.l	d0,-(a4)                        ; $8007 = integer constant
	move.w	#$8007,-(a4)
	bra.w	ir_delete_eight_bytes
.constant_not_equal:
	bsr.w	float_constant_to_integer
	bne.s	.not_equal_always
	move.w	#$807c,-(a4)                    ; $807c integer <>
	bra.s	.write_compare_constant
.not_equal_always:
	moveq	#-1,d0                          ; not integral: x <> c is true
	bra.s	.write_truth_constant
.constant_807f:
	bsr.w	float_constant_to_integer
	bne.s	.adjust_for_8080
	move.w	#$807f,-(a4)                    ; $807f
	bra.s	.write_compare_constant
.constant_8080:
	bsr.w	float_constant_to_integer
	bne.s	.adjust_for_8080
.write_8080:
	move.w	#$8080,-(a4)                    ; $8080
	bra.s	.write_compare_constant
.adjust_for_8080:
	tst.l	d2                              ; not integral: compare against the integer below/above c
	bpl.s	.write_8080                     ; constant positive: keep the truncated value
	subq.l	#1,d0                           ; negative: one lower
	bra.s	.write_8080
.constant_807d:
	bsr.w	float_constant_to_integer
	bne.s	.adjust_for_807e
	move.w	#$807d,-(a4)                    ; $807d
	bra.s	.write_compare_constant
.constant_807e:
	bsr.w	float_constant_to_integer
	bne.s	.adjust_for_807e
.write_807e:
	move.w	#$807e,-(a4)                    ; $807e
	bra.s	.write_compare_constant
.adjust_for_807e:
	tst.l	d2                              ; sign of the constant
	bmi.s	.write_807e                     ; negative: keep the truncated value
	subq.l	#1,d0                           ; positive: one lower
	bra.s	.write_807e
.float_constant_then_push:
	cmpi.w	#$804a,d3                       ; $8006 $8001 c op $8002: same rewrite when the result is pushed again
	beq.s	.push_add
	cmpi.w	#$804b,d3                       ; $804b subtract
	beq.s	.push_subtract
	cmpi.w	#$804c,d3                       ; $804c reversed subtract
	beq.s	.push_reversed_subtract
	cmpi.w	#$804d,d3                       ; $804d multiply
	beq.s	.push_multiply
	cmpi.w	#$8050,d3                       ; $8050 reversed DIV
	beq.s	.push_div
	cmpi.w	#$8051,d3                       ; $8051 DIV
	beq.s	.push_reversed_div
.no_push_rewrite:
	suba.w	#$c,a4                          ; no rewrite: back over the 12 bytes read
	bra.w	optimise_next
.push_add:
	move.w	#$8063,d3                       ; $8063 integer add
	bra.s	.no_exchange
.push_subtract:
	move.w	#$8064,d3                       ; $8064 integer subtract
	bra.s	.no_exchange
.push_multiply:
	move.w	#$805e,d3                       ; $805e integer multiply
	bra.s	.no_exchange
.push_div:
	move.w	#$805f,d3                       ; $805f integer divide
	bra.s	.no_exchange
.push_reversed_div:
	move.w	#$805f,d3                       ; $805f, with $8083 before it
	bra.s	.exchange_needed
.push_reversed_subtract:
	move.w	#$8064,d3                       ; $8064, with $8083 before it
.exchange_needed:
	move.w	#$8083,d4                       ; d4 = $8083 exchange
	bra.s	.test_integral
.no_exchange:
	moveq	#0,d4                           ; d4 = 0: no exchange
.test_integral:
	movem.w	d3-d4,-(sp)                     ; keep the operator across the call
	bsr.w	float_constant_to_integer       ; Z: the constant is an exact integer in d0
	movem.w	(sp)+,d3-d4
	bne.s	.no_push_rewrite                ; not integral: no rewrite
	movem.l	d0/d3-d4,-(sp)                  ; measure the following float operand
	addq.l	#2,a4                           ; past the $8002
	bsr.w	measure_ir_operand
	movem.l	(sp)+,d1/d3-d4                  ; d1 = the integer constant
	not.l	d0                              ; -1: consumer not found
	beq.s	.push_not_rewritten
	cmpi.w	#$8006,d7                       ; right operand converted from integer?
	bne.s	.push_not_rewritten
	move.w	(a2),d5                         ; d5 = the operator after the pop
	cmpi.w	#$805a,d5                       ; $805a =
	beq.s	.push_equal
	cmpi.w	#$805b,d5                       ; $805b <>
	beq.s	.push_not_equal
	cmpi.w	#$8057,d5                       ; $8057
	beq.s	.push_807d
	cmpi.w	#$8056,d5                       ; $8056
	beq.s	.push_807e
	cmpi.w	#$8059,d5                       ; $8059
	beq.s	.push_807f
	cmpi.w	#$8058,d5                       ; $8058
	beq.s	.push_8080
.push_not_rewritten:
	subq.l	#2,a4                           ; back to the $8002
	bra.w	.no_push_rewrite
.push_equal:
	move.w	#$807b,d5                       ; = -> $807b
	bra.s	.write_push_compare
.push_not_equal:
	move.w	#$807c,d5                       ; <> -> $807c
	bra.s	.write_push_compare
.push_807d:
	move.w	#$807d,d5                       ; $8057 -> $807d
	bra.s	.write_push_compare
.push_807e:
	move.w	#$807e,d5                       ; $8056 -> $807e
	bra.s	.write_push_compare
.push_807f:
	move.w	#$807f,d5                       ; $8059 -> $807f
	bra.s	.write_push_compare
.push_8080:
	move.w	#$8080,d5                       ; $8058 -> $8080
.write_push_compare:
	move.w	d5,(a2)                         ; comparison with an integer right operand: use the integer compare
	move.w	#$801b,-(a2)                    ; $801b over the $8004 pop
	move.w	#$8017,-(a4)                    ; $8017 integer push over the $8002
	move.w	d3,-(a4)                        ; integer operator before it
	move.w	d4,-(a4)                        ; $8083 or 0 before that
	bne.s	.write_with_exchange            ; with $8083: keep it
	addq.l	#2,a4                           ; no exchange: drop the 0 word
	move.l	d1,-(a4)                        ; the integer constant
	move.w	#$8008,-(a4)                    ; IR $8008 constant as the second operand
	movea.l	a2,a0                           ; a0 = the $801b
	moveq	#2,d0
	bsr.w	ir_delete_bytes                 ; delete the $8006 before it
	bra.w	ir_delete_six_bytes             ; delete the six bytes left over
.write_with_exchange:
	move.l	d1,-(a4)                        ; the integer constant
	move.w	#$8008,-(a4)                    ; IR $8008 constant as the second operand
	movea.l	a2,a0                           ; a0 = the $801b
	moveq	#2,d0
	bsr.w	ir_delete_bytes                 ; delete the $8006 before it
	bra.w	ir_delete_four_bytes            ; delete the four bytes left over

;------------------------------------------------------------------------------
; Tests whether the float constant d0 (mantissa long) / d1 (mantissa low word) / d2 (exponent) is an exact integer.
; Exit Z: d0 = the integer (also Z for 0.0, d2 = 0). NE: not integral; d3/d4/d5 keep the original constant.
; Uses float_to_int and int_to_float and compares the round trip.
;------------------------------------------------------------------------------
float_constant_to_integer:
	tst.w	d2                              ; exponent word 0 = the constant is 0.0
	bne.s	.not_zero                       ; non-zero: convert and compare
	moveq	#0,d0                           ; 0.0 is the integer 0 (Z set)
	rts
.not_zero:
	move.l	d0,d3                           ; keep the original constant in d3/d4/d5
	move.w	d1,d4
	move.w	d2,d5
	bsr.w	float_to_int                    ; float -> integer
	move.l	d0,d6                           ; d6 = the integer value
	bsr.w	int_to_float                    ; and back to float
	cmp.l	d0,d3                           ; round trip gives the same mantissa long?
	bne.s	.done
	cmp.w	d1,d4                           ; same mantissa low word?
	bne.s	.done
	cmp.w	d2,d5                           ; same exponent?
	bne.s	.done
	move.l	d6,d0                           ; same value: return the integer with Z set
	moveq	#0,d6                           ; Z set: the constant was integral
.done:
	rts                                     ; NE when the round trip differed

;------------------------------------------------------------------------------
; Optimiser case for '$803f v $8084 w op': two long variables (v loaded, w the operand). d3 = v, a4 points at op.
; op $8083 (exg) is removed by swapping v and w. v = w: v+v -> $8012, v-v -> $8007 0, v*v -> $8014, v=v/v>=v/v<=v -> -1,
; others 0.
; Followed by '$8042 x' (store long) with x = v or w: becomes '$803f other $80dc+n x' (n: + 0, - 1, * 2, / 3).
; v+w / v-w followed by a push ($8017) and later popped by X ($801b-$8023 into d1-a1): the push goes and the pop
; becomes X+$69 v (load v into X's register) and X+$1bd w / X+$1cf w (add / subtract long var w on that register).
;------------------------------------------------------------------------------
optimise_long_var_pair:
	move.w	(a4)+,d1                        ; d1 = w
	move.w	(a4),d0                         ; d0 = operator
	cmpi.w	#$8083,d0                       ; $8083: exchange the two operands
	beq.w	.swap_operands
	cmp.w	d1,d3                           ; same variable on both sides?
	beq.s	.same_variable
	cmpi.w	#$8042,2(a4)                    ; next is a long store $8042?
	bne.s	.no_store_rewrite
	cmp.w	4(a4),d3                        ; store target x = v?
	beq.s	.store_into_v
	cmp.w	4(a4),d1                        ; x = w? (only commutative ops then)
	bne.s	.no_store_rewrite
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_into_w
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_into_w
	bra.s	.no_store_rewrite               ; other ops cannot store into w
.store_into_v:
	cmpi.w	#$805e,d0
	beq.s	.mul_into_v                     ; v = v * w
	cmpi.w	#$8063,d0
	beq.s	.add_into_v                     ; v = v + w
	cmpi.w	#$8064,d0
	beq.s	.sub_into_v                     ; v = v - w
	cmpi.w	#$805f,d0
	beq.s	.div_into_v                     ; v = v / w
.no_store_rewrite:
	bra.w	.fold_pair_into_push
.mul_into_w:
	move.w	#$80de,d0                       ; w = w * v -> $80de (multiply into w)
	bra.s	.write_op_assign
.add_into_w:
	move.w	#$80dc,d0                       ; w = w + v -> $80dc (add into w)
	bra.s	.write_op_assign
.div_into_v:
	move.w	#$80df,d0                       ; v = v / w -> $80df (divide into v)
	bra.s	.load_w_first
.sub_into_v:
	move.w	#$80dd,d0                       ; v = v - w -> $80dd (subtract from v)
	bra.s	.load_w_first
.add_into_v:
	move.w	#$80dc,d0                       ; v = v + w -> $80dc
	bra.s	.load_w_first
.mul_into_v:
	move.w	#$80de,d0                       ; v = v * w -> $80de
.load_w_first:
	move.w	d1,-$6(a4)                      ; v = v op w: put w first, store into v
.write_op_assign:
	move.w	d0,-$4(a4)                      ; op-assign code over the old $8084
	move.w	4(a4),-(a4)                     ; store target over the old w: $803f src $80dx dst
	addq.l	#8,a4                           ; a4 past the $8042 x
	bra.w	ir_delete_six_bytes             ; drop op $8042 x
.same_variable:
	cmpi.w	#$8063,d0                       ; v op v with $8063 +
	beq.s	.double_value
	cmpi.w	#$8064,d0                       ; $8064 -: always 0
	beq.s	.result_false
	cmpi.w	#$805e,d0                       ; $805e *: square
	beq.s	.square_value
	cmpi.w	#$807b,d0                       ; $807b =: true
	beq.s	.result_true
	cmpi.w	#$807c,d0                       ; $807c <>: false
	beq.s	.result_false
	cmpi.w	#$807d,d0                       ; $807d >=: true
	beq.s	.result_true
	cmpi.w	#$807f,d0                       ; $807f <=: true
	beq.s	.result_true
	cmpi.w	#$807e,d0                       ; $807e >: false
	beq.s	.result_false
	cmpi.w	#$8080,d0                       ; $8080 <: false
	beq.s	.result_false
	bra.s	.fold_pair_into_push            ; anything else: try the push fold
.double_value:
	move.w	#$8012,(a4)                     ; v + v -> $8012 (add.l d0,d0)
	bra.w	ir_delete_four_bytes            ; drop $8084 v: leaves $803f v $8012
.result_true:
	moveq	#-1,d0                          ; true: -1
	bra.s	.write_constant_result
.result_false:
	moveq	#0,d0                           ; false: 0
.write_constant_result:
	addq.l	#2,a4                           ; a4 past the operator
	move.l	d0,-(a4)                        ; constant over w and op
	move.w	#$8007,-(a4)                    ; $8007 integer constant over the $8084
	bra.w	ir_delete_four_bytes            ; drop $803f v: leaves $8007 c
.swap_operands:
	move.w	d1,-$6(a4)                      ; $8083: swap the two variables instead
	move.w	d3,-(a4)                        ; v into the second operand slot
	addq.l	#4,a4                           ; a4 past the $8083
	bra.w	ir_delete_two_bytes             ; drop the $8083
.square_value:
	move.w	#$8014,(a4)                     ; v * v -> $8014
	bra.w	ir_delete_four_bytes            ; drop $8084 v: leaves $803f v $8014
.fold_pair_into_push:
	cmpi.w	#$8017,2(a4)                    ; add/sub followed by a push?
	bne.s	.no_fold
	move.w	(a4),d0                         ; d0 = operator
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.add_or_sub_pushed
	cmpi.w	#$8063,d0                       ; $8063 add
	bne.s	.no_fold
.add_or_sub_pushed:
	addq.l	#4,a4                           ; a4 past the $8017
	bsr.w	measure_ir_operand              ; find the pop of the pushed value; a2 = after it
	subq.l	#4,a4                           ; a4 back at the operator
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.s	.no_fold                        ; give up
	move.w	-$2(a2),-(sp)                   ; save X, the popping IR code
	move.w	(a4),-(sp)                      ; save the operator
	move.w	-(a4),-(sp)                     ; save w (a4 now at w)
	move.w	-$4(a4),-(sp)                   ; save v
	lea	6(a4),a0                        ; a0 = past the $8017
	moveq	#12,d0                          ; delete '$803f v $8084 w op $8017' (12 bytes)
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word X
	moveq	#6,d0                           ; make 6 bytes of room at X
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d1                        ; d1 = v
	move.w	(sp)+,d2                        ; d2 = w
	move.w	(sp)+,d4                        ; d4 = operator
	move.w	(sp)+,d0                        ; d0 = X
	addi.w	#$69,d0                         ; X+$69: load v straight into X's register ($8084-$808c)
	move.w	d0,(a2)+
	move.w	d1,(a2)+
	addi.w	#$154,d0                        ; X+$1bd: add long var w to it ($81d8-$81e0)
	cmpi.w	#$8063,d4                       ; add?
	beq.s	.write_pop_operand
	addi.w	#$12,d0                         ; subtract: X+$1cf ($81ea-$81f2 sub long var)
.write_pop_operand:
	move.w	d0,(a2)+
	move.w	d2,(a2)+
	bra.w	optimise_restart                ; pass changed: start again
.no_fold:
	subq.l	#4,a4                           ; a4 back at the start of '$803f v'
	bra.w	optimise_next                   ; nothing done: continue the scan

;------------------------------------------------------------------------------
; Optimiser handler for IR $803f v (load long variable v into d0). a4 points at v.
; By the following IR: $8084 -> optimise_long_var_pair; $8017 -> fuse_pushed_long_var; $808d/$8099 ->
; long_var_op_word_var /
; long_var_op_byte_var; $8008 c op -> constant cases below; $80a3-$80aa (PEEK forms on the address in d0): the $803f
; becomes $808b (load v into a0) and the code + 8 ($80ab-$80b2, the same PEEKs through a0).
;------------------------------------------------------------------------------
optimise_load_long_var:
	move.w	(a4)+,d3                        ; d3 = variable number
	move.w	(a4)+,d1                        ; d1 = next IR word
	cmpi.w	#$8084,d1                       ; $8084: a long variable as the operand
	beq.w	optimise_long_var_pair
	cmpi.w	#$8017,d1                       ; $8017: push long
	beq.w	fuse_pushed_long_var
	cmpi.w	#$8008,d1                       ; $8008: integer constant as the operand
	beq.s	.long_var_constant
	cmpi.w	#$808d,d1                       ; $808d: a word variable as the operand
	beq.w	long_var_op_word_var
	cmpi.w	#$8099,d1                       ; $8099: a byte variable as the operand
	beq.w	long_var_op_byte_var
	subi.w	#$80a3,d1                       ; $80a3-$80aa: peek with the address in d0?
	cmpi.w	#$7,d1                          ; one of the 8 PEEK codes?
	bhi.s	.no_rewrite
	move.w	#$808b,-$6(a4)                  ; $808b: load v into a0 instead
	addq.w	#8,-$2(a4)                      ; peek code + 8: the (a0) forms $80ab-$80b2
	sf	optimise_no_change_flag         ; mark the pass as changed
.no_rewrite:
	bra.w	optimise_reread
.long_var_constant:
	movem.w	4(a4),d0/d2/d4                  ; $803f v $8008 c op: d0 = op, d2/d4 = the next IR words
	cmpi.w	#$8042,d2                       ; followed by a store into the same long variable?
	bne.s	.not_constant_op_assign
	cmp.w	d4,d3                           ; store target is v itself?
	bne.s	.not_constant_op_assign
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_constant_into_var
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.sub_constant_into_var
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_constant_into_var
	cmpi.w	#$805f,d0                       ; $805f divide
	bne.s	.not_constant_op_assign
	move.w	#$80df,d0                       ; v = v / c -> $80df
	bra.s	.write_constant_op_assign
.add_constant_into_var:
	move.w	#$80dc,d0                       ; v = v + c -> $80dc
.write_constant_op_assign:
	move.w	d0,6(a4)                        ; result: $8007 c $80dx v
	move.l	(a4),2(a4)                      ; constant over the operator and $8042
	move.w	#$8007,(a4)                     ; $8007 integer constant over the old c
	bra.w	ir_delete_six_bytes             ; drop '$803f v $8008': leaves $8007 c $80dx v
.sub_constant_into_var:
	move.w	#$80dd,d0                       ; v = v - c -> $80dd
	bra.s	.write_constant_op_assign
.mul_constant_into_var:
	move.w	#$80de,d0                       ; v = v * c -> $80de
	bra.s	.write_constant_op_assign
.not_constant_op_assign:
	cmpi.w	#$8064,d0                       ; subtract?
	bne.s	.try_fold_add_into_pop
	neg.l	(a4)                            ; v - c -> v + (-c)
	move.w	#$8063,d0
	move.w	d0,4(a4)                        ; operator slot becomes the add
.try_fold_add_into_pop:
	cmpi.w	#$8063,d0                       ; only an add can be folded into the pop
	bne.s	optimise_var_no_change          ; no: leave it
	cmpi.w	#$8017,d2                       ; v + c pushed ($8017)?
	bne.s	optimise_var_no_change
	addq.l	#8,a4                           ; a4 past the $8017
	bsr.w	measure_ir_operand              ; measure the pushed operand; a2 = after the pop
	subq.l	#8,a4                           ; a4 back at c
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.s	optimise_var_no_change
	move.w	-$2(a2),-(sp)                   ; save X, the popping IR code
	move.l	(a4),-(sp)                      ; save c
	move.w	-$4(a4),-(sp)                   ; save v
	lea	8(a4),a0                        ; a0 = past the $8017
	moveq	#14,d0                          ; delete '$803f v $8008 c $8063 $8017' (14 bytes)
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word X
	moveq	#8,d0                           ; make 8 bytes of room at X
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d1                        ; d1 = v
	move.l	(sp)+,d2                        ; d2 = c
	move.w	(sp)+,d0                        ; d0 = X
	move.b	d2,d3                           ; constant fits a byte?
	ext.w	d3
	ext.l	d3
	cmp.l	d2,d3
	beq.s	.pop_byte_constant
	addi.w	#$69,d0                         ; long constant: load v into X's register, add c
	move.w	d0,(a2)+                        ; X+$69: load v straight into X's register
	move.w	d1,(a2)+
	addi.w	#$14b,d0                        ; X+$1b4: add the constant to it ($81cf-$81d7)
	move.w	d0,(a2)+
	move.l	d2,(a2)+                        ; the constant (long)
	bra.w	optimise_restart                ; pass changed: start again
.pop_byte_constant:
	addi.w	#$ffed,d0                       ; byte constant: load c into the register, add v
	move.w	d0,(a2)+                        ; X-$13: load c into X's register ($8008-$8010)
	move.l	d2,(a2)+
	addi.w	#$1d0,d0                        ; X+$1bd: add long var v to it
	move.w	d0,(a2)+
	move.w	d1,(a2)+
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Shared exit of the variable handlers: no rewrite, continue the optimiser scan at the current IR word.
;------------------------------------------------------------------------------
optimise_var_no_change:
	bra.w	optimise_reread

;------------------------------------------------------------------------------
; '$803f v $808d w op $8042 v' case: the second variable is a word variable (d7 = $8040 load word).
;------------------------------------------------------------------------------
long_var_op_word_var:
	move.w	#$8040,d7
	bra.s	long_var_op_other_var

;------------------------------------------------------------------------------
; '$803f v $8099 w op $8042 v' case: the second variable is a byte variable (d7 = $803d load byte).
;------------------------------------------------------------------------------
long_var_op_byte_var:
	move.w	#$803d,d7

;------------------------------------------------------------------------------
; Rewrites 'load long v, op with variable w, store into v' into 'load w (d7), $80dc..$80df v' (v = v op w).
; Entry d3 = v, d7 = load code for w, a4 points at w. Operators $8063/$814c +, $8064/$814d -, $805e/$814e *, $805f /.
;------------------------------------------------------------------------------
long_var_op_other_var:
	movem.w	2(a4),d0/d2/d4                  ; d0 = op, d2 = the next IR word, d4 = its variable
	cmpi.w	#$8042,d2                       ; store into a long variable...
	bne.s	optimise_var_no_change
	cmp.w	d4,d3                           ; ...the same one
	bne.s	optimise_var_no_change
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_other_into_var
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.sub_other_into_var
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_other_into_var
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.add_other_into_var
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.sub_other_into_var
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.mul_other_into_var
	cmpi.w	#$805f,d0                       ; $805f divide
	bne.s	optimise_var_no_change
	move.w	#$80df,d0                       ; v = v / w -> $80df
	bra.s	.write_other_op_assign
.add_other_into_var:
	move.w	#$80dc,d0                       ; v = v + w -> $80dc
.write_other_op_assign:
	move.w	d0,4(a4)                        ; write: d7 w $80dx v
	move.w	(a4),2(a4)                      ; w over the operator
	move.w	d7,(a4)                         ; load code for w over the $808d/$8099
	bra.w	ir_delete_six_bytes             ; drop '$803f v' + the old store: d7 w $80dx v
.sub_other_into_var:
	move.w	#$80dd,d0                       ; v = v - w -> $80dd
	bra.s	.write_other_op_assign
.mul_other_into_var:
	move.w	#$80de,d0                       ; v = v * w -> $80de
	bra.s	.write_other_op_assign

;------------------------------------------------------------------------------
; '$803f v $8017 <expr> X': a long variable pushed and popped later by IR code X ($801b-$8023, into d1-a1).
; The push is removed and the pop becomes X+$69 v ($8084-$808c: load the variable straight into that register).
;------------------------------------------------------------------------------
fuse_pushed_long_var:
	bsr.w	measure_ir_operand              ; find the pop; a2 = just after it
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.w	optimise_retry_word             ; give up
	move.w	-$2(a2),-(sp)                   ; X = the popping IR code
	movea.l	a4,a0                           ; delete '$803f v $8017'
	moveq	#6,d0
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word X
	moveq	#2,d0                           ; make room for the variable number
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d0                        ; d0 = X
	addi.w	#$69,d0                         ; X+$69: load v straight into X's register
	move.w	d0,(a2)+
	move.w	d3,(a2)+                        ; the variable number
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Word-variable version of optimise_long_var_pair: '$8040 v $808d w op' with stores $8043 and op-assign codes
; $80e0-$80e3; the word operators $814c-$814e count as well. Folded pushes use X+$72 / X+$1c6/$1d8.
;------------------------------------------------------------------------------
optimise_word_var_pair:
	move.w	(a4)+,d1                        ; d1 = w
	move.w	(a4),d0                         ; d0 = operator
	cmpi.w	#$8083,d0                       ; $8083: exchange the two operands
	beq.w	.swap_word_operands
	cmp.w	d1,d3                           ; same variable on both sides?
	beq.w	.same_word_variable
	cmpi.w	#$8043,2(a4)                    ; next is a word store $8043?
	bne.s	.no_word_store_rewrite
	cmp.w	4(a4),d3                        ; store target x = v?
	beq.s	.store_into_word_v
	cmp.w	4(a4),d1                        ; x = w? (only commutative ops then)
	bne.s	.no_word_store_rewrite
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_into_word_w
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_into_word_w
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.mul_into_word_w
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.add_into_word_w
	bra.s	.no_word_store_rewrite
.store_into_word_v:
	cmpi.w	#$805e,d0                       ; v = v * w
	beq.s	.mul_into_word_v
	cmpi.w	#$8063,d0                       ; v = v + w
	beq.s	.add_into_word_v
	cmpi.w	#$8064,d0                       ; v = v - w
	beq.s	.sub_into_word_v
	cmpi.w	#$814e,d0                       ; v = v * w (word multiply)
	beq.s	.mul_into_word_v
	cmpi.w	#$814c,d0                       ; v = v + w (word add)
	beq.s	.add_into_word_v
	cmpi.w	#$814d,d0                       ; v = v - w (word subtract)
	beq.s	.sub_into_word_v
	cmpi.w	#$805f,d0                       ; v = v / w
	beq.s	.div_into_word_v
.no_word_store_rewrite:
	bra.w	.fold_word_pair_into_push       ; no store rewrite: try the push fold
.mul_into_word_w:
	move.w	#$80e2,d0                       ; w = w * v -> $80e2
	bra.s	.write_word_op_assign
.add_into_word_w:
	move.w	#$80e0,d0                       ; w = w + v -> $80e0
	bra.s	.write_word_op_assign
.div_into_word_v:
	move.w	#$80e3,d0                       ; v = v / w -> $80e3
	bra.s	.load_word_w_first
.sub_into_word_v:
	move.w	#$80e1,d0                       ; v = v - w -> $80e1
	bra.s	.load_word_w_first
.add_into_word_v:
	move.w	#$80e0,d0                       ; v = v + w -> $80e0
	bra.s	.load_word_w_first
.mul_into_word_v:
	move.w	#$80e2,d0                       ; v = v * w -> $80e2
.load_word_w_first:
	move.w	d1,-$6(a4)                      ; v = v op w: put w first, store into v
.write_word_op_assign:
	move.w	d0,-$4(a4)                      ; op-assign code over the old $808d
	move.w	4(a4),-(a4)                     ; store target over the old w
	addq.l	#8,a4                           ; a4 past the $8043 x
	bra.w	ir_delete_six_bytes             ; drop op $8043 x
.same_word_variable:
	cmpi.w	#$8063,d0                       ; v op v with $8063 +
	beq.s	.double_word_value
	cmpi.w	#$8064,d0                       ; $8064 -: always 0
	beq.s	.word_result_false
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.double_word_value
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.word_result_false
	cmpi.w	#$807b,d0                       ; $807b =: true
	beq.s	.word_result_true
	cmpi.w	#$807c,d0                       ; $807c <>: false
	beq.s	.word_result_false
	cmpi.w	#$807d,d0                       ; $807d >=: true
	beq.s	.word_result_true
	cmpi.w	#$807f,d0                       ; $807f <=: true
	beq.s	.word_result_true
	cmpi.w	#$807e,d0                       ; $807e >: false
	beq.s	.word_result_false
	cmpi.w	#$8080,d0                       ; $8080 <: false
	beq.s	.word_result_false
	bra.s	.fold_word_pair_into_push       ; anything else: try the push fold
.double_word_value:
	move.w	#$8012,(a4)                     ; v + v -> $8012
	bra.w	ir_delete_four_bytes            ; drop $808d v: leaves $8040 v $8012
.word_result_true:
	moveq	#-1,d0                          ; true: -1
	bra.s	.write_word_constant_result
.word_result_false:
	moveq	#0,d0                           ; false: 0
.write_word_constant_result:
	addq.l	#2,a4                           ; a4 past the operator
	move.l	d0,-(a4)                        ; constant over w and op
	move.w	#$8007,-(a4)                    ; $8007 integer constant over the $808d
	bra.w	ir_delete_four_bytes            ; drop $8040 v: leaves $8007 c
.swap_word_operands:
	move.w	d1,-$6(a4)                      ; $8083: swap the variables
	move.w	d3,-(a4)
	addq.l	#4,a4                           ; a4 past the $8083
	bra.w	ir_delete_two_bytes             ; drop the $8083
.fold_word_pair_into_push:
	cmpi.w	#$8017,2(a4)                    ; add/sub followed by a push?
	bne.s	.no_word_fold
	move.w	(a4),d0                         ; d0 = operator
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.word_add_or_sub_pushed
	cmpi.w	#$8063,d0                       ; $8063 add
	bne.s	.no_word_fold
.word_add_or_sub_pushed:
	addq.l	#4,a4                           ; a4 past the $8017
	bsr.w	measure_ir_operand              ; find the pop of the pushed value; a2 = after it
	subq.l	#4,a4                           ; a4 back at the operator
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.s	.no_word_fold
	move.w	-$2(a2),-(sp)                   ; save X, the popping IR code
	move.w	(a4),-(sp)                      ; save the operator
	move.w	-(a4),-(sp)                     ; save w (a4 now at w)
	move.w	-$4(a4),-(sp)                   ; save v
	lea	6(a4),a0                        ; a0 = past the $8017
	moveq	#12,d0                          ; delete '$8040 v $808d w op $8017' (12 bytes)
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word X
	moveq	#6,d0                           ; make 6 bytes of room at X
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d1                        ; d1 = v
	move.w	(sp)+,d2                        ; d2 = w
	move.w	(sp)+,d4                        ; d4 = operator
	move.w	(sp)+,d0                        ; d0 = X
	addi.w	#$72,d0                         ; X+$72: load word var v into X's register ($808d-)
	move.w	d0,(a2)+
	move.w	d1,(a2)+
	addi.w	#$154,d0                        ; X+$1c6: add word var w to it ($81e1-$81e9)
	cmpi.w	#$8063,d4                       ; add?
	beq.s	.write_word_pop_operand
	addi.w	#$12,d0                         ; subtract: X+$1d8 ($81f3-$81fb sub word var)
.write_word_pop_operand:
	move.w	d0,(a2)+
	move.w	d2,(a2)+
	bra.w	optimise_restart                ; pass changed: start again
.no_word_fold:
	subq.l	#4,a4                           ; a4 back at the start of '$8040 v'
	bra.w	optimise_next                   ; nothing done: continue the scan

;------------------------------------------------------------------------------
; Optimiser handler for IR $8040 v (load word variable, sign-extended into d0). a4 points at v.
; $802f after it is deleted (already a word). $808d -> optimise_word_var_pair; $8017 -> fuse with X+$72; $8084/$8099 ->
; other
; variable op-assign; $8008 c op: store back into v -> $80e0-$80e3; a compare with a constant outside the word range
; gives
; a constant result; v - c becomes v + (-c).
;------------------------------------------------------------------------------
optimise_load_word_var:
	move.w	(a4)+,d3                        ; d3 = variable number
	move.w	(a4)+,d1                        ; d1 = next IR word
	cmpi.w	#$802f,d1                       ; $802f ext.w: redundant after a word load
	beq.w	ir_delete_two_bytes             ; $802f (word cast) is redundant after a word load
	cmpi.w	#$808d,d1                       ; $808d: a word variable as the operand
	beq.w	optimise_word_var_pair
	cmpi.w	#$8017,d1                       ; $8017: push long
	beq.w	.fuse_pushed_word_var
	cmpi.w	#$8008,d1                       ; $8008: integer constant as the operand
	beq.s	.word_var_constant
	cmpi.w	#$8084,d1                       ; $8084: a long variable as the operand
	beq.w	.other_var_is_long
	cmpi.w	#$8099,d1                       ; $8099: a byte variable as the operand
	beq.w	.other_var_is_byte
	bra.w	optimise_reread                 ; nothing to do
.word_var_constant:
	movem.w	4(a4),d0/d2/d4                  ; d0 = op, d2 = the next IR word, d4 = its variable
	cmpi.w	#$8043,d2                       ; followed by a word store $8043?
	bne.s	.word_var_compare_out_of_range
	cmp.w	d4,d3                           ; into v itself?
	bne.w	.word_var_add_constant
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_constant_into_word_var
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.sub_constant_into_word_var
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_constant_into_word_var
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.add_constant_into_word_var
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.sub_constant_into_word_var
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.mul_constant_into_word_var
	cmpi.w	#$805f,d0                       ; $805f divide
	bne.s	.word_var_add_constant
	move.w	#$80e3,d0                       ; v = v / c -> $80e3
	bra.s	.write_word_constant_op_assign
.add_constant_into_word_var:
	move.w	#$80e0,d0                       ; v = v + c -> $80e0
.write_word_constant_op_assign:
	move.w	d0,6(a4)                        ; op-assign code over the $8043
	move.l	(a4),2(a4)                      ; constant over the operator
	move.w	#$8007,(a4)                     ; $8007 integer constant over the old c
	bra.w	ir_delete_six_bytes             ; drop '$8040 v $8008': leaves $8007 c $80ex v
.sub_constant_into_word_var:
	move.w	#$80e1,d0                       ; v = v - c -> $80e1
	bra.s	.write_word_constant_op_assign
.mul_constant_into_word_var:
	move.w	#$80e2,d0                       ; v = v * c -> $80e2
	bra.s	.write_word_constant_op_assign
.word_var_compare_out_of_range:
	move.l	(a4),d2                         ; constant outside the word range?
	move.w	d2,d3                           ; d3 = c truncated to a word, sign-extended
	ext.l	d3
	cmp.l	d2,d3                           ; same: in range, no constant result
	beq.s	.word_var_add_constant
	move.w	4(a4),d0                        ; d0 = operator
	cmpi.w	#$807f,d0                       ; $807f <=
	beq.s	.negate_constant
	cmpi.w	#$807d,d0                       ; $807d >=
	beq.s	.test_constant_sign
	cmpi.w	#$8080,d0                       ; $8080 <
	beq.s	.negate_constant
	cmpi.w	#$807e,d0                       ; $807e >
	beq.s	.test_constant_sign
	cmpi.w	#$807c,d0                       ; $807c <>: always true
	beq.s	.compare_always_true
	cmpi.w	#$807b,d0                       ; $807b =: always false
	bne.s	.word_var_add_constant
.compare_always_false:
	moveq	#0,d0                           ; always false
.write_compare_result:
	move.l	d0,2(a4)                        ; result over c and the operator
	move.w	#$8007,(a4)                     ; $8007 integer constant
	bra.w	ir_delete_six_bytes             ; drop '$8040 v $8008': leaves $8007 result
.negate_constant:
	neg.l	d2                              ; <= and <: test -c
.test_constant_sign:
	tst.l	d2                              ; c above the word range (or -c for <=, <)?
	bpl.s	.compare_always_false           ; yes: false
.compare_always_true:
	moveq	#-1,d0                          ; always true
	bra.s	.write_compare_result
.word_var_add_constant:
	cmpi.w	#$8064,d0                       ; subtract?
	bne.s	.try_fold_word_add_into_pop
	neg.l	(a4)                            ; v - c -> v + (-c)
	move.w	#$8063,d0                       ; operator slot becomes the add
	move.w	d0,4(a4)
.try_fold_word_add_into_pop:
	cmpi.w	#$8063,d0                       ; only an add can be folded into the pop
	bne.s	.word_var_no_change
	cmpi.w	#$8017,6(a4)                    ; v + c pushed ($8017)?
	bne.s	.word_var_no_change
	addq.l	#8,a4                           ; a4 past the $8017
	bsr.w	measure_ir_operand              ; find the pop of the pushed value; a2 = after it
	subq.l	#8,a4                           ; a4 back at c
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.s	.word_var_no_change
	move.w	-$2(a2),-(sp)                   ; save X, the popping IR code
	move.l	(a4),-(sp)                      ; save c
	move.w	-$4(a4),-(sp)                   ; save v
	lea	8(a4),a0                        ; a0 = past the $8017
	moveq	#14,d0                          ; delete '$8040 v $8008 c $8063 $8017' (14 bytes)
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word X
	moveq	#8,d0                           ; make 8 bytes of room at X
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d1                        ; d1 = v
	move.l	(sp)+,d2                        ; d2 = c
	move.w	(sp)+,d0                        ; d0 = X
	move.b	d2,d3                           ; constant fits a byte?
	ext.w	d3
	ext.l	d3
	cmp.l	d2,d3
	beq.s	.pop_word_byte_constant
	addi.w	#$72,d0                         ; long constant: load word var v into X's register, add c
	move.w	d0,(a2)+
	move.w	d1,(a2)+
	addi.w	#$142,d0                        ; X+$1b4: add the constant to it ($81cf-$81d7)
	move.w	d0,(a2)+
	move.l	d2,(a2)+                        ; the constant (long)
	bra.w	optimise_restart                ; pass changed: start again
.pop_word_byte_constant:
	addi.w	#$ffed,d0                       ; byte constant: X-$13 c (load c into X's register)
	move.w	d0,(a2)+
	move.l	d2,(a2)+
	addi.w	#$1d9,d0                        ; X+$1c6: add word var v to it
	move.w	d0,(a2)+
	move.w	d1,(a2)+
	bra.w	optimise_restart                ; pass changed: start again
.word_var_no_change:
	bra.w	optimise_var_no_change
.other_var_is_long:
	move.w	#$803f,d7                       ; $8084: other variable is long
	bra.s	.other_var_into_word_var
.other_var_is_byte:
	move.w	#$803d,d7                       ; $8099: other variable is byte
.other_var_into_word_var:
	movem.w	2(a4),d0/d2/d4                  ; d0 = op, d2 = the next IR word, d4 = its variable
	cmpi.w	#$8043,d2                       ; followed by a word store $8043...
	bne.s	.word_var_no_change
	cmp.w	d4,d3                           ; ...into v itself?
	bne.s	.word_var_no_change
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_other_into_word_var
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.sub_other_into_word_var
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.add_other_into_word_var
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.sub_other_into_word_var
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_other_into_word_var
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.mul_other_into_word_var
	cmpi.w	#$805f,d0                       ; $805f divide
	beq.s	.div_other_into_word_var
	bra.s	.word_var_no_change
.add_other_into_word_var:
	move.w	#$80e0,d0                       ; v = v + w -> $80e0
.write_word_other_op_assign:
	move.w	d0,4(a4)                        ; op-assign code over the store
	move.w	(a4),2(a4)                      ; w over the operator
	move.w	d7,(a4)                         ; load code for w over the $8084/$8099
	bra.w	ir_delete_six_bytes             ; drop '$8040 v' + the old store: d7 w $80ex v
.sub_other_into_word_var:
	move.w	#$80e1,d0                       ; v = v - w -> $80e1
	bra.s	.write_word_other_op_assign
.mul_other_into_word_var:
	move.w	#$80e2,d0                       ; v = v * w -> $80e2
	bra.s	.write_word_other_op_assign
.div_other_into_word_var:
	move.w	#$80e3,d0                       ; v = v / w -> $80e3
	bra.s	.write_word_other_op_assign
.fuse_pushed_word_var:
	bsr.w	measure_ir_operand              ; '$8040 v $8017 <expr> X' -> '<expr> X+$72 v'
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.w	optimise_retry_word
	move.w	-$2(a2),-(sp)                   ; save X, the popping IR code
	movea.l	a4,a0                           ; delete '$8040 v $8017'
	moveq	#6,d0
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word X
	moveq	#2,d0                           ; make room for the variable number
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d0                        ; d0 = X
	addi.w	#$72,d0                         ; X+$72: load word var v into X's register
	move.w	d0,(a2)+
	move.w	d3,(a2)+                        ; the variable number
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Byte-variable version of optimise_long_var_pair: '$803d v $8099 w op' with stores $8044 and op-assign codes
; $80e4-$80e7.
;------------------------------------------------------------------------------
optimise_byte_var_pair:
	move.w	(a4)+,d1                        ; d1 = w
	move.w	(a4),d0                         ; d0 = operator
	cmpi.w	#$8083,d0                       ; $8083: exchange the two operands
	beq.w	.swap_byte_operands
	cmp.w	d1,d3                           ; same variable on both sides?
	beq.w	.same_byte_variable
	cmpi.w	#$8044,2(a4)                    ; next is a byte store $8044?
	bne.s	.no_byte_store_rewrite
	cmp.w	4(a4),d3                        ; store target x = v?
	beq.s	.store_into_byte_v
	cmp.w	4(a4),d1                        ; x = w? (only commutative ops then)
	bne.s	.no_byte_store_rewrite
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_into_byte_w
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_into_byte_w
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.mul_into_byte_w
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.add_into_byte_w
	bra.s	.no_byte_store_rewrite
.store_into_byte_v:
	cmpi.w	#$805e,d0                       ; v = v * w
	beq.s	.mul_into_byte_v
	cmpi.w	#$8063,d0                       ; v = v + w
	beq.s	.add_into_byte_v
	cmpi.w	#$8064,d0                       ; v = v - w
	beq.s	.sub_into_byte_v
	cmpi.w	#$814e,d0                       ; v = v * w (word multiply)
	beq.s	.mul_into_byte_v
	cmpi.w	#$814c,d0                       ; v = v + w (word add)
	beq.s	.add_into_byte_v
	cmpi.w	#$814d,d0                       ; v = v - w (word subtract)
	beq.s	.sub_into_byte_v
	cmpi.w	#$805f,d0                       ; v = v / w
	beq.s	.div_into_byte_v
.no_byte_store_rewrite:
	bra.s	.no_byte_fold                   ; no store rewrite (no push fold for bytes)
.mul_into_byte_w:
	move.w	#$80e6,d0                       ; w = w * v -> $80e6
	bra.s	.write_byte_op_assign
.add_into_byte_w:
	move.w	#$80e4,d0                       ; w = w + v -> $80e4
	bra.s	.write_byte_op_assign
.div_into_byte_v:
	move.w	#$80e7,d0                       ; v = v / w -> $80e7
	bra.s	.load_byte_w_first
.sub_into_byte_v:
	move.w	#$80e5,d0                       ; v = v - w -> $80e5
	bra.s	.load_byte_w_first
.add_into_byte_v:
	move.w	#$80e4,d0                       ; v = v + w -> $80e4
	bra.s	.load_byte_w_first
.mul_into_byte_v:
	move.w	#$80e6,d0                       ; v = v * w -> $80e6
.load_byte_w_first:
	move.w	d1,-$6(a4)                      ; v = v op w: put w first, store into v
.write_byte_op_assign:
	move.w	d0,-$4(a4)                      ; op-assign code over the old $8099
	move.w	4(a4),-(a4)                     ; store target over the old w
	addq.l	#8,a4                           ; a4 past the $8044 x
	bra.w	ir_delete_six_bytes             ; drop op $8044 x
.same_byte_variable:
	cmpi.w	#$8063,d0                       ; v op v with $8063 +
	beq.s	.double_byte_value
	cmpi.w	#$8064,d0                       ; $8064 -: always 0
	beq.s	.byte_result_false
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.double_byte_value
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.byte_result_false
	cmpi.w	#$807b,d0                       ; $807b =: true
	beq.s	.byte_result_true
	cmpi.w	#$807c,d0                       ; $807c <>: false
	beq.s	.byte_result_false
	cmpi.w	#$807d,d0                       ; $807d >=: true
	beq.s	.byte_result_true
	cmpi.w	#$807f,d0                       ; $807f <=: true
	beq.s	.byte_result_true
	cmpi.w	#$807e,d0                       ; $807e >: false
	beq.s	.byte_result_false
	cmpi.w	#$8080,d0                       ; $8080 <: false
	beq.s	.byte_result_false
.no_byte_fold:
	subq.l	#4,a4                           ; a4 back at the start of '$803d v'
	bra.w	optimise_next                   ; nothing done: continue the scan
.double_byte_value:
	move.w	#$8012,(a4)                     ; v + v -> $8012
	bra.w	ir_delete_four_bytes            ; drop $8099 v: leaves $803d v $8012
.byte_result_true:
	moveq	#-1,d0                          ; true: -1
	bra.s	.write_byte_constant_result
.byte_result_false:
	moveq	#0,d0                           ; false: 0
.write_byte_constant_result:
	addq.l	#2,a4                           ; a4 past the operator
	move.l	d0,-(a4)                        ; constant over w and op
	move.w	#$8007,-(a4)                    ; $8007 integer constant over the $8099
	bra.w	ir_delete_four_bytes            ; drop $803d v: leaves $8007 c
.swap_byte_operands:
	move.w	d1,-$6(a4)                      ; $8083: swap the variables
	move.w	d3,-(a4)                        ; v into the second operand slot
	addq.l	#4,a4                           ; a4 past the $8083
	bra.w	ir_delete_two_bytes             ; drop the $8083

;------------------------------------------------------------------------------
; Optimiser handler for IR $803d v (load byte variable, zero-extended into d0). a4 points at v.
; $802f / $802e (word / byte cast) after it are deleted. $8099 -> optimise_byte_var_pair; $8017 -> fuse with X+$7e when
; X <= $8022;
; $8008 c op with a store back into v -> $80e4-$80e7; $8084/$808d -> other variable op-assign.
; The code at $8ac2-$8e14 (byte compare with an out-of-range constant) has no label and is never reached.
;------------------------------------------------------------------------------
optimise_load_byte_var:
	move.w	(a4)+,d3                        ; d3 = variable number
	move.w	(a4)+,d1                        ; d1 = next IR word
	cmpi.w	#$802f,d1                       ; $802f word cast: redundant
	beq.w	ir_delete_two_bytes
	cmpi.w	#$802e,d1                       ; $802e byte cast: redundant
	beq.w	ir_delete_two_bytes
	cmpi.w	#$8099,d1                       ; $8099: a byte variable as the operand
	beq.w	optimise_byte_var_pair
	cmpi.w	#$8017,d1                       ; $8017: push long
	beq.w	.fuse_pushed_byte_var
	cmpi.w	#$8008,d1                       ; $8008: integer constant as the operand
	beq.s	.byte_var_constant
	cmpi.w	#$8084,d1                       ; $8084: a long variable as the operand
	beq.w	.other_var_is_long_into_byte
	cmpi.w	#$808d,d1                       ; $808d: a word variable as the operand
	beq.w	.other_var_is_word
	bra.w	optimise_reread                 ; nothing to do
.byte_var_constant:
	movem.w	4(a4),d0/d2/d4                  ; d0 = op, d2 = the next IR word, d4 = its variable
	cmpi.w	#$8044,d2                       ; followed by a byte store $8044?
	bne.w	.byte_var_no_change
	cmp.w	d4,d3                           ; into v itself?
	bne.w	.byte_var_no_change
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_constant_into_byte_var
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.sub_constant_into_byte_var
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_constant_into_byte_var
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.add_constant_into_byte_var
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.sub_constant_into_byte_var
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.mul_constant_into_byte_var
	cmpi.w	#$805f,d0                       ; $805f divide
	bne.s	.byte_var_no_change
	move.w	#$80e7,d0                       ; v = v / c -> $80e7
	bra.s	.write_byte_constant_op_assign
.add_constant_into_byte_var:
	move.w	#$80e4,d0                       ; v = v + c -> $80e4
.write_byte_constant_op_assign:
	move.w	d0,6(a4)                        ; op-assign code over the $8044
	move.l	(a4),2(a4)                      ; constant over the operator
	move.w	#$8007,(a4)                     ; $8007 integer constant over the old c
	bra.w	ir_delete_six_bytes             ; drop '$803d v $8008': leaves $8007 c $80ex v
.sub_constant_into_byte_var:
	move.w	#$80e5,d0                       ; v = v - c -> $80e5
	bra.s	.write_byte_constant_op_assign
.mul_constant_into_byte_var:
	move.w	#$80e6,d0                       ; v = v * c -> $80e6
	bra.s	.write_byte_constant_op_assign
	move.l	(a4),d2                         ; unreachable: no branch leads here
	moveq	#0,d3                           ; d3 = c truncated to an unsigned byte
	move.b	d2,d3
	cmp.l	d2,d3                           ; in the byte range: no constant result
	beq.s	.byte_var_no_change
	move.w	4(a4),d0                        ; d0 = operator
	cmpi.w	#$807f,d0                       ; $807f <=
	beq.s	.negate_byte_constant
	cmpi.w	#$807d,d0                       ; $807d >=
	beq.s	.test_byte_constant_sign
	cmpi.w	#$8080,d0                       ; $8080 <
	beq.s	.negate_byte_constant
	cmpi.w	#$807e,d0                       ; $807e >
	beq.s	.test_byte_constant_sign
	cmpi.w	#$807c,d0                       ; $807c <>: always true
	beq.s	.byte_compare_true
	cmpi.w	#$807b,d0                       ; $807b =: always false
	bne.s	.byte_var_no_change
.byte_compare_false:
	moveq	#0,d0
.write_byte_compare_result:
	move.w	#$8007,(a4)                     ; $8007 integer constant
	move.l	d0,2(a4)                        ; the result over c
	bra.w	ir_delete_six_bytes             ; drop '$803d v $8008': leaves $8007 result
.negate_byte_constant:
	neg.l	d2                              ; <= and <: test -c
.test_byte_constant_sign:
	tst.l	d2                              ; c above the range?
	bpl.s	.byte_compare_false             ; yes: false
.byte_compare_true:
	moveq	#-1,d0                          ; always true
	bra.s	.write_byte_compare_result
.byte_var_no_change:
	bra.w	optimise_reread
.other_var_is_word:
	move.w	#$8040,d7                       ; $808d: other variable is word
	bra.s	.other_var_into_byte_var
.other_var_is_long_into_byte:
	move.w	#$803f,d7                       ; $8084: other variable is long
.other_var_into_byte_var:
	movem.w	2(a4),d0/d2/d4                  ; d0 = op, d2 = the next IR word, d4 = its variable
	cmpi.w	#$8044,d2                       ; followed by a byte store $8044...
	bne.s	.byte_var_no_change
	cmp.w	d4,d3                           ; ...into v itself?
	bne.s	.byte_var_no_change
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.add_other_into_byte_var
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.sub_other_into_byte_var
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.mul_other_into_byte_var
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.s	.add_other_into_byte_var
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.sub_other_into_byte_var
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.mul_other_into_byte_var
	cmpi.w	#$805f,d0                       ; $805f divide
	beq.s	.div_other_into_byte_var
	bra.s	.byte_var_no_change
.add_other_into_byte_var:
	move.w	#$80e4,d0                       ; v = v + w -> $80e4
.write_byte_other_op_assign:
	move.w	d0,4(a4)                        ; op-assign code over the store
	move.w	(a4),2(a4)                      ; w over the operator
	move.w	d7,(a4)                         ; load code for w over the $8084/$808d
	bra.w	ir_delete_six_bytes             ; drop '$803d v' + the old store: d7 w $80ex v
.sub_other_into_byte_var:
	move.w	#$80e5,d0                       ; v = v - w -> $80e5
	bra.s	.write_byte_other_op_assign
.mul_other_into_byte_var:
	move.w	#$80e6,d0                       ; v = v * w -> $80e6
	bra.s	.write_byte_other_op_assign
.div_other_into_byte_var:
	move.w	#$80e7,d0                       ; v = v / w -> $80e7
	bra.s	.write_byte_other_op_assign
.fuse_pushed_byte_var:
	bsr.w	measure_ir_operand              ; '$803d v $8017 <expr> X' -> '<expr> X+$7e v'
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.w	optimise_retry_word
	move.w	-$2(a2),d0                      ; d0 = X, the popping IR code
	cmpi.w	#$8022,d0                       ; only pops up to $7d18
	bhi.w	optimise_retry_word
	move.w	d0,-(sp)                        ; save X
	movea.l	a4,a0                           ; delete '$803d v $8017'
	moveq	#6,d0
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word X
	moveq	#2,d0                           ; make room for the variable number
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,d0                        ; d0 = X
	addi.w	#$7e,d0                         ; X+$7e: load byte var v into X's register ($8099-)
	move.w	d0,(a2)+
	move.w	d3,(a2)+                        ; the variable number
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Optimiser handler for IR $802f (word cast): deleted when followed by $8022 $8097 or $8022 $8096.
;------------------------------------------------------------------------------
optimise_word_cast:
	cmpi.w	#$8022,(a4)                     ; $802f followed by $8022 (pop into a0)...
	bne.w	optimise_next
	cmpi.w	#$8097,2(a4)                    ; ...and $8097?
	beq.s	.delete_cast
	cmpi.w	#$8096,2(a4)                    ; ...or $8096?
	bne.w	optimise_next
.delete_cast:
	bra.w	ir_delete_two_bytes             ; drop the cast

;------------------------------------------------------------------------------
; Optimiser handler for IR $802e (byte cast): deleted when followed by $8022 $8096.
;------------------------------------------------------------------------------
optimise_byte_cast:
	cmpi.w	#$8022,(a4)                     ; $802e followed by $8022 (pop into a0)...
	bne.w	optimise_next
	cmpi.w	#$8096,2(a4)                    ; ...and $8096: drop the cast
	beq.w	ir_delete_two_bytes
	bra.w	optimise_next                   ; otherwise keep it

;------------------------------------------------------------------------------
; Optimiser handler for IR $8001 c op (float constant c as the right operand of float operator op).
; d0/d1/d2 = constant (mantissa long, mantissa low word, exponent word, 0 = zero, negated for a negative value), d7 =
; op.
; Followed by $8005 (to integer) with an integral c: $804a/$804b -> $8005 $8008 c $8063 (sub negates c), $812a/$812b ->
; $812c/$812d.
; Otherwise folds: x+0 / x-0 deleted, two constant adds merged (float_add); x*0 -> $8000 0.0, x*1 and x/1 deleted,
; x*2 -> $8011 (DOUBLE); constant mul/div chains merged (float_multiply, float_divide); x^2 -> library $1a FSQUARE.
;------------------------------------------------------------------------------
optimise_float_constant_operand:
	move.l	(a4)+,d0                        ; d0 = mantissa long
	move.w	(a4)+,d1                        ; d1 = mantissa low word
	move.w	(a4)+,d2                        ; d2 = exponent word
	move.w	(a4)+,d7                        ; d7 = float operator
	cmpi.w	#$8005,(a4)                     ; result converted to integer ($8005)?
	bne.s	.float_constant_op
	cmpi.w	#$804a,d7                       ; $804a float add
	beq.s	.integer_add_constant
	cmpi.w	#$812a,d7                       ; $812a float MIN
	beq.s	.integer_min_constant
	cmpi.w	#$812b,d7                       ; $812b float MAX
	beq.s	.integer_max_constant
	cmpi.w	#$804b,d7                       ; $804b float subtract
	bne.s	.float_constant_op
	neg.w	d2                              ; x - c = x + (-c): negate the exponent word
.integer_add_constant:
	bsr.w	float_constant_to_integer       ; c integral? d0 = the integer
	bne.s	.not_integral                   ; no: fold as a float
	move.w	#$8063,(a4)                     ; integer add
.write_integer_operator:
	move.l	d0,-(a4)                        ; $8005 $8008 c op
	move.w	#$8008,-(a4)                    ; $8008 integer constant operand
	move.w	#$8005,-(a4)                    ; $8005 moved in front: x to integer first
	bra.w	ir_delete_four_bytes            ; drop '$8001' and the rest of c: $8005 $8008 c op
.integer_min_constant:
	bsr.w	float_constant_to_integer
	bne.s	.not_integral
	move.w	#$812c,(a4)                     ; $812a -> $812c
	bra.s	.write_integer_operator
.integer_max_constant:
	bsr.w	float_constant_to_integer
	bne.s	.not_integral
	move.w	#$812d,(a4)                     ; $812b -> $812d
	bra.s	.write_integer_operator
.not_integral:
	move.l	d3,d0                           ; not integral: restore the constant
	move.l	d4,d1
	move.l	d5,d2
	move.w	(a4),d7                         ; d7 = the operator again
.float_constant_op:
	cmpi.w	#$804a,d7                       ; $804a float add
	beq.s	.float_add_constant
	cmpi.w	#$804b,d7                       ; $804b float subtract
	beq.s	.float_sub_constant
	cmpi.w	#$804d,d7                       ; $804d float multiply
	beq.s	.float_mul_constant
	cmpi.w	#$804e,d7                       ; $804e float divide
	beq.w	.float_div_constant
	cmpi.w	#$8054,d7                       ; $8054 float power
	beq.w	.float_power_constant
.no_float_fold:
	bra.w	optimise_reread
.float_sub_constant:
	neg.w	d2                              ; x - c = x + (-c)
.float_add_constant:
	tst.w	d2                              ; x + 0.0: drop
	beq.s	.delete_constant
	cmpi.w	#$8001,(a4)+                    ; another float constant add follows?
	bne.s	.no_add_chain
	move.l	(a4)+,d3                        ; second constant d3/d4/d5
	move.w	(a4)+,d4
	move.w	(a4)+,d5
	move.w	(a4)+,d6                        ; d6 = its operator
	cmpi.w	#$804a,d6                       ; x + c1 + c2
	beq.s	.merge_add_constants
	cmpi.w	#$804b,d6                       ; x + c1 - c2
	beq.s	.second_is_subtract
	suba.w	#$c,a4                          ; neither: a4 back over the second constant
.no_add_chain:
	bra.w	optimise_reread
.second_is_subtract:
	neg.w	d5                              ; - c2 = + (-c2)
.merge_add_constants:
	bsr.w	float_add                       ; add the two constants
	move.w	#$804a,-(a4)                    ; write '$804a' then c1+c2 back over the second
	move.w	d2,-(a4)
	move.w	d1,-(a4)
	move.l	d0,-(a4)
	subq.l	#2,a4                           ; a4 = end of the first constant
.delete_constant:
	moveq	#12,d0                          ; delete 12 bytes ($8001 c op)
	bra.w	ir_delete_bytes_restart         ; delete 12 bytes ending at a4
.result_float_zero:
	clr.l	-(a4)                           ; x * 0.0: the value becomes the constant 0.0 ($8000)
	clr.l	-(a4)
	move.w	#$8000,-(a4)                    ; $8000 float constant over the $8001 slot
	bra.w	ir_delete_two_bytes
.float_mul_constant:
	tst.w	d2                              ; x * 0.0
	beq.s	.result_float_zero
	cmpi.w	#$3ff,d2                        ; exponent $3ff, mantissa $80000000 = 1.0: x * 1 dropped
	bne.s	.not_times_one
	tst.w	d1
	bne.s	.not_times_one                  ; low word must be 0
	add.l	d0,d0                           ; mantissa $80000000? (shifts out to 0)
	beq.s	.delete_constant
	roxr.l	#1,d0                           ; no: restore the mantissa
.not_times_one:
	cmpi.w	#$400,d2                        ; exponent $400 = 2.0: x * 2 -> $8011
	bne.s	.try_mul_chain
	tst.w	d1
	bne.s	.try_mul_chain
	add.l	d0,d0                           ; mantissa $80000000?
	beq.s	.mul_by_two
	roxr.l	#1,d0                           ; no: restore the mantissa
.try_mul_chain:
	cmpi.w	#$8001,(a4)+                    ; another float constant follows?
	bne.s	.no_mul_chain
	move.l	(a4)+,d3                        ; second constant d3/d4/d5
	move.w	(a4)+,d4
	move.w	(a4)+,d5
	move.w	(a4)+,d6                        ; d6 = its operator
	cmpi.w	#$804d,d6                       ; x * c1 * c2
	beq.s	.merge_mul_constants
	cmpi.w	#$804e,d6                       ; x * c1 / c2
	beq.s	.mul_then_div
	suba.w	#$a,a4                          ; neither: a4 back over the second constant
.no_mul_chain:
	bra.w	optimise_reread
.merge_mul_constants:
	bsr.w	float_multiply                  ; multiply the constants
.write_mul_constant:
	move.w	#$804d,-(a4)                    ; write '$804d' then the merged constant
	move.w	d2,-(a4)
	move.w	d1,-(a4)
	move.l	d0,-(a4)
	subq.l	#2,a4                           ; a4 = end of the first constant
	bra.s	.delete_constant
.mul_then_div:
	tst.w	d5                              ; c2 = 0.0?
	beq.s	.mul_then_div_by_zero           ; yes: keep x / 0
	bsr.w	float_divide                    ; c1 / c2
	bra.s	.write_mul_constant
.mul_then_div_by_zero:
	suba.w	#$c,a4                          ; drop x * c1, keep / 0.0
	bra.s	.delete_constant
.mul_by_two:
	move.w	#$8011,-(a4)                    ; $8011 = float DOUBLE (library $28f)
	bra.w	ir_delete_ten_bytes             ; drop '$8001 c': leaves $8011
.float_div_constant:
	tst.w	d2                              ; x / 0.0 left alone
	beq.w	optimise_next                   ; x / 0.0: keep for the runtime error
	cmpi.w	#$3ff,d2                        ; 1.0?
	bne.s	.try_div_chain
	tst.w	d1                              ; low word must be 0
	bne.s	.try_div_chain
	add.l	d0,d0                           ; mantissa $80000000? x / 1 dropped
	beq.w	.delete_constant
	roxr.l	#1,d0                           ; no: restore the mantissa
.try_div_chain:
	cmpi.w	#$8001,(a4)+                    ; another float constant follows?
	bne.s	.no_div_chain
	move.l	(a4)+,d3                        ; second constant d3/d4/d5
	move.w	(a4)+,d4
	move.w	(a4)+,d5
	move.w	(a4)+,d6                        ; d6 = its operator
	cmpi.w	#$804d,d6                       ; x / c1 * c2
	beq.s	.div_then_mul
	cmpi.w	#$804e,d6                       ; x / c1 / c2
	beq.s	.div_then_div
	suba.w	#$a,a4                          ; neither: a4 back over the second constant
.no_div_chain:
	bra.w	optimise_reread
.div_then_div:
	bsr.w	float_multiply                  ; x / c1 / c2 = x / (c1 * c2)
.write_div_constant:
	move.w	#$804e,-(a4)                    ; $804e divide
.write_merged_constant:
	move.w	d2,-(a4)                        ; the merged constant before the operator
	move.w	d1,-(a4)
	move.l	d0,-(a4)
	subq.l	#2,a4                           ; a4 = end of the first constant
	bra.w	.delete_constant
.div_then_mul:
	exg	d3,d0                           ; c2 into d0-d2, c1 into d3-d5
	exg	d4,d1
	exg	d5,d2
	tst.w	d5                              ; c1 = 0.0? (cannot be: checked at $8d2a)
	beq.s	.divisor_zero
	bsr.w	float_divide                    ; c2 / c1: x / c1 * c2 = x * (c2 / c1)
	move.w	#$804d,-(a4)                    ; the multiply
	bra.s	.write_merged_constant
.divisor_zero:
	moveq	#0,d2                           ; constant 0.0
	bra.s	.write_div_constant
.float_power_constant:
	cmpi.w	#$400,d2                        ; x ^ 2.0 -> library $1a FSQUARE
	bne.w	.no_float_fold
	tst.w	d1                              ; low word must be 0
	bne.w	.no_float_fold
	add.l	d0,d0                           ; mantissa $80000000?
	bne.w	.no_float_fold
	move.w	#$1a,-(a4)                      ; $1a FSQUARE over the operator
	bra.w	ir_delete_ten_bytes             ; drop '$8001 c'

;------------------------------------------------------------------------------
; Optimiser handler for IR $8018: '$8018 $8007 c $8022' (constant in between) becomes '$8007 c'.
;------------------------------------------------------------------------------
optimise_ir_8018:
	cmpi.w	#$8007,(a4)                     ; a constant right after the $8018 (save string)...
	bne.s	.no_constant_between
	cmpi.w	#$8022,6(a4)                    ; ...and then $8022 (pop into a0)?
	bne.s	.no_constant_between
	move.l	2(a4),4(a4)                     ; c over the $8022
	move.w	(a4)+,(a4)                      ; $8007 one word on; a4 past the first copy
	bra.w	ir_delete_four_bytes            ; drop '$8018 $8007': leaves $8007 c
.no_constant_between:
	bra.w	optimise_next

;------------------------------------------------------------------------------
; Optimiser handler for IR $8017 (push the integer d0 as left operand). a4 points after it.
; '$8017 $8007 c $801b op' -> '$8008 c op'' and '$8017 $803f/$8040/$803d v $801b op' -> '$8084/$808d/$8099 v op'',
; with op' from swapped_int_operator and a $8083 (exg d0,d1) kept in front when the operator is not commutative.
;------------------------------------------------------------------------------
optimise_push_int:
	cmpi.w	#$8007,(a4)                     ; '$8017 $8007 c': pushed integer constant
	beq.s	.push_constant
	cmpi.w	#$803f,(a4)                     ; pushed long variable
	beq.s	.push_long_var
	cmpi.w	#$8040,(a4)                     ; pushed word variable
	beq.s	.push_word_var
	cmpi.w	#$803d,(a4)                     ; pushed byte variable
	beq.s	.push_byte_var
	bra.w	optimise_next                   ; anything else: no change
.push_constant:
	cmpi.w	#$801b,6(a4)                    ; constant followed by the pop $801b?
	bne.w	optimise_next
	move.w	8(a4),d0                        ; d0 = the operator after the pop
	bsr.s	swapped_int_operator            ; can the operands change places?
	bne.w	optimise_next                   ; no
	move.w	#$8008,-$2(a4)                  ; $8007 -> $8008 (constant operand)
	move.l	2(a4),(a4)+                     ; constant one word down, over the $8007
	tst.w	d1                              ; no exg needed
	bne.s	.keep_constant_exg
	move.w	d0,(a4)+                        ; op' over the old c low word
	addq.l	#4,a4                           ; a4 past the old operator
	bra.w	ir_delete_four_bytes            ; drop '$801b op': '$8008 c op''
.keep_constant_exg:
	move.w	d1,(a4)+                        ; $8083 exg first
	move.w	d0,(a4)+                        ; then op'
	addq.l	#2,a4                           ; a4 past the old operator
	bra.w	ir_delete_two_bytes             ; drop the old operator: '$8008 c $8083 op''
.push_long_var:
	move.w	#$8084,d7                       ; long variable -> $8084
	bra.s	.push_variable
.push_word_var:
	move.w	#$808d,d7                       ; word variable -> $808d
	bra.s	.push_variable
.push_byte_var:
	move.w	#$8099,d7                       ; byte variable -> $8099
.push_variable:
	cmpi.w	#$801b,4(a4)                    ; variable followed by the pop $801b?
	bne.w	optimise_next
	move.w	6(a4),d0                        ; d0 = the operator after the pop
	bsr.s	swapped_int_operator            ; can the operands change places?
	bne.w	optimise_next                   ; no
	move.w	d7,-$2(a4)                      ; operand-form load over the $8017
	move.w	2(a4),(a4)+                     ; variable number over the old load code
	tst.w	d1                              ; no exg needed
	bne.s	.keep_variable_exg
	move.w	d0,(a4)+                        ; op' over the old variable number
	addq.l	#4,a4                           ; a4 past the old operator
	bra.w	ir_delete_four_bytes            ; drop '$801b op': '$8084 v op''
.keep_variable_exg:
	move.w	d1,(a4)+                        ; $8083 exg first
	move.w	d0,(a4)+                        ; then op'
	addq.l	#2,a4                           ; a4 past the old operator
	bra.w	ir_delete_two_bytes             ; drop the old operator: '$8084 v $8083 op''

;------------------------------------------------------------------------------
; Gives the integer operator to use when the pushed left operand and d0 change places.
; Entry d0 = operator. Exit Z: d0 = operator, d1 = 0 or $8083 (an exg d0,d1 is still needed). NE (d0 = -1): not handled.
; Commutative: $8063, $814c, $8060-$8062, $807b, $807c, $805e, $814e, $812c, $812d. Mirrored: $807d <-> $807f, $807e <->
; $8080.
; With exg: $8083, $8064, $814d, $805f, $8065, $8066, $8067.
;------------------------------------------------------------------------------
swapped_int_operator:
	moveq	#0,d1                           ; d1 = 0: no exg needed
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.w	.operator_found
	cmpi.w	#$814c,d0                       ; $814c word add
	beq.w	.operator_found
	cmpi.w	#$8060,d0                       ; $8060 AND
	beq.w	.operator_found
	cmpi.w	#$8061,d0                       ; $8061 OR
	beq.w	.operator_found
	cmpi.w	#$8062,d0                       ; $8062 XOR
	beq.s	.operator_found
	cmpi.w	#$807b,d0                       ; $807b =
	beq.s	.operator_found
	cmpi.w	#$807c,d0                       ; $807c <>
	beq.s	.operator_found
	cmpi.w	#$807f,d0                       ; $807f <=
	bne.s	.not_le
.mirror_ge_le:
	eori.w	#$2,d0                          ; $807f (<=) <-> $807d (>=)
	bra.s	.operator_found
.not_le:
	cmpi.w	#$807d,d0                       ; $807d >=
	beq.s	.mirror_ge_le
	cmpi.w	#$8080,d0                       ; $8080 <
	bne.s	.not_lt
.mirror_gt_lt:
	eori.w	#$fe,d0                         ; $8080 (<) <-> $807e (>)
	bra.s	.operator_found
.not_lt:
	cmpi.w	#$807e,d0                       ; $807e >
	beq.s	.mirror_gt_lt
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.operator_found
	cmpi.w	#$814e,d0                       ; $814e word multiply
	beq.s	.operator_found
	cmpi.w	#$812c,d0                       ; $812c integer MIN
	beq.s	.operator_found
	cmpi.w	#$812d,d0                       ; $812d integer MAX
	beq.s	.operator_found
	move.w	#$8083,d1                       ; the rest keep the order with an exg
	cmpi.w	#$8083,d0                       ; $8083 exg
	beq.s	.operator_found
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.operator_found
	cmpi.w	#$814d,d0                       ; $814d word subtract
	beq.s	.operator_found
	cmpi.w	#$805f,d0                       ; $805f divide
	beq.s	.operator_found
	cmpi.w	#$8065,d0                       ; $8065 MOD
	beq.s	.operator_found
	cmpi.w	#$8066,d0                       ; $8066 EQV
	beq.s	.operator_found
	cmpi.w	#$8067,d0                       ; $8067 IMP
	beq.s	.operator_found
	moveq	#-1,d0                          ; not handled: NE
	rts
.operator_found:
	cmp.w	d0,d0                           ; Z set: d0 = operator
	rts

;------------------------------------------------------------------------------
; '$8000 c $5a' (library $5a RANDOM of a float constant): when c is an integer up to $ffff it becomes
; '$8007 c $5c $8006' (RAND on the integer, then converted to float). Entry d3/d4/d5 = the constant.
;------------------------------------------------------------------------------
optimise_random_constant:
	move.l	d3,d0                           ; constant into d0/d1/d2
	move.l	d4,d1
	move.l	d5,d2
	bsr.w	float_constant_to_integer       ; integral? d0 = the integer
	bne.s	.not_small_integer              ; no
	cmpi.l	#$ffff,d0                       ; up to $ffff?
	bhi.s	.not_small_integer              ; no
	move.w	#$8006,-(a4)                    ; $8006 int to float at the end
	move.w	#$5c,-(a4)                      ; library $5c RAND
	move.l	d0,-(a4)                        ; the integer
	move.w	#$8007,-(a4)                    ; $8007 integer constant
	bra.w	ir_delete_two_bytes             ; drop the old $8000: '$8007 c $5c $8006'
.not_small_integer:
	bra.w	optimise_next

;------------------------------------------------------------------------------
; Optimiser handler for IR $80ed n p (string constant: word length, long address). Library calls on it are folded:
; $ac LENSTR -> $8007 n; $ad ASCSTR -> $8007 first byte; a string compare '$81ff X routine' (X = string variable,
; routine
; from string_routine_table SGE..SNE) becomes '$803b X $80ed n p' with the COSxx routine (compare with a constant
; string).
;------------------------------------------------------------------------------
optimise_string_constant:
	move.w	(a4)+,d0                        ; d0 = length
	movea.l	(a4)+,a1                        ; a1 = address of the characters
	move.w	(a4)+,d1                        ; d1 = the IR word after the constant
	cmpi.w	#$ac,d1                         ; $ac LENSTR
	beq.s	.length_constant
	cmpi.w	#$ad,d1                         ; $ad ASCSTR
	beq.s	.first_char_constant
	cmpi.w	#$81ff,d1                       ; $81ff string compare
	bne.s	.no_string_fold
	move.w	2(a4),d0                        ; d0 = the compare routine after the $81ff X
	lea	string_routine_table(pc),a0     ; 6 compare routines SGE SLE SGT SLT SEQ SNE
	moveq	#5,d1
.find_compare_routine:
	cmp.w	(a0)+,d0                        ; search the 6 compare routines
	dbeq	d1,.find_compare_routine
	bne.s	.no_string_fold                 ; not a compare routine
	move.w	$44(a0),d0                      ; COSxx: compare with a constant string
	move.w	(a4),d1                         ; d1 = X
	move.l	-$6(a4),d2                      ; d2 = address of the characters
	move.w	-$8(a4),d3                      ; d3 = length
	move.w	#$803b,-$a(a4)                  ; $803b X (load string var X)
	move.w	d1,-$8(a4)
	move.w	#$80ed,-$6(a4)                  ; then the constant string $80ed n p
	move.w	d3,-$4(a4)
	move.l	d2,-$2(a4)
	move.w	d0,2(a4)                        ; routine word becomes COSxx
	bra.w	optimise_restart                ; pass changed: start again
.no_string_fold:
	bra.w	optimise_reread
.length_constant:
	ext.l	d0                              ; LEN = the length
.write_int_constant:
	move.l	d0,-(a4)                        ; the value over the constant
	move.w	#$8007,-(a4)                    ; $8007 integer constant over the $80ed
	bra.w	ir_delete_four_bytes            ; drop the old n/library word
.first_char_constant:
	moveq	#0,d0                           ; ASC = the first character
	move.b	(a1),d0
	bra.s	.write_int_constant

;------------------------------------------------------------------------------
; Optimiser handler for IR $80e9 (empty string): LEN/ASC -> $8007 0; string compare -> '$803b X EMSxx'.
;------------------------------------------------------------------------------
optimise_empty_string:
	move.w	(a4)+,d1                        ; d1 = the IR word after $80e9
	cmpi.w	#$ac,d1                         ; $ac LENSTR
	beq.s	.empty_length_zero
	cmpi.w	#$ad,d1                         ; $ad ASCSTR
	beq.s	.empty_length_zero
	cmpi.w	#$81ff,d1                       ; $81ff string compare
	bne.s	.no_empty_string_fold
	move.w	2(a4),d0                        ; d0 = the compare routine after the $81ff X
	lea	string_routine_table(pc),a0     ; 6 compare routines SGE SLE SGT SLT SEQ SNE
	moveq	#5,d1
.find_empty_compare_routine:
	cmp.w	(a0)+,d0
	dbeq	d1,.find_empty_compare_routine
	bne.s	.no_empty_string_fold           ; not a compare routine
	move.w	$c(a0),d0                       ; EMSxx: compare with the empty string
	move.w	#$803b,-$4(a4)                  ; $803b over the $80e9
	move.w	(a4),-$2(a4)                    ; X over the $81ff
	move.w	d0,(a4)+                        ; EMSxx over the X slot
	addq.l	#2,a4                           ; a4 past the old routine
	bra.w	ir_delete_two_bytes             ; drop the old routine: '$803b X EMSxx'
.no_empty_string_fold:
	bra.w	optimise_reread
.empty_length_zero:
	movea.l	a4,a0                           ; two more bytes for '$8007 0'
	moveq	#2,d0
	bsr.w	ir_insert_bytes
	subq.l	#2,a4                           ; a4 at the old library word
	clr.l	(a4)                            ; value 0
	move.w	#$8007,-(a4)                    ; $8007 over the $80e9
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Optimiser handler for IR $80ea c (one-character string): LEN -> 1, ASC -> c; compare -> CHSxx with c as $8007.
;------------------------------------------------------------------------------
optimise_one_char_string:
	move.w	(a4)+,d0                        ; d0 = the character
	move.w	(a4)+,d1                        ; d1 = the IR word after it
	cmpi.w	#$ac,d1                         ; $ac LENSTR
	beq.s	.length_one
	cmpi.w	#$ad,d1                         ; $ad ASCSTR
	beq.s	.write_char_constant
	cmpi.w	#$81ff,d1                       ; $81ff string compare
	bne.s	.no_char_fold
	move.w	2(a4),d0                        ; d0 = the compare routine after the $81ff X
	lea	string_routine_table(pc),a0     ; 6 compare routines SGE SLE SGT SLT SEQ SNE
	moveq	#5,d1
.find_char_compare_routine:
	cmp.w	(a0)+,d0
	dbeq	d1,.find_char_compare_routine
	bne.s	.no_char_fold                   ; not a compare routine
	move.w	$1a(a0),-(sp)                   ; CHSxx: compare with one character
	move.w	-$4(a4),d2                      ; d2 = the character
	ext.w	d2                              ; as a signed value
	bra.s	rewrite_string_compare_constant
.no_char_fold:
	bra.w	optimise_reread
.length_one:
	moveq	#1,d0                           ; LEN = 1
.write_char_constant:
	andi.l	#$ff,d0                         ; ASC = the character code
	move.l	d0,-(a4)                        ; the value over the character and library word
	move.w	#$8007,-(a4)                    ; $8007 over the $80ea
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Builds '$803b X $8007 value routine' for a string compare against a short constant string.
; Entry d2 = value, routine number on the stack.
;------------------------------------------------------------------------------
rewrite_string_compare_constant:
	move.w	(a4),d1                         ; d1 = X
	move.w	#$803b,-$6(a4)                  ; $803b over the $80ea / $80eb
	move.w	d1,-$4(a4)                      ; X next
	move.w	#$8007,-$2(a4)                  ; $8007 over the $81ff
	ext.l	d2
	move.l	d2,(a4)+                        ; the value over the old X and routine
	moveq	#2,d0                           ; room for the routine word
	movea.l	a4,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,(a4)+                     ; the CHSxx / MISxx routine
	bra.w	optimise_next                   ; continue the scan

;------------------------------------------------------------------------------
; Optimiser handler for IR $80eb w (two-character string): LEN -> 2, ASC -> first byte, CVI -> the word; compare ->
; MISxx.
;------------------------------------------------------------------------------
optimise_two_char_string:
	move.w	(a4)+,d0                        ; d0 = the two characters
	move.w	(a4)+,d1                        ; d1 = the IR word after them
	cmpi.w	#$ac,d1                         ; $ac LENSTR
	beq.s	.length_two
	cmpi.w	#$ad,d1                         ; $ad ASCSTR
	beq.s	.first_char_of_word
	cmpi.w	#$ae,d1                         ; $ae CVISTR
	beq.s	.word_value
	cmpi.w	#$81ff,d1                       ; $81ff string compare
	bne.s	.no_mki_fold
	move.w	2(a4),d0                        ; d0 = the compare routine after the $81ff X
	lea	string_routine_table(pc),a0     ; 6 compare routines SGE SLE SGT SLT SEQ SNE
	moveq	#5,d1
.find_mki_compare_routine:
	cmp.w	(a0)+,d0
	dbeq	d1,.find_mki_compare_routine
	bne.s	.no_mki_fold                    ; not a compare routine
	move.w	$28(a0),-(sp)                   ; MISxx: compare with a two-character string
	move.w	-$4(a4),d2                      ; d2 = the two characters
	bra.s	rewrite_string_compare_constant
.no_mki_fold:
	bra.w	optimise_reread
.length_two:
	moveq	#2,d0                           ; LEN = 2
	bra.s	.write_mki_constant
.first_char_of_word:
	lsr.w	#8,d0                           ; ASC = high byte
.word_value:
	ext.l	d0                              ; CVI: the word, sign-extended
.write_mki_constant:
	move.l	d0,-(a4)                        ; the value over the constant
	move.w	#$8007,-(a4)                    ; $8007 over the $80eb
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Optimiser handler for IR $80ec l (four-character string): LEN -> 4, ASC -> top byte, CVI -> high word, CVL -> long;
; compare -> MLSxx.
;------------------------------------------------------------------------------
optimise_four_char_string:
	move.l	(a4)+,d0                        ; d0 = the four characters
	move.w	(a4)+,d1                        ; d1 = the IR word after them
	cmpi.w	#$ac,d1                         ; $ac LENSTR
	beq.s	.length_four
	cmpi.w	#$ad,d1                         ; $ad ASCSTR
	beq.s	.first_char_of_long
	cmpi.w	#$ae,d1                         ; $ae CVISTR
	beq.s	.high_word_value
	cmpi.w	#$af,d1                         ; $af CVLSTR
	beq.s	.write_mkl_constant
	cmpi.w	#$81ff,d1                       ; $81ff string compare
	bne.s	.no_mkl_fold
	move.w	2(a4),d0                        ; d0 = the compare routine after the $81ff X
	lea	string_routine_table(pc),a0     ; 6 compare routines SGE SLE SGT SLT SEQ SNE
	moveq	#5,d1
.find_mkl_compare_routine:
	cmp.w	(a0)+,d0
	dbeq	d1,.find_mkl_compare_routine
	bne.s	.no_mkl_fold                    ; not a compare routine
	move.w	$36(a0),d0                      ; MLSxx: compare with a four-character string
	move.w	(a4),d1                         ; d1 = X
	move.l	-$6(a4),d2                      ; d2 = the four characters
	move.w	#$803b,-$8(a4)                  ; $803b X
	move.w	d1,-$6(a4)
	move.w	#$8007,-$4(a4)                  ; then $8007 and the long
	move.l	d2,-$2(a4)
	move.w	d0,2(a4)                        ; routine word becomes MLSxx
	addq.l	#4,a4                           ; a4 past it
	bra.w	optimise_next                   ; continue the scan
.no_mkl_fold:
	bra.w	optimise_reread
.length_four:
	moveq	#4,d0                           ; LEN = 4
	bra.s	.write_mkl_constant
.first_char_of_long:
	lsr.l	#8,d0                           ; ASC: top byte...
.high_word_value:
	swap	d0                              ; ...or CVI: the high word
	ext.l	d0                              ; sign-extended
.write_mkl_constant:
	move.l	d0,-(a4)                        ; the value over the constant
	move.w	#$8007,-(a4)                    ; $8007 one word on
	bra.w	ir_delete_two_bytes             ; drop the $80ec: '$8007 value'

;------------------------------------------------------------------------------
; Optimiser handler for IR $8038 (INKEY$). LEN(INKEY$) used as a condition ($80bf/$80c0) -> $104 INKEY;
; INKEY$ compared with "" ($8018 $80e9 $8023 SEQ/SNE) -> $104 INKEY $8008 0 $807b/$807c.
;------------------------------------------------------------------------------
optimise_inkey_string:
	movem.w	(a4),d0-d4                      ; d0-d4 = the next five IR words
	cmpi.w	#$ac,d0                         ; $ac LENSTR: LEN(INKEY$)
	beq.s	.length_of_inkey
	cmpi.w	#$8018,d0                       ; $8018 (save string) $80e9 ("") $8023 (pop into a1)?
	bne.s	.no_inkey_fold
	cmpi.w	#$80e9,d1
	bne.s	.no_inkey_fold
	cmpi.w	#$8023,d2
	bne.s	.no_inkey_fold
	cmpi.w	#$144,d3                        ; $144 SEQ
	beq.s	.compare_equal
	cmpi.w	#$145,d3                        ; $145 SNE
	bne.s	.no_inkey_fold
	move.w	#$807c,d0                       ; INKEY$<>"": $807c <>
	bra.s	.write_inkey_compare
.compare_equal:
	move.w	#$807b,d0                       ; INKEY$="": $807b =
.write_inkey_compare:
	move.w	#$104,-$2(a4)                   ; library $104 INKEY
	move.w	#$8008,(a4)+                    ; $8008 integer constant 0
	clr.l	(a4)+
	move.w	d0,(a4)+                        ; then the integer compare
	bra.w	optimise_next                   ; continue the scan
.length_of_inkey:
	cmpi.w	#$80bf,d1                       ; used as a condition: $80bf jump if false...
	beq.s	.inkey_as_condition
	cmpi.w	#$80c0,d1                       ; ...or $80c0 jump if true
	beq.s	.inkey_as_condition
.no_inkey_fold:
	bra.w	optimise_next
.inkey_as_condition:
	move.w	#$104,(a4)                      ; LEN(INKEY$) -> INKEY
	bra.w	ir_delete_two_bytes

;------------------------------------------------------------------------------
; Optimiser handler for IR $8084 w op (long variable w as operand): followed by a store into w -> op-assign
; $80dc (+) / $80de (*); with $8083 and / -> $80df. The $80dd test compares d1 with both $8064 and $8078, so it never
; matches.
;------------------------------------------------------------------------------
optimise_long_var_operand:
	move.w	(a4)+,d0                        ; d0 = w
	movem.w	(a4),d1-d4                      ; d1 = op, d2-d4 = the next IR words
	cmpi.w	#$8042,d2                       ; store $8042 right after op?
	bne.s	.store_after_exg
	cmp.w	d0,d3                           ; into w itself?
	bne.s	optimise_var_operand_no_change
	cmpi.w	#$8063,d1                       ; w = w + d0 -> $80dc
	beq.s	.add_into_var
	cmpi.w	#$805e,d1                       ; w = w * d0 -> $80de
	beq.s	.mul_into_var
	bra.s	optimise_var_operand_no_change
.store_after_exg:
	cmpi.w	#$8042,d3                       ; 'op $8042 w' after a $8083 exg?
	bne.s	optimise_var_operand_no_change
	cmp.w	d0,d4                           ; into w itself?
	bne.s	optimise_var_operand_no_change
	cmpi.w	#$8083,d1                       ; $8083 exg
	beq.s	.exg_divide
	cmpi.w	#$8064,d1                       ; $8064 subtract
	bne.s	optimise_var_operand_no_change
	cmpi.w	#$8078,d1                       ; d1 cannot also be $8078: this case is never taken
	bne.s	optimise_var_operand_no_change
	move.w	#$80dd,d0                       ; w = w - d0 -> $80dd (never reached)
	bra.s	rewrite_var_op_assign_swapped
.exg_divide:
	cmpi.w	#$805f,d2                       ; $8083 $805f: w = w / d0?
	bne.w	optimise_next
	move.w	#$80df,d0                       ; -> $80df
	bra.s	rewrite_var_op_assign_swapped
.mul_into_var:
	move.w	#$80de,d0                       ; w = w * d0 -> $80de
	bra.s	rewrite_var_op_assign
.add_into_var:
	move.w	#$80dc,d0                       ; w = w + d0 -> $80dc

;------------------------------------------------------------------------------
; Writes op-assign code d0 over the operator and deletes 6 bytes.
;------------------------------------------------------------------------------
rewrite_var_op_assign:
	move.w	d0,-$4(a4)                      ; op-assign code over the $8084/$808d/$8099/$805d
	addq.l	#6,a4                           ; a4 past the store
	bra.w	ir_delete_six_bytes             ; drop 'w op store w'... leaves code w

;------------------------------------------------------------------------------
; Writes op-assign code d0 over the operator and deletes 8 bytes (the exg form).
;------------------------------------------------------------------------------
rewrite_var_op_assign_swapped:
	move.w	d0,-$4(a4)                      ; op-assign code over the operand-form load
	addq.l	#8,a4                           ; a4 past the store
	bra.w	ir_delete_eight_bytes           ; drop 'w $8083 op store w'... leaves code w

;------------------------------------------------------------------------------
; Shared exit: no rewrite.
;------------------------------------------------------------------------------
optimise_var_operand_no_change:
	bra.w	optimise_next

;------------------------------------------------------------------------------
; Word version of optimise_long_var_operand ($808d w, store $8043, codes $80e0-$80e3); same never-true $80e1 test.
;------------------------------------------------------------------------------
optimise_word_var_operand:
	move.w	(a4)+,d0                        ; d0 = w
	movem.w	(a4),d1-d4                      ; d1 = op, d2-d4 = the next IR words
	cmpi.w	#$8043,d2                       ; store $8043 right after op?
	bne.s	.store_after_word_exg
	cmp.w	d0,d3                           ; into w itself?
	bne.s	optimise_var_operand_no_change
	cmpi.w	#$8063,d1                       ; $8063 add
	beq.s	.add_into_word_var
	cmpi.w	#$805e,d1                       ; $805e multiply
	beq.s	.mul_into_word_var
	cmpi.w	#$814c,d1                       ; $814c word add
	beq.s	.add_into_word_var
	cmpi.w	#$814e,d1                       ; $814e word multiply
	beq.s	.mul_into_word_var
	bra.s	optimise_var_operand_no_change
.store_after_word_exg:
	cmpi.w	#$8043,d3                       ; 'op $8043 w' after a $8083 exg?
	bne.s	optimise_var_operand_no_change
	cmp.w	d0,d4                           ; into w itself?
	bne.s	optimise_var_operand_no_change
	cmpi.w	#$8083,d1                       ; $8083 exg
	beq.s	.word_exg_divide
	cmpi.w	#$8064,d1                       ; $8064 subtract
	bne.s	optimise_var_operand_no_change
	cmpi.w	#$8078,d1                       ; never true (d1 is $8064 here)
	bne.s	optimise_var_operand_no_change
	move.w	#$80e1,d0                       ; -> $80e1 (never reached)
	bra.s	rewrite_var_op_assign_swapped
.word_exg_divide:
	cmpi.w	#$805f,d2                       ; $8083 $805f: w = w / d0?
	bne.w	optimise_next
	move.w	#$80e3,d0                       ; -> $80e3
	bra.s	rewrite_var_op_assign_swapped
.mul_into_word_var:
	move.w	#$80e2,d0                       ; w = w * d0 -> $80e2
	bra.s	rewrite_var_op_assign
.add_into_word_var:
	move.w	#$80e0,d0                       ; w = w + d0 -> $80e0
	bra.s	rewrite_var_op_assign

;------------------------------------------------------------------------------
; Byte version of optimise_long_var_operand ($8099 w, store $8044, codes $80e4-$80e7); same never-true $80e5 test.
;------------------------------------------------------------------------------
optimise_byte_var_operand:
	move.w	(a4)+,d0                        ; d0 = w
	movem.w	(a4),d1-d4                      ; d1 = op, d2-d4 = the next IR words
	cmpi.w	#$8044,d2                       ; store $8044 right after op?
	bne.s	.store_after_byte_exg
	cmp.w	d0,d3                           ; into w itself?
	bne.s	optimise_var_operand_no_change
	cmpi.w	#$8063,d1                       ; $8063 add
	beq.s	.add_into_byte_var
	cmpi.w	#$805e,d1                       ; $805e multiply
	beq.s	.mul_into_byte_var
	cmpi.w	#$814c,d1                       ; $814c word add
	beq.s	.add_into_byte_var
	cmpi.w	#$814e,d1                       ; $814e word multiply
	beq.s	.mul_into_byte_var
	bra.w	optimise_var_operand_no_change
.store_after_byte_exg:
	cmpi.w	#$8044,d3                       ; 'op $8044 w' after a $8083 exg?
	bne.w	optimise_var_operand_no_change
	cmp.w	d0,d4                           ; into w itself?
	bne.w	optimise_var_operand_no_change
	cmpi.w	#$8083,d1                       ; $8083 exg
	beq.s	.byte_exg_divide
	cmpi.w	#$8064,d1                       ; $8064 subtract
	bne.w	optimise_var_operand_no_change
	cmpi.w	#$8078,d1                       ; never true (d1 is $8064 here)
	bne.w	optimise_var_operand_no_change
	move.w	#$80e5,d0                       ; -> $80e5 (never reached)
	bra.w	rewrite_var_op_assign_swapped
.byte_exg_divide:
	cmpi.w	#$805f,d2                       ; $8083 $805f: w = w / d0?
	bne.w	optimise_next
	move.w	#$80e7,d0                       ; -> $80e7
	bra.w	rewrite_var_op_assign_swapped
.mul_into_byte_var:
	move.w	#$80e6,d0                       ; w = w * d0 -> $80e6
	bra.w	rewrite_var_op_assign
.add_into_byte_var:
	move.w	#$80e4,d0                       ; w = w + d0 -> $80e4
	bra.w	rewrite_var_op_assign

;------------------------------------------------------------------------------
; Optimiser handler for IR $805d v op (float variable v as operand): followed by '$8041 v' (store into v) becomes
; the float op-assign $80d8 (+), $80d9 (-), $80da (*), $80db (/).
;------------------------------------------------------------------------------
optimise_float_var_operand:
	move.w	(a4)+,d0                        ; d0 = v
	movem.w	(a4),d1-d3                      ; d1 = op, d2/d3 = the next IR words
	cmpi.w	#$8041,d2                       ; followed by $8041 (store float var)...
	bne.w	optimise_next
	cmp.w	d0,d3                           ; ...into v itself?
	bne.w	optimise_next
	cmpi.w	#$804a,d1                       ; $804a add
	beq.s	.float_add_into_var
	cmpi.w	#$804d,d1                       ; $804d multiply
	beq.s	.float_mul_into_var
	cmpi.w	#$804c,d1                       ; $804c reverse subtract (v - d0)
	beq.s	.float_sub_into_var
	cmpi.w	#$804f,d1                       ; $804f reverse divide (v / d0)
	beq.s	.float_div_into_var
	bra.w	optimise_next
.float_mul_into_var:
	move.w	#$80da,d0                       ; v = v * d0 -> $80da
	bra.w	rewrite_var_op_assign
.float_add_into_var:
	move.w	#$80d8,d0                       ; v = v + d0 -> $80d8
	bra.w	rewrite_var_op_assign
.float_div_into_var:
	move.w	#$80db,d0                       ; v = v / d0 -> $80db
	bra.w	rewrite_var_op_assign
.float_sub_into_var:
	move.w	#$80d9,d0                       ; v = v - d0 -> $80d9
	bra.w	rewrite_var_op_assign

;------------------------------------------------------------------------------
; Optimiser handler for IR $8063 (add): becomes $814c (add.w) when only the low word of the result is used.
;------------------------------------------------------------------------------
optimise_int_add:
	move.w	#$814c,d0                       ; $814c add.w
	bra.s	use_word_operator_if_word_result

;------------------------------------------------------------------------------
; Optimiser handler for IR $8064 (sub): becomes $814d when only the low word of the result is used.
;------------------------------------------------------------------------------
optimise_int_sub:
	move.w	#$814d,d0                       ; $814d sub.w
	bra.s	use_word_operator_if_word_result

;------------------------------------------------------------------------------
; Optimiser handler for IR $805e (multiply): becomes $814e when only the low word of the result is used.
;------------------------------------------------------------------------------
optimise_int_mul:
	move.w	#$814e,d0                       ; $814e muls.w

;------------------------------------------------------------------------------
; Common part: writes d0 over the operator when the next IR word is a word or byte use: $8043 (store word var),
; $80e0-$80e7, $8027, $802f, $8030, $802e.
;------------------------------------------------------------------------------
use_word_operator_if_word_result:
	move.w	(a4),d1                         ; d1 = the IR word after the operator
	cmpi.w	#$8043,d1                       ; $8043 store word var
	beq.s	.use_word_operator
	cmpi.w	#$80e0,d1                       ; $80e0-$80e7 word / byte var op-assign
	beq.s	.use_word_operator
	cmpi.w	#$80e1,d1
	beq.s	.use_word_operator
	cmpi.w	#$80e2,d1
	beq.s	.use_word_operator
	cmpi.w	#$80e3,d1
	beq.s	.use_word_operator
	cmpi.w	#$80e4,d1
	beq.s	.use_word_operator
	cmpi.w	#$80e5,d1
	beq.s	.use_word_operator
	cmpi.w	#$80e6,d1
	beq.s	.use_word_operator
	cmpi.w	#$80e7,d1
	beq.s	.use_word_operator
	cmpi.w	#$8027,d1                       ; $8027 push word d0
	beq.s	.use_word_operator
	cmpi.w	#$802f,d1                       ; $802f ext.w (sign-extend word)
	beq.s	.use_word_operator
	cmpi.w	#$8030,d1                       ; $8030 zero-extend word
	beq.s	.use_word_operator
	cmpi.w	#$802e,d1                       ; $802e zero-extend byte
	beq.s	.use_word_operator
	bra.w	optimise_next                   ; long result needed: keep
.use_word_operator:
	move.w	d0,-$2(a4)                      ; word operator over the long one
	bra.w	optimise_restart                ; pass changed: start again

;------------------------------------------------------------------------------
; Optimiser handler for IR $803c v: a following $802f is deleted; NOT ($8032) before a branch $80bf/$80c0 is folded into
; the branch (eor $7f swaps $80bf and $80c0), which is only right for 0/-1 values, so $803c is probably a boolean load.
;------------------------------------------------------------------------------
optimise_load_boolean_var:
	move.w	(a4)+,d3                        ; d3 = variable number
	move.w	(a4)+,d1                        ; d1 = next IR word
	cmpi.w	#$802f,d1                       ; $802f ext.w: redundant
	beq.s	.delete_next_word
	cmpi.w	#$8032,d1                       ; $8032 NOT d0...
	bne.s	.no_boolean_fold
	cmpi.w	#$80bf,(a4)                     ; ...before $80bf jump if false
	beq.s	.invert_branch
	cmpi.w	#$80c0,(a4)                     ; ...or $80c0 jump if true?
	bne.s	.no_boolean_fold
.invert_branch:
	eori.w	#$7f,(a4)                       ; $80bf <-> $80c0
.delete_next_word:
	bra.w	ir_delete_two_bytes             ; drop the $802f / $8032
.no_boolean_fold:
	bra.w	optimise_reread

;------------------------------------------------------------------------------
; Optimiser handler for IR $803b v (load string variable) followed by $8018 (save the string for a later operand):
; when the saved string is popped by $8022 (into a0) or $8023 (into a1), '$803b v $8018' is removed and the pop becomes
; $803b v / $81ff v (string variable address into a1), so the variable is read where it is used.
;------------------------------------------------------------------------------
optimise_ir_803b:
	move.w	(a4)+,d3                        ; d3 = string variable
	move.w	(a4)+,d1                        ; d1 = next IR word
	cmpi.w	#$8018,d1                       ; $8018: the string is saved for later
	bne.s	.no_string_var_fold
	bsr.w	measure_ir_operand              ; find where it is popped; a2 = after the pop
	not.l	d0                              ; d0 = -1: the operand cannot be followed
	beq.s	.no_string_var_fold
	move.w	-$2(a2),d1                      ; d1 = the popping IR code
	move.w	#$803b,d0                       ; popped by $8022 (into a0): load $803b there
	cmpi.w	#$8022,d1
	beq.s	.move_load_to_pop
	move.w	#$81ff,d0                       ; popped by $8023 (into a1): $81ff (address into a1)
	cmpi.w	#$8023,d1
	bne.s	.no_string_var_fold
.move_load_to_pop:
	move.w	d0,-(sp)                        ; save the replacement code
	movea.l	a4,a0                           ; delete '$803b v $8018'
	moveq	#6,d0
	bsr.w	ir_delete_bytes
	suba.w	d0,a2                           ; a2 follows the deletion
	subq.l	#2,a2                           ; a2 = at the pop word
	moveq	#2,d0                           ; room for the variable number
	movea.l	a2,a0
	bsr.w	ir_insert_bytes
	move.w	(sp)+,(a2)+                     ; replacement code over the pop
	move.w	d3,(a2)+                        ; then the variable
	bra.w	optimise_restart                ; pass changed: start again
.no_string_var_fold:
	bra.w	optimise_reread
ext_l_d1_code_address:
	dc.w	$0000,$0000                     ; address where the last ext.l d1 was written (set at $c12a, checked
                                                ;   before muls/divs)

;------------------------------------------------------------------------------
; Code generator main loop: walks the IR buffer ir_buffer and writes 68000 code through a1 (from
; statement_code_buffer). Clears ext_l_d0_code_address, ext_l_d1_code_address, ext_w_d0_code_address and
; previous_ir_code; previous_ir_code / current_ir_code follow the IR codes. Negative words dispatch through
; codegen_dispatch_table with a0 just after the code; positive words are library routine numbers and become a call
; (emit_library_call). Ends at a zero word.
;------------------------------------------------------------------------------
generate_code:
	clr.l	ext_l_d0_code_address           ; no ext.l d0 recorded yet
	clr.l	ext_l_d1_code_address           ; no ext.l d1 recorded yet
	clr.l	ext_w_d0_code_address           ; no ext.w d0 recorded yet
	clr.l	previous_ir_code
	lea	ir_buffer,a0                    ; a0 = IR read pointer, a1 = code output
	lea	statement_code_buffer,a1
.next_ir_word:
	moveq	#0,d0                           ; zero-extended for the table index
	move.w	(a0)+,d0                        ; d0 = next IR word
	move.w	current_ir_code,previous_ir_code ; previous IR code
	move.w	d0,current_ir_code              ; current IR code
	beq.s	.done                           ; 0: end of the IR
	bpl.s	.library_call                   ; positive: a library routine number
	add.w	d0,d0                           ; $8xxx * 2: the low bits index the table
	lea	codegen_dispatch_table(pc,d0.w),a2 ; a2 = the table entry
	adda.w	(a2),a2                         ; a2 = the handler
	jsr	(a2)                            ; a0 = just after the IR code
	bra.s	.next_ir_word                   ; next IR word
.library_call:
	bsr.w	emit_library_call               ; library routine: emit the call
	bra.s	.next_ir_word
.done:
	rts                                     ; done
codegen_dispatch_table:
	dc.w	emit_float_constant-codegen_dispatch_table ; handlers for IR $8000-$81ff, offsets from this table
	dc.w	emit_float_constant_operand-(codegen_dispatch_table+2)
	dc.w	emit_save_float_accumulator-(codegen_dispatch_table+4)
	dc.w	emit_pop_float_accumulator-(codegen_dispatch_table+6)
	dc.w	emit_pop_float_operand-(codegen_dispatch_table+8)
	dc.w	gen_float_to_integer-(codegen_dispatch_table+10)
	dc.w	gen_integer_to_float-(codegen_dispatch_table+12)
	dc.w	gen_int_constant-(codegen_dispatch_table+14)
	dc.w	emit_int_constant_operand-(codegen_dispatch_table+16)
	dc.w	load_constant_d2-(codegen_dispatch_table+18)
	dc.w	load_constant_d3-(codegen_dispatch_table+20)
	dc.w	load_constant_d4-(codegen_dispatch_table+22)
	dc.w	load_constant_d5-(codegen_dispatch_table+24)
	dc.w	load_constant_d6-(codegen_dispatch_table+26)
	dc.w	load_constant_d7-(codegen_dispatch_table+28)
	dc.w	gen_load_constant_a0-(codegen_dispatch_table+30)
	dc.w	gen_load_constant_a1-(codegen_dispatch_table+32)
	dc.w	gen_float_double-(codegen_dispatch_table+34)
	dc.w	gen_double_d0-(codegen_dispatch_table+36)
	dc.w	gen_float_square-(codegen_dispatch_table+38)
	dc.w	gen_integer_square-(codegen_dispatch_table+40)
	dc.w	gen_call_a0-(codegen_dispatch_table+42)
	dc.w	gen_call_with_parameter_block-(codegen_dispatch_table+44)
	dc.w	gen_push_d0-(codegen_dispatch_table+46)
	dc.w	gen_save_string_operand-(codegen_dispatch_table+48)
	dc.w	gen_push_a1-(codegen_dispatch_table+50)
	dc.w	gen_pop_d0-(codegen_dispatch_table+52)
	dc.w	gen_pop_d1-(codegen_dispatch_table+54)
	dc.w	gen_pop_d2-(codegen_dispatch_table+56)
	dc.w	gen_pop_d3-(codegen_dispatch_table+58)
	dc.w	gen_pop_d4-(codegen_dispatch_table+60)
	dc.w	gen_pop_d5-(codegen_dispatch_table+62)
	dc.w	gen_pop_d6-(codegen_dispatch_table+64)
	dc.w	gen_pop_d7-(codegen_dispatch_table+66)
	dc.w	gen_pop_a0-(codegen_dispatch_table+68)
	dc.w	gen_pop_a1-(codegen_dispatch_table+70)
	dc.w	gen_gemdos_call-(codegen_dispatch_table+72)
	dc.w	gen_bios_call-(codegen_dispatch_table+74)
	dc.w	gen_xbios_call-(codegen_dispatch_table+76)
	dc.w	gen_push_word_d0-(codegen_dispatch_table+78)
	dc.w	gen_no_code-(codegen_dispatch_table+80)
	dc.w	gen_store_bool_var_tested-(codegen_dispatch_table+82)
	dc.w	gen_draw_call-(codegen_dispatch_table+84)
	dc.w	gen_drawto_call-(codegen_dispatch_table+86)
	dc.w	gen_float_sgn-(codegen_dispatch_table+88)
	dc.w	gen_float_negate-(codegen_dispatch_table+90)
