;------------------------------------------------------------------------------
; '$8007 c $8006': the integer constant d0 is converted to float (int_to_float) and emitted as a float constant.
;------------------------------------------------------------------------------
emit_int_constant_as_float:
	bsr.w	int_to_float                    ; d0 -> float d0/d1/d2
	move.w	d1,d6                           ; d6 = mantissa low word
	move.w	d2,d7                           ; d7 = exponent
	bra.s	emit_float_value

;------------------------------------------------------------------------------
; Codegen for IR $8000 c (float constant value). Reads mantissa d0, low word d6, exponent d7.
; Then: next $8041 (store float var) -> gen_constant_store_float_var; $80d8 with 1.0 -> gen_float_var_increment
; (FADDQ1V); next $8002 (push) -> two pushes of the constant; 0.0 -> moveq #0,d2 only; else load d0/d1/d2.
;------------------------------------------------------------------------------
emit_float_constant:
	move.l	(a0)+,d0                        ; d0 = mantissa long
	move.w	(a0)+,d6                        ; d6 = mantissa low word
	move.w	(a0)+,d7                        ; d7 = exponent word

;------------------------------------------------------------------------------
; Common part of the float constant codegen, constant in d0/d6/d7.
;------------------------------------------------------------------------------
emit_float_value:
	cmpi.w	#$8041,(a0)                     ; store into a float variable
	beq.w	gen_constant_store_float_var
	cmpi.w	#$80d8,(a0)                     ; float var += 1.0?
	bne.s	.not_increment
	tst.w	d6                              ; 1.0: low word 0...
	bne.s	.not_increment
	cmpi.w	#$3ff,d7                        ; ...exponent $3ff...
	bne.s	.not_increment
	cmpi.l	#$80000000,d0                   ; ...mantissa $80000000
	bne.s	.not_increment
	addq.l	#2,a0                           ; a0 past the $80d8
	bra.w	gen_float_var_increment         ; FADDQ1V: increment in place
.not_increment:
	cmpi.w	#$8002,(a0)                     ; $8002 (save float accumulator) next?
	beq.s	.push_constant
	tst.w	d7                              ; 0.0?
	bne.s	.load_float_registers
	move.w	#$7400,(a1)+                    ; moveq #0,d2: exponent 0 is enough for 0.0
	rts
.push_constant:
	addq.l	#2,a0                           ; a0 past the $8002
	bsr.w	emit_push_constant_long         ; push the mantissa long
	move.w	d6,d0                           ; low word and exponent in one long
	swap	d0
	move.w	d7,d0
	bra.w	emit_push_constant_long         ; push low word and exponent
.load_float_registers:
	moveq	#0,d2                           ; d2 = 0: register d0
	bsr.w	emit_load_constant_dreg         ; d0 = mantissa
	moveq	#1,d2                           ; register d1
	move.w	d6,d0
	bsr.w	emit_load_word_constant         ; d1 = low word
	moveq	#2,d2                           ; register d2
	move.w	d7,d0
	bra.w	emit_load_word_constant         ; d2 = exponent

;------------------------------------------------------------------------------
; Float multiply by a power of two 2^n (constant exponent d5, mantissa $80000000). Negative constant: neg.w d2 first.
; n = 0: nothing; n = 1: library $28f DOUBLE; else moveq/move.w #n,d3 + library $237 MUL2P; n < 0: $291 HALF / $238
; DIV2P.
;------------------------------------------------------------------------------
emit_float_mul_power_of_two:
	move.w	d5,d0                           ; d0 = exponent word of the constant
	bpl.s	.positive_exponent              ; positive constant
	move.w	#$4442,(a1)+                    ; neg.w d2 (negates the float)
	neg.w	d5                              ; the exponent itself
.positive_exponent:
	move.w	#$3ff,d6                        ; d6 = exponent - $3ff = the power n
	sub.w	d5,d6
	neg.w	d6

;------------------------------------------------------------------------------
; Emits the scaling for d6 = power of two (flags from d6).
;------------------------------------------------------------------------------
emit_float_scale_by_power_of_two:
	beq.s	.no_scaling                     ; n = 0: x * 1
	bmi.s	emit_float_scale_down           ; n < 0: scale down
	cmpi.w	#$7f,d6                         ; n above $7f: needs a word count
	bhi.s	.word_count
	cmpi.b	#$1,d6                          ; n = 1: DOUBLE
	beq.s	.call_double
	move.b	#$76,(a1)+                      ; moveq #n,d3
	move.b	d6,(a1)+                        ; the count
.call_mul2p:
	move.w	#$237,d0                        ; library $237 MUL2P
	bra.w	emit_library_call
.word_count:
	move.w	#$363c,(a1)+                    ; move.w #n,d3
	move.w	d6,(a1)+                        ; the count
	bra.s	.call_mul2p
.call_double:
	move.w	#$28f,d0                        ; library $28f DOUBLE
	bra.w	emit_library_call
.no_scaling:
	rts

;------------------------------------------------------------------------------
; Float divide by a power of two: as emit_float_mul_power_of_two with the shift reversed.
;------------------------------------------------------------------------------
emit_float_div_power_of_two:
	move.w	d5,d0                           ; d0 = exponent word of the constant
	bpl.s	.positive_divisor_exponent      ; positive constant
	move.w	#$4442,(a1)+                    ; neg.w d2 (negates the float)
	neg.w	d5                              ; the exponent itself
.positive_divisor_exponent:
	move.w	#$3ff,d6                        ; d6 = $3ff - exponent = -n
	sub.w	d5,d6                           ; and scale by 2^-n
	bra.s	emit_float_scale_by_power_of_two

;------------------------------------------------------------------------------
; Emits the scaling down by 2^-d6: library $291 HALF for 1, else d3 = count and $238 DIV2P.
;------------------------------------------------------------------------------
emit_float_scale_down:
	neg.w	d6                              ; d6 = the count
	cmpi.w	#$7f,d6                         ; above $7f: needs a word count
	bhi.s	.word_divide_count
	cmpi.b	#$1,d6                          ; 1: HALF
	beq.s	.call_half
	move.b	#$76,(a1)+                      ; moveq #n,d3
	move.b	d6,(a1)+                        ; the count
.call_div2p:
	move.w	#$238,d0                        ; library $238 DIV2P
	bra.w	emit_library_call
.word_divide_count:
	move.w	#$363c,(a1)+                    ; move.w #n,d3
	move.w	d6,(a1)+                        ; the count
	bra.s	.call_div2p
.call_half:
	move.w	#$291,d0                        ; library $291 HALF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Float add of a constant: +1.0 -> library 52 FADDQ1, -1.0 -> library 53 FSUBQ1, else the general path.
;------------------------------------------------------------------------------
emit_float_add_constant:
	tst.w	d4                              ; low word of the constant must be 0
	bne.w	emit_float_constant_operand_general
	cmpi.l	#$80000000,d3                   ; mantissa $80000000
	bne.w	emit_float_constant_operand_general
	cmpi.w	#$3ff,d5                        ; exponent $3ff = +1.0
	beq.s	.add_one
	cmpi.w	#$fc01,d5                       ; exponent $fc01 = -1.0
	bne.w	emit_float_constant_operand_general
	moveq	#53,d0                          ; FSUBQ1
	bra.w	emit_library_call
.add_one:
	moveq	#52,d0                          ; FADDQ1
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Float compare with a constant, $805a =: d2 = 7 (EQ).
;------------------------------------------------------------------------------
float_compare_eq_constant:
	moveq	#7,d2
	bra.s	emit_float_compare_constant

;------------------------------------------------------------------------------
; Float compare with a constant, $805b <>: d2 = 6 (NE).
;------------------------------------------------------------------------------
float_compare_ne_constant:
	moveq	#6,d2
	bra.s	emit_float_compare_constant

;------------------------------------------------------------------------------
; Float compare with a constant, $8056 >: d2 = 14 (GT).
;------------------------------------------------------------------------------
float_compare_gt_constant:
	moveq	#14,d2
	bra.s	emit_float_compare_constant

;------------------------------------------------------------------------------
; Float compare with a constant, $8057 >=: d2 = 12 (GE).
;------------------------------------------------------------------------------
float_compare_ge_constant:
	moveq	#12,d2
	bra.s	emit_float_compare_constant

;------------------------------------------------------------------------------
; Float compare with a constant, $8058 <: d2 = 13 (LT).
;------------------------------------------------------------------------------
float_compare_lt_constant:
	moveq	#13,d2
	bra.s	emit_float_compare_constant

;------------------------------------------------------------------------------
; Float compare with a constant, $8059 <=: d2 = 15 (LE).
;------------------------------------------------------------------------------
float_compare_le_constant:
	moveq	#15,d2

;------------------------------------------------------------------------------
; Inline float compare of d0/d1/d2 with the constant d3/d4/d5, d2 = condition code. Result Scc d0, then
; finish_condition_result.
; Constant 0.0: tst.w d2 (or, when the float was just loaded through a0, only the exponent is read: move.w 6(a0),d2 or
; move.w d+6(a5),d2). Power of two (low word 0, mantissa $80000000): = / <> write cmpi.w #exp,d2 / bne.s / tst.w d1 /
; bne.s / add.l d0,d0 / Scc; >= and < compare only the exponent (cmpi.w #exp,d2 or against memory) / sge or slt.
; Anything else goes to the general constant operand code.
;------------------------------------------------------------------------------
emit_float_compare_constant:
	tst.w	d5                              ; constant 0.0?
	beq.s	.float_compare_zero
	tst.w	d4                              ; low word must be 0 for the short forms
	bne.w	.low_word_not_zero
	add.l	d3,d3                           ; mantissa exactly $80000000?
	bne.w	.general_constant
	cmpi.w	#$7,d2                          ; $7 EQ
	beq.s	.compare_eq_power_of_two
	cmpi.w	#$6,d2                          ; $6 NE
	beq.s	.compare_eq_power_of_two
	cmpi.w	#$c,d2                          ; $c GE
	beq.s	.compare_ge_power_of_two
	cmpi.w	#$d,d2                          ; $d LT
	beq.w	.compare_lt_power_of_two
	bra.w	.general_constant               ; GT and LE: general code
.float_compare_zero:
	bsr.w	float_just_loaded_via_a0        ; float operand just loaded through a0?
	bne.s	.test_exponent                  ; no: tst.w d2
	subq.l	#6,a1                           ; drop the last 3 words of the load
	cmpi.w	#$41ed,-$4(a1)                  ; lea d(a5),a0?
	bne.s	.exponent_via_a0
	move.w	#$342d,-$4(a1)                  ; move.w d+6(a5),d2: exponent only
	addq.w	#6,-$2(a1)                      ; displacement + 6: the exponent word
	bra.s	.write_scc                      ; Scc after it
.exponent_via_a0:
	move.l	#$34280006,(a1)+                ; move.w 6(a0),d2
	bra.s	.write_scc
.test_exponent:
	move.w	#$4a42,(a1)+                    ; tst.w d2
.write_scc:
	rol.w	#8,d2                           ; Scc d0 ($50c0 + cc<<8)
	ori.w	#$50c0,d2                       ; Scc d0
	move.w	d2,(a1)+
	bra.w	finish_condition_result
.compare_eq_power_of_two:
	move.w	#$c42,(a1)+                     ; cmpi.w #exp,d2
	move.w	d5,(a1)+
	move.w	#$6606,(a1)+                    ; bne.s +6
	move.l	#$4a416602,(a1)+                ; tst.w d1 / bne.s +2
	move.w	#$d080,(a1)+                    ; add.l d0,d0: zero only for mantissa $80000000
	ror.w	#8,d2                           ; Scc d0 ($50c0 + cc<<8)
	ori.w	#$50c0,d2
	move.w	d2,(a1)+
	bra.w	finish_condition_result         ; then the common condition-result code
.compare_ge_power_of_two:
	bsr.s	float_just_loaded_via_a0        ; float just loaded through a0?
	bne.s	.ge_compare_d2                  ; no: compare d2
	subq.l	#6,a1                           ; drop the last 3 words of the load
	cmpi.w	#$41ed,-$4(a1)                  ; lea d(a5),a0?
	bne.s	.ge_compare_via_a0              ; no: the load was through a0 itself
	move.w	-(a1),d0                        ; d0 = the displacement; a1 back to it
	addq.w	#6,d0                           ; + 6: the exponent word
	move.w	#$c6d,-$2(a1)                   ; cmpi.w #exp,d+6(a5)
	move.w	d5,(a1)+                        ; the exponent
	move.w	d0,(a1)+                        ; the displacement
	bra.s	.write_sge                      ; then sge
.ge_compare_via_a0:
	move.w	#$c68,(a1)+                     ; cmpi.w #exp,6(a0)
	move.w	d5,(a1)+                        ; the exponent
	move.w	#$6,(a1)+                       ; displacement 6
	bra.s	.write_sge
.ge_compare_d2:
	move.w	#$c42,(a1)+                     ; cmpi.w #exp,d2
	move.w	d5,(a1)+                        ; the exponent
.write_sge:
	move.w	#$5cc0,(a1)+                    ; sge d0
	bra.w	finish_condition_result
.compare_lt_power_of_two:
	bsr.s	float_just_loaded_via_a0        ; float just loaded through a0?
	bne.s	.lt_compare_d2                  ; no: compare d2
	subq.l	#6,a1                           ; drop the last 3 words of the load
	cmpi.w	#$41ed,-$4(a1)                  ; lea d(a5),a0?
	bne.s	.lt_compare_via_a0              ; no: the load was through a0 itself
	move.w	-(a1),d0                        ; d0 = the displacement; a1 back to it
	addq.w	#6,d0                           ; + 6: the exponent word
	move.w	#$c6d,-$2(a1)                   ; cmpi.w #exp,d+6(a5) over the lea
	move.w	d5,(a1)+                        ; the exponent
	move.w	d0,(a1)+                        ; the displacement
	bra.s	.write_slt                      ; then slt
.lt_compare_via_a0:
	move.w	#$c68,(a1)+                     ; cmpi.w #exp,6(a0)
	move.w	d5,(a1)+                        ; the exponent
	move.w	#$6,(a1)+                       ; displacement 6
	bra.s	.write_slt
.lt_compare_d2:
	move.w	#$c42,(a1)+                     ; cmpi.w #exp,d2
	move.w	d5,(a1)+                        ; the exponent
.write_slt:
	move.w	#$5dc0,(a1)+                    ; slt d0
	bra.w	finish_condition_result
.general_constant:
	roxr.l	#1,d3                           ; undo the add.l d3,d3
.low_word_not_zero:
	bra.s	emit_float_constant_operand_general ; load d3-d5 and the operator's own code

;------------------------------------------------------------------------------
; Z when the previous IR was $803e or $80c5 and the last two words written are move.w (a0)+,d1 / move.w (a0)+,d2
; ($3218 $3418), i.e. the float operand was just loaded through a0.
;------------------------------------------------------------------------------
float_just_loaded_via_a0:
	cmpi.w	#$803e,previous_ir_code         ; previous IR $803e (load float var)?
	beq.s	.check_load_words
	cmpi.w	#$80c5,previous_ir_code         ; or $80c5 (float array element)?
	bne.s	.return_flags
.check_load_words:
	cmpi.l	#$32183418,-$4(a1)              ; Z when the code ends move.w (a0)+,d1 / move.w (a0)+,d2
.return_flags:
	rts                                     ; Z: the operand was just loaded through a0

;------------------------------------------------------------------------------
; Codegen for IR $8001 c op (float constant as right operand). d3/d4/d5 = constant, d0 = operator.
; Comparisons go to the inline compares; + to emit_float_add_constant; * and / by a power of two to the scaling code;
; else the constant is loaded into d3/d4/d5 and a0 is left on the operator for its own handler.
;------------------------------------------------------------------------------
emit_float_constant_operand:
	move.l	(a0)+,d3                        ; d3 = mantissa long
	move.w	(a0)+,d4                        ; d4 = mantissa low word
	move.w	(a0)+,d5                        ; d5 = exponent word
	move.w	(a0)+,d0                        ; d0 = the float operator
	cmpi.w	#$805a,d0                       ; $805a =
	beq.w	float_compare_eq_constant
	cmpi.w	#$805b,d0                       ; $805b <>
	beq.w	float_compare_ne_constant
	cmpi.w	#$8058,d0                       ; $8058 <
	beq.w	float_compare_lt_constant
	cmpi.w	#$8059,d0                       ; $8059 <=
	beq.w	float_compare_le_constant
	cmpi.w	#$8056,d0                       ; $8056 >
	beq.w	float_compare_gt_constant
	cmpi.w	#$8057,d0                       ; $8057 >=
	beq.w	float_compare_ge_constant
	cmpi.w	#$804a,d0                       ; $804a float add
	beq.w	emit_float_add_constant

;------------------------------------------------------------------------------
; General float constant operand: loads the constant into d3/d4/d5 (moveq #0,d5 for 0.0). With a zero low word and an
; operator in float_op_constant_routines the operator is replaced by its '0' library routine and d4 is not loaded.
;------------------------------------------------------------------------------
emit_float_constant_operand_general:
	tst.w	d4                              ; low word 0 and...
	bne.s	.not_power_of_two
	cmpi.l	#$80000000,d3                   ; ...mantissa $80000000: a power of two
	bne.s	.not_power_of_two
	cmpi.w	#$804d,d0                       ; $804d *
	beq.w	emit_float_mul_power_of_two
	cmpi.w	#$804e,d0                       ; $804e /
	beq.w	emit_float_div_power_of_two
.not_power_of_two:
	subq.l	#2,a0                           ; back to the operator word
	tst.w	d5                              ; 0.0?
	bne.s	.load_constant                  ; no: load it
	move.w	#$7a00,(a1)+                    ; moveq #0,d5
	rts
.load_constant:
	tst.w	d4                              ; low word 0?
	bne.s	.load_d3_d4_d5                  ; no: load all three
	move.w	(a0),d0                         ; d0 = the operator
	lea	float_op_constant_routines(pc),a2 ; operators that have a short-constant form
	moveq	#7,d1                           ; 8 entries
.find_operator:
	cmp.w	(a2)+,d0
	dbeq	d1,.find_operator               ; find it in the list
	beq.s	.use_short_constant_routine
.load_d3_d4_d5:
	move.l	d3,d0
	moveq	#3,d2                           ; register d3
	bsr.w	emit_load_constant_dreg
	moveq	#4,d2                           ; register d4
	move.w	d4,d0
	bsr.w	emit_load_word_constant
	moveq	#5,d2                           ; register d5
	move.w	d5,d0
	bra.w	emit_load_word_constant
.use_short_constant_routine:
	move.w	$e(a2),(a0)                     ; replace the operator by the matching '0' routine
	move.l	d3,d0                           ; mantissa into d3
	moveq	#3,d2                           ; register d3
	bsr.w	emit_load_constant_dreg
	moveq	#5,d2                           ; exponent into d5
	move.w	d5,d0
	bra.w	emit_load_word_constant
float_op_constant_routines:
	dc.w	$01f4,$01f6,$01f7,$01f5,$804a,$804b,$804d,$804e ; 8 operators, then the 8 replacement library routines:
                                                ;   $1f4 FI_DIV $1f6 FI_ADD $1f7 FI_SUB $1f5 FI_MUL $804a $804b $804d
                                                ;   $804e -> $201 FI_DIV0 $203 FI_ADD0 $204 FI_SUB0 $202 FI_MUL0 $207
                                                ;   FADD0 $208 FSUB0 $206 FMUL0 $205 FDIV0
	dc.w	$0201,$0203,$0204,$0202,$0207,$0208,$0206,$0205 ; 8 operators, then the 8 replacement library routines:
                                                ;   $1f4 FI_DIV $1f6 FI_ADD $1f7 FI_SUB $1f5 FI_MUL $804a $804b $804d
                                                ;   $804e -> $201 FI_DIV0 $203 FI_ADD0 $204 FI_SUB0 $202 FI_MUL0 $207
                                                ;   FADD0 $208 FSUB0 $206 FMUL0 $205 FDIV0

;------------------------------------------------------------------------------
; Codegen for IR $8002 (save the float accumulator d0/d1/d2 before the right operand).
; If the right operand up to its $8004 contains only integer constants, integer variables and the integer operators
; $801b,
; $8063, $8064, $8083, $814c, $814d, $805e, $8028 (code that does not touch d3-d5), the $8004 is changed to $7d1e (no
; code) and
; the value is copied: move.l d0,d3 / move.l d1,d4 / move.l d2,d5. Otherwise move.l d0,-(sp) / move.w d2,-(sp) / move.w
; d1,-(sp).
;------------------------------------------------------------------------------
emit_save_float_accumulator:
	movea.l	a0,a2                           ; a2 scans the right operand
.scan_operand:
	move.w	(a2)+,d0                        ; d0 = next IR word
	bpl.w	.push_on_stack                  ; a library call: d3-d5 may be used, push
	cmpi.w	#$8004,d0                       ; $8004 reached: operand is harmless
	beq.s	.keep_in_registers
	cmpi.w	#$8007,d0                       ; $8007 integer constant
	beq.s	.skip_long_operand
	cmpi.w	#$8008,d0                       ; $8008 integer constant operand
	beq.s	.skip_long_operand
	cmpi.w	#$803f,d0                       ; $803f load long var
	beq.s	.skip_word_operand
	cmpi.w	#$8084,d0                       ; $8084 long var into d1
	beq.s	.skip_word_operand
	cmpi.w	#$8040,d0                       ; $8040 load word var
	beq.s	.skip_word_operand
	cmpi.w	#$808d,d0                       ; $808d word var into d1
	beq.s	.skip_word_operand
	cmpi.w	#$803d,d0                       ; $803d load byte var
	beq.s	.skip_word_operand
	cmpi.w	#$8099,d0                       ; $8099 byte var into d1
	beq.s	.skip_word_operand
	cmpi.w	#$801b,d0                       ; $801b pop into d1
	beq.s	.scan_operand
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.scan_operand
	cmpi.w	#$8064,d0                       ; $8064 subtract
	beq.s	.scan_operand
	cmpi.w	#$8083,d0                       ; $8083 exg d0,d1
	beq.s	.scan_operand
	cmpi.w	#$814c,d0                       ; $814c add.w
	beq.s	.scan_operand
	cmpi.w	#$814d,d0                       ; $814d sub.w
	beq.s	.scan_operand
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.scan_operand
	cmpi.w	#$8028,d0                       ; $8028 no code
	beq.s	.scan_operand
	bra.s	.push_on_stack                  ; anything else: push
.skip_long_operand:
	addq.l	#2,a2                           ; skip the constant's second word
.skip_word_operand:
	addq.l	#2,a2                           ; skip the variable number / first word
	bra.s	.scan_operand                   ; next IR word
.keep_in_registers:
	move.w	#$8028,-(a2)                    ; the $8004 now generates nothing
	move.w	#$2600,(a1)+                    ; move.l d0,d3
	move.w	#$2801,(a1)+                    ; move.l d1,d4
	move.w	#$2a02,(a1)+                    ; move.l d2,d5
	rts
.push_on_stack:
	move.w	#$2f00,(a1)+                    ; move.l d0,-(sp)
	move.w	#$3f02,(a1)+                    ; move.w d2,-(sp)
	move.w	#$3f01,(a1)+                    ; move.w d1,-(sp)
	rts

;------------------------------------------------------------------------------
; Codegen for IR $8003: pops the saved float into d0/d1/d2 (move.w (sp)+,d1 / move.w (sp)+,d2 / move.l (sp)+,d0).
;------------------------------------------------------------------------------
emit_pop_float_accumulator:
	move.w	#$321f,(a1)+                    ; move.w (sp)+,d1
	move.w	#$341f,(a1)+                    ; move.w (sp)+,d2
	move.w	#$201f,(a1)+                    ; move.l (sp)+,d0
	rts

;------------------------------------------------------------------------------
; Codegen for IR $8004: pops the saved float into d3/d4/d5 as left operand (move.w (sp)+,d4 / move.w (sp)+,d5 / move.l
; (sp)+,d3).
;------------------------------------------------------------------------------
emit_pop_float_operand:
	move.w	#$381f,(a1)+                    ; move.w (sp)+,d4
	move.w	#$3a1f,(a1)+                    ; move.w (sp)+,d5
	move.w	#$261f,(a1)+                    ; move.l (sp)+,d3
	rts

;------------------------------------------------------------------------------
; Emits a load of the word constant d0 into data register d2: moveq #d0,Dn when it fits a byte, else move.w #d0,Dn.
; The code at $9c40-$9f64 after it has no label and is never called.
;------------------------------------------------------------------------------
emit_load_word_constant:
	move.b	d0,d1                           ; fits a signed byte?
	ext.w	d1
	cmp.w	d0,d1
	bne.s	.word_immediate
	add.b	d2,d2                           ; moveq: $70 + 2*reg in the first byte
	addi.b	#$70,d2
	move.b	d2,(a1)+                        ; moveq opcode byte
	move.b	d0,(a1)+                        ; the value byte
	rts
.word_immediate:
	ror.w	#7,d2                           ; move.w #imm,Dn ($303c + reg<<9)
	ori.w	#$303c,d2
	move.w	d2,(a1)+
	move.w	d0,(a1)+                        ; the word value
	rts
	add.b	d2,d2                           ; unreferenced
	addi.b	#$70,d2                         ; moveq #n,Dn
	move.b	d2,(a1)+
	move.b	d0,(a1)+
	bpl.s	.unreferenced_done              ; positive: done
	not.b	-$1(a1)                         ; negative: moveq #~n, then not.b Dn (zero-extended)
	andi.w	#$7,d2
	ori.w	#$4600,d2                       ; not.b Dn
	move.w	d2,(a1)+
.unreferenced_done:
	rts

;------------------------------------------------------------------------------
; Integer multiply of d0 by the constant d0 (IR $8008 c $805e). After a recorded ext.l d0 and a word constant that is
; not
; a power of two: muls.w #c,d0. Else shifts and adds: 0 -> moveq #0,d0; negative c -> neg.l d0; trailing zero bits ->
; shift;
; odd part 3 / 5 / 2^k+1 / 2^k-1 with a copy in d1 or d2; others by bit runs with add.l d0,d2 / sub.l d0,d2, then add.l
; d2,d0.
; For c = $80000000 the shift by 31 is written twice.
;------------------------------------------------------------------------------
emit_mul_int_constant:
	cmpi.w	#$48c0,-(a1)                    ; last word ext.l d0?
	bne.s	.shift_and_add
	cmpa.l	ext_l_d0_code_address(pc),a1    ; and it is the recorded one
	bne.s	.shift_and_add
	move.w	d0,d1                           ; c fits a word?
	ext.l	d1
	beq.s	.shift_and_add                  ; 0: no muls
	cmp.l	d0,d1                           ; not a word
	bne.s	.shift_and_add
.find_lowest_bit:
	add.w	d1,d1                           ; power of two? (one bit set)
	bcc.s	.find_lowest_bit
	beq.s	.shift_and_add                  ; only one bit: shifts are better
	move.w	#$c1fc,(a1)+                    ; muls.w #c,d0 over the ext.l
	move.w	d0,(a1)+                        ; the factor
	clr.l	ext_l_d0_code_address           ; the ext.l is gone
	rts
.shift_and_add:
	addq.l	#2,a1                           ; undo the -(a1)
	moveq	#1,d7                           ; d7 = 1
	tst.l	d0
	beq.w	.emit_clear_result              ; x * 0: moveq #0,d0
	bpl.s	.count_trailing_zeros           ; positive factor
	neg.l	d0                              ; negative factor
	bpl.s	.negate_result                  ; still negative: $80000000
	moveq	#31,d1                          ; $80000000
	bsr.w	emit_shift_left_result          ; shift by 31 (then once more below)
.negate_result:
	bsr.w	gen_negate_d0                   ; neg.l d0
.count_trailing_zeros:
	moveq	#-1,d1                          ; d1 = number of trailing zero bits
.shift_out_zero:
	addq.l	#1,d1                           ; count it
	lsr.l	#1,d0                           ; shift the factor right
	bcc.s	.shift_out_zero                 ; until a 1 bit drops out
	roxl.l	#1,d0                           ; put the 1 bit back: d0 = odd part
	cmp.l	d7,d0                           ; factor 1 left: only the shift
	beq.w	emit_shift_left_result
	cmpi.l	#$3,d0                          ; odd part 3?
	bne.s	.not_three
	bsr.w	emit_shift_left_result          ; the shift for the trailing zeros
	move.w	#$2200,(a1)+                    ; x*3: move.l d0,d1 / add.l d0,d0 / add.l d1,d0
	move.w	#$d080,(a1)+
	move.w	#$d081,(a1)+
	rts
.not_three:
	cmpi.l	#$5,d0                          ; odd part 5?
	bne.s	.odd_factor
	bsr.w	emit_shift_left_result          ; the shift for the trailing zeros
	move.w	#$2200,(a1)+                    ; x*5: move.l d0,d1 / asl.l #2,d0 / add.l d1,d0
	move.w	#$e580,(a1)+
	move.w	#$d081,(a1)+
	rts
.odd_factor:
	bsr.w	emit_shift_left_result          ; the shift for the trailing zeros
	move.l	d0,d2                           ; d2 = odd part - 1
	subq.l	#1,d2
	moveq	#-1,d1                          ; d1 = log2 of it
.count_zeros_below:
	addq.l	#1,d1
	lsr.l	#1,d2
	bcc.s	.count_zeros_below              ; until the lowest set bit
	bne.s	.not_power_plus_one             ; bits left: not 2^k+1
	move.w	#$2400,(a1)+                    ; 2^k+1: move.l d0,d2 / shift / add.l d2,d0
	bsr.w	emit_shift_left_result          ; shift left by k
	move.w	#$d082,(a1)+
	rts
.not_power_plus_one:
	move.l	d0,d2                           ; d2 = odd part + 1
	addq.l	#1,d2
	moveq	#-1,d1                          ; d1 = log2 of it
.count_zeros_above:
	addq.l	#1,d1
	lsr.l	#1,d2
	bcc.s	.count_zeros_above              ; until the lowest set bit
	bne.s	.general_factor                 ; bits left: not 2^k-1
	move.w	#$2400,(a1)+                    ; 2^k-1: move.l d0,d2 / shift / sub.l d2,d0
	bsr.s	emit_shift_left_result          ; shift left by k
	move.w	#$9082,(a1)+
	rts
.general_factor:
	move.w	#$2400,(a1)+                    ; general: move.l d0,d2

;------------------------------------------------------------------------------
; General shift-and-add loop of emit_mul_int_constant over the bit runs of the factor.
;------------------------------------------------------------------------------
.emit_mul_constant_bits:
	bclr	#$0,d0                          ; bit 0 done
	tst.l	d0                              ; no bits left
	beq.s	.emit_add_partial_to_result     ; finish with add.l d2,d0
	moveq	#0,d1
.count_zero_run:
	addq.l	#1,d1                           ; count the zero bits
	lsr.l	#1,d0
	btst	#$0,d0                          ; up to the next 1 bit
	beq.s	.count_zero_run
	cmp.l	d7,d1                           ; a single zero (run of 1)?
	bne.s	.emit_shift_partial_product     ; no: shift and add
	moveq	#-1,d1
.count_one_run:
	addq.l	#1,d1                           ; count the 1 bits
	btst	d1,d0                           ; of the run starting at bit 0
	bne.s	.count_one_run
	cmp.l	d7,d1                           ; single 1 bit: shift and add
	beq.s	.emit_shift_partial_product
	cmpi.w	#$2400,-(a1)                    ; first partial product (move.l d0,d2)?
	bne.s	.emit_sub_partial_product       ; no: sub.l d0,d2
	addq.l	#2,a1                           ; neg.l d2 instead of the move.l d0,d2
	move.w	#$4482,(a1)+
	bra.s	.emit_shift_bit_run             ; then shift past the run

;------------------------------------------------------------------------------
; Emits sub.l d0,d2.
;------------------------------------------------------------------------------
.emit_sub_partial_product:
	move.w	#$9480,(a1)+                    ; sub.l d0,d2

;------------------------------------------------------------------------------
; Shifts the factor past a bit run and emits the shift.
;------------------------------------------------------------------------------
.emit_shift_bit_run:
	lsr.l	d1,d0                           ; factor past the run
	addq.w	#1,d1                           ; shift count + 1
	bsr.s	emit_shift_left_result          ; emit the shift
	bra.s	.emit_add_partial_product       ; then add.l d0,d2 if bits are left

;------------------------------------------------------------------------------
; Emits the shift for the next partial product.
;------------------------------------------------------------------------------
.emit_shift_partial_product:
	bsr.s	emit_shift_left_result          ; emit the shift

;------------------------------------------------------------------------------
; Emits add.l d0,d2 when bits are left.
;------------------------------------------------------------------------------
.emit_add_partial_product:
	bclr	#$0,d0                          ; the bit just reached
	tst.l	d0                              ; none left
	beq.s	.emit_mul_constant_bits         ; next run
	move.w	#$d480,(a1)+                    ; add.l d0,d2
	bra.s	.emit_mul_constant_bits         ; next run

;------------------------------------------------------------------------------
; Emits add.l d2,d0 (end of the general multiply).
;------------------------------------------------------------------------------
.emit_add_partial_to_result:
	move.w	#$d082,(a1)+                    ; add.l d2,d0
	rts

;------------------------------------------------------------------------------
; Emits moveq #0,d0 (multiply by 0).
;------------------------------------------------------------------------------
.emit_clear_result:
	move.w	#$7000,(a1)+                    ; moveq #0,d0
	rts

;------------------------------------------------------------------------------
; Emits d0 shifted left by d1 bits: 0 nothing, 1 add.l d0,d0, 2-8 lsl.l #n,d0, more moveq #n,d1 / asl.l d1,d0.
;------------------------------------------------------------------------------
emit_shift_left_result:
	cmpi.w	#$8,d1                          ; d1 = shift count
	bhi.s	.shift_by_register              ; above 8: by a register
	cmpi.w	#$1,d1                          ; 1: add.l d0,d0
	beq.s	.add_to_itself
	tst.w	d1                              ; 0: nothing
	beq.s	.no_shift
	andi.w	#$7,d1                          ; lsl.l #n,d0 ($e188, count field)
	ror.w	#7,d1
	ori.w	#$e188,d1
	move.w	d1,(a1)+
	rts                                     ; the shift
.add_to_itself:
	move.w	#$d080,(a1)+                    ; add.l d0,d0
.no_shift:
	rts
.shift_by_register:
	move.b	#$72,(a1)+                      ; moveq #n,d1
	move.b	d1,(a1)+                        ; the count
	move.w	#$e3a0,(a1)+                    ; asl.l d1,d0
	rts

;------------------------------------------------------------------------------
; Divide by constant 0: no code.
;------------------------------------------------------------------------------
div_constant_zero:
	rts                                     ; no code

;------------------------------------------------------------------------------
; Integer divide of d0 by the constant d0 (IR $8008 c $805f). 0: no code. Power of two 2^k: test or negate d0 (no tst.l
; after a variable load $803f/$8040/$803d, which set the flags), bpl.s, add c-1 (addq.l / moveq + add.l / addi.l), asr.l
; #k (or moveq #k,d1 / asr.l d1,d0) so the result rounds toward zero. After a recorded ext.l d0 with a word c: divs.w
; #c,d0 then gen_sign_extend_word. Else c is loaded into d1 and the general divide (gen_integer_divide) follows.
; c = 1 would encode addq #8 / asr #8; presumably the optimiser has removed /1 before.
;------------------------------------------------------------------------------
emit_div_int_constant:
	tst.l	d0                              ; / 0: no code
	beq.s	div_constant_zero
	moveq	#1,d1                           ; d1 = 1 << d2
	moveq	#0,d2                           ; d2 = k
	tst.l	d0                              ; N for a negative divisor
	smi	d7                              ; d7 = divisor negative
	bpl.s	.find_power
	neg.l	d0                              ; |c|
.find_power:
	cmp.l	d0,d1                           ; find k with |c| = 2^k
	beq.s	.divide_power_of_two
	addq.w	#1,d2                           ; next power
	add.l	d1,d1
	bcc.s	.find_power                     ; until it overflows
	cmpi.w	#$48c0,-(a1)                    ; not a power: last word ext.l d0?
	bne.s	.divide_by_register
	cmpa.l	ext_l_d0_code_address(pc),a1    ; the recorded ext.l d0?
	bne.s	.divide_by_register
	move.w	d0,d1                           ; c fits a word?
	ext.l	d1
	cmp.l	d0,d1
	bne.s	.divide_by_register
	addq.l	#2,a1                           ; over the ext.l
	move.w	#$81fc,(a1)+                    ; divs.w #c,d0
	move.w	d0,(a1)+                        ; the divisor
	bra.w	gen_sign_extend_word            ; ext.l d0 after the quotient
.divide_by_register:
	addq.l	#2,a1                           ; undo the -(a1)
	moveq	#1,d2                           ; c into d1, then the general divide
	bsr.w	emit_load_constant_dreg         ; move c into d1
	bra.w	gen_integer_divide              ; then the general divide
.divide_power_of_two:
	cmpi.w	#$3,d2                          ; k up to 3: addq
	bls.s	.shift_up_to_3
	cmpi.w	#$7,d2                          ; k up to 7: moveq into d1
	bls.s	.shift_up_to_7
	bra.w	.shift_8_or_more                ; else addi.l and a register shift
.shift_up_to_3:
	move.w	previous_ir_code(pc),d6         ; just after a variable load?
	cmpi.w	#$803f,d6                       ; $803f long var
	beq.s	.flags_set_addq
	cmpi.w	#$8040,d6                       ; $8040 word var
	beq.s	.flags_set_addq
	cmpi.w	#$803d,d6                       ; $803d byte var
	bne.s	.test_dividend_addq             ; no: flags not set
.flags_set_addq:
	tst.b	d7                              ; divisor negative?
	beq.s	.write_addq_rounding            ; no: flags come from the load
	move.w	#$4480,(a1)+                    ; neg.l d0 (sets the flags)
	bra.s	.write_addq_rounding
.test_dividend_addq:
	move.w	#$4a80,(a1)+                    ; tst.l d0
	tst.b	d7                              ; divisor negative?
	beq.s	.write_addq_rounding
	move.w	#$4480,-$2(a1)                  ; neg.l d0 instead
.write_addq_rounding:
	move.w	#$6a02,(a1)+                    ; bpl.s +2
	subq.w	#1,d0                           ; c - 1
	ror.w	#7,d0                           ; addq count field
	ori.w	#$5080,d0                       ; addq.l #c-1,d0
	move.w	d0,(a1)+
	andi.w	#$7,d2                          ; k into the count field
	ror.w	#7,d2
	ori.w	#$e080,d2                       ; asr.l #k,d0
	move.w	d2,(a1)+
	rts
.shift_up_to_7:
	move.w	previous_ir_code(pc),d6         ; just after a variable load?
	cmpi.w	#$803f,d6                       ; $803f long var
	beq.s	.flags_set_moveq
	cmpi.w	#$8040,d6                       ; $8040 word var
	beq.s	.flags_set_moveq
	cmpi.w	#$803d,d6                       ; $803d byte var
	bne.s	.test_dividend_moveq            ; no: flags not set
.flags_set_moveq:
	tst.b	d7                              ; divisor negative?
	beq.s	.write_moveq_rounding           ; no: flags come from the load
	move.w	#$4480,(a1)+                    ; neg.l d0 (sets the flags)
	bra.s	.write_moveq_rounding
.test_dividend_moveq:
	move.w	#$4a80,(a1)+                    ; tst.l d0
	tst.b	d7                              ; divisor negative?
	beq.s	.write_moveq_rounding
	move.w	#$4480,-$2(a1)                  ; neg.l d0 instead
.write_moveq_rounding:
	move.w	#$6a04,(a1)+                    ; bpl.s +4
	subq.w	#1,d0                           ; c - 1
	ori.w	#$7200,d0                       ; moveq #c-1,d1
	move.w	d0,(a1)+
	move.w	#$d081,(a1)+                    ; add.l d1,d0
	andi.w	#$7,d2                          ; k
	ror.w	#7,d2
	ori.w	#$e080,d2                       ; asr.l #k,d0
	move.w	d2,(a1)+
	rts
.shift_8_or_more:
	move.w	previous_ir_code(pc),d6         ; just after a variable load?
	cmpi.w	#$803f,d6                       ; $803f long var
	beq.s	.flags_set_addi
	cmpi.w	#$8040,d6                       ; $8040 word var
	beq.s	.flags_set_addi
	cmpi.w	#$803d,d6                       ; $803d byte var
	bne.s	.test_dividend_addi             ; no: flags not set
.flags_set_addi:
	tst.b	d7                              ; divisor negative?
	beq.s	.write_addi_rounding            ; no: flags come from the load
	move.w	#$4480,(a1)+                    ; neg.l d0 (sets the flags)
	bra.s	.write_addi_rounding
.test_dividend_addi:
	move.w	#$4a80,(a1)+                    ; tst.l d0
	tst.b	d7                              ; divisor negative?
	beq.s	.write_addi_rounding
	move.w	#$4480,-$2(a1)                  ; neg.l d0 instead
.write_addi_rounding:
	move.w	#$6a06,(a1)+                    ; bpl.s +6
	subq.w	#1,d0                           ; c - 1
	move.w	#$680,(a1)+                     ; addi.l #c-1,d0
	move.l	d0,(a1)+                        ; the long
	move.b	#$72,(a1)+                      ; moveq #k,d1
	move.b	d2,(a1)+                        ; k
	move.w	#$e2a0,(a1)+                    ; asr.l d1,d0
	rts

;------------------------------------------------------------------------------
; Integer MOD by a constant ($8065): no special code, the constant goes into d1.
;------------------------------------------------------------------------------
emit_mod_int_constant:
	bra.w	load_constant_operand_register  ; c into d1, then the register MOD

;------------------------------------------------------------------------------
; Integer add of the constant d0 (IR $8008 c $8063). 0: nothing. After '$803f v' (move.l d(a5),d0 written):
; moveq #c,d0 / move.w #c,d0 / move.l #c,d0 followed by add.l d(a5),d0 or add.w d+2(a5),d0. Else 1..8 addq.l, -8..-1
; subq.l,
; byte -> moveq into d1 and add.l d1,d0, else addi.w (only the low word used, ext.l removed) or addi.l.
;------------------------------------------------------------------------------
emit_add_int_constant:
	tst.l	d0                              ; + 0: no code
	beq.w	.add_done
	bsr.w	drop_ext_if_word_use            ; drop ext.l before a word use
	cmpi.w	#$803f,previous_ir_code         ; just after '$803f v'?
	bne.s	.add_general
	cmpi.w	#$202d,-$4(a1)                  ; last written move.l d(a5),d0?
	bne.s	.add_general
	move.l	-(a1),d2                        ; d2 = $202d and the displacement; a1 back over them
	move.b	d0,d1                           ; c fits a byte?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1
	bne.s	.add_not_byte                   ; no
	move.w	#$7000,d7                       ; moveq #c,d0
	move.b	d0,d7                           ; the byte
	move.w	d7,(a1)+
.add_var_to_d0:
	move.w	#$d0ad,(a1)+                    ; add.l d(a5),d0
.write_add_displacement:
	move.w	d2,(a1)+
	bra.w	mark_result_modified
.add_not_byte:
	movem.l	d0/d2,-(sp)                     ; save c and the old load
	bsr.w	low_word_only_d0                ; only the low word of the result used?
	movem.l	(sp)+,d0/d2
	bne.s	.add_long_constant              ; no: move.l #c,d0
	move.w	#$303c,(a1)+                    ; move.w #c,d0
	move.w	d0,(a1)+                        ; the word
	move.w	#$d06d,(a1)+                    ; add.w d+2(a5),d0 (low word of the long)
	addq.w	#2,d2                           ; displacement + 2: low word of the long
	bra.s	.write_add_displacement         ; write it
.add_long_constant:
	move.w	#$203c,(a1)+                    ; move.l #c,d0
	move.l	d0,(a1)+                        ; the long
	bra.s	.add_var_to_d0                  ; then add.l d(a5),d0
.add_general:
	moveq	#8,d1                           ; 1..8: addq.l
	cmp.l	d1,d0
	bls.s	emit_addq_long
	moveq	#-8,d1                          ; -8..-1: subq.l
	cmp.l	d1,d0
	bcc.s	emit_subq_long_negated
	move.b	d0,d1                           ; fits a byte?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1
	beq.w	load_constant_operand_register  ; byte constant: moveq into d1 and the register add
	move.l	d0,-(sp)                        ; save c
	bsr.w	low_word_only_d0                ; only the low word of the result used?
	movem.l	(sp)+,d2                        ; d2 = c (flags kept)
	beq.s	.addi_word                      ; yes: addi.w
	move.w	#$680,(a1)+                     ; addi.l #c,d0
	move.l	d2,(a1)+                        ; the long
.add_done:
	rts
.addi_word:
	bsr.w	drop_trailing_ext_long          ; the ext.l d0 is no longer needed
	move.w	#$640,(a1)+                     ; addi.w #c,d0
	move.w	d2,(a1)+                        ; the word
	rts

;------------------------------------------------------------------------------
; Emits addq.l #-d0,d0.
;------------------------------------------------------------------------------
emit_addq_long_negated:
	neg.w	d0                              ; subq -c turned into addq

;------------------------------------------------------------------------------
; Emits addq.l #d0,d0 ($5080, count field).
;------------------------------------------------------------------------------
emit_addq_long:
	andi.w	#$7,d0                          ; count field (8 encodes as 0)
	ror.w	#7,d0
	ori.w	#$5080,d0                       ; addq.l #n,d0
	move.w	d0,(a1)+
	bra.s	mark_result_modified

;------------------------------------------------------------------------------
; Emits subq.l #-d0,d0.
;------------------------------------------------------------------------------
emit_subq_long_negated:
	neg.w	d0                              ; -c

;------------------------------------------------------------------------------
; Emits subq.l #d0,d0 ($5180).
;------------------------------------------------------------------------------
emit_subq_long:
	andi.w	#$7,d0                          ; count field (8 encodes as 0)
	ror.w	#7,d0
	ori.w	#$5180,d0
	move.w	d0,(a1)+                        ; the opcode
	bra.s	mark_result_modified

;------------------------------------------------------------------------------
; Emits addq.w #-d0,d0.
;------------------------------------------------------------------------------
emit_addq_word_negated:
	neg.w	d0                              ; -c

;------------------------------------------------------------------------------
; Emits addq.w #d0,d0 ($5040).
;------------------------------------------------------------------------------
emit_addq_word:
	andi.w	#$7,d0                          ; count field (8 encodes as 0)
	ror.w	#7,d0
	ori.w	#$5040,d0
	move.w	d0,(a1)+                        ; the opcode
	bra.s	mark_result_modified

;------------------------------------------------------------------------------
; Emits subq.w #-d0,d0.
;------------------------------------------------------------------------------
emit_subq_word_negated:
	neg.w	d0                              ; -c

;------------------------------------------------------------------------------
; Emits subq.w #d0,d0 ($5140).
;------------------------------------------------------------------------------
emit_subq_word:
	andi.w	#$7,d0                          ; count field (8 encodes as 0)
	ror.w	#7,d0
	ori.w	#$5140,d0
	move.w	d0,(a1)+                        ; the opcode

;------------------------------------------------------------------------------
; Sets current_ir_code to $8061, so the next handler does not take d0 for a just-loaded variable.
;------------------------------------------------------------------------------
mark_result_modified:
	move.w	#$8061,current_ir_code          ; $8061 (OR): later handlers see no fresh variable load
	rts

;------------------------------------------------------------------------------
; Integer subtract of the constant d0 (IR $8008 c $8064). 0: nothing. '$803f v $8008 c $8064 $8078' (negated: c - v):
; moveq/move.l #c,d0 / sub.l d(a5),d0. Else subq.l / addq.l / moveq into d1 / subi.w / subi.l as for add.
; a0 is moved past the $8078 before the move.l d(a5),d0 check, so when that check fails the negate is skipped.
;------------------------------------------------------------------------------
emit_sub_int_constant:
	tst.l	d0                              ; - 0: no code
	beq.s	.sub_zero
	bsr.w	drop_ext_if_word_use
	cmpi.w	#$8078,(a0)                     ; followed by $8078 (negate): c - v?
	bne.s	.sub_general
	cmpi.w	#$803f,previous_ir_code         ; just after '$803f v'?
	bne.s	.sub_general
	addq.l	#2,a0                           ; skip the $8078
	cmpi.w	#$202d,-$4(a1)                  ; last written move.l d(a5),d0?
	bne.s	.sub_general
	move.l	-(a1),d2                        ; d2 = $202d and the displacement; a1 back over them
	move.b	d0,d1                           ; c fits a byte?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1
	bne.s	.sub_long_constant
	move.w	#$7000,d7                       ; moveq #c,d0
	move.b	d0,d7                           ; the byte
	move.w	d7,(a1)+
.sub_var_from_d0:
	move.w	#$90ad,(a1)+                    ; sub.l d(a5),d0
	move.w	d2,(a1)+
	bra.s	mark_result_modified
.sub_long_constant:
	move.w	#$203c,(a1)+                    ; move.l #c,d0
	move.l	d0,(a1)+                        ; the long
	bra.s	.sub_var_from_d0                ; then sub.l d(a5),d0
.sub_general:
	moveq	#8,d1                           ; 1..8: subq.l
	cmp.l	d1,d0
	bls.w	emit_subq_long
	moveq	#-8,d1                          ; -8..-1: addq.l
	cmp.l	d1,d0
	bcc.w	emit_addq_long_negated
	move.b	d0,d1                           ; fits a byte?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1
	beq.w	load_constant_operand_register  ; byte constant: moveq into d1 and sub.l d1,d0
	move.l	d0,-(sp)                        ; save c
	bsr.w	low_word_only_d0                ; only the low word of the result used?
	movea.l	(sp)+,a2                        ; a2 = c (flags kept)
	beq.s	.subi_word                      ; yes: subi.w
	move.w	#$480,(a1)+                     ; subi.l #c,d0
	move.l	a2,(a1)+                        ; the long
	bra.s	.sub_done
.subi_word:
	move.w	#$440,(a1)+                     ; subi.w #c,d0
	move.w	a2,(a1)+                        ; the word
.sub_done:
	bra.w	mark_result_modified
.sub_zero:
	rts

;------------------------------------------------------------------------------
; Integer AND with the constant d0 (IR $8008 c $8060). -1: nothing. 0: moveq #0,d0. After a long load: moveq/move.l
; #c,d0 /
; and.l d(a5),d0. $ffffxxxx: andi.w (clr.w d0 for $ffff0000, clr.b d0 for $ffffff00). One zero bit: bclr #n,d0.
; 0..$7f: moveq into d1. Else andi.w (word use) or andi.l.
;------------------------------------------------------------------------------
emit_and_int_constant:
	addq.l	#1,d0                           ; c = -1?
	beq.w	.and_all_ones                   ; AND -1: no code
	subq.l	#1,d0                           ; c back
	beq.w	.and_zero                       ; AND 0
	bsr.w	drop_ext_if_word_use
	cmpi.w	#$803f,previous_ir_code         ; just after '$803f v'?
	bne.s	.and_general
	cmpi.w	#$202d,-$4(a1)                  ; last written move.l d(a5),d0?
	bne.s	.and_general
	move.l	-(a1),d2                        ; d2 = $202d and the displacement; a1 back over them
	move.b	d0,d1                           ; c fits a byte?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1
	bne.s	.and_long_constant
	move.w	#$7000,d7                       ; moveq #c,d0
	move.b	d0,d7                           ; the byte
	move.w	d7,(a1)+
.and_var_with_d0:
	move.w	#$c0ad,(a1)+                    ; and.l d(a5),d0
	move.w	d2,(a1)+                        ; the displacement
	bra.w	mark_result_modified
.and_long_constant:
	move.w	#$203c,(a1)+                    ; move.l #c,d0
	move.l	d0,(a1)+                        ; the long
	bra.s	.and_var_with_d0                ; then and.l d(a5),d0
.and_general:
	moveq	#-1,d1                          ; upper word all ones?
	move.w	d0,d1                           ; d1 = $ffff and the low word of c
	cmp.l	d0,d1                           ; same as c?
	beq.s	.upper_word_all_ones
	moveq	#0,d2                           ; d2 = bit number
	moveq	#1,d1                           ; d1 = bit mask
	not.l	d0                              ; look for a single zero bit
.find_zero_bit:
	cmp.l	d1,d0
	beq.s	.and_single_zero_bit            ; only that bit was zero
	addq.w	#1,d2
	add.l	d1,d1                           ; next bit
	bcc.s	.find_zero_bit                  ; all 32 tried
	not.l	d0                              ; c back
	cmpi.l	#$7f,d0                         ; 0..$7f: moveq into d1 and and.l d1,d0
	bls.w	load_constant_operand_register
	move.l	d0,-(sp)                        ; save c
	bsr.w	low_word_only_d0                ; only the low word of the result used?
	movea.l	(sp)+,a2                        ; a2 = c (flags kept)
	beq.s	.andi_word                      ; yes: andi.w
	move.w	#$280,(a1)+                     ; andi.l #c,d0
	move.l	a2,(a1)+                        ; the long
	bra.s	.and_done
.andi_word:
	move.w	#$240,(a1)+                     ; andi.w #c,d0
	move.w	a2,(a1)+                        ; the word
.and_done:
	bra.w	mark_result_modified
.and_all_ones:
	rts
.and_zero:
	move.w	#$7000,(a1)+                    ; AND 0: moveq #0,d0
	bra.s	.and_done
.upper_word_all_ones:
	tst.w	d0                              ; $ffff0000?
	beq.s	.clear_low_word
	cmpi.w	#$ff00,d0                       ; $ffffff00?
	beq.s	.clear_low_byte
	move.w	#$240,(a1)+                     ; andi.w #c,d0
	move.w	d0,(a1)+                        ; the word
	rts
.clear_low_word:
	move.w	#$4240,(a1)+                    ; clr.w d0
	rts
.clear_low_byte:
	move.w	#$4200,(a1)+                    ; clr.b d0
	rts
.and_single_zero_bit:
	move.w	#$880,(a1)+                     ; bclr #n,d0
	move.w	d2,(a1)+                        ; the bit number
	rts

;------------------------------------------------------------------------------
; When the next IR word is library $1ae FORW1, $1af FORW2 or $8043 (store word var), removes a recorded ext.l d0
; (drop_trailing_ext_long).
;------------------------------------------------------------------------------
drop_ext_if_word_use:
	move.w	(a0),d1                         ; d1 = the next IR word
	cmpi.w	#$1ae,d1                        ; library $1ae FORW1
	beq.s	.drop_ext
	cmpi.w	#$1af,d1                        ; library $1af FORW2
	beq.s	.drop_ext
	cmpi.w	#$8043,d1                       ; $8043 store word var
	bne.s	.keep_ext
.drop_ext:
	bra.w	drop_trailing_ext_long          ; remove the recorded ext.l d0
.keep_ext:
	rts

;------------------------------------------------------------------------------
; Integer OR with the constant d0 (IR $8008 c $8061). -1: moveq #-1,d0. 0: nothing. After a long load with a byte c:
; moveq #c,d0
; / or.l d(a5),d0. $ff: st d0; $80: tas d0; one bit: bset #n,d0 (bit 7: tas d0); other words: ori.w; -128..-1: moveq
; into d1;
; else ori.l / ori.w.
;------------------------------------------------------------------------------
emit_or_int_constant:
	addq.l	#1,d0                           ; c = -1?
	beq.w	.or_all_ones                    ; OR -1: moveq #-1,d0
	subq.l	#1,d0                           ; c back
	beq.w	.or_zero                        ; OR 0: no code
	bsr.s	drop_ext_if_word_use
	cmpi.w	#$803f,previous_ir_code         ; just after '$803f v'?
	bne.s	.or_general
	cmpi.w	#$202d,-$4(a1)                  ; last written move.l d(a5),d0?
	bne.s	.or_general
	move.l	-(a1),d2                        ; d2 = $202d and the displacement; a1 back over them
	move.b	d0,d1                           ; c fits a byte?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1
	bne.s	.or_not_byte
	move.w	#$7000,d7                       ; moveq #c,d0
	move.b	d0,d7                           ; the byte
	move.w	d7,(a1)+
.or_var_with_d0:
	move.w	#$80ad,(a1)+                    ; or.l d(a5),d0
	move.w	d2,(a1)+                        ; the displacement
	bra.w	mark_result_modified
.or_not_byte:
	moveq	#0,d1                           ; c fits an unsigned word?
	move.w	d0,d1
	cmp.l	d0,d1                           ; yes: keep the load, general code
	beq.s	.or_restore_load
	move.l	d0,d1                           ; find the top set bit (16 shifts at most)
	moveq	#15,d3                          ; at most 16 shifts
.find_top_bit:
	add.l	d1,d1                           ; shift left
	dbcs	d3,.find_top_bit                ; until a 1 drops out
	beq.s	.or_restore_load                ; nothing below it: single bit, use bset
	move.w	#$203c,(a1)+                    ; move.l #c,d0
	move.l	d0,(a1)+                        ; the long
	bra.s	.or_var_with_d0                 ; then or.l d(a5),d0
.or_restore_load:
	addq.l	#4,a1                           ; keep the move.l and use the general code
.or_general:
	moveq	#0,d1                           ; c fits an unsigned word?
	move.w	d0,d1
	cmp.l	d0,d1                           ; yes: the word forms
	beq.s	.or_word_constant
	moveq	#0,d2                           ; d2 = bit number
	moveq	#1,d1                           ; d1 = bit mask
.find_set_bit:
	cmp.l	d1,d0
	beq.s	.or_single_bit                  ; a single bit
	addq.w	#1,d2                           ; next bit
	add.l	d1,d1
	bcc.s	.find_set_bit                   ; all 32 tried
	cmpi.l	#$ffffff80,d0                   ; -128..-1: moveq into d1 and or.l d1,d0
	bcc.w	load_constant_operand_register
	move.l	d0,-(sp)                        ; save c
	bsr.w	low_word_only_d0                ; only the low word of the result used?
	movea.l	(sp)+,a2                        ; a2 = c (flags kept)
	beq.s	.ori_word                       ; yes: ori.w
	move.w	#$80,(a1)+                      ; ori.l #c,d0
	move.l	a2,(a1)+                        ; the long
	bra.s	.or_done
.ori_word:
	move.w	#$40,(a1)+                      ; ori.w #c,d0
	move.w	a2,(a1)+                        ; the word
.or_done:
	bra.w	mark_result_modified
.or_zero:
	rts
.or_all_ones:
	move.w	#$70ff,(a1)+                    ; moveq #-1,d0
	bra.s	.or_done
.or_word_constant:
	cmpi.w	#$ff,d0                         ; $ff: st d0
	beq.s	.or_low_byte
	cmpi.w	#$80,d0                         ; $80: tas d0
	beq.s	.or_bit_seven
	move.w	#$40,(a1)+                      ; ori.w #c,d0
	move.w	d0,(a1)+                        ; the word
	rts
.or_low_byte:
	move.w	#$50c0,(a1)+                    ; st d0 (or #$ff)
	rts
.or_single_bit:
	cmpi.w	#$7,d2                          ; bit 7?
	beq.s	.or_bit_seven                   ; yes: tas d0
	move.w	#$8c0,(a1)+                     ; bset #n,d0
	move.w	d2,(a1)+                        ; the bit number
	rts
.or_bit_seven:
	move.w	#$4ac0,(a1)+                    ; tas d0 (sets bit 7)
	rts

;------------------------------------------------------------------------------
; Integer EOR with the constant d0 (IR $8008 c $8062). -1: not.l d0. 0: nothing. $ffff: not.w; $ff: not.b; other words
; eori.w;
; -128..-1: moveq into d1; else eori.l / eori.w. A single bit should give bchg #n,d0, but the opcode is written without
; advancing a1 and is overwritten by the bit number.
;------------------------------------------------------------------------------
emit_eor_int_constant:
	addq.l	#1,d0                           ; d0 + 1 = 0: the constant is -1
	beq.s	.eor_minus_one                  ; -1: not.l d0
	subq.l	#1,d0                           ; restore the constant
	beq.s	.eor_zero                       ; 0: x eor 0 = x, no code
	moveq	#0,d1                           ; d1 = the low word, zero-extended
	move.w	d0,d1
	cmp.l	d0,d1                           ; constant in 0..$ffff?
	beq.s	.eor_word_constant              ; yes: the word forms
	moveq	#0,d2                           ; d2 = bit number
	moveq	#1,d1                           ; d1 = test bit, from bit 0 up
.find_single_bit:
	cmp.l	d1,d0                           ; constant a single bit?
	beq.s	.eor_single_bit
	addq.w	#1,d2                           ; next bit number
	add.l	d1,d1                           ; test bit one place up
	bcc.s	.find_single_bit                ; until it leaves bit 31
	cmpi.l	#$ffffff80,d0                   ; -128..-1:
	bcc.w	load_constant_operand_register  ; constant into d1, then the register form
	move.l	d0,-(sp)                        ; keep the constant
	bsr.w	low_word_only_d0                ; Z: only the low word of d0 is used
	movea.l	(sp)+,a2                        ; a2 = constant (flags kept)
	beq.s	.emit_eori_word                 ; low word only: eori.w
	move.w	#$a80,(a1)+                     ; eori.l #c,d0
	move.l	a2,(a1)+                        ; the long immediate
	bra.s	.eor_done
.emit_eori_word:
	move.w	#$a40,(a1)+                     ; eori.w #c,d0
	move.w	a2,(a1)+                        ; the word immediate
.eor_done:
	bra.w	mark_result_modified            ; result in d0 changed
.eor_zero:
	rts
.eor_minus_one:
	move.w	#$4680,(a1)+                    ; not.l d0
	bra.w	mark_result_modified
.eor_word_constant:
	cmpi.w	#$ffff,d0                       ; $ffff: not.w d0
	beq.s	.emit_not_word
	cmpi.w	#$ff,d0                         ; $ff: not.b d0
	beq.s	.emit_not_byte
	move.w	#$a40,(a1)+                     ; eori.w #c,d0
	move.w	d0,(a1)+                        ; the immediate
	rts
.emit_not_word:
	move.w	#$4640,(a1)+                    ; not.w d0
	rts
.emit_not_byte:
	move.w	#$4600,(a1)+                    ; not.b d0
	rts
.eor_single_bit:
	move.w	#$840,(a1)                      ; bchg #n,d0 written without (a1)+, so the next move overwrites it
	move.w	d2,(a1)+                        ; bit number (over the bchg)
	rts

;------------------------------------------------------------------------------
; Integer compare of d0 with a constant, $807b =: d2 = 7 (EQ).
;------------------------------------------------------------------------------
int_compare_eq_constant:
	moveq	#7,d2                           ; EQ
	bra.s	emit_int_compare_constant

;------------------------------------------------------------------------------
; Integer compare of d0 with a constant, $807c <>: d2 = 6 (NE).
;------------------------------------------------------------------------------
int_compare_ne_constant:
	moveq	#6,d2                           ; NE
	bra.s	emit_int_compare_constant

;------------------------------------------------------------------------------
; Integer compare of d0 with a constant, $807e >: d2 = 14 (GT).
;------------------------------------------------------------------------------
int_compare_gt_constant:
	moveq	#14,d2                          ; GT
	bra.s	emit_int_compare_constant

;------------------------------------------------------------------------------
; Integer compare of d0 with a constant, $807d >=: d2 = 12 (GE).
;------------------------------------------------------------------------------
int_compare_ge_constant:
	moveq	#12,d2                          ; GE
	bra.s	emit_int_compare_constant

;------------------------------------------------------------------------------
; Integer compare of d0 with a constant, $8080 <: d2 = 13 (LT).
;------------------------------------------------------------------------------
int_compare_lt_constant:
	moveq	#13,d2                          ; LT
	bra.s	emit_int_compare_constant

;------------------------------------------------------------------------------
; Integer compare of d0 with a constant, $807f <=: d2 = 15 (LE).
;------------------------------------------------------------------------------
int_compare_le_constant:
	moveq	#15,d2                          ; LE

;------------------------------------------------------------------------------
; Integer compare of d0 with the constant d0 (IR $8008 c $807b-$8080), d2 = condition code; ends with Scc d0 and
; finish_condition_result. After a recorded ext.l d0: the word compare. 0: tst.l d0 unless the value was just
; loaded (long: none; byte $803d: unsigned rules, > -> NE, >= true, < false, <= -> EQ). After a long load:
; moveq #c,d0 / cmp.l d(a5),d0 with the condition reversed, or cmpi.l #c,d(a5). Else subq.l / addq.l for -8..8,
; moveq into d1, or subi.l #c,d0 (flags as a compare).
;------------------------------------------------------------------------------
emit_int_compare_constant:
	cmpi.w	#$48c0,-(a1)                    ; recorded ext.l d0 last? (a1 back on it)
	bne.s	.no_recorded_ext
	cmpa.l	ext_l_d0_code_address(pc),a1    ; the one at ext_l_d0_code_address?
	beq.w	emit_word_compare_constant      ; yes: compare as a word, writing over the ext.l
.no_recorded_ext:
	addq.l	#2,a1                           ; no: keep the last word
	tst.l	d0                              ; compare with 0?
	beq.w	.int_compare_zero
	cmpi.w	#$803f,previous_ir_code         ; previous IR $803f: d0 loaded from an integer variable
	bne.s	.compare_general
	cmpi.w	#$202d,-$4(a1)                  ; and the last code is move.l d(a5),d0?
	bne.s	.compare_general
	move.b	d0,d1
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1                           ; constant fits a byte?
	bne.s	.emit_cmpi_var                  ; no: cmpi.l #c,d(a5) over the load
	move.w	-(a1),d1                        ; d1 = variable offset, a1 back on it
	move.w	#$7000,d7                       ; d7 = moveq #c,d0
	move.b	d0,d7                           ; d7.b = the constant
	move.w	d7,-$2(a1)                      ; moveq #c,d0 over the move.l
	cmpi.b	#$8,d2                          ; operands reversed: GE<->LE, GT<->LT
	bcs.s	.emit_cmp_var
	eori.b	#$3,d2                          ; GE<->LE, GT<->LT
.emit_cmp_var:
	move.w	#$b0ad,(a1)+                    ; cmp.l d(a5),d0
	move.w	d1,(a1)+                        ; the variable offset
	bra.s	.emit_scc_long                  ; Scc d0
.compare_general:
	cmpi.l	#$8,d0                          ; 1..8: subq.l #c,d0
	bls.s	.emit_subq_long
	cmpi.l	#$fffffff8,d0                   ; -8..-1: addq.l #-c,d0
	bcc.s	.emit_addq_long
	move.b	d0,d1
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1                           ; constant fits a byte?
	beq.w	load_constant_operand_register  ; yes: moveq #c,d1, then the operator's register compare
	move.w	previous_ir_code(pc),d7         ; same long-load test again; it failed to get here, so never true
	cmpi.w	#$803f,d7                       ; previous IR $803f?
	bne.s	.emit_subi_long
	cmpi.w	#$202d,-$4(a1)                  ; and move.l d(a5),d0 last?
	bne.s	.emit_subi_long
.emit_cmpi_var:
	move.w	-(a1),d1                        ; d1 = variable offset, a1 back on it
	move.w	#$cad,-$2(a1)                   ; cmpi.l #c,d(a5) over the move.l
	move.l	d0,(a1)+                        ; the long immediate
	move.w	d1,(a1)+                        ; then the offset
	bra.s	.emit_scc_long
.emit_subi_long:
	move.w	#$480,(a1)+                     ; $0480 = subi.l #c,d0: flags as for cmpi.l
	move.l	d0,(a1)+                        ; the long immediate
	bra.s	.emit_scc_long
.int_compare_zero:
	move.w	previous_ir_code(pc),d7         ; compare with 0: look at the previous IR
	cmpi.w	#$803f,d7                       ; $803f: move.l d(a5),d0 set the flags already
	beq.s	.emit_scc_long
	cmpi.w	#$803d,d7                       ; $803d: byte variable loaded (moveq #0,d0 / move.b)
	beq.s	.unsigned_byte_compare_zero
	move.w	#$4a80,(a1)+                    ; tst.l d0
.emit_scc_long:
	asl.w	#8,d2                           ; condition into bits 8-11
	ori.w	#$50c0,d2                       ; $50c0 = st d0, condition added: Scc d0
	move.w	d2,(a1)+                        ; Scc d0
	bra.w	finish_condition_result         ; fold NOT / jumps, or ext.w d0
.emit_subq_long:
	bsr.w	emit_subq_long                  ; subq.l #c,d0
	bra.s	.emit_scc_long
.emit_addq_long:
	bsr.w	emit_addq_long_negated          ; addq.l #-c,d0
	bra.s	.emit_scc_long
.unsigned_byte_compare_zero:
	cmpi.w	#$7,d2                          ; byte variable just loaded: the value is unsigned
	beq.s	.drop_moveq_before_load         ; EQ stays
	cmpi.w	#$6,d2                          ; NE
	beq.s	.drop_moveq_before_load         ; NE stays
	cmpi.w	#$e,d2                          ; GT (14)
	beq.s	.gt_becomes_ne                  ; GT -> NE
	cmpi.w	#$c,d2                          ; GE (12)
	beq.s	.always_true                    ; x >= 0 always true
	cmpi.w	#$d,d2                          ; LT (13)
	beq.s	.always_false                   ; x < 0 always false
	moveq	#7,d2                           ; LE (15) -> EQ
	bra.s	.drop_moveq_before_load
.gt_becomes_ne:
	moveq	#6,d2                           ; GT -> NE (unsigned: > 0 means <> 0)
.drop_moveq_before_load:
	cmpi.w	#$7000,-$6(a1)                  ; remove the moveq #0,d0 in front of the move.b
	beq.s	.shift_load_down                ; it is: overwrite it with the move.b
	move.w	-$6(a1),-$8(a1)                 ; else move the word before the move.b back a word (case not clear)
.shift_load_down:
	move.l	-$4(a1),-$6(a1)                 ; move.b d(a5),d0 one word down
	subq.l	#2,a1                           ; the code is a word shorter
	bra.s	.emit_scc_long                  ; move.b set the flags: just the Scc
.always_true:
	moveq	#-1,d0                          ; x >= 0 always true
	bra.s	.constant_result
.always_false:
	moveq	#0,d0                           ; x < 0 always false
.constant_result:
	subq.l	#6,a1                           ; turn the load into moveq #-1,d0 / moveq #0,d0
	cmpi.b	#$70,(a1)+                      ; moveq there? step onto its data byte
	beq.s	.write_moveq_data
	subq.l	#2,a1                           ; no moveq: back again (the byte lands at a1-6; case not clear)
.write_moveq_data:
	move.b	d0,(a1)+                        ; data byte -1 / 0; the move.b is dropped
	rts

;------------------------------------------------------------------------------
; Word compare of d0 with the constant d0 (a recorded ext.l d0 was dropped). After '$8040 v' (move.w d(a5),d0):
; cmpi.w #c,d(a5); 1..8 subq.w, -8..-1 addq.w, else subi.w #c,d0; 0: tst.w d0 unless just loaded. Then Scc d0.
;------------------------------------------------------------------------------
emit_word_compare_constant:
	tst.l	d0                              ; compare with 0?
	beq.s	.word_compare_zero
	move.w	previous_ir_code(pc),d7         ; previous IR
	cmpi.w	#$8040,d7                       ; $8040: word variable loaded
	bne.s	.compare_word_general
	cmpi.w	#$302d,-$4(a1)                  ; and the last code is move.w d(a5),d0?
	bne.s	.compare_word_general
	cmpi.w	#$8,d0                          ; 1..8: subq.w
	bls.s	.emit_subq_word
	cmpi.w	#$fff8,d0                       ; -8..-1: addq.w
	bcc.s	.emit_addq_word
	move.w	-(a1),d1                        ; d1 = variable offset, a1 back on it
	move.w	#$c6d,-$2(a1)                   ; $0c6d = cmpi.w #c,d(a5) over the move.w
	move.w	d0,(a1)+                        ; the immediate
	move.w	d1,(a1)+                        ; the offset
	bra.s	.emit_scc_word
.compare_word_general:
	cmpi.w	#$8,d0                          ; 1..8: subq.w #c,d0
	bls.s	.emit_subq_word
	cmpi.w	#$fff8,d0                       ; -8..-1: addq.w #-c,d0
	bcc.s	.emit_addq_word
	move.w	#$440,(a1)+                     ; subi.w #c,d0
	move.w	d0,(a1)+                        ; the immediate
	bra.s	.emit_scc_word
.emit_subq_word:
	bsr.w	emit_subq_word                  ; subq.w #c,d0
	bra.s	.emit_scc_word
.emit_addq_word:
	bsr.w	emit_addq_word_negated          ; addq.w #-c,d0
	bra.s	.emit_scc_word
.word_compare_zero:
	move.w	previous_ir_code(pc),d7         ; compare with 0: previous IR
	cmpi.w	#$8040,d7                       ; $8040: move.w set the flags already
	beq.s	.emit_scc_word
	move.w	#$4a40,(a1)+                    ; tst.w d0
.emit_scc_word:
	asl.w	#8,d2                           ; condition into bits 8-11
	ori.w	#$50c0,d2                       ; $50c0 = st d0, condition added: Scc d0
	move.w	d2,(a1)+                        ; Scc d0
	bra.w	finish_condition_result         ; fold NOT / jumps, or ext.w d0

;------------------------------------------------------------------------------
; IR $8008 c $811d: word compare, d2 = 12 (GE).
;------------------------------------------------------------------------------
word_compare_ge_constant:
	moveq	#12,d2                          ; GE
	bra.s	word_compare_constant_entry

;------------------------------------------------------------------------------
; IR $8008 c $811e: word compare, d2 = 15 (LE).
;------------------------------------------------------------------------------
word_compare_le_constant:
	moveq	#15,d2                          ; LE

;------------------------------------------------------------------------------
; Sign-extends the constant, drops a recorded ext.l d0 and goes to the word compare.
;------------------------------------------------------------------------------
word_compare_constant_entry:
	ext.l	d0                              ; sign-extend the word constant
	cmpi.w	#$48c0,-(a1)                    ; recorded ext.l d0 last? (a1 back on it)
	bne.s	.no_recorded_ext_word
	cmpa.l	ext_l_d0_code_address(pc),a1    ; the one at ext_l_d0_code_address?
	beq.s	emit_word_compare_constant      ; yes: write over it
.no_recorded_ext_word:
	addq.l	#2,a1                           ; no: keep the last word
	bra.w	emit_word_compare_constant

;------------------------------------------------------------------------------
; IR $8008 c $8124: unsigned byte compare, d2 = 4 (HS).
;------------------------------------------------------------------------------
byte_compare_hs_constant:
	moveq	#4,d2                           ; HS
	bra.s	emit_byte_compare_constant

;------------------------------------------------------------------------------
; IR $8008 c $8125: unsigned byte compare, d2 = 3 (LS).
;------------------------------------------------------------------------------
byte_compare_ls_constant:
	moveq	#3,d2                           ; LS

;------------------------------------------------------------------------------
; Byte compare of d0 with the constant d0. After '$803d v' (moveq #0,d0 / move.b d(a5),d0): the moveq is removed
; and cmpi.b #c,d(a5) written; else subi.b #c,d0; 0: tst.l d0 unless just loaded (then only the moveq is
; removed). Then Scc d0 and finish_condition_result.
;------------------------------------------------------------------------------
emit_byte_compare_constant:
	ext.l	d0                              ; sign-extend the constant
	cmpi.w	#$48c0,-(a1)                    ; recorded ext.l d0 last? (a1 back on it)
	bne.s	.no_recorded_ext_byte
	cmpa.l	ext_l_d0_code_address(pc),a1    ; the one at ext_l_d0_code_address?
	beq.s	.byte_ext_checked               ; yes: write over it
.no_recorded_ext_byte:
	addq.l	#2,a1                           ; no: keep the last word
.byte_ext_checked:
	tst.l	d0                              ; compare with 0?
	beq.s	.byte_compare_zero
	move.w	previous_ir_code(pc),d7         ; previous IR
	cmpi.w	#$803d,d7                       ; $803d: byte variable loaded
	bne.s	.emit_subi_byte
	cmpi.w	#$102d,-$4(a1)                  ; and the last code is move.b d(a5),d0?
	bne.s	.emit_subi_byte
	move.w	-(a1),d1                        ; d1 = variable offset, a1 back on it
	cmpi.w	#$7000,-$4(a1)                  ; moveq #0,d0 in front of the move.b?
	bne.s	.emit_cmpi_byte_var
	subq.l	#2,a1                           ; yes: remove it too
.emit_cmpi_byte_var:
	move.w	#$c2d,-$2(a1)                   ; $0c2d = cmpi.b #c,d(a5)
	move.w	d0,(a1)+                        ; the immediate
	move.w	d1,(a1)+                        ; the offset
	bra.s	.drop_byte_moveq
.emit_subi_byte:
	move.w	#$400,(a1)+                     ; subi.b #c,d0
	move.w	d0,(a1)+                        ; the immediate
	bra.s	.drop_byte_moveq
.byte_compare_zero:
	move.w	previous_ir_code(pc),d7         ; compare with 0: previous IR
	cmpi.w	#$803d,d7                       ; $803d: drop the moveq, move.b sets the flags
	beq.s	.drop_byte_moveq
	move.w	#$4a80,(a1)+                    ; tst.l d0
	bra.s	.emit_scc_byte
.drop_byte_moveq:
	cmpi.w	#$102d,-$4(a1)                  ; move.b d(a5),d0 last? (the zero case after $803d)
	bne.s	.emit_scc_byte
	move.w	-(a1),d1                        ; d1 = offset, a1 back on it
	cmpi.w	#$7000,-$4(a1)                  ; moveq #0,d0 in front?
	bne.s	.rewrite_byte_load
	subq.l	#2,a1                           ; yes: remove it
.rewrite_byte_load:
	move.w	#$102d,-$2(a1)                  ; $102d = move.b d(a5),d0, one word down
	move.w	d1,(a1)+                        ; the offset
.emit_scc_byte:
	asl.w	#8,d2                           ; condition into bits 8-11
	ori.w	#$50c0,d2                       ; $50c0 = st d0, condition added: Scc d0
	move.w	d2,(a1)+                        ; Scc d0
	bra.w	finish_condition_result         ; fold NOT / jumps, or ext.w d0

;------------------------------------------------------------------------------
; IR $8008 n $8075: bset #n,d0.
;------------------------------------------------------------------------------
emit_bset_constant:
	andi.w	#$1f,d0                         ; bit number 0-31
	move.w	#$8c0,(a1)+                     ; $08c0 = bset #n,d0
	move.w	d0,(a1)+                        ; the bit number
	rts

;------------------------------------------------------------------------------
; IR $8008 n $8076: bclr #n,d0. The bset code at $a49c after it has no label and is never used.
;------------------------------------------------------------------------------
emit_bclr_constant:
	andi.w	#$1f,d0                         ; bit number 0-31
	move.w	#$880,(a1)+                     ; $0880 = bclr #n,d0
	move.w	d0,(a1)+                        ; the bit number
	rts
	andi.w	#$1f,d0                         ; unreferenced
	move.w	#$8c0,(a1)+                     ; $08c0 = bset #n,d0
	move.w	d0,(a1)+                        ; the bit number
	rts

;------------------------------------------------------------------------------
; IR $8008 n $8074: btst #n,d0 / sne d0, then finish_condition_result.
;------------------------------------------------------------------------------
emit_btst_constant:
	andi.w	#$1f,d0                         ; bit number 0-31
	move.w	#$800,(a1)+                     ; $0800 = btst #n,d0
	move.w	d0,(a1)+                        ; the bit number
	move.w	#$56c0,(a1)+                    ; sne d0
	bra.w	finish_condition_result         ; fold NOT / jumps, or ext.w d0

;------------------------------------------------------------------------------
; IR $8008 n $8068: long SHL by a constant (lsl.l).
;------------------------------------------------------------------------------
long_shl_constant:
	move.w	#$e188,d2                       ; $e188 = lsl.l #8,d0
	bra.s	emit_long_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $8069: long SHR by a constant (lsr.l).
;------------------------------------------------------------------------------
long_shr_constant:
	move.w	#$e088,d2                       ; $e088 = lsr.l #8,d0
	bra.s	emit_long_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $806a: long ROL by a constant (rol.l).
;------------------------------------------------------------------------------
long_rol_constant:
	move.w	#$e198,d2                       ; $e198 = rol.l #8,d0
	bra.s	emit_long_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $806b: long ROR by a constant (ror.l).
;------------------------------------------------------------------------------
long_ror_constant:
	move.w	#$e098,d2                       ; $e098 = ror.l #8,d0

;------------------------------------------------------------------------------
; Long shift/rotate of d0 by the constant d0 (d2 = opcode with count 8). The count is masked to 0-63 and written back
; into
; the IR. 0: nothing. Shifts: 16 -> clr.w d0 / swap d0 or swap d0 / clr.w d0, 32 or more -> moveq #0,d0, 1-8 immediate,
; 9-31 moveq #n,d1 and the register form. Rotates: count & 31, 16 -> swap d0, over 16 -> other direction by 32-n.
; A rotate by 32 masks to 0 and is written as a rotate by 8.
;------------------------------------------------------------------------------
emit_long_shift_constant:
	andi.l	#$3f,d0                         ; count 0-63
	move.l	d0,-$6(a0)                      ; store the masked count back into the IR
	beq.s	.long_shift_done                ; 0: no code
	btst	#$4,d2                          ; bit 4 of the opcode: rotate
	bne.s	.rotate_long
	cmpi.w	#$10,d0                         ; shift by 16: swap and clear
	beq.s	.shift_long_by_16
	cmpi.w	#$20,d0                         ; 1-31: immediate or register count
	bcs.s	.shift_long_immediate
	move.w	#$7000,(a1)+                    ; shift by 32 or more: moveq #0,d0
	rts
.rotate_long:
	andi.w	#$1f,d0                         ; rotate count & 31 (32 becomes 0, emitted as 8)
	cmpi.w	#$10,d0                         ; 16: just a swap
	beq.w	gen_swap_d0                     ; rotate by 16 = swap d0
	bcs.s	.shift_long_immediate           ; 1-15: as it is
	eori.w	#$100,d2                        ; flip the direction bit
	neg.w	d0                              ; 17-31 -> 32-n the other way
	andi.w	#$1f,d0                         ; count 1-15
.shift_long_immediate:
	cmpi.w	#$8,d0                          ; 1-8 fit the immediate field
	bhi.s	.shift_long_by_register         ; 9 or more: count in d1
	andi.w	#$7,d0                          ; 8 is written as 0
	ror.w	#7,d0                           ; count into bits 9-11
	or.w	d2,d0                           ; into the opcode
	move.w	d0,(a1)+                        ; lsX/roX #n,d0
.long_shift_done:
	rts
.shift_long_by_register:
	move.b	#$72,(a1)+                      ; $72 = moveq #n,d1
	move.b	d0,(a1)+                        ; the count
	addi.w	#$220,d2                        ; register count (d1) form
	move.w	d2,(a1)+                        ; lsX/roX d1,d0
	rts
.shift_long_by_16:
	btst	#$8,d2                          ; bit 8 of the opcode set: left
	bne.s	.shift_left_by_16               ; left: swap / clr.w
	move.l	#$42404840,(a1)+                ; lsr 16: clr.w d0 / swap d0
	rts
.shift_left_by_16:
	move.l	#$48404240,(a1)+                ; lsl 16: swap d0 / clr.w d0
	rts

;------------------------------------------------------------------------------
; IR $8008 n $806c: word SHL by a constant.
;------------------------------------------------------------------------------
word_shl_constant:
	move.w	#$e148,d2                       ; $e148 = lsl.w #8,d0
	bra.s	emit_word_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $806d: word SHR by a constant.
;------------------------------------------------------------------------------
word_shr_constant:
	move.w	#$e048,d2                       ; $e048 = lsr.w #8,d0
	bra.s	emit_word_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $806e: word ROL by a constant.
;------------------------------------------------------------------------------
word_rol_constant:
	move.w	#$e158,d2                       ; $e158 = rol.w #8,d0
	bra.s	emit_word_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $806f: word ROR by a constant.
;------------------------------------------------------------------------------
word_ror_constant:
	move.w	#$e058,d2                       ; $e058 = ror.w #8,d0

;------------------------------------------------------------------------------
; Word shift/rotate of d0 by a constant; removes a recorded ext.l d0 first and ends at gen_sign_extend_word. Shift
; by 16: left -> moveq #0,d0, right -> writes the words $0000,$4840 (ori.b #$40,d0), which is not a shift
; result. Rotates: count & 15, 8 or more -> other direction.
;------------------------------------------------------------------------------
emit_word_shift_constant:
	movem.w	d0/d2,-(sp)                     ; keep count and opcode
	bsr.w	drop_trailing_ext_long          ; a word shift needs no ext.l
	movem.w	(sp)+,d0/d2                     ; count and opcode back
	andi.l	#$3f,d0                         ; count 0-63
	move.l	d0,-$6(a0)                      ; store the masked count back into the IR
	beq.s	.word_shift_extend              ; 0: only the sign extension
	btst	#$4,d2                          ; bit 4: rotate
	bne.s	.rotate_word
	cmpi.w	#$10,d0                         ; 16: special
	beq.s	.shift_word_by_16
	bcs.s	.shift_word_immediate           ; 1-15: immediate or register count
	move.w	#$7000,(a1)+                    ; 17 or more: moveq #0,d0
	rts
.rotate_word:
	andi.w	#$f,d0                          ; rotate count 0-15
	cmpi.w	#$8,d0                          ; 1-7: as it is
	bcs.s	.shift_word_immediate
	eori.w	#$100,d2                        ; flip the direction bit
	neg.w	d0                              ; 8-15 -> 16-n the other way
	andi.w	#$f,d0                          ; count 1-8
.shift_word_immediate:
	cmpi.w	#$8,d0                          ; 1-8 fit the immediate field
	bhi.s	.shift_word_by_register         ; 9-15: count in d1
	andi.w	#$7,d0                          ; 8 is written as 0
	ror.w	#7,d0                           ; count into bits 9-11
	or.w	d2,d0                           ; into the opcode
	move.w	d0,(a1)+                        ; lsX/roX.w #n,d0
.word_shift_extend:
	bra.w	gen_sign_extend_word            ; ext.l d0 if the user needs a long
.shift_word_by_register:
	move.b	#$72,(a1)+                      ; $72 = moveq #n,d1
	move.b	d0,(a1)+                        ; the count
	addi.w	#$220,d2                        ; register count (d1) form
	move.w	d2,(a1)+                        ; lsX/roX.w d1,d0
	bra.w	gen_sign_extend_word
.shift_word_by_16:
	btst	#$8,d2                          ; bit 8 of the opcode set: left
	bne.s	.shift_word_left_by_16          ; left by 16: moveq #0,d0
	move.l	#$4840,(a1)+                    ; writes $0000 $4840 = ori.b #$40,d0
	bra.w	gen_sign_extend_word
.shift_word_left_by_16:
	move.w	#$7000,(a1)+                    ; left by 16: moveq #0,d0
	rts

;------------------------------------------------------------------------------
; IR $8008 n $8070: byte SHL by a constant.
;------------------------------------------------------------------------------
byte_shl_constant:
	move.w	#$e108,d2                       ; $e108 = lsl.b #8,d0
	bra.s	emit_byte_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $8071: byte SHR by a constant.
;------------------------------------------------------------------------------
byte_shr_constant:
	move.w	#$e008,d2                       ; $e008 = lsr.b #8,d0
	bra.s	emit_byte_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $8072: byte ROL by a constant.
;------------------------------------------------------------------------------
byte_rol_constant:
	move.w	#$e118,d2                       ; $e118 = rol.b #8,d0
	bra.s	emit_byte_shift_constant

;------------------------------------------------------------------------------
; IR $8008 n $8073: byte ROR by a constant.
;------------------------------------------------------------------------------
byte_ror_constant:
	move.w	#$e018,d2                       ; $e018 = ror.b #8,d0

;------------------------------------------------------------------------------
; Byte shift/rotate of d0 by a constant; removes recorded ext.l / ext.w first (drop_trailing_extends), ends at
; gen_zero_extend_byte (andi.l #$ff). Shifts of 8 or more -> moveq #0,d0; rotates count & 7, 4 or more -> other
; direction.
;------------------------------------------------------------------------------
emit_byte_shift_constant:
	movem.w	d0/d2,-(sp)                     ; keep count and opcode
	bsr.w	drop_trailing_extends           ; a byte op needs neither ext.l nor ext.w
	movem.w	(sp)+,d0/d2                     ; count and opcode back
	andi.l	#$3f,d0                         ; count 0-63
	move.l	d0,-$6(a0)                      ; store the masked count back into the IR
	beq.s	.byte_shift_zero_extend         ; 0: only the zero extension
	btst	#$4,d2                          ; bit 4: rotate
	bne.s	.rotate_byte
	cmpi.w	#$8,d0                          ; 1-7: immediate
	bcs.s	.shift_byte_immediate
	move.w	#$7000,(a1)+                    ; 8 or more: moveq #0,d0
	rts
.rotate_byte:
	andi.w	#$7,d0                          ; rotate count 0-7
	cmpi.w	#$4,d0                          ; 1-3: as it is
	bcs.s	.shift_byte_immediate
	eori.w	#$100,d2                        ; flip the direction bit
	neg.w	d0                              ; 4-7 -> 8-n the other way (masked below)
.shift_byte_immediate:
	andi.w	#$7,d0                          ; count field (8 would be 0 anyway)
	ror.w	#7,d0                           ; count into bits 9-11
	or.w	d2,d0                           ; into the opcode
	move.w	d0,(a1)+                        ; lsX/roX.b #n,d0
.byte_shift_zero_extend:
	bra.w	gen_zero_extend_byte            ; andi.l #$ff,d0 unless only stored as a byte / word
	move.w	#$7000,(a1)+                    ; unreferenced
	rts

;------------------------------------------------------------------------------
; Codegen for IR $8008 c op (integer constant as right operand of an integer operator). d0 = c, d1 = operator:
; $8063 add, $8064 sub, $8060 AND, $8061 OR, $8062 XOR, $807b-$8080 compares, $811d/$811e word compares,
; $8124/$8125 byte compares, $8068-$8073 shifts and rotates (long/word/byte), $8074 BTST, $8075 BSET, $8076 BCLR,
; $805e multiply, $805f divide, $8065 MOD, $814c-$814e word add/sub/mul (gen_add_constant_d0, gen_sub_constant_d0,
; gen_mul_word_constant_d0). Anything else: load_constant_operand_register.
;------------------------------------------------------------------------------
emit_int_constant_operand:
	move.l	(a0)+,d0                        ; d0 = the constant
	move.w	(a0)+,d1                        ; d1 = the operator IR
	cmpi.w	#$8063,d1                       ; $8063 add
	beq.w	emit_add_int_constant
	cmpi.w	#$8064,d1                       ; $8064 sub
	beq.w	emit_sub_int_constant
	cmpi.w	#$8060,d1                       ; $8060 AND
	beq.w	emit_and_int_constant
	cmpi.w	#$8061,d1                       ; $8061 OR
	beq.w	emit_or_int_constant
	cmpi.w	#$8062,d1                       ; $8062 EOR
	beq.w	emit_eor_int_constant
	cmpi.w	#$807b,d1                       ; $807b =
	beq.w	int_compare_eq_constant
	cmpi.w	#$807c,d1                       ; $807c <>
	beq.w	int_compare_ne_constant
	cmpi.w	#$807e,d1                       ; $807e >
	beq.w	int_compare_gt_constant
	cmpi.w	#$807d,d1                       ; $807d >=
	beq.w	int_compare_ge_constant
	cmpi.w	#$811d,d1                       ; $811d word >=
	beq.w	word_compare_ge_constant
	cmpi.w	#$8124,d1                       ; $8124 unsigned byte >=
	beq.w	byte_compare_hs_constant
	cmpi.w	#$8080,d1                       ; $8080 <
	beq.w	int_compare_lt_constant
	cmpi.w	#$807f,d1                       ; $807f <=
	beq.w	int_compare_le_constant
	cmpi.w	#$811e,d1                       ; $811e word <=
	beq.w	word_compare_le_constant
	cmpi.w	#$8125,d1                       ; $8125 unsigned byte <=
	beq.w	byte_compare_ls_constant
	cmpi.w	#$8068,d1                       ; $8068 long SHL
	beq.w	long_shl_constant
	cmpi.w	#$8069,d1                       ; $8069 long SHR
	beq.w	long_shr_constant
	cmpi.w	#$806a,d1                       ; $806a long ROL
	beq.w	long_rol_constant
	cmpi.w	#$806b,d1                       ; $806b long ROR
	beq.w	long_ror_constant
	cmpi.w	#$806c,d1                       ; $806c word SHL
	beq.w	word_shl_constant
	cmpi.w	#$806d,d1                       ; $806d word SHR
	beq.w	word_shr_constant
	cmpi.w	#$806e,d1                       ; $806e word ROL
	beq.w	word_rol_constant
	cmpi.w	#$806f,d1                       ; $806f word ROR
	beq.w	word_ror_constant
	cmpi.w	#$8070,d1                       ; $8070 byte SHL
	beq.w	byte_shl_constant
	cmpi.w	#$8071,d1                       ; $8071 byte SHR
	beq.w	byte_shr_constant
	cmpi.w	#$8072,d1                       ; $8072 byte ROL
	beq.w	byte_rol_constant
	cmpi.w	#$8073,d1                       ; $8073 byte ROR
	beq.w	byte_ror_constant
	cmpi.w	#$8075,d1                       ; $8075 BSET
	beq.w	emit_bset_constant
	cmpi.w	#$8074,d1                       ; $8074 BTST
	beq.w	emit_btst_constant
	cmpi.w	#$8076,d1                       ; $8076 BCLR
	beq.w	emit_bclr_constant
	cmpi.w	#$8074,d1                       ; $8074 again: never true here
	beq.w	emit_btst_constant
	cmpi.w	#$805e,d1                       ; $805e multiply
	beq.w	emit_mul_int_constant
	cmpi.w	#$805f,d1                       ; $805f divide
	beq.w	emit_div_int_constant
	cmpi.w	#$8065,d1                       ; $8065 MOD
	beq.w	emit_mod_int_constant
	cmpi.w	#$814c,d1                       ; $814c word add
	beq.w	gen_add_constant_d0
	cmpi.w	#$814d,d1                       ; $814d word sub
	beq.w	gen_sub_constant_d0
	cmpi.w	#$814e,d1                       ; $814e word multiply
	beq.w	gen_mul_word_constant_d0

;------------------------------------------------------------------------------
; Loads the constant into d1 and leaves a0 on the operator word, so the operator's own handler (register form, e.g.
; add.l d1,d0) runs next.
;------------------------------------------------------------------------------
load_constant_operand_register:
	subq.l	#6,a0                           ; back onto the constant; the load leaves a0 on the operator
	moveq	#1,d2                           ; into d1
	bra.w	emit_load_long_constant

;------------------------------------------------------------------------------
; Codegen for IR $8007 c (integer constant value). d0 = c, d1 = next IR word. Folded with what follows: $80dc-$80e7
; (variable op-assign), $8017 (push: pea / clr.l -(sp)), $8027, $8042-$8045 (store into a variable), $80bf/$80c0,
; $80c7-$80ca, $8006 (to float: emitted as a float constant). Else moveq / move.w / move.l into d0.
;------------------------------------------------------------------------------
gen_int_constant:
	move.l	(a0)+,d0                        ; d0 = the constant
	move.w	(a0)+,d1                        ; d1 = the next IR word
	cmpi.w	#$80dc,d1                       ; $80dc integer variable += c
	beq.w	gen_integer_var_add_constant
	cmpi.w	#$80dd,d1                       ; $80dd integer variable -= c
	beq.w	gen_integer_var_sub_constant
	cmpi.w	#$80de,d1                       ; $80de integer variable *= c
	beq.w	gen_integer_var_mul_constant
	cmpi.w	#$80df,d1                       ; $80df integer variable /= c
	beq.w	gen_integer_var_div_constant
	cmpi.w	#$80e0,d1                       ; $80e0 word variable += c
	beq.w	gen_word_var_add_constant
	cmpi.w	#$80e1,d1                       ; $80e1 word variable -= c
	beq.w	gen_word_var_sub_constant
	cmpi.w	#$80e2,d1                       ; $80e2 word variable *= c
	beq.w	gen_word_var_mul_constant
	cmpi.w	#$80e3,d1                       ; $80e3 word variable /= c
	beq.w	gen_word_var_div_constant
	cmpi.w	#$80e4,d1                       ; $80e4 byte variable += c
	beq.w	gen_byte_var_add_constant
	cmpi.w	#$80e5,d1                       ; $80e5 byte variable -= c
	beq.w	gen_byte_var_sub_constant
	cmpi.w	#$80e6,d1                       ; $80e6 byte variable *= c
	beq.w	gen_byte_var_mul_constant
	cmpi.w	#$80e7,d1                       ; $80e7 byte variable /= c
	beq.w	gen_byte_var_div_constant
	cmpi.w	#$8017,d1                       ; push the constant
	beq.w	emit_push_constant_long
	cmpi.w	#$8027,d1                       ; $8027 push word
	beq.w	emit_push_constant_word
	cmpi.w	#$8042,d1                       ; $8042 store into an integer variable
	beq.w	gen_constant_store_integer_var
	cmpi.w	#$8043,d1                       ; $8043 store into a word variable
	beq.w	gen_constant_store_word_var
	cmpi.w	#$8044,d1                       ; $8044 store into a byte variable
	beq.w	gen_constant_store_byte_var
	cmpi.w	#$8045,d1                       ; $8045 store into a boolean variable
	beq.w	gen_constant_store_bool_var
	cmpi.w	#$80bf,d1                       ; $80bf jump if false
	beq.w	gen_constant_jump_if_false
	cmpi.w	#$80c0,d1                       ; $80c0 jump if true
	beq.w	gen_constant_jump_if_true
	cmpi.w	#$80c7,d1                       ; $80c7 integer array element store
	beq.w	gen_int_array_store_constant
	cmpi.w	#$80c8,d1                       ; $80c8 word array element store
	beq.w	gen_word_array_store_constant
	cmpi.w	#$80c9,d1                       ; $80c9 byte array element store
	beq.w	gen_byte_array_store_constant
	cmpi.w	#$80ca,d1                       ; $80ca boolean array element store
	beq.w	gen_bool_array_store_constant
	cmpi.w	#$8006,d1                       ; converted to float
	beq.w	emit_int_constant_as_float
	subq.l	#6,a0                           ; back to the constant; load it into d0
	moveq	#0,d2                           ; into d0
	bra.s	emit_load_long_constant

;------------------------------------------------------------------------------
; Codegen for IR $8009 c: load the constant into d2.
;------------------------------------------------------------------------------
load_constant_d2:
	moveq	#2,d2                           ; register d2
	bra.s	emit_load_long_constant

;------------------------------------------------------------------------------
; Codegen for IR $800a c: load the constant into d3.
;------------------------------------------------------------------------------
load_constant_d3:
	moveq	#3,d2                           ; register d3
	bra.s	emit_load_long_constant

;------------------------------------------------------------------------------
; Codegen for IR $800b c: load the constant into d4.
;------------------------------------------------------------------------------
load_constant_d4:
	moveq	#4,d2                           ; register d4
	bra.s	emit_load_long_constant

;------------------------------------------------------------------------------
; Codegen for IR $800c c: load the constant into d5.
;------------------------------------------------------------------------------
load_constant_d5:
	moveq	#5,d2                           ; register d5
	bra.s	emit_load_long_constant

;------------------------------------------------------------------------------
; Codegen for IR $800d c: load the constant into d6.
;------------------------------------------------------------------------------
load_constant_d6:
	moveq	#6,d2                           ; register d6
	bra.s	emit_load_long_constant

;------------------------------------------------------------------------------
; Codegen for IR $800e c: load the constant into d7.
;------------------------------------------------------------------------------
load_constant_d7:
	moveq	#7,d2                           ; register d7

;------------------------------------------------------------------------------
; Loads the long constant at (a0)+ into data register d2: moveq when it fits a byte, moveq / move.w #c
; (emit_load_word_constant) when only the low word is used (low_word_only returns Z), else
; emit_load_constant_dreg (moveq / swap or move.l #c).
;------------------------------------------------------------------------------
emit_load_long_constant:
	move.l	(a0)+,d0                        ; d0 = the constant
	move.l	d0,d1
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1                           ; fits a byte?
	beq.s	emit_load_constant_dreg         ; yes: moveq
	move.l	d0,-(sp)                        ; keep the constant
	bsr.w	low_word_only                   ; Z: only the low word of register d2 is used
	movem.l	(sp)+,d0                        ; movem keeps the flags
	beq.w	emit_load_word_constant         ; low word only: moveq / move.w #c

;------------------------------------------------------------------------------
; Emits code that loads the long constant d0 into data register d2 (0-7):
; moveq #n,Dd2 when it fits a byte; moveq #n,Dd2 / swap Dd2 for $00nn0000 or $ffnnffff;
; move.l #n,Dd2 otherwise.  a1 = code write pointer.  Reached from the IR $8007-$800e constant loads.
;------------------------------------------------------------------------------
emit_load_constant_dreg:
	move.b	d0,d1                           ; d0 = constant, d2 = register number
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1                           ; fits a byte?
	bne.s	.try_moveq_swap                 ; not a byte: try moveq / swap
	add.b	d2,d2                           ; $70 + 2*reg = moveq #n,Dreg opcode byte
	addi.b	#$70,d2                         ; $70 + 2*reg = moveq #n,Dreg opcode byte
	move.b	d2,(a1)+                        ; moveq opcode byte
	move.b	d0,(a1)+                        ; moveq data byte
	rts
.try_moveq_swap:
	move.l	d0,d1                           ; d1 = sign-extended byte of the high word, swapped back
	swap	d1
	ext.w	d1
	ext.l	d1
	swap	d1
	cmp.l	d0,d1                           ; high word a sign-extended byte, low word its sign?
	bne.s	.emit_move_long_immediate       ; not of the form $00nn0000 / $ffnnffff
	swap	d0                              ; d0.b = the byte of the high word
	move.w	#$38,d1                         ; ($38 + reg) * 2 = moveq #n,Dreg
	add.b	d2,d1
	add.b	d1,d1
	move.b	d1,(a1)+                        ; moveq opcode byte
	move.b	d0,(a1)+                        ; moveq data byte
	ori.w	#$4840,d2                       ; $4840 + reg = swap Dreg
	move.w	d2,(a1)+                        ; swap Dreg
	rts
.emit_move_long_immediate:
	ror.w	#7,d2                           ; reg << 9
	ori.w	#$203c,d2                       ; $203c = move.l #imm,d0, register added
	move.w	d2,(a1)+                        ; move.l #imm,Dreg
	move.l	d0,(a1)+                        ; the long immediate
	rts

;------------------------------------------------------------------------------
; Emits a push of the long constant d0: clr.l -(sp) for 0, pea (n).w when it fits a word, pea (n).l
; otherwise.  Used for IR $8007 (constant) followed by $8017 (push).
;------------------------------------------------------------------------------
emit_push_constant_long:
	tst.l	d0                              ; 0: clr.l -(sp)
	beq.s	.emit_clr_long_push
	move.w	d0,d1
	ext.l	d1                              ; word sign-extended
	cmp.l	d0,d1                           ; does not fit a word
	beq.s	.emit_pea_word
	move.w	#$4879,(a1)+                    ; $4879 = pea (xxx).l
	move.l	d0,(a1)+                        ; the long
	rts
.emit_pea_word:
	move.w	#$4878,(a1)+                    ; $4878 = pea (xxx).w
	move.w	d0,(a1)+                        ; the word
	rts
.emit_clr_long_push:
	move.w	#$42a7,(a1)+                    ; $42a7 = clr.l -(sp)
	rts

;------------------------------------------------------------------------------
; Emits a push of the word constant d0: clr.w -(sp) for 0, move.w #n,-(sp) otherwise.  Used for IR
; $8007 followed by $8027 (push word).
;------------------------------------------------------------------------------
emit_push_constant_word:
	tst.w	d0                              ; 0: clr.w -(sp)
	beq.s	.emit_clr_word_push
	move.w	#$3f3c,(a1)+                    ; $3f3c = move.w #imm,-(sp)
	move.w	d0,(a1)+                        ; the immediate
	rts
.emit_clr_word_push:
	move.w	#$4267,(a1)+                    ; $4267 = clr.w -(sp)
	rts

;------------------------------------------------------------------------------
; IR $800f: load the long constant that follows in the IR into a0.
;------------------------------------------------------------------------------
gen_load_constant_a0:
	moveq	#0,d2                           ; a0
	bra.s	emit_load_constant_areg

;------------------------------------------------------------------------------
; IR $8010: load the long constant that follows in the IR into a1.
;------------------------------------------------------------------------------
gen_load_constant_a1:
	moveq	#1,d2                           ; a1

;------------------------------------------------------------------------------
; Reads the long constant from the IR ((a0)+) and emits a load of address register d2 (0 = a0, 1 = a1):
; suba.l An,An for 0, movea.w #n,An when it fits a word, movea.l #n,An otherwise.
;------------------------------------------------------------------------------
emit_load_constant_areg:
	move.l	(a0)+,d0                        ; the long constant from the IR
	bne.s	.nonzero_constant
	move.w	d2,d3                           ; d3 = register for the source field
	ror.w	#7,d2                           ; register into bits 9-11
	or.w	d3,d2                           ; register in both fields
	ori.w	#$91c8,d2                       ; $91c8 = suba.l a0,a0, registers added
	move.w	d2,(a1)+                        ; suba.l An,An
	rts
.nonzero_constant:
	move.w	d0,d1
	ext.l	d1                              ; word sign-extended
	cmp.l	d0,d1                           ; fits a word?
	beq.s	.emit_movea_word
	ror.w	#7,d2                           ; register into bits 9-11
	ori.w	#$207c,d2                       ; $207c = movea.l #imm,a0, register added
	move.w	d2,(a1)+                        ; movea.l #imm,An
	move.l	d0,(a1)+                        ; the long
	rts
.emit_movea_word:
	ror.w	#7,d2                           ; register into bits 9-11
	ori.w	#$307c,d2                       ; $307c = movea.w #imm,a0, register added
	move.w	d2,(a1)+                        ; movea.w #imm,An
	move.w	d0,(a1)+                        ; the word
	rts

;------------------------------------------------------------------------------
; IR $8017: push d0.  Looks at the next IR word (skipping one load in between: an IR $8007
; constant, a variable into d0 ($803c $803d $803f $8040) or into d1-d7/a0/a1 ($8084-$808c $808d-$8095
; $8099-$809f $80b4-$80ba), or an $8028):
; when that is a pop into a register (IR $801b-$8023) the push and pop become one move.l d0,Dn /
; movea.l d0,An and the pop is overwritten with IR $8028 (no code).  Otherwise emits move.l d0,-(sp).
;------------------------------------------------------------------------------
gen_push_d0:
	movea.l	a0,a2                           ; a2 = look-ahead in the IR
	move.w	(a0),d0                         ; d0 = the next IR code
	cmpi.w	#$8028,d0                       ; $8028 = no code
	beq.s	.check_for_pop
	cmpi.w	#$8007,d0                       ; $8007 = constant with a long operand
	beq.s	.skip_long_operand
	cmpi.w	#$803f,d0                       ; $803f integer variable into d0
	beq.s	.skip_load
	cmpi.w	#$8040,d0                       ; $8040 word variable into d0
	beq.s	.skip_load
	cmpi.w	#$803d,d0                       ; $803d byte variable into d0
	beq.s	.skip_load
	cmpi.w	#$803c,d0                       ; $803c boolean variable into d0
	beq.s	.skip_load
	cmpi.w	#$8084,d0                       ; $8084-$808c: integer variable into d1-d7 / a0 / a1
	bcs.s	.not_integer_var_load
	cmpi.w	#$808c,d0
	bls.s	.skip_load
.not_integer_var_load:
	cmpi.w	#$808d,d0                       ; $808d-$8095
	bcs.s	.not_word_var_load
	cmpi.w	#$8095,d0
	bls.s	.skip_load
.not_word_var_load:
	cmpi.w	#$8099,d0                       ; $8099-$809f
	bcs.s	.not_byte_var_load
	cmpi.w	#$809f,d0
	bls.s	.skip_load
.not_byte_var_load:
	cmpi.w	#$80b4,d0                       ; $80b4-$80ba
	bcs.s	.not_other_var_load
	cmpi.w	#$80ba,d0
	bls.s	.skip_load
.not_other_var_load:
	cmpi.w	#$801b,d0                       ; $801b-$8023 = pop into d1..d7, a0, a1
	bcs.s	.emit_push_d0
	cmpi.w	#$8023,d0
	bls.s	.check_for_pop
.emit_push_d0:
	move.w	#$2f00,(a1)+                    ; $2f00 = move.l d0,-(sp)
	rts
.skip_long_operand:
	addq.l	#2,a2                           ; $8007: code + long operand
.skip_load:
	addq.l	#4,a2                           ; skip code + word operand
.check_for_pop:
	move.w	(a2),d0                         ; d0 = the IR after the push (or after one load)
	subi.w	#$801a,d0                       ; register number: $801a = d0 ... $8021 = d7, $8022 = a0, $8023 = a1
	beq.s	.emit_push_d0                   ; a pop into d0 straight after: just push
	cmpi.w	#$a,d0                          ; above 10: not a pop (10, $8024, gets through)
	bhi.s	.emit_push_d0
	cmpi.w	#$8,d0                          ; 8 and 9 are a0 / a1
	bcc.s	.move_to_areg
	ror.w	#7,d0                           ; register into bits 9-11
	ori.w	#$2000,d0                       ; $2000 = move.l d0,d0, destination register added
	move.w	d0,(a1)+                        ; move.l d0,Dn
	move.w	#$8028,(a2)                     ; the pop becomes $8028 (no code)
	rts
.move_to_areg:
	subq.w	#8,d0                           ; a0 / a1: register 0 / 1
	ror.w	#7,d0                           ; register into bits 9-11
	ori.w	#$2040,d0                       ; $2040 = movea.l d0,a0, register added
	move.w	d0,(a1)+                        ; movea.l d0,An
	move.w	#$8028,(a2)                     ; the pop becomes $8028 (no code)
	rts

gen_add_stack_to_d0:
	move.w	#$d09f,(a1)+                    ; $d09f = add.l (sp)+,d0
	bra.s	set_current_ir_code

gen_sub_stack_from_d0:
	move.w	#$909f,(a1)+                    ; $909f = sub.l (sp)+,d0
	bra.s	set_current_ir_code

gen_and_stack_to_d0:
	move.w	#$c09f,(a1)+                    ; $c09f = and.l (sp)+,d0
	bra.s	set_current_ir_code

gen_or_stack_to_d0:
	move.w	#$809f,(a1)+                    ; $809f = or.l (sp)+,d0

;------------------------------------------------------------------------------
; Stores d1 (the IR operator just consumed) as current_ir_code, so the next handler sees it as the previous
; code.
;------------------------------------------------------------------------------
set_current_ir_code:
	move.w	d1,current_ir_code
	rts

gen_stack_compare_eq:
	moveq	#7,d0                           ; seq
	bra.s	emit_stack_compare_scc

gen_stack_compare_ne:
	moveq	#6,d0                           ; sne
	bra.s	emit_stack_compare_scc

gen_stack_compare_gt:
	moveq	#14,d0                          ; sgt
	bra.s	emit_stack_compare_scc

gen_stack_compare_ge:
	moveq	#12,d0                          ; sge
	bra.s	emit_stack_compare_scc

gen_stack_compare_lt:
	moveq	#13,d0                          ; slt
	bra.s	emit_stack_compare_scc

gen_stack_compare_le:
	moveq	#15,d0                          ; sle

;------------------------------------------------------------------------------
; Emits sub.l (sp)+,d0 and Scc d0 with condition d0 (cc number), then finishes the truth value at
; finish_condition_result.
;------------------------------------------------------------------------------
emit_stack_compare_scc:
	move.w	#$909f,(a1)+                    ; $909f = sub.l (sp)+,d0
	asl.w	#8,d0                           ; condition into bits 8-11
	ori.w	#$50c0,d0                       ; $50c0 = st d0, condition added
	move.w	d0,(a1)+                        ; Scc d0
	bra.w	finish_condition_result

gen_add_d0_to_stack:
	move.w	#$d197,(a1)+                    ; $d197 = add.l d0,(sp)

skip_push_ir_word:
	addq.l	#2,a0                           ; skip the $8017 push
	rts

gen_and_d0_to_stack:
	move.w	#$c197,(a1)+                    ; $c197 = and.l d0,(sp)
	bra.s	skip_push_ir_word

gen_or_d0_to_stack:
	move.w	#$8197,(a1)+                    ; $8197 = or.l d0,(sp)
	bra.s	skip_push_ir_word

gen_eor_d0_to_stack:
	move.w	#$b197,(a1)+                    ; $b197 = eor.l d0,(sp)
	bra.s	skip_push_ir_word

gen_sub_d0_from_stack:
	move.w	#$9197,(a1)+                    ; $9197 = sub.l d0,(sp)
	addq.l	#4,a0                           ; skip $8064 and $8017
	rts

;------------------------------------------------------------------------------
; IR $801b: pop the stack into d1.  Combines with the IR that follows:
; - $801b op $8017 (pop, op, push) for add/and/or/eor ($8063/$8060/$8061/$8062) becomes one op.l d0,(sp);
;   $801b $8083 $8064 $8017 becomes sub.l d0,(sp); $801b $8083 $8064 becomes sub.l (sp)+,d0 / neg.l d0;
; - $801b op for add/sub/and/or becomes op.l (sp)+,d0;
; - $801b compare ($807b-$8080) becomes sub.l (sp)+,d0 / Scc d0;
; - $801b $8100 pops straight into an integer variable (gen_pop_store_integer_var);
; - otherwise move.l (sp)+,d1.
;------------------------------------------------------------------------------
gen_pop_d1:
	move.w	(a0)+,d1                        ; d1 = the IR operator after the pop
	cmpi.w	#$8017,(a0)                     ; followed by $8017 push?
	bne.s	.no_push_after
	cmpi.w	#$8063,d1                       ; $8063 = add
	beq.s	gen_add_d0_to_stack
	cmpi.w	#$8061,d1                       ; $8061 = or
	beq.s	gen_or_d0_to_stack
	cmpi.w	#$8060,d1                       ; $8060 = and
	beq.s	gen_and_d0_to_stack
	cmpi.w	#$8062,d1                       ; $8062 = eor
	beq.s	gen_eor_d0_to_stack
.no_push_after:
	cmpi.w	#$8083,d1                       ; $8083 = exchange d0/d1
	bne.s	.fold_with_stack
	cmpi.w	#$8064,(a0)                     ; $8064 = sub
	bne.s	.fold_with_stack
	cmpi.w	#$8017,2(a0)                    ; and a $8017 push after the sub?
	beq.s	gen_sub_d0_from_stack
	addq.l	#2,a0                           ; skip the $8064
	move.w	#$909f,(a1)+                    ; $909f = sub.l (sp)+,d0
	bra.w	gen_negate_d0
.fold_with_stack:
	cmpi.w	#$8063,d1                       ; $8063 add
	beq.w	gen_add_stack_to_d0
	cmpi.w	#$8064,d1                       ; $8064 sub
	beq.w	gen_sub_stack_from_d0
	cmpi.w	#$8060,d1                       ; $8060 and
	beq.w	gen_and_stack_to_d0
	cmpi.w	#$8061,d1                       ; $8061 or
	beq.w	gen_or_stack_to_d0
	cmpi.w	#$807b,d1                       ; $807b = equal
	beq.w	gen_stack_compare_eq
	cmpi.w	#$807c,d1                       ; $807c = not equal
	beq.w	gen_stack_compare_ne
	cmpi.w	#$807e,d1                       ; $807e = greater
	beq.w	gen_stack_compare_gt
	cmpi.w	#$807d,d1                       ; $807d = greater or equal
	beq.w	gen_stack_compare_ge
	cmpi.w	#$8080,d1                       ; $8080 = less
	beq.w	gen_stack_compare_lt
	cmpi.w	#$807f,d1                       ; $807f = less or equal
	beq.w	gen_stack_compare_le
	cmpi.w	#$8100,d1                       ; $8100 = store d1 into an integer variable
	beq.w	gen_pop_store_integer_var
	subq.l	#2,a0                           ; nothing to combine: back to the operator
	moveq	#1,d0                           ; d1
	bra.s	emit_pop_dreg

gen_pop_d0:
	moveq	#0,d0                           ; register d0
	bra.s	emit_pop_dreg

gen_pop_d2:
	moveq	#2,d0                           ; register d2
	bra.s	emit_pop_dreg

gen_pop_d3:
	moveq	#3,d0                           ; register d3
	bra.s	emit_pop_dreg

gen_pop_d4:
	moveq	#4,d0                           ; register d4
	bra.s	emit_pop_dreg

gen_pop_d5:
	moveq	#5,d0                           ; register d5
	bra.s	emit_pop_dreg

gen_pop_d6:
	moveq	#6,d0                           ; register d6
	bra.s	emit_pop_dreg

gen_pop_d7:
	moveq	#7,d0                           ; register d7

;------------------------------------------------------------------------------
; Emits move.l (sp)+,Dn for data register d0 (0-7).  IR $801a-$8021 pop into d0..d7 ($801b = d1 is handled
; at gen_pop_d1).
;------------------------------------------------------------------------------
emit_pop_dreg:
	ror.w	#7,d0                           ; register into bits 9-11
	ori.w	#$201f,d0                       ; $201f = move.l (sp)+,d0, register added
	move.w	d0,(a1)+                        ; move.l (sp)+,Dn
	rts

gen_pop_a0:
	moveq	#0,d0                           ; register a0
	bra.s	emit_pop_areg

gen_pop_a1:
	moveq	#1,d0                           ; register a1

;------------------------------------------------------------------------------
; Emits movea.l (sp)+,An for address register d0 (0 = a0, 1 = a1).  IR $8022/$8023.
;------------------------------------------------------------------------------
emit_pop_areg:
	ror.w	#7,d0                           ; register into bits 9-11
	ori.w	#$205f,d0                       ; $205f = movea.l (sp)+,a0, register added
	move.w	d0,(a1)+                        ; movea.l (sp)+,An
	rts

;------------------------------------------------------------------------------
; IR $802c: SGN of the float in d0-d2.  d2 is the float's exponent word, whose sign is the number's sign
; (see gen_float_negate).  Emits tst.w d2 (left out when the last code was move.w (a0)+,d1 / move.w (a0)+,d2,
; which set the flags already) and a branch sequence that leaves 1, 0 or -1 in d0.  When IR $81fc follows
; (consumed here) only beq.s / moveq #1,d0 is emitted.  Ends at mark_result_modified.
;------------------------------------------------------------------------------
gen_float_sgn:
	cmpi.l	#$32183418,-$4(a1)              ; $3218 $3418 = move.w (a0)+,d1 / move.w (a0)+,d2 (flags already from
                                                ;   d2)
	beq.s	.float_flags_set                ; yes: flags already from d2
	move.w	#$4a42,(a1)+                    ; $4a42 = tst.w d2
.float_flags_set:
	cmpi.w	#$81fc,(a0)                     ; $81fc follows: only zero / nonzero is wanted
	beq.s	.float_sgn_then_abs
	move.w	#$6e06,(a1)+                    ; $6e06 = bgt.s +6
	move.l	#$6b087000,(a1)+                ; bmi.s +8 / moveq #0,d0
	move.l	#$60067001,(a1)+                ; bra.s +6 / moveq #1,d0
	move.l	#$600270ff,(a1)+                ; bra.s +2 / moveq #-1,d0
	bra.w	mark_result_modified
.float_sgn_then_abs:
	addq.l	#2,a0                           ; consume the $81fc
	move.l	#$67027001,(a1)+                ; beq.s +2 / moveq #1,d0
	bra.w	mark_result_modified

;------------------------------------------------------------------------------
; IR $8200 (ABS of a float, written by parse_fn_abs): tst.w d2 / bgt.s +2, falling into gen_float_negate
; (neg.w d2): the sign of a float is the sign of its exponent word.
;------------------------------------------------------------------------------
gen_ir_8200_float_abs:
	cmpi.l	#$32183418,-$4(a1)              ; $3218 $3418 = move.w (a0)+,d1 / move.w (a0)+,d2 just emitted?
	beq.s	.emit_bgt_skip
	move.w	#$4a42,(a1)+                    ; $4a42 = tst.w d2
.emit_bgt_skip:
	move.w	#$6e02,(a1)+                    ; $6e02 = bgt.s +2 (skip the neg.w d2 that follows)

;------------------------------------------------------------------------------
; IR $802d: negate the float in d0-d2 by emitting neg.w d2 (the exponent word carries the sign).
;------------------------------------------------------------------------------
gen_float_negate:
	move.w	#$4442,(a1)+                    ; $4442 = neg.w d2
	rts

gen_add_d1_to_d0:
	move.w	#$d081,(a1)+                    ; $d081 = add.l d1,d0
	rts

;------------------------------------------------------------------------------
; IR $814c: word add, emits add.w d1,d0.  The optimiser writes $814c in place of $8063 when only the low word
; of the result is used.
;------------------------------------------------------------------------------
gen_ir_814c_add_word_d1_to_d0:
	move.w	#$d041,(a1)+                    ; $d041 = add.w d1,d0
	rts

;------------------------------------------------------------------------------
; IR $814d: word subtract, emits sub.w d1,d0 (the word form of $8064).
;------------------------------------------------------------------------------
gen_ir_814d_sub_word_d1_from_d0:
	move.w	#$9041,(a1)+                    ; $9041 = sub.w d1,d0
	rts

gen_sub_d1_from_d0:
	move.w	#$9081,(a1)+                    ; $9081 = sub.l d1,d0
	rts

gen_double_d0:
	move.w	#$d080,(a1)+                    ; $d080 = add.l d0,d0
	rts

;------------------------------------------------------------------------------
; IR $8011: call library routine $28f DOUBLE (the float in registers times two).
;------------------------------------------------------------------------------
gen_float_double:
	move.w	#$28f,d0                        ; library routine $28f DOUBLE
	bra.w	emit_library_call

gen_compare_eq:
	moveq	#7,d2                           ; seq
	bra.s	emit_compare_scc

gen_compare_ne:
	moveq	#6,d2                           ; sne
	bra.s	emit_compare_scc

gen_compare_ge:
	moveq	#12,d2                          ; sge
	bra.s	emit_compare_scc

gen_compare_gt:
	moveq	#14,d2                          ; sgt
	bra.s	emit_compare_scc

gen_compare_lt:
	moveq	#13,d2                          ; slt
	bra.s	emit_compare_scc

gen_compare_le:
	moveq	#15,d2                          ; sle

;------------------------------------------------------------------------------
; Emits sub.l d1,d0 and Scc d0 with condition d2, then finishes the truth value at
; finish_condition_result.  IR $807b-$8081 integer compares.
;------------------------------------------------------------------------------
emit_compare_scc:
	move.w	#$9081,(a1)+                    ; $9081 = sub.l d1,d0
	rol.w	#8,d2                           ; condition into bits 8-11
	ori.w	#$50c0,d2                       ; $50c0 = st d0, condition added
	move.w	d2,(a1)+                        ; Scc d0
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $807a: drops a trailing ext.l d0, emits lsr.b #1,d0 / scs d0 (true when d0 is odd), then
; finish_condition_result.
;------------------------------------------------------------------------------
gen_odd_test:
	bsr.w	drop_trailing_ext_long
	move.w	#$e208,(a1)+                    ; $e208 = lsr.b #1,d0
	move.w	#$55c0,(a1)+                    ; $55c0 = scs d0
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $8079: drops a trailing ext.l d0, emits lsr.b #1,d0 / scc d0 (true when d0 is even), then
; finish_condition_result.
;------------------------------------------------------------------------------
gen_even_test:
	bsr.w	drop_trailing_ext_long
	move.w	#$e208,(a1)+                    ; $e208 = lsr.b #1,d0
	move.w	#$54c0,(a1)+                    ; $54c0 = scc d0
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $8082: SGN of the integer d0.  Emits tst.l d0 if the flags do not already reflect d0, then
; beq.s / bmi.s / moveq #1,d0 / bra.s / moveq #-1,d0.  When IR $81fc follows (consumed here) only beq.s /
; moveq #1,d0 is emitted.  Ends at mark_result_modified.
;------------------------------------------------------------------------------
gen_integer_sgn:
	bsr.w	emit_test_d0
	cmpi.w	#$81fc,(a0)                     ; $81fc follows: only zero / nonzero is wanted
	beq.s	.int_sgn_then_abs
	move.w	#$6708,(a1)+                    ; $6708 = beq.s +8
	move.l	#$6b047001,(a1)+                ; bmi.s +4 / moveq #1,d0
	move.l	#$600270ff,(a1)+                ; bra.s +2 / moveq #-1,d0
	bra.w	mark_result_modified
.int_sgn_then_abs:
	addq.l	#2,a0                           ; consume the $81fc
	move.l	#$67027001,(a1)+                ; beq.s +2 / moveq #1,d0
	bra.w	mark_result_modified

;------------------------------------------------------------------------------
; IR $81fc: integer ABS of d0.  Emits tst.l d0 if the flags do not already reflect d0 (emit_test_d0_keep_extend),
; bgt.s +2, then falls into gen_negate_d0 (neg.l d0).  gen_integer_sgn and gen_float_sgn consume a following $81fc
; themselves (ABS of SGN is 0 or 1).
;------------------------------------------------------------------------------
gen_ir_81fc_integer_abs:
	bsr.w	emit_test_d0_keep_extend        ; IR $81fc entry: integer ABS (tst.l d0 / bgt.s +2 / neg.l d0)
	move.w	#$6e02,(a1)+                    ; $6e02 = bgt.s +2 (skip the neg.l d0)

;------------------------------------------------------------------------------
; IR $8078: negate d0 (neg.l d0) and continue at mark_result_modified.
;------------------------------------------------------------------------------
gen_negate_d0:
	move.w	#$4480,(a1)+                    ; $4480 = neg.l d0
	bra.w	mark_result_modified

gen_and_d1_to_d0:
	move.w	#$c081,(a1)+                    ; $c081 = and.l d1,d0
	rts

gen_or_d1_to_d0:
	move.w	#$8081,(a1)+                    ; $8081 = or.l d1,d0
	rts

gen_eor_d1_to_d0:
	move.w	#$b380,(a1)+                    ; $b380 = eor.l d1,d0
	rts

gen_eqv:
	move.l	#$b3804680,(a1)+                ; eor.l d1,d0 / not.l d0
	rts

gen_imp:
	move.l	#$b1814681,(a1)+                ; eor.l d0,d1 / not.l d1
	move.w	#$8081,(a1)+                    ; $8081 = or.l d1,d0
	rts

gen_bit_change:
	move.w	#$340,(a1)+                     ; $0340 = bchg d1,d0
	rts

gen_bit_set:
	move.w	#$3c0,(a1)+                     ; $03c0 = bset d1,d0
	rts

gen_bit_clear:
	move.w	#$380,(a1)+                     ; $0380 = bclr d1,d0
	rts

;------------------------------------------------------------------------------
; IR $8074: BTST.  Emits btst d1,d0 / sne d0; when the previous IR was $8083 (exg d1,d0 just emitted) the
; exg is overwritten with btst d0,d1 instead.  Then finish_condition_result.
;------------------------------------------------------------------------------
gen_bit_test:
	cmpi.w	#$8083,previous_ir_code         ; previous IR $8083: exg d1,d0 was just emitted
	beq.s	.btst_after_exg
	move.w	#$300,(a1)+                     ; $0300 = btst d1,d0
.emit_sne:
	move.w	#$56c0,(a1)+                    ; $56c0 = sne d0
	bra.w	finish_condition_result
.btst_after_exg:
	move.w	#$101,-$2(a1)                   ; overwrite the exg with $0101 = btst d0,d1
	bra.s	.emit_sne

gen_shift_left_long:
	move.w	#$e3a8,(a1)+                    ; $e3a8 = lsl.l d1,d0
	rts

gen_shift_right_long:
	move.w	#$e2a8,(a1)+                    ; $e2a8 = lsr.l d1,d0
	rts

gen_rotate_left_long:
	move.w	#$e3b8,(a1)+                    ; $e3b8 = rol.l d1,d0
	rts

gen_rotate_right_long:
	move.w	#$e2b8,(a1)+                    ; $e2b8 = ror.l d1,d0
	rts

gen_rotate_left_byte:
	move.w	#$e338,-(sp)                    ; $e338 = rol.b d1,d0

;------------------------------------------------------------------------------
; Drops trailing ext.w / ext.l d0, then emits the byte shift/rotate opcode taken from the stack and
; zero-extends the byte at gen_zero_extend_byte.
;------------------------------------------------------------------------------
emit_byte_shift:
	bsr.w	drop_trailing_extends
	move.w	(sp)+,(a1)+                     ; the opcode
	bra.s	gen_zero_extend_byte

gen_rotate_right_byte:
	move.w	#$e238,-(sp)                    ; $e238 = ror.b d1,d0
	bra.s	emit_byte_shift

gen_shift_left_byte:
	move.w	#$e328,-(sp)                    ; $e328 = lsl.b d1,d0
	bra.s	emit_byte_shift

gen_shift_right_byte:
	move.w	#$e228,-(sp)                    ; $e228 = lsr.b d1,d0
	bra.s	emit_byte_shift

gen_shift_left_word:
	move.w	#$e368,-(sp)                    ; $e368 = lsl.w d1,d0

;------------------------------------------------------------------------------
; Drops a trailing ext.l d0, then emits the word shift/rotate opcode taken from the stack and
; sign-extends the word at gen_sign_extend_word.
;------------------------------------------------------------------------------
emit_word_shift:
	bsr.w	drop_trailing_ext_long
	move.w	(sp)+,(a1)+                     ; the opcode
	bra.w	gen_sign_extend_word

gen_shift_right_word:
	move.w	#$e268,-(sp)                    ; $e268 = lsr.w d1,d0
	bra.s	emit_word_shift

gen_rotate_left_word:
	move.w	#$e378,-(sp)                    ; $e378 = rol.w d1,d0
	bra.s	emit_word_shift

gen_rotate_right_word:
	move.w	#$e278,-(sp)                    ; $e278 = ror.w d1,d0
	bra.s	emit_word_shift

;------------------------------------------------------------------------------
; IR $802e: make d0 an unsigned byte with andi.l #$ff,d0.  Left out (or reduced to andi.w #$ff,d0) when
; the value is only stored as a byte ($8096) or word ($8097) through a0, after the IR that sets a0
; ($808b/$8094 variable, $800f constant, $8022 pop).
;------------------------------------------------------------------------------
gen_zero_extend_byte:
	cmpi.w	#$808b,(a0)                     ; $808b = integer variable into a0
	beq.s	.a0_from_variable
	cmpi.w	#$8094,(a0)                     ; $8094 = word variable into a0
	beq.s	.a0_from_variable
	cmpi.w	#$800f,(a0)                     ; $800f constant load into a0
	beq.s	.a0_from_constant
	cmpi.w	#$8022,(a0)                     ; $8022 pop into a0
	beq.s	.a0_from_pop
.emit_andi_long_ff:
	move.w	#$280,(a1)+                     ; $0280 = andi.l #imm,d0
	move.l	#$ff,(a1)+                      ; the immediate
	rts
.a0_from_variable:
	move.w	4(a0),d0                        ; the IR after the a0 load
.check_store_size:
	cmpi.w	#$8096,d0                       ; $8096 = byte store: nothing needed
	beq.s	.byte_extend_done
	cmpi.w	#$8097,d0                       ; $8097 = word store
	beq.s	.emit_andi_word_ff
	bra.s	.emit_andi_long_ff
.emit_andi_word_ff:
	move.l	#$24000ff,(a1)+                 ; $0240 $00ff = andi.w #$ff,d0
.byte_extend_done:
	rts
.a0_from_constant:
	move.w	6(a0),d0                        ; the IR after $800f and its long constant
	bra.s	.check_store_size
.a0_from_pop:
	move.w	2(a0),d0                        ; the IR after the pop
	bra.s	.check_store_size

;------------------------------------------------------------------------------
; Called after an Scc d0 has been emitted.  Looks at the next three IR words:
; - $8032 (NOT): inverts the Scc condition, consumes the NOT and looks again;
; - $80bf / $80c0 (jump if false / true): removes the Scc and emits a Bcc with the matching condition at
;   emit_conditional_jump (d7 = Bcc opcode byte);
; - $801b $8061/$8060/$8062 $8017 (combine with the stacked value by or/and/eor): replaces the Scc with a
;   branch over moveq #-1,d0 / move.l d0,(sp), clr.l (sp) or not.l (sp);
; - otherwise emits ext.w d0 and goes on to gen_sign_extend_word.
;------------------------------------------------------------------------------
finish_condition_result:
	movem.w	(a0)+,d0-d2                     ; d0-d2 = the next three IR words
	cmpi.w	#$8032,d0                       ; $8032 = NOT
	bne.s	.check_jump
	eori.w	#$100,-$2(a1)                   ; flip the condition of the Scc just emitted
	subq.l	#4,a0                           ; consume only the NOT
	bra.s	finish_condition_result
.check_jump:
	cmpi.w	#$80bf,d0                       ; $80bf = jump if false
	beq.s	.jump_if_false
	cmpi.w	#$80c0,d0                       ; $80c0 = jump if true
	beq.s	.jump_if_true
	cmpi.w	#$801b,d0                       ; $801b pop d1, op, $8017 push
	bne.s	.extend_result
	cmpi.w	#$8017,d2                       ; push after the operator?
	bne.s	.extend_result
	cmpi.w	#$8061,d1                       ; $8061 = or
	beq.s	.or_into_stack
	cmpi.w	#$8060,d1                       ; $8060 = and
	beq.s	.and_into_stack
	cmpi.w	#$8062,d1                       ; $8062 = eor
	beq.s	.eor_into_stack
	bra.s	.extend_result
.or_into_stack:
	move.w	-(a1),d0                        ; the Scc: keep its condition
	andi.w	#$f00,d0                        ; condition bits
	eori.w	#$6104,d0                       ; eor $6104: Bcc.s +4 with the inverted condition
	move.w	d0,(a1)+                        ; Bcc.s +4, inverted
	move.w	#$70ff,(a1)+                    ; $70ff = moveq #-1,d0
	move.w	#$2e80,(a1)+                    ; $2e80 = move.l d0,(sp)
	rts
.and_into_stack:
	move.w	-(a1),d0                        ; the Scc: keep its condition
	andi.w	#$f00,d0                        ; condition bits
	ori.w	#$6002,d0                       ; $6002 = bcc.s +2 with the Scc condition
	move.w	d0,(a1)+                        ; Bcc.s +2
	move.w	#$4297,(a1)+                    ; $4297 = clr.l (sp)
	rts
.eor_into_stack:
	move.w	-(a1),d0                        ; the Scc: keep its condition
	andi.w	#$f00,d0                        ; condition bits
	ori.w	#$6002,d0                       ; $6002 = bcc.s +2 with the Scc condition
	move.w	d0,(a1)+                        ; Bcc.s +2
	move.w	#$4697,(a1)+                    ; $4697 = not.l (sp), skipped when true: looks inverted for EOR
	rts
.jump_if_true:
	moveq	#96,d7                          ; $60 = bra: Bcc with the same condition
	bra.s	.scc_to_bcc
.jump_if_false:
	moveq	#97,d7                          ; $61: Bcc with the inverted condition
.scc_to_bcc:
	subq.l	#4,a0                           ; consume only the jump IR; a0 on its target
	subq.l	#2,a1                           ; remove the Scc
	moveq	#15,d0                          ; condition of the Scc
	and.b	(a1),d0                         ; d0 = condition from the Scc's high byte
	eor.b	d0,d7                           ; d7 = Bcc opcode byte
	bra.w	emit_conditional_jump
.extend_result:
	subq.l	#6,a0                           ; nothing consumed: back over the three words
	move.w	#$4880,(a1)+                    ; $4880 = ext.w d0

;------------------------------------------------------------------------------
; IR $802f: make the word in d0 a long (ext.l d0), only when it is needed.  Drops a trailing ext.l first.
; Looks at the next IR word: for PRINUM/PXINUM/P0RINUM/P0XINUM it changes the routine to the word version
; (PRWNUM/PXWNUM/P0RWNUM/P0XWNUM), IR $8006 becomes FWTOF; users that take a word ($80bf $80c0 $8043
; $80e0-$80e7 $8027 FORW1 FORW2, byte/word stores through a0) need no ext.l.  For $8084/$808d/$8099 followed by
; add/sub/$805e/and/or/eor it changes the operator to the word form ($814c/$814d/$814e or the same code)
; when what comes after takes a word ($8043 $8044 $8027 FORW1 FORW2; the routine_flag_table test there checks
; d0 instead of d1 and never succeeds).  Otherwise emits ext.l d0 and records its address in
; ext_l_d0_code_address so it can be dropped later.
;------------------------------------------------------------------------------
gen_sign_extend_word:
	bsr.w	drop_trailing_ext_long
	move.w	(a0),d0                         ; d0 = the IR that uses the value
	cmpi.w	#$40,d0                         ; PRINUM
	beq.w	.use_prwnum
	cmpi.w	#$f2,d0                         ; PXINUM
	beq.w	.use_pxwnum
	cmpi.w	#$261,d0                        ; P0RINUM
	beq.w	.use_p0rwnum
	cmpi.w	#$260,d0                        ; P0XINUM
	beq.w	.use_p0xwnum
	cmpi.w	#$80bf,d0                       ; consumers that only need a word follow
	beq.w	.no_ext_needed
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.w	.no_ext_needed
	cmpi.w	#$8043,d0                       ; $8043 word store
	beq.w	.no_ext_needed
	cmpi.w	#$80e0,d0                       ; $80e0-$80e7 word / byte variable op= value
	beq.w	.no_ext_needed
	cmpi.w	#$80e1,d0
	beq.s	.no_ext_needed
	cmpi.w	#$80e2,d0
	beq.s	.no_ext_needed
	cmpi.w	#$80e3,d0
	beq.s	.no_ext_needed
	cmpi.w	#$80e4,d0
	beq.s	.no_ext_needed
	cmpi.w	#$80e5,d0
	beq.s	.no_ext_needed
	cmpi.w	#$80e6,d0
	beq.s	.no_ext_needed
	cmpi.w	#$80e7,d0
	beq.s	.no_ext_needed
	cmpi.w	#$8027,d0                       ; $8027 = push word
	beq.s	.no_ext_needed
	cmpi.w	#$1ae,d0                        ; FORW1
	beq.s	.no_ext_needed
	cmpi.w	#$1af,d0                        ; FORW2
	beq.s	.no_ext_needed
	cmpi.w	#$808b,d0                       ; $808b / $8094: a0 loaded from a variable
	beq.s	.a0_from_var_store
	cmpi.w	#$8094,d0                       ; $8094 word variable into a0
	beq.s	.a0_from_var_store
	cmpi.w	#$800f,d0                       ; $800f constant into a0
	beq.s	.a0_from_constant_store
	cmpi.w	#$8022,d0                       ; $8022 pop into a0
	beq.s	.a0_from_pop_store
	cmpi.w	#$8006,d0                       ; $8006
	beq.s	.use_fwtof
	movea.l	a0,a2                           ; a2 = look-ahead pointer
	cmpi.w	#$8084,d0                       ; $8084 / $808d / $8099 followed by an operator
	beq.s	.try_word_operator
	cmpi.w	#$808d,d0
	beq.s	.try_word_operator
	cmpi.w	#$8099,d0
	beq.s	.try_word_operator
.extend_unless_word_used:
	bsr.w	low_word_only_d0                ; Z: only the low word of d0 is used
	beq.s	.no_ext_needed                  ; then no ext.l
.emit_ext_long:
	move.l	a1,ext_l_d0_code_address        ; remember where the ext.l is
	move.w	#$48c0,(a1)+                    ; $48c0 = ext.l d0
.no_ext_needed:
	rts
.use_prwnum:
	move.w	#$1b0,(a0)                      ; PRINUM -> PRWNUM
	rts
.use_pxwnum:
	move.w	#$1b1,(a0)                      ; PXINUM -> PXWNUM
	rts
.use_p0rwnum:
	move.w	#$264,(a0)                      ; P0RINUM -> P0RWNUM
	rts
.use_p0xwnum:
	move.w	#$265,(a0)                      ; P0XINUM -> P0XWNUM
	rts
.use_fwtof:
	move.w	#$233,(a0)                      ; $8006 -> FWTOF
	rts
.a0_from_var_store:
	move.w	4(a0),d0                        ; the IR after the a0 load
.check_store_through_a0:
	cmpi.w	#$8096,d0                       ; $8096 = byte store
	beq.s	.no_ext_needed
	cmpi.w	#$8097,d0                       ; $8097 = word store
	bne.s	.emit_ext_long
	rts
.a0_from_constant_store:
	move.w	6(a0),d0                        ; the IR after $800f and its long constant
	bra.s	.check_store_through_a0
.a0_from_pop_store:
	move.w	2(a0),d0                        ; the IR after the pop
	bra.s	.check_store_through_a0
.try_word_operator:
	move.w	4(a0),d0                        ; the operator after the operand
	move.w	#$814c,d2                       ; add -> $814c
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.check_after_operator
	move.w	#$814d,d2                       ; sub -> $814d
	cmpi.w	#$8064,d0                       ; $8064 sub
	beq.s	.check_after_operator
	move.w	#$814e,d2                       ; $805e -> $814e
	cmpi.w	#$805e,d0                       ; $805e multiply
	beq.s	.check_after_operator
	move.w	d0,d2                           ; and / or / eor keep their code
	cmpi.w	#$8060,d0                       ; $8060 and
	beq.s	.check_after_operator
	cmpi.w	#$8061,d0                       ; $8061 or
	beq.s	.check_after_operator
	cmpi.w	#$8062,d0                       ; $8062 eor
	beq.s	.check_after_operator
	bra.w	.extend_unless_word_used        ; other operator: the usual look-ahead
.skip_neg_or_not:
	addq.l	#2,a2                           ; step over a NEG or NOT
.check_after_operator:
	move.w	6(a2),d1                        ; d1 = the IR after the operator
	bpl.s	.routine_after_operator         ; a library routine
	cmpi.w	#$8078,d1                       ; $8078 = NEG
	beq.s	.skip_neg_or_not
	cmpi.w	#$8032,d1                       ; $8032 = NOT
	beq.s	.skip_neg_or_not
	cmpi.w	#$8043,d1                       ; $8043 word store
	beq.s	.use_word_operator
	cmpi.w	#$8044,d1                       ; $8044 byte store
	beq.s	.use_word_operator
	cmpi.w	#$8027,d1                       ; $8027 push word
	beq.s	.use_word_operator
	cmpi.w	#$1ae,d1                        ; FORW1
	beq.s	.use_word_operator
	cmpi.w	#$1af,d1                        ; FORW2
	beq.s	.use_word_operator
	bra.w	.emit_ext_long                  ; anything else needs the long
.look_ahead_from_a0:
	movea.l	a0,a2                           ; back to the usual look-ahead
	bra.w	.extend_unless_word_used
.routine_after_operator:
	bsr.s	test_routine_takes_word         ; tests d0 (the operator, negative), not d1: always EQ
	beq.s	.look_ahead_from_a0             ; EQ: not a word routine
.use_word_operator:
	move.w	d2,4(a0)                        ; use the word form of the operator
	rts
	dc.w	$610a,$6700,$ff34,$4e75         ; unreferenced: bsr.s test_routine_takes_word / beq.w .l0b13a / rts

return_zero_flag:
	moveq	#0,d0                           ; Z: not a word routine
	rts

;------------------------------------------------------------------------------
; Entry d0 = IR word.  Returns NE when d0 is a library routine number whose bit 0 in routine_flag_table is
; set (the routine takes its argument as a word, so no ext.l is needed), EQ for IR codes ($8xxx) and other
; routines.
;------------------------------------------------------------------------------
test_routine_takes_word:
	tst.w	d0                              ; an IR code: no
	bmi.s	return_zero_flag
	btst	#$0,routine_flag_table(pc,d0.w) ; bit 0: routine takes a word
	rts

; One byte per library routine number (routine 0 first).  Bit n set: the routine uses only the low word of
; register dn, so no ext.l is needed for it (low_word_only tests bit d2, test_routine_takes_word bit 0).
routine_flag_table:
	dc.w	$00ff,$ffff,$ff00,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$ff00,$00ff,$ffff,$ffff,$ffff,$ff00
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$2f03,$ff00,$ffff,$0000,$00ff,$ffff,$ffff
	dc.w	$ff01,$0100,$01ff,$01ff,$ff00,$0000,$0100,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$00ff,$0000
	dc.w	$0000,$00ff,$ffff,$ffff,$ffff,$ffff,$ffff,$0202
	dc.w	$ffff,$ffff,$ffff,$ffff,$0101,$0000,$ff05,$0505
	dc.w	$0505,$0504,$0505,$0505,$0101,$0101,$0101,$0101
	dc.w	$0101,$0101,$0001,$0100,$0001,$0100,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0101,$0000,$0000
	dc.w	$0000,$0000,$0000,$0001,$0100,$0000,$0000,$0001
	dc.w	$0101,$0300,$0001,$0101,$0100,$0000,$0000,$0000
	dc.w	$0103,$0000,$0000,$0000,$0000,$0000,$0000,$0001
	dc.w	$0301,$0001,$0001,$0000,$0000,$0001,$0001,$0300
	dc.w	$0101,$0100,$0000,$0000,$0101,$0100,$0000,$0100
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0001,$0101
	dc.w	$0101,$0101,$0101,$0101,$0101,$0100,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0606,$0005,$0100
	dc.w	$0007,$ff00,$0000,$0301,$0505,$0504,$02fb,$fbfb
	dc.w	$fbfb,$fbfb,$fbfb,$ffff,$0100,$ffff,$ffff,$fffb
	dc.w	$fb00,$0200,$0000,$01ff,$ff01,$01ff,$ffff,$01ff
	dc.w	$0000,$0306,$0100,$ffff,$ff00,$00ff,$ff00,$0101
	dc.w	$fbfb,$ffff,$0001,$0101,$0000,$0000,$0101,$0000
	dc.w	$0100,$ff00,$0000,$0000,$0100,$0000,$0101,$df00
	dc.w	$0000,$0100,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0001,$0100,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0001,$ffff,$0101,$0101
	dc.w	$0101,$01ff,$ffff,$0001,$0101,$0001,$0000,$ff00
	dc.w	$ffff,$0000,$00df,$0101,$0101,$0101,$0101,$0000
	dc.w	$0101,$0101,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$00ff,$ff02,$02ff,$ffff,$ffff
	dc.w	$ffff,$ffff,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0303
	dc.w	$0203,$0302,$0101,$0101,$ffff,$ffff,$ffff,$ffff
	dc.w	$ffff,$00ff,$0000,$ffff,$0000,$00ff,$0404,$0404
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0101,$0101,$0000,$0000
	dc.w	$0101,$0100,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$ffff,$ffff,$ff00,$0000,$0000
	dc.w	$0000

;------------------------------------------------------------------------------
; Drops a trailing ext.l d0 and then a trailing ext.w d0 from the code just written (see the two entries
; below).
;------------------------------------------------------------------------------
drop_trailing_extends:
	bsr.s	drop_trailing_ext_long

;------------------------------------------------------------------------------
; If the last word written at a1 is ext.w d0 ($4880) and is the one recorded in ext_w_d0_code_address, removes
; it (a1 moves back two bytes) and clears the record.  Otherwise a1 is unchanged.
;------------------------------------------------------------------------------
drop_trailing_ext_word:
	cmpi.w	#$4880,-(a1)                    ; $4880 = ext.w d0
	bne.s	.keep_ext_word
	cmpa.l	ext_w_d0_code_address(pc),a1    ; the one recorded?
	beq.s	.drop_ext_word
.keep_ext_word:
	addq.l	#2,a1                           ; no: keep it
	rts
.drop_ext_word:
	clr.l	ext_w_d0_code_address           ; yes: a1 stays on it, so it is overwritten
	rts

;------------------------------------------------------------------------------
; If the last word written at a1 is ext.l d0 ($48c0) and is the one recorded in ext_l_d0_code_address, removes
; it (a1 moves back two bytes) and clears the record.  Otherwise a1 is unchanged.  Used before byte or word
; operations, which do not need the long value.
;------------------------------------------------------------------------------
drop_trailing_ext_long:
	cmpi.w	#$48c0,-(a1)                    ; $48c0 = ext.l d0
	bne.s	.keep_ext_long
	cmpa.l	ext_l_d0_code_address(pc),a1    ; the one recorded?
	beq.s	.drop_ext_long
.keep_ext_long:
	addq.l	#2,a1                           ; no: keep it
	rts
.drop_ext_long:
	clr.l	ext_l_d0_code_address           ; yes: a1 stays on it, so it is overwritten
	rts

;------------------------------------------------------------------------------
; IR $8030: make d0 an unsigned word with andi.l #$ffff,d0 (after dropping a trailing ext.l).  Left out
; when the value is only stored as a byte ($8096) or word ($8097) through a0 (as at gen_zero_extend_byte).
;------------------------------------------------------------------------------
gen_zero_extend_word:
	bsr.s	drop_trailing_ext_long
	cmpi.w	#$808b,(a0)                     ; $808b integer variable into a0
	beq.s	.a0_from_variable_word
	cmpi.w	#$8094,(a0)                     ; $8094 word variable into a0
	beq.s	.a0_from_variable_word
	cmpi.w	#$800f,(a0)                     ; $800f constant into a0
	beq.s	.a0_from_constant_word
	cmpi.w	#$8022,(a0)                     ; $8022 pop into a0
	beq.s	.a0_from_pop_word
.emit_andi_long_ffff:
	move.w	#$280,(a1)+                     ; $0280 = andi.l #imm,d0
	move.l	#$ffff,(a1)+                    ; the immediate
	rts
.a0_from_variable_word:
	move.w	4(a0),d0                        ; the IR after the a0 load
.check_store_size_word:
	cmpi.w	#$8096,d0                       ; $8096 = byte store
	beq.s	.word_extend_done
	cmpi.w	#$8097,d0                       ; $8097 = word store
	bne.s	.emit_andi_long_ffff
.word_extend_done:
	rts
.a0_from_constant_word:
	move.w	6(a0),d0                        ; the IR after $800f and its long constant
	bra.s	.check_store_size_word
.a0_from_pop_word:
	move.w	2(a0),d0                        ; the IR after the pop
	bra.s	.check_store_size_word

gen_swap_d0:
	move.w	#$4840,(a1)+                    ; $4840 = swap d0
	rts

gen_not_d0:
	move.w	#$4680,(a1)+                    ; $4680 = not.l d0
	rts

;------------------------------------------------------------------------------
; IR $8033: writes subq.l #1,d0 at a1 without advancing a1, so no code results (the word is overwritten by
; the next instruction).
;------------------------------------------------------------------------------
gen_decrement_dropped:
	move.w	#$5380,(a1)                     ; $5380 = subq.l #1,d0, but a1 is not advanced
	rts

gen_increment_d0:
	move.w	#$5280,(a1)+                    ; $5280 = addq.l #1,d0
	rts

gen_exchange_d0_d1:
	move.w	#$c340,(a1)+                    ; $c340 = exg d1,d0
	rts

;------------------------------------------------------------------------------
; IR $8039 $803a $8047 $8048: no code.
;------------------------------------------------------------------------------
gen_nothing:
	rts

; Bit table indexed by library routine number, most significant bit of each byte first: a set bit means
; the routine leaves the condition codes set from its result in d0, so no tst.l d0 is needed after it.
flags_set_bit_table:
	dc.w	$000f,$b180,$0000,$0000,$0100,$0007,$fff8,$fffc
	dc.w	$0000,$00ff,$f00f,$0000,$0000,$00fc,$0003,$0000
	dc.w	$0800,$0000,$0003,$fffe,$fdfb,$f7ef,$dfff,$ffff
	dc.w	$ffff,$ffff,$ffe7,$3f30,$4000,$0007,$4e00,$0004
	dc.w	$0000,$0000,$0000,$0600,$0000,$0000,$0000,$0000
	dc.w	$000c,$007e,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$00ff,$e000,$0000,$0000,$0000,$0000

;------------------------------------------------------------------------------
; Makes the condition codes reflect d0 before a conditional branch or SGN.  Nothing is emitted when the
; last code was a library call ($6101 + last_library_routine) or the previous IR was a routine with its bit
; set in flags_set_bit_table, or when the previous IR code already sets the flags (constant load $8007, $803c
; $803d $803f $8040 $80c1 $80c3 $80c4, add/sub/and/or/eor, NOT, $80a3-$80b1).  After $80c2 only a trailing
; ext.l is dropped.  A trailing recorded ext.l d0 is kept (it sets the flags), or removed when an ext.w d0
; precedes it.  Otherwise emits tst.l d0.
;------------------------------------------------------------------------------
emit_test_d0:
	move.w	last_library_routine(pc),d0     ; routine number of the last library call
	cmp.w	-$2(a1),d0                      ; is the last word that routine number?
	beq.s	.check_call_marker
.check_previous_ir:
	move.w	previous_ir_code(pc),d0         ; d0 = previous IR code
	bmi.s	.check_ir_codes                 ; an IR code, not a routine
	bra.s	.test_flag_bit
.check_call_marker:
	cmpi.w	#$6101,-$4(a1)                  ; $6101 = library call marker before the routine number
	bne.s	.check_previous_ir
.test_flag_bit:
	lea	flags_set_bit_table(pc),a2      ; bit number, most significant first
	moveq	#7,d1                           ; bit number for btst
	eor.w	d0,d1                           ; bit 7 - (n & 7): most significant bit first
	lsr.w	#3,d0                           ; byte index
	btst	d1,0(a2,d0.w)                   ; the routine's bit set?
	beq.s	.check_trailing_ext             ; routine does not set the flags
	rts                                     ; yes: flags set already
.check_ir_codes:
	cmpi.w	#$8007,d0                       ; IR codes after which the flags are already set from d0
	beq.s	.flags_ready
	cmpi.w	#$803f,d0                       ; $803f integer variable
	beq.s	.flags_ready
	cmpi.w	#$8040,d0                       ; $8040 word variable
	beq.s	.flags_ready
	cmpi.w	#$803d,d0                       ; $803d byte variable
	beq.s	.flags_ready
	cmpi.w	#$803c,d0                       ; $803c boolean variable
	beq.s	.flags_ready
	cmpi.w	#$80c1,d0                       ; $80c1
	beq.s	.flags_ready
	cmpi.w	#$80c2,d0                       ; $80c2: only drop a trailing ext.l
	beq.s	.drop_ext_only
	cmpi.w	#$80c3,d0
	beq.s	.flags_ready
	cmpi.w	#$80c4,d0
	beq.s	.flags_ready
	cmpi.w	#$8063,d0                       ; add, sub, or, and, eor: flags set
	beq.s	.flags_ready
	cmpi.w	#$8064,d0
	beq.s	.flags_ready
	cmpi.w	#$8061,d0
	beq.s	.flags_ready
	cmpi.w	#$8060,d0
	beq.s	.flags_ready
	cmpi.w	#$8062,d0
	beq.s	.flags_ready
	cmpi.w	#$8032,d0                       ; $8032 NOT
	beq.s	.flags_ready
	cmpi.w	#$80a3,d0                       ; $80a3-$80b1
	bcs.s	.check_trailing_ext
	cmpi.w	#$80b2,d0                       ; $80a3-$80b1: flags set
	bcs.s	.flags_ready
.check_trailing_ext:
	cmpi.w	#$48c0,-(a1)                    ; $48c0 = ext.l d0
	bne.s	.emit_tst_long
	cmpa.l	ext_l_d0_code_address(pc),a1    ; the recorded one?
	bne.s	.emit_tst_long                  ; no: tst.l
	cmpi.w	#$4880,-(a1)                    ; $4880 = ext.w d0 before it: the ext.l is removed
	beq.s	.ext_handled
	addq.l	#2,a1                           ; keep the ext.l
.ext_handled:
	addq.l	#2,a1                           ; a1 after the ext.l (or on it, removing it)
.flags_ready:
	rts
.emit_tst_long:
	addq.l	#2,a1                           ; nothing to rely on
	move.w	#$4a80,(a1)+                    ; $4a80 = tst.l d0
	rts
.drop_ext_only:
	bra.w	drop_trailing_ext_long

;------------------------------------------------------------------------------
; As emit_test_d0, but $80c2 also needs no test and a trailing recorded ext.l d0 is always kept (it sets the
; flags).  Used only by gen_ir_81fc_integer_abs (IR $81fc).
;------------------------------------------------------------------------------
emit_test_d0_keep_extend:
	move.w	last_library_routine(pc),d0     ; routine number of the last library call
	cmp.w	-$2(a1),d0                      ; is the last word that routine number?
	beq.s	.abs_check_call_marker
.abs_check_previous_ir:
	move.w	previous_ir_code(pc),d0         ; d0 = previous IR code
	bmi.s	.abs_check_ir_codes             ; an IR code, not a routine
	bra.s	.abs_test_flag_bit
.abs_check_call_marker:
	cmpi.w	#$6101,-$4(a1)                  ; $6101 = library call marker before the routine number
	bne.s	.abs_check_previous_ir
.abs_test_flag_bit:
	lea	flags_set_bit_table(pc),a2      ; bit table, most significant bit first
	moveq	#7,d1                           ; bit number for btst
	eor.w	d0,d1                           ; bit 7 - (n & 7)
	lsr.w	#3,d0                           ; byte index
	btst	d1,0(a2,d0.w)                   ; the routine's bit set?
	beq.s	.abs_check_trailing_ext         ; no: look at the trailing ext.l
	rts                                     ; yes: flags set already
.abs_check_ir_codes:
	cmpi.w	#$8007,d0                       ; IR codes after which the flags are already set from d0
	beq.s	.abs_flags_ready
	cmpi.w	#$803f,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$8040,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$803d,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$803c,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$80c1,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$80c2,d0                       ; $80c2: no test either
	beq.s	.abs_flags_ready
	cmpi.w	#$80c3,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$80c4,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$8063,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$8064,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$8061,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$8060,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$8062,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$8032,d0
	beq.s	.abs_flags_ready
	cmpi.w	#$80a3,d0                       ; $80a3-$80b1
	bcs.s	.abs_check_trailing_ext
	cmpi.w	#$80b2,d0
	bcs.s	.abs_flags_ready
.abs_check_trailing_ext:
	cmpi.w	#$48c0,-(a1)                    ; $48c0 = ext.l d0
	bne.s	.abs_emit_tst_long
	cmpa.l	ext_l_d0_code_address(pc),a1    ; the recorded one?
	bne.s	.abs_emit_tst_long
	addq.l	#2,a1                           ; keep the ext.l
.abs_flags_ready:
	rts
.abs_emit_tst_long:
	addq.l	#2,a1                           ; nothing to rely on
	move.w	#$4a80,(a1)+                    ; $4a80 = tst.l d0
	rts

;------------------------------------------------------------------------------
; IR $8007 constant followed by $80bf (jump if false): a zero constant always jumps (gen_jump); a nonzero
; one never does.
;------------------------------------------------------------------------------
gen_constant_jump_if_false:
	tst.l	d0                              ; constant zero: always jumps
	beq.s	gen_jump

;------------------------------------------------------------------------------
; For a jump that is never taken: records the code position (a1 - statement_code_buffer + code_write_pointer
; - code_buffer_start) in the list at a6, emits nop and skips the label operand (4 bytes of IR).
;------------------------------------------------------------------------------
emit_nop_for_dropped_jump:
	move.l	a1,d1                           ; offset of this place in the code
	subi.l	#statement_code_buffer,d1       ; minus the buffer start
	add.l	code_write_pointer(pc),d1       ; plus the output position
	sub.l	code_buffer_start(pc),d1        ; minus the output start
	move.l	d1,(a6)+                        ; into the list at a6
	move.w	#$4e71,(a1)+                    ; $4e71 = nop
	addq.l	#4,a0                           ; skip the label operand
	rts

;------------------------------------------------------------------------------
; IR $8007 constant followed by $80c0 (jump if true): a nonzero constant always jumps (gen_jump), zero
; never does.
;------------------------------------------------------------------------------
gen_constant_jump_if_true:
	tst.l	d0                              ; constant zero: never jumps
	beq.s	emit_nop_for_dropped_jump
	bra.s	gen_jump

;------------------------------------------------------------------------------
; IR $8208 (the overflow check NEXT adds under N+): d7 = $69 (bvs) and a jump to the placeholder target
; $0f0f0f0f (emit_placeholder_jump), patched later as the loop exit.
;------------------------------------------------------------------------------
gen_ir_8208_overflow_branch:
	moveq	#105,d7                         ; $69 = bvs
	bra.s	emit_placeholder_jump

;------------------------------------------------------------------------------
; IR $8207 (the carry check of the byte NEXT under N+): as gen_ir_8208_overflow_branch with d7 = $65 (bcs).
;------------------------------------------------------------------------------
gen_ir_8207_carry_branch:
	moveq	#101,d7                         ; $65 = bcs

;------------------------------------------------------------------------------
; Branch with opcode byte d7 to the placeholder target $0f0f0f0f through emit_jump_to_target.  The target does
; not fit a word displacement, so it becomes the inverted Bcc / jmp (xxx).l form, patched later as a loop exit.
; Reached from emit_bvs_placeholder_jump and emit_bcs_placeholder_jump.
;------------------------------------------------------------------------------
emit_placeholder_jump:
	move.l	#$f0f0f0f,d0                    ; dummy target $0f0f0f0f: always the long jmp form
	bra.s	emit_jump_to_target

;------------------------------------------------------------------------------
; IR $80bd: jump if the float in d0-d2 is false (tst.w d2 / beq).
;------------------------------------------------------------------------------
gen_float_jump_if_false:
	move.w	#$4a42,(a1)+                    ; $4a42 = tst.w d2
	moveq	#103,d7                         ; $67 = beq
	bra.s	emit_conditional_jump

;------------------------------------------------------------------------------
; IR $80be: jump if the float in d0-d2 is true (tst.w d2 / bne).
;------------------------------------------------------------------------------
gen_float_jump_if_true:
	move.w	#$4a42,(a1)+                    ; $4a42 = tst.w d2
	moveq	#102,d7                         ; $66 = bne
	bra.s	emit_conditional_jump

;------------------------------------------------------------------------------
; IR $80bf: jump if d0 is false (tst.l d0 if needed / beq).
;------------------------------------------------------------------------------
gen_jump_if_false:
	bsr.w	emit_test_d0
	moveq	#103,d7                         ; $67 = beq
	bra.s	emit_conditional_jump

;------------------------------------------------------------------------------
; IR $80c0: jump if d0 is true (tst.l d0 if needed / bne).
;------------------------------------------------------------------------------
gen_jump_if_true:
	bsr.w	emit_test_d0
	moveq	#102,d7                         ; $66 = bne
	bra.s	emit_conditional_jump

;------------------------------------------------------------------------------
; IR $8049: unconditional jump (bra).
;------------------------------------------------------------------------------
gen_jump:
	moveq	#96,d7                          ; $60 = bra

;------------------------------------------------------------------------------
; Reads the jump target (a code offset, long) from the IR and emits the branch at emit_jump_to_target.
; d7 = Bcc opcode byte ($60 bra, $66 bne, $67 beq, or a condition from an Scc).
;------------------------------------------------------------------------------
emit_conditional_jump:
	move.l	(a0)+,d0                        ; d0 = target offset

;------------------------------------------------------------------------------
; Emits a branch from the current code position to offset d0 with opcode byte d7.  The position (a1 -
; statement_code_buffer + code_write_pointer - code_buffer_start) is recorded in the list at a6.  Displacement
; in a byte: Bcc.s; in a word: Bcc.w; otherwise jmp (xxx).l, preceded for a conditional branch by the inverted
; Bcc with displacement byte $ff (a placeholder; not worked out here).
;------------------------------------------------------------------------------
emit_jump_to_target:
	move.l	a1,d1                           ; d1 = offset of this branch in the code
	subi.l	#statement_code_buffer,d1       ; minus the buffer start
	add.l	code_write_pointer(pc),d1       ; plus the output position
	sub.l	code_buffer_start(pc),d1        ; minus the output start
	move.l	d1,(a6)+                        ; record it in the list at a6
	move.l	d0,d2                           ; d2 = target - position
	sub.l	d1,d2                           ; minus the position
	subq.l	#2,d2                           ; displacement from the opcode word + 2
	move.l	d2,d3
	ext.l	d3                              ; sign-extended word
	cmp.l	d2,d3                           ; fits a word?
	beq.s	.short_or_word_branch           ; fits a word?
	cmpi.b	#$60,d7                         ; bra: just jmp
	beq.s	.emit_jmp_long
	eori.b	#$1,d7                          ; inverted condition
	move.b	d7,(a1)+                        ; Bcc.s with the inverted condition
	st	(a1)+                           ; displacement byte $ff
.emit_jmp_long:
	move.w	#$4ef9,(a1)+                    ; $4ef9 = jmp (xxx).l
	move.l	d0,(a1)+                        ; the target
	rts
.short_or_word_branch:
	ext.w	d3                              ; sign-extended byte
	cmp.w	d2,d3                           ; fits a byte?
	beq.s	.emit_short_branch              ; fits a byte: Bcc.s
	move.b	d7,(a1)+                        ; opcode byte
	clr.b	(a1)+                           ; Bcc.w
	move.w	d2,(a1)+                        ; word displacement
	rts
.emit_short_branch:
	move.b	d7,(a1)+                        ; opcode byte
	move.b	d2,(a1)+                        ; byte displacement
	rts

;------------------------------------------------------------------------------
; Emits movea.l d0(a5),a2: the variable at offset d0 holds a pointer, so the code goes through (a2).
;------------------------------------------------------------------------------
emit_load_var_pointer_a2:
	move.w	#$246d,(a1)+                    ; $246d = movea.l d16(a5),a2
	move.w	d0,(a1)+                        ; the offset
	rts

;------------------------------------------------------------------------------
; IR $81ca var: integer variable = 0.  d0 = 0, then gen_constant_store_integer_var (clr.l var(a5) or, for a
; pointer variable, movea.l var(a5),a2 / clr.l (a2)).
;------------------------------------------------------------------------------
gen_ir_81ca_clear_integer_var:
	moveq	#0,d0                           ; IR $81ca entry: constant 0 for the integer store that follows

;------------------------------------------------------------------------------
; IR $8007 constant followed by $8042 (store into integer variable); d0 = the constant.  Emits clr.l var
; for 0, moveq #n,d0 / move.l d0,var for a byte value (leaving it in d0 too), move.l #n,var otherwise.  A
; variable flagged negative in its table entry is reached through movea.l ptr(a5),a2 and (a2).
;------------------------------------------------------------------------------
gen_constant_store_integer_var:
	move.l	d0,d6                           ; d6 = the constant
	beq.s	.clear_integer_var              ; 0: clr.l
	ext.w	d0
	ext.l	d0                              ; sign-extended byte
	cmp.l	d0,d6                           ; fits a byte?
	beq.s	.store_via_moveq                ; fits a byte: moveq
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bmi.s	.store_long_imm_through_a2      ; pointer variable
	move.w	#$2b7c,(a1)+                    ; $2b7c = move.l #imm,d16(a5)
	move.l	d6,(a1)+                        ; the long immediate
	move.w	d0,(a1)+                        ; the offset
	rts
.store_long_imm_through_a2:
	bsr.s	emit_load_var_pointer_a2
	move.w	#$24bc,(a1)+                    ; $24bc = move.l #imm,(a2)
	move.l	d6,(a1)+                        ; the long immediate
	rts
.store_via_moveq:
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d6,(a1)+                        ; the data byte
	bra.w	gen_store_integer_var           ; then move.l d0,var: d0 keeps the value too
.clear_integer_var:
	move.w	#$42ad,d1                       ; $42ad = clr.l d16(a5)
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bra.w	emit_op_on_variable             ; clr.l var or movea.l / clr.l (a2)

;------------------------------------------------------------------------------
; IR $81cc var: word variable = 0.  d0 = 0, then gen_constant_store_word_var (clr.w var(a5) or clr.w (a2)).
;------------------------------------------------------------------------------
gen_ir_81cc_clear_word_var:
	moveq	#0,d0                           ; IR $81cc entry: constant 0 for the word store that follows

;------------------------------------------------------------------------------
; IR $8007 constant followed by $8043 (store into word variable): clr.w var or move.w #n,var (through a2
; for a pointer variable).
;------------------------------------------------------------------------------
gen_constant_store_word_var:
	move.l	d0,d6                           ; d6 = the constant
	bsr.w	lookup_word_var                 ; d0 = offset, N: pointer variable
	bmi.s	.word_store_through_a2
	tst.w	d6                              ; 0: clr.w
	beq.s	.clear_word_var
	move.w	#$3b7c,(a1)+                    ; $3b7c = move.w #imm,d16(a5)
	move.w	d6,(a1)+                        ; the immediate
	move.w	d0,(a1)+                        ; the offset
	rts
.clear_word_var:
	move.w	#$426d,(a1)+                    ; $426d = clr.w d16(a5)
	move.w	d0,(a1)+                        ; the offset
	rts
.word_store_through_a2:
	bsr.s	emit_load_var_pointer_a2
	tst.w	d6                              ; 0: clr.w (a2)
	beq.s	.clear_word_through_a2
	move.w	#$34bc,(a1)+                    ; $34bc = move.w #imm,(a2)
	move.w	d6,(a1)+                        ; the immediate
	rts
.clear_word_through_a2:
	move.w	#$4252,(a1)+                    ; $4252 = clr.w (a2)
	rts

;------------------------------------------------------------------------------
; IR $81cd var: byte variable = 0.  d0 = 0, then gen_constant_store_byte_var (sf var(a5) or sf (a2)).
;------------------------------------------------------------------------------
gen_ir_81cd_clear_byte_var:
	moveq	#0,d0                           ; IR $81cd entry: constant 0 for the byte store that follows

;------------------------------------------------------------------------------
; IR $8007 constant followed by $8044 (store into byte variable): sf var for 0, st var for $ff, move.b
; #n,var otherwise (through a2 for a pointer variable).
;------------------------------------------------------------------------------
gen_constant_store_byte_var:
	move.l	d0,d6                           ; d6 = the constant
	bsr.w	lookup_byte_var                 ; d0 = offset, N: pointer variable
	bmi.s	.byte_store_through_a2
	tst.b	d6                              ; 0: sf var
	beq.s	emit_sf_var
	cmpi.w	#$ff,d6                         ; $ff: st var
	beq.s	emit_st_var
	move.w	#$1b7c,(a1)+                    ; $1b7c = move.b #imm,d16(a5)
	clr.b	(a1)+                           ; immediate word: $00, then the byte
	move.b	d6,(a1)+                        ; the byte
	move.w	d0,(a1)+                        ; the offset
	rts
.byte_store_through_a2:
	bsr.w	emit_load_var_pointer_a2
	tst.b	d6                              ; 0: sf (a2)
	beq.s	emit_sf_through_a2
	not.b	d6                              ; $ff: st (a2)
	beq.s	emit_st_through_a2
	not.b	d6                              ; restore the byte
	move.w	#$14bc,(a1)+                    ; $14bc = move.b #imm,(a2)
	move.w	d6,(a1)+                        ; immediate (low byte used)
	rts

emit_sf_through_a2:
	move.w	#$51d2,(a1)+                    ; $51d2 = sf (a2)
	rts

emit_st_through_a2:
	move.w	#$50d2,(a1)+                    ; $50d2 = st (a2)
	rts

emit_bool_constant_through_a2:
	bsr.w	emit_load_var_pointer_a2
	tst.l	d6                              ; FALSE: sf (a2), TRUE: st (a2)
	beq.s	emit_sf_through_a2
	bra.s	emit_st_through_a2

;------------------------------------------------------------------------------
; IR $81cb var: boolean variable = FALSE.  d0 = 0, then gen_constant_store_bool_var (sf var(a5) or sf (a2)).
;------------------------------------------------------------------------------
gen_ir_81cb_clear_bool_var:
	moveq	#0,d0                           ; IR $81cb entry: constant 0 for the boolean store that follows

;------------------------------------------------------------------------------
; IR $8007 constant followed by $8045 (store into boolean variable): st var for nonzero, sf var for 0
; (through a2 for a pointer variable).
;------------------------------------------------------------------------------
gen_constant_store_bool_var:
	move.l	d0,d6                           ; d6 = the constant
	bsr.w	lookup_bool_var                 ; d0 = offset, N: pointer variable
	bmi.s	emit_bool_constant_through_a2
	tst.l	d6                              ; 0: sf var, else st var
	beq.s	emit_sf_var

emit_st_var:
	move.w	#$50ed,(a1)+                    ; $50ed = st d16(a5)
	move.w	d0,(a1)+                        ; the offset
	rts

emit_sf_var:
	move.w	#$51ed,(a1)+                    ; $51ed = sf d16(a5)
	move.w	d0,(a1)+                        ; the offset
	rts

;------------------------------------------------------------------------------
; IR $801b (pop d1) followed by IR $8100 (store d1 into integer variable): move.l (sp)+,var.
;------------------------------------------------------------------------------
gen_pop_store_integer_var:
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bmi.s	.pop_into_pointer_target
	move.w	#$2b5f,(a1)+                    ; $2b5f = move.l (sp)+,d16(a5)
