	rts

;------------------------------------------------------------------------------
; IR $8042: store d0 into an integer variable: move.l d0,var(a5) or move.l d0,(a2).
;------------------------------------------------------------------------------
gen_store_integer_var:
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bmi.s	.long_into_pointer_target
	move.w	#$2b40,(a1)+                    ; $2b40 = move.l d0,d16(a5)
	move.w	d0,(a1)+                        ; the offset
	rts
.long_into_pointer_target:
	bsr.w	emit_load_var_pointer_a2
	move.w	#$2480,(a1)+                    ; $2480 = move.l d0,(a2)
	rts

;------------------------------------------------------------------------------
; IR $8043: store d0 into a word variable: move.w d0,var(a5) or move.w d0,(a2).
