;------------------------------------------------------------------------------
gen_store_byte_var:
	bsr.w	lookup_byte_var                 ; d0 = offset, N: pointer variable
	bmi.s	.byte_into_pointer_target
	move.w	#$1b40,(a1)+                    ; $1b40 = move.b d0,d16(a5)
	move.w	d0,(a1)+                        ; the offset
