	move.w	#$1480,(a1)+                    ; $1480 = move.b d0,(a2)
	rts

;------------------------------------------------------------------------------
; IR $8045: store d0 into a boolean variable: tst.l d0 when needed, then sne var(a5) or sne (a2).
; The code after it, up to gen_store_bool_var_tested, is reached through the IR $8100-$811b part of the
; codegen table: stores of d1-d7 into integer, word and byte variables.
;------------------------------------------------------------------------------
gen_store_bool_var:
	bsr.w	emit_test_d0                    ; tst.l d0 unless the flags are set already
	bsr.w	lookup_bool_var                 ; d0 = offset, N: pointer variable
	bmi.s	.bool_into_pointer_target
	move.w	#$56ed,(a1)+                    ; $56ed = sne d16(a5)
