;------------------------------------------------------------------------------
; Store data register d4 into the integer variable next in the IR: move.l Dn,var(a5) ($2b40+n), or for a
; pointer variable movea.l var(a5),a2 / move.l Dn,(a2) ($2480+n).  Entry d4 = register number 1-7.
;------------------------------------------------------------------------------
emit_store_dn_integer_var:
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bmi.s	.store_long_through_pointer
	addi.w	#$2b40,d4                       ; $2b40 + n = move.l Dn,d16(a5)
