; movea.l var(a5),a2 / move.w Dn,(a2) ($3480+n) for a pointer variable.  Entry d4 = register number.
;------------------------------------------------------------------------------
emit_store_dn_word_var:
	bsr.w	lookup_word_var                 ; d0 = offset, N: pointer variable
	bmi.s	.store_word_through_pointer
	addi.w	#$3b40,d4                       ; $3b40 + n = move.w Dn,d16(a5)
	move.w	d4,(a1)+                        ; opcode
	move.w	d0,(a1)+                        ; the offset
