; movea.l var(a5),a2 / move.b Dn,(a2) ($1480+n) for a pointer variable.  Entry d4 = register number.
;------------------------------------------------------------------------------
emit_store_dn_byte_var:
	bsr.w	lookup_byte_var                 ; d0 = offset, N: pointer variable
	bmi.s	.store_byte_through_pointer
	addi.w	#$1b40,d4                       ; $1b40 + n = move.b Dn,d16(a5)
