; $8105 ... $8119 (d1-d7, four apart) follow, using tst.l Dn.
;------------------------------------------------------------------------------
gen_store_bool_var_tested:
	moveq	#0,d4                           ; d0
	bra.s	emit_store_dn_bool_var

;------------------------------------------------------------------------------
; IR $8101 var: store d1 into a boolean variable (tst.l d1 / sne var).  d4 = 1, then emit_store_dn_bool_var.
;------------------------------------------------------------------------------
gen_ir_8101_store_d1_bool_var:
