;------------------------------------------------------------------------------
gen_ir_8119_store_d7_bool_var:
	moveq	#7,d4                           ; d4 = register d7

;------------------------------------------------------------------------------
; Store data register d4 (0-7) into the boolean variable next in the IR: tst.l Dn ($4a80+n) / sne var(a5)
; ($56ed), or movea.l var(a5),a2 / tst.l Dn / sne (a2) ($56d2) for a pointer variable.
;------------------------------------------------------------------------------
emit_store_dn_bool_var:
	bsr.w	lookup_bool_var                 ; d0 = offset, N: pointer variable
	bmi.s	.store_bool_through_pointer
	addi.w	#$4a80,d4                       ; $4a80 + n = tst.l Dn
	move.w	d4,(a1)+                        ; tst.l Dn
	move.w	#$56ed,(a1)+                    ; $56ed = sne d16(a5)
	move.w	d0,(a1)+                        ; the offset
	rts
.store_bool_through_pointer:
	bsr.w	emit_load_var_pointer_a2
	addi.w	#$4a80,d4                       ; $4a80 + n = tst.l Dn
	move.w	d4,(a1)+                        ; tst.l Dn
	move.w	#$56d2,(a1)+                    ; $56d2 = sne (a2)
	rts

;------------------------------------------------------------------------------
; IR $81c8 var: float variable = 0.  d7 = 0 (exponent word of 0.0) and a0 stepped back so that the addq.l #2,a0
; of gen_constant_store_float_var (meant to skip a $8041) lands on the variable number.  Emits the variable's
; address and clr.w 6(a0), folded into clr.w var+6(a5).
;------------------------------------------------------------------------------
gen_ir_81c8_clear_float_var:
	moveq	#0,d7                           ; IR $81c8 entry: exponent 0 = 0.0
	subq.l	#2,a0                           ; cancels the skip of $8041 in gen_constant_store_float_var

;------------------------------------------------------------------------------
; IR $8000 float constant followed by $8041 (store float variable); d0/d6/d7 = the constant's mantissa
; long, mantissa word and exponent word.  Emits the variable's address into a0, then clr.w 6(a0) (folded into
; clr.w var+6(a5)) for zero, or move.w / clr.l / move.w or two move.l #imm,(a0)+.
;------------------------------------------------------------------------------
gen_constant_store_float_var:
	addq.l	#2,a0                           ; skip the $8041
	movem.l	d0/d6-d7,-(sp)                  ; keep the constant
	bsr.s	emit_float_var_address_a0       ; lea / movea.l var(a5),a0
	movem.l	(sp)+,d0/d6-d7                  ; constant back
	tst.w	d7                              ; d7 = exponent word: 0 means 0.0
	beq.s	.zero_float
	tst.w	d6                              ; third word and low word of the mantissa long zero?
	bne.s	.store_float_two_longs
	tst.w	d0
	bne.s	.store_float_two_longs
	move.w	#$30fc,(a1)+                    ; $30fc = move.w #imm,(a0)+
	swap	d0                              ; high word of the mantissa long
	move.w	d0,(a1)+                        ; high word of the mantissa
	move.w	#$4298,(a1)+                    ; $4298 = clr.l (a0)+: the two zero words
	move.w	#$30fc,(a1)+                    ; $30fc = move.w #imm,(a0)+
	move.w	d7,(a1)+                        ; the exponent word
	rts
.store_float_two_longs:
	move.w	#$20fc,(a1)+                    ; $20fc = move.l #imm,(a0)+
	move.l	d0,(a1)+                        ; mantissa long
	move.w	#$20fc,(a1)+                    ; $20fc = move.l #imm,(a0)+
	move.w	d6,(a1)+                        ; third word
	move.w	d7,(a1)+                        ; and the exponent word
	rts
.zero_float:
	cmpi.w	#$41ed,-$4(a1)                  ; $41ed = lea d16(a5),a0 just emitted?
	beq.s	.fold_into_clr_var
	move.l	#$42680006,(a1)+                ; clr.w 6(a0): the exponent word
	rts
.fold_into_clr_var:
	move.w	#$426d,-$4(a1)                  ; the lea becomes clr.w var+6(a5)
	addq.w	#6,-$2(a1)                      ; offset + 6: the exponent word
	rts

;------------------------------------------------------------------------------
; Looks up the float variable whose index is next in the IR and emits its address into a0: lea var(a5),a0
; or movea.l var(a5),a0 for a pointer variable.  Also IR $80ee.
;------------------------------------------------------------------------------
emit_float_var_address_a0:
	bsr.w	lookup_float_var
	bmi.s	emit_movea_var_pointer_a0       ; pointer variable

emit_lea_var_a0:
	move.w	#$41ed,(a1)+                    ; $41ed = lea d16(a5),a0
	move.w	d0,(a1)+                        ; the offset
	rts

;------------------------------------------------------------------------------
; IR $81ff var: address of a string variable's descriptor into a1 for a string compare.  Emits lea var(a5),a0 /
; movea.l var(a5),a0 through emit_string_var_address_a0 and turns the destination into a1.
;------------------------------------------------------------------------------
gen_ir_81ff_string_var_address_a1:
	bsr.s	emit_string_var_address_a0      ; IR $81ff entry: string variable address into a1
	addq.b	#2,-$4(a1)                      ; +2 in the high byte: destination register a0 -> a1 ($41ed -> $43ed,
                                                ;   $206d -> $226d)
	rts

;------------------------------------------------------------------------------
; IR $803b: string variable.  Emits its descriptor address into a0; then folds a following IR $8018 into
; pea var(a5) / move.l var(a5),-(sp), or a following LENSTR into move.w 4(a0),d0 / move.w var+4(a5),d0 (the
; length word of the descriptor) and sign-extends it.
;------------------------------------------------------------------------------
gen_load_string_var:
	bsr.s	emit_string_var_address_a0
	lea	-$4(a1),a2                      ; a2 = the lea / movea just emitted
	cmpi.w	#$8018,(a0)                     ; $8018 follows
	beq.s	.push_string_descriptor
	cmpi.w	#$ac,(a0)                       ; LENSTR follows
	beq.s	.load_string_length
	rts
.push_string_descriptor:
	addq.l	#2,a0                           ; consume the $8018
	cmpi.w	#$41ed,(a2)                     ; lea var(a5),a0: the descriptor is in the variable?
	beq.s	.push_descriptor_address
	move.w	#$2f2d,(a2)                     ; $2f2d = move.l d16(a5),-(sp)
	rts
.push_descriptor_address:
	move.w	#$486d,(a2)                     ; $486d = pea d16(a5)
	rts
.load_string_length:
	move.w	(a0)+,current_ir_code           ; consume LENSTR
	cmpi.w	#$41ed,(a2)                     ; lea var(a5),a0?
	beq.s	.fold_length_into_var_load
	move.l	#$30280004,(a1)+                ; move.w 4(a0),d0: the length word
	bra.w	gen_sign_extend_word
.fold_length_into_var_load:
	move.w	#$302d,(a2)+                    ; $302d = move.w d16(a5),d0, offset + 4
	addq.w	#4,(a2)                         ; offset + 4: the length word
	bra.w	gen_sign_extend_word

;------------------------------------------------------------------------------
; Looks up the string variable whose index is next in the IR and emits its address into a0.
;------------------------------------------------------------------------------
emit_string_var_address_a0:
	bsr.w	lookup_string_var

;------------------------------------------------------------------------------
; With the flags from a variable lookup: lea var(a5),a0 (pl) or movea.l var(a5),a0 (mi).
;------------------------------------------------------------------------------
emit_var_address_a0:
	bpl.s	emit_lea_var_a0

emit_movea_var_pointer_a0:
	move.w	#$206d,(a1)+                    ; $206d = movea.l d16(a5),a0
	move.w	d0,(a1)+                        ; the offset
	rts

;------------------------------------------------------------------------------
; Looks up an integer variable (IR operand) and emits its address into a0.
;------------------------------------------------------------------------------
emit_integer_var_address_a0:
	bsr.w	lookup_integer_var
	bra.s	emit_var_address_a0

;------------------------------------------------------------------------------
; Looks up a word variable (IR operand) and emits its address into a0.
;------------------------------------------------------------------------------
emit_word_var_address_a0:
	bsr.w	lookup_word_var
	bra.s	emit_var_address_a0

;------------------------------------------------------------------------------
; Looks up a byte variable (IR operand) and emits its address into a0.
;------------------------------------------------------------------------------
emit_byte_var_address_a0:
	bsr.w	lookup_byte_var
	bra.s	emit_var_address_a0

;------------------------------------------------------------------------------
; IR $8041: store the float in d0-d2 into a float variable: address into a0, then move.l d0,(a0)+ /
; move.w d1,(a0)+ / move.w d2,(a0)+.
;------------------------------------------------------------------------------
gen_store_float_var:
	bsr.s	emit_float_var_address_a0
	move.w	#$20c0,(a1)+                    ; $20c0 = move.l d0,(a0)+
	move.w	#$30c1,(a1)+                    ; $30c1 = move.w d1,(a0)+
	move.w	#$30c2,(a1)+                    ; $30c2 = move.w d2,(a0)+
	rts

;------------------------------------------------------------------------------
; IR $8006 (integer to float) followed by $8041: address of the float variable into a0 and a call of
; ISTOF.
;------------------------------------------------------------------------------
gen_store_integer_as_float_var:
	bsr.w	emit_float_var_address_a0
	move.w	#$1d7,d0                        ; ISTOF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8046: string assignment.  When the last code was a call of EMPSTR, CHRSTR, MKISTR, MKLSTR or CONSTR,
; that call is removed and EMPSTOS, CHRSTOS, MKISTOS, MKLSTOS or CONSTOS is called with the variable's address
; in a0.  Otherwise the variable's address goes into a1 and STOS is called.
;------------------------------------------------------------------------------
gen_store_string_var:
	move.w	last_library_routine(pc),d0     ; last library call
	cmp.w	-$2(a1),d0                      ; is the last word that routine number?
	bne.s	.plain_string_assign
	cmpi.w	#$6101,-$4(a1)                  ; $6101 = library call marker
	bne.s	.plain_string_assign
	cmpi.w	#$a4,d0                         ; EMPSTR
	beq.s	.use_empstos
	cmpi.w	#$a5,d0                         ; CHRSTR
	beq.s	.use_chrstos
	cmpi.w	#$a6,d0                         ; MKISTR
	beq.s	.use_mkistos
	cmpi.w	#$a7,d0                         ; MKLSTR
	beq.s	.use_mklstos
	cmpi.w	#$b1,d0                         ; CONSTR
	beq.s	.use_constos
.plain_string_assign:
	move.w	#$f0,d4                         ; STOS
	bsr.s	emit_string_var_address_a0
	addi.w	#$200,-$4(a1)                   ; lea/movea ... ,a0 becomes ... ,a1
	move.w	d4,d0                           ; STOS
	bra.w	emit_library_call
.use_empstos:
	subq.l	#4,a1                           ; remove the call
	move.w	#$f5,d4                         ; EMPSTOS
.emit_store_call:
	bsr.w	emit_string_var_address_a0      ; lea / movea.l var(a5),a0
	move.w	d4,d0                           ; the ...STOS routine
	bra.w	emit_library_call
.use_chrstos:
	subq.l	#4,a1                           ; remove the call
	move.w	#$f7,d4                         ; CHRSTOS
	bra.s	.emit_store_call
.use_mkistos:
	subq.l	#4,a1                           ; remove the call
	move.w	#$f8,d4                         ; MKISTOS
	bra.s	.emit_store_call
.use_mklstos:
	subq.l	#4,a1                           ; remove the call
	move.w	#$f9,d4                         ; MKLSTOS
	bra.s	.emit_store_call
.use_constos:
	subq.l	#4,a1                           ; remove the call
	move.w	#$f6,d4                         ; CONSTOS
	bra.s	.emit_store_call

;------------------------------------------------------------------------------
; IR $803f: load an integer variable into d0.  d0-d7 = the next eight IR words (d0 = the variable index).
; Folds what follows:
; - $8017 push: move.l var,-(sp); $8027 push word: move.w var+2,-(sp);
; - $8042 store: copy into the other variable;
; - $8078 NEG / $8032 NOT then $8042 into the same variable: neg.l / not.l var;
; - $8008 constant then add/sub/and/or/eor then $8042 into the same variable: addq/subq/addi/andi/ori/eori
;   or moveq + op.l d0,var, and nothing for and #-1 / or #0 / eor #0;
; - $8084 variable then op then $8042 (see gen_update_integer_var_by_var).
; Otherwise move.l var,d0.
;------------------------------------------------------------------------------
gen_load_integer_var:
	movem.w	(a0),d0-d7                      ; d0 = variable, d1.. = the IR words after it
	cmpi.w	#$8017,d1                       ; $8017 push
	beq.w	gen_push_integer_var
	cmpi.w	#$8027,d1                       ; $8027 push word
	beq.w	gen_push_integer_var_word
	cmpi.w	#$8084,d1                       ; $8084 load integer variable into d1
	beq.w	gen_update_integer_var_by_var
	cmpi.w	#$8042,d1                       ; $8042 store
	beq.w	gen_copy_integer_var
	cmpi.w	#$8078,d1                       ; $8078 NEG
	beq.w	gen_neg_integer_var_in_place
	cmpi.w	#$8032,d1                       ; $8032 NOT
	beq.w	gen_not_integer_var_in_place
	cmpi.w	#$8008,d1                       ; $8008 constant into d1, op, $8042 into the same variable
	bne.s	.not_a_fold
	cmpi.w	#$8042,d5                       ; $8042 after the operator?
	bne.s	.not_a_fold
	cmp.w	d6,d0                           ; into the same variable?
	bne.s	.not_a_fold
	move.l	4(a0),d1                        ; the constant
	move.l	d1,d2                           ; d2 = d3 = the constant
	move.l	d1,d3
	cmpi.w	#$8063,d4                       ; add
	beq.w	.add_constant
	cmpi.w	#$8064,d4                       ; sub
	beq.w	.sub_constant
	cmpi.w	#$8060,d4                       ; and
	beq.s	.and_constant
	cmpi.w	#$8061,d4                       ; or
	beq.s	.or_constant
	cmpi.w	#$8062,d4                       ; eor
	beq.w	.eor_constant
.not_a_fold:
	bra.w	emit_load_integer_var_d0
.and_constant:
	tst.l	d2                              ; and #0: clr.l
	beq.s	.and_zero
	addq.l	#1,d1                           ; and #-1: nothing
	beq.s	.skip_update_sequence
	move.w	#$c1ad,d1                       ; $c1ad = and.l d0,d16(a5)
	ext.w	d3
	ext.l	d3                              ; byte sign-extended
	cmp.l	d3,d2                           ; fits a byte?
	beq.w	emit_moveq_then_op_integer_var  ; yes: moveq #c,d0 / and.l d0,var
	move.w	#$2ad,d1                        ; $02ad = andi.l #imm,d16(a5)
	bra.w	.immediate_on_target
.and_zero:
	move.w	#$42ad,d1                       ; $42ad = clr.l d16(a5)
	bra.w	emit_op_on_target_integer_var   ; on the target variable
.skip_update_sequence:
	lea	$e(a0),a0                       ; skip the whole sequence
	rts
.or_constant:
	tst.l	d2                              ; or #0: nothing
	beq.s	.skip_update_sequence
	move.w	#$81ad,d1                       ; $81ad = or.l d0,d16(a5)
	ext.w	d3
	ext.l	d3                              ; byte sign-extended
	cmp.l	d3,d2                           ; fits a byte?
	beq.w	emit_moveq_then_op_integer_var  ; yes: moveq #c,d0 / or.l d0,var
	move.l	d2,d3                           ; low word zero?
	clr.w	d3                              ; d3 = high word only
	cmp.l	d2,d3                           ; low word zero?
	bne.s	.or_long_constant               ; no: ori.l / ori.w on the low word
	move.w	#$6d,d1                         ; $006d = ori.w #imm,d16(a5) on the high word
	lea	$c(a0),a0                       ; a0 on the target variable
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bmi.s	.or_high_word_through_a2
	move.w	d1,(a1)+                        ; ori.w #hi,var: the high word
	move.w	d2,(a1)+                        ; the high word
	move.w	d0,(a1)+                        ; the offset
	rts
.or_high_word_through_a2:
	bsr.w	emit_immediate_op_through_a2    ; ori.w #imm,(a2) followed by d2 as a long
	subq.l	#2,a1                           ; drop its low (zero) word: ori.w #hi,(a2)
	rts
.or_long_constant:
	move.w	#$ad,d1                         ; $00ad = ori.l #imm,d16(a5)
	lea	$c(a0),a0                       ; a0 on the target variable
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bmi.s	emit_immediate_op_through_a2    ; pointer variable: ori.l #c,(a2)
	moveq	#0,d3                           ; fits an unsigned word?
	move.w	d2,d3                           ; low word, zero-extended
	cmp.l	d2,d3                           ; fits an unsigned word?
	bne.s	.emit_ori_long_var              ; no: ori.l
	addq.w	#2,d0                           ; ori.w on the low word at offset + 2
	move.w	#$6d,(a1)+                      ; $006d = ori.w #imm,d16(a5)
	move.w	d2,(a1)+                        ; the low word
	move.w	d0,(a1)+                        ; offset of the low word
	rts
.emit_ori_long_var:
	move.w	d1,(a1)+                        ; $00ad = ori.l #imm,d16(a5)
	move.l	d2,(a1)+                        ; the immediate
	move.w	d0,(a1)+                        ; the offset
	rts
.eor_constant:
	tst.l	d2                              ; eor #0: nothing
	beq.s	.skip_update_sequence
	addq.l	#1,d1                           ; eor #-1
	beq.s	.eor_minus_one
	move.w	#$b1ad,d1                       ; $b1ad = eor.l d0,d16(a5)
	ext.w	d3
	ext.l	d3                              ; byte sign-extended
	cmp.l	d3,d2                           ; fits a byte?
	beq.s	emit_moveq_then_op_integer_var  ; yes: moveq #c,d0 / eor.l d0,var
	move.w	#$aad,d1                        ; $0aad = eori.l #imm,d16(a5)
	bra.s	.immediate_on_target
.eor_minus_one:
	move.w	#$46ad,d1                       ; $46ad = not.l d16(a5)
	bra.s	emit_op_on_target_integer_var
.sub_constant:
	neg.l	d1                              ; sub: negated constant
.add_constant:
	cmpi.l	#$8,d1                          ; 1..8: addq (0 would give addq #8)
	bls.s	emit_addq_integer_var
	cmpi.l	#$fffffff8,d1                   ; -8..-1: subq
	bcc.s	emit_subq_integer_var
	ext.w	d1
	ext.l	d1                              ; byte sign-extended
	cmp.l	d2,d1                           ; compares the byte of d1 with d2, the constant before the neg
	beq.s	emit_add_byte_constant_integer_var
	move.w	#$6ad,d1                        ; $06ad = addi.l #d2,d16(a5): for sub d2 is not negated (looks wrong)
.immediate_on_target:
	lea	$c(a0),a0                       ; skip to the target variable
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	bmi.s	emit_immediate_op_through_a2
	move.w	d1,(a1)+                        ; opcode
	move.l	d2,(a1)+                        ; the long immediate
	move.w	d0,(a1)+                        ; the offset
	rts

;------------------------------------------------------------------------------
; Emits movea.l ptr(a5),a2 and the immediate instruction d1 with (a2) as destination (d1 eor $3f turns the
; d16(a5) mode into (a2)), followed by the long immediate d2.
;------------------------------------------------------------------------------
emit_immediate_op_through_a2:
	bsr.w	emit_load_var_pointer_a2
	eori.w	#$3f,d1                         ; d16(a5) -> (a2)
	move.w	d1,(a1)+                        ; opcode
	move.l	d2,(a1)+                        ; the long immediate
	rts

emit_add_byte_constant_integer_var:
	move.w	#$d1ad,d1                       ; $d1ad = add.l d0,d16(a5)

emit_moveq_then_op_integer_var:
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d2,(a1)+                        ; the data byte
	bra.s	emit_op_on_target_integer_var   ; op.l d0,var

emit_subq_integer_var:
	neg.l	d1                              ; n = -c
	andi.w	#$7,d1                          ; 8 is written as 0
	ror.w	#7,d1                           ; count into bits 9-11
	ori.w	#$51ad,d1                       ; $51ad = subq.l #n,d16(a5)
	bra.s	emit_op_on_target_integer_var

emit_addq_integer_var:
	andi.w	#$7,d1                          ; 8 is written as 0
	ror.w	#7,d1                           ; count into bits 9-11
	ori.w	#$50ad,d1                       ; $50ad = addq.l #n,d16(a5)

;------------------------------------------------------------------------------
; Skips to the target variable (12 bytes on in the IR) and emits instruction d1 on it.
;------------------------------------------------------------------------------
emit_op_on_target_integer_var:
	lea	$c(a0),a0                       ; skip to the target variable
	bra.w	emit_op_integer_var

;------------------------------------------------------------------------------
; IR $803f v1 followed by $8042 v2: copy one integer variable into another (move.l v1(a5),v2(a5) or the
; forms through a0/a1 for pointer variables).  Nothing when v1 = v2.
;------------------------------------------------------------------------------
gen_copy_integer_var:
	bsr.w	lookup_integer_var
	movem.w	d0/d7,-(sp)                     ; source variable
	addq.l	#2,a0                           ; skip the $8042
	bsr.w	lookup_integer_var              ; target variable
	movem.w	(sp)+,d1/d6                     ; d1 / d6 = source offset / flags
	cmp.w	d0,d1                           ; same variable: nothing
	beq.s	.copy_done
	tst.w	d6                              ; source a pointer variable?
	bmi.s	.source_is_pointer
	tst.w	d7                              ; target a pointer variable?
	bmi.s	.target_is_pointer
	move.w	#$2b6d,(a1)+                    ; $2b6d = move.l d16(a5),d16(a5)
	move.w	d1,(a1)+                        ; source offset
	move.w	d0,(a1)+                        ; target offset
.copy_done:
	rts
.source_is_pointer:
	tst.w	d7                              ; target a pointer variable too?
	bmi.s	.both_pointers
	move.w	#$206d,(a1)+                    ; $206d = movea.l d16(a5),a0
	move.w	d1,(a1)+                        ; source offset
	move.w	#$2b50,(a1)+                    ; $2b50 = move.l (a0),d16(a5)
	move.w	d0,(a1)+                        ; target offset
	rts
.both_pointers:
	move.w	#$226d,(a1)+                    ; $226d = movea.l d16(a5),a1
	move.w	d0,(a1)+                        ; target offset
	move.w	#$206d,(a1)+                    ; movea.l source(a5),a0
	move.w	d1,(a1)+                        ; source offset
	move.w	#$2290,(a1)+                    ; $2290 = move.l (a0),(a1)
	rts
.target_is_pointer:
	move.w	#$206d,(a1)+                    ; movea.l target(a5),a0
	move.w	d0,(a1)+                        ; target offset
	move.w	#$20ad,(a1)+                    ; $20ad = move.l d16(a5),(a0)
	move.w	d1,(a1)+                        ; source offset
	rts

;------------------------------------------------------------------------------
; $803f followed by $8017: move.l var(a5),-(sp) or move.l (a2),-(sp).
;------------------------------------------------------------------------------
gen_push_integer_var:
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	addq.l	#2,a0                           ; skip the $8017 (flags kept)
	bmi.s	.push_through_a2
	move.w	#$2f2d,(a1)+                    ; $2f2d = move.l d16(a5),-(sp)
	move.w	d0,(a1)+                        ; the offset
	rts
.push_through_a2:
	bsr.w	emit_load_var_pointer_a2
	move.w	#$2f12,(a1)+                    ; $2f12 = move.l (a2),-(sp)
	rts

;------------------------------------------------------------------------------
; $803f followed by $8027: move.w var+2(a5),-(sp) or move.w 2(a2),-(sp) (low word of the long).
;------------------------------------------------------------------------------
gen_push_integer_var_word:
	bsr.w	lookup_integer_var              ; d0 = offset, N: pointer variable
	addq.l	#2,a0                           ; skip the $8027 (flags kept)
	bmi.s	.push_word_through_a2
	move.w	#$3f2d,(a1)+                    ; $3f2d = move.w d16(a5),-(sp), offset + 2
	addq.w	#2,d0                           ; +2: the low word
	move.w	d0,(a1)+                        ; the offset
	rts
.push_word_through_a2:
	bsr.w	emit_load_var_pointer_a2
	move.l	#$3f2a0002,(a1)+                ; move.w 2(a2),-(sp)
	rts

;------------------------------------------------------------------------------
; $803f v1 $8084 v2 op $8042 v: emits move.l v2,d0 / op.l d0,v1 when the target is one of the two (add,
; sub, and, or, eor; v op v gives 0 for sub/eor, nothing for and/or).  The IR positions it checks (d3 d4 d5
; d6) are those of the $8008 case with its two-word constant, while the code it emits consumes six words for
; this case; not worked out which is meant.
;------------------------------------------------------------------------------
gen_update_integer_var_by_var:
	cmpi.w	#$8042,d5                       ; the $8042 position of the $8008 case
	bne.w	emit_load_integer_var_d0
	cmp.w	d0,d6                           ; target = the word at d6?
	beq.s	.target_is_first
	cmp.w	d0,d3                           ; or the word at d3?
	beq.w	.target_is_second
	bra.w	emit_load_integer_var_d0
.target_is_first:
	cmp.w	d0,d3                           ; both: the same variable twice
	beq.w	.same_variable_twice
	cmpi.w	#$8063,d4                       ; $8063 add
	beq.s	.op_add
	cmpi.w	#$8064,d4                       ; $8064 sub
	beq.s	.op_sub
	cmpi.w	#$8060,d4                       ; $8060 and
	beq.s	.op_and
	cmpi.w	#$8061,d4                       ; $8061 or
	beq.s	.op_or
	cmpi.w	#$8062,d4                       ; $8062 eor
	beq.s	.op_eor
	bra.w	emit_load_integer_var_d0
.op_add:
	moveq	#-47,d5                         ; $d1 = add.l d0,<ea>
	bra.s	.emit_op_into_first
.op_sub:
	moveq	#-111,d5                        ; $91 = sub.l d0,<ea>
	bra.s	.emit_op_into_first
.op_and:
	moveq	#-63,d5                         ; $c1 = and.l d0,<ea>
	bra.s	.emit_op_into_first
.op_or:
	moveq	#-127,d5                        ; $81 = or.l d0,<ea>
	bra.s	.emit_op_into_first
.op_eor:
	moveq	#-79,d5                         ; $b1 = eor.l d0,<ea>
.emit_op_into_first:
	bsr.w	lookup_integer_var              ; first variable
	movem.w	d0/d7,-(sp)                     ; keep it
	addq.l	#2,a0                           ; skip the $8084
	bsr.w	lookup_integer_var              ; second variable
	addq.l	#6,a0                           ; skip the rest of the sequence
	movem.w	(sp)+,d1/d6                     ; d1 / d6 = first variable: the target
.load_source:
	tst.w	d7                              ; source a pointer variable?
	bpl.s	.load_source_direct
	move.w	#$246d,(a1)+                    ; movea.l v2(a5),a2 / move.l (a2),d0
	move.w	d0,(a1)+                        ; source offset
	move.w	#$2012,(a1)+                    ; $2012 = move.l (a2),d0
	bra.s	.apply_to_target
.load_source_direct:
	move.w	#$202d,(a1)+                    ; $202d = move.l d16(a5),d0
	move.w	d0,(a1)+                        ; source offset
.apply_to_target:
	tst.w	d6                              ; target a pointer variable?
	bpl.s	.apply_to_target_direct
	move.w	#$246d,(a1)+                    ; movea.l target(a5),a2
	move.w	d1,(a1)+                        ; target offset
	move.b	d5,(a1)+                        ; op opcode byte
	move.b	#$92,(a1)+                      ; op.l d0,(a2)
	rts
.apply_to_target_direct:
	move.b	d5,(a1)+                        ; op opcode byte
	move.b	#$ad,(a1)+                      ; op.l d0,d16(a5)
	move.w	d1,(a1)+                        ; target offset
	rts
.target_is_second:
	cmpi.w	#$8063,d4                       ; only the commutative ones: no sub
	beq.s	.swap_add
	cmpi.w	#$8060,d4                       ; $8060 and
	beq.s	.swap_and
	cmpi.w	#$8061,d4                       ; $8061 or
	beq.s	.swap_or
	cmpi.w	#$8062,d4                       ; $8062 eor
	beq.s	.swap_eor
	bra.s	emit_load_integer_var_d0
.swap_add:
	moveq	#-47,d5                         ; add
	bra.s	.emit_op_into_second
.swap_and:
	moveq	#-63,d5                         ; and
	bra.s	.emit_op_into_second
.swap_or:
	moveq	#-127,d5                        ; or
	bra.s	.emit_op_into_second
.swap_eor:
	moveq	#-79,d5                         ; eor
.emit_op_into_second:
	bsr.w	lookup_integer_var              ; first variable
	movem.w	d0/d7,-(sp)                     ; keep it
	addq.l	#2,a0                           ; skip the $8084
	bsr.w	lookup_integer_var              ; second variable
	addq.l	#6,a0                           ; skip the rest
	movem.w	(sp)+,d1/d6                     ; d1 / d6 = first variable
	exg	d1,d0                           ; the other variable is the target
	exg	d7,d6                           ; and its flags
	bra.s	.load_source
.same_variable_twice:
	cmpi.w	#$8063,d4                       ; v + v: add.l
	beq.w	.op_add
	cmpi.w	#$8064,d4                       ; v - v: 0
	beq.s	.store_zero
	cmpi.w	#$8060,d4                       ; v and v: v
	beq.s	.no_change
	cmpi.w	#$8061,d4                       ; v or v: v
	beq.s	.no_change
	cmpi.w	#$8062,d4                       ; v eor v: 0
	beq.s	.store_zero
	bra.s	emit_load_integer_var_d0
.store_zero:
	moveq	#0,d0                           ; v-v, v eor v: store 0
	adda.w	#$a,a0                          ; a0 on the target variable
	bra.w	gen_constant_store_integer_var
.no_change:
	adda.w	#$c,a0                          ; v and v, v or v: nothing
	rts

gen_not_integer_var_in_place:
	move.w	#$46ad,d1                       ; $46ad = not.l d16(a5)
	bra.s	emit_unary_integer_var_in_place

gen_neg_integer_var_in_place:
	move.w	#$44ad,d1                       ; $44ad = neg.l d16(a5)

;------------------------------------------------------------------------------
; $803f v $8078/$8032 $8042 v: neg.l / not.l of the variable in place (d1 = opcode).
;------------------------------------------------------------------------------
emit_unary_integer_var_in_place:
	cmpi.w	#$8042,d2                       ; $8042 after the NEG / NOT?
	bne.s	emit_load_integer_var_d0
	cmp.w	d3,d0                           ; into the same variable?
	bne.s	emit_load_integer_var_d0
	addq.l	#6,a0                           ; a0 on the target variable
	bra.s	emit_op_integer_var             ; neg.l / not.l var

;------------------------------------------------------------------------------
; Emits move.l var,d0 for the integer variable whose index is next in the IR.
;------------------------------------------------------------------------------
emit_load_integer_var_d0:
	moveq	#0,d1                           ; d0

;------------------------------------------------------------------------------
; Emits move.l var,Dn (d1 = register number) or movea.l for a0/a1 (d1 already an opcode).
;------------------------------------------------------------------------------
emit_load_integer_var_reg:
	ror.w	#7,d1                           ; register into bits 9-11
	ori.w	#$202d,d1                       ; $202d = move.l d16(a5),d0, register added

;------------------------------------------------------------------------------
; Looks up the integer variable whose index is next in the IR and emits instruction d1 with it as the
; operand (emit_op_on_variable).
;------------------------------------------------------------------------------
emit_op_integer_var:
	bsr.w	lookup_integer_var

;------------------------------------------------------------------------------
; As emit_op_integer_var, the variable already looked up (d0 = offset, d7 = table high word).
;------------------------------------------------------------------------------
emit_op_integer_var_found:
	tst.w	d7                              ; N: pointer variable
	bra.w	emit_op_on_variable

;------------------------------------------------------------------------------
; IR $8084: load an integer variable into d1.  When a constant ($8007) and add/sub follow, the IR is
; rearranged to constant, IR $8201/$8202 (add/sub variable), variable index, and handled from the $8007
; handler.  Otherwise folds the following operator into op.l var,d0 (add, sub, and, or), cmp.l var,d0 / Scc
; for compares, or emits move.l var,d1.
;------------------------------------------------------------------------------
gen_load_integer_var_d1:
	move.w	2(a0),d0                        ; the IR after the variable index
	cmpi.w	#$8007,d0                       ; constant follows
	bne.s	.fold_operator_d1
	move.w	8(a0),d2                        ; the operator after the constant
	cmpi.w	#$8063,d2                       ; $8063 add
	beq.s	.rewrite_as_add_var
	cmpi.w	#$8064,d2                       ; $8064 sub
	beq.s	.rewrite_as_sub_var
	cmpi.w	#$814c,d2                       ; $814c word add
	beq.s	.rewrite_as_add_var
	cmpi.w	#$814d,d2                       ; $814d word sub
	bne.s	.fold_operator_d1
.rewrite_as_sub_var:
	move.w	(a0),d1                         ; sub: constant, $8202, variable
	move.l	4(a0),2(a0)                     ; constant over the $8007
	move.w	#$8202,6(a0)                    ; $8202 = subtract variable
	move.w	d1,8(a0)                        ; variable index over the operator
	addq.l	#2,a0                           ; a0 on the constant for gen_int_constant
	bra.w	gen_int_constant
.rewrite_as_add_var:
	move.w	(a0),d1                         ; add: constant, $8201, variable
	move.l	4(a0),2(a0)                     ; constant over the $8007
	move.w	#$8201,6(a0)                    ; $8201 = add variable
	move.w	d1,8(a0)                        ; variable index over the operator
	addq.l	#2,a0                           ; a0 on the constant for gen_int_constant
	bra.w	gen_int_constant
.fold_operator_d1:
	bsr.w	lookup_integer_var              ; d0 = offset, d7 = flags
	move.w	(a0)+,d2                        ; d2 = the operator
	cmpi.w	#$8063,d2                       ; $8063 add
	beq.s	.emit_add_var
	cmpi.w	#$8064,d2                       ; $8064 sub
	beq.s	.emit_sub_var
	cmpi.w	#$814c,d2                       ; $814c word add
	beq.s	.emit_add_var
	cmpi.w	#$814d,d2                       ; $814d word sub
	beq.s	.emit_sub_var
	cmpi.w	#$8060,d2                       ; $8060 and
	beq.s	.emit_and_var
	cmpi.w	#$8061,d2                       ; $8061 or
	beq.s	.emit_or_var
	cmpi.w	#$807b,d2                       ; $807b =
	beq.s	.compare_eq_var
	cmpi.w	#$807c,d2                       ; $807c <>
	beq.s	.compare_ne_var
	cmpi.w	#$807f,d2                       ; $807f <=
	beq.s	.compare_le_var
	cmpi.w	#$8080,d2                       ; $8080 <
	beq.s	.compare_lt_var
	cmpi.w	#$807e,d2                       ; $807e >
	beq.s	.compare_gt_var
	cmpi.w	#$807d,d2                       ; $807d >=
	beq.s	.compare_ge_var
	subq.l	#2,a0                           ; no fold: back to the operator
	move.w	#$222d,d1                       ; $222d = move.l d16(a5),d1
	bra.w	emit_op_integer_var_found
.emit_add_var:
	move.w	#$d0ad,d1                       ; $d0ad = add.l d16(a5),d0
	bra.w	emit_op_integer_var_found
.emit_sub_var:
	move.w	#$90ad,d1                       ; $90ad = sub.l d16(a5),d0
	bra.w	emit_op_integer_var_found
.emit_and_var:
	move.w	#$c0ad,d1                       ; $c0ad = and.l d16(a5),d0
	bra.w	emit_op_integer_var_found
.emit_or_var:
	move.w	#$80ad,d1                       ; $80ad = or.l d16(a5),d0
	bra.w	emit_op_integer_var_found
.compare_eq_var:
	moveq	#7,d6                           ; EQ
.emit_cmp_var_scc:
	move.w	#$b0ad,d1                       ; $b0ad = cmp.l d16(a5),d0
	bsr.w	emit_op_integer_var_found       ; cmp.l var,d0
	rol.w	#8,d6                           ; condition into bits 8-11
	ori.w	#$50c0,d6                       ; Scc d0
	move.w	d6,(a1)+                        ; Scc d0
	bra.w	finish_condition_result         ; fold NOT / jumps, or ext.w d0
.compare_ne_var:
	moveq	#6,d6                           ; NE
	bra.s	.emit_cmp_var_scc
.compare_gt_var:
	moveq	#14,d6                          ; GT
	bra.s	.emit_cmp_var_scc
.compare_ge_var:
	moveq	#12,d6                          ; GE
	bra.s	.emit_cmp_var_scc
.compare_lt_var:
	moveq	#13,d6                          ; LT
	bra.s	.emit_cmp_var_scc
.compare_le_var:
	moveq	#15,d6                          ; LE
	bra.s	.emit_cmp_var_scc

gen_load_integer_var_d2:
	moveq	#2,d1                           ; register d2
	bra.w	emit_load_integer_var_reg

gen_load_integer_var_d3:
	moveq	#3,d1                           ; register d3
	bra.w	emit_load_integer_var_reg

gen_load_integer_var_d4:
	moveq	#4,d1                           ; register d4
	bra.w	emit_load_integer_var_reg

gen_load_integer_var_d5:
	moveq	#5,d1                           ; register d5
	bra.w	emit_load_integer_var_reg

gen_load_integer_var_d6:
	moveq	#6,d1                           ; register d6
	bra.w	emit_load_integer_var_reg

gen_load_integer_var_d7:
	moveq	#7,d1                           ; register d7
	bra.w	emit_load_integer_var_reg

gen_load_integer_var_a0:
	move.w	#$206d,d1                       ; $206d = movea.l d16(a5),a0
	bra.w	emit_op_integer_var

gen_load_integer_var_a1:
	move.w	#$226d,d1                       ; $226d = movea.l d16(a5),a1
	bra.w	emit_op_integer_var

;------------------------------------------------------------------------------
; $8040 followed by $8027: move.w var,-(sp).
;------------------------------------------------------------------------------
gen_push_word_var:
	bsr.w	lookup_word_var                 ; d0 = offset, N: pointer variable
	addq.l	#2,a0                           ; skip the $8027 (flags kept)
	bmi.s	.push_word_var_through_a2
	move.w	#$3f2d,(a1)+                    ; $3f2d = move.w d16(a5),-(sp)
	move.w	d0,(a1)+                        ; the offset
	rts
.push_word_var_through_a2:
	bsr.w	emit_load_var_pointer_a2
	move.w	#$3f12,(a1)+                    ; $3f12 = move.w (a2),-(sp)
	rts

;------------------------------------------------------------------------------
; $8040 followed by $8017: movea.w var,a2 / pea (a2) (pushes the word sign-extended).
;------------------------------------------------------------------------------
gen_push_word_var_long:
	bsr.w	lookup_word_var                 ; d0 = offset, N: pointer variable
	addq.l	#2,a0                           ; skip the $8017 (flags kept)
	bmi.s	.sign_extend_through_a2
	move.w	#$346d,(a1)+                    ; $346d = movea.w d16(a5),a2
	move.w	d0,(a1)+                        ; the offset
.emit_pea_a2:
	move.w	#$4852,(a1)+                    ; $4852 = pea (a2)
	rts
.sign_extend_through_a2:
	bsr.w	emit_load_var_pointer_a2
	move.w	#$3452,(a1)+                    ; $3452 = movea.w (a2),a2
	bra.s	.emit_pea_a2

;------------------------------------------------------------------------------
; $8040 v1 followed by $8043 v2: copy one word variable into another.
;------------------------------------------------------------------------------
gen_copy_word_var:
	bsr.w	lookup_word_var                 ; source variable
	movem.w	d0/d7,-(sp)                     ; keep source offset and flags
	addq.l	#2,a0                           ; skip the $8043
	bsr.w	lookup_word_var                 ; target variable
	movem.w	(sp)+,d1/d6                     ; d1 / d6 = source offset / flags
	cmp.w	d0,d1                           ; same variable: nothing
	beq.s	.word_copy_done
	tst.w	d6                              ; source a pointer variable?
	bmi.s	.word_source_is_pointer
	tst.w	d7                              ; target a pointer variable?
	bmi.s	.word_target_is_pointer
	move.w	#$3b6d,(a1)+                    ; $3b6d = move.w d16(a5),d16(a5)
	move.w	d1,(a1)+                        ; source offset
	move.w	d0,(a1)+                        ; target offset
.word_copy_done:
	rts
.word_source_is_pointer:
	tst.w	d7                              ; target a pointer variable too?
	bmi.s	.word_both_pointers
	move.w	#$206d,(a1)+                    ; movea.l source(a5),a0
	move.w	d1,(a1)+                        ; source offset
	move.w	#$3b50,(a1)+                    ; $3b50 = move.w (a0),d16(a5)
	move.w	d0,(a1)+                        ; target offset
	rts
.word_both_pointers:
	move.w	#$226d,(a1)+                    ; movea.l target(a5),a1
	move.w	d0,(a1)+                        ; target offset
	move.w	#$206d,(a1)+                    ; movea.l source(a5),a0
	move.w	d1,(a1)+                        ; source offset
	move.w	#$3290,(a1)+                    ; $3290 = move.w (a0),(a1)
	rts
.word_target_is_pointer:
	move.w	#$206d,(a1)+                    ; movea.l target(a5),a0
	move.w	d0,(a1)+                        ; target offset
	move.w	#$30ad,(a1)+                    ; $30ad = move.w d16(a5),(a0)
	move.w	d1,(a1)+                        ; source offset
	rts

;------------------------------------------------------------------------------
; IR $8040: load a word variable into d0.  Folds a following push ($8017 / $8027), copy ($8043), constant
; add/sub ($8008 with add or sub, also sub then NEG), or a second word variable ($808d) with compare, multiply, and, or,
; divide; v op v of one variable is simplified (v-v = 0, v/v = 1, v+v, v*v).  Otherwise move.w var,d0 with
; ext.l only when the user needs a long.
;------------------------------------------------------------------------------
gen_load_word_var:
	movem.w	(a0),d0-d5                      ; d0 = variable, d1.. = the IR words after it
	cmpi.w	#$8027,d1                       ; $8027 push word
	beq.w	gen_push_word_var
	cmpi.w	#$8017,d1                       ; $8017 push long
	beq.w	gen_push_word_var_long
	cmpi.w	#$8043,d1                       ; $8043 store into a word variable
	beq.s	gen_copy_word_var
	cmpi.w	#$8008,d1                       ; $8008 constant into d1
	bne.w	.try_second_word_var
	move.l	4(a0),d1                        ; d1 = the constant
	cmpi.w	#$8063,d4                       ; $8063 add
	beq.s	.add_word_constant
	cmpi.w	#$8064,d4                       ; $8064 sub
	bne.w	emit_load_word_var_d0
	cmpi.w	#$8078,d5                       ; sub then NEG
	bne.s	.sub_as_add
	move.l	d1,d2                           ; d2 = the constant
	ext.w	d1
	ext.l	d1                              ; byte sign-extended
	cmp.l	d1,d2                           ; fits a byte?
	bne.s	.reverse_sub_word_constant
	move.b	#$70,(a1)+                      ; moveq #n,d0, then sub.w var,d0
	move.b	d2,(a1)+                        ; the data byte
	moveq	#0,d1                           ; d1 = register d0
	bsr.w	gen_sub_word_variable           ; sub.w var,d0: c - v
	lea	$a(a0),a0                       ; skip up to and over the NEG
	rts
.reverse_sub_word_constant:
	addq.l	#2,a0                           ; a0 on the $8008
	bsr.w	low_word_only_d0                ; Z: only the low word of the result is used
	subq.l	#2,a0                           ; a0 back on the variable
	bne.w	emit_load_word_var_d0           ; long needed: plain load, the rest later
	bsr.w	emit_load_word_var_d0           ; move.w var,d0
	bsr.w	drop_trailing_ext_long          ; remove its ext.l
	addq.l	#4,a0                           ; a0 on the low word of the constant
	move.w	#$640,(a1)+                     ; addi.w #-c,d0, NEG skipped: v-c, not c-v (looks wrong)
	move.w	(a0)+,(a1)                      ; low word of the constant
	neg.w	(a1)+                           ; negated
	addq.l	#4,a0                           ; skip the operator and the NEG
	rts
.sub_as_add:
	neg.l	d1                              ; sub: add the negated constant
.add_word_constant:
	move.l	d1,d3                           ; d3 = the constant
	ext.w	d1
	ext.l	d1                              ; byte sign-extended
	cmp.l	d1,d3                           ; fits a byte?
	bne.s	.add_word_immediate
	move.b	#$70,(a1)+                      ; moveq #n,d0, then add.w var,d0
	move.b	d1,(a1)+                        ; the data byte
.emit_add_word_var:
	moveq	#0,d1                           ; d1 = register d0
	bsr.w	gen_add_word_variable           ; add.w var,d0
	addq.l	#8,a0                           ; skip the rest
	rts
.add_word_immediate:
	addq.l	#2,a0                           ; a0 on the $8008
	bsr.w	low_word_only_d0                ; Z: only the low word is used
	subq.l	#2,a0                           ; a0 back on the variable
	bne.w	emit_load_word_var_d0           ; long needed: plain load
	move.w	#$303c,(a1)+                    ; $303c = move.w #imm,d0
	move.w	d3,(a1)+                        ; the constant's low word
	bra.s	.emit_add_word_var
.try_second_word_var:
	cmpi.w	#$808d,d1                       ; $808d second word variable
	bne.w	emit_load_word_var_d0
	cmpi.w	#$807b,d3                       ; $807b =
	beq.s	.cmp_word_eq
	cmpi.w	#$807c,d3                       ; $807c <>
	beq.s	.cmp_word_ne
	cmpi.w	#$807e,d3                       ; $807e >
	beq.s	.cmp_word_gt
	cmpi.w	#$807d,d3                       ; $807d >=
	beq.s	.cmp_word_ge
	cmpi.w	#$8080,d3                       ; $8080 <
	beq.s	.cmp_word_lt
	cmpi.w	#$807f,d3                       ; $807f <=
	beq.s	.cmp_word_le
	cmpi.w	#$805e,d3                       ; $805e multiply
	beq.s	.emit_muls_word_var
	cmpi.w	#$814e,d3                       ; $814e word multiply
	beq.s	.emit_muls_word_var
	cmpi.w	#$8061,d3                       ; $8061 or
	beq.s	emit_word_var_or_var
	cmpi.w	#$8060,d3                       ; $8060 and
	beq.s	emit_word_var_and_var
	cmpi.w	#$805f,d3                       ; $805f divide
	beq.s	emit_word_var_divide_var
	bra.s	gen_word_var_with_itself        ; others: the same variable twice?
.emit_cmp_word_var_scc:
	move.w	d2,-(sp)                        ; keep the condition
	bsr.w	emit_load_word_var_d0_plain     ; move.w v1,d0
	addq.l	#2,a0                           ; skip the $808d
	move.w	#$b06d,d1                       ; $b06d = cmp.w d16(a5),d0
	bsr.w	emit_op_word_var                ; cmp.w v2,d0
	addq.l	#2,a0                           ; skip the compare IR
	move.w	(sp)+,d2                        ; the condition
	ror.w	#8,d2                           ; condition into bits 8-11
	ori.w	#$50c0,d2                       ; Scc d0
	move.w	d2,(a1)+                        ; Scc d0
	bra.w	finish_condition_result         ; fold NOT / jumps, or ext.w d0
.cmp_word_eq:
	moveq	#7,d2                           ; EQ
	bra.s	.emit_cmp_word_var_scc
.cmp_word_ne:
	moveq	#6,d2                           ; NE
	bra.s	.emit_cmp_word_var_scc
.cmp_word_ge:
	moveq	#12,d2                          ; GE
	bra.s	.emit_cmp_word_var_scc
.cmp_word_gt:
	moveq	#14,d2                          ; GT
	bra.s	.emit_cmp_word_var_scc
.cmp_word_lt:
	moveq	#13,d2                          ; LT
	bra.s	.emit_cmp_word_var_scc
.cmp_word_le:
	moveq	#15,d2                          ; LE
	bra.s	.emit_cmp_word_var_scc
.emit_muls_word_var:
	bsr.w	emit_load_word_var_d0_plain     ; move.w v1,d0
	addq.l	#2,a0                           ; skip the $808d
	move.w	#$c1ed,d1                       ; $c1ed = muls.w d16(a5),d0

;------------------------------------------------------------------------------
; emit_op_word_var, then skip one IR word.
;------------------------------------------------------------------------------
emit_op_word_var_skip:
	bsr.w	emit_op_word_var
	addq.l	#2,a0                           ; skip the operator
	rts

emit_word_var_divide_var:
	bsr.w	emit_load_word_var_d0_plain     ; move.w v1,d0
	move.w	#$48c0,(a1)+                    ; $48c0 = ext.l d0
	addq.l	#2,a0                           ; skip the $808d
	move.w	#$81ed,d1                       ; $81ed = divs.w d16(a5),d0
	bra.s	emit_word_var_op_extend

emit_word_var_or_var:
	bsr.w	emit_load_word_var_d0_plain     ; move.w v1,d0
	addq.l	#2,a0                           ; skip the $808d
	move.w	#$806d,d1                       ; $806d = or.w d16(a5),d0

emit_word_var_op_extend:
	bsr.s	emit_op_word_var_skip           ; op.w v2,d0 and skip the operator
	bra.w	gen_sign_extend_word            ; ext.l d0 if the user needs a long

emit_word_var_and_var:
	bsr.w	emit_load_word_var_d0_plain     ; move.w v1,d0
	addq.l	#2,a0                           ; skip the $808d
	move.w	#$c06d,d1                       ; $c06d = and.w d16(a5),d0
	bra.s	emit_word_var_op_extend

gen_word_var_with_itself:
	cmp.w	d0,d2                           ; same variable twice?
	bne.s	emit_load_word_var_d0
	cmpi.w	#$8063,d3                       ; $8063 add
	beq.s	.double_word_var
	cmpi.w	#$814c,d3                       ; $814c word add
	beq.s	.double_word_var
	cmpi.w	#$8064,d3                       ; $8064 sub
	beq.s	.result_zero
	cmpi.w	#$814d,d3                       ; $814d word sub
	beq.s	.result_zero
	cmpi.w	#$805e,d3                       ; multiply: taken before, never true here
	beq.s	.square_word_var
	cmpi.w	#$814e,d3                       ; $814e word multiply
	beq.s	.square_word_var
	cmpi.w	#$805f,d3                       ; divide: taken before, never true here
	beq.s	.result_one
	cmpi.w	#$8065,d3                       ; $8065 MOD
	beq.s	.result_zero
	cmpi.w	#$8060,d3                       ; and / or: taken before, never true here
	beq.s	.result_is_var
	cmpi.w	#$8061,d3                       ; $8061 or
	beq.s	.result_is_var
	cmpi.w	#$8062,d3                       ; $8062 eor
	beq.s	.result_zero
	bra.s	emit_load_word_var_d0           ; anything else: plain load
.result_zero:
	move.w	#$7000,(a1)+                    ; $7000 = moveq #0,d0 (v-v, v mod v, v eor v)
	addq.l	#8,a0                           ; skip v, $808d, v, operator
	rts
.result_one:
	move.w	#$7001,(a1)+                    ; $7001 = moveq #1,d0 (v/v)
	addq.l	#8,a0                           ; skip v, $808d, v, operator
	rts
.double_word_var:
	bsr.s	emit_load_word_var_d0_plain     ; move.w v,d0
	move.w	#$48c0,(a1)+                    ; ext.l d0 / add.l d0,d0
	move.w	#$d080,(a1)+                    ; $d080 = add.l d0,d0
	addq.l	#6,a0                           ; skip $808d, v, operator
	rts
.result_is_var:
	bsr.s	emit_load_word_var_d0_plain     ; move.w v,d0
	addq.l	#6,a0                           ; skip $808d, v, operator
	bra.w	gen_sign_extend_word
.square_word_var:
	bsr.s	emit_load_word_var_d0_plain     ; move.w v,d0
	move.w	#$c1c0,(a1)+                    ; $c1c0 = muls.w d0,d0
	addq.l	#6,a0                           ; skip $808d, v, operator
	rts

;------------------------------------------------------------------------------
; Emits move.w var,d0 ($302d) for the word variable next in the IR, with no extension.
;------------------------------------------------------------------------------
emit_load_word_var_d0_plain:
	move.w	#$302d,d1                       ; $302d = move.w d16(a5),d0
	bra.w	emit_op_word_var

;------------------------------------------------------------------------------
; Emits move.w var,d0 for the word variable next in the IR (d1 = 0 at emit_load_word_var_reg).
;------------------------------------------------------------------------------
emit_load_word_var_d0:
	moveq	#0,d1                           ; register d0

;------------------------------------------------------------------------------
; Emits move.w var,Dn (d1 = register) for the word variable next in the IR, then ext.l Dn unless the IR
; that uses the register takes a word (checked through low_word_only; for d0 through gen_sign_extend_word).
; For d5 the loop codes $80c1-$80cc, $812e-$8131, $8156-$815b and $81a1-$81a6 need no ext.l.  $808d followed
; by a multiply becomes muls.w d1,d0.  The address of an ext.l Dn is kept in ext_l_d1_code_address.
;------------------------------------------------------------------------------
emit_load_word_var_reg:
	move.w	d1,d2                           ; d2 = register number
	ror.w	#7,d1                           ; register into bits 9-11
	ori.w	#$302d,d1                       ; $302d = move.w d16(a5),d0, register added
	bsr.w	emit_op_word_var
	move.w	(a0),d0                         ; d0 = the IR that uses it
	cmpi.w	#$5,d2                          ; d5: look at the loop IR that uses it
	bne.s	.users_taking_a_word
	cmpi.w	#$800b,d0                       ; $800b constant into d4 first: skip it
	bne.s	.not_constant_d4
	move.w	6(a0),d0                        ; the IR after the constant
	bra.s	.check_loop_ir
.not_constant_d4:
	cmpi.w	#$801e,d0                       ; $801e pop into d4 first
	bne.s	.not_pop_d4
	move.w	2(a0),d0                        ; the IR after the pop
	bra.s	.check_loop_ir
.not_pop_d4:
	cmpi.w	#$8087,d0                       ; $8087 / $8090 / $809c: variable into d4 first
	beq.s	.after_var_load_d4
	cmpi.w	#$8090,d0                       ; $8090 word variable into d4
	beq.s	.after_var_load_d4
	cmpi.w	#$809c,d0                       ; $809c byte variable into d4
	bne.s	.check_loop_ir
.after_var_load_d4:
	move.w	4(a0),d0                        ; the IR after the variable
.check_loop_ir:
	cmpi.w	#$80c1,d0                       ; loop IR codes that take d5 as a word
	bcs.s	.users_taking_a_word
	cmpi.w	#$80cc,d0
	bls.s	.d5_kept_as_word
	cmpi.w	#$812e,d0                       ; $812e-$8131
	bcs.s	.users_taking_a_word
	cmpi.w	#$8131,d0
	bls.s	.d5_kept_as_word
	cmpi.w	#$8156,d0                       ; $8156-$815b
	bcs.s	.users_taking_a_word
	cmpi.w	#$815b,d0
	bls.s	.d5_kept_as_word
	cmpi.w	#$81a1,d0                       ; $81a1-$81a6
	bcs.s	.users_taking_a_word
	cmpi.w	#$81a6,d0
	bls.s	.d5_kept_as_word
	bra.s	.users_taking_a_word
.d5_kept_as_word:
	rts                                     ; loop IR takes d5 as a word: no ext.l
.users_taking_a_word:
	cmpi.w	#$8043,d0                       ; users that take a word: no ext.l
	beq.w	.no_ext_needed_word
	cmpi.w	#$1b2,d0                        ; FORC1
	beq.w	.no_ext_needed_word
	cmpi.w	#$1b3,d0                        ; FORC2
	beq.w	.no_ext_needed_word
	cmpi.w	#$811c,d0                       ; $811c
	beq.w	.no_ext_needed_word
	cmpi.w	#$80e0,d0                       ; $80e0-$80e7: variable op= value
	beq.w	.no_ext_needed_word
	cmpi.w	#$80e1,d0
	beq.w	.no_ext_needed_word
	cmpi.w	#$80e2,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$814c,d0                       ; $814c-$814e word operators
	beq.s	.no_ext_needed_word
	cmpi.w	#$814d,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$814e,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$80e3,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$80e4,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$80e5,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$80e6,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$80e7,d0
	beq.s	.no_ext_needed_word
	cmpi.w	#$1ae,d0                        ; FORW1
	beq.s	.no_ext_needed_word
	cmpi.w	#$1af,d0                        ; FORW2
	beq.s	.no_ext_needed_word
	cmpi.w	#$8040,d0                       ; $8040 / $803d / $8099: decided by the look-ahead
	beq.s	.extend_if_needed
	cmpi.w	#$803d,d0                       ; $803d byte variable
	beq.s	.extend_if_needed
	cmpi.w	#$8099,d0                       ; $8099 byte variable into d1
	beq.s	.extend_if_needed
	cmpi.w	#$808d,d0                       ; $808d followed by a multiply
	bne.s	.extend_if_needed
	cmpi.w	#$805e,4(a0)                    ; multiply follows: muls.w d1,d0
	beq.s	.fold_muls_d1
	cmpi.w	#$814e,4(a0)                    ; $814e word multiply
	beq.s	.fold_muls_d1
.extend_if_needed:
	tst.w	d2                              ; d0: gen_sign_extend_word decides
	beq.w	gen_sign_extend_word
	bsr.w	low_word_only                   ; does the user need a long?
	beq.s	.no_ext_needed_word             ; only the low word used: no ext.l
	move.l	a1,ext_l_d1_code_address        ; remember the ext.l Dn
	ori.w	#$48c0,d2                       ; $48c0 + n = ext.l Dn
	move.w	d2,(a1)+                        ; ext.l Dn
.no_ext_needed_word:
	rts
.fold_muls_d1:
	addq.l	#2,a0                           ; skip the $808d
	bsr.s	gen_load_word_var_d1            ; move.w v2,d1 (perhaps ext.l d1)
	cmpi.w	#$48c1,-(a1)                    ; $48c1 = ext.l d1 just emitted?
	beq.s	.emit_muls_d1_d0
	addq.l	#2,a1                           ; no: keep the last word
.emit_muls_d1_d0:
	move.w	#$c1c1,(a1)+                    ; $c1c1 = muls.w d1,d0
	addq.l	#2,a0                           ; skip the multiply IR
	rts

;------------------------------------------------------------------------------
; Looks up the word variable next in the IR and emits instruction d1 with it as the operand.
;------------------------------------------------------------------------------
emit_op_word_var:
	bsr.w	lookup_word_var                 ; d0 = offset, d7/N = through-pointer flag of the entry
	bra.w	emit_op_on_variable             ; emit opcode d1 with the variable as its operand

;------------------------------------------------------------------------------
; IR $808d: load a word variable into d1.  With a following constant and add/sub the IR is rearranged
; (IR $8203/$8204) as in gen_load_integer_var_d1; add/sub/$814c/$814d/$814e fold into the operation on d0;
; otherwise move.w var,d1 (ext.l when needed).
;------------------------------------------------------------------------------
gen_load_word_var_d1:
	move.w	2(a0),d0                        ; d0 = the IR after the variable index
	cmpi.w	#$8007,d0                       ; $8007 integer constant follows?
	bne.s	.no_constant_follows
	move.w	8(a0),d2                        ; d2 = the operator after the 4-byte constant
	cmpi.w	#$8063,d2                       ; $8063 add
	beq.s	.rearrange_add
	cmpi.w	#$8064,d2                       ; $8064 sub
	beq.s	.rearrange_sub
	cmpi.w	#$814c,d2                       ; $814c word add
	beq.s	.rearrange_add
	cmpi.w	#$814d,d2                       ; $814d word sub
	bne.s	.no_constant_follows
.rearrange_sub:
	move.w	(a0),d1                         ; sub: constant, $8204, variable
	move.l	4(a0),2(a0)                     ; move the constant down over the $8007
	move.w	#$8204,6(a0)                    ; then $8204 (subtract the word variable)
	move.w	d1,8(a0)                        ; then the variable index, over the operator
	addq.l	#2,a0                           ; a0 at the constant, as gen_int_constant expects
	bra.w	gen_int_constant                ; generate the constant; $8204 handles the variable
.rearrange_add:
	move.w	(a0),d1                         ; add: constant, $8203, variable
	move.l	4(a0),2(a0)                     ; move the constant down over the $8007
	move.w	#$8203,6(a0)                    ; then $8203 (add the word variable)
	move.w	d1,8(a0)                        ; then the variable index, over the operator
	addq.l	#2,a0                           ; a0 at the constant, as gen_int_constant expects
	bra.w	gen_int_constant                ; generate the constant; $8203 handles the variable
.no_constant_follows:
	bsr.w	lookup_word_var                 ; d0 = offset, d7/N = pointer flag; a0 past the index
	move.w	(a0)+,d2                        ; d2 = the operator that follows
	cmpi.w	#$8063,d2                       ; $8063 add: add.l via movea.w
	beq.s	emit_add_word_var_to_d0
	cmpi.w	#$8064,d2                       ; $8064 sub: sub.l via movea.w
	beq.s	emit_sub_word_var_from_d0
	cmpi.w	#$814c,d2                       ; $814c word add
	beq.s	.add_word_to_d0
	cmpi.w	#$814d,d2                       ; $814d word sub
	beq.s	.sub_word_from_d0
	cmpi.w	#$814e,d2                       ; $814e word multiply
	beq.s	.multiply_word_into_d0
	subq.l	#4,a0                           ; back to the variable index
	bra.s	emit_load_word_var_d1
.add_word_to_d0:
	move.w	#$d06d,d1                       ; $d06d = add.w d16(a5),d0
	bra.s	emit_op_word_var_found
.multiply_word_into_d0:
	move.w	#$c1ed,d1                       ; $c1ed = muls.w d16(a5),d0
	bra.s	emit_op_word_var_found
.sub_word_from_d0:
	move.w	#$906d,d1                       ; $906d = sub.w d16(a5),d0

;------------------------------------------------------------------------------
; As emit_op_word_var, the variable already looked up.
;------------------------------------------------------------------------------
emit_op_word_var_found:
	tst.w	d7                              ; N again from the entry's high word (d7), lost by the compares
	bra.w	emit_op_on_variable

;------------------------------------------------------------------------------
; movea.w var,a0 / add.l a0,d0: adds the word variable sign-extended.
;------------------------------------------------------------------------------
emit_add_word_var_to_d0:
	move.w	#$306d,d1                       ; $306d = movea.w d16(a5),a0
	bsr.s	emit_op_word_var_found          ; emit movea.w var,a0
	move.w	#$d088,(a1)+                    ; $d088 = add.l a0,d0
	rts

;------------------------------------------------------------------------------
; movea.w var,a0 / sub.l a0,d0.
;------------------------------------------------------------------------------
emit_sub_word_var_from_d0:
	move.w	#$306d,d1                       ; $306d = movea.w d16(a5),a0
	bsr.s	emit_op_word_var_found          ; emit movea.w var,a0
	move.w	#$9088,(a1)+                    ; $9088 = sub.l a0,d0
	rts

;------------------------------------------------------------------------------
; move.w var,d1 with ext.l when needed; for a following shift, rotate or bit operation ($8068-$8077) the
; last word (the ext.l) is removed again.
;------------------------------------------------------------------------------
emit_load_word_var_d1:
	moveq	#1,d1                           ; register d1
	bsr.w	emit_load_word_var_reg          ; move.w var,d1 / ext.l d1 when needed
	cmpi.w	#$8068,(a0)                     ; shift, rotate or bit operation follows
	bcs.s	.keep_ext_l                     ; below $8068: keep the ext.l
	cmpi.w	#$8077,(a0)                     ; up to $8077 bit change
	bhi.s	.keep_ext_l                     ; above $8077: keep the ext.l
	subq.l	#2,a1                           ; remove the ext.l d1
.keep_ext_l:
	rts

gen_load_word_var_d2:
	moveq	#2,d1                           ; register d2
	bra.w	emit_load_word_var_reg

gen_load_word_var_d3:
	moveq	#3,d1                           ; register d3
	bra.w	emit_load_word_var_reg

gen_load_word_var_d4:
	moveq	#4,d1                           ; register d4
	bra.w	emit_load_word_var_reg

gen_load_word_var_d5:
	moveq	#5,d1                           ; register d5
	bra.w	emit_load_word_var_reg

gen_load_word_var_d6:
	moveq	#6,d1                           ; register d6
	bra.w	emit_load_word_var_reg

gen_load_word_var_d7:
	moveq	#7,d1                           ; register d7
	bra.w	emit_load_word_var_reg

gen_load_word_var_a0:
	move.w	#$306d,d1                       ; $306d = movea.w d16(a5),a0
	bra.w	emit_op_word_var

gen_load_word_var_a1:
	move.w	#$326d,d1                       ; $326d = movea.w d16(a5),a1
	bra.w	emit_op_word_var

;------------------------------------------------------------------------------
; IR $803d: load a byte variable into d0.  Bytes are unsigned: moveq #0,d0 / move.b var,d0, or only
; move.b when the user takes a byte ($8044, $80e4-$80e6, FORC1, FORC2, $8123, $80bf, $80c0, or an
; operation whose result is stored as a byte).
;------------------------------------------------------------------------------
gen_load_byte_var:
	moveq	#0,d1                           ; register d0
	move.w	2(a0),d0                        ; the IR that uses the byte
	cmpi.w	#$8044,d0                       ; $8044 store byte variable
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$80e4,d0                       ; $80e4 byte variable add
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$80e5,d0                       ; $80e5 byte variable sub
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$80e6,d0                       ; $80e6 byte variable mul
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$1b2,d0                        ; FORC1 (library routine $1b2)
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$1b3,d0                        ; FORC2 (library routine $1b3)
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$8123,d0                       ; $8123 FOR compare with byte limit
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$80bf,d0                       ; $80bf jump if false: move.b sets the flags
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.s	emit_move_byte_var_to_reg
	cmpi.w	#$808d,d0                       ; $808d word variable into d1
	beq.s	.second_operand_loaded
	cmpi.w	#$8084,d0                       ; $8084 integer variable into d1
	beq.s	.second_operand_loaded
	cmpi.w	#$8099,d0                       ; $8099 byte variable into d1
	bne.s	emit_load_byte_var_zero_extended
.second_operand_loaded:
	move.w	4(a0),d0                        ; 4(a0) is that load's variable index, not an operator (looks wrong)
	cmpi.w	#$805e,d0                       ; $805e integer multiply
	beq.s	.check_byte_store
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.check_byte_store
	cmpi.w	#$8064,d0                       ; $8064 sub
	bne.s	emit_load_byte_var_zero_extended
.check_byte_store:
	cmpi.w	#$8044,6(a0)                    ; result stored into a byte variable: move.b is enough
	beq.s	emit_move_byte_var_to_reg       ; yes: move.b only; otherwise zero-extend below

;------------------------------------------------------------------------------
; Emits moveq #0,Dn / move.b var,Dn (d1 = register number).
;------------------------------------------------------------------------------
emit_load_byte_var_zero_extended:
	ror.w	#7,d1                           ; register number to bits 9-11
	move.w	d1,d2                           ; d1 keeps the register for the move.b
	ori.w	#$7000,d2                       ; $7000 = moveq #0,d0, register added
	move.w	d2,(a1)+                        ; moveq #0,Dn

;------------------------------------------------------------------------------
; Emits move.b var,Dn (d1 = register number << 9 or 0).
;------------------------------------------------------------------------------
emit_move_byte_var_to_reg:
	ori.w	#$102d,d1                       ; $102d = move.b d16(a5),d0, register added

;------------------------------------------------------------------------------
; Looks up the byte variable next in the IR and emits instruction d1 with it as the operand.
;------------------------------------------------------------------------------
emit_op_byte_var:
	bsr.w	lookup_byte_var                 ; d0 = offset, N = through pointer

;------------------------------------------------------------------------------
; Emits instruction d1 with operand d16(a5), offset d0 (flags from the variable's table entry).  When the
; entry is negative the variable holds a pointer: movea.l d0(a5),a2 first and the operand becomes (a2).
; The source effective address is in bits 0-5 of d1 ($2d = d16(a5); eor $3f gives $12 = (a2)).
;------------------------------------------------------------------------------
emit_op_on_variable:
	bmi.s	.through_pointer
	move.w	d1,(a1)+                        ; opcode with d16(a5)
	move.w	d0,(a1)+                        ; offset
	rts
.through_pointer:
	bsr.w	emit_load_var_pointer_a2        ; movea.l var(a5),a2
	eori.w	#$3f,d1                         ; d16(a5) -> (a2)
	move.w	d1,(a1)+                        ; opcode with (a2), no offset word
	rts

;------------------------------------------------------------------------------
; Emits move.b boolvar,Dn for the boolean variable next in the IR (sets the flags for a following jump).
;------------------------------------------------------------------------------
emit_move_bool_var_to_reg:
	ror.w	#7,d1                           ; register number to bits 9-11
	ori.w	#$102d,d1                       ; $102d = move.b d16(a5),d0, register added
	bsr.w	lookup_bool_var                 ; d0 = offset, N = through pointer
	bra.s	emit_op_on_variable

;------------------------------------------------------------------------------
; IR $8099: load a byte variable into d1 (moveq #0,d1 / move.b var,d1, or only move.b when the result is
; used as a byte or as a shift count).
;------------------------------------------------------------------------------
gen_load_byte_var_d1:
	move.w	2(a0),d0                        ; d0 = the IR after the variable index
	cmpi.w	#$8009,d0                       ; $8009 constant into d2
	bne.s	.check_operation
	cmpi.w	#$8124,8(a0)                    ; $8124 byte compare >= after the constant
	beq.s	.move_byte_only
	cmpi.w	#$8125,8(a0)                    ; $8125 byte compare <=
	beq.s	.move_byte_only
	cmpi.w	#$8129,8(a0)                    ; $8129 byte FOR test with a variable step
	beq.s	.move_byte_only
.check_operation:
	cmpi.w	#$805e,d0                       ; $805e integer multiply
	beq.s	.check_store_follows
	cmpi.w	#$8063,d0                       ; $8063 add
	beq.s	.check_store_follows
	cmpi.w	#$8064,d0                       ; $8064 sub
	bne.s	.check_second_load
.check_store_follows:
	cmpi.w	#$8044,4(a0)                    ; $8044 store byte follows the operation: no zero-extension
	beq.s	.move_byte_only
.check_second_load:
	cmpi.w	#$803f,d0                       ; $803f integer variable load
	beq.s	.check_operation_after_load
	cmpi.w	#$8040,d0                       ; $8040 word variable load
	beq.s	.check_operation_after_load
	cmpi.w	#$803d,d0                       ; $803d byte variable load
	bne.s	.check_shift_count
.check_operation_after_load:
	move.w	6(a0),d1                        ; d1 = the operator after that variable's index
	cmpi.w	#$805e,d1                       ; $805e integer multiply
	beq.s	.check_store_after_operation
	cmpi.w	#$8063,d1                       ; $8063 add
	beq.s	.check_store_after_operation
	cmpi.w	#$8064,d1                       ; $8064 sub
	bne.s	.check_shift_count
.check_store_after_operation:
	cmpi.w	#$8044,8(a0)                    ; $8044 store byte variable follows
	beq.s	.move_byte_only
.check_shift_count:
	cmpi.w	#$8068,d0                       ; shifts, rotates and bit ops $8068-$8077: d1 is a count
	bcs.s	.zero_extend
	cmpi.w	#$8077,d0                       ; up to $8077 bit change
	bhi.s	.zero_extend
.move_byte_only:
	move.w	#$122d,d1                       ; $122d = move.b d16(a5),d1
	bra.w	emit_op_byte_var                ; emit move.b var,d1
.zero_extend:
	moveq	#1,d1                           ; register d1
	bra.w	emit_load_byte_var_zero_extended ; moveq #0,d1 / move.b var,d1

gen_load_byte_var_d2:
	moveq	#2,d1                           ; register d2
	bra.w	emit_load_byte_var_zero_extended

gen_load_byte_var_d3:
	moveq	#3,d1                           ; register d3
	bra.w	emit_load_byte_var_zero_extended

gen_load_byte_var_d4:
	moveq	#4,d1                           ; register d4
	bra.w	emit_load_byte_var_zero_extended

gen_load_byte_var_d5:
	moveq	#5,d1                           ; register d5
	bra.w	emit_load_byte_var_zero_extended

gen_load_byte_var_d6:
	moveq	#6,d1                           ; register d6
	bra.w	emit_load_byte_var_zero_extended

gen_load_byte_var_d7:
	moveq	#7,d1                           ; register d7
	bra.w	emit_load_byte_var_zero_extended

;------------------------------------------------------------------------------
; IR $80a1: as gen_load_byte_var_a0, then adds 2 to the high byte of the word at -2(a0) to turn movea.w
; (sp)+,a0 into movea.w (sp)+,a1.  The code changes -2(a0), the IR, not -2(a1), the code (looks wrong).
;------------------------------------------------------------------------------
gen_load_byte_var_a1:
	bsr.s	gen_load_byte_var_a0            ; emits clr.w -(sp) / move.b / movea.w (sp)+,a0
	addq.b	#2,-$2(a0)                      ; meant for movea.w (sp)+,a1, but changes the IR
	rts

;------------------------------------------------------------------------------
; IR $80a0: load a byte variable into a0: clr.w -(sp) / move.b var,1(sp) / movea.w (sp)+,a0.
;------------------------------------------------------------------------------
gen_load_byte_var_a0:
	move.w	#$4267,(a1)+                    ; $4267 = clr.w -(sp)
	bsr.w	lookup_byte_var                 ; d0 = offset, N = through pointer
	bmi.s	.byte_through_pointer           ; pointer variable: movea.l var(a5),a2 first
	move.w	#$1f6d,(a1)+                    ; $1f6d = move.b d16(a5),d16(sp)
	move.w	d0,(a1)+                        ; offset
	move.l	#$1305f,(a1)+                   ; offset 1 / $305f = movea.w (sp)+,a0
	rts
.byte_through_pointer:
	bsr.w	emit_load_var_pointer_a2        ; movea.l var(a5),a2
	move.l	#$1f520001,(a1)+                ; $1f52 0001 = move.b (a2),1(sp)
	move.w	#$305f,(a1)+                    ; $305f = movea.w (sp)+,a0
	rts

gen_load_bool_var_d7:
	moveq	#7,d1                           ; register d7
	bra.s	emit_load_bool_var_reg

gen_load_bool_var_d6:
	moveq	#6,d1                           ; register d6
	bra.s	emit_load_bool_var_reg

gen_load_bool_var_d5:
	moveq	#5,d1                           ; register d5
	bra.s	emit_load_bool_var_reg

gen_load_bool_var_d4:
	moveq	#4,d1                           ; register d4
	bra.s	emit_load_bool_var_reg

gen_load_bool_var_d3:
	moveq	#3,d1                           ; register d3
	bra.s	emit_load_bool_var_reg

gen_load_bool_var_d2:
	moveq	#2,d1                           ; register d2
	bra.s	emit_load_bool_var_reg

gen_load_bool_var_d1:
	moveq	#1,d1                           ; register d1
	bra.s	emit_load_bool_var_reg

;------------------------------------------------------------------------------
; IR $803c: load a boolean variable into d0 as 0 / -1.  Before a jump ($80bf/$80c0) only move.b var,d0.
;------------------------------------------------------------------------------
gen_load_bool_var:
	moveq	#0,d1                           ; register d0
	cmpi.w	#$80c0,2(a0)                    ; jump follows: move.b sets the flags
	beq.w	emit_move_bool_var_to_reg
	cmpi.w	#$80bf,2(a0)                    ; $80bf jump if false follows
	beq.w	emit_move_bool_var_to_reg

;------------------------------------------------------------------------------
; Emits moveq #0,Dn / tst.b var / beq.s +2 / moveq #-1,Dn (d1 = register number).
;------------------------------------------------------------------------------
emit_load_bool_var_reg:
	ror.w	#7,d1                           ; register number to bits 9-11
	ori.w	#$7000,d1                       ; $7000 = moveq #0,d0, register added
	move.w	d1,(a1)+                        ; moveq #0,Dn
	bsr.w	lookup_bool_var                 ; d0 = offset, N = through pointer
	bmi.s	.bool_through_pointer           ; pointer variable: test through a2
	move.w	#$4a2d,(a1)+                    ; $4a2d = tst.b d16(a5)
	move.w	d0,(a1)+                        ; offset
	move.w	#$6702,(a1)+                    ; $6702 = beq.s +2
	st	d1                              ; d1 becomes $70ff + reg = moveq #-1,Dn
	move.w	d1,(a1)+                        ; the moveq #-1,Dn
	rts
.bool_through_pointer:
	bsr.w	emit_load_var_pointer_a2        ; movea.l var(a5),a2
	move.w	#$4a12,(a1)+                    ; $4a12 = tst.b (a2)
	move.w	#$6702,(a1)+                    ; $6702 = beq.s +2
	st	d1                              ; moveq #-1,Dn
	move.w	d1,(a1)+                        ; the moveq #-1,Dn
	rts

gen_load_bool_var_a1:
	moveq	#1,d1                           ; register a1
	move.w	#$93c9,(a1)+                    ; $93c9 = suba.l a1,a1
	bra.s	emit_load_bool_var_areg

gen_load_bool_var_a0:
	moveq	#0,d1                           ; register a0
	move.w	#$91c8,(a1)+                    ; $91c8 = suba.l a0,a0

;------------------------------------------------------------------------------
; Emits tst.b var / beq.s +2 / subq.l #1,An after the suba.l An,An emitted by the caller (d1 = 0 for a0,
; 1 for a1).  The pointer case writes tst.b (a2) followed by the offset word and loads no a2 (looks wrong).
;------------------------------------------------------------------------------
emit_load_bool_var_areg:
	bsr.w	lookup_bool_var                 ; d0 = offset, N = through pointer
	bmi.s	.areg_through_pointer           ; pointer variable
	move.w	#$4a2d,(a1)+                    ; $4a2d = tst.b d16(a5)
	move.w	d0,(a1)+                        ; offset
	move.w	#$6702,(a1)+                    ; $6702 = beq.s +2
	move.w	#$5388,(a1)                     ; $5388 = subq.l #1,a0, register added
	or.w	d1,(a1)+                        ; register a0 or a1
	rts
.areg_through_pointer:
	move.w	#$4a12,(a1)+                    ; tst.b (a2), then the offset word
	move.w	d0,(a1)+                        ; offset word after the tst.b (a2) (looks wrong)
	move.w	#$6702,(a1)+                    ; $6702 = beq.s +2
	move.w	#$5388,(a1)                     ; $5388 = subq.l #1,a0, register added
	or.w	d1,(a1)+                        ; register a0 or a1
	rts

;------------------------------------------------------------------------------
; IR $803e: load a float variable.  With a following float constant ($8001) and operator, the IR is
; rearranged to constant, $805d variable, operator with the operands swapped ($804b<->$804c, $804e<->$804f,
; $8056<->$8058, $8057<->$8059, $8050<->$8051, $8052<->$8053), and handled from the $8000 constant handler;
; var + 1.0 calls VFADDQ1, var * 2^n / var / 2^n use VMUL2P / VDIV2P / VDOUBLE / VHALF.  Otherwise the address
; goes into a0 and emit_use_float_var_at_a0 decides.
;------------------------------------------------------------------------------
gen_load_float_var:
	cmpi.w	#$8001,2(a0)                    ; $8001 = float constant as second operand
	bne.w	.use_variable_address
	movem.w	$c(a0),d0-d1                    ; d0 = operator after the 8-byte constant, d1 = the IR after it
	tst.w	$a(a0)                          ; exponent 0: the constant is 0.0
	bne.s	.swap_operator
	cmpi.w	#$80bf,d1                       ; $80bf jump if false after the operator
	beq.s	.compare_with_zero
	cmpi.w	#$80c0,d1                       ; $80c0 jump if true after the operator
	bne.s	.swap_operator
.compare_with_zero:
	cmpi.w	#$8056,d0                       ; below $8056: not a comparison
	bcs.s	.swap_operator
	cmpi.w	#$805b,d0                       ; comparison with 0.0 before a jump: test the exponent directly
	bls.w	.use_variable_address
.swap_operator:
	cmpi.w	#$804a,d0                       ; swap the operands of the operator
	beq.w	.check_power_of_two             ; $804a FADD: no swap needed
	cmpi.w	#$804b,d0                       ; $804b FSUB
	bne.s	.check_reverse_sub
.flip_sub:
	eori.w	#$7,d0                          ; $804b <-> $804c (FSUB / FXSUB)
	bra.s	.check_power_of_two
.check_reverse_sub:
	cmpi.w	#$804c,d0                       ; $804c FXSUB
	beq.s	.flip_sub
	cmpi.w	#$804d,d0                       ; $804d FMUL: no swap needed
	beq.s	.check_power_of_two
	cmpi.w	#$804e,d0                       ; $804e FDIV
	bne.s	.check_reverse_div
.flip_div:
	eori.w	#$1,d0                          ; $804e <-> $804f (FDIV / FXDIV)
	bra.s	.check_power_of_two
.check_reverse_div:
	cmpi.w	#$804f,d0                       ; $804f FXDIV
	beq.s	.flip_div
	cmpi.w	#$805a,d0                       ; $805a = : no swap needed
	beq.s	.check_power_of_two
	cmpi.w	#$805b,d0                       ; $805b <> : no swap needed
	beq.s	.check_power_of_two
	cmpi.w	#$8057,d0                       ; $8057 >=
	bne.s	.check_le
.flip_ge_le:
	eori.w	#$e,d0                          ; $8057 <-> $8059 (>= / <=)
	bra.s	.check_power_of_two
.check_le:
	cmpi.w	#$8059,d0                       ; $8059 <=
	beq.s	.flip_ge_le
	cmpi.w	#$8056,d0                       ; $8056 >
	bne.s	.check_lt
.flip_gt_lt:
	eori.w	#$e,d0                          ; $8056 <-> $8058 (> / <)
	bra.s	.check_power_of_two
.check_lt:
	cmpi.w	#$8058,d0                       ; $8058 <
	beq.s	.flip_gt_lt
	cmpi.w	#$8052,d0                       ; $8052 MOD
	bne.s	.check_reverse_mod
.flip_mod:
	eori.w	#$1,d0                          ; $8052 <-> $8053 (MOD / reverse MOD)
	bra.s	.check_power_of_two
.check_reverse_mod:
	cmpi.w	#$8053,d0                       ; $8053 reverse MOD
	beq.s	.flip_mod
	cmpi.w	#$8050,d0                       ; $8050 integer DIV
	bne.s	.check_reverse_integer_div
.flip_integer_div:
	eori.w	#$1,d0                          ; $8050 <-> $8051 (DIV / reverse DIV)
	bra.s	.check_power_of_two
.check_reverse_integer_div:
	cmpi.w	#$8051,d0                       ; $8051 reverse DIV
	beq.s	.flip_integer_div
	bra.s	.use_variable_address           ; other operators (power): no rearranging
.check_power_of_two:
	cmpi.w	#$8000,4(a0)                    ; mantissa $80000000 0000: a power of two
	bne.s	.swap_to_constant_first
	tst.l	6(a0)                           ; low four mantissa bytes zero too?
	bne.s	.swap_to_constant_first
	move.w	$a(a0),d1                       ; d1 = exponent word
	cmpi.w	#$804a,d0                       ; FADD
	beq.s	.check_plus_one
	cmpi.w	#$804f,d0                       ; FXDIV after the swap: variable / constant
	beq.w	gen_float_var_divide_power_of_two
	cmpi.w	#$804d,d0                       ; FMUL
	beq.w	gen_float_var_multiply_power_of_two
	bra.s	.swap_to_constant_first
.check_plus_one:
	cmpi.w	#$3ff,d1                        ; 1.0
	bne.s	.swap_to_constant_first
	bsr.w	emit_float_var_address_a0       ; lea var(a5),a0
	lea	$c(a0),a0                       ; skip the constant and the operator
	moveq	#54,d0                          ; VFADDQ1
	bra.w	emit_library_call               ; emit jsr VFADDQ1
.swap_to_constant_first:
	move.w	(a0),d1                         ; rearrange to constant, $805d variable, operator
	move.l	4(a0),(a0)                      ; first half of the constant over the index and $8001
	move.l	8(a0),4(a0)                     ; then the low half of the constant
	move.w	#$805d,8(a0)                    ; then $805d second float variable
	move.w	d1,$a(a0)                       ; its index
	move.w	d0,$c(a0)                       ; the operator, operands now swapped
	bra.w	emit_float_constant             ; a0 at the constant; $805d var follows it
.use_variable_address:
	bsr.w	emit_float_var_address_a0       ; lea var(a5),a0 (or the pointer); a0 past the index

;------------------------------------------------------------------------------
; a0 = address of a float variable.  Uses it directly where a routine takes a pointer: jump if false/true
; (tests the exponent word), copy into another float variable ($8041), a second variable ($805d) with an
; operator from float_var_var_routine_table, PRNUM/PXNUM/P0RNUM/P0XNUM -> PRVAR/PXVAR/P0RVAR/P0XVAR, $8005
; -> VFFTOI, $8011 -> VDOUBLE, $8002 push -> two move.l (a0)+,-(sp), FINT..FCOSQ -> VFINT..VFCOSQ.  Otherwise
; loads it: move.l (a0)+,d0 / move.w (a0)+,d1 / move.w (a0)+,d2.
;------------------------------------------------------------------------------
emit_use_float_var_at_a0:
	move.w	(a0),d0                         ; d0 = the IR that uses the variable
	cmpi.w	#$80bd,d0                       ; $80bd float jump if false
	beq.w	gen_float_var_jump_if_false
	cmpi.w	#$80be,d0                       ; $80be float jump if true
	beq.w	gen_float_var_jump_if_true
	cmpi.w	#$8041,d0                       ; $8041 store into float variable
	beq.w	.store_into_float_var
	cmpi.w	#$805d,d0                       ; $805d second float variable
	beq.w	.variable_with_variable
	cmpi.w	#$3f,d0                         ; PRNUM
	beq.s	.print_var_round
	cmpi.w	#$f1,d0                         ; PXNUM
	beq.s	.print_var_exact
	cmpi.w	#$262,d0                        ; P0RNUM
	beq.s	.print_round
	cmpi.w	#$263,d0                        ; P0XNUM
	beq.s	.print_exact
	cmpi.w	#$8005,d0                       ; $8005 = FFTOI
	beq.s	.float_to_int
	cmpi.w	#$8011,d0                       ; $8011 = DOUBLE
	beq.s	.double_var
	cmpi.w	#$8002,d0                       ; $8002 = push float
	beq.s	.push_var
	cmpi.w	#$b2,d0                         ; FINT .. FCOSQ
	bcs.s	.load_into_d0_d2
	cmpi.w	#$c4,d0                         ; up to FCOSQ
	bcc.s	.load_into_d0_d2
	addi.w	#$12,d0                         ; + $12: VFINT .. VFCOSQ, the versions taking a0
	addq.l	#2,a0                           ; skip the operator
	bra.w	emit_library_call               ; emit jsr to it, pointer in a0
.load_into_d0_d2:
	move.w	#$2018,(a1)+                    ; $2018 = move.l (a0)+,d0
	move.w	#$3218,(a1)+                    ; $3218 = move.w (a0)+,d1
	move.w	#$3418,(a1)+                    ; $3418 = move.w (a0)+,d2
	rts
.print_round:
	move.w	#$268,d0                        ; P0RVAR
	bra.s	.call_routine
.print_exact:
	move.w	#$269,d0                        ; P0XVAR
	bra.s	.call_routine
.print_var_round:
	move.w	#$1d5,d0                        ; PRVAR
	bra.s	.call_routine
.print_var_exact:
	move.w	#$1d6,d0                        ; PXVAR
.call_routine:
	addq.l	#2,a0                           ; skip the operator
	bra.w	emit_library_call
.float_to_int:
	move.w	#$1d8,d0                        ; VFFTOI
	bra.s	.call_routine
.double_var:
	addq.l	#2,a0                           ; skip the $8011
	move.w	#$290,d0                        ; VDOUBLE
	bra.w	emit_library_call
.store_into_float_var:
	addq.l	#2,a0                           ; skip the $8041
	bsr.w	emit_float_var_address_a0       ; lea dest(a5),a0, turned into lea dest(a5),a1 below
	addi.w	#$200,-$4(a1)                   ; second address into a1
	move.l	#$22d822d8,(a1)+                ; $22d8 = move.l (a0)+,(a1)+, twice
	rts
.push_var:
	move.l	#$2f182f18,(a1)+                ; $2f18 = move.l (a0)+,-(sp), twice
	addq.l	#2,a0                           ; skip the $8002
	rts
.variable_with_variable:
	move.w	4(a0),d0                        ; the operator after $805d var
	lea	float_var_var_routine_table(pc),a2 ; 14 operators, then their 14 routines
	moveq	#13,d1                          ; dbeq count: 14 entries
.find_var_var_operator:
	cmp.w	(a2)+,d0                        ; is d0 one of them?
	dbeq	d1,.find_var_var_operator       ; until found or all 14 tried
	bne.s	.load_into_d0_d2                ; not found: load the first variable into d0-d2
	move.w	$1a(a2),-(sp)                   ; routine number 14 words on (a2 is one past the match)
	addq.l	#2,a0                           ; skip the $805d
	bsr.w	emit_float_var_address_a0       ; lea var2(a5),a0
	addi.w	#$200,-$4(a1)                   ; second address into a1
	addq.l	#2,a0                           ; skip the operator
	move.w	(sp)+,d0                        ; d0 = the routine
	bra.w	emit_library_call               ; emit jsr to the routine, (a0) op (a1)

; 14 IR operator codes followed by 14 library routine numbers: the routine for float variable (a0)
; operator float variable (a1): VVFADD VVFSUB VVFXSUB VVFMUL VVFDIV VVFXDIV VVFEQ VVFNE VVFGT VVFGE VVFLT VVFLE
; VVFMIN VVFMAX.
float_var_var_routine_table:
	dc.w	$804a,$804b,$804c,$804d,$804e,$804f,$805a,$805b
	dc.w	$8056,$8057,$8058,$8059,$812a,$812b,$0296,$0297
	dc.w	$0298,$029f,$02a0,$02a1,$0299,$029a,$029b,$029c
	dc.w	$029d,$029e,$0336,$0338

gen_float_var_jump_if_false:
	move.w	#$80bf,(a0)                     ; becomes the integer jump if false
	bra.s	emit_float_var_exponent_test    ; exponent word zero means 0.0

gen_float_var_jump_if_true:
	move.w	#$80c0,(a0)                     ; becomes the integer jump if true

;------------------------------------------------------------------------------
; Tests the exponent word of the float variable at a0: move.w 6(a0),d2, or the lea just emitted becomes
; move.w var+6(a5),d2.  Continues at mark_result_modified.
;------------------------------------------------------------------------------
emit_float_var_exponent_test:
	cmpi.w	#$41ed,-$4(a1)                  ; $41ed = lea d16(a5),a0 just emitted?
	bne.s	.emit_test_through_a0
	move.w	#$342d,-$4(a1)                  ; $342d = move.w d16(a5),d2, offset + 6
	addq.w	#6,-$2(a1)                      ; offset + 6: the exponent word
	bra.s	.done
.emit_test_through_a0:
	move.l	#$34280006,(a1)+                ; $3428 0006 = move.w 6(a0),d2
.done:
	bra.w	mark_result_modified            ; d2 now holds the result for the jump

;------------------------------------------------------------------------------
; Float variable times the constant 2^n (d1 = the constant's exponent word, negative for a negative
; constant, which adds neg.w d2).
;------------------------------------------------------------------------------
gen_float_var_multiply_power_of_two:
	bsr.w	emit_float_var_address_a0       ; lea var(a5),a0
	move.w	d1,d0                           ; d0 = signed exponent (sign of the constant)
	bpl.s	emit_float_var_times_power_of_two ; positive constant
	neg.w	d1                              ; exponent without the sign bit
	bsr.s	emit_float_var_times_power_of_two ; emit the multiply by 2^n
	move.w	#$4442,(a1)+                    ; $4442 = neg.w d2: negative constant
	rts

;------------------------------------------------------------------------------
; d6 = d1 - $3ff (the power n), then emit_float_var_scale.
;------------------------------------------------------------------------------
emit_float_var_times_power_of_two:
	move.w	#$3ff,d6                        ; 1.0 has exponent $3ff
	sub.w	d1,d6                           ; d6 = $3ff - exponent
	neg.w	d6                              ; d6 = exponent - $3ff = n

;------------------------------------------------------------------------------
; Skips the constant and operator in the IR and emits the scaling of the float variable at a0 by 2^d6:
; moveq/move.w #n,d3 and VMUL2P, VDOUBLE for n = 1, a plain load for n = 0; negative n goes to
; emit_float_var_scale_down.
;------------------------------------------------------------------------------
emit_float_var_scale:
	lea	$c(a0),a0                       ; skip constant and operator
	bmi.s	emit_float_var_scale_down       ; n negative: divide by 2^-n instead
	cmpi.w	#$7f,d6                         ; n above 127: needs move.w
	bhi.s	.n_as_word
	tst.b	d6                              ; n = 0: times 1
	beq.s	.times_one
	cmpi.b	#$1,d6                          ; n = 1: VDOUBLE
	beq.s	.times_two
	move.b	#$76,(a1)+                      ; $76 = moveq #n,d3
	move.b	d6,(a1)+                        ; n
.call_mul2p:
	move.w	#$239,d0                        ; VMUL2P
	bra.w	emit_library_call               ; emit jsr VMUL2P (a0 = variable, d3 = n)
.n_as_word:
	move.w	#$363c,(a1)+                    ; $363c = move.w #imm,d3
	move.w	d6,(a1)+                        ; n
	bra.s	.call_mul2p
.times_two:
	move.w	#$290,d0                        ; VDOUBLE
	bra.w	emit_library_call               ; emit jsr VDOUBLE
.plain_use:
	bra.w	emit_use_float_var_at_a0
.times_one:
	tst.w	d0                              ; times 1: plain use; times -1: load and neg.w d2
	bpl.s	.plain_use
	move.w	#$2018,(a1)+                    ; $2018 = move.l (a0)+,d0
	move.w	#$3218,(a1)+                    ; $3218 = move.w (a0)+,d1
	move.w	#$3418,(a1)+                    ; $3418 = move.w (a0)+,d2; caller adds neg.w d2
	rts

;------------------------------------------------------------------------------
; Float variable divided by the constant 2^n.
;------------------------------------------------------------------------------
gen_float_var_divide_power_of_two:
	bsr.w	emit_float_var_address_a0       ; lea var(a5),a0
	move.w	d1,d0                           ; d0 = signed exponent (sign of the constant)
	bpl.s	emit_float_var_over_power_of_two ; positive constant
	neg.w	d1                              ; exponent without the sign bit
	bsr.s	emit_float_var_over_power_of_two ; emit the division by 2^n
	move.w	#$4442,(a1)+                    ; $4442 = neg.w d2: negative constant
	rts

;------------------------------------------------------------------------------
; d6 = $3ff - d1 (minus the power), then emit_float_var_scale.
;------------------------------------------------------------------------------
emit_float_var_over_power_of_two:
	move.w	#$3ff,d6                        ; 1.0 has exponent $3ff
	sub.w	d1,d6                           ; d6 = $3ff - exponent = -n (negative: scale down)
	bra.s	emit_float_var_scale

;------------------------------------------------------------------------------
; Emits the scaling by 2^-n: moveq/move.w #n,d3 and VDIV2P, VHALF for n = 1.
;------------------------------------------------------------------------------
emit_float_var_scale_down:
	neg.w	d6                              ; d6 = n
	cmpi.w	#$7f,d6                         ; n above 127: needs move.w
	bhi.s	.count_as_word
	cmpi.b	#$1,d6                          ; n = 1: VHALF
	beq.s	.halve
	move.b	#$76,(a1)+                      ; $76 = moveq #n,d3
	move.b	d6,(a1)+                        ; n
.call_div2p:
	move.w	#$23a,d0                        ; VDIV2P
	bra.w	emit_library_call               ; emit jsr VDIV2P (a0 = variable, d3 = n)
.count_as_word:
	move.w	#$363c,(a1)+                    ; $363c = move.w #imm,d3
	move.w	d6,(a1)+                        ; n
	bra.s	.call_div2p
.halve:
	move.w	#$292,d0                        ; VHALF
	bra.w	emit_library_call               ; emit jsr VHALF

;------------------------------------------------------------------------------
; IR $805d: a float variable as the second operand.  Its address goes into a0; when the operator that
; follows is in float_var_second_routine_table its routine is called directly; otherwise loads it into d3-d5
; (move.l (a0)+,d3 / move.w (a0)+,d4 / move.w (a0)+,d5).
;------------------------------------------------------------------------------
gen_load_float_var_second:
	bsr.w	emit_float_var_address_a0       ; lea var(a5),a0; a0 past the index
	move.w	(a0),d1                         ; d1 = the operator that follows
	lea	float_var_second_routine_table(pc),a2 ; operators, then their routines
	moveq	#21,d0                          ; dbeq count: 22 entries
.find_operator:
	cmp.w	(a2)+,d1                        ; is d1 one of them?
	dbeq	d0,.find_operator               ; until found or all 22 tried
	bne.s	.load_into_d3_d5                ; not found: load into d3-d5
	move.w	$2a(a2),d0                      ; routine number 22 words on (a2 is one past the match)
	addq.l	#2,a0                           ; skip the operator
	bra.w	emit_library_call               ; emit jsr to it
.load_into_d3_d5:
	move.w	#$2618,(a1)+                    ; $2618 = move.l (a0)+,d3
	move.w	#$3818,(a1)+                    ; $3818 = move.w (a0)+,d4
	move.w	#$3a18,(a1)+                    ; $3a18 = move.w (a0)+,d5
	rts

; 22 operator codes (IR codes and the FIV_ routines) followed by 22 library routine numbers: the routine for
; the float in d0-d2 and the float variable at a0 (VFADD VFSUB VFXSUB VFMUL VFDIV VFXDIV VFEQ VFNE VFGE VFGT
; VFLE VFLT VFMOD VFXMOD VFIDIV VFXIDIV FIV_ADD FIV_SUB FIV_MUL FIV_DIV VFMIN VFMAX).
float_var_second_routine_table:
	dc.w	$804a,$804b,$804c,$804d,$804e,$804f,$805a,$805b
	dc.w	$8057,$8056,$8059,$8058,$8052,$8053,$8050,$8051
	dc.w	$01fa,$01fb,$01f9,$01f8,$812a,$812b,$0030,$0033
	dc.w	$00d6,$0032,$0031,$00d7,$00d8,$00d9,$00da,$00db
	dc.w	$00dc,$00dd,$00de,$00df,$00e0,$00e1,$01fa,$01fb
	dc.w	$01f9,$01f8,$0335,$0337

;------------------------------------------------------------------------------
; IR $8096: store the byte d0 at (a0): move.b d0,(a0) (trailing ext.l / ext.w dropped).
;------------------------------------------------------------------------------
gen_store_byte_at_a0:
	bsr.w	drop_trailing_ext_long          ; drop an ext.l d0 just emitted
	bsr.w	drop_trailing_ext_word          ; and an ext.w d0
	move.w	#$1080,(a1)+                    ; $1080 = move.b d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8097: store the word d0 at (a0): move.w d0,(a0).
;------------------------------------------------------------------------------
gen_store_word_at_a0:
	bsr.w	drop_trailing_ext_long          ; drop an ext.l d0 just emitted
	move.w	#$3080,(a1)+                    ; $3080 = move.w d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8098: store the long d0 at (a0): move.l d0,(a0).
;------------------------------------------------------------------------------
gen_store_long_at_a0:
	move.w	#$2080,(a1)+                    ; $2080 = move.l d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8035: move.b d0,n(a0), offset n from the IR.
;------------------------------------------------------------------------------
gen_store_byte_at_a0_offset:
	bsr.w	drop_trailing_ext_long          ; drop an ext.l d0 just emitted
	bsr.w	drop_trailing_ext_word          ; and an ext.w d0
	move.w	#$1140,(a1)+                    ; $1140 = move.b d0,d16(a0)
	move.w	(a0)+,(a1)+                     ; offset from the IR
	rts

;------------------------------------------------------------------------------
; IR $8036: move.w d0,n(a0).
;------------------------------------------------------------------------------
gen_store_word_at_a0_offset:
	bsr.w	drop_trailing_ext_long          ; drop an ext.l d0 just emitted
	move.w	#$3140,(a1)+                    ; $3140 = move.w d0,d16(a0)
	move.w	(a0)+,(a1)+                     ; offset from the IR
	rts

;------------------------------------------------------------------------------
; IR $8037: move.l d0,n(a0).
;------------------------------------------------------------------------------
gen_store_long_at_a0_offset:
	move.w	#$2140,(a1)+                    ; $2140 = move.l d0,d16(a0)
	move.w	(a0)+,(a1)+                     ; offset from the IR
	rts

;------------------------------------------------------------------------------
; Reads a variable index from the IR ((a0)+) and returns its entry in the integer variable table
; (var_1184e, 4 bytes per variable): d0 = the entry (low word = offset from a5), d7 = its high word; N set when
; the variable is reached through a pointer.
;------------------------------------------------------------------------------
lookup_integer_var:
	move.w	(a0)+,d0                        ; variable index
	movea.w	d0,a2                           ; index as a long
	adda.l	a2,a2                           ; 4 bytes per variable
	adda.l	a2,a2
	adda.l	int_variable_table(pc),a2       ; plus the table base
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	rts

;------------------------------------------------------------------------------
; As lookup_integer_var for the word variable table var_11866.
;------------------------------------------------------------------------------
lookup_word_var:
	move.w	(a0)+,d0                        ; variable index
	movea.w	d0,a2                           ; index as a long
	adda.l	a2,a2                           ; 4 bytes per variable
	adda.l	a2,a2
	adda.l	word_variable_table(pc),a2      ; plus the table base
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	rts

;------------------------------------------------------------------------------
; As lookup_integer_var for the float variable table var_11846.
;------------------------------------------------------------------------------
lookup_float_var:
	move.w	(a0)+,d0                        ; variable index
	movea.w	d0,a2                           ; index as a long
	adda.l	a2,a2
	adda.l	a2,a2                           ; 4 bytes per variable
	adda.l	float_variable_table(pc),a2     ; plus the table base
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	rts

;------------------------------------------------------------------------------
; As lookup_integer_var for the string variable table var_1184a.
;------------------------------------------------------------------------------
lookup_string_var:
	move.w	(a0)+,d0                        ; variable index
	movea.w	d0,a2                           ; index as a long
	adda.l	a2,a2
	adda.l	a2,a2                           ; 4 bytes per variable
	adda.l	string_variable_table(pc),a2    ; plus the table base
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	rts

;------------------------------------------------------------------------------
; As lookup_integer_var for the byte variable table var_1186a.
;------------------------------------------------------------------------------
lookup_byte_var:
	move.w	(a0)+,d0                        ; variable index
	movea.w	d0,a2                           ; index as a long
	adda.l	a2,a2
	adda.l	a2,a2                           ; 4 bytes per variable
	adda.l	byte_variable_table(pc),a2      ; plus the table base
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	rts

;------------------------------------------------------------------------------
; As lookup_integer_var for the boolean variable table var_11852.
;------------------------------------------------------------------------------
lookup_bool_var:
	move.w	(a0)+,d0                        ; variable index
	movea.w	d0,a2                           ; index as a long
	adda.l	a2,a2                           ; 4 bytes per variable
	adda.l	a2,a2                           ; 4 bytes per variable
	adda.l	bool_variable_table(pc),a2      ; plus the table base
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	rts

;------------------------------------------------------------------------------
; IR $80a3: byte at address d0 (movea.l d0,a0, then gen_peek_byte_at_a0).
;------------------------------------------------------------------------------
gen_peek_byte:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80ab: byte at (a0) into d0, zero-extended (moveq #0,d0 / move.b (a0),d0); only move.b before a jump.
;------------------------------------------------------------------------------
gen_peek_byte_at_a0:
	move.w	(a0),d0                         ; d0 = the IR that uses the byte
	cmpi.w	#$80bf,d0                       ; $80bf jump if false
	beq.s	.move_byte
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.s	.move_byte
	move.w	#$7000,(a1)+                    ; $7000 = moveq #0,d0
.move_byte:
	move.w	#$1010,(a1)+                    ; $1010 = move.b (a0),d0
	rts

;------------------------------------------------------------------------------
; IR $80a4: word at address d0, sign-extended.
;------------------------------------------------------------------------------
gen_peek_word_signed:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80ac: move.w (a0),d0, ext.l when needed (not before a jump).
;------------------------------------------------------------------------------
gen_peek_word_signed_at_a0:
	move.w	#$3010,(a1)+                    ; $3010 = move.w (a0),d0
	move.w	(a0),d0                         ; d0 = the IR that uses the word
	cmpi.w	#$80bf,d0                       ; $80bf jump if false: no ext.l
	beq.s	.done
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.s	.done
	bra.w	gen_sign_extend_word            ; ext.l d0 when needed
.done:
	rts

;------------------------------------------------------------------------------
; IR $80a5: word at address d0, zero-extended.
;------------------------------------------------------------------------------
gen_peek_word:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80ad: moveq #0,d0 / move.w (a0),d0 (only move.w before a jump).
;------------------------------------------------------------------------------
gen_peek_word_at_a0:
	move.w	(a0),d0                         ; d0 = the IR that uses the word
	cmpi.w	#$80bf,d0                       ; $80bf jump if false
	beq.s	.move_word
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.s	.move_word
	move.w	#$7000,(a1)+                    ; $7000 = moveq #0,d0
.move_word:
	move.w	#$3010,(a1)+                    ; $3010 = move.w (a0),d0
	rts

;------------------------------------------------------------------------------
; IR $80a6: long at address d0.
;------------------------------------------------------------------------------
gen_peek_long:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80ae: movea.l (a0),a0; when another read follows ($80a3-$80aa) it uses this a0 (chained reads),
; when $8017 follows it becomes move.l (a0),-(sp), otherwise move.l (a0),d0.
;------------------------------------------------------------------------------
gen_peek_long_at_a0:
	move.w	#$2050,(a1)+                    ; $2050 = movea.l (a0),a0
	cmpi.w	#$8017,(a0)                     ; $8017 push long follows?
	bne.s	.check_chained_read
	addq.l	#2,a0                           ; skip the $8017
	move.w	#$2f10,-$2(a1)                  ; becomes $2f10 = move.l (a0),-(sp)
	rts
.check_chained_read:
	move.w	(a0)+,d0                        ; d0 = the IR that follows
	cmpi.w	#$80a6,d0                       ; $80a6 long read through this a0
	beq.s	gen_peek_long_at_a0
	cmpi.w	#$80aa,d0                       ; $80aa long read with offset
	beq.w	gen_peek_long_offset_at_a0
	cmpi.w	#$80a4,d0                       ; $80a4 signed word read
	beq.s	gen_peek_word_signed_at_a0
	cmpi.w	#$80a8,d0                       ; $80a8 signed word read with offset
	beq.s	gen_peek_word_signed_offset_at_a0
	cmpi.w	#$80a3,d0                       ; $80a3 byte read
	beq.w	gen_peek_byte_at_a0
	cmpi.w	#$80a7,d0                       ; $80a7 byte read with offset
	beq.s	gen_peek_byte_offset_at_a0
	subq.l	#2,a0                           ; none: back to that IR word
	move.w	#$2010,-$2(a1)                  ; becomes $2010 = move.l (a0),d0
	rts

;------------------------------------------------------------------------------
; IR $80a7: byte at address d0 + offset (IR operand).
;------------------------------------------------------------------------------
gen_peek_byte_offset:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80af: moveq #0,d0 / move.b n(a0),d0.
;------------------------------------------------------------------------------
gen_peek_byte_offset_at_a0:
	move.w	2(a0),d0                        ; d0 = the IR after the offset
	cmpi.w	#$80bf,d0                       ; $80bf jump if false: no moveq #0
	beq.s	.move_byte
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.s	.move_byte
	move.w	#$7000,(a1)+                    ; $7000 = moveq #0,d0
.move_byte:
	move.w	#$1028,(a1)+                    ; $1028 = move.b d16(a0),d0
	move.w	(a0)+,(a1)+                     ; offset from the IR
	rts

;------------------------------------------------------------------------------
; IR $80a8: word at address d0 + offset, sign-extended.
;------------------------------------------------------------------------------
gen_peek_word_signed_offset:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80b0: move.w n(a0),d0, ext.l when needed.
;------------------------------------------------------------------------------
gen_peek_word_signed_offset_at_a0:
	move.w	#$3028,(a1)+                    ; $3028 = move.w d16(a0),d0
	move.w	(a0)+,(a1)+                     ; offset from the IR
	move.w	(a0),d0                         ; d0 = the IR that uses the word
	cmpi.w	#$80bf,d0                       ; $80bf jump if false: no ext.l
	beq.s	.done
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.s	.done
	bra.w	gen_sign_extend_word            ; ext.l d0 when needed
.done:
	rts

;------------------------------------------------------------------------------
; IR $80a9: word at address d0 + offset, zero-extended.
;------------------------------------------------------------------------------
gen_peek_word_offset:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80b1: moveq #0,d0 / move.w n(a0),d0.
;------------------------------------------------------------------------------
gen_peek_word_offset_at_a0:
	move.w	2(a0),d0                        ; d0 = the IR after the offset
	cmpi.w	#$80bf,d0                       ; $80bf jump if false: no moveq #0
	beq.s	.move_word
	cmpi.w	#$80c0,d0                       ; $80c0 jump if true
	beq.s	.move_word
	move.w	#$7000,(a1)+                    ; $7000 = moveq #0,d0
.move_word:
	move.w	#$3028,(a1)+                    ; $3028 = move.w d16(a0),d0
	move.w	(a0)+,(a1)+                     ; offset from the IR
	rts

;------------------------------------------------------------------------------
; IR $80aa: long at address d0 + offset.
;------------------------------------------------------------------------------
gen_peek_long_offset:
	move.w	#$2040,(a1)+                    ; $2040 = movea.l d0,a0

;------------------------------------------------------------------------------
; IR $80b2: move.l n(a0),d0, or move.l n(a0),-(sp) when $8017 follows.
;------------------------------------------------------------------------------
gen_peek_long_offset_at_a0:
	move.w	#$2028,(a1)+                    ; $2028 = move.l d16(a0),d0
	move.w	(a0)+,(a1)+                     ; offset from the IR
	cmpi.w	#$8017,(a0)                     ; $8017 push long follows?
	bne.s	.done
	addq.l	#2,a0                           ; skip the $8017
	move.w	#$2f28,-$4(a1)                  ; becomes $2f28 = move.l d16(a0),-(sp)
.done:
	rts

;------------------------------------------------------------------------------
; IR $80a2: call library routine CHARK.
;------------------------------------------------------------------------------
gen_chark:
	move.w	#$112,d0                        ; CHARK
	bra.s	emit_library_call

;------------------------------------------------------------------------------
; Array table lookups: reads an array index and a second word (d1) from the IR and returns the entry in
; the integer array table var_1185e (d0, d7 = high word, N = through a pointer).
;------------------------------------------------------------------------------
lookup_integer_array:
	movea.l	int_array_table(pc),a2          ; a2 = integer array table
	bra.s	lookup_array_entry

;------------------------------------------------------------------------------
; As lookup_integer_array for the word array table var_11876.
;------------------------------------------------------------------------------
lookup_word_array:
	movea.l	word_array_table(pc),a2         ; a2 = word array table
	bra.s	lookup_array_entry

;------------------------------------------------------------------------------
; As lookup_integer_array for the byte array table var_1187a.
;------------------------------------------------------------------------------
lookup_byte_array:
	movea.l	byte_array_table(pc),a2         ; a2 = byte array table
	bra.s	lookup_array_entry

;------------------------------------------------------------------------------
; As lookup_integer_array for the boolean array table var_11862.
;------------------------------------------------------------------------------
lookup_bool_array:
	movea.l	bool_array_table(pc),a2         ; a2 = boolean array table
	bra.s	lookup_array_entry

;------------------------------------------------------------------------------
; As lookup_integer_array for the string array table var_1185a.
;------------------------------------------------------------------------------
lookup_string_array:
	movea.l	string_array_table(pc),a2       ; a2 = string array table
	bra.s	lookup_array_entry

;------------------------------------------------------------------------------
; As lookup_integer_array for the float array table var_11856.
;------------------------------------------------------------------------------
lookup_float_array:
	movea.l	float_array_table(pc),a2        ; a2 = float array table

;------------------------------------------------------------------------------
; a2 = array table: d0 = index, d1 = second IR word; returns d0 = entry, d7 = its high word.
;------------------------------------------------------------------------------
lookup_array_entry:
	move.w	(a0)+,d0                        ; array index
	move.w	(a0)+,d1                        ; second operand word
	asl.w	#2,d0                           ; 4 bytes per array
	adda.w	d0,a2                           ; a2 = the entry
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	rts

;------------------------------------------------------------------------------
; Emits a call of library routine d0 as the two words $6101 (bsr.s marker) and the routine number, or
; $6001 (bra.s marker) for RETURN and RETSTR, which do not come back.  The routine number is kept in
; last_library_routine (the linker turns the pair into the real call).  Also the codegen for every positive IR word.
;------------------------------------------------------------------------------
emit_library_call:
	move.w	d0,last_library_routine         ; remember the routine
	cmpi.w	#$27a,d0                        ; RETURN
	beq.s	.no_return_routine
	cmpi.w	#$294,d0                        ; RETSTR
	beq.s	.no_return_routine
	move.w	#$6101,(a1)+                    ; $6101 = bsr.s marker
	move.w	d0,(a1)+                        ; routine number for the linker
	rts
.no_return_routine:
	move.w	#$6001,(a1)+                    ; $6001 = bra.s marker
	move.w	d0,(a1)+                        ; routine number for the linker
	rts
	btst	d0,d0                           ; unreferenced word $0100

;------------------------------------------------------------------------------
; IR $8005: float in d0-d2 to integer (FFTOI).
;------------------------------------------------------------------------------
gen_float_to_integer:
	moveq	#6,d0                           ; FFTOI
	bra.s	emit_library_call

;------------------------------------------------------------------------------
; IR $8006: integer d0 to float (FITOF).  Followed by $8041: ISTOF into the variable.  Followed by a
; float constant ($8001) and add/sub/mul/div: the operator becomes FI_ADD/FI_SUB/FI_MUL/FI_DIV; followed by a
; float variable ($805d) and an operator: FIV_ADD/FIV_SUB/FIV_MUL/FIV_DIV.  The conversion itself is then
; left out.
;------------------------------------------------------------------------------
gen_integer_to_float:
	cmpi.w	#$8041,(a0)                     ; $8041 store follows
	bne.s	.check_constant_operation       ; no: check for a float operation
	addq.l	#2,a0                           ; skip the $8041
	bra.w	gen_store_integer_as_float_var  ; ISTOF: integer stored straight into the float variable
.check_constant_operation:
	cmpi.w	#$8001,(a0)                     ; $8001 float constant follows
	bne.s	.check_variable_operation       ; no: check for a float variable
	move.w	$a(a0),d0                       ; its operator
	cmpi.w	#$804a,d0                       ; $804a FADD
	beq.s	.constant_add
	cmpi.w	#$804b,d0                       ; $804b FSUB
	beq.s	.constant_sub
	cmpi.w	#$804d,d0                       ; $804d FMUL
	beq.s	.constant_mul
	cmpi.w	#$804e,d0                       ; $804e FDIV
	beq.s	.constant_div
.check_variable_operation:
	cmpi.w	#$805d,(a0)                     ; $805d float variable follows
	beq.s	.variable_operation
.convert_to_float:
	moveq	#7,d0                           ; FITOF
	bra.s	emit_library_call
.constant_add:
	move.w	#$1f6,d0                        ; FI_ADD
	bra.s	.replace_constant_operator
.constant_sub:
	move.w	#$1f7,d0                        ; FI_SUB
	bra.s	.replace_constant_operator
.constant_mul:
	move.w	#$1f5,d0                        ; FI_MUL
	bra.s	.replace_constant_operator
.constant_div:
	move.w	#$1f4,d0                        ; FI_DIV
.replace_constant_operator:
	move.w	d0,$a(a0)                       ; replaces the operator; no conversion emitted
	rts
.variable_operation:
	move.w	4(a0),d0                        ; d0 = the operator after $805d var
	cmpi.w	#$804a,d0                       ; $804a FADD
	beq.s	.variable_add
	cmpi.w	#$804b,d0                       ; $804b FSUB
	beq.s	.variable_sub
	cmpi.w	#$804d,d0                       ; $804d FMUL
	beq.s	.variable_mul
	cmpi.w	#$804e,d0                       ; $804e FDIV
	beq.s	.variable_div
	bra.s	.convert_to_float               ; other operators: convert with FITOF
.variable_add:
	move.w	#$1fa,d0                        ; FIV_ADD
	bra.s	.replace_variable_operator
.variable_sub:
	move.w	#$1fb,d0                        ; FIV_SUB
	bra.s	.replace_variable_operator
.variable_mul:
	move.w	#$1f9,d0                        ; FIV_MUL
	bra.s	.replace_variable_operator
.variable_div:
	move.w	#$1f8,d0                        ; FIV_DIV
.replace_variable_operator:
	move.w	d0,4(a0)                        ; replaces the operator; no conversion emitted
	rts

gen_float_add:
	moveq	#8,d0                           ; FADD
	bra.w	emit_library_call

gen_float_sub:
	moveq	#27,d0                          ; FSUB
	bra.w	emit_library_call

gen_float_reverse_sub:
	moveq	#33,d0                          ; FXSUB
	bra.w	emit_library_call

gen_float_square:
	moveq	#26,d0                          ; FSQUARE
	bra.w	emit_library_call

gen_integer_square:
	moveq	#34,d0                          ; ISQUARE
	bra.w	emit_library_call

gen_float_mul:
	moveq	#21,d0                          ; FMUL
	bra.w	emit_library_call

gen_float_div:
	moveq	#10,d0                          ; FDIV
	bra.w	emit_library_call

gen_float_mod:
	moveq	#20,d0                          ; FMOD
	bra.w	emit_library_call

gen_float_integer_div:
	moveq	#17,d0                          ; FIDIV
	bra.w	emit_library_call

gen_float_reverse_div:
	moveq	#29,d0                          ; FXDIV
	bra.w	emit_library_call

gen_float_reverse_mod:
	moveq	#31,d0                          ; FXMOD
