;------------------------------------------------------------------------------
; IR $805e: integer multiply.  muls.w d1,d0 (dropping trailing ext.l d0 / ext.l d1) when the result is
; stored as a word or byte or the $*& option (option_star_flag) is set; otherwise LMUL.
;------------------------------------------------------------------------------
gen_integer_multiply:
	cmpi.w	#$8043,(a0)                     ; store as word
	beq.s	gen_ir_814e_multiply_word
	cmpi.w	#$8044,(a0)                     ; store as byte
	beq.s	gen_ir_814e_multiply_word
	tst.b	option_star_flag                ; option $*&: integer multiply as muls.w
	bne.s	gen_ir_814e_multiply_word
	moveq	#38,d0                          ; LMUL
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $814e: word multiply.  Drops a trailing ext.l d0 (drop_trailing_ext_long) and a trailing ext.l d1 when it is
; the one recorded in ext_l_d1_code_address, then emits muls.w d1,d0.  Also the muls.w path of
; gen_integer_multiply.
;------------------------------------------------------------------------------
gen_ir_814e_multiply_word:
	bsr.w	drop_trailing_ext_long          ; IR $814e entry (word multiply): drops trailing ext.l d0 and ext.l d1
	cmpi.w	#$48c1,-(a1)                    ; ext.l d1 just before?
	bne.s	.keep_last_word                 ; no: keep the word
	cmpa.l	ext_l_d1_code_address(pc),a1    ; the one recorded by the d1 load?
	beq.s	.emit_muls                      ; yes: overwrite it
.keep_last_word:
	addq.l	#2,a1                           ; keep the ext.l
.emit_muls:
	move.w	#$c1c1,(a1)+                    ; $c1c1 = muls.w d1,d0
	rts

;------------------------------------------------------------------------------
; IR $805f: integer divide.  divs.w d1,d0 in place of a trailing ext.l d1 when the result is used as a word
; ($80e0-$80e3, $8043); otherwise LDIV.
;------------------------------------------------------------------------------
gen_integer_divide:
	cmpi.w	#$48c1,-(a1)                    ; $48c1 = ext.l d1, the recorded one?
	bne.s	.long_divide                    ; no: LDIV
	cmpa.l	ext_l_d1_code_address(pc),a1    ; the one recorded by the d1 load?
	bne.s	.long_divide
	cmpi.w	#$80e0,(a0)                     ; $80e0 word variable add
	beq.s	.word_divide
	cmpi.w	#$80e1,(a0)                     ; $80e1 word variable sub
	beq.s	.word_divide
	cmpi.w	#$80e2,(a0)                     ; $80e2 word variable mul
	beq.s	.word_divide
	cmpi.w	#$80e3,(a0)                     ; $80e3 word variable div
	beq.s	.word_divide
	cmpi.w	#$8043,(a0)                     ; $8043 store word variable
	bne.s	.long_divide
.word_divide:
	move.w	#$81c1,(a1)+                    ; $81c1 = divs.w d1,d0 over the ext.l
	clr.l	ext_l_d1_code_address           ; the ext.l is gone
	rts
.long_divide:
	addq.l	#2,a1                           ; keep the last word
	moveq	#35,d0                          ; LDIV
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8065: integer MOD (LMOD).
