;------------------------------------------------------------------------------
; IR $80dc: add.l d0,integer variable.
;------------------------------------------------------------------------------
gen_integer_var_add:
	move.w	#$d1ad,d1                       ; $d1ad = add.l d0,d16(a5)
	bra.w	emit_op_integer_var

;------------------------------------------------------------------------------
; IR $80dd: sub.l d0,integer variable.
;------------------------------------------------------------------------------
gen_integer_var_sub:
	move.w	#$91ad,d1                       ; $91ad = sub.l d0,d16(a5)
	bra.w	emit_op_integer_var

gen_integer_var_decrement:
	moveq	#-1,d0                          ; IR $80d5: minus 1
	bra.s	gen_integer_var_add_constant

gen_integer_var_increment:
	moveq	#1,d0                           ; IR $80d1: plus 1
	bra.s	gen_integer_var_add_constant

gen_integer_var_sub_constant:
	neg.l	d0                              ; IR $8007 then $80dd: minus the constant

;------------------------------------------------------------------------------
; Integer variable plus the constant d0 (IR $8007 then $80dc): nothing for 0, addq.l / subq.l for 1..8 /
; -8..-1, moveq + add.l d0,var for a byte, addi.l #n,var otherwise (the immediate is put before the
; variable's offset word).
;------------------------------------------------------------------------------
gen_integer_var_add_constant:
	move.l	d0,d1                           ; d1 = constant (for the quick forms)
	beq.s	.add_nothing                    ; 0: nothing to add
	cmpi.l	#$8,d0                          ; 1..8 (unsigned): addq.l
	bls.s	.addq
	cmpi.l	#$fffffff8,d0                   ; -8..-1: subq.l
	bcc.s	.subq
	ext.w	d1                              ; fits a moveq?
	ext.l	d1
	cmp.l	d0,d1                           ; same value as a sign-extended byte?
	bne.s	.addi                           ; no: addi.l #n
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d0,(a1)+                        ; n
	bra.s	gen_integer_var_add             ; then add.l d0,var
.addq:
	andi.w	#$7,d1                          ; 8 encodes as 0
	ror.w	#7,d1                           ; count to bits 9-11
	ori.w	#$50ad,d1                       ; $50ad = addq.l #n,d16(a5)
	bra.w	emit_op_integer_var
.add_nothing:
	addq.l	#2,a0                           ; 0: skip the variable
	rts
.subq:
	neg.w	d1                              ; d1 = 1..8
	andi.w	#$7,d1                          ; 8 encodes as 0
	ror.w	#7,d1                           ; count to bits 9-11
	ori.w	#$51ad,d1                       ; $51ad = subq.l #n,d16(a5)
	bra.w	emit_op_integer_var
.addi:
	move.l	d0,-(sp)                        ; keep the constant
	move.w	#$6ad,d1                        ; $06ad = addi.l #imm,d16(a5)
	bsr.w	emit_op_integer_var             ; emits opcode and offset (or movea.l + (a2) form)
	cmpi.w	#$6ad,d1                        ; not changed to (a2)?
	bne.s	.addi_through_pointer
	move.w	-(a1),d0                        ; put the immediate before the offset word
	move.l	(sp)+,(a1)+                     ; the immediate long
	move.w	d0,(a1)+                        ; then the offset
	rts
.addi_through_pointer:
	move.l	(sp)+,(a1)+                     ; (a2) form: immediate straight after the opcode
	rts

;------------------------------------------------------------------------------
; IR $80de: integer variable times d0: address into a0, move.l (a0),d1, the multiply, move.l d0,(a0).
;------------------------------------------------------------------------------
gen_integer_var_mul:
	bsr.w	emit_integer_var_address_a0     ; lea var(a5),a0 / movea.l var(a5),a0
	move.w	#$2210,(a1)+                    ; $2210 = move.l (a0),d1
	bsr.w	gen_integer_multiply            ; emit muls.w d1,d0 or LMUL
	move.w	#$2080,(a1)+                    ; $2080 = move.l d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8007 then $80de: integer variable times a constant (emit_mul_int_constant).
;------------------------------------------------------------------------------
gen_integer_var_mul_constant:
	move.l	d0,-(sp)                        ; keep the constant
	bsr.w	emit_integer_var_address_a0     ; lea var(a5),a0 / movea.l var(a5),a0
	move.w	#$2010,(a1)+                    ; $2010 = move.l (a0),d0
	move.l	(sp)+,d0                        ; d0 = the constant again
	bsr.w	emit_mul_int_constant           ; emit d0 times the constant
	move.w	#$2080,(a1)+                    ; $2080 = move.l d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $80df: integer variable divided by d0: move.l (a0),d1, XLDIV, move.l d0,(a0).
;------------------------------------------------------------------------------
gen_integer_var_div:
	bsr.w	emit_integer_var_address_a0     ; lea var(a5),a0 / movea.l var(a5),a0
	move.w	#$2210,(a1)+                    ; $2210 = move.l (a0),d1
	move.w	#$38,d0                         ; XLDIV
	bsr.w	emit_library_call               ; emit jsr XLDIV (d1 / d0)
	move.w	#$2080,(a1)+                    ; $2080 = move.l d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8007 then $80df: integer variable divided by a constant (emit_div_int_constant).
;------------------------------------------------------------------------------
gen_integer_var_div_constant:
	move.l	d0,-(sp)                        ; keep the constant
	bsr.w	emit_integer_var_address_a0     ; lea var(a5),a0 / movea.l var(a5),a0
	move.w	#$2010,(a1)+                    ; $2010 = move.l (a0),d0
	move.l	(sp)+,d0                        ; d0 = the constant again
	bsr.w	emit_div_int_constant           ; emit d0 divided by the constant
	move.w	#$2080,(a1)+                    ; $2080 = move.l d0,(a0)
	rts

gen_word_var_add:
	move.w	#$d16d,d1                       ; $d16d = add.w d0,d16(a5)
	bra.w	emit_op_word_var

gen_word_var_sub:
	move.w	#$916d,d1                       ; $916d = sub.w d0,d16(a5)
	bra.w	emit_op_word_var

gen_word_var_decrement:
	moveq	#-1,d0                          ; IR $80d6: minus 1
	bra.s	gen_word_var_add_constant

gen_word_var_increment:
	moveq	#1,d0                           ; IR $80d2: plus 1
	bra.s	gen_word_var_add_constant

gen_word_var_sub_constant:
	neg.l	d0                              ; IR $8007 then $80e1: minus the constant

;------------------------------------------------------------------------------
; Word variable plus the constant d0: nothing, addq.w / subq.w, or addi.w #n,var.
;------------------------------------------------------------------------------
gen_word_var_add_constant:
	move.w	d0,d1                           ; d1 = constant (for the quick forms)
	beq.s	.add_nothing                    ; 0: nothing to add
	cmpi.w	#$8,d0                          ; 1..8 (unsigned): addq.w
	bls.s	.addq
	cmpi.w	#$fff8,d0                       ; -8..-1: subq.w
	bcc.s	.subq
	move.w	d0,-(sp)                        ; keep the constant
	move.w	#$66d,d1                        ; $066d = addi.w #imm,d16(a5)
	bsr.w	emit_op_word_var                ; emits opcode and offset (or movea.l + (a2) form)
	cmpi.w	#$66d,d1                        ; still the d16(a5) form?
	bne.s	.addi_through_pointer
	move.w	-(a1),d0                        ; d0 = the offset word
	move.w	(sp)+,(a1)+                     ; the immediate word
	move.w	d0,(a1)+                        ; then the offset
	rts
.addi_through_pointer:
	move.w	(sp)+,(a1)+                     ; (a2) form: immediate straight after the opcode
	rts
.addq:
	andi.w	#$7,d1                          ; 8 encodes as 0
	ror.w	#7,d1                           ; count to bits 9-11
	ori.w	#$506d,d1                       ; $506d = addq.w #n,d16(a5)
	bra.w	emit_op_word_var
.add_nothing:
	addq.l	#2,a0                           ; skip the variable index
	rts
.subq:
	neg.w	d1                              ; d1 = 1..8
	andi.w	#$7,d1                          ; 8 encodes as 0
	ror.w	#7,d1                           ; count to bits 9-11
	ori.w	#$516d,d1                       ; $516d = subq.w #n,d16(a5)
	bra.w	emit_op_word_var

;------------------------------------------------------------------------------
; IR $80e2: word variable times d0: muls.w var,d0, then stores d0 back (gen_store_word_var).
;------------------------------------------------------------------------------
gen_word_var_mul:
	move.w	#$c1ed,d1                       ; $c1ed = muls.w d16(a5),d0
	bsr.w	emit_op_word_var                ; emits opcode and offset; a0 past the index
	subq.l	#2,a0                           ; back to the variable for the store
	bra.w	gen_store_word_var

;------------------------------------------------------------------------------
; Word variable times the constant d0.w: clr.w var for 0, nothing for 1, asl.w var for 2, a load and
; asl.w #n,d0 and a store for another power of two, otherwise moveq/move.w #n,d0 / muls.w var,d0 / store.
; For 256 two asl.w #8 are emitted (looks wrong).
;------------------------------------------------------------------------------
gen_word_var_mul_constant:
	move.w	d0,-(sp)                        ; keep the constant
	beq.s	.times_zero                     ; 0: clr.w var
	moveq	#16,d1                          ; find the highest set bit
.find_top_bit:
	subq.w	#1,d1                           ; d1 = bit number of the bit shifted out
	add.w	d0,d0                           ; top bit into carry
	bcc.s	.find_top_bit                   ; not yet: next bit
	bne.s	.not_a_power_of_two             ; more bits: not a power of two
	tst.w	d1                              ; n = 0: times 1
	beq.s	.times_one
	cmpi.w	#$1,d1                          ; n = 1: asl.w var
	beq.s	.times_two
	move.w	d1,(sp)                         ; keep n
	moveq	#0,d1                           ; register d0
	bsr.w	emit_load_word_var_reg          ; move.w var,d0
	move.w	(sp)+,d1                        ; d1 = n
	subq.w	#8,d1                           ; n of 8 or more: asl.w #8 first
	bmi.s	.emit_asl                       ; below 8
	move.w	#$e140,(a1)+                    ; $e140 = asl.w #8,d0
	subq.w	#8,d1                           ; n - 8 left (8 for 256 becomes 0 = 8 again)
.emit_asl:
	andi.w	#$7,d1                          ; 8 encodes as 0
	ror.w	#7,d1                           ; count to bits 9-11
	ori.w	#$e140,d1                       ; $e140 = asl.w #n,d0
	move.w	d1,(a1)+                        ; the asl.w
	subq.l	#2,a0                           ; back to the variable for the store
	bra.w	gen_store_word_var              ; move.w d0,var
.times_one:
	addq.l	#2,sp                           ; drop the saved constant
	addq.l	#2,a0                           ; skip the variable index
	rts
.times_two:
	addq.l	#2,sp                           ; drop the saved constant
	move.w	#$e1ed,d1                       ; $e1ed = asl.w d16(a5)
	bra.w	emit_op_word_var
.not_a_power_of_two:
	move.w	(sp)+,d0                        ; d0 = the constant
	move.w	d0,d1                           ; fits a moveq?
	ext.w	d1
	cmp.w	d0,d1                           ; same value as a sign-extended byte?
	bne.s	.constant_as_word               ; no: move.w #n,d0
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d0,(a1)+                        ; n
	bra.s	gen_word_var_mul                ; then muls.w var,d0 and the store
.constant_as_word:
	move.w	#$303c,(a1)+                    ; $303c = move.w #imm,d0
	move.w	d0,(a1)+                        ; n
	bra.s	gen_word_var_mul                ; then muls.w var,d0 and the store
.times_zero:
	addq.l	#2,sp                           ; drop the saved constant
	move.w	#$42ed,d1                       ; $42ed = clr.w d16(a5)
	bra.w	emit_op_word_var

;------------------------------------------------------------------------------
; IR $80e3: word variable divided by d0: move.w (a0),d1 / ext.l d1 / divs.w d0,d1 / move.w d1,(a0).
;------------------------------------------------------------------------------
gen_word_var_div:
	bsr.w	emit_word_var_address_a0        ; lea var(a5),a0
	move.w	#$3210,(a1)+                    ; $3210 = move.w (a0),d1
	move.w	#$48c1,(a1)+                    ; $48c1 = ext.l d1
	move.w	#$83c0,(a1)+                    ; $83c0 = divs.w d0,d1
	move.w	#$3081,(a1)+                    ; $3081 = move.w d1,(a0)
	rts

;------------------------------------------------------------------------------
; Word variable divided by a constant: move.w (a0),d0 / ext.l d0 / divs.w #n,d0 / move.w d0,(a0).
;------------------------------------------------------------------------------
gen_word_var_div_constant:
	move.w	d0,-(sp)                        ; keep the constant
	bsr.w	emit_word_var_address_a0        ; a0 = the variable's address
	move.w	#$3010,(a1)+                    ; $3010 = move.w (a0),d0
	move.w	#$48c0,(a1)+                    ; $48c0 = ext.l d0
	move.w	#$81fc,(a1)+                    ; $81fc = divs.w #imm,d0
	move.w	(sp)+,(a1)+                     ; the constant
	move.w	#$3080,(a1)+                    ; $3080 = move.w d0,(a0)
	rts

gen_byte_var_add:
	move.w	#$d12d,d1                       ; $d12d = add.b d0,d16(a5)
	bra.w	emit_op_byte_var

gen_byte_var_sub:
	move.w	#$912d,d1                       ; $912d = sub.b d0,d16(a5)
	bra.w	emit_op_byte_var

gen_byte_var_decrement:
	moveq	#-1,d0                          ; IR $80d7: minus 1
	bra.s	gen_byte_var_add_constant

gen_byte_var_increment:
	moveq	#1,d0                           ; IR $80d3: plus 1
	bra.s	gen_byte_var_add_constant

gen_byte_var_sub_constant:
	neg.l	d0                              ; IR $8007 then $80e5: minus the constant

;------------------------------------------------------------------------------
; Byte variable plus the constant d0.b: nothing, addq.b / subq.b, or addi.b #n,var.
;------------------------------------------------------------------------------
gen_byte_var_add_constant:
	move.b	d0,d1                           ; d1 = constant (for the quick forms)
	beq.s	.add_nothing                    ; 0: nothing to add
	cmpi.b	#$8,d0                          ; 1..8 (unsigned): addq.b
	bls.s	.addq
	dc.w	$0c00,$fff8                     ; cmpi.b	#$f8,d0
	bcc.s	.subq                           ; -8..-1: subq.b
	andi.w	#$ff,d0                         ; immediate word: byte constant in the low byte
	move.w	d0,-(sp)                        ; keep the constant
	move.w	#$62d,d1                        ; $062d = addi.b #imm,d16(a5)
	bsr.w	emit_op_byte_var                ; emits opcode and offset (or movea.l + (a2) form)
	cmpi.w	#$62d,d1                        ; still the d16(a5) form?
	bne.s	.addi_through_pointer
	move.w	-(a1),d0                        ; d0 = the offset word
	move.w	(sp)+,(a1)+                     ; the immediate word
	move.w	d0,(a1)+                        ; then the offset
	rts
.addi_through_pointer:
	move.w	(sp)+,(a1)+                     ; (a2) form: immediate straight after the opcode
	rts
.addq:
	andi.w	#$7,d1                          ; 8 encodes as 0
	ror.w	#7,d1                           ; count to bits 9-11
	ori.w	#$502d,d1                       ; $502d = addq.b #n,d16(a5)
	bra.w	emit_op_byte_var
.add_nothing:
	addq.l	#2,a0                           ; skip the variable index
	rts
.subq:
	neg.w	d1                              ; d1 = 1..8
	andi.w	#$7,d1                          ; 8 encodes as 0
	ror.w	#7,d1                           ; count to bits 9-11
	ori.w	#$512d,d1                       ; $512d = subq.b #n,d16(a5)
	bra.w	emit_op_byte_var

gen_byte_var_mul_constant:
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d0,(a1)+                        ; n, then the multiply with d0 = n

;------------------------------------------------------------------------------
; IR $80e6: byte variable times d0: move.b (a0),d1 / muls.w d1,d0 / move.b d0,(a0).
;------------------------------------------------------------------------------
gen_byte_var_mul:
	bsr.w	emit_byte_var_address_a0        ; lea var(a5),a0
	move.w	#$1210,(a1)+                    ; $1210 = move.b (a0),d1
	move.w	#$c1c1,(a1)+                    ; $c1c1 = muls.w d1,d0
	move.w	#$1080,(a1)+                    ; $1080 = move.b d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $80e7: byte variable divided by d0: moveq #0,d1 / move.b (a0),d1 / divs.w d0,d1 / move.b d1,(a0).
;------------------------------------------------------------------------------
gen_byte_var_div:
	bsr.w	emit_byte_var_address_a0        ; lea var(a5),a0
	move.w	#$7200,(a1)+                    ; $7200 = moveq #0,d1
	move.w	#$1210,(a1)+                    ; $1210 = move.b (a0),d1
	move.w	#$83c0,(a1)+                    ; $83c0 = divs.w d0,d1
	move.w	#$1081,(a1)+                    ; $1081 = move.b d1,(a0)
	rts

;------------------------------------------------------------------------------
; Byte variable divided by a constant: moveq #0,d0 / move.b (a0),d0 / divs.w #n,d0 / move.b d0,(a0).
;------------------------------------------------------------------------------
gen_byte_var_div_constant:
	move.w	d0,-(sp)                        ; keep the constant
	bsr.w	emit_byte_var_address_a0        ; a0 = the variable's address
	move.w	#$7000,(a1)+                    ; $7000 = moveq #0,d0
	move.w	#$1010,(a1)+                    ; $1010 = move.b (a0),d0
	move.w	#$81fc,(a1)+                    ; $81fc = divs.w #imm,d0
	move.w	(sp)+,(a1)+                     ; the constant
	move.w	#$1080,(a1)+                    ; $1080 = move.b d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8027: push the word d0 (move.w d0,-(sp)).
;------------------------------------------------------------------------------
gen_push_word_d0:
	move.w	#$3f00,(a1)+                    ; $3f00 = move.w d0,-(sp)

;------------------------------------------------------------------------------
; IR $8028: no code.
;------------------------------------------------------------------------------
gen_no_code:
	rts

;------------------------------------------------------------------------------
; IR $8024: GEMDOS call (trap #1), then removes the parameters from the stack.
;------------------------------------------------------------------------------
gen_gemdos_call:
	moveq	#1,d0                           ; trap #1
	bra.s	emit_trap

;------------------------------------------------------------------------------
; IR $8025: BIOS call (trap #13).
;------------------------------------------------------------------------------
gen_bios_call:
	moveq	#13,d0                          ; trap #13
	bra.s	emit_trap

;------------------------------------------------------------------------------
; IR $8026: XBIOS call (trap #14).
;------------------------------------------------------------------------------
gen_xbios_call:
	moveq	#14,d0                          ; trap #14

emit_trap:
	ori.w	#$4e40,d0                       ; $4e40 = trap #0, vector added
	move.w	d0,(a1)+                        ; the trap

;------------------------------------------------------------------------------
; Reads the number of stack bytes from the IR and emits addq.l #n,sp (1-8) or lea n(sp),sp.
;------------------------------------------------------------------------------
emit_stack_cleanup:
	move.w	(a0)+,d0                        ; bytes to remove from the stack

emit_stack_cleanup_d0:
	beq.s	.done                           ; 0: nothing to remove
	cmpi.w	#$8,d0                          ; more than 8: lea
	bhi.s	.lea_cleanup
	andi.w	#$7,d0                          ; 8 encodes as 0
	ror.w	#7,d0                           ; count to bits 9-11
	ori.w	#$508f,d0                       ; $508f = addq.l #n,sp
	move.w	d0,(a1)+                        ; the addq.l
.done:
	rts
.lea_cleanup:
	move.w	#$4fef,(a1)+                    ; $4fef = lea d16(sp),sp
	move.w	d0,(a1)+                        ; n
	rts

;------------------------------------------------------------------------------
; IR $8016: call of the address in a0 with a parameter block: pea (sp) / move.w #n/4,-(sp) (clr.w for
; none), adds the 6 bytes to the IR's stack count, then jsr (a0) and the stack clean-up.
;------------------------------------------------------------------------------
gen_call_with_parameter_block:
	move.w	#$4857,(a1)+                    ; $4857 = pea (sp)
	move.w	(a0),d0                         ; d0 = the IR's stack byte count
	beq.s	.no_parameters                  ; no parameters: clr.w -(sp)
	move.w	#$3f3c,(a1)+                    ; $3f3c = move.w #imm,-(sp)
	lsr.w	#2,d0                           ; number of long parameters
	move.w	d0,(a1)+                        ; n
	bra.s	.add_block_bytes
.no_parameters:
	move.w	#$4267,(a1)+                    ; $4267 = clr.w -(sp)
.add_block_bytes:
	addq.w	#6,(a0)                         ; the pea and the word are removed too

;------------------------------------------------------------------------------
; IR $8015: jsr (a0), then removes the parameters (IR word) from the stack.
;------------------------------------------------------------------------------
gen_call_a0:
	move.w	#$4e90,(a1)+                    ; $4e90 = jsr (a0)
	bra.s	emit_stack_cleanup

;------------------------------------------------------------------------------
; Emit the address of an integer array descriptor into a0.
; Reads the variable number from the IR (via int_array_table, $0ccf2) and falls into emit_variable_address_a0.
;------------------------------------------------------------------------------
emit_int_array_address:
	bsr.w	lookup_integer_array            ; d0 = entry offset, d7 = flags, d1 = second IR word

;------------------------------------------------------------------------------
; Emit the address of a variable into a0: d0 = a5 offset, d7 = high word of the table entry.
; d7 negative (indirect variable): movea.l d16(a5),a0 ($206d); otherwise lea d16(a5),a0 ($41ed).
; Steps a0 back one IR word so the caller sees the following word again.
;------------------------------------------------------------------------------
emit_variable_address_a0:
	tst.w	d7                              ; N set: the variable holds a pointer
	bpl.s	.direct_variable
	move.w	#$206d,(a1)+                    ; movea.l d16(a5),a0
	bra.s	.emit_offset
.direct_variable:
	move.w	#$41ed,(a1)+                    ; lea d16(a5),a0
.emit_offset:
	move.w	d0,(a1)+                        ; offset
	subq.l	#2,a0                           ; the caller reads the second word again
	rts

;------------------------------------------------------------------------------
; Emit the address of a word array descriptor into a0 (word_array_table).
;------------------------------------------------------------------------------
emit_word_array_address:
	bsr.w	lookup_word_array               ; d0 = entry offset, d7 = flags
	bra.s	emit_variable_address_a0

;------------------------------------------------------------------------------
; Emit the address of a byte array descriptor into a0 (byte_array_table).
;------------------------------------------------------------------------------
emit_byte_array_address:
	bsr.w	lookup_byte_array               ; d0 = entry offset, d7 = flags
	bra.s	emit_variable_address_a0

;------------------------------------------------------------------------------
; Emit the address of a boolean array descriptor into a0 (bool_array_table).
;------------------------------------------------------------------------------
emit_bool_array_address:
	bsr.w	lookup_bool_array               ; d0 = entry offset, d7 = flags
	bra.s	emit_variable_address_a0

;------------------------------------------------------------------------------
; Emit the address of a float array descriptor into a0 (float_array_table).
;------------------------------------------------------------------------------
emit_float_array_address:
	bsr.w	lookup_float_array              ; d0 = entry offset, d7 = flags
	bra.s	emit_variable_address_a0

;------------------------------------------------------------------------------
; Emit the address of a string array descriptor into a0 (string_array_table).
;------------------------------------------------------------------------------
emit_string_array_address:
	bsr.w	lookup_string_array             ; d0 = entry offset, d7 = flags
	bra.s	emit_variable_address_a0

;------------------------------------------------------------------------------
; Read the next IR word and emit moveq #n,d7 (number of dimensions for DIM).
;------------------------------------------------------------------------------
emit_moveq_d7_from_ir:
	move.w	(a0)+,d0                        ; d0 = number of dimensions
	move.b	#$7e,(a1)+                      ; moveq #n,d7
	move.b	d0,(a1)+                        ; n
	rts

;------------------------------------------------------------------------------
; IR $80f2: DIM of an integer array. Emits moveq #dims,d7, the descriptor address into a0, then a call to DIMI.
;------------------------------------------------------------------------------
gen_dim_int_array:
	bsr.s	emit_moveq_d7_from_ir           ; moveq #dims,d7
	bsr.s	emit_int_array_address          ; a0 = descriptor address
	move.w	#$e4,d0                         ; DIMI
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f4: DIM of a word array (DIMW).
;------------------------------------------------------------------------------
gen_dim_word_array:
	bsr.s	emit_moveq_d7_from_ir           ; moveq #dims,d7
	bsr.s	emit_word_array_address         ; a0 = descriptor address
	move.w	#$e6,d0                         ; DIMW
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f5: DIM of a byte array (DIMC).
;------------------------------------------------------------------------------
gen_dim_byte_array:
	bsr.s	emit_moveq_d7_from_ir           ; moveq #dims,d7
	bsr.s	emit_byte_array_address         ; a0 = descriptor address
	move.w	#$e7,d0                         ; DIMC
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f3: DIM of a boolean array (DIMB).
;------------------------------------------------------------------------------
gen_dim_bool_array:
	bsr.s	emit_moveq_d7_from_ir           ; moveq #dims,d7
	bsr.s	emit_bool_array_address         ; a0 = descriptor address
	move.w	#$e5,d0                         ; DIMB
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f0: DIM of a float array (DIMF).
;------------------------------------------------------------------------------
gen_dim_float_array:
	bsr.s	emit_moveq_d7_from_ir           ; moveq #dims,d7
	bsr.s	emit_float_array_address        ; a0 = descriptor address
	move.w	#$e2,d0                         ; DIMF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f1: DIM of a string array (DIMS).
;------------------------------------------------------------------------------
gen_dim_string_array:
	bsr.s	emit_moveq_d7_from_ir           ; moveq #dims,d7
	bsr.s	emit_string_array_address       ; a0 = descriptor address
	move.w	#$e3,d0                         ; DIMS
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f7: ARRAYFILL of an integer array: descriptor address into a0, call AFILLI.
;------------------------------------------------------------------------------
gen_arrayfill_int:
	bsr.w	emit_int_array_address          ; a0 = descriptor address
	move.w	#$e9,d0                         ; AFILLI
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f6: ARRAYFILL of a float array (AFILLF).
;------------------------------------------------------------------------------
gen_arrayfill_float:
	bsr.s	emit_float_array_address        ; a0 = descriptor address
	move.w	#$e8,d0                         ; AFILLF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f9: ARRAYFILL of a word array (AFILLW).
;------------------------------------------------------------------------------
gen_arrayfill_word:
	bsr.w	emit_word_array_address         ; a0 = descriptor address
	move.w	#$ea,d0                         ; AFILLW
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80fa: ARRAYFILL of a byte array (AFILLC).
;------------------------------------------------------------------------------
gen_arrayfill_byte:
	bsr.w	emit_byte_array_address         ; a0 = descriptor address
	move.w	#$eb,d0                         ; AFILLC
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80f8: ARRAYFILL of a boolean array (AFILLB).
;------------------------------------------------------------------------------
gen_arrayfill_bool:
	bsr.w	emit_bool_array_address         ; a0 = descriptor address
	move.w	#$ec,d0                         ; AFILLB
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80e9: the empty string "". If the next word is a PRINT string call (PRSTR $a8 or P0RSTR $271) nothing is printed,
; so both are dropped; otherwise call EMPSTR.
;------------------------------------------------------------------------------
gen_empty_string:
	cmpi.w	#$a8,(a0)                       ; PRSTR
	beq.s	.print_nothing
	cmpi.w	#$271,(a0)                      ; P0RSTR
	beq.s	.print_nothing
	move.w	#$a4,d0                         ; EMPSTR
	bra.w	emit_library_call
.print_nothing:
	addq.l	#2,a0                           ; skip the print call too
	rts

;------------------------------------------------------------------------------
; IR $80ea: CHR$(constant). Emits moveq #c,d0 and CHRSTR, or folds a following PRINT into PRCHR / P0RCHR,
; and a space into PRTICK / P0RTICK (no moveq needed).
;------------------------------------------------------------------------------
gen_chr_constant:
	move.w	(a0)+,d0                        ; d0 = the character code
	cmpi.w	#$a8,(a0)                       ; PRSTR follows: print it directly
	beq.s	.print_char
	cmpi.w	#$271,(a0)                      ; P0RSTR follows
	beq.s	.print_char_no_newline
	move.b	#$70,(a1)+                      ; moveq #c,d0
	move.b	d0,(a1)+                        ; c
	move.w	#$a5,d0                         ; CHRSTR
	bra.w	emit_library_call
.print_char:
	addq.l	#2,a0                           ; skip the PRSTR
	cmpi.b	#$20,d0                         ; CHR$(32) printed: PRTICK
	beq.s	.print_space
	move.b	#$70,(a1)+                      ; moveq #c,d0
	move.b	d0,(a1)+                        ; c
	move.w	#$a9,d0                         ; PRCHR
	bra.w	emit_library_call
.print_space:
	moveq	#62,d0                          ; PRTICK (prints a space, no character needed)
	bra.w	emit_library_call
.print_char_no_newline:
	addq.l	#2,a0                           ; skip the P0RSTR
	cmpi.b	#$20,d0                         ; CHR$(32): P0RTICK
	beq.s	.print_space_no_newline
	move.b	#$70,(a1)+                      ; moveq #c,d0
	move.b	d0,(a1)+                        ; c
	move.w	#$258,d0                        ; P0RCHR
	bra.w	emit_library_call
.print_space_no_newline:
	move.w	#$259,d0                        ; P0RTICK
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80eb: MKI$(constant). Emits move.w #n,d0 and MKISTR, or folds a following PRINT into PRMKI / P0RMKI;
; MKI$(&HD0A) printed is CR LF, so the move.w is removed and PRCR / P0RCR called.
;------------------------------------------------------------------------------
gen_mki_constant:
	move.w	(a0)+,d0                        ; d0 = the MKI$ value
	move.w	#$303c,(a1)+                    ; move.w #n,d0
	move.w	d0,(a1)+                        ; n
	cmpi.w	#$a8,(a0)                       ; PRSTR follows
	beq.s	.print_mki
	cmpi.w	#$271,(a0)                      ; P0RSTR follows
	beq.s	.print_mki_no_newline
	move.w	#$a6,d0                         ; MKISTR
	bra.w	emit_library_call
.print_mki:
	addq.l	#2,a0                           ; skip the PRSTR
	cmpi.w	#$d0a,d0                        ; MKI$(&HD0A) = CR LF
	beq.s	.print_crlf
	move.w	#$aa,d0                         ; PRMKI
	bra.w	emit_library_call
.print_crlf:
	subq.l	#4,a1                           ; drop the move.w
	moveq	#60,d0                          ; PRCR
	bra.w	emit_library_call
.print_mki_no_newline:
	addq.l	#2,a0                           ; skip the P0RSTR
	cmpi.w	#$d0a,d0                        ; MKI$(&HD0A) = CR LF
	beq.s	.print_crlf_no_newline
	move.w	#$256,d0                        ; P0RMKI
	bra.w	emit_library_call
.print_crlf_no_newline:
	subq.l	#4,a1                           ; drop the move.w
	move.w	#$255,d0                        ; P0RCR
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80ec: MKL$(constant). Emits move.l #n,d0 and MKLSTR, or PRMKL / P0RMKL when printed.
;------------------------------------------------------------------------------
gen_mkl_constant:
	move.l	(a0)+,d0                        ; d0 = the MKL$ value
	move.w	#$203c,(a1)+                    ; move.l #n,d0
	move.l	d0,(a1)+                        ; n
	cmpi.w	#$a8,(a0)                       ; PRSTR follows
	beq.s	.print_mkl
	cmpi.w	#$271,(a0)                      ; P0RSTR follows
	beq.s	.print_mkl_no_newline
	move.w	#$a7,d0                         ; MKLSTR
	bra.w	emit_library_call
.print_mkl:
	addq.l	#2,a0                           ; skip the PRSTR
	move.w	#$ab,d0                         ; PRMKL
	bra.w	emit_library_call
.print_mkl_no_newline:
	addq.l	#2,a0                           ; skip the P0RSTR
	move.w	#$257,d0                        ; P0RMKL
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80ed: string constant (word length, long pointer to the text). Puts the text in the string pool and loads it
; (emit_string_constant_load), then picks the routine from the next IR word: a constant-string compare (COSxx $163-$168)
; is left to its own handler; PRINT forms become CPRSTR / PXCSTR / C0PRSTR / P0XCSTR; otherwise CONSTR.
;------------------------------------------------------------------------------
gen_string_constant:
	move.w	(a0)+,d0                        ; d0 = string length
	movea.l	(a0)+,a2                        ; a2 = the text
	bsr.s	emit_string_constant_load       ; emit lea pool,a2 / moveq #len,d0
	move.w	(a0),d0                         ; d0 = the routine that takes the string
	cmpi.w	#$167,d0                        ; COSEQ: compare with a constant string
	beq.s	.skip_consumer
	cmpi.w	#$168,d0                        ; COSNE
	beq.s	.skip_consumer
	cmpi.w	#$163,d0                        ; COSGE
	beq.s	.skip_consumer
	cmpi.w	#$165,d0                        ; COSGT
	beq.s	.skip_consumer
	cmpi.w	#$164,d0                        ; COSLE
	beq.s	.skip_consumer
	cmpi.w	#$166,d0                        ; COSLT
	beq.s	.skip_consumer
	cmpi.w	#$f3,d0                         ; PXSTR
	beq.s	.print_constant_newline         ; PXSTR becomes PXCSTR
	cmpi.w	#$a8,d0                         ; PRSTR
	beq.s	.after_print
	cmpi.w	#$272,d0                        ; P0XSTR becomes P0XCSTR
	beq.s	.print_constant_no_newline
	cmpi.w	#$271,d0                        ; P0RSTR
	beq.s	.after_print_no_newline
	move.w	#$b1,d0                         ; CONSTR: the constant as a string value
	bra.s	.call_routine
.after_print:
	addq.l	#2,a0                           ; skip the PRSTR
	cmpi.w	#$3c,(a0)                       ; PRCR follows
	beq.s	.print_constant_newline
	move.w	#$b0,d0                         ; CPRSTR
	bra.s	.call_routine
.print_constant_newline:
	move.w	#$f4,d0                         ; PXCSTR
	bra.s	.skip_consumer
.after_print_no_newline:
	addq.l	#2,a0                           ; skip the P0RSTR
	cmpi.w	#$3c,(a0)                       ; PRCR follows
	beq.s	.print_constant_no_newline
	move.w	#$25a,d0                        ; C0PRSTR
	bra.s	.call_routine
.print_constant_no_newline:
	move.w	#$25b,d0                        ; P0XCSTR
.skip_consumer:
	addq.l	#2,a0                           ; skip the consumer (or the PRCR)
.call_routine:
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Put a string constant into the string pool and emit its load.
; Entry: d0.w = length, a2 = text. The pool runs from data_text_start to data_area_end with limit string_pool_limit;
; when it would overflow, the code buffer (code_buffer_start..code_write_pointer) is moved up $1000 bytes with
; copy_memory_backwards. An identical byte sequence already in the pool is reused. Emits lea abs.l,a2 ($45f9, offset
; into the pool, fixed later by relocate_string_address) and moveq #len,d0 / move.w #len,d0.
;------------------------------------------------------------------------------
emit_string_constant_load:
	ext.l	d0                              ; d0 = length as a long
	movea.l	data_text_start(pc),a3          ; pool start
	movea.l	data_area_end(pc),a4            ; pool end
	move.l	string_pool_limit(pc),d7        ; pool limit
	sub.l	d0,d7                           ; d7 = limit less the length
	cmpa.l	d7,a4                           ; room left in the pool?
	bcs.s	.pool_has_room
	movem.l	d0/a0-a1,-(sp)                  ; no: move the code buffer up to make room
	movea.l	code_write_pointer(pc),a0       ; code buffer end
	move.l	code_buffer_start(pc),d0        ; code buffer start
	sub.l	a0,d0                           ; d0 = start - end
	neg.l	d0                              ; d0 = bytes of code to move
	lea	$1000(a0),a1                    ; move the code up $1000 bytes
	bsr.w	copy_memory_backwards           ; copy d0 bytes from a0 up to a1, from the top down
	move.l	#$1000,d0                       ; everything after the pool moved $1000 up
	add.l	d0,code_buffer_start
	add.l	d0,code_write_pointer
	add.l	d0,string_pool_limit
	movem.l	(sp)+,d0/a0-a1                  ; d0 = length, a0/a1 restored
.pool_has_room:
	suba.w	d0,a4                           ; a4 = last start position the string can have
	move.b	(a2),d3                         ; d3 = first character
	bra.s	.search_test
.search_pool:
	cmp.b	(a3),d3                         ; first character matches?
	bne.s	.next_pool_byte
	move.w	d0,d1                           ; compare from the last byte down
	subq.w	#1,d1                           ; dbne count
.compare_bytes:
	move.b	0(a2,d1.w),d2
	cmp.b	0(a3,d1.w),d2
	dbne	d1,.compare_bytes               ; until a difference or all compared
	beq.s	.found_in_pool                  ; all equal: reuse this copy
.next_pool_byte:
	addq.l	#1,a3                           ; try the next start position
.search_test:
	cmpa.l	a4,a3                           ; still a possible start?
	bls.s	.search_pool
	movea.l	data_area_end(pc),a3            ; not found: append at the pool end
.found_in_pool:
	move.l	a3,d1                           ; d1 = pool offset
	sub.l	data_text_start(pc),d1          ; as an offset from the pool start
	move.w	#$45f9,(a1)+                    ; lea abs.l,a2 (pool offset)
	move.l	d1,(a1)+                        ; the offset (made absolute later)
	cmpi.w	#$7f,d0                         ; length over 127: move.w
	bhi.s	.long_length
	move.b	#$70,(a1)+                      ; moveq #len,d0
	move.b	d0,(a1)+                        ; len
	bra.s	.copy_test
.long_length:
	move.w	#$303c,(a1)+                    ; move.w #len,d0
	move.w	d0,(a1)+                        ; len
	bra.s	.copy_test
.copy_to_pool:
	move.b	(a2)+,(a3)+                     ; append the text to the pool
.copy_test:
	dbra	d0,.copy_to_pool                ; copy the text (over the identical bytes when reused)
	cmpa.l	data_area_end(pc),a3            ; past the old pool end?
	bcs.s	.pool_done
	move.l	a3,data_area_end                ; the pool grows
.pool_done:
	rts

;------------------------------------------------------------------------------
; IR $81ce pos: RESTORE.  The long after the IR code is the DATA position; emits lea pos,a2 ($45f9, abs.l) and a
; call of library routine $32e RESTORE.
;------------------------------------------------------------------------------
gen_ir_81ce_restore:
	move.w	#$45f9,(a1)+                    ; $45f9 = lea (xxx).l,a2, the DATA position from the IR
	move.l	(a0)+,(a1)+                     ; the DATA position
	move.w	#$32e,d0                        ; library routine $32e RESTORE
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8019: emit move.l a1,-(sp) ($2f09).
;------------------------------------------------------------------------------
gen_push_a1:
	move.w	#$2f09,(a1)+                    ; move.l a1,-(sp)
	rts

;------------------------------------------------------------------------------
; IR $8018: save the string address in a0 for a later string operation.
; $803b followed by $8023: emit movea.l a0,a1 ($2248) and turn the $8023 into $7d1e (no code).
; A special constant ($80e9 empty, $80ea CHR$, $80eb MKI$, $80ec MKL$, $80ed constant) followed by $8023 and a string
; routine from string_routine_table: emit the constant and call the specialised routine (EMSxx, CHSxx, MISxx, MLSxx,
; COSxx).
; Otherwise scan forward to the consumer: $8023 -> move.l a0,-(a1) ($2308), $8022 -> nothing, both then marked $8028;
; anything else -> move.l a0,-(sp) ($2f08).
;------------------------------------------------------------------------------
gen_save_string_operand:
	move.w	(a0),d0                         ; d0 = the IR after the $8018
	cmpi.w	#$803b,d0                       ; $803b string variable load next?
	bne.s	.not_assign_pair
	cmpi.w	#$8023,4(a0)                    ; then $8023 pop into a1?
	bne.s	.not_assign_pair
	move.w	#$2248,(a1)+                    ; movea.l a0,a1
	move.w	#$8028,4(a0)                    ; the pop into a1 is not needed
	rts
.not_assign_pair:
	cmpi.w	#$80e9,d0                       ; $80e9 "" before a string operation
	beq.w	.empty_string_compare
	cmpi.w	#$80ea,d0                       ; $80ea CHR$ constant
	beq.w	.chr_compare
	cmpi.w	#$80eb,d0                       ; $80eb MKI$ constant
	beq.w	.mki_compare
	cmpi.w	#$80ec,d0                       ; $80ec MKL$ constant
	beq.w	.mkl_compare
	cmpi.w	#$80ed,d0                       ; $80ed string constant
	beq.w	.constant_compare
	movea.l	a0,a2                           ; a2 scans forward over the operand loads
.scan_ir:
	move.w	(a2)+,d0                        ; d0 = next IR word
	cmpi.w	#$8007,d0                       ; $8007 integer constant: long operand
	beq.s	.skip_two_operand_words
	cmpi.w	#$8008,d0                       ; below $8008
	bcs.s	.not_constant_load
	cmpi.w	#$800e,d0                       ; $8008-$800e constant into a register: long operand
	bls.s	.skip_two_operand_words
.not_constant_load:
	cmpi.w	#$803f,d0                       ; $803f integer variable load
	beq.s	.skip_one_operand_word
	cmpi.w	#$8040,d0                       ; $8040 word variable load
	beq.s	.skip_one_operand_word
	cmpi.w	#$803d,d0                       ; $803d byte variable load
	beq.s	.skip_one_operand_word
	cmpi.w	#$803c,d0                       ; $803c boolean variable load
	beq.s	.skip_one_operand_word
	cmpi.w	#$8084,d0                       ; below $8084
	bcs.s	.not_integer_reg_load
	cmpi.w	#$808a,d0                       ; $8084-$808a integer variable into d1-d7
	bls.s	.skip_one_operand_word
.not_integer_reg_load:
	cmpi.w	#$808d,d0                       ; below $808d
	bcs.s	.not_word_reg_load
	cmpi.w	#$8093,d0                       ; $808d-$8093 word variable into d1-d7
	bls.s	.skip_one_operand_word
.not_word_reg_load:
	cmpi.w	#$8099,d0                       ; below $8099
	bcs.s	.not_byte_reg_load
	cmpi.w	#$809f,d0                       ; $8099-$809f byte variable into d1-d7
	bls.s	.skip_one_operand_word
.not_byte_reg_load:
	cmpi.w	#$80b4,d0                       ; below $80b4
	bcs.s	.not_bool_reg_load
	cmpi.w	#$80ba,d0                       ; $80b4-$80ba boolean variable into d1-d7
	bls.s	.skip_one_operand_word
.not_bool_reg_load:
	cmpi.w	#$8022,d0                       ; $8022 pop into a0: a0 already holds it
	beq.s	.mark_consumed
	cmpi.w	#$8023,d0                       ; $8023 pop into a1
	bne.s	.push_a0
	move.w	#$2308,(a1)+                    ; $2308 = move.l a0,-(a1)
.mark_consumed:
	move.w	#$8028,-(a2)                    ; the pop becomes $8028 no code
	rts
.skip_two_operand_words:
	addq.l	#2,a2                           ; skip the second operand word
.skip_one_operand_word:
	addq.l	#2,a2                           ; skip the operand word
	bra.s	.scan_ir
.push_a0:
	move.w	#$2f08,(a1)+                    ; move.l a0,-(sp)
.done:
	rts
.empty_string_compare:
	cmpi.w	#$8023,2(a0)                    ; $8023 straight after the ""?
	bne.s	.push_a0
	move.w	4(a0),d0                        ; d0 = the string routine
	bsr.w	find_string_routine_column      ; its column in string_routine_table
	bne.s	.push_a0                        ; not a string compare or add
	move.w	$c(a2),d0                       ; EMS variant (0 for ADD)
	addq.l	#6,a0                           ; skip $8023 and the routine
	beq.s	.done                           ; "" + string: nothing to do
	bra.w	emit_library_call
.chr_compare:
	cmpi.w	#$8023,4(a0)                    ; $8023 after CHR$(c)?
	bne.s	.push_a0
	move.w	6(a0),d0                        ; d0 = the string routine
	bsr.w	find_string_routine_column      ; its column in string_routine_table
	bne.s	.push_a0
	move.w	$1a(a2),d0                      ; CHS variant
	move.l	(a0)+,d1                        ; d1 low byte = c
	move.b	#$70,(a1)+                      ; $70 = moveq #c,d0
	move.b	d1,(a1)+                        ; c
	addq.l	#4,a0                           ; skip $8023 and the routine
	bra.w	emit_library_call
.mki_compare:
	cmpi.w	#$8023,4(a0)                    ; $8023 after MKI$(n)?
	bne.s	.push_a0
	move.w	6(a0),d0                        ; d0 = the string routine
	bsr.s	find_string_routine_column      ; its column in string_routine_table
	bne.s	.push_a0
	move.w	$28(a2),d0                      ; MIS variant
	move.l	(a0)+,d1                        ; d1 low word = n
	move.w	#$303c,(a1)+                    ; $303c = move.w #n,d0
	move.w	d1,(a1)+                        ; n
	addq.l	#4,a0                           ; skip $8023 and the routine
	bra.w	emit_library_call
.mkl_compare:
	cmpi.w	#$8023,6(a0)                    ; $8023 after MKL$(n)?
	bne.s	.push_a0
	move.w	8(a0),d0                        ; d0 = the string routine
	bsr.s	find_string_routine_column      ; its column in string_routine_table
	bne.s	.push_a0
	move.w	$36(a2),d0                      ; MLS variant
	addq.l	#2,a0                           ; skip the $80ec
	move.w	#$203c,(a1)+                    ; $203c = move.l #n,d0
	move.l	(a0)+,(a1)+                     ; n
	addq.l	#4,a0                           ; skip $8023 and the routine
	bra.w	emit_library_call
.constant_compare:
	cmpi.w	#$8023,8(a0)                    ; $8023 after the string constant?
	bne.w	.push_a0
	move.w	$a(a0),d0                       ; d0 = the string routine
	bsr.s	find_string_routine_column      ; its column in string_routine_table
	bne.w	.push_a0
	move.w	$44(a2),-(sp)                   ; COS variant
	addq.l	#2,a0                           ; skip the $80ed
	move.w	(a0)+,d0                        ; d0 = length
	movea.l	(a0)+,a2                        ; a2 = the text
	bsr.w	emit_string_constant_load       ; lea pool,a2 / moveq #len,d0
	addq.l	#4,a0                           ; skip $8023 and the routine
	move.w	(sp)+,d0                        ; the COS routine
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Search row 0 of string_routine_table (SGE SLE SGT SLT SEQ SNE SADD) for routine d0.
; Exit: Z set if found, a2 = the entry after it; the same column of the next rows is at $c(a2), $1a(a2), ...
;------------------------------------------------------------------------------
find_string_routine_column:
	lea	string_routine_table(pc),a2
	moveq	#6,d1                           ; dbeq count: 7 entries
.search_column:
	cmp.w	(a2)+,d0                        ; is d0 one of them?
	dbeq	d1,.search_column               ; until found or all 7 tried
	rts

; Library routine numbers of the string operations, 7 per row (GE LE GT LT EQ NE ADD):
; S (string,string), EMS (empty string), CHS (CHR$ constant), MIS (MKI$ constant), MLS (MKL$ constant),
; COS (string constant); the last 6 entries are SLE SGE SLT SGT SEQ SNE (compare with the operands swapped). EMS has no
; ADD (0).
string_routine_table:
	dc.w	$0140,$0141,$0142,$0143,$0144,$0145,$013f,$0147
	dc.w	$0148,$0149,$014a,$014b,$014c,$0000,$014e,$014f
	dc.w	$0150,$0151,$0152,$0153,$014d,$0155,$0156,$0157
	dc.w	$0158,$0159,$015a,$0154,$015c,$015d,$015e,$015f
	dc.w	$0160,$0161,$015b,$0163,$0164,$0165,$0166,$0167
	dc.w	$0168,$0162,$0141,$0140,$0143,$0142,$0144,$0145

;------------------------------------------------------------------------------
; IR $80e8: FOR loop end test of an integer counter in d0: cmp.l -6(a3),d0 ($b0abfffa), then sle d0 if the next IR word
; is $807f (counting down), else sge d0; finished at finish_condition_result.
;------------------------------------------------------------------------------
gen_for_compare_limit:
	move.l	#$b0abfffa,(a1)+                ; $b0abfffa = cmp.l -6(a3),d0: the limit
	move.w	(a0)+,d0                        ; d0 = the compare IR that follows
	cmpi.w	#$807f,d0                       ; counting down
	bne.w	emit_sge_result
	bra.s	emit_sle_result

;------------------------------------------------------------------------------
; IR $80fb: move.l -6(a3),d0 ($202bfffa), the FOR limit from the loop frame.
;------------------------------------------------------------------------------
gen_load_for_limit:
	move.l	#$202bfffa,(a1)+                ; $202bfffa = move.l -6(a3),d0
	rts

;------------------------------------------------------------------------------
; IR $80fc: move.l -10(a3),d0 ($202bfff6), the FOR step from the loop frame.
;------------------------------------------------------------------------------
gen_load_for_step:
	move.l	#$202bfff6,(a1)+                ; $202bfff6 = move.l -10(a3),d0
	rts

;------------------------------------------------------------------------------
; IR $80fd: move.l -6(a3),d2 ($242bfffa).
;------------------------------------------------------------------------------
gen_load_for_limit_d2:
	move.l	#$242bfffa,(a1)+                ; $242bfffa = move.l -6(a3),d2
	rts

;------------------------------------------------------------------------------
; IR $80fe: FOR test with a variable step: tst.l d0 / bpl.s *+4 / exg d2,d1 / cmp.l d2,d1, then sle d0.
;------------------------------------------------------------------------------
gen_for_compare_signed_step:
	move.w	#$4a80,(a1)+                    ; $4a80 = tst.l d0 (the step)
	move.w	#$6a02,(a1)+                    ; bpl.s *+4
	move.w	#$c541,(a1)+                    ; exg d2,d1
	move.w	#$b282,(a1)+                    ; $b282 = cmp.l d2,d1
	bra.s	emit_sle_result

;------------------------------------------------------------------------------
; IR $811c cmp: FOR test of a word counter in d0 against the limit word of the loop frame.  Drops a trailing
; ext.l d0, emits cmp.w -4(a3),d0 ($b06bfffc), then reads the next IR word: $811e (counting down) gives sle d0,
; anything else sge d0, finished at finish_condition_result.
;------------------------------------------------------------------------------
gen_ir_811c_for_compare_word_limit:
	bsr.w	drop_trailing_ext_long          ; IR $811c entry
	move.l	#$b06bfffc,(a1)+                ; $b06bfffc = cmp.w -4(a3),d0: the word limit
	move.w	(a0)+,d0                        ; d0 = the compare IR that follows
	cmpi.w	#$811e,d0                       ; $811e = word <= compare: counting down
	bne.s	emit_sge_result
	bra.s	emit_sle_result

;------------------------------------------------------------------------------
; IR $811f: move.w -4(a3),d0 ($302bfffc), the word FOR limit from the loop frame.
;------------------------------------------------------------------------------
gen_ir_811f_load_word_for_limit:
	move.l	#$302bfffc,(a1)+                ; $302bfffc = move.w -4(a3),d0
	rts

;------------------------------------------------------------------------------
; IR $8120: move.w -6(a3),d0 ($302bfffa), the word FOR step from the loop frame.
;------------------------------------------------------------------------------
gen_ir_8120_load_word_for_step:
	move.l	#$302bfffa,(a1)+                ; $302bfffa = move.w -6(a3),d0
	rts

;------------------------------------------------------------------------------
; IR $8121: move.w -4(a3),d2 ($342bfffc), the word FOR limit into d2.
;------------------------------------------------------------------------------
gen_ir_8121_load_word_for_limit_d2:
	move.l	#$342bfffc,(a1)+                ; $342bfffc = move.w -4(a3),d2
	rts

;------------------------------------------------------------------------------
; IR $8122: word FOR test with a variable step: tst.w d0 / bpl.s *+4 / exg d2,d1 / cmp.w d2,d1, then sle d0
; (emit_sle_result).  A negative step swaps the operands, so one compare serves both directions.
;------------------------------------------------------------------------------
gen_ir_8122_for_compare_word_signed_step:
	move.w	#$4a40,(a1)+                    ; $4a40 = tst.w d0 (the step)
	move.w	#$6a02,(a1)+                    ; $6a02 = bpl.s *+4
	move.w	#$c541,(a1)+                    ; $c541 = exg d2,d1
	move.w	#$b242,(a1)+                    ; $b242 = cmp.w d2,d1
	bra.s	emit_sle_result

;------------------------------------------------------------------------------
; IR $811e: word compare <= : drops a trailing ext.l d0, emits sub.w d1,d0 and sle d0 (emit_sle_result).
;------------------------------------------------------------------------------
gen_ir_811e_compare_word_le:
	bsr.w	drop_trailing_ext_long          ; drop an ext.l d0 just emitted
	move.w	#$9041,(a1)+                    ; $9041 = sub.w d1,d0

;------------------------------------------------------------------------------
; Emit sle d0 ($5fc0) and finish the boolean result at finish_condition_result.
;------------------------------------------------------------------------------
emit_sle_result:
	move.w	#$5fc0,(a1)+                    ; $5fc0 = sle d0
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $811d: word compare >= : drops a trailing ext.l d0, emits sub.w d1,d0 and sge d0 (emit_sge_result).
;------------------------------------------------------------------------------
gen_ir_811d_compare_word_ge:
	bsr.w	drop_trailing_ext_long          ; drop an ext.l d0 just emitted
	move.w	#$9041,(a1)+                    ; $9041 = sub.w d1,d0

;------------------------------------------------------------------------------
; Emit sge d0 ($5cc0) and finish the boolean result at finish_condition_result.
;------------------------------------------------------------------------------
emit_sge_result:
	move.w	#$5cc0,(a1)+                    ; $5cc0 = sge d0
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $8123 cmp: FOR test of a byte counter in d0.  Drops trailing ext.w d0 / ext.l d0 (drop_trailing_extends),
; emits cmp.b -4(a3),d0 ($b02bfffc), then reads the next IR word: $8125 (counting down) gives sls d0, anything
; else scc d0 (unsigned: byte counters are 0-255).
;------------------------------------------------------------------------------
gen_ir_8123_for_compare_byte_limit:
	bsr.w	drop_trailing_extends           ; byte counter variants ($b02bfffc = cmp.b -4(a3),d0)
	move.l	#$b02bfffc,(a1)+                ; $b02bfffc = cmp.b -4(a3),d0: the byte limit
	move.w	(a0)+,d0                        ; d0 = the compare IR that follows
	cmpi.w	#$8125,d0                       ; $8125 = byte <= compare: counting down
	bne.s	emit_shs_result
	bra.s	emit_sls_result

;------------------------------------------------------------------------------
; IR $8126: move.b -4(a3),d0 ($102bfffc), the byte FOR limit from the loop frame.
;------------------------------------------------------------------------------
gen_ir_8126_load_byte_for_limit:
	move.l	#$102bfffc,(a1)+                ; $102bfffc = move.b -4(a3),d0
	rts

;------------------------------------------------------------------------------
; IR $8127: move.b -3(a3),d0 ($102bfffd), the byte FOR step from the loop frame.
;------------------------------------------------------------------------------
gen_ir_8127_load_byte_for_step:
	move.l	#$102bfffd,(a1)+                ; $102bfffd = move.b -3(a3),d0
	rts

;------------------------------------------------------------------------------
; IR $8128: move.b -4(a3),d2 ($142bfffc), the byte FOR limit into d2.
;------------------------------------------------------------------------------
gen_ir_8128_load_byte_for_limit_d2:
	move.l	#$142bfffc,(a1)+                ; $142bfffc = move.b -4(a3),d2
	rts

;------------------------------------------------------------------------------
; IR $8129: byte FOR test with a variable step: tst.b d0 / bpl.s *+4 / exg d2,d1 / cmp.b d2,d1, then sls d0
; (emit_sls_result).
;------------------------------------------------------------------------------
gen_ir_8129_for_compare_byte_signed_step:
	move.w	#$4a00,(a1)+                    ; $4a00 = tst.b d0 (the step)
	move.w	#$6a02,(a1)+                    ; $6a02 = bpl.s *+4
	move.w	#$c541,(a1)+                    ; $c541 = exg d2,d1
	move.w	#$b202,(a1)+                    ; $b202 = cmp.b d2,d1
	bra.s	emit_sls_result

;------------------------------------------------------------------------------
; IR $8125: byte compare <= (unsigned): drops trailing extends, emits sub.b d1,d0 and sls d0 (emit_sls_result).
;------------------------------------------------------------------------------
gen_ir_8125_compare_byte_le:
	bsr.w	drop_trailing_extends           ; drop an ext.w / ext.l d0 just emitted
	move.w	#$9001,(a1)+                    ; $9001 = sub.b d1,d0

;------------------------------------------------------------------------------
; Emit sls d0 ($53c0) and finish the boolean result at finish_condition_result.
;------------------------------------------------------------------------------
emit_sls_result:
	move.w	#$53c0,(a1)+                    ; $53c0 = sls d0
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $8124: byte compare >= (unsigned): drops trailing extends, emits sub.b d1,d0 and scc d0 (emit_shs_result).
;------------------------------------------------------------------------------
gen_ir_8124_compare_byte_ge:
	bsr.w	drop_trailing_extends           ; drop an ext.w / ext.l d0 just emitted
	move.w	#$9001,(a1)+                    ; $9001 = sub.b d1,d0

;------------------------------------------------------------------------------
; Emit scc d0 ($54c0, true when higher or same) and finish the boolean result at finish_condition_result.
;------------------------------------------------------------------------------
emit_shs_result:
	move.w	#$54c0,(a1)+                    ; $54c0 = scc d0 (shs)
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $812a: MIN of two floats, a call of library routine $1b8 FMIN.
;------------------------------------------------------------------------------
gen_ir_812a_float_min:
	move.w	#$1b8,d0                        ; FMIN
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $812b: MAX of two floats, a call of library routine $1b9 FMAX.
;------------------------------------------------------------------------------
gen_ir_812b_float_max:
	move.w	#$1b9,d0                        ; FMAX
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $812c: MIN of the integers d0 and d1 (the optimiser turns $812a into $7e22 for integer operands).
; d0 = $6f (ble) for emit_min_max_exchange: cmp.l d1,d0 / ble.s +2 / exg d1,d0.
;------------------------------------------------------------------------------
gen_ir_812c_integer_min:
	moveq	#111,d0                         ; $6f = ble: keep d0 when d0 <= d1
	bra.s	emit_min_max_exchange

;------------------------------------------------------------------------------
; IR $812d: MAX of the integers d0 and d1 (from $812b).  d0 = $6c (bge) for emit_min_max_exchange.
;------------------------------------------------------------------------------
gen_ir_812d_integer_max:
	moveq	#108,d0                         ; $6c = bge: keep d0 when d0 >= d1

;------------------------------------------------------------------------------
; Emit cmp.l d1,d0 / Bcc.s +2 / exg d1,d0 with the Bcc opcode byte in d0: d0 keeps the wanted operand, else
; it is exchanged with d1.
;------------------------------------------------------------------------------
emit_min_max_exchange:
	move.w	#$b081,(a1)+                    ; $b081 = cmp.l d1,d0
	move.b	d0,(a1)+                        ; Bcc opcode byte (ble or bge)
	move.b	#$2,(a1)+                       ; displacement 2: over the exg
	move.w	#$c340,(a1)+                    ; $c340 = exg d1,d0
	rts

;------------------------------------------------------------------------------
; IR $80ce: emit movem.l (sp)+,mask ($4cdf) when the mask word is not 0.
;------------------------------------------------------------------------------
gen_movem_pop:
	move.w	(a0)+,d0                        ; d0 = register mask
	beq.s	.no_registers                   ; no registers
	move.w	#$4cdf,(a1)+                    ; movem.l (sp)+,mask
	move.w	d0,(a1)+                        ; mask
.no_registers:
	rts

;------------------------------------------------------------------------------
; IR $80cd: register save. Bit 0 of the mask: move.l d0,-(sp) ($2f00). The other bits are reversed (predecrement order)
; for movem.l regs,-(sp) ($48e7). A following IR word, if not 0, is ORed with $2000 and emitted (a move.l whose
; operands are in that word; not worked out further).
;------------------------------------------------------------------------------
gen_movem_push:
	move.w	(a0)+,d0                        ; d0 = register mask (bit 0 = d0)
	bclr	#$0,d0                          ; d0 in the mask?
	beq.s	.check_other_registers          ; no
	move.w	#$2f00,(a1)+                    ; move.l d0,-(sp)
.check_other_registers:
	tst.w	d0                              ; any registers besides d0?
	beq.s	.check_extra_word               ; no other registers
	moveq	#15,d2                          ; reverse all 16 bits for the -(sp) mask
.reverse_bits:
	lsr.w	#1,d0                           ; next bit out at the bottom
	addx.w	d1,d1                           ; and in at the bottom of d1 (old d1 bits shift out)
	dbra	d2,.reverse_bits                ; 16 bits
	move.w	#$48e7,(a1)+                    ; movem.l regs,-(sp)
	move.w	d1,(a1)+                        ; reversed mask
.check_extra_word:
	move.w	(a0)+,d0                        ; d0 = the extra IR word
	beq.s	.done                           ; 0: nothing more
	ori.w	#$2000,d0                       ; make it a move.l
	move.w	d0,(a1)+                        ; emitted as given (not worked out)
.done:
	rts

;------------------------------------------------------------------------------
; IR $8132: INC of a float array element (address in a0): library routine $1db FADDQ1V.
; The element address comes from the $812e-$8131 code before it (lea ...,a0).
;------------------------------------------------------------------------------
gen_ir_8132_inc_float_element:
	move.w	#$1db,d0                        ; library routine $1db FADDQ1V
	bra.w	emit_library_call               ; emit jsr FADDQ1V (a0 = element)

;------------------------------------------------------------------------------
; IR $8136: DEC of a float array element (address in a0): library routine $1dc FSUBQ1V.
; The element address comes from the $812e-$8131 code before it (lea ...,a0).
;------------------------------------------------------------------------------
gen_ir_8136_dec_float_element:
	move.w	#$1dc,d0                        ; library routine $1dc FSUBQ1V
	bra.w	emit_library_call               ; emit jsr FSUBQ1V (a0 = element)

;------------------------------------------------------------------------------
; IR $813a: ADD to a float array element (address in a0, value in d0-d2): library routine 9 FADDV.
; The element address comes from the $812e-$8131 code before it (lea ...,a0).
;------------------------------------------------------------------------------
gen_ir_813a_add_float_element:
	moveq	#9,d0                           ; library routine 9 FADDV
	bra.w	emit_library_call               ; emit jsr FADDV

;------------------------------------------------------------------------------
; IR $813e: SUB from a float array element: library routine 28 FSUBV.
; The element address comes from the $812e-$8131 code before it (lea ...,a0).
;------------------------------------------------------------------------------
gen_ir_813e_sub_float_element:
