	rts

;------------------------------------------------------------------------------
; IR $8145: MUL of a byte array element by d0: emits $04ba, $c1c1 (muls.w d1,d0), $1080 (move.b d0,(a0)).
; $04ba does not decode to a usable instruction (subi.l #imm with a PC-relative destination, taking the next
; words as its immediate); a load of the byte into d1 seems to be meant.  Not worked out further.
; The element address comes from the $812e-$8131 code before it (lea ...,a0).
;------------------------------------------------------------------------------
gen_ir_8145_mul_byte_element:
	move.w	#$4ba,(a1)+                     ; $04ba: not a usable instruction (see the header)
	move.w	#$c1c1,(a1)+                    ; $c1c1 = muls.w d1,d0
	move.w	#$1080,(a1)+                    ; $1080 = move.b d0,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8147: DIV of an integer array element by d0: move.l (a0),d1 / call XLDIV ($38) / move.l d0,(a0).
