	rts

;------------------------------------------------------------------------------
; IR $8148: DIV of a word array element by d0: move.w (a0),d1 / ext.l d1 / divs.w d0,d1 / move.w d1,(a0).
; The element address comes from the $812e-$8131 code before it (lea ...,a0).
;------------------------------------------------------------------------------
gen_ir_8148_div_word_element:
	move.w	#$3210,(a1)+                    ; $3210 = move.w (a0),d1
	move.w	#$48c1,(a1)+                    ; $48c1 = ext.l d1
	move.w	#$83c0,(a1)+                    ; $83c0 = divs.w d0,d1
	move.w	#$3081,(a1)+                    ; $3081 = move.w d1,(a0)
	rts

;------------------------------------------------------------------------------
; IR $8149: DIV of a byte array element by d0: moveq #0,d1 / move.b (a0),d1 / divs.w d0,d1 / move.b d1,(a0).
; The element address comes from the $812e-$8131 code before it (lea ...,a0).
;------------------------------------------------------------------------------
gen_ir_8149_div_byte_element:
	move.w	#$7200,(a1)+                    ; $7200 = moveq #0,d1
	move.w	#$1210,(a1)+                    ; $1210 = move.b (a0),d1
	move.w	#$83c0,(a1)+                    ; $83c0 = divs.w d0,d1
	move.w	#$1081,(a1)+                    ; $1081 = move.b d1,(a0)
	rts
	move.l	#$9aae000e,(a1)+                ; unreferenced: $9aae000e = sub.l 14(a6),d5
	move.l	#$98ae000e,(a1)+                ; $98ae000e = sub.l 14(a6),d4
	rts

;------------------------------------------------------------------------------
; Emit lea d6(a0,d4.l),a0 ($41f0 $48xx with displacement d6).
;------------------------------------------------------------------------------
emit_lea_element_a0:
	move.l	#$41f04800,(a1)+                ; lea 0(a0,d4.l),a0
	move.b	d6,-$1(a1)                      ; displacement in the extension word's low byte
	rts

;------------------------------------------------------------------------------
; Address of an element of an integer array in a0. d1 = number of indices (from the IR).
; 1 index: descriptor into a0, asl.l #2,d4, lea 4(a0,d4.l),a0 (0 with OPTION BASE 1).
; 2 indices: as 1 but mulu.w 6(a0),d5 / add.l d5,d4 first (subq.l #1,d5 with OPTION BASE 1), displacement 8.
; More: descriptor via emit_var_address_a0, moveq #n,d7 and a call to RCAI.
; Callers check for $6101 at -4(a1) to tell the library form from the inline form.
;------------------------------------------------------------------------------
emit_int_element_address:
	bsr.w	lookup_integer_array            ; d0 = descriptor offset, d7 = flags, d1 = number of indices
	cmpi.w	#$1,d1                          ; one index?
	bne.s	.not_one_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero                      ; base 0
	moveq	#0,d6                           ; base 1: displacement 4 - 4
	bra.s	.emit_scale_and_lea
.base_zero:
	moveq	#4,d6                           ; descriptor header 4 bytes
.emit_scale_and_lea:
	move.w	#$e584,(a1)+                    ; $e584 = asl.l #2,d4: 4 bytes per element
	bra.s	emit_lea_element_a0             ; lea d6(a0,d4.l),a0
.not_one_index:
	cmpi.w	#$2,d1                          ; two indices?
	bne.s	.general_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero_two_indices          ; base 0
	move.w	#$5385,(a1)+                    ; $5385 = subq.l #1,d5 (OPTION BASE 1)
	moveq	#4,d6                           ; displacement 8 - 4
	bra.s	.combine_indices                ; then the multiply
.base_zero_two_indices:
	moveq	#8,d6                           ; descriptor header 8 bytes
.combine_indices:
	bsr.w	emit_second_index_multiply      ; mulu.w 6(a0),d5 / add.l d5,d4
	bra.s	.emit_scale_and_lea             ; then the scale and the lea
.general_index:
	tst.w	d7                              ; N = descriptor through a pointer
	bsr.w	emit_var_address_a0             ; lea / movea.l descriptor,a0
	move.b	#$7e,(a1)+                      ; $7e = moveq #n,d7: number of indices
	move.b	d1,(a1)+                        ; n
	move.w	#$1ec,d0                        ; RCAI
	bra.w	emit_library_call               ; emit jsr RCAI

;------------------------------------------------------------------------------
; IR $80c5: load an element of a float array. Library form: RCAF changed to ARCLF.
; Inline: $8002 next -> move.l (a0)+,-(sp) twice (push); $8004 with an operator in float_var_op_table -> call the
; VFxxx routine that takes its operand from (a0); otherwise emit_use_float_var_at_a0.
;------------------------------------------------------------------------------
gen_float_array_load:
	bsr.w	emit_float_element_address      ; the element address in a0, or RCAF
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	bne.s	.inline_load                    ; no: the element address is in a0
	move.w	#$1e7,-$2(a1)                   ; RCAF -> ARCLF (recall the element)
	rts
.inline_load:
	movem.w	(a0),d0-d1                      ; d0 = next IR, d1 = the one after
	cmpi.w	#$8002,d0                       ; push the float
	bne.s	.not_push                       ; no
	addq.l	#2,a0                           ; skip the $8002
	move.l	#$2f182f18,(a1)+                ; move.l (a0)+,-(sp) twice
	rts
.not_push:
	cmpi.w	#$8004,d0                       ; $8004 pop float operand, then an operator?
.use_element:
	bne.w	emit_use_float_var_at_a0        ; no: use the element like a float variable
	lea	float_var_op_table(pc),a2       ; operators, then their routines
	moveq	#19,d0                          ; dbeq count: 20 entries
.search_op:
	cmp.w	(a2)+,d1                        ; is d1 one of them?
	dbeq	d0,.search_op                   ; until found or all 20 tried
	bne.s	.use_element                    ; no: use the element like a float variable
	move.w	$26(a2),d0                      ; routine 20 words on (a2 is one past the match)
	addq.l	#4,a0                           ; skip the $8004 and the operator
	bsr.w	emit_pop_float_accumulator      ; pop the first operand into d0-d2
	bra.w	emit_library_call               ; emit jsr VFxxx: d0-d2 op (a0)

; 20 IR operator codes ($804a-$805b, $812a, $812b), then the 20 library routines that do the operation with the
; second operand in memory at (a0): VFADD VFXSUB VFSUB VFMUL VFXDIV VFDIV, the compares, VFMOD/VFIDIV, FIV_ADD/FIV_MUL,
; VFMIN/VFMAX.
float_var_op_table:
	dc.w	$804a,$804b,$804c,$804d,$804e,$804f,$805a,$805b
	dc.w	$8057,$8056,$8059,$8058,$8052,$8053,$8050,$8051
	dc.w	$01fa,$01f9,$812a,$812b,$0030,$00d6,$0033,$0032
	dc.w	$00d7,$0031,$00d8,$00d9,$00dc,$00dd,$00da,$00db
	dc.w	$00df,$00de,$00e1,$00e0,$01fa,$01f9,$0335,$0337

;------------------------------------------------------------------------------
; IR $80cb: store d0/d1/d2 into a float array element: move.l d0,(a0)+ / move.w d1,(a0)+ / move.w d2,(a0)+
; or RCAF changed to ASTOF.
;------------------------------------------------------------------------------
gen_float_array_store:
	bsr.s	emit_float_element_address      ; the element address in a0, or RCAF
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_store
	move.w	#$20c0,(a1)+                    ; move.l d0,(a0)+
	move.w	#$30c1,(a1)+                    ; move.w d1,(a0)+
	move.w	#$30c2,(a1)+                    ; move.w d2,(a0)+
	rts
.library_store:
	move.w	#$1eb,-$2(a1)                   ; RCAF -> ASTOF
	rts

;------------------------------------------------------------------------------
; Address of an element of a float array in a0 (asl.l #3,d4: 8 bytes per element); as emit_int_element_address,
; library routine RCAF.
;------------------------------------------------------------------------------
emit_float_element_address:
	bsr.w	lookup_float_array              ; d0 = descriptor offset, d7 = flags, d1 = number of indices
	cmpi.w	#$1,d1                          ; one index?
	bne.s	.not_one_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero                      ; base 0
	moveq	#-4,d6                          ; base 1: displacement 4 - 8
	bra.s	.emit_scale_and_lea
.base_zero:
	moveq	#4,d6                           ; descriptor header 4 bytes
.emit_scale_and_lea:
	move.w	#$e784,(a1)+                    ; $e784 = asl.l #3,d4: 8 bytes per element
	bra.w	emit_lea_element_a0             ; lea d6(a0,d4.l),a0
.not_one_index:
	cmpi.w	#$2,d1                          ; two indices?
	bne.s	.general_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero_two_indices          ; base 0
	move.w	#$5385,(a1)+                    ; $5385 = subq.l #1,d5 (OPTION BASE 1)
	moveq	#0,d6                           ; displacement 8 - 8
	bra.s	.combine_indices
.base_zero_two_indices:
	moveq	#8,d6                           ; descriptor header 8 bytes
.combine_indices:
	bsr.s	emit_second_index_multiply      ; mulu.w 6(a0),d5 / add.l d5,d4
	bra.s	.emit_scale_and_lea
.general_index:
	tst.w	d7                              ; N = descriptor through a pointer
	bsr.w	emit_var_address_a0             ; lea / movea.l descriptor,a0
	move.b	#$7e,(a1)+                      ; $7e = moveq #n,d7: number of indices
	move.b	d1,(a1)+                        ; n
	move.w	#$1ef,d0                        ; RCAF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Emit mulu.w 6(a0),d5 / add.l d5,d4: combine the two indices of a 2-dimensional array.
;------------------------------------------------------------------------------
emit_second_index_multiply:
	move.l	#$cae80006,(a1)+                ; mulu.w 6(a0),d5
	move.w	#$d885,(a1)+                    ; add.l d5,d4
	rts

;------------------------------------------------------------------------------
; Address of an element of a word array in a0 (add.l d4,d4); library routine RCAW.
;------------------------------------------------------------------------------
emit_word_element_address:
	bsr.w	lookup_word_array               ; d0 = descriptor offset, d7 = flags, d1 = number of indices
	cmpi.w	#$1,d1                          ; one index?
	bne.s	.not_one_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero                      ; base 0
	moveq	#2,d6                           ; base 1: displacement 4 - 2
	bra.s	.emit_scale_and_lea
.base_zero:
	moveq	#4,d6                           ; descriptor header 4 bytes
.emit_scale_and_lea:
	move.w	#$d884,(a1)+                    ; $d884 = add.l d4,d4: 2 bytes per element
	bra.w	emit_lea_element_a0             ; lea d6(a0,d4.l),a0
.not_one_index:
	cmpi.w	#$2,d1                          ; two indices?
	bne.s	.general_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero_two_indices          ; base 0
	move.w	#$5385,(a1)+                    ; $5385 = subq.l #1,d5 (OPTION BASE 1)
	moveq	#6,d6                           ; displacement 8 - 2
	bra.s	.combine_indices
.base_zero_two_indices:
	moveq	#8,d6                           ; descriptor header 8 bytes
.combine_indices:
	bsr.s	emit_second_index_multiply      ; mulu.w 6(a0),d5 / add.l d5,d4
	bra.s	.emit_scale_and_lea
.general_index:
	tst.w	d7                              ; N = descriptor through a pointer
	bsr.w	emit_var_address_a0             ; lea / movea.l descriptor,a0
	move.b	#$7e,(a1)+                      ; $7e = moveq #n,d7: number of indices
	move.b	d1,(a1)+                        ; n
	move.w	#$1ed,d0                        ; RCAW
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Address of an element of a byte array in a0 (no scaling); library routine RCAC.
;------------------------------------------------------------------------------
emit_byte_element_address:
	bsr.w	lookup_byte_array               ; d0 = descriptor offset, d7 = flags, d1 = number of indices
	cmpi.w	#$1,d1                          ; one index?
	bne.s	.not_one_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero                      ; base 0
	moveq	#3,d6                           ; base 1: displacement 4 - 1
	bra.s	.emit_lea
.base_zero:
	moveq	#4,d6                           ; descriptor header 4 bytes
.emit_lea:
	bra.w	emit_lea_element_a0             ; lea d6(a0,d4.l),a0, no scaling
.not_one_index:
	cmpi.w	#$2,d1                          ; two indices?
	bne.s	.general_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.base_zero_two_indices          ; base 0
	move.w	#$5385,(a1)+                    ; $5385 = subq.l #1,d5 (OPTION BASE 1)
	moveq	#7,d6                           ; displacement 8 - 1
	bra.s	.combine_indices
.base_zero_two_indices:
	moveq	#8,d6                           ; descriptor header 8 bytes
.combine_indices:
	bsr.w	emit_second_index_multiply      ; mulu.w 6(a0),d5 / add.l d5,d4
	bra.s	.emit_lea
.general_index:
	tst.w	d7                              ; N = descriptor through a pointer
	bsr.w	emit_var_address_a0             ; lea / movea.l descriptor,a0
	move.b	#$7e,(a1)+                      ; $7e = moveq #n,d7: number of indices
	move.b	d1,(a1)+                        ; n
	move.w	#$1ee,d0                        ; RCAC
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Address of the byte holding an element of a boolean array: move.b d4,d5 / lsr.l #3,d4, d5 = bit number,
; then lea; library routine RCAB.
;------------------------------------------------------------------------------
emit_bool_element_address:
	bsr.w	lookup_bool_array               ; d0 = descriptor offset, d7 = flags, d1 = number of indices
	cmpi.w	#$1,d1                          ; one index?
	bne.s	.not_one_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.set_displacement               ; base 0
	move.w	#$5384,(a1)+                    ; $5384 = subq.l #1,d4 (OPTION BASE 1)
.set_displacement:
	moveq	#4,d6                           ; descriptor header 4 bytes
.emit_bit_index:
	move.w	#$1a04,(a1)+                    ; $1a04 = move.b d4,d5: low bits give the bit number
	move.w	#$e68c,(a1)+                    ; $e68c = lsr.l #3,d4: byte offset
	bra.w	emit_lea_element_a0             ; lea d6(a0,d4.l),a0
.not_one_index:
	cmpi.w	#$2,d1                          ; two indices?
	bne.s	.general_index
	bsr.w	emit_array_descriptor_a0        ; descriptor into a0; Z = OPTION BASE 0
	beq.s	.two_index_displacement         ; base 0
	move.w	#$5385,(a1)+                    ; $5385 = subq.l #1,d5 (OPTION BASE 1)
	move.w	#$5384,(a1)+                    ; $5384 = subq.l #1,d4
.two_index_displacement:
	moveq	#8,d6                           ; descriptor header 8 bytes
	bsr.w	emit_second_index_multiply      ; mulu.w 6(a0),d5 / add.l d5,d4
	bra.s	.emit_bit_index
.general_index:
	tst.w	d7                              ; N = descriptor through a pointer
	bsr.w	emit_var_address_a0             ; lea / movea.l descriptor,a0
	move.b	#$7e,(a1)+                      ; $7e = moveq #n,d7: number of indices
	move.b	d1,(a1)+                        ; n
	move.w	#$1fc,d0                        ; RCAB
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $80cc: store into a string array element: descriptor into a1, then ASTOS1 / ASTOS2, or ASTOS for more indices
; (the movea/lea to a0 is changed to a1 by adding $200).
;------------------------------------------------------------------------------
gen_string_array_store:
	bsr.w	lookup_string_array             ; d0 = descriptor offset, d7 = flags, d1 = number of indices
	cmpi.w	#$1,d1                          ; one index?
	bne.s	.not_one_index
	bsr.w	emit_array_descriptor_a1        ; movea.l descriptor,a1
	move.w	#$23c,d0                        ; ASTOS1
	bra.w	emit_library_call               ; emit jsr ASTOS1
.not_one_index:
	cmpi.w	#$2,d1                          ; two indices?
	bne.s	.general_index
	bsr.w	emit_array_descriptor_a1        ; movea.l descriptor,a1
	move.w	#$23d,d0                        ; ASTOS2
	bra.w	emit_library_call               ; emit jsr ASTOS2
.general_index:
	tst.w	d7                              ; N = descriptor through a pointer
	bsr.w	emit_var_address_a0             ; lea / movea.l descriptor,a0
	addi.w	#$200,-$4(a1)                   ; movea / lea to a1
	move.b	#$7e,(a1)+                      ; $7e = moveq #n,d7: number of indices
	move.b	d1,(a1)+                        ; n
	move.w	#$23b,d0                        ; ASTOS
	bra.w	emit_library_call               ; emit jsr ASTOS

;------------------------------------------------------------------------------
; IR $80c6: recall a string array element (emit_string_element_recall). If LEN() ($ac) follows, the length is read
; from the descriptor directly: move.w 4(a0),d0.
;------------------------------------------------------------------------------
gen_string_array_load:
	bsr.s	emit_string_element_recall      ; RCAS1 / RCAS2 / RCAS
	cmpi.w	#$ac,(a0)                       ; LENSTR follows
	beq.s	.len_of_element
	rts
.len_of_element:
	move.w	(a0)+,current_ir_code           ; the LEN is consumed (skips its own handler)
	move.l	#$30280004,(a1)+                ; $30280004 = move.w 4(a0),d0: the string's length
	bra.w	gen_sign_extend_word            ; ext.l d0 when needed

;------------------------------------------------------------------------------
; Recall an element of a string array: RCAS1, RCAS2 or RCAS (more indices).
;------------------------------------------------------------------------------
emit_string_element_recall:
	bsr.w	lookup_string_array             ; d0 = descriptor offset, d7 = flags, d1 = number of indices
	cmpi.w	#$1,d1                          ; one index?
	bne.s	.not_one_index
	bsr.s	emit_array_descriptor_a1        ; movea.l descriptor,a1
	move.w	#$23f,d0                        ; RCAS1
	bra.w	emit_library_call
.not_one_index:
	cmpi.w	#$2,d1                          ; two indices?
	bne.s	.general_index
	bsr.s	emit_array_descriptor_a1        ; movea.l descriptor,a1
	move.w	#$240,d0                        ; RCAS2
	bra.w	emit_library_call
.general_index:
	tst.w	d7                              ; N = descriptor through a pointer
	bsr.w	emit_var_address_a0             ; lea / movea.l descriptor,a0
	addi.w	#$200,-$4(a1)                   ; movea / lea to a1
	move.b	#$7e,(a1)+                      ; $7e = moveq #n,d7: number of indices
	move.b	d1,(a1)+                        ; n
	move.w	#$23e,d0                        ; RCAS
	bra.w	emit_library_call

; Self-modified long in the text (address stored in a table at $06c24): 0 for OPTION BASE 0, non-zero for BASE 1.
; The instruction shown is that long decoded as code.
option_base_flag:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Emit movea.l d16(a5),a0 ($206d), plus movea.l (a0),a0 ($2050) for an indirect variable: the array descriptor.
; Exit: d7 = option_base_flag, Z set for OPTION BASE 0.
;------------------------------------------------------------------------------
emit_array_descriptor_a0:
	move.w	#$206d,(a1)+                    ; movea.l d16(a5),a0
	move.w	d0,(a1)+                        ; offset of the descriptor pointer
	tst.w	d7                              ; N = the variable holds a pointer
	bpl.s	.direct_descriptor
	move.w	#$2050,(a1)+                    ; movea.l (a0),a0
.direct_descriptor:
	move.l	option_base_flag(pc),d7         ; d7 and Z: OPTION BASE
	rts

;------------------------------------------------------------------------------
; As emit_array_descriptor_a0 but into a1 ($226d, $2251). Exit: Z set for OPTION BASE 0.
;------------------------------------------------------------------------------
emit_array_descriptor_a1:
	move.w	#$226d,(a1)+                    ; movea.l d16(a5),a1
	move.w	d0,(a1)+                        ; offset of the descriptor pointer
	tst.w	d7                              ; N = the variable holds a pointer
	bpl.s	.direct_descriptor
	move.w	#$2251,(a1)+                    ; movea.l (a1),a1
.direct_descriptor:
	tst.l	option_base_flag                ; Z set: OPTION BASE 0
	rts

;------------------------------------------------------------------------------
; Store the constant 0 or not 0 (d0) into a boolean array element: patches the lea into bset/bclr d5,(a0,d4.l)
; ($0bf0/$0bb0), or uses ASETB / ACLRB.
;------------------------------------------------------------------------------
gen_bool_array_store_constant:
	move.l	d0,-(sp)                        ; keep the constant
	bsr.w	emit_bool_element_address       ; element address (inline: byte in a0/d4, bit in d5)
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_store
	move.l	(sp)+,d0                        ; d0 = the constant
	beq.s	.clear_bit                      ; 0: bclr
	move.w	#$bf0,-$4(a1)                   ; the lea becomes bset d5,(d8,a0,d4.l)
	rts
.clear_bit:
	move.w	#$bb0,-$4(a1)                   ; the lea becomes bclr d5,(d8,a0,d4.l)
	rts
.library_store:
	move.l	(sp)+,d0                        ; d0 = the constant
	bne.s	.clear_with_library
	move.w	#$1ff,-$2(a1)                   ; RCAB -> ASETB
	rts
.clear_with_library:
	move.w	#$1fe,-$2(a1)                   ; RCAB -> ACLRB
	rts

;------------------------------------------------------------------------------
; IR $80ca: store d0 into a boolean array element: bset d5,(..) / tst.l d0 / bne.s / bclr d5,(..), or ASTOB.
;------------------------------------------------------------------------------
gen_bool_array_store:
	bsr.w	emit_bool_element_address       ; element address (inline: byte in a0/d4, bit in d5)
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_store
	move.l	-(a1),d0                        ; d0 = the lea word pair (opcode, extension)
	move.w	#$bf0,(a1)+                     ; $0bf0 = bset d5,(d8,a0,d4.l)
	move.w	d0,(a1)+                        ; the extension word of the lea
	move.w	#$4a80,(a1)+                    ; tst.l d0
	move.w	#$6604,(a1)+                    ; $6604 = bne.s *+6: over the bclr
	move.w	#$bb0,(a1)+                     ; $0bb0 = bclr d5,(d8,a0,d4.l)
	move.w	d0,(a1)+                        ; the extension word
	rts
.library_store:
	move.w	#$200,-$2(a1)                   ; RCAB -> ASTOB
	rts

;------------------------------------------------------------------------------
; IR $80c4: load a boolean array element: btst d5,(a0,d4.l) / sne d0 then finish_condition_result, or ARCLB.
;------------------------------------------------------------------------------
gen_bool_array_load:
	bsr.w	emit_bool_element_address       ; element address (inline: byte in a0/d4, bit in d5)
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_load
	move.l	-(a1),d0                        ; d0 = the lea word pair; overwritten
	move.w	#$b30,(a1)+                     ; btst d5,(d8,a0,d4.l)
	move.w	d0,(a1)+                        ; extension word
	move.w	#$56c0,(a1)+                    ; sne d0
	bra.w	finish_condition_result         ; d0 = 0 / -1, flags for a jump
.library_load:
	move.w	#$1fd,-$2(a1)                   ; RCAB -> ARCLB
	rts

;------------------------------------------------------------------------------
; Store the constant d0 into an integer array element: inline move.l #n / moveq+move.l / clr.l into (d,a0,d4.l),
; library ASTOI (with moveq) / ACLRI.
;------------------------------------------------------------------------------
gen_int_array_store_constant:
	move.l	d0,-(sp)                        ; keep the constant
	bsr.w	emit_int_element_address        ; element address: lea d(a0,d4.l),a0 or RCAI
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	bne.s	.inline_store                   ; no: inline store
	move.l	(sp)+,d0                        ; d0 = the constant
	beq.s	.clear_with_library             ; 0: ACLRI
	move.b	d0,d1                           ; fits a moveq?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1                           ; same value as a sign-extended byte?
	beq.s	.store_with_library             ; yes: moveq + ASTOI
	move.w	#$20bc,(a1)+                    ; $20bc = move.l #n,(a0) after RCAI
	move.l	d0,(a1)+                        ; n
	rts
.store_with_library:
	subq.l	#4,a1                           ; drop the RCAI call
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d0,(a1)+                        ; n
	move.w	#$1e8,d0                        ; ASTOI
	bra.w	emit_library_call
.clear_with_library:
	move.w	#$1f0,-$2(a1)                   ; RCAI -> ACLRI
	rts
.inline_store:
	move.l	-(a1),d7                        ; d7 = the lea word pair; overwritten
	move.l	(sp)+,d0                        ; d0 = the constant
	beq.s	.clear_element                  ; 0: clr.l
	move.b	d0,d1                           ; fits a moveq?
	ext.w	d1
	ext.l	d1
	cmp.l	d0,d1                           ; same value as a sign-extended byte?
	beq.s	.store_with_moveq
	move.w	#$21bc,(a1)+                    ; move.l #n,(d8,a0,d4.l)
	move.l	d0,(a1)+                        ; n
	move.w	d7,(a1)+                        ; extension word
	rts
.store_with_moveq:
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d0,(a1)+                        ; n
	move.w	#$2180,(a1)+                    ; move.l d0,(d8,a0,d4.l)
	move.w	d7,(a1)+                        ; extension word
	rts
.clear_element:
	move.w	#$42b0,(a1)+                    ; clr.l (d8,a0,d4.l)
	move.w	d7,(a1)+                        ; extension word
	rts

;------------------------------------------------------------------------------
; IR $80c7: store d0 into an integer array element: move.l d0,(d,a0,d4.l) ($2180) or ASTOI.
;------------------------------------------------------------------------------
gen_int_array_store:
	bsr.w	emit_int_element_address        ; element address: lea d(a0,d4.l),a0 or RCAI
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_store
	move.w	#$2180,-$4(a1)                  ; the lea becomes move.l d0,(d8,a0,d4.l)
	rts
.library_store:
	move.w	#$1e8,-$2(a1)                   ; RCAI -> ASTOI
	rts

;------------------------------------------------------------------------------
; IR $80c1: load an integer array element: move.l (..),d0 ($2030), or move.l (..),-(sp) ($2f30) when $8017 (push)
; follows; library ARCLI.
;------------------------------------------------------------------------------
gen_int_array_load:
	bsr.w	emit_int_element_address        ; element address: lea d(a0,d4.l),a0 or RCAI
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_load
	cmpi.w	#$8017,(a0)                     ; $8017 push long follows?
	beq.s	.push_element
	move.w	#$2030,-$4(a1)                  ; move.l (d8,a0,d4.l),d0
	rts
.push_element:
	move.w	#$2f30,-$4(a1)                  ; move.l (d8,a0,d4.l),-(sp)
	addq.l	#2,a0                           ; skip the $8017
	rts
.library_load:
	move.w	#$1e4,-$2(a1)                   ; RCAI -> ARCLI
	rts

;------------------------------------------------------------------------------
; Store the constant d0 into a word array element (move.w #n / clr.w, or ASTOW / ACLRW).
;------------------------------------------------------------------------------
gen_word_array_store_constant:
	move.w	d0,-(sp)                        ; keep the constant
	bsr.w	emit_word_element_address       ; element address: lea d(a0,d4.l),a0 or RCAW
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	bne.s	.inline_store                   ; no: inline store
	move.w	(sp)+,d0                        ; d0 = the constant
	beq.s	.clear_with_library             ; 0: ACLRW
	move.w	#$30bc,(a1)+                    ; $30bc = move.w #n,(a0) after RCAW
	move.w	d0,(a1)+                        ; n
	rts
.clear_with_library:
	move.w	#$1f1,-$2(a1)                   ; RCAW -> ACLRW
	rts
.inline_store:
	move.l	-(a1),d7                        ; d7 = the lea word pair; overwritten
	move.w	(sp)+,d0                        ; d0 = the constant
	beq.s	.clear_element                  ; 0: clr.w
	move.w	#$31bc,(a1)+                    ; $31bc = move.w #n,(d8,a0,d4.l)
	move.w	d0,(a1)+                        ; n
	move.w	d7,(a1)+                        ; extension word
	rts
.clear_element:
	move.w	#$4270,(a1)+                    ; $4270 = clr.w (d8,a0,d4.l)
	move.w	d7,(a1)+                        ; extension word
	rts

;------------------------------------------------------------------------------
; IR $80c8: store d0 into a word array element ($3180) or ASTOW.
;------------------------------------------------------------------------------
gen_word_array_store:
	bsr.w	emit_word_element_address       ; element address: lea d(a0,d4.l),a0 or RCAW
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_store
	move.w	#$3180,-$4(a1)                  ; the lea becomes move.w d0,(d8,a0,d4.l)
	rts
.library_store:
	move.w	#$1e9,-$2(a1)                   ; RCAW -> ASTOW
	rts

;------------------------------------------------------------------------------
; IR $80c2: load a word array element: move.w (..),d0 then gen_sign_extend_word; $8027 next: move.w (..),-(sp);
; $8017 next: movea.w (..),a2 / pea (a2) (pushes it sign-extended); library ARCLW.
;------------------------------------------------------------------------------
gen_word_array_load:
	bsr.w	emit_word_element_address       ; element address: lea d(a0,d4.l),a0 or RCAW
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_load
	cmpi.w	#$8027,(a0)                     ; $8027 push word follows?
	beq.s	.push_word
	cmpi.w	#$8017,(a0)                     ; $8017 push long follows?
	beq.s	.push_sign_extended
	move.w	#$3030,-$4(a1)                  ; move.w (d8,a0,d4.l),d0
	bra.w	gen_sign_extend_word            ; ext.l d0 when needed
.push_word:
	move.w	#$3f30,-$4(a1)                  ; move.w (..),-(sp)
	addq.l	#2,a0                           ; skip the $8027
	rts
.library_load:
	move.w	#$1e5,-$2(a1)                   ; RCAW -> ARCLW
	rts
.push_sign_extended:
	move.w	#$3470,-$4(a1)                  ; movea.w (..),a2
	move.w	#$4852,(a1)+                    ; pea (a2)
	addq.l	#2,a0                           ; skip the $8017
	rts

;------------------------------------------------------------------------------
; Store the constant d0.b into a byte array element (move.b #n / clr.b / st, or ASTOC / ACLRC).
;------------------------------------------------------------------------------
gen_byte_array_store_constant:
	move.b	d0,-(sp)                        ; keep the constant
	bsr.w	emit_byte_element_address       ; element address: lea d(a0,d4.l),a0 or RCAC
	moveq	#0,d0                           ; d0 = the constant, zero-extended
	move.b	(sp)+,d0
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	bne.s	.inline_store                   ; no: inline store
	tst.b	d0                              ; constant 0?
	beq.s	.clear_with_library
	subq.l	#4,a1                           ; drop the RCAC call
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d0,(a1)+                        ; n
	move.w	#$1ea,d0                        ; ASTOC
	bra.w	emit_library_call
.clear_with_library:
	move.w	#$1f2,-$2(a1)                   ; RCAC -> ACLRC
	rts
.inline_store:
	move.l	-(a1),d7                        ; d7 = the lea word pair; overwritten
	tst.w	d0                              ; 0: clr.b
	beq.s	.clear_element
	cmpi.b	#$ff,d0                         ; $ff: st
	beq.s	.set_element
	move.w	#$11bc,(a1)+                    ; move.b #n,(..)
	move.w	d0,(a1)+                        ; n as the immediate word
	move.w	d7,(a1)+                        ; extension word
	rts
.clear_element:
	move.w	#$4230,(a1)+                    ; clr.b (..)
	move.w	d7,(a1)+                        ; extension word
	rts
.set_element:
	move.w	#$50f0,(a1)+                    ; st (..)
	move.w	d7,(a1)+                        ; extension word
	rts

;------------------------------------------------------------------------------
; IR $80c9: store d0 into a byte array element ($1180) or ASTOC.
;------------------------------------------------------------------------------
gen_byte_array_store:
	bsr.w	emit_byte_element_address       ; element address: lea d(a0,d4.l),a0 or RCAC
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_store
	move.w	#$1180,-$4(a1)                  ; the lea becomes move.b d0,(d8,a0,d4.l)
	rts
.library_store:
	move.w	#$1ea,-$2(a1)                   ; RCAC -> ASTOC
	rts

;------------------------------------------------------------------------------
; IR $80c3: load a byte array element: moveq #0,d0 / move.b (..),d0, without the moveq when $80bf/$80c0 follows;
; library ARCLC.
;------------------------------------------------------------------------------
gen_byte_array_load:
	bsr.w	emit_byte_element_address       ; element address: lea d(a0,d4.l),a0 or RCAC
	cmpi.w	#$6101,-$4(a1)                  ; library call emitted?
	beq.s	.library_load
	move.l	-(a1),d0                        ; d0 = the lea word pair; overwritten
	cmpi.w	#$80bf,(a0)                     ; $80bf jump if false: no moveq #0
	beq.s	.move_byte_only
	cmpi.w	#$80c0,(a0)                     ; $80c0 jump if true
	beq.s	.move_byte_only
	move.l	#$70001030,(a1)+                ; moveq #0,d0 / move.b (..),d0
	move.w	d0,(a1)+                        ; extension word
	rts
.library_load:
	move.w	#$1e6,-$2(a1)                   ; RCAC -> ARCLC
	rts
.move_byte_only:
	move.w	#$1030,(a1)+                    ; $1030 = move.b (d8,a0,d4.l),d0
	move.w	d0,(a1)+                        ; extension word
	rts

;------------------------------------------------------------------------------
; IR $80ef: move.w d2,d0 / sne d0, then the boolean result at finish_condition_result.
;------------------------------------------------------------------------------
gen_bool_from_d2:
	move.w	#$3002,(a1)+                    ; move.w d2,d0
	move.w	#$56c0,(a1)+                    ; $56c0 = sne d0
	bra.w	finish_condition_result

;------------------------------------------------------------------------------
; IR $802b: DRAWTO with a point count: moveq #count,d0 and call DRAWTO.
;------------------------------------------------------------------------------
gen_drawto_call:
	move.w	#$3,d0                          ; DRAWTO
	bra.s	emit_count_and_call

;------------------------------------------------------------------------------
; IR $802a: DRAW: moveq #count,d0 and call DRAW.
;------------------------------------------------------------------------------
gen_draw_call:
	move.w	#$224,d0                        ; DRAW

;------------------------------------------------------------------------------
; Read the IR word (bytes of parameters), divide by 4 and emit moveq #n,d0, then call routine d0.
;------------------------------------------------------------------------------
emit_count_and_call:
	move.w	(a0)+,d1                        ; d1 = parameter bytes
	lsr.w	#2,d1                           ; d1 = number of longs
	move.b	#$70,(a1)+                      ; $70 = moveq #n,d0
	move.b	d1,(a1)+                        ; n
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $818d n: call numeric function FN n.  Sets d4 = numeric_fn_address_table, a2 = function_line_table,
; d5 = marker $7f02, d7 = -3 (high word of an external $X call), then gen_proc_or_fn_call.
;------------------------------------------------------------------------------
gen_ir_818d_numeric_fn_call:
	move.l	numeric_fn_address_table(pc),d4 ; numeric FN call setup
	movea.l	function_line_table(pc),a2      ; a2 = FN definition lines
	move.w	#$7f02,d5                       ; FN marker
	moveq	#-3,d7                          ; high word of an external FN call
	bra.s	gen_proc_or_fn_call

;------------------------------------------------------------------------------
; IR $818e n: call string function FN n$.  As gen_ir_818d_numeric_fn_call with string_fn_address_table,
; string_function_line_table, marker $7f04 and d7 = -4.
;------------------------------------------------------------------------------
gen_ir_818e_string_fn_call:
	move.l	string_fn_address_table(pc),d4  ; string FN call setup
	movea.l	string_function_line_table(pc),a2 ; a2 = FN$ definition lines
	move.w	#$7f04,d5                       ; FN$ marker
	moveq	#-4,d7                          ; high word of an external FN$ call
	bra.s	gen_proc_or_fn_call

;------------------------------------------------------------------------------
; IR $80b3: call a procedure. Sets a2 = procedure_line_table, d7 = -2, marker $4afd, d4 = procedure_address_table,
; then falls into gen_proc_or_fn_call.  gen_ir_818d_numeric_fn_call and gen_ir_818e_string_fn_call before it do the
; same for numeric FN (-3, $7f02) and string FN (-4, $7f04).
;------------------------------------------------------------------------------
gen_procedure_call:
	movea.l	procedure_line_table(pc),a2     ; a2 = PROCEDURE definition lines
	moveq	#-2,d7                          ; high word of an external procedure call
	move.w	#$4afd,d5                       ; procedure marker
	move.l	procedure_address_table(pc),d4  ; d4 = code offsets of the procedures

;------------------------------------------------------------------------------
; Call a procedure or function d0 (IR word). If its definition starts with a $X directive (token $336, then 'X') it is
; external: emit jsr $fffe/$fffd/$fffc:number (fixed by relocate_absolute_long) and pop the parameters, counted from the
; definition line, with emit_stack_cleanup_d0. Otherwise emit the marker d5 and the number: short form (a bsr) when the
; definition is already known and less than 32000 bytes back, else the long form (jsr).
;------------------------------------------------------------------------------
gen_proc_or_fn_call:
	move.w	(a0)+,d0                        ; d0 = procedure / function number
	ext.l	d0
	move.l	d0,d1                           ; d1 = number
	asl.w	#2,d1                           ; times 4: table offset
	move.l	a2,d6                           ; d6 = the line table, kept
	movea.l	0(a2,d1.w),a2                   ; a2 = the definition line
	adda.w	(a2),a2                         ; plus the line's offset word: the line's code
	addq.l	#2,a2                           ; past the line header (not worked out)
	cmpi.w	#$336,(a2)+                     ; $ line (compiler directive)
	bne.s	.basic_procedure
.skip_spaces:
	moveq	#-33,d2                         ; upper case
	and.b	(a2)+,d2                        ; next character, upper case
	cmpi.b	#$20,d2                         ; skip spaces
	beq.s	.skip_spaces
	cmpi.b	#$58,d2                         ; 'X': external procedure ($X name)
	bne.s	.basic_procedure
	move.w	#$4eb9,(a1)+                    ; jsr abs.l, high word = -2/-3/-4
	move.w	d7,(a1)+                        ; $fffe / $fffd / $fffc
	move.w	d0,(a1)+                        ; the number (fixed by relocate_absolute_long)
	movea.l	d6,a2                           ; the line table again
	movea.l	0(a2,d1.w),a2                   ; a2 = the definition line
	addq.l	#6,a2                           ; the parameter list (not worked out)
	moveq	#0,d7                           ; d7 = parameter bytes to remove
	move.b	(a2),d1                         ; d1 = first parameter byte
	cmpi.b	#$46,d1                         ; 'F' or $9d: no parameters to remove
	beq.s	.no_cleanup
	cmpi.b	#$9d,d1                         ; $9d: no parameter list (not worked out)
	beq.s	.no_cleanup
.count_parameters:
	move.b	(a2)+,d1                        ; d1 = next parameter byte
	bpl.s	.not_variable_parameter         ; below $80: end of the variable parameters
	cmpi.b	#$f0,d1                         ; $f0 and up: one more number byte
	bcs.s	.skip_variable_number
	addq.l	#1,a2                           ; skip the extra number byte
.skip_variable_number:
	addq.l	#2,a2                           ; skip the variable number
	andi.w	#$f,d1                          ; type: 0 float, 1 string, 2 integer, 3.. bool/word/byte
	beq.s	.float_parameter                ; float: 8 bytes
	addq.w	#2,d7                           ; two bytes for a short type
	cmpi.w	#$2,d1                          ; string or integer: 4 bytes
	bhi.s	.count_parameters
	addq.w	#2,d7                           ; two more: 4 in all
	bra.s	.count_parameters
.float_parameter:
	addq.w	#8,d7                           ; float: 8 bytes
	bra.s	.count_parameters
.not_variable_parameter:
	cmpi.b	#$32,d1                         ; $32: VAR parameters (addresses) follow (not worked out)
	bne.s	.emit_stack_cleanup
.count_array_parameters:
	addq.w	#4,d7                           ; 4 bytes: an address
	move.b	(a5)+,d1                        ; reads a5, not a2, the source token pointer (looks wrong)
	bpl.s	.emit_stack_cleanup             ; below $80: end of the list
	cmpi.b	#$f0,d1                         ; $f0 and up: one more number byte
	bcs.s	.skip_array_number
	addq.l	#1,a5                           ; skip the extra number byte
.skip_array_number:
	addq.l	#2,a5                           ; skip the variable number
	bclr	#$2,d1                          ; bit 2 set: one more byte (not worked out)
	beq.s	.count_array_parameters
	addq.l	#1,a5                           ; skip the extra byte
	bra.s	.count_array_parameters
.emit_stack_cleanup:
	move.w	d7,d0                           ; d0 = parameter bytes
	bra.w	emit_stack_cleanup_d0           ; addq.l / lea n(sp),sp
.no_cleanup:
	rts
.basic_procedure:
	movea.l	d4,a2                           ; a2 = the address table
	move.l	0(a2,d1.w),d2                   ; d2 = the code offset of the definition (negative = not known yet)
	bmi.s	.emit_long_marker               ; not yet defined: long form
	move.l	code_write_pointer(pc),d3       ; d3 = the code write pointer
	sub.l	code_buffer_start(pc),d3        ; d3 = current code offset
	sub.l	d3,d2                           ; d2 = distance to the definition
	cmpi.l	#$ffff8300,d2                   ; backwards by less than 32000 bytes?
	bcs.s	.emit_long_marker               ; no: long form
	addq.b	#1,d5                           ; short marker $4afe; FN markers become $7f03 / $7f05
	bmi.s	.emit_short_marker              ; procedure: $4afe
	subq.b	#2,d5                           ; FN markers: $7f01 / $7f03
.emit_short_marker:
	move.w	d5,(a1)+                        ; marker
	move.w	d0,(a1)+                        ; the number
	rts
.emit_long_marker:
	move.w	d5,(a1)+                        ; marker
	move.l	d0,(a1)+                        ; the number as a long
	rts

;------------------------------------------------------------------------------
; IR $80cf: GOTO a label: $4af9 nnnn (becomes bra.w) when the label is defined and in range, else $4af8 nnnn.l (jmp).
;------------------------------------------------------------------------------
gen_goto_label:
	move.w	(a0)+,d0                        ; d0 = label number
	ext.l	d0
	move.l	d0,d1                           ; d1 = number
	asl.w	#2,d1                           ; times 4: table offset
	movea.l	label_address_table(pc),a2      ; a2 = code offsets of the labels
	move.l	0(a2,d1.w),d2                   ; d2 = the label's code offset (negative = not known yet)
	bmi.s	.emit_long_marker               ; not yet defined: long form
	move.l	code_write_pointer(pc),d3       ; d3 = the code write pointer
	sub.l	code_buffer_start(pc),d3        ; d3 = current code offset
	sub.l	d3,d2                           ; d2 = distance to the label
	cmpi.l	#$ffff8300,d2                   ; backwards by less than 32000 bytes?
	bcs.s	.emit_long_marker
	move.w	#$4af9,(a1)+                    ; bra.w label marker
	move.w	d0,(a1)+                        ; the number
	rts
.emit_long_marker:
	move.w	#$4af8,(a1)+                    ; jmp abs.l label marker
	move.l	d0,(a1)+                        ; the number as a long
	rts

;------------------------------------------------------------------------------
; IR $80ff: address of a procedure into a2: $4afa nnnn (lea d16(pc),a2) or $4afb nnnn.l (lea abs.l,a2);
; an entry of 0 gives suba.l a2,a2.
;------------------------------------------------------------------------------
gen_procedure_address:
	move.w	(a0)+,d0                        ; d0 = procedure number
	ext.l	d0
	move.l	d0,d1                           ; d1 = number
	asl.w	#2,d1                           ; times 4: table offset
	movea.l	procedure_address_table(pc),a2  ; a2 = code offsets of the procedures
	move.l	0(a2,d1.w),d2                   ; d2 = the procedure's code offset
	bmi.s	.emit_long_marker               ; not yet defined: long form
	beq.s	.no_address                     ; 0: no address (procedure not there)
	move.l	code_write_pointer(pc),d3       ; d3 = the code write pointer
	sub.l	code_buffer_start(pc),d3        ; d3 = current code offset
	sub.l	d3,d2                           ; d2 = distance to the procedure
	cmpi.l	#$ffff8300,d2                   ; backwards by less than 32000 bytes?
	bcs.s	.emit_long_marker               ; no: long form
	move.w	#$4afa,(a1)+                    ; lea d16(pc),a2 proc marker
	move.w	d0,(a1)+                        ; the number
	rts
.emit_long_marker:
	move.w	#$4afb,(a1)+                    ; lea abs.l,a2 proc marker
	move.l	d0,(a1)+                        ; the number as a long
	rts
.no_address:
	move.w	#$95ca,(a1)+                    ; suba.l a2,a2
	rts

;------------------------------------------------------------------------------
; Use the address in a0 according to the next IR word: the PEEK forms $80a3/$80a4/$80a6/$80a7/$80a8/$80aa go to
; gen_peek_byte_at_a0 .. gen_peek_long_offset_at_a0; $8017 -> move.l a0,-(sp); otherwise move.l a0,d0 (the IR word
; is left unread).
;------------------------------------------------------------------------------
gen_use_address_a0:
	move.w	(a0)+,d0                        ; d0 = the IR that uses the address
	cmpi.w	#$80a6,d0                       ; $80a6 long read at a0
	beq.w	gen_peek_long_at_a0
	cmpi.w	#$80aa,d0                       ; $80aa long read with offset
	beq.w	gen_peek_long_offset_at_a0
	cmpi.w	#$80a4,d0                       ; $80a4 signed word read
	beq.w	gen_peek_word_signed_at_a0
	cmpi.w	#$80a8,d0                       ; $80a8 signed word read with offset
	beq.w	gen_peek_word_signed_offset_at_a0
	cmpi.w	#$80a3,d0                       ; $80a3 byte read
	beq.w	gen_peek_byte_at_a0
	cmpi.w	#$80a7,d0                       ; $80a7 byte read with offset
	beq.w	gen_peek_byte_offset_at_a0
	cmpi.w	#$8017,d0                       ; $8017 push long
	beq.s	.push_a0
	subq.l	#2,a0                           ; not consumed: back to that IR word
	move.w	#$2008,(a1)+                    ; move.l a0,d0
	rts
.push_a0:
	move.w	#$2f08,(a1)+                    ; move.l a0,-(sp)
	rts

;------------------------------------------------------------------------------
; IR $8150 var: VARPTR (V:) of a float variable. a2 = float_variable_table, then gen_variable_address_and_use: lea/movea
; var(a5),a0 and the address used by the next IR word (PEEK forms, push, or move.l a0,d0).
;------------------------------------------------------------------------------
gen_ir_8150_varptr_float_var:
	movea.l	float_variable_table(pc),a2     ; float variable

;------------------------------------------------------------------------------
; Emit the variable address (emit_variable_address) and use it (gen_use_address_a0). a2 = variable table.
; The gen_ir_815x entries after it select the table for each variable type.
;------------------------------------------------------------------------------
gen_variable_address_and_use:
	bsr.s	emit_variable_address           ; lea / movea.l var(a5),a0
	bra.s	gen_use_address_a0              ; then use a0 as the next IR wants

;------------------------------------------------------------------------------
; Read a variable number from the IR, look it up in table a2 and emit its address through emit_var_address_a0.
; Exit: d0 = table entry (low word = a5 offset), d7 = high word (negative = indirect).
;------------------------------------------------------------------------------
emit_variable_address:
	move.w	(a0)+,d0                        ; variable number
	asl.w	#2,d0                           ; 4 bytes per entry
	adda.w	d0,a2                           ; a2 = the entry
	move.l	(a2),d0                         ; d0 = the entry: high word flags, low word offset
	move.w	(a2),d7                         ; N set: reached through a pointer
	bra.w	emit_var_address_a0             ; lea var(a5),a0 or movea.l var(a5),a0

;------------------------------------------------------------------------------
; IR $8152 var: VARPTR (V:) of a integer variable. a2 = int_variable_table, then gen_variable_address_and_use: lea/movea
; var(a5),a0 and the address used by the next IR word (PEEK forms, push, or move.l a0,d0).
;------------------------------------------------------------------------------
gen_ir_8152_varptr_integer_var:
	movea.l	int_variable_table(pc),a2       ; a2 = integer variable table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8154 var: VARPTR (V:) of a word variable.  a2 = word_variable_table, then gen_variable_address_and_use: lea/movea
; var(a5),a0 and the address used by the next IR word (PEEK forms, push, or move.l a0,d0).
;------------------------------------------------------------------------------
gen_ir_8154_varptr_word_var:
	movea.l	word_variable_table(pc),a2      ; a2 = word variable table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8155 var: VARPTR (V:) of a byte variable.  a2 = byte_variable_table, then gen_variable_address_and_use: lea/movea
; var(a5),a0 and the address used by the next IR word (PEEK forms, push, or move.l a0,d0).
;------------------------------------------------------------------------------
gen_ir_8155_varptr_byte_var:
	movea.l	byte_variable_table(pc),a2      ; a2 = byte variable table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8153 var: VARPTR (V:) of a bool variable.  a2 = bool_variable_table, then gen_variable_address_and_use: lea/movea
; var(a5),a0 and the address used by the next IR word (PEEK forms, push, or move.l a0,d0).
;------------------------------------------------------------------------------
gen_ir_8153_varptr_bool_var:
	movea.l	bool_variable_table(pc),a2      ; a2 = boolean variable table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8151 var: VARPTR of a string variable: the address of its text.  Emits the descriptor address into a0
; (emit_variable_address with string_variable_table) and move.l (a0),d0 ($2010).
;------------------------------------------------------------------------------
gen_ir_8151_varptr_string_var:
	movea.l	string_variable_table(pc),a2    ; a2 = string variable table
	bsr.s	emit_variable_address           ; lea / movea.l descriptor,a0
	move.w	#$2010,(a1)+                    ; $2010 = move.l (a0),d0: the text pointer from the descriptor
	rts

;------------------------------------------------------------------------------
; IR $815c var: ARRPTR of a string variable: the address of its descriptor (string_variable_table), used as in
; gen_variable_address_and_use.
;------------------------------------------------------------------------------
gen_ir_815c_arrptr_string_var:
	movea.l	string_variable_table(pc),a2    ; a2 = string variable table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $815d arr: ARRPTR of a float array: the address of its descriptor.  a2 = float_array_table, then
; gen_variable_address_and_use.
;------------------------------------------------------------------------------
gen_ir_815d_arrptr_float_array:
	movea.l	float_array_table(pc),a2        ; a2 = float array table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $815e arr: ARRPTR of a string array: the address of its descriptor.  a2 = string_array_table, then
; gen_variable_address_and_use.
;------------------------------------------------------------------------------
gen_ir_815e_arrptr_string_array:
	movea.l	string_array_table(pc),a2       ; a2 = string array table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $815f arr: ARRPTR of a integer array: the address of its descriptor.  a2 = int_array_table, then
; gen_variable_address_and_use.
;------------------------------------------------------------------------------
gen_ir_815f_arrptr_integer_array:
	movea.l	int_array_table(pc),a2          ; a2 = integer array table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8160 arr: ARRPTR of a bool array: the address of its descriptor.  a2 = bool_array_table, then
; gen_variable_address_and_use.
;------------------------------------------------------------------------------
gen_ir_8160_arrptr_bool_array:
	movea.l	bool_array_table(pc),a2         ; a2 = boolean array table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8161 arr: ARRPTR of a word array: the address of its descriptor.  a2 = word_array_table, then
; gen_variable_address_and_use.
;------------------------------------------------------------------------------
gen_ir_8161_arrptr_word_array:
	movea.l	word_array_table(pc),a2         ; a2 = word array table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8162 arr: ARRPTR of a byte array: the address of its descriptor.  a2 = byte_array_table, then
; gen_variable_address_and_use.
;------------------------------------------------------------------------------
gen_ir_8162_arrptr_byte_array:
	movea.l	byte_array_table(pc),a2         ; a2 = byte array table
	bra.s	gen_variable_address_and_use

;------------------------------------------------------------------------------
; IR $8156: VARPTR of a float array element: emit_float_element_address (the index code comes before it), then
; move.l a0,d0 (emit_address_a0_to_d0).
;------------------------------------------------------------------------------
gen_ir_8156_varptr_float_element:
	bsr.w	emit_float_element_address      ; the element address in a0, or RCAF

;------------------------------------------------------------------------------
; Emit move.l a0,d0 ($2008): the address just computed into a0 becomes the integer result.
;------------------------------------------------------------------------------
emit_address_a0_to_d0:
	move.w	#$2008,(a1)+                    ; $2008 = move.l a0,d0
	rts

;------------------------------------------------------------------------------
; IR $8158: VARPTR of a integer array element: emit_int_element_address (the index code comes before it), then
; move.l a0,d0 (emit_address_a0_to_d0).
;------------------------------------------------------------------------------
gen_ir_8158_varptr_integer_element:
	bsr.w	emit_int_element_address        ; the element address in a0, or RCAI
	bra.s	emit_address_a0_to_d0

;------------------------------------------------------------------------------
; IR $815a: VARPTR of a word array element: emit_word_element_address (the index code comes before it), then
; move.l a0,d0 (emit_address_a0_to_d0).
;------------------------------------------------------------------------------
gen_ir_815a_varptr_word_element:
	bsr.w	emit_word_element_address       ; the element address in a0, or RCAW
	bra.s	emit_address_a0_to_d0

;------------------------------------------------------------------------------
; IR $815b: VARPTR of a byte array element: emit_byte_element_address (the index code comes before it), then
; move.l a0,d0 (emit_address_a0_to_d0).
;------------------------------------------------------------------------------
gen_ir_815b_varptr_byte_element:
	bsr.w	emit_byte_element_address       ; the element address in a0, or RCAC
	bra.s	emit_address_a0_to_d0

;------------------------------------------------------------------------------
; IR $8159: VARPTR of a bool array element: emit_bool_element_address (the index code comes before it), then
; move.l a0,d0 (emit_address_a0_to_d0).
;------------------------------------------------------------------------------
gen_ir_8159_varptr_bool_element:
	bsr.w	emit_bool_element_address       ; the element address in a0, or RCAB
	bra.s	emit_address_a0_to_d0

;------------------------------------------------------------------------------
; IR $8157: VARPTR of a string array element: emit_string_element_recall (descriptor address into a0), then
; move.l (a0),d0 ($2010), the address of the text.
;------------------------------------------------------------------------------
gen_ir_8157_varptr_string_element:
	bsr.w	emit_string_element_recall      ; string descriptor of the element into a0
	move.w	#$2010,(a1)+                    ; $2010 = move.l (a0),d0
	rts

;------------------------------------------------------------------------------
; IR $8163 var: a float value parameter of a PROCEDURE/FUNCTION.  lookup_float_var, lea var(a5),a0
; (emit_lea_variable_a0) and a call of library routine $282 VALPARF, which takes the argument from the caller.
;------------------------------------------------------------------------------
gen_ir_8163_value_parameter_float:
	bsr.w	lookup_float_var                ; value parameter: lea var(a5),a0 then the VALPARx routine
	bsr.s	emit_lea_variable_a0            ; lea var(a5),a0
	move.w	#$282,d0                        ; library routine $282 VALPARF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8164 var: a string value parameter of a PROCEDURE/FUNCTION.  lookup_string_var, lea var(a5),a0
; (emit_lea_variable_a0) and a call of library routine $283 VALPARS, which takes the argument from the caller.
;------------------------------------------------------------------------------
gen_ir_8164_value_parameter_string:
	bsr.w	lookup_string_var               ; d0 = offset
	bsr.s	emit_lea_variable_a0            ; lea var(a5),a0
	move.w	#$283,d0                        ; library routine $283 VALPARS
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8165 var: a integer value parameter of a PROCEDURE/FUNCTION.  lookup_integer_var, lea var(a5),a0
; (emit_lea_variable_a0) and a call of library routine $284 VALPARI, which takes the argument from the caller.
;------------------------------------------------------------------------------
gen_ir_8165_value_parameter_integer:
	bsr.w	lookup_integer_var              ; d0 = offset
	bsr.s	emit_lea_variable_a0            ; lea var(a5),a0
	move.w	#$284,d0                        ; library routine $284 VALPARI
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8166 var: a bool value parameter of a PROCEDURE/FUNCTION.  lookup_bool_var, lea var(a5),a0
; (emit_lea_variable_a0) and a call of library routine $285 VALPARB, which takes the argument from the caller.
;------------------------------------------------------------------------------
gen_ir_8166_value_parameter_bool:
	bsr.w	lookup_bool_var                 ; d0 = offset
	bsr.s	emit_lea_variable_a0            ; lea var(a5),a0
	move.w	#$285,d0                        ; library routine $285 VALPARB
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8167 var: a word value parameter of a PROCEDURE/FUNCTION.  lookup_word_var, lea var(a5),a0
; (emit_lea_variable_a0) and a call of library routine $286 VALPARW, which takes the argument from the caller.
;------------------------------------------------------------------------------
gen_ir_8167_value_parameter_word:
	bsr.w	lookup_word_var                 ; d0 = offset
	bsr.s	emit_lea_variable_a0            ; lea var(a5),a0
	move.w	#$286,d0                        ; library routine $286 VALPARW
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8168 var: a byte value parameter of a PROCEDURE/FUNCTION.  lookup_byte_var, lea var(a5),a0
; (emit_lea_variable_a0) and a call of library routine $287 VALPARC, which takes the argument from the caller.
;------------------------------------------------------------------------------
gen_ir_8168_value_parameter_byte:
	bsr.w	lookup_byte_var                 ; d0 = offset
	bsr.s	emit_lea_variable_a0            ; lea var(a5),a0
	move.w	#$287,d0                        ; library routine $287 VALPARC
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; Emit lea d16(a5),a0 ($41ed) with d0 = offset.
;------------------------------------------------------------------------------
emit_lea_variable_a0:
	move.w	#$41ed,(a1)+                    ; $41ed = lea d16(a5),a0
	move.w	d0,(a1)+                        ; offset
	rts

;------------------------------------------------------------------------------
; IR $8169 var: a float VAR parameter.  lookup_float_var, then emit_var_parameter (lea var(a5),a0 / VARPAR).
;------------------------------------------------------------------------------
gen_ir_8169_var_parameter_float:
	bsr.w	lookup_float_var                ; VARPAR: lea of a VAR parameter

;------------------------------------------------------------------------------
; Emit lea var(a5),a0 for offset d0 (emit_lea_variable_a0) and a call of library routine $27b VARPAR, which
; makes the variable slot point at the caller's variable.
;------------------------------------------------------------------------------
emit_var_parameter:
	bsr.s	emit_lea_variable_a0            ; lea var(a5),a0
	move.w	#$27b,d0                        ; library routine $27b VARPAR
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $816a var: a string VAR parameter.  lookup_string_var, then emit_var_parameter (lea var(a5),a0 / VARPAR).
;------------------------------------------------------------------------------
gen_ir_816a_var_parameter_string:
	bsr.w	lookup_string_var               ; d0 = offset, N = through pointer
	bra.s	emit_var_parameter

;------------------------------------------------------------------------------
; IR $816b var: a integer VAR parameter.  lookup_integer_var, then emit_var_parameter (lea var(a5),a0 / VARPAR).
;------------------------------------------------------------------------------
gen_ir_816b_var_parameter_integer:
	bsr.w	lookup_integer_var              ; d0 = offset, N = through pointer
	bra.s	emit_var_parameter

;------------------------------------------------------------------------------
; IR $816c var: a bool VAR parameter.  lookup_bool_var, then emit_var_parameter (lea var(a5),a0 / VARPAR).
;------------------------------------------------------------------------------
gen_ir_816c_var_parameter_bool:
	bsr.w	lookup_bool_var                 ; d0 = offset, N = through pointer
	bra.s	emit_var_parameter

;------------------------------------------------------------------------------
; IR $816d var: a word VAR parameter.  lookup_word_var, then emit_var_parameter (lea var(a5),a0 / VARPAR).
;------------------------------------------------------------------------------
gen_ir_816d_var_parameter_word:
	bsr.w	lookup_word_var                 ; d0 = offset, N = through pointer
	bra.s	emit_var_parameter

;------------------------------------------------------------------------------
; IR $816e var: a byte VAR parameter.  lookup_byte_var, then emit_var_parameter (lea var(a5),a0 / VARPAR).
;------------------------------------------------------------------------------
gen_ir_816e_var_parameter_byte:
	bsr.w	lookup_byte_var                 ; d0 = offset, N = through pointer
	bra.s	emit_var_parameter

;------------------------------------------------------------------------------
; IR $816f arr: a float array VAR parameter (name()).  lookup_float_array, then emit_var_parameter_array.
;------------------------------------------------------------------------------
gen_ir_816f_var_parameter_float_array:
	bsr.w	lookup_float_array              ; d0 = descriptor offset; reads two IR words

;------------------------------------------------------------------------------
; lookup_array_entry read two IR words but an array parameter has only its number: a0 goes back one word, then
; emit_var_parameter (lea var(a5),a0 / VARPAR).
;------------------------------------------------------------------------------
emit_var_parameter_array:
	subq.l	#2,a0                           ; give back the second IR word read by the array lookup
	bra.s	emit_var_parameter

;------------------------------------------------------------------------------
; IR $8170 arr: a string array VAR parameter (name()).  lookup_string_array, then emit_var_parameter_array.
;------------------------------------------------------------------------------
gen_ir_8170_var_parameter_string_array:
	bsr.w	lookup_string_array             ; d0 = descriptor offset; reads two IR words
	bra.s	emit_var_parameter_array

;------------------------------------------------------------------------------
; IR $8171 arr: a integer array VAR parameter (name()).  lookup_integer_array, then emit_var_parameter_array.
;------------------------------------------------------------------------------
gen_ir_8171_var_parameter_integer_array:
	bsr.w	lookup_integer_array            ; d0 = descriptor offset; reads two IR words
	bra.s	emit_var_parameter_array

;------------------------------------------------------------------------------
; IR $8172 arr: a bool array VAR parameter (name()).  lookup_bool_array, then emit_var_parameter_array.
;------------------------------------------------------------------------------
gen_ir_8172_var_parameter_bool_array:
	bsr.w	lookup_bool_array               ; d0 = descriptor offset; reads two IR words
	bra.s	emit_var_parameter_array

;------------------------------------------------------------------------------
; IR $8173 arr: a word array VAR parameter (name()).  lookup_word_array, then emit_var_parameter_array.
;------------------------------------------------------------------------------
gen_ir_8173_var_parameter_word_array:
	bsr.w	lookup_word_array               ; d0 = descriptor offset; reads two IR words
	bra.s	emit_var_parameter_array

;------------------------------------------------------------------------------
; IR $8174 arr: a byte array VAR parameter (name()).  lookup_byte_array, then emit_var_parameter_array.
;------------------------------------------------------------------------------
gen_ir_8174_var_parameter_byte_array:
	bsr.w	lookup_byte_array               ; d0 = descriptor offset; reads two IR words
	bra.s	emit_var_parameter_array

;------------------------------------------------------------------------------
; IR $8175 var: pass a float variable to a VAR parameter: push its address.  lookup_float_var, then
; emit_push_variable_address.
;------------------------------------------------------------------------------
gen_ir_8175_var_argument_float:
	bsr.w	lookup_float_var                ; d0 = offset, N = through pointer

;------------------------------------------------------------------------------
; With the flags of a variable lookup (d0 = offset): pea var(a5) ($486d), or move.l var(a5),-(sp) ($2f2d) for a
; pointer variable, whose slot already holds the address.
;------------------------------------------------------------------------------
emit_push_variable_address:
	bmi.s	.push_indirect                  ; N: the slot holds the variable's address
	move.w	#$486d,(a1)+                    ; pea d16(a5)
	move.w	d0,(a1)+                        ; offset
	rts
.push_indirect:
	move.w	#$2f2d,(a1)+                    ; move.l d16(a5),-(sp)
	move.w	d0,(a1)+                        ; offset
	rts

;------------------------------------------------------------------------------
; IR $8176 var: pass a string variable to a VAR parameter: push its address.  lookup_string_var, then
; emit_push_variable_address.
;------------------------------------------------------------------------------
gen_ir_8176_var_argument_string:
	bsr.w	lookup_string_var               ; d0 = offset, N = through pointer
	bra.s	emit_push_variable_address

;------------------------------------------------------------------------------
; IR $8177 var: pass a integer variable to a VAR parameter: push its address.  lookup_integer_var, then
; emit_push_variable_address.
;------------------------------------------------------------------------------
gen_ir_8177_var_argument_integer:
	bsr.w	lookup_integer_var              ; d0 = offset, N = through pointer
	bra.s	emit_push_variable_address

;------------------------------------------------------------------------------
; IR $8178 var: pass a bool variable to a VAR parameter: push its address.  lookup_bool_var, then
; emit_push_variable_address.
;------------------------------------------------------------------------------
gen_ir_8178_var_argument_bool:
	bsr.w	lookup_bool_var                 ; d0 = the variable's offset, flags from its pointer bit
	bra.s	emit_push_variable_address

;------------------------------------------------------------------------------
; IR $8179 var: pass a word variable to a VAR parameter: push its address.  lookup_word_var, then
; emit_push_variable_address.
;------------------------------------------------------------------------------
gen_ir_8179_var_argument_word:
	bsr.w	lookup_word_var                 ; d0 = the variable's offset, flags from its pointer bit
	bra.s	emit_push_variable_address

;------------------------------------------------------------------------------
; IR $817a var: pass a byte variable to a VAR parameter: push its address.  lookup_byte_var, then
; emit_push_variable_address.
;------------------------------------------------------------------------------
gen_ir_817a_var_argument_byte:
	bsr.w	lookup_byte_var                 ; d0 = the variable's offset, flags from its pointer bit
	bra.s	emit_push_variable_address

;------------------------------------------------------------------------------
; IR $817b arr: pass a float array to a VAR parameter: push its descriptor address.  lookup_float_array, then
; emit_push_array_address.
;------------------------------------------------------------------------------
gen_ir_817b_var_argument_float_array:
	bsr.w	lookup_float_array              ; d0 = descriptor offset; the lookup read two IR words

;------------------------------------------------------------------------------
; a0 back one IR word (the array lookup read two), then emit_push_variable_address.
;------------------------------------------------------------------------------
emit_push_array_address:
	subq.l	#2,a0                           ; give back the second IR word read by the array lookup
	bra.s	emit_push_variable_address

;------------------------------------------------------------------------------
; IR $817c arr: pass a string array to a VAR parameter: push its descriptor address.  lookup_string_array, then
; emit_push_array_address.
;------------------------------------------------------------------------------
gen_ir_817c_var_argument_string_array:
	bsr.w	lookup_string_array             ; d0 = descriptor offset; the lookup read two IR words
	bra.s	emit_push_array_address

;------------------------------------------------------------------------------
; IR $817d arr: pass a integer array to a VAR parameter: push its descriptor address.  lookup_integer_array, then
; emit_push_array_address.
;------------------------------------------------------------------------------
gen_ir_817d_var_argument_integer_array:
	bsr.w	lookup_integer_array            ; d0 = descriptor offset; the lookup read two IR words
	bra.s	emit_push_array_address

;------------------------------------------------------------------------------
; IR $817e arr: pass a bool array to a VAR parameter: push its descriptor address.  lookup_bool_array, then
; emit_push_array_address.
;------------------------------------------------------------------------------
gen_ir_817e_var_argument_bool_array:
	bsr.w	lookup_bool_array               ; d0 = descriptor offset; the lookup read two IR words
	bra.s	emit_push_array_address

;------------------------------------------------------------------------------
; IR $817f arr: pass a word array to a VAR parameter: push its descriptor address.  lookup_word_array, then
; emit_push_array_address.
;------------------------------------------------------------------------------
gen_ir_817f_var_argument_word_array:
	bsr.w	lookup_word_array               ; d0 = descriptor offset; the lookup read two IR words
	bra.s	emit_push_array_address

;------------------------------------------------------------------------------
; IR $8180 arr: pass a byte array to a VAR parameter: push its descriptor address.  lookup_byte_array, then
; emit_push_array_address.
;------------------------------------------------------------------------------
gen_ir_8180_var_argument_byte_array:
	bsr.w	lookup_byte_array               ; d0 = descriptor offset; the lookup read two IR words
	bra.s	emit_push_array_address

;------------------------------------------------------------------------------
; IR $8181 var: LOCAL float variable.  lookup_float_var, d1 = library routine $27c LOCALF, then emit_local_variable.
;------------------------------------------------------------------------------
gen_ir_8181_local_float:
	bsr.w	lookup_float_var                ; LOCAL: lea then LOCALF..LOCALC
	move.w	#$27c,d1                        ; library routine $27c LOCALF
	bra.s	emit_local_variable

;------------------------------------------------------------------------------
; IR $81c9 var: string variable = "".  Emits its descriptor address into a0 (emit_string_var_address_a0) and a
; call of library routine $f5 EMPSTOS.
;------------------------------------------------------------------------------
gen_ir_81c9_clear_string_var:
	bsr.w	emit_string_var_address_a0      ; lea/movea of the string descriptor into a0
	move.w	#$f5,d0                         ; EMPSTOS
	bra.w	emit_library_call               ; emit jsr EMPSTOS

;------------------------------------------------------------------------------
; IR $8182 var: LOCAL string variable.  lookup_string_var, d1 = library routine $27d LOCALS, then emit_local_variable.
;------------------------------------------------------------------------------
gen_ir_8182_local_string:
	bsr.w	lookup_string_var               ; d0 = the variable's offset
	move.w	#$27d,d1                        ; library routine $27d LOCALS

;------------------------------------------------------------------------------
; Emit lea var(a5),a0 ($41ed, offset d0) and a call of the LOCALx library routine in d1, which saves the
; variable's value for the end of the procedure.
;------------------------------------------------------------------------------
emit_local_variable:
	move.w	#$41ed,(a1)+                    ; $41ed = lea d16(a5),a0
	move.w	d0,(a1)+
	move.w	d1,d0                           ; d0 = the LOCALx routine number for the call
	bra.w	emit_library_call               ; emit jsr LOCALx

;------------------------------------------------------------------------------
; IR $8183 var: LOCAL integer variable.  lookup_integer_var, d1 = library routine $27e LOCALI, then emit_local_variable.
;------------------------------------------------------------------------------
gen_ir_8183_local_integer:
	bsr.w	lookup_integer_var
	move.w	#$27e,d1                        ; library routine $27e LOCALI
	bra.s	emit_local_variable

;------------------------------------------------------------------------------
; IR $8184 var: LOCAL bool variable.  lookup_bool_var, d1 = library routine $27f LOCALB, then emit_local_variable.
;------------------------------------------------------------------------------
gen_ir_8184_local_bool:
	bsr.w	lookup_bool_var
	move.w	#$27f,d1                        ; library routine $27f LOCALB
	bra.s	emit_local_variable

;------------------------------------------------------------------------------
; IR $8185 var: LOCAL word variable.  lookup_word_var, d1 = library routine $280 LOCALW, then emit_local_variable.
;------------------------------------------------------------------------------
gen_ir_8185_local_word:
	bsr.w	lookup_word_var
	move.w	#$280,d1                        ; library routine $280 LOCALW
	bra.s	emit_local_variable

;------------------------------------------------------------------------------
; IR $8186 var: LOCAL byte variable.  lookup_byte_var, d1 = library routine $281 LOCALC, then emit_local_variable.
;------------------------------------------------------------------------------
gen_ir_8186_local_byte:
	bsr.w	lookup_byte_var
	move.w	#$281,d1                        ; library routine $281 LOCALC
	bra.s	emit_local_variable

;------------------------------------------------------------------------------
; IR $81c2 var: ABSOLUTE of a float variable (address in d0).  lookup_float_var, then emit_store_absolute_address.
;------------------------------------------------------------------------------
gen_ir_81c2_absolute_float:
	bsr.w	lookup_float_var

;------------------------------------------------------------------------------
; Emit move.l d0,var(a5) ($2b40, offset d0 of the lookup): the variable's slot (a pointer variable) gets the
; address from d0.
;------------------------------------------------------------------------------
emit_store_absolute_address:
	move.w	#$2b40,(a1)+                    ; move.l d0,d16(a5)
	move.w	d0,(a1)+
	rts

;------------------------------------------------------------------------------
; IR $81c3 var: ABSOLUTE of a string variable (address in d0).  lookup_string_var, then emit_store_absolute_address.
;------------------------------------------------------------------------------
gen_ir_81c3_absolute_string:
	bsr.w	lookup_string_var               ; d0 = the variable's offset
	bra.s	emit_store_absolute_address

;------------------------------------------------------------------------------
; IR $81c4 var: ABSOLUTE of a integer variable (address in d0).  lookup_integer_var, then emit_store_absolute_address.
;------------------------------------------------------------------------------
gen_ir_81c4_absolute_integer:
	bsr.w	lookup_integer_var
	bra.s	emit_store_absolute_address

;------------------------------------------------------------------------------
; IR $81c5 var: ABSOLUTE of a bool variable (address in d0).  lookup_bool_var, then emit_store_absolute_address.
;------------------------------------------------------------------------------
gen_ir_81c5_absolute_bool:
	bsr.w	lookup_bool_var
	bra.s	emit_store_absolute_address

;------------------------------------------------------------------------------
; IR $81c6 var: ABSOLUTE of a word variable (address in d0).  lookup_word_var, then emit_store_absolute_address.
;------------------------------------------------------------------------------
gen_ir_81c6_absolute_word:
	bsr.w	lookup_word_var
	bra.s	emit_store_absolute_address

;------------------------------------------------------------------------------
; IR $81c7 var: ABSOLUTE of a byte variable (address in d0).  lookup_byte_var, then emit_store_absolute_address.
;------------------------------------------------------------------------------
gen_ir_81c7_absolute_byte:
	bsr.w	lookup_byte_var
	bra.s	emit_store_absolute_address

;------------------------------------------------------------------------------
; IR $8187 arr: ERASE of a float array.  lookup_float_array, then emit_erase_array.
;------------------------------------------------------------------------------
gen_ir_8187_erase_float_array:
	bsr.w	lookup_float_array

;------------------------------------------------------------------------------
; Emit the array descriptor address into a0 (emit_variable_address_a0, which also gives back the second IR word
; read by the lookup) and a call of library routine $28e ERASE.
;------------------------------------------------------------------------------
emit_erase_array:
	bsr.w	emit_variable_address_a0
	move.w	#$28e,d0                        ; ERASE
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $8188 arr: ERASE of a string array.  lookup_string_array, then emit_erase_array.
;------------------------------------------------------------------------------
gen_ir_8188_erase_string_array:
	bsr.w	lookup_string_array
	bra.s	emit_erase_array

;------------------------------------------------------------------------------
; IR $8189 arr: ERASE of a integer array.  lookup_integer_array, then emit_erase_array.
;------------------------------------------------------------------------------
gen_ir_8189_erase_integer_array:
	bsr.w	lookup_integer_array
	bra.s	emit_erase_array

;------------------------------------------------------------------------------
; IR $818a arr: ERASE of a bool array.  lookup_bool_array, then emit_erase_array.
;------------------------------------------------------------------------------
gen_ir_818a_erase_bool_array:
	bsr.w	lookup_bool_array
	bra.s	emit_erase_array

;------------------------------------------------------------------------------
; IR $818b arr: ERASE of a word array.  lookup_word_array, then emit_erase_array.
;------------------------------------------------------------------------------
gen_ir_818b_erase_word_array:
	bsr.w	lookup_word_array
	bra.s	emit_erase_array

;------------------------------------------------------------------------------
; IR $818c arr: ERASE of a byte array.  lookup_byte_array, then emit_erase_array.
;------------------------------------------------------------------------------
gen_ir_818c_erase_byte_array:
	bsr.w	lookup_byte_array
	bra.s	emit_erase_array

;------------------------------------------------------------------------------
; IR $81a8: SWAP of two strings (descriptor addresses in a0/a1 or on the stack): library routine $295 SWAPS.
;------------------------------------------------------------------------------
gen_ir_81a8_swap_strings:
	move.w	#$295,d0                        ; SWAPS
	bra.w	emit_library_call               ; emit jsr SWAPS

;------------------------------------------------------------------------------
; IR $81a7: SWAP of two floats at (a0) and (a1): two long exchanges (emit_swap_long_a0_a1 twice, 8 bytes).
;------------------------------------------------------------------------------
gen_ir_81a7_swap_floats:
	bsr.s	emit_swap_long_a0_a1            ; first long of the 8-byte float
	bra.s	emit_swap_long_a0_a1            ; second long; returns through the rts there

;------------------------------------------------------------------------------
; IR $81ad: SWAP of two whole arrays: the 6-byte descriptors at (a0) and (a1) are exchanged, a long
; (emit_swap_long_a0_a1) then a word (emit_swap_word_a0_a1).
;------------------------------------------------------------------------------
gen_ir_81ad_swap_arrays:
	bsr.s	emit_swap_long_a0_a1            ; first long of the descriptor, then the word below

;------------------------------------------------------------------------------
; IR $81ab: SWAP of two words: move.w (a0),d0 / move.w (a1),(a0)+ / move.w d0,(a1)+.  Also the tail of
; gen_ir_81ad_swap_arrays.
;------------------------------------------------------------------------------
emit_swap_word_a0_a1:
	move.l	#$301030d1,(a1)+                ; $3010 $30d1 = move.w (a0),d0 / move.w (a1),(a0)+
	move.w	#$32c0,(a1)+                    ; $32c0 = move.w d0,(a1)+
	rts

;------------------------------------------------------------------------------
; Emit move.l (a0),d0 / move.l (a1),(a0)+ / move.l d0,(a1)+: exchange a long (SWAP); the entries around it do
; floats (3 calls), words and bytes.
;------------------------------------------------------------------------------
emit_swap_long_a0_a1:
	move.l	#$201020d1,(a1)+                ; $2010 $20d1 = move.l (a0),d0 / move.l (a1),(a0)+
	move.w	#$22c0,(a1)+                    ; $22c0 = move.l d0,(a1)+
	rts

;------------------------------------------------------------------------------
; IR $81ac (byte) and IR $81aa (boolean, scalars only): SWAP of two bytes: move.b (a0),d0 / move.b (a1),(a0)+ /
; move.b d0,(a1)+.
;------------------------------------------------------------------------------
gen_ir_81ac_swap_bytes:
	move.l	#$101010d1,(a1)+                ; $1010 $10d1 = move.b (a0),d0 / move.b (a1),(a0)+
	move.w	#$12c0,(a1)+                    ; $12c0 = move.b d0,(a1)+
	rts

;------------------------------------------------------------------------------
; IR $819b var: a float variable as a SWAP operand.  a2 = float_variable_table, then emit_swap_operand_address.
;------------------------------------------------------------------------------
gen_ir_819b_swap_operand_float_var:
	movea.l	float_variable_table(pc),a2     ; a2 = float variable table for emit_variable_address

;------------------------------------------------------------------------------
; Emit the address of SWAP operand variable (table a2) into a0 (emit_variable_address).  When the first
; operand's push ($8018) follows: it is consumed; if the second operand is a scalar too ($819b-$81a0) the lea/movea
; is turned to a1 and the $8023 pop after the second operand becomes $8028 (no code); otherwise move.l a0,-(sp).
;------------------------------------------------------------------------------
emit_swap_operand_address:
	bsr.w	emit_variable_address           ; lea/movea var(a5),a0; a0 = next IR word after the operand
	cmpi.w	#$8018,(a0)                     ; $8018: push of the first operand follows
	bne.s	.second_operand_done
	addq.l	#2,a0                           ; consume the $8018
	move.w	(a0),d0                         ; d0 = IR code of the second operand
	subi.w	#$819b,d0                       ; $819b-$81a0
	cmpi.w	#$6,d0                          ; six scalar SWAP operand codes
	bcc.s	.push_a0                        ; second operand not a scalar: push a0
	move.w	#$8028,4(a0)                    ; the $8023 after the second operand: no code needed
	addi.w	#$200,-$4(a1)                   ; lea/movea ...,a0 -> ...,a1
	rts
.push_a0:
	move.w	#$2f08,(a1)+                    ; $2f08 = move.l a0,-(sp)
.second_operand_done:
	rts

;------------------------------------------------------------------------------
; IR $819d var: a integer variable as a SWAP operand.  a2 = int_variable_table, then emit_swap_operand_address.
;------------------------------------------------------------------------------
gen_ir_819d_swap_operand_integer_var:
	movea.l	int_variable_table(pc),a2
	bra.s	emit_swap_operand_address

;------------------------------------------------------------------------------
; IR $819f var: a word variable as a SWAP operand.  a2 = word_variable_table, then emit_swap_operand_address.
;------------------------------------------------------------------------------
gen_ir_819f_swap_operand_word_var:
	movea.l	word_variable_table(pc),a2
	bra.s	emit_swap_operand_address

;------------------------------------------------------------------------------
; IR $81a0 var: a byte variable as a SWAP operand.  a2 = byte_variable_table, then emit_swap_operand_address.
;------------------------------------------------------------------------------
gen_ir_81a0_swap_operand_byte_var:
	movea.l	byte_variable_table(pc),a2
	bra.s	emit_swap_operand_address

;------------------------------------------------------------------------------
; IR $819e var: a bool variable as a SWAP operand.  a2 = bool_variable_table, then emit_swap_operand_address.
;------------------------------------------------------------------------------
gen_ir_819e_swap_operand_bool_var:
	movea.l	bool_variable_table(pc),a2
	bra.s	emit_swap_operand_address

;------------------------------------------------------------------------------
; IR $819c var: a string variable as a SWAP operand.  a2 = string_variable_table, then emit_swap_operand_address.
;------------------------------------------------------------------------------
gen_ir_819c_swap_operand_string_var:
	movea.l	string_variable_table(pc),a2
	bra.s	emit_swap_operand_address

;------------------------------------------------------------------------------
; IR $81a3: a integer array element as a SWAP operand.  emit_int_element_address, then emit_swap_element_address.
;------------------------------------------------------------------------------
gen_ir_81a3_swap_operand_integer_element:
	bsr.w	emit_int_element_address
	bra.s	emit_swap_element_address

;------------------------------------------------------------------------------
; IR $81a5: a word array element as a SWAP operand.  emit_word_element_address, then emit_swap_element_address.
;------------------------------------------------------------------------------
gen_ir_81a5_swap_operand_word_element:
	bsr.w	emit_word_element_address
	bra.s	emit_swap_element_address

;------------------------------------------------------------------------------
; IR $81a6: a byte array element as a SWAP operand.  emit_byte_element_address, then emit_swap_element_address.
;------------------------------------------------------------------------------
gen_ir_81a6_swap_operand_byte_element:
	bsr.w	emit_byte_element_address
	bra.s	emit_swap_element_address

;------------------------------------------------------------------------------
; IR $81a2: a string array element as a SWAP operand.  emit_string_element_recall, then emit_swap_element_address.
;------------------------------------------------------------------------------
gen_ir_81a2_swap_operand_string_element:
	bsr.w	emit_string_element_recall
	bra.s	emit_swap_element_address

;------------------------------------------------------------------------------
; IR $81a1: a float array element as a SWAP operand.  emit_float_element_address, then emit_swap_element_address.
;------------------------------------------------------------------------------
gen_ir_81a1_swap_operand_float_element:
	bsr.w	emit_float_element_address

;------------------------------------------------------------------------------
; After a SWAP operand element address has been emitted into a0: when the first operand's push ($8018) follows it
; is consumed, and
; - after a library call ($6101 marker, string element): second operand scalar -> movea.l a0,a1 and its $8023
;   becomes $8028; else move.l a0,-(sp);
; - second operand scalar ($819b-$81a0): the lea is turned to a1, its $8023 becomes $8028;
; - otherwise the IR of the second operand's index is scanned ($800b/$800c skip two words, $8087 $8088 $8090
;   $8091 $809c $809d one) for its element code $81a1-$81a6: found -> lea to a1 and the $8023 after it becomes
;   $8028; not found -> the lea d(a0,Xn),a0 becomes pea d(a0,Xn) ($4870).
;------------------------------------------------------------------------------
emit_swap_element_address:
	cmpi.w	#$8018,(a0)                     ; $8018: push of the first operand follows?
	bne.s	.element_done                   ; no: the second operand, address stays in a0
	cmpi.w	#$6101,-$4(a1)                  ; $6101 = library call marker: the address came from a routine
	addq.l	#2,a0                           ; consume the $8018 (flags kept from the cmpi)
	beq.s	.library_result                 ; string element came from a library routine
	move.w	(a0),d0                         ; d0 = IR code of the second operand
	subi.w	#$819b,d0
	cmpi.w	#$6,d0                          ; six scalar SWAP operand codes $819b-$81a0
	bcc.s	.scan_ir                        ; not a scalar: look for the second element's code
	move.w	#$8028,4(a0)                    ; the $8023 after the second operand: no code needed
	addi.w	#$200,-$4(a1)                   ; lea/movea ...,a0 -> ...,a1
	rts
.scan_ir:
	movea.l	a0,a2                           ; a2 scans the second operand's index IR
	bra.s	.next_scanned_word
.skip_two_ir_words:
	addq.l	#2,a2                           ; operand word of a two-word IR item
.skip_one_ir_word:
	addq.l	#2,a2                           ; operand word of a one-word IR item
.next_scanned_word:
	move.w	(a2)+,d0                        ; d0 = next IR word of the second operand
	cmpi.w	#$800b,d0                       ; $800b: two operand words
	beq.s	.skip_two_ir_words
	cmpi.w	#$800c,d0                       ; $800c: two operand words
	beq.s	.skip_two_ir_words
	cmpi.w	#$8087,d0                       ; $8087-$809d: one operand word each
	beq.s	.skip_one_ir_word
	cmpi.w	#$8088,d0
	beq.s	.skip_one_ir_word
	cmpi.w	#$8090,d0
	beq.s	.skip_one_ir_word
	cmpi.w	#$8091,d0
	beq.s	.skip_one_ir_word
	cmpi.w	#$809c,d0
	beq.s	.skip_one_ir_word
	cmpi.w	#$809d,d0
	beq.s	.skip_one_ir_word
	subi.w	#$81a1,d0                       ; element code $81a1-$81a6 of the second operand?
	cmpi.w	#$6,d0
	bcs.s	.retarget_to_a1                 ; found: the first address goes to a1
	move.w	#$4870,-$4(a1)                  ; $4870 = pea d8(a0,Xn): push the element address instead
.element_done:
	rts
.retarget_to_a1:
	move.w	#$8028,4(a2)                    ; the $8023 after the second element: no code needed
	addi.w	#$200,-$4(a1)                   ; lea ...,a0 -> ...,a1
	rts
.library_result:
	move.w	(a0),d0                         ; d0 = IR code of the second operand
	subi.w	#$819b,d0                       ; six scalar SWAP operand codes $819b-$81a0
	cmpi.w	#$6,d0
	bcc.s	.push_library_result            ; second operand not a scalar: push a0
	move.w	#$8028,4(a0)                    ; the $8023 after the second operand: no code needed
	move.w	#$2248,(a1)+                    ; $2248 = movea.l a0,a1
	rts
.push_library_result:
	move.w	#$2f08,(a1)+                    ; $2f08 = move.l a0,-(sp)
	rts

;------------------------------------------------------------------------------
; IR $81a4: a boolean array element as a SWAP operand: only its address (emit_bool_element_address); a SWAP with
; a boolean element goes through the library routines SWPBVA/SWPBAV/SWPBAA.
;------------------------------------------------------------------------------
gen_ir_81a4_swap_operand_bool_element:
	bra.w	emit_bool_element_address

;------------------------------------------------------------------------------
; IR $81fd: movem.l d5/a0,-(sp) ($48e70480).  Written by parse_swap in place of the first operand's push ($8018)
; for a boolean SWAP whose first operand is an array element (element address a0 and bit number d5).
;------------------------------------------------------------------------------
gen_ir_81fd_push_d5_a0:
	move.l	#$48e70480,(a1)+                ; $48e7 $0480 = movem.l d5/a0,-(sp)
	rts

;------------------------------------------------------------------------------
; IR $81fe: movem.l (sp)+,d4/a1 ($4cdf0210), the matching pop (in place of $8023): the first operand's address and
; bit number arrive in a1/d4 for SWPBAV/SWPBAA.
;------------------------------------------------------------------------------
gen_ir_81fe_pop_d4_a1:
	move.l	#$4cdf0210,(a1)+                ; $4cdf $0210 = movem.l (sp)+,d4/a1
	rts

;------------------------------------------------------------------------------
; Add the integer constant d0 to d0 in the generated code. Directly after move.l d16(a5),d0 ($202d) while
; previous_ir_code is $803f the load is turned into moveq/move.l #n,d0 + add.l d16(a5),d0; otherwise
; addq/subq (emit_addq_word/emit_subq_word_negated) or addi.w #n,d0 ($0640).
;------------------------------------------------------------------------------
gen_add_constant_d0:
	ext.l	d0                              ; d0 = the constant; 0 needs no code
	beq.s	.add_nothing
	bsr.w	drop_ext_if_word_use            ; remove a pending ext.l d0 if only the word is used
	cmpi.w	#$803f,previous_ir_code         ; previous IR $803f: integer variable loaded into d0
	bne.s	.add_immediate                  ; otherwise a plain add of the constant
	cmpi.w	#$202d,-$4(a1)                  ; move.l d16(a5),d0 just emitted
	bne.s	.add_immediate
	move.l	-(a1),d2                        ; take back the load; d2 = $202d and the offset
	move.b	d0,d1                           ; does the constant fit a byte?
	ext.w	d1
	cmp.w	d0,d1
	bne.s	.long_constant                  ; no: move.l #n,d0
	move.w	#$7000,d7                       ; $7000 = moveq #0,d0, constant in the low byte
	move.b	d0,d7
	move.w	d7,(a1)+                        ; moveq #n,d0
.emit_add_variable:
	move.w	#$d0ad,(a1)+                    ; add.l d16(a5),d0
	move.w	d2,(a1)+                        ; the variable's offset (low word of d2)
	bra.w	mark_result_modified            ; d0 changed: forget its known state
.long_constant:
	move.w	#$203c,(a1)+                    ; $203c = move.l #n,d0
	move.l	d0,(a1)+                        ; the constant
	bra.s	.emit_add_variable
.add_immediate:
	cmpi.w	#$8,d0                          ; 1..8: addq.w #n,d0
	bls.w	emit_addq_word
	cmpi.w	#$fff8,d0                       ; -8..-1: subq.w #-n,d0
	bcc.w	emit_subq_word_negated
	move.w	#$640,(a1)+                     ; addi.w #n,d0
	move.w	d0,(a1)+                        ; the constant
.add_nothing:
	rts

;------------------------------------------------------------------------------
; Subtract the constant d0 (as gen_add_constant_d0; the load is folded only when the next IR word is $8078 and
; previous_ir_code is $803f, with the constant negated); otherwise subq/addq or subi.w #n,d0 ($0440).
;------------------------------------------------------------------------------
gen_sub_constant_d0:
	ext.l	d0                              ; d0 = the constant; 0 needs no code
	beq.s	.sub_nothing
	bsr.w	drop_ext_if_word_use            ; remove a pending ext.l d0 if only the word is used
	cmpi.w	#$8078,(a0)                     ; next IR $8078 (meaning not worked out here)
	bne.s	.sub_immediate
	cmpi.w	#$803f,previous_ir_code         ; previous IR $803f: integer variable loaded into d0
	bne.s	.sub_immediate
	addq.l	#2,a0                           ; consume the $8078
	cmpi.w	#$202d,-$4(a1)                  ; move.l d16(a5),d0 just emitted?
	bne.s	.sub_immediate
	move.l	-(a1),d2                        ; take back the load; d2 = $202d and the offset
	neg.w	d0                              ; the constant negated
	move.b	d0,d1                           ; does it fit a byte?
	ext.w	d1
	cmp.w	d0,d1
	bne.s	.word_constant                  ; no: move.w #n,d0
	move.w	#$7000,d7                       ; $7000 = moveq #0,d0, constant in the low byte
	move.b	d0,d7
	move.w	d7,(a1)+                        ; moveq #-n,d0
.emit_add_variable:
	move.w	#$d0ad,(a1)+                    ; $d0ad = add.l d16(a5),d0
	move.l	d2,(a1)+                        ; move.l: writes $202d and the offset, unlike the .w at $e0e6
	bra.w	mark_result_modified
.word_constant:
	move.w	#$303c,(a1)+                    ; $303c = move.w #n,d0
	move.w	d0,(a1)+
	bra.s	.emit_add_variable
.sub_immediate:
	cmpi.w	#$8,d0                          ; 1..8: subq.w #n,d0
	bls.w	emit_subq_word
	cmpi.w	#$fff8,d0                       ; -8..-1: addq.w #-n,d0
	bcc.w	emit_addq_word_negated
	move.w	#$440,(a1)+                     ; subi.w #n,d0
	move.w	d0,(a1)+
	bra.w	mark_result_modified            ; d0 changed: forget its known state
.sub_nothing:
	rts

;------------------------------------------------------------------------------
; Multiply d0.w by the constant d0: 0 -> moveq #0,d0; a power of two -> neg / asl.w #8 / asl.w #n / add.w d0,d0;
; otherwise muls.w #n,d0 ($c1fc) and ext_l_d0_code_address cleared.
;------------------------------------------------------------------------------
gen_mul_word_constant_d0:
	move.w	d0,d1                           ; d1 = |constant| for the power-of-two test
	beq.s	.times_zero                     ; times 0
	bpl.s	.power_of_two_test
	neg.w	d1
.power_of_two_test:
	add.w	d1,d1                           ; shift left until the top set bit falls out
	bcc.s	.power_of_two_test
	beq.s	.power_of_two                   ; nothing left: a single bit, a power of two
	move.w	#$c1fc,(a1)+                    ; muls.w #n,d0
	move.w	d0,(a1)+
	clr.l	ext_l_d0_code_address           ; muls.w drops the word use: no ext.l d0 pending
	rts
.times_zero:
	move.w	#$7000,(a1)+                    ; moveq #0,d0
	rts
.power_of_two:
	tst.w	d0                              ; negative power of two?
	bpl.s	.count_shift
	move.w	#$4440,(a1)+                    ; neg.w d0
	neg.w	d0                              ; make the constant positive
.count_shift:
	moveq	#15,d7                          ; d7 = bit number of the constant: the shift count
.find_top_bit:
	btst	d7,d0
	dbne	d7,.find_top_bit
	cmpi.w	#$8,d7                          ; more than 8: asl.w #8 first
	bls.s	.shift_rest
	move.w	#$e140,(a1)+                    ; asl.w #8,d0
.shift_rest:
	moveq	#7,d0                           ; d0 = remaining shift count 0..7
	and.w	d7,d0
	beq.s	.mul_done                       ; 0: no shift left
	cmpi.w	#$1,d0                          ; times 2 is add.w d0,d0
	beq.s	.times_two
	ror.w	#7,d0                           ; count to bits 9-11 (7 rotates right = 9 left)
	ori.w	#$e140,d0                       ; $e140 = asl.w #n,d0
	move.w	d0,(a1)+
.mul_done:
	rts
.times_two:
	move.w	#$d040,(a1)+                    ; add.w d0,d0
	rts

;------------------------------------------------------------------------------
; IR $8198 arr: second array of SWAP a(),b() (boolean): descriptor address into a1.  Pushes
; retarget_to_next_address_register as the return address and falls into the boolean descriptor load.
;------------------------------------------------------------------------------
gen_ir_8198_bool_array_descriptor_a1:
	pea	retarget_to_next_address_register(pc) ; rts of the descriptor load returns there: a0 -> a1

;------------------------------------------------------------------------------
; IR $8192 arr: first array of SWAP a(),b() (boolean): emit_array_descriptor with bool_array_table (lea/movea
; var(a5),a0).
;------------------------------------------------------------------------------
gen_ir_8192_bool_array_descriptor:
	movea.l	bool_array_table(pc),a2         ; a2 = bool array table
	bra.s	emit_array_descriptor

;------------------------------------------------------------------------------
; IR $8197 arr: second SWAP array (integer): emit_int_array_descriptor, returning through
; retarget_to_next_address_register (a0 -> a1).
;------------------------------------------------------------------------------
gen_ir_8197_int_array_descriptor_a1:
	pea	retarget_to_next_address_register(pc) ; rts of the descriptor load returns there: a0 -> a1

;------------------------------------------------------------------------------
; Load the descriptor address of an integer array (int_array_table) through emit_array_descriptor.
; The pea retarget_to_next_address_register entries before each of these retarget the load to a1.
;------------------------------------------------------------------------------
emit_int_array_descriptor:
	movea.l	int_array_table(pc),a2
	bra.s	emit_array_descriptor

;------------------------------------------------------------------------------
; IR $8195 arr: second SWAP array (float): emit_float_array_descriptor, then a0 -> a1.
;------------------------------------------------------------------------------
gen_ir_8195_float_array_descriptor_a1:
	pea	retarget_to_next_address_register(pc) ; rts of the descriptor load returns there: a0 -> a1

;------------------------------------------------------------------------------
; As emit_int_array_descriptor for float arrays; used with INSAF/DELAF.
;------------------------------------------------------------------------------
emit_float_array_descriptor:
	movea.l	float_array_table(pc),a2
	bra.s	emit_array_descriptor

;------------------------------------------------------------------------------
; IR $8199 arr: second SWAP array (word): emit_word_array_descriptor, then a0 -> a1.
;------------------------------------------------------------------------------
gen_ir_8199_word_array_descriptor_a1:
	pea	retarget_to_next_address_register(pc) ; rts of the descriptor load returns there: a0 -> a1

;------------------------------------------------------------------------------
; As emit_int_array_descriptor for word arrays (INSAW/DELAW).
;------------------------------------------------------------------------------
emit_word_array_descriptor:
	movea.l	word_array_table(pc),a2
	bra.s	emit_array_descriptor

;------------------------------------------------------------------------------
; IR $819a arr: second SWAP array (byte): emit_byte_array_descriptor, then a0 -> a1.
;------------------------------------------------------------------------------
gen_ir_819a_byte_array_descriptor_a1:
	pea	retarget_to_next_address_register(pc) ; rts of the descriptor load returns there: a0 -> a1

;------------------------------------------------------------------------------
; As emit_int_array_descriptor for byte arrays (INSAC/DELAC).
;------------------------------------------------------------------------------
emit_byte_array_descriptor:
	movea.l	byte_array_table(pc),a2
	bra.s	emit_array_descriptor

;------------------------------------------------------------------------------
; IR $8196 arr: second SWAP array (string): emit_string_array_descriptor, then a0 -> a1.
;------------------------------------------------------------------------------
gen_ir_8196_string_array_descriptor_a1:
	pea	retarget_to_next_address_register(pc) ; rts of the descriptor load returns there: a0 -> a1

;------------------------------------------------------------------------------
; As emit_int_array_descriptor for string arrays (INSAS/DELAS).
;------------------------------------------------------------------------------
emit_string_array_descriptor:
	movea.l	string_array_table(pc),a2

;------------------------------------------------------------------------------
; Read the variable number, look it up in table a2 and emit the address through emit_var_address_a0.
;------------------------------------------------------------------------------
emit_array_descriptor:
	move.w	(a0)+,d0                        ; d0 = array number from the IR
	asl.w	#2,d0                           ; 4-byte table entries
	adda.w	d0,a2
	move.l	(a2),d0                         ; d0 = offset, sign = pointer flag
	move.w	(a2),d7                         ; d7 = high word of the entry for the flags test
	bra.w	emit_var_address_a0             ; lea/movea var(a5),a0

;------------------------------------------------------------------------------
; IR $81b0 arr: INSERT into a float array. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array
; types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_float_array_descriptor) and a
; call of library routine $2f0 INSAF.
;------------------------------------------------------------------------------
gen_ir_81b0_insert_float_array:
	bsr.s	emit_float_array_descriptor
	move.w	#$2f0,d0                        ; library routine $2f0 INSAF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81b1 arr: INSERT into a string array (descriptor into a1). The parser writes $81ac+type for INSERT and $81b0+type
; for DELETE (array types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_string_array_descriptor) and a
; call of library routine $2f1 INSAS.
;------------------------------------------------------------------------------
gen_ir_81b1_insert_string_array:
	bsr.s	emit_string_array_descriptor
	addi.w	#$200,-$4(a1)                   ; INSAS wants the descriptor in a1
	move.w	#$2f1,d0                        ; library routine $2f1 INSAS
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81b2 arr: INSERT into an integer array. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array
; types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_int_array_descriptor) and a
; call of library routine $2f2 INSAI.
;------------------------------------------------------------------------------
gen_ir_81b2_insert_integer_array:
	bsr.s	emit_int_array_descriptor
	move.w	#$2f2,d0                        ; library routine $2f2 INSAI
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81b8 arr: INSERT into a word array; also IR $81b3 (boolean array type), which therefore uses the word array table
; and INSAW. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_word_array_descriptor) and a
; call of library routine $2f3 INSAW.
;------------------------------------------------------------------------------
gen_ir_81b8_insert_word_array:
	bsr.s	emit_word_array_descriptor
	move.w	#$2f3,d0                        ; library routine $2f3 INSAW
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81b9 arr: INSERT into a byte array. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array types
; 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_byte_array_descriptor) and a
; call of library routine $2f4 INSAC.
;------------------------------------------------------------------------------
gen_ir_81b9_insert_byte_array:
	bsr.s	emit_byte_array_descriptor
	move.w	#$2f4,d0                        ; library routine $2f4 INSAC
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81b4 arr: DELETE from a float array. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array
; types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_float_array_descriptor) and a
; call of library routine $2f5 DELAF.
;------------------------------------------------------------------------------
gen_ir_81b4_delete_float_array:
	bsr.s	emit_float_array_descriptor
	move.w	#$2f5,d0                        ; library routine $2f5 DELAF
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81b5 arr: DELETE from a string array. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array
; types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_string_array_descriptor) and a
; call of library routine $2f6 DELAS.
;------------------------------------------------------------------------------
gen_ir_81b5_delete_string_array:
	bsr.s	emit_string_array_descriptor
	move.w	#$2f6,d0                        ; library routine $2f6 DELAS
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81b6 arr: DELETE from an integer array. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array
; types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_int_array_descriptor) and a
; call of library routine $2f7 DELAI.
;------------------------------------------------------------------------------
gen_ir_81b6_delete_integer_array:
	bsr.w	emit_int_array_descriptor
	move.w	#$2f7,d0                        ; library routine $2f7 DELAI
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81bc arr: DELETE from a word array; also IR $81b7 (boolean array type), word table and DELAW. The parser writes
; $81ac+type for INSERT and $81b0+type for DELETE (array types 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_word_array_descriptor) and a
; call of library routine $2f8 DELAW.
;------------------------------------------------------------------------------
gen_ir_81bc_delete_word_array:
	bsr.s	emit_word_array_descriptor
	move.w	#$2f8,d0                        ; library routine $2f8 DELAW
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81bd arr: DELETE from a byte array. The parser writes $81ac+type for INSERT and $81b0+type for DELETE (array types
; 4-7,
; 12, 13), after the index (and for INSERT the value) expressions. Emits the descriptor address
; (emit_byte_array_descriptor) and a
; call of library routine $2f9 DELAC.
;------------------------------------------------------------------------------
gen_ir_81bd_delete_byte_array:
	bsr.s	emit_byte_array_descriptor
	move.w	#$2f9,d0                        ; library routine $2f9 DELAC
	bra.w	emit_library_call

;------------------------------------------------------------------------------
; IR $81c1: the lea/movea ...,a0 just emitted is turned to ...,a2 (two steps of retarget_to_next_address_register).
; Written by the parser after an array reference whose descriptor a library routine wants in a2 (e.g. at $68fe, $6aa2).
;------------------------------------------------------------------------------
gen_ir_81c1_retarget_address_a2:
	addq.b	#2,-$4(a1)                      ; a0 -> a1, and the next step a1 -> a2

;------------------------------------------------------------------------------
; Add 2 to the high byte of the instruction at -4(a1): its destination address register goes up by one (a0 -> a1).
;------------------------------------------------------------------------------
retarget_to_next_address_register:
	addq.b	#2,-$4(a1)                      ; destination An field (bits 9-11) +1
	rts

;------------------------------------------------------------------------------
; IR $81bf off: INLINE var%,len: the inline data address.  The long after the IR code (offset in the data area,
; relocated) gives lea off,a2 ($45f9) / move.l a2,d0 ($200a); the $8042 store into the integer variable follows.
;------------------------------------------------------------------------------
gen_ir_81bf_inline_address:
	move.w	#$45f9,(a1)+                    ; $45f9 = lea (xxx).l,a2
	move.l	(a0)+,(a1)+                     ; the inline data address (relocated long)
	move.w	#$200a,(a1)+                    ; $200a = move.l a2,d0
	rts

;------------------------------------------------------------------------------
; IR $81cf c.l: add the long constant c to d1.  d0 = 1, then emit_add_constant_dn.
;------------------------------------------------------------------------------
gen_ir_81cf_add_constant_d1:
	moveq	#1,d0                           ; d0 = register number for the addi/addq that follows
	bra.s	emit_add_constant_dn

;------------------------------------------------------------------------------
; IR $81d0 c.l: add the long constant c to d2.  d0 = 2, then emit_add_constant_dn.
;------------------------------------------------------------------------------
gen_ir_81d0_add_constant_d2:
	moveq	#2,d0                           ; register d2
	bra.s	emit_add_constant_dn

;------------------------------------------------------------------------------
; IR $81d1 c.l: add the long constant c to d3.  d0 = 3, then emit_add_constant_dn.
;------------------------------------------------------------------------------
gen_ir_81d1_add_constant_d3:
	moveq	#3,d0                           ; register d3
	bra.s	emit_add_constant_dn

;------------------------------------------------------------------------------
; IR $81d2 c.l: add the long constant c to d4.  d0 = 4, then emit_add_constant_dn.
;------------------------------------------------------------------------------
gen_ir_81d2_add_constant_d4:
	moveq	#4,d0                           ; register d4
	bra.s	emit_add_constant_dn

;------------------------------------------------------------------------------
; IR $81d3 c.l: add the long constant c to d5.  d0 = 5, then emit_add_constant_dn.
;------------------------------------------------------------------------------
gen_ir_81d3_add_constant_d5:
	moveq	#5,d0                           ; register d5
	bra.s	emit_add_constant_dn

;------------------------------------------------------------------------------
; IR $81d4 c.l: add the long constant c to d6.  d0 = 6, then emit_add_constant_dn.
;------------------------------------------------------------------------------
gen_ir_81d4_add_constant_d6:
	moveq	#6,d0                           ; register d6
	bra.s	emit_add_constant_dn

;------------------------------------------------------------------------------
; IR $81d5 c.l: add the long constant c to d7.  d0 = 7, then emit_add_constant_dn.
;------------------------------------------------------------------------------
gen_ir_81d5_add_constant_d7:
	moveq	#7,d0                           ; register d7

;------------------------------------------------------------------------------
; Add the long constant after the IR code to data register d0 (number): nothing for 0, addq #n,Dn for 1..8,
; subq #n,Dn for -8..-1, addi.w #n,Dn when only the low word is used (low_word_only with d2 = register), else
; addi.l #n,Dn.
;------------------------------------------------------------------------------
emit_add_constant_dn:
	move.l	(a0)+,d1                        ; d1 = the constant
	beq.s	.constant_zero
	cmpi.l	#$8,d1                          ; 1..8: addq.l #n,dn
	bls.s	emit_addq_dn
	cmpi.l	#$fffffff8,d1                   ; -8..-1: subq.l #-n,dn
	bcc.s	emit_subq_dn
	move.w	d0,d2                           ; d2 = register for low_word_only
	movem.l	d0-d1,-(sp)                     ; keep register and constant over the look-ahead
	bsr.w	low_word_only                   ; only the low word used? (Z set if so)
	movem.l	(sp)+,d0-d1
	bne.s	.addi_long                      ; the whole long is needed
	ori.w	#$640,d0                        ; addi.w #n,dn
	move.w	d0,(a1)+
	move.w	d1,(a1)+                        ; the constant, word only
	rts
.addi_long:
	ori.w	#$680,d0                        ; addi.l #n,dn
	move.w	d0,(a1)+
	move.l	d1,(a1)+                        ; the constant
.constant_zero:
	rts

;------------------------------------------------------------------------------
; Emit addq.l #d1,Dn ($5080 + data 1..8 in bits 9-11 + register d0); also addq.l #n,An when d0 = 8+n.
;------------------------------------------------------------------------------
emit_addq_dn:
	andi.w	#$7,d1                          ; data 1..8 (8 as 0)
	ror.w	#7,d1                           ; to bits 9-11
	ori.w	#$5080,d1                       ; addq #n,dn
	or.w	d0,d1                           ; register (and mode) from d0
	move.w	d1,(a1)+
	rts

;------------------------------------------------------------------------------
; Emit subq.l #-d1,Dn ($5180, d1 = -8..-1); also subq.l #n,An when d0 = 8+n.
;------------------------------------------------------------------------------
emit_subq_dn:
	neg.w	d1                              ; d1 = 1..8
	andi.w	#$7,d1                          ; data 1..8 (8 as 0)
	ror.w	#7,d1                           ; to bits 9-11
	ori.w	#$5180,d1                       ; subq #n,dn
	or.w	d0,d1                           ; register (and mode) from d0
	move.w	d1,(a1)+
	rts

;------------------------------------------------------------------------------
; IR $81d6 c.l: add the long constant c to a0.  d0 = 0, then emit_add_constant_an.
;------------------------------------------------------------------------------
gen_ir_81d6_add_constant_a0:
	moveq	#0,d0                           ; register a0
	bra.s	emit_add_constant_an

;------------------------------------------------------------------------------
; IR $81d7 c.l: add the long constant c to a1.  d0 = 1, then emit_add_constant_an.
;------------------------------------------------------------------------------
gen_ir_81d7_add_constant_a1:
	moveq	#1,d0                           ; register a1

;------------------------------------------------------------------------------
; Add the long constant after the IR code to address register d0: nothing for 0, addq/subq #n,An for -8..8,
; lea c(An),An ($41e8) for a word constant, adda.l #c,An ($d1fc) otherwise.
;------------------------------------------------------------------------------
emit_add_constant_an:
	move.l	(a0)+,d1                        ; d1 = the constant
	beq.s	.add_an_done
	move.w	d1,d2                           ; does it fit a sign-extended word?
	ext.l	d2
	cmp.l	d1,d2
	beq.s	.word_sized
	ori.w	#$5288,d0
	move.w	d0,(a1)+
	move.l	d1,(a1)+                        ; the constant
.add_an_done:
	rts
.word_sized:
	cmpi.w	#$8,d1                          ; 1..8: addq.l #n,an
	bls.s	.addq_an
	cmpi.w	#$fff8,d1                       ; -8..-1: subq.l #-n,an
	bcc.s	.subq_an
	move.w	d0,d2                           ; source register in bits 0-2, destination in 9-11
	ror.w	#7,d2
	or.w	d2,d0
	ori.w	#$41e8,d0                       ; lea d16(an),an
