;------------------------------------------------------------------------------
; Add a word variable to data register d1 (0-7, the unlabelled entries before set it). If only the low word of the
; result is needed (low_word_only): add.w d16(a5),dn ($d06d); else movea.w d16(a5),a2 / add.l a2,dn (sign extended).
;------------------------------------------------------------------------------
gen_add_word_variable:
	move.w	d0,d2                           ; d2 = d0, not d1 as in gen_sub_word_variable (looks wrong)
	ror.w	#7,d1                           ; register to bits 9-11
	bsr.w	lookup_word_var                 ; d0 = offset, d7 = flags
	movem.w	d0-d2/d7,-(sp)                  ; keep them over the look-ahead
	bsr.s	low_word_only                   ; only the low word used? (Z set if so)
	movem.w	(sp)+,d0-d2/d7
	bne.s	.long_add                       ; the whole long is needed: sign-extend via a2
	ori.w	#$d06d,d1                       ; add.w d16(a5),dn
	tst.w	d7                              ; flags for emit_op_on_variable: pointer variable?
	bra.w	emit_op_on_variable             ; emit add.w var,dn (through (a2) for a pointer)
.long_add:
	move.w	d1,-(sp)                        ; keep the add instruction
	move.w	#$346d,d1                       ; $346d = movea.w d16(a5),a2: sign-extends the word
	tst.w	d7
	bsr.w	emit_op_on_variable             ; emit movea.w var,a2
	move.w	(sp)+,d1
	ori.w	#$d08a,d1                       ; $d08a = add.l a2,d0, register added
	move.w	d1,(a1)+
	rts

