;------------------------------------------------------------------------------
gen_sub_word_variable:
	move.w	d1,d2                           ; d2 = register for low_word_only
	ror.w	#7,d1                           ; register to bits 9-11
	bsr.w	lookup_word_var                 ; d0 = offset, d7 = flags
	movem.w	d0-d2/d7,-(sp)                  ; keep them over the look-ahead
	bsr.s	low_word_only                   ; only the low word used? (Z set if so)
	movem.w	(sp)+,d0-d2/d7
	bne.s	.long_sub                       ; the whole long is needed: sign-extend via a2
	ori.w	#$906d,d1                       ; sub.w d16(a5),dn
	tst.w	d7                              ; flags for emit_op_on_variable: pointer variable?
	bra.w	emit_op_on_variable             ; emit sub.w var,dn
.long_sub:
	move.w	d1,-(sp)                        ; keep the sub instruction
	move.w	#$346d,d1                       ; $346d = movea.w d16(a5),a2
	tst.w	d7
	bsr.w	emit_op_on_variable             ; emit movea.w var,a2
	move.w	(sp)+,d1
	ori.w	#$908a,d1                       ; $908a = sub.l a2,d0, register added
	move.w	d1,(a1)+
	rts

;------------------------------------------------------------------------------
; low_word_only for register d0 (d2 = 0).
;------------------------------------------------------------------------------
low_word_only_d0:
	moveq	#0,d2                           ; register d0

;------------------------------------------------------------------------------
; Look ahead in the IR from a0: is only the low word of the value in register d2 used?
; Yes for $8043, $811c, $80e0-$80e7 and the FOR routines FORC1/FORC2/FORW1/FORW2 next; otherwise IR words with no
; effect on the value are skipped and the first library routine call decides: bit d2 of dat_0af10[routine] set = word
; only.
; Exit: d7 = 0 and Z set if only the low word is needed, d7 = -1 otherwise.
;------------------------------------------------------------------------------
low_word_only:
	move.w	(a0),d1                         ; d1 = next IR word
	cmpi.w	#$8043,d1                       ; $8043: word use
	beq.w	.word_only
	cmpi.w	#$1b2,d1                        ; FORC1
	beq.w	.word_only
	cmpi.w	#$1b3,d1                        ; FORC2
	beq.w	.word_only
	cmpi.w	#$811c,d1                       ; $811c: word use
	beq.w	.word_only
	cmpi.w	#$8043,d1                       ; $8043 again (tested twice)
	beq.w	.word_only
	cmpi.w	#$80e0,d1                       ; $80e0-$80e7: word use
	beq.w	.word_only
	cmpi.w	#$80e1,d1
	beq.w	.word_only
	cmpi.w	#$80e2,d1
	beq.w	.word_only
	cmpi.w	#$80e3,d1
	beq.w	.word_only
	cmpi.w	#$80e4,d1
	beq.w	.word_only
	cmpi.w	#$80e5,d1
	beq.w	.word_only
	cmpi.w	#$80e6,d1
	beq.w	.word_only
	cmpi.w	#$80e7,d1
	beq.w	.word_only
	cmpi.w	#$1ae,d1                        ; FORW1
	beq.w	.word_only
	cmpi.w	#$1af,d1                        ; FORW2
	beq.w	.word_only
	lea	-$4(a0),a2                      ; a2 = a0 after the two addq below
.skip_ir_and_two:
	addq.l	#2,a2                           ; skip a two-word operand
.skip_ir_and_one:
	addq.l	#2,a2                           ; skip a one-word operand
.next_ir_word:
	move.w	(a2)+,d1                        ; d1 = next IR word; positive = library routine
	bpl.w	.library_routine
	cmpi.w	#$8028,d1                       ; $8028 no code: look further
	beq.s	.next_ir_word
	cmpi.w	#$8078,d1                       ; $8078: look further
	beq.s	.next_ir_word
	cmpi.w	#$8032,d1                       ; $8032: look further
	beq.s	.next_ir_word
	cmpi.w	#$814c,d1                       ; $814c-$814e word add/sub: look further
	beq.s	.next_ir_word
	cmpi.w	#$814d,d1
	beq.s	.next_ir_word
	cmpi.w	#$814e,d1
.skip_if_equal:
	beq.s	.next_ir_word
	cmpi.w	#$8007,d1                       ; $8007-$8010: constants etc., two operand words
	bcs.s	.test_pop_range
	cmpi.w	#$8010,d1
	bls.s	.skip_ir_and_two
.test_pop_range:
	cmpi.w	#$801b,d1                       ; $801b-$8023: register pops, look further
	bcs.s	.test_8084_range
	cmpi.w	#$8023,d1
	bls.s	.next_ir_word
.test_8084_range:
	cmpi.w	#$8084,d1                       ; $8084-$808c: one operand word
	bcs.s	.test_808d_range
	cmpi.w	#$808c,d1
	bls.s	.skip_ir_and_one
.test_808d_range:
	cmpi.w	#$808d,d1                       ; $808d-$8095: one operand word
	bcs.s	.test_81cf_range
	cmpi.w	#$8095,d1
	bls.s	.skip_ir_and_one
.test_81cf_range:
	cmpi.w	#$81cf,d1                       ; $81cf-$81d7: add constant, a long operand
	bcs.s	.test_8060_codes
	cmpi.w	#$81d7,d1
	bls.s	.skip_ir_and_two
	cmpi.w	#$81fb,d1                       ; $81d8-$81fb: add/sub variable, one operand word
	bls.s	.skip_ir_and_one
	cmpi.w	#$8201,d1                       ; $8201-$8204: one operand word
	bcs.s	.test_8060_codes
	cmpi.w	#$8204,d1
	bls.s	.skip_ir_and_one
.test_8060_codes:
	cmpi.w	#$8063,d1                       ; $8060-$8064: look further
	beq.s	.skip_if_equal
	cmpi.w	#$8064,d1
	beq.s	.skip_if_equal
	cmpi.w	#$8061,d1
	beq.s	.skip_if_equal
	cmpi.w	#$8062,d1
	beq.s	.skip_if_equal
	cmpi.w	#$8060,d1
	beq.s	.skip_if_equal
	cmpi.w	#$8099,d1                       ; $8099-$809f: one operand word
	bcs.s	.other_ir
	cmpi.w	#$809f,d1
	bls.w	.skip_ir_and_one
.other_ir:
	cmpi.w	#$8007,d1                       ; $8007: two operand words
	beq.w	.skip_ir_and_two
	cmpi.w	#$803f,d1                       ; $803d-$8040: one operand word
	beq.w	.skip_ir_and_one
	cmpi.w	#$8040,d1
	beq.w	.skip_ir_and_one
	cmpi.w	#$803d,d1
	beq.w	.skip_ir_and_one
	cmpi.w	#$803e,d1
	beq.w	.skip_ir_and_one
	cmpi.w	#$8003,d1                       ; $8003/$8004: no operand, look further
	beq.s	.continue_scan
	cmpi.w	#$8004,d1
	beq.s	.continue_scan
	cmpi.w	#$8000,d1                       ; $8000/$8001: 8-byte float constant follows
	beq.s	.skip_constant
	cmpi.w	#$8001,d1
	bne.s	.long_needed                    ; anything else: the whole long is needed
.skip_constant:
	addq.l	#8,a2                           ; skip the float constant
.continue_scan:
	bra.w	.next_ir_word
.word_only:
	bra.s	.word_only_result
.library_routine:
	tst.w	d1                              ; word reached from the bpl: always positive here
	bmi.s	.check_ir                       ; never taken
	lea	routine_flag_table(pc),a2       ; bit table per library routine
	btst	d2,0(a2,d1.w)                   ; bit d2 set: the routine uses only the low word of dn
	beq.s	.other_ir                       ; clear: d1 positive, so .other_ir ends in .long_needed
	bra.s	.word_only_result
.check_ir:
	cmpi.w	#$8043,d1                       ; not reached (only from the bmi above)
	beq.s	.word_only_result
	cmpi.w	#$8044,d1
	beq.s	.word_only_result
	cmpi.w	#$8027,d1
	beq.s	.word_only_result
	cmpi.w	#$1ae,d1
	beq.s	.word_only_result
	cmpi.w	#$1af,d1
	bne.s	.other_ir
.word_only_result:
	moveq	#0,d7                           ; low word only: Z set
	rts
.long_needed:
	moveq	#-1,d7                          ; the long is needed
	rts

;------------------------------------------------------------------------------
; Not reached from the codegen table or any branch: emits movem.l a3-a6,-(sp) ($48e7 $001e).
;------------------------------------------------------------------------------
emit_push_a3_a6_unreferenced:
	move.l	#$48e7001e,(a1)+                ; $48e7 $001e = movem.l a3-a6,-(sp) (predecrement mask, bits reversed)
	rts

;------------------------------------------------------------------------------
; Not reached: emits movem.l (sp)+,a3-a6 ($4cdf $7800).
;------------------------------------------------------------------------------
emit_pop_a3_a6_unreferenced:
	move.l	#$4cdf7800,(a1)+                ; $4cdf $7800 = movem.l (sp)+,a3-a6
	rts

;------------------------------------------------------------------------------
; Not reached: emits movem.l d5-d7/a0,-(sp) ($48e7 $0780).
;------------------------------------------------------------------------------
emit_push_d5_d7_a0_unreferenced:
	move.l	#$48e70780,(a1)+                ; $48e7 $0780 = movem.l d5-d7/a0,-(sp)
	rts

;------------------------------------------------------------------------------
; Not reached: emits movem.l (sp)+,d1-d4 ($4cdf $001e); after emit_push_d5_d7_a0_unreferenced it would move
; d5/d6/d7/a0 into d1-d4.
;------------------------------------------------------------------------------
emit_pop_d1_d4_unreferenced:
	move.l	#$4cdf001e,(a1)+                ; $4cdf $001e = movem.l (sp)+,d1-d4
	rts
	neg.w	d5

;------------------------------------------------------------------------------
; Floating point add for constant folding: d0.l/d1.w/d2.w + d3.l/d4.w/d5.w -> d0/d1/d2.
; Format: d0:d1 = 48-bit mantissa (top bit set), d2 = exponent biased $3ff, negated for a negative number, 0 for
; zero. Overflow: moveq #1,d0 / jmp (a6) (error exit set by the caller). The neg.w d5 just before this label
; ($0e974) is a subtract entry, but nothing branches to it.
;------------------------------------------------------------------------------
float_add:
	ext.l	d2                              ; sign of the first operand to the high word of d2
	bgt.s	.first_nonzero                  ; positive
	beq.s	.first_zero                     ; exponent 0: the first operand is zero
	neg.w	d2                              ; d2.w = exponent, the high word keeps the sign
.first_nonzero:
	ext.l	d5                              ; sign of the second operand to the high word of d5
	bgt.s	.second_nonzero
	beq.s	.apply_sign                     ; second operand zero: result = first
	neg.w	d5                              ; d5.w = exponent, the high word keeps the sign
.second_nonzero:
	moveq	#16,d7                          ; d7 = 16, the word step of the shifts
	move.w	d2,d6                           ; d6 = exponent difference
	sub.w	d5,d6
	bgt.s	.shift_second                   ; first larger: shift the second right
	beq.s	.aligned                        ; same exponent: no shift
	exg	d3,d0                           ; second larger: exchange the operands
	exg	d4,d1
	exg	d5,d2
	neg.w	d6                              ; d6 = positive difference
.shift_second:
	sub.w	d7,d6                           ; shift under 16?
	bls.s	.shift_under_16
	sub.w	d7,d6                           ; shift 16..31?
	bls.s	.shift_16_to_32
	cmp.w	d7,d6                           ; over 48 bits: the smaller operand does not count
	bhi.s	.apply_sign
	move.l	d3,d4                           ; shift 32..48: only the top word survives, in d4
	moveq	#0,d3
	swap	d4
	lsr.w	d6,d4
	bra.s	.aligned
.shift_16_to_32:
	add.w	d7,d6                           ; d6 = shift less 16
	lsr.l	d6,d3                           ; d3 shifted; its low word becomes d4
	move.w	d3,d4
	clr.w	d3                              ; d3 = the high word of the shifted value
	swap	d3
	bra.s	.aligned
.shift_under_16:
	add.w	d7,d6                           ; d6 = shift 1..16
	swap	d4                              ; d4 = low word of d3 above the low word of d4
	move.w	d3,d4
	swap	d4
	lsr.l	d6,d3                           ; shift the 48-bit mantissa right
	lsr.l	d6,d4
.aligned:
	eor.l	d2,d5                           ; same signs (high words)?
	bmi.s	.subtract                       ; different: subtract the mantissas
	addx.w	d4,d1                           ; add the 48-bit mantissas
	addx.l	d3,d0
	bcc.s	.apply_sign                     ; no carry: done
	roxr.l	#1,d0                           ; carry: mantissa right one bit, exponent +1
	roxr.w	#1,d1
	addq.w	#1,d2
	cmpi.w	#$1fff,d2                       ; exponent out of range?
	bhi.s	.overflow
.apply_sign:
	tst.l	d2                              ; negative result: exponent negated
	bpl.s	.add_done
	neg.w	d2
.add_done:
	rts
.first_zero:
	move.l	d3,d0                           ; first operand zero: result = the second
	exg	d1,d4
	exg	d2,d5
	rts
.overflow:
	moveq	#1,d0                           ; error 1: float overflow, to the error exit in a6
	jmp	(a6)
.subtract:
	subx.w	d4,d1                           ; subtract the 48-bit mantissas
	subx.l	d3,d0
	bpl.s	.normalise                      ; top bit clear: normalise
	bcc.s	.apply_difference_sign          ; top bit set, no borrow: already normalised
	eor.l	d5,d2                           ; borrow: the result has the second operand's sign
	neg.w	d1                              ; negate the 48-bit mantissa
	negx.l	d0
.normalise:
	cmpi.l	#$ffff,d0                       ; top word empty: shift by words first
	bls.s	.normalise_by_words
.normalise_bit_loop:
	add.w	d1,d1                           ; shift left until the top bit is set
	addx.l	d0,d0
	dbmi	d2,.normalise_bit_loop          ; exponent -1 per bit
	subq.w	#1,d2
	ble.s	.difference_underflow           ; exponent gone: underflow to zero
.apply_difference_sign:
	tst.l	d2                              ; negative result: exponent negated
	bpl.s	.subtract_done
	neg.w	d2
.subtract_done:
	rts
.difference_underflow:
	moveq	#0,d1                           ; result zero
.clear_high_and_exponent:
	moveq	#0,d0
	moveq	#0,d2
	rts
.normalise_by_words:
	swap	d0                              ; top word to the low word; zero: only d1 left
	beq.s	.only_low_word_left
	move.w	d1,d0                           ; d0 = mantissa without its empty top word
	tst.l	d0                              ; flags for the first dbmi test
	bra.s	.shift_long_test
.shift_long_loop:
	add.l	d0,d0                           ; shift left until the top bit is set
.shift_long_test:
	dbmi	d2,.shift_long_loop             ; exponent -1 per bit
	moveq	#0,d1
	sub.w	d7,d2                           ; less 16 for the word moved up
	ble.s	.clear_high_and_exponent        ; exponent gone: underflow to zero
	tst.l	d2                              ; negative result: exponent negated
	bpl.s	.long_shift_done
	neg.w	d2
.long_shift_done:
	rts
.only_low_word_left:
	move.w	d1,d0                           ; only d1 holds bits
	bne.s	.shift_word_test
	moveq	#0,d2                           ; difference zero: result zero
	rts
.shift_word_loop:
	add.w	d0,d0                           ; shift left until the top bit is set
.shift_word_test:
	dbmi	d2,.shift_word_loop             ; exponent -1 per bit
	moveq	#0,d1
	subi.w	#$20,d2                         ; less 32 for the two words moved up
	ble.s	.clear_high_and_exponent        ; exponent gone: underflow to zero
	swap	d0                              ; the word to the top of d0
	tst.l	d2                              ; negative result: exponent negated
	bpl.s	.word_shift_done
	neg.w	d2
.word_shift_done:
	rts

;------------------------------------------------------------------------------
; Floating point divide (d0/d1/d2 / d3/d4/d5 -> d0/d1/d2), long division by 16-bit steps.
; Exit: d7 = 0, or d7 = -1 for division by zero.
;------------------------------------------------------------------------------
float_divide:
	tst.w	d5                              ; divisor zero or negative?
	ble.s	.divisor_not_positive
	ext.l	d2                              ; sign of the dividend to the high word of d2
	bgt.s	.divide                         ; positive dividend
	bne.s	.dividend_negative              ; negative dividend
.return_ok:
	moveq	#0,d7                           ; dividend zero: result zero
	rts
.division_by_zero:
	moveq	#-1,d7
	rts
.underflow_zero:
	moveq	#0,d2                           ; exponent below range: result zero
	bra.s	.return_ok
.divisor_not_positive:
	beq.s	.division_by_zero               ; divisor zero
	neg.w	d5                              ; divisor exponent made positive
	neg.w	d2                              ; and the dividend's sign flipped instead
	ext.l	d2                              ; sign of the dividend to the high word of d2
	bgt.s	.divide
	beq.s	.return_ok                      ; dividend zero: result zero
.dividend_negative:
	neg.w	d2                              ; d2.w = exponent, the high word keeps the sign
.divide:
	sub.w	d5,d2                           ; exponent of the quotient, bias $3ff
	addi.w	#$3ff,d2
	bmi.s	.underflow_zero                 ; underflow: result zero
	lsr.l	#1,d0                           ; dividend mantissa halved: first divu cannot overflow
	roxr.w	#1,d1
	move.l	d3,d5                           ; d5 = top word of the divisor
	swap	d5
	tst.w	d4                              ; divisor's low word zero: shorter loop
	beq.w	.divisor_low_word_zero
	divu.w	d5,d0                           ; first quotient digit
	move.w	d0,-(sp)                        ; push the digit
	move.w	d0,d6                           ; d6, d7 = digit, for the product with the divisor
	move.w	d0,d7
	move.w	d1,d0                           ; d0:d1 = remainder:next dividend word
	moveq	#0,d1
	mulu.w	d3,d6                           ; digit * divisor high long (low word)
	mulu.w	d4,d7                           ; digit * divisor low word
	swap	d7                              ; carry its high word into d6
	add.w	d7,d6
	bcc.s	.first_product_done
	addi.l	#$10000,d6                      ; carry out of the word add
.first_product_done:
	swap	d7                              ; d7 = low word of the product
	sub.w	d7,d1                           ; remainder less digit * divisor
	subx.l	d6,d0
	bcc.s	.second_digit                   ; no borrow: the digit was right
.first_digit_correct:
	subq.w	#1,(sp)                         ; digit one too large: decrement it
	add.w	d4,d1                           ; and add the divisor back
	addx.l	d3,d0
	bcc.s	.first_digit_correct            ; until the remainder is positive again
.second_digit:
	divu.w	d5,d0                           ; second quotient digit
	bvs.w	.quotient_digit_overflow        ; digit over $ffff
	move.w	d0,-(sp)                        ; push the digit
	move.w	d0,d6
	move.w	d0,d7
	move.w	d1,d0
	moveq	#0,d1
	mulu.w	d3,d6
	mulu.w	d4,d7
	swap	d7
	add.w	d7,d6
	bcc.s	.second_product_done
	addi.l	#$10000,d6
.second_product_done:
	swap	d7
	sub.w	d7,d1
	subx.l	d6,d0
	bcc.s	.third_digit
.second_digit_correct:
	subq.w	#1,(sp)
	add.w	d4,d1
	addx.l	d3,d0
	bcc.s	.second_digit_correct
.third_digit:
	divu.w	d5,d0                           ; third quotient digit
	bvs.w	.third_digit_overflow           ; digit over $ffff
	move.w	d0,-(sp)                        ; push the digit
	move.w	d0,d6
	move.w	d0,d7
	move.w	d1,d0
	moveq	#0,d1
	mulu.w	d3,d6
	mulu.w	d4,d7
	swap	d7
	add.w	d7,d6
	bcc.s	.third_product_done
	addi.l	#$10000,d6
.third_product_done:
	swap	d7
	sub.w	d7,d1
	subx.l	d6,d0
	bcc.s	.collect_quotient
.third_digit_correct:
	subq.w	#1,(sp)
	add.w	d4,d1
	addx.l	d3,d0
	bcc.s	.third_digit_correct
.collect_quotient:
	move.l	d0,d3                           ; d3 = remainder, for the rounding
	move.w	(sp)+,d1                        ; d1 = third digit
	move.l	(sp)+,d0                        ; d0 = second:first digit
	swap	d0                              ; d0 = first:second digit
	bmi.s	.round_quotient                 ; top bit set: already normalised
.normalise_quotient:
	add.l	d3,d3                           ; shift quotient and remainder left one bit
	addx.w	d1,d1
	addx.l	d0,d0
	dbmi	d2,.normalise_quotient          ; exponent -1 per bit, until the top bit is set
	subq.w	#1,d2
	bmi.w	.underflow_zero                 ; exponent gone: underflow to zero
.round_quotient:
	add.l	d3,d3                           ; remainder * 2: half the divisor or more?
	bcs.s	.round_up
	bpl.s	.apply_quotient_sign            ; under half: no rounding
.round_up:
	addq.w	#1,d1                           ; round the 48-bit quotient up
	bcc.s	.apply_quotient_sign
	addq.l	#1,d0
	bcc.s	.apply_quotient_sign
	roxr.l	#1,d0                           ; carry out: mantissa $8000..., exponent +1
	roxr.w	#1,d1
	addq.w	#1,d2
.apply_quotient_sign:
	tst.l	d2                              ; negative quotient: exponent negated
	bpl.s	.quotient_done
	neg.w	d2
.quotient_done:
	bra.w	.return_ok
.quotient_digit_overflow:
	move.w	#$ffff,-(sp)                    ; digit = $ffff
	move.l	d3,d6                           ; d6:d7 = divisor * $ffff, as divisor << 16 less divisor
	move.w	d4,d7
	sub.w	d3,d7
	subx.w	d5,d6
	bcc.s	.subtract_ffff_multiple
	subi.l	#$10000,d5                      ; should adjust d6; d5's high word is never used
.subtract_ffff_multiple:
	sub.w	d7,d1                           ; remainder less $ffff * divisor
	subx.l	d6,d0
	swap	d0                              ; d0:d1 = remainder:next dividend word
	move.w	d1,d0
	moveq	#0,d1
	bra.w	.third_digit                    ; the third digit is always the one that follows
.divisor_low_word_zero:
	divu.w	d5,d0                           ; first quotient digit, divisor = d3 only
	tst.w	d3                              ; divisor just one word?
	beq.s	.divisor_16_bit
	move.w	d0,-(sp)                        ; push the digit
	move.w	d0,d6
	move.w	d1,d0                           ; d0 = remainder:next dividend word
	moveq	#0,d1
	mulu.w	d3,d6                           ; digit * divisor low word
	sub.l	d6,d0                           ; remainder less digit * divisor
	bcc.s	.second_digit_32bit             ; no borrow: the digit was right
.first_digit_correct_32bit:
	subq.w	#1,(sp)                         ; digit one too large: decrement it
	add.l	d3,d0                           ; and add the divisor back
	bcc.s	.first_digit_correct_32bit      ; until the remainder is positive again
.second_digit_32bit:
	divu.w	d5,d0                           ; second quotient digit
	bvs.s	.quotient_digit_overflow        ; digit over $ffff
	move.w	d0,-(sp)                        ; push the digit
	move.w	d0,d6
	move.w	d1,d0
	moveq	#0,d1
	mulu.w	d3,d6
	sub.l	d6,d0
	bcc.s	.third_digit_32bit
.second_digit_correct_32bit:
	subq.w	#1,(sp)
	add.l	d3,d0
	bcc.s	.second_digit_correct_32bit
.third_digit_32bit:
	divu.w	d5,d0                           ; third quotient digit
	bvs.s	.third_digit_overflow           ; digit over $ffff
	move.w	d0,-(sp)                        ; push the digit
	move.w	d0,d6
	move.w	d1,d0
	mulu.w	d3,d6
	sub.l	d6,d0
	bcc.s	.collect_quotient_32bit
.third_digit_correct_32bit:
	subq.w	#1,(sp)
	add.l	d3,d0
	bcc.s	.third_digit_correct_32bit
.collect_quotient_32bit:
	move.l	d0,d3                           ; d3 = remainder, for the rounding
	move.w	(sp)+,d1                        ; d1 = third digit
	move.l	(sp)+,d0                        ; d0 = second:first digit
	swap	d0                              ; d0 = first:second digit
	bmi.s	.round_quotient_32bit           ; top bit set: already normalised
.normalise_quotient_32bit:
	add.l	d3,d3                           ; shift quotient and remainder left one bit
	addx.w	d1,d1
	addx.l	d0,d0
	dbmi	d2,.normalise_quotient_32bit    ; exponent -1 per bit, until the top bit is set
	subq.w	#1,d2
	bmi.w	.underflow_zero                 ; exponent gone: underflow to zero
.round_quotient_32bit:
	add.l	d3,d3                           ; remainder * 2: half the divisor or more?
	bcs.s	.round_up_32bit
	bpl.s	.apply_quotient_sign_32bit      ; under half: no rounding
.round_up_32bit:
	addq.w	#1,d1                           ; round the 48-bit quotient up
	bcc.s	.apply_quotient_sign_32bit
	addq.l	#1,d0
	bcc.s	.apply_quotient_sign_32bit
	roxr.l	#1,d0                           ; carry out: mantissa $8000..., exponent +1
	roxr.w	#1,d1
	addq.w	#1,d2
.apply_quotient_sign_32bit:
	tst.l	d2                              ; negative quotient: exponent negated
	bpl.s	.quotient_done_32bit
	neg.w	d2
.quotient_done_32bit:
	bra.w	.return_ok
.divisor_16_bit:
	move.w	d0,-(sp)                        ; push the first digit
	move.w	d0,d6
	move.w	d1,d0                           ; d0 = remainder:next dividend word
	moveq	#0,d1
	divu.w	d5,d0                           ; second quotient digit
	bvs.w	.quotient_digit_overflow        ; digit over $ffff
	move.w	d0,-(sp)                        ; push the digit
	move.w	d1,d0                           ; d0 = remainder:0
	divu.w	d5,d0                           ; third quotient digit
	bvs.s	.third_digit_overflow           ; digit over $ffff
	move.w	d0,-(sp)                        ; push the digit
	bra.s	.collect_quotient_32bit
.third_digit_overflow:
	move.w	#$ffff,-(sp)                    ; third digit = $ffff
	bra.w	.collect_quotient

;------------------------------------------------------------------------------
; Floating point d0/d1/d2 to a 32-bit integer in d0 (truncated). Overflow: moveq #2,d0 / jmp (a6).
;------------------------------------------------------------------------------
float_to_int:
	ext.l	d2                              ; sign to the high word of d2
	bmi.s	.negative                       ; negative number
	subi.w	#$3ff,d2                        ; unbiased exponent
	bmi.s	.below_one                      ; below 1: result 0
	subi.w	#$1f,d2                         ; 31 or more: does not fit a long
	bpl.s	.integer_overflow
	neg.w	d2                              ; d2 = 31 - exponent
	lsr.l	d2,d0                           ; shift the top long of the mantissa into place
	rts
.below_one:
	moveq	#0,d0                           ; |x| < 1: result 0
	rts
.negative:
	neg.w	d2                              ; exponent made positive
	subi.w	#$3ff,d2                        ; unbiased exponent
	bmi.s	.below_one                      ; below 1: result 0
	subi.w	#$1f,d2                         ; 31 or more?
	bpl.s	.negative_limit                 ; 31 or more: only -2^31 fits
	neg.w	d2
	lsr.l	d2,d0                           ; shift into place
	neg.l	d0                              ; and negate
.negative_done:
	rts
.negative_limit:
	bne.s	.integer_overflow               ; over 31: overflow
	cmpi.l	#$80000000,d0                   ; exactly -2^31?
	beq.s	.negative_done
.integer_overflow:
	moveq	#2,d0                           ; error 2: integer overflow, to the error exit in a6
	jmp	(a6)

;------------------------------------------------------------------------------
; 32-bit integer d0 to floating point d0/d1/d2.
;------------------------------------------------------------------------------
int_to_float:
	moveq	#0,d1                           ; low mantissa word 0
	move.l	d0,d2                           ; d2 = 0 for zero; flags: zero or negative
	ble.s	.negative_or_zero
	cmpi.l	#$ffff,d0                       ; more than 16 bits?
	bhi.s	.over_16_bits
	move.w	#$40d,d2                        ; exponent of bit 14, bias $3ff
	tst.w	d0                              ; bit 15 set?
	bmi.s	.bit_15_set
.normalise_word:
	add.w	d0,d0                           ; shift left until bit 15 is set
	dbmi	d2,.normalise_word              ; exponent -1 per bit
	swap	d0                              ; to the top word of d0
	rts
.bit_15_set:
	swap	d0                              ; bit 15 set: to the top word
	addq.w	#1,d2                           ; exponent of bit 15
	rts
.over_16_bits:
	move.w	#$41d,d2                        ; exponent of bit 30, bias $3ff
.normalise_long:
	add.l	d0,d0                           ; shift left until bit 31 is set
	dbmi	d2,.normalise_long              ; exponent -1 per bit
	rts
.negative_or_zero:
	neg.l	d0                              ; magnitude of a negative number
	beq.s	.zero_done                      ; zero: d2 = 0 already
	bmi.s	.minimum_long                   ; $80000000: still negative
	cmpi.l	#$ffff,d0                       ; more than 16 bits?
	bhi.s	.negative_over_16_bits
	move.w	#$40d,d2                        ; exponent of bit 14, bias $3ff
	tst.w	d0                              ; bit 15 set?
	bmi.s	.negative_bit_15_set
.negative_normalise_word:
	add.w	d0,d0                           ; shift left until bit 15 is set
	dbmi	d2,.negative_normalise_word     ; exponent -1 per bit
	swap	d0                              ; to the top word of d0
	neg.w	d2                              ; negative: exponent negated
	rts
.negative_bit_15_set:
	swap	d0                              ; bit 15 set: to the top word
	addq.w	#1,d2                           ; exponent of bit 15
	neg.w	d2                              ; negative: exponent negated
	rts
.negative_over_16_bits:
	move.w	#$41d,d2                        ; exponent of bit 30, bias $3ff
.negative_normalise_long:
	add.l	d0,d0                           ; shift left until bit 31 is set
	dbmi	d2,.negative_normalise_long     ; exponent -1 per bit
	neg.w	d2                              ; negative: exponent negated
	rts
.minimum_long:
	move.w	#$fbe2,d2                       ; -2^31: mantissa $80000000, exponent -($3ff+31)
.zero_done:
	rts

;------------------------------------------------------------------------------
; Part of float_multiply_positive: the first mantissa's low word (d1) is zero, so the products with it are
; left out; the second's low (d4) and middle words are tested the same way. Ends in float_mul_normalise.
;------------------------------------------------------------------------------
float_mul_low_word_zero:
	tst.w	d4                              ; second operand's low mantissa word zero too?
	beq.s	.both_low_words_zero
	move.w	d3,d1                           ; d1 = middle word of the second mantissa
	beq.s	.second_middle_word_zero        ; zero: one product fewer
	mulu.w	d0,d1                           ; middle * middle
	moveq	#0,d6
	swap	d3                              ; d3.w = top word of the second
	swap	d0                              ; d0.w = top word of the first
	mulu.w	d0,d4                           ; top of first * low of second
	move.w	d3,d5                           ; d5 = top * top
	mulu.w	d0,d5
	add.l	d4,d1                           ; sum the products of the same weight
	addx.l	d6,d5                           ; carry into the top product
	move.w	d3,d6                           ; the two top * middle products
	swap	d3
	move.w	d0,d7
	swap	d0
	mulu.w	d6,d0
	mulu.w	d7,d3
	add.l	d3,d0                           ; summed in d0
	bcc.w	float_mul_normalise             ; no carry: combine the partial sums
	addi.l	#$10000,d5                      ; carry into the top product
	bra.w	float_mul_normalise
.second_middle_word_zero:
	swap	d3                              ; second's middle word zero
	swap	d0
	mulu.w	d0,d4                           ; top of first * low of second
	move.w	d3,d5                           ; d5 = top * top
	mulu.w	d0,d5
	move.l	d4,d1                           ; d1 = weight-32 products
	move.w	d0,d7
	swap	d0
	mulu.w	d3,d0                           ; d0 = middle of first * top of second
	bra.w	float_mul_normalise
.both_low_words_zero:
	move.w	d3,d1                           ; d1 = middle word of the second mantissa
	beq.s	.only_top_words                 ; zero: only the top words
	mulu.w	d0,d1                           ; middle * middle
	swap	d3
	swap	d0
	move.w	d3,d5                           ; d5 = top * top
	mulu.w	d0,d5
	move.w	d3,d6                           ; the two top * middle products
	swap	d3
	move.w	d0,d7
	swap	d0
	mulu.w	d6,d0
	mulu.w	d7,d3
	add.l	d3,d0                           ; summed in d0
	bcc.w	float_mul_normalise             ; no carry: combine the partial sums
	addi.l	#$10000,d5                      ; carry into the top product
	bra.w	float_mul_normalise
.only_top_words:
	swap	d3                              ; only the top words of both mantissas count
	swap	d0
	move.w	d3,d5                           ; d5 = top * top
	mulu.w	d0,d5
	swap	d0
	mulu.w	d3,d0                           ; d0 = middle of first * top of second
	moveq	#0,d1                           ; nothing at weight 32
	bra.w	float_mul_normalise

;------------------------------------------------------------------------------
; float_multiply with the second operand zero or negative (d5 sign-extended): zero gives zero; otherwise the
; magnitudes are multiplied and the result negated when exactly one operand is negative.
;------------------------------------------------------------------------------
float_mul_second_not_positive:
	beq.s	float_mul_result_zero           ; second operand zero: result zero
	neg.w	d2                              ; first operand's sign flipped
	beq.s	float_mul_result_zero           ; first zero: result zero
	bmi.s	.result_negative                ; first was positive: the result is negative
	neg.w	d5                              ; both negative: multiply the magnitudes
	bra.s	float_multiply_positive
.result_negative:
	neg.w	d2                              ; first back to its positive exponent
	neg.w	d5                              ; second's exponent made positive
	bsr.s	float_multiply_positive
	neg.w	d2                              ; negative result
	rts

;------------------------------------------------------------------------------
; float_multiply with the first operand zero or negative and the second positive: zero gives zero, otherwise the
; result of the magnitudes is negated.
;------------------------------------------------------------------------------
float_mul_first_not_positive:
	beq.s	float_mul_result_zero           ; first operand zero: result zero
	neg.w	d2                              ; exponent made positive
	bsr.s	float_multiply_positive
	neg.w	d2                              ; negative result
	rts

;------------------------------------------------------------------------------
; Result zero: exponent 0.
;------------------------------------------------------------------------------
float_mul_result_zero:
	moveq	#0,d2                           ; exponent 0: zero
	rts

;------------------------------------------------------------------------------
; Floating point multiply d0/d1/d2 * d3/d4/d5 -> d0/d1/d2, signs handled by the entries before it.
;------------------------------------------------------------------------------
float_multiply:
	ext.l	d5                              ; sign of the second to the high word of d5
	ble.s	float_mul_second_not_positive   ; zero or negative
	ext.l	d2                              ; sign of the first to the high word of d2
	ble.s	float_mul_first_not_positive    ; zero or negative

;------------------------------------------------------------------------------
; Multiply two positive floats: adds the exponents and picks the partial products for zero low words.
;------------------------------------------------------------------------------
float_multiply_positive:
	add.w	d5,d2                           ; exponent = sum less the bias ($3ff, +1 for the shift)
	subi.w	#$3fe,d2
	tst.w	d1                              ; first operand's low mantissa word zero?
	beq.w	float_mul_low_word_zero
	tst.w	d4                              ; second's low word nonzero: all products
	bne.s	float_mul_full_mantissa
	move.w	d3,d5                           ; d5 = middle word of the second
	beq.s	.second_only_top_word           ; zero: the second has only its top word
	mulu.w	d0,d5                           ; middle * middle
	moveq	#0,d6
	swap	d3                              ; d3.w = top word of the second
	mulu.w	d3,d1                           ; low of first * top of second
	add.l	d5,d1                           ; sum the products of weight 32
	swap	d0                              ; d0.w = top word of the first
	move.w	d3,d5
	mulu.w	d0,d5                           ; d5 = top * top
	addx.l	d6,d5                           ; carry into the top product
	move.w	d3,d6                           ; the two top * middle products
	swap	d3
	move.w	d0,d7
	swap	d0
	mulu.w	d6,d0
	mulu.w	d7,d3
	add.l	d3,d0                           ; summed in d0
	bcc.s	float_mul_normalise             ; no carry: combine the partial sums
	addi.l	#$10000,d5                      ; carry into the top product
	bra.s	float_mul_normalise
.second_only_top_word:
	swap	d3                              ; d3.w = top word of the second
	mulu.w	d3,d1                           ; low of first * top of second
	swap	d0
	move.w	d3,d5
	mulu.w	d0,d5                           ; d5 = top * top
	swap	d0
	mulu.w	d3,d0                           ; d0 = middle of first * top of second
	bra.s	float_mul_normalise
	beq.s	.full_result_zero               ; unreferenced signed entries for float_multiply_full
	neg.w	d2                              ; as float_mul_second_not_positive
	beq.s	.full_result_zero
	bmi.s	.full_result_negative
	neg.w	d5
	bra.s	float_multiply_full
.full_result_negative:
	neg.w	d2
	neg.w	d5
	bsr.s	float_multiply_full
	neg.w	d2
	rts
.full_first_not_positive:
	beq.s	.full_result_zero
	neg.w	d2
	bsr.s	float_multiply_full
	neg.w	d2
	rts
.full_result_zero:
	moveq	#0,d2
	rts
	ext.l	d2                              ; unreferenced: as float_multiply for the full form
	ble.s	.full_first_not_positive

;------------------------------------------------------------------------------
; Multiply two positive floats using all partial products. The signed entries before it ($0edd2-$0edf8) have
; no label and nothing reaches them, so this is only reached through them: dead code in practice.
;------------------------------------------------------------------------------
float_multiply_full:
	add.w	d5,d2                           ; exponent = sum less the bias ($3ff, +1 for the shift)
	subi.w	#$3fe,d2

;------------------------------------------------------------------------------
; Product of the full 48-bit mantissas (from float_multiply_positive when both low words are nonzero): weight-64
; product in d5, weight-48 in d0, weight-32 in d1; lower products are dropped.
;------------------------------------------------------------------------------
float_mul_full_mantissa:
	moveq	#0,d5                           ; d5 = middle word of the second
	move.w	d3,d5
	beq.s	.skip_middle_product            ; zero: skip middle * middle
	mulu.w	d0,d5                           ; middle * middle
.skip_middle_product:
	moveq	#0,d6
	swap	d3                              ; d3.w = top word of the second
	mulu.w	d3,d1                           ; low of first * top of second
	add.l	d5,d1                           ; sum the products of weight 32
	swap	d0                              ; d0.w = top word of the first
	mulu.w	d0,d4                           ; top of first * low of second
	move.w	d3,d5
	mulu.w	d0,d5                           ; d5 = top * top
	addx.l	d6,d5                           ; carry into the top product
	add.l	d4,d1                           ; third product of weight 32
	addx.l	d6,d5                           ; carry into the top product
	move.w	d3,d6                           ; the two top * middle products
	swap	d3
	move.w	d0,d7
	swap	d0
	mulu.w	d6,d0
	mulu.w	d7,d3
	add.l	d3,d0                           ; summed in d0
	bcc.s	float_mul_normalise             ; no carry: combine the partial sums
	addi.l	#$10000,d5                      ; carry into the top product

;------------------------------------------------------------------------------
; Combine the partial sums d5/d0/d1 into the 48-bit result d0:d1 and normalise it by one bit. Exponent above
; $1fff gives the largest value ($ffffffff/$ffff/$1fff, no error), below zero gives zero. The code from $0eb1c
; to $0eb6e (a general normalise) has no label and is not reached.
;------------------------------------------------------------------------------
float_mul_normalise:
	swap	d1                              ; d1.w = high word of the weight-32 sum
	add.w	d0,d1                           ; plus the low word of the weight-48 sum
	clr.w	d0                              ; d0 = high word of the weight-48 sum
	swap	d0
	addx.l	d5,d0                           ; d0 = top 32 bits of the product
	bmi.s	.check_exponent_range           ; top bit set: normalised
	swap	d1                              ; shift the 48-bit result left one bit
	add.l	d1,d1
	swap	d1
	addx.l	d0,d0
	subq.w	#1,d2                           ; exponent -1
.check_exponent_range:
	cmpi.w	#$1fff,d2                       ; exponent within 0..$1fff?
	bhi.s	.exponent_out_of_range
	rts
.exponent_out_of_range:
	tst.w	d2                              ; too large or below zero?
	bpl.s	.overflow_to_maximum            ; too large: largest value, no error
.result_zero:
	moveq	#0,d2                           ; underflow: zero
	moveq	#0,d0
	moveq	#0,d1
	rts
	bmi.s	.normalise_done                 ; unreferenced normalise code from here to $0eb48
.normalise_nonnegative:
	beq.s	.top_long_zero                  ; top long zero: shift by words
	tst.w	d2                              ; negative number?
	bpl.s	.shift_bit_positive
	neg.w	d2                              ; exponent made positive
.shift_bit_negative:
	add.w	d1,d1                           ; shift left until the top bit is set
	addx.l	d0,d0
	dbmi	d2,.shift_bit_negative          ; exponent -1 per bit
.finish_negative:
	subq.w	#1,d2
	neg.w	d2                              ; exponent negative again
	bpl.s	.result_zero                    ; underflowed: zero
	rts
.shift_bit_positive:
	add.w	d1,d1                           ; shift left until the top bit is set
	addx.l	d0,d0
	dbmi	d2,.shift_bit_positive          ; exponent -1 per bit
.finish_positive:
	subq.w	#1,d2
	bmi.s	.result_zero                    ; underflowed: zero
.normalise_done:
	rts
	tst.l	d0                              ; unreferenced entry
	bge.s	.normalise_nonnegative
	rts
.top_long_zero:
	move.w	d1,d0                           ; only the low word holds bits
	beq.s	.result_zero                    ; all zero
	swap	d0                              ; to the top of d0
	moveq	#0,d1
	tst.w	d2                              ; negative number?
	bmi.s	.negative_exponent
	subi.w	#$20,d2                         ; less 32 for the words moved up
	tst.l	d0
	bmi.s	.normalise_done                 ; top bit set already
.shift_long_positive:
	add.l	d0,d0                           ; shift left until the top bit is set
	dbmi	d2,.shift_long_positive
	bra.s	.finish_positive
.negative_exponent:
	neg.w	d2                              ; exponent made positive
.shift_long_negative:
	add.l	d0,d0                           ; shift left until the top bit is set
	dbmi	d2,.shift_long_negative
	bra.s	.finish_negative
.overflow_to_maximum:
	moveq	#-1,d0                          ; overflow gives the largest mantissa and exponent
	moveq	#-1,d1
	move.w	#$1fff,d2
	rts

;------------------------------------------------------------------------------
; 32-bit signed multiply for constant folding: d0 = d0 * d3.
;------------------------------------------------------------------------------
int_multiply:
	tst.l	d3                              ; multiplier negative?
	bpl.s	.multiplier_positive
	neg.l	d3                              ; make it positive and move the sign to d0
	neg.l	d0
	bpl.s	uint_multiply                   ; both negative: product positive
.negative_product:
	neg.l	d0                              ; magnitude of d0
	bsr.s	uint_multiply
	neg.l	d0                              ; negative product
	rts
.multiplier_positive:
	tst.l	d0                              ; multiplicand negative?
	bmi.s	.negative_product

;------------------------------------------------------------------------------
; 32-bit unsigned multiply: d0 = d0 * d3 (low 32 bits).
;------------------------------------------------------------------------------
uint_multiply:
	cmp.l	d0,d3                           ; d3 the larger?
	bhi.s	.multiplier_larger
	cmpi.l	#$10000,d0                      ; d0 fits a word?
	bcc.s	.long_multiply                  ; no: long multiply
.word_multiply:
	mulu.w	d3,d0                           ; both fit a word: one mulu
	rts
.multiplier_larger:
	cmpi.l	#$10000,d3                      ; d3 fits a word?
	bcs.s	.word_multiply
	exg	d3,d0                           ; d3 = the smaller, d0 the larger
.long_multiply:
	move.l	d0,d1                           ; d1 = the larger factor
	mulu.w	d3,d0                           ; low word * d3
	swap	d1                              ; high word * d3
	mulu.w	d3,d1
	swap	d1                              ; shifted up 16 (overflow lost)
	clr.w	d1
	add.l	d1,d0                           ; low 32 bits of the product
	rts

;------------------------------------------------------------------------------
; 32-bit signed integer division (DIV / \): d0 = d3 / d0. Division by zero: moveq #0,d0 / jmp (a6).
;------------------------------------------------------------------------------
int_divide:
	exg	d3,d0                           ; d0 = dividend, d3 = divisor
	move.l	d3,d1                           ; d1 = divisor
	beq.s	int_divide_by_zero              ; zero: error
	bmi.s	.signed_divide                  ; negative divisor: signed path
	cmp.l	d0,d1                           ; divisor not below the dividend (unsigned)?
	bcc.s	.divisor_not_smaller
	ext.l	d3                              ; divisor fits a signed word?
	cmp.l	d1,d3
	bne.s	.signed_divide                  ; no: long division
	divs.w	d1,d0                           ; one divs.w
	bvs.s	.signed_divide                  ; quotient over a word: long division
	ext.l	d0                              ; quotient only
	rts
.divisor_not_smaller:
	bne.s	.quotient_zero                  ; divisor larger: quotient 0
	bgt.s	.signed_divide                  ; never taken (Z set here)
	moveq	#1,d0                           ; equal: quotient 1
	rts
.quotient_zero:
	moveq	#0,d0                           ; dividend smaller than the divisor
	rts
.signed_divide:
	move.l	d1,d3                           ; d3 = divisor; positive?
	bge.s	int_divide_signed_dividend
	neg.l	d3                              ; divide by its magnitude
	bsr.s	int_divide_signed_dividend
	neg.l	d0                              ; and negate the quotient
	rts

;------------------------------------------------------------------------------
; Signed division with a positive divisor d3: d0 = d0 / d3.
;------------------------------------------------------------------------------
int_divide_signed_dividend:
	tst.l	d0                              ; dividend positive?
	bgt.s	uint_divide
	neg.l	d0                              ; divide its magnitude
	bsr.s	uint_divide
	neg.l	d0                              ; and negate the quotient
	rts

;------------------------------------------------------------------------------
; Unsigned division by shift and subtract: d0 = d0 / d3 (d5 used for the quotient).
;------------------------------------------------------------------------------
uint_divide:
	moveq	#0,d5                           ; d5 = quotient
	moveq	#1,d4                           ; d4 = bit of the quotient for the current divisor
	cmp.l	d3,d0                           ; dividend below the divisor: quotient 0
	bcs.s	.halve_divisor
.align_divisor:
	add.l	d3,d3                           ; double the divisor until it passes the dividend
	add.l	d4,d4
	cmp.l	d3,d0
	bcc.s	.align_divisor
	bra.s	.halve_divisor
.next_quotient_bit:
	cmp.l	d3,d0                           ; fits: set this quotient bit and subtract
	bcs.s	.halve_divisor
	or.l	d4,d5
	sub.l	d3,d0
.halve_divisor:
	lsr.l	#1,d3                           ; divisor and quotient bit down one place
	lsr.l	#1,d4
	bne.s	.next_quotient_bit              ; until the quotient bit runs out
	move.l	d5,d0                           ; d0 = quotient
	rts

int_divide_by_zero:
	moveq	#0,d0                           ; error 0: division by zero, to the error exit in a6
	jmp	(a6)

;------------------------------------------------------------------------------
; 32-bit signed MOD: d0 = d3 MOD d0. Division by zero: moveq #0,d0 / jmp (a6).
;------------------------------------------------------------------------------
int_modulo:
	exg	d3,d0                           ; d0 = dividend, d3 = divisor
	move.l	d3,d1                           ; d1 = divisor
	beq.s	int_modulo_by_zero              ; zero: error
	bmi.s	.signed_modulo                  ; negative divisor: signed path
	cmp.l	d0,d1                           ; divisor not below the dividend (unsigned)?
	bcc.s	.modulus_not_smaller
	ext.l	d3                              ; divisor fits a signed word?
	cmp.l	d1,d3                           ; no: long division
	bne.s	.signed_modulo
	divs.w	d1,d0                           ; one divs.w
	bvs.s	.signed_modulo                  ; quotient over a word: long division
	swap	d0                              ; remainder from the high word
	ext.l	d0
	rts
.modulus_not_smaller:
	beq.s	.remainder_zero                 ; equal: remainder 0
	blt.s	.signed_modulo                  ; never taken in practice: d1 positive, d0 below it
	rts                                     ; dividend below the divisor: it is the remainder
.remainder_zero:
	moveq	#0,d0
	rts
.signed_modulo:
	moveq	#0,d5                           ; d5 = quotient for uint_modulo
	move.l	d1,d3                           ; d3 = divisor; positive?
	bge.s	uint_modulo
	neg.l	d3                              ; divide by its magnitude
	bsr.s	uint_modulo
	neg.l	d0                              ; negative divisor: remainder negated
	rts

;------------------------------------------------------------------------------
; Unsigned remainder: d0 = d0 MOD d3 (d5 = quotient).
;------------------------------------------------------------------------------
uint_modulo:
	tst.l	d0                              ; dividend negative?
	bge.s	.dividend_positive
	neg.l	d0                              ; its magnitude: the dividend's sign is dropped
.dividend_positive:
	moveq	#1,d4                           ; d4 = bit of the quotient for the current divisor
	cmp.l	d3,d0                           ; dividend below the divisor: it is the remainder
	bcs.s	.halve_modulus
.align_modulus:
	add.l	d3,d3                           ; double the divisor until it passes the dividend
	add.l	d4,d4
	cmp.l	d3,d0
	bcc.s	.align_modulus
	bra.s	.halve_modulus
.next_remainder_bit:
	cmp.l	d3,d0                           ; fits: set this quotient bit and subtract
	bcs.s	.halve_modulus
	or.l	d4,d5
	sub.l	d3,d0
.halve_modulus:
	lsr.l	#1,d3                           ; divisor and quotient bit down one place
	lsr.l	#1,d4
	bne.s	.next_remainder_bit             ; until the quotient bit runs out; d0 = remainder
	rts

int_modulo_by_zero:
	moveq	#0,d0                           ; error 0: division by zero, to the error exit in a6
	jmp	(a6)

; The 28-byte header of the .O file, filled by write_object_file: $601a, text, data and bss lengths, symbol table
; length, relocation lengths.
object_header:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

; Pointer to the .O file name; start-up ($0005c) stores the name from the command line, default TEST.O.
object_file_name_pointer:
	dc.l	default_object_name

; "TEST.O",0: the default object file name (the listing shows it decoded as code).
default_object_name:
	dc.b	'TEST.O',0                      ; 'TE' (the bytes of the name, decoded as code)
	dc.b	$00

;------------------------------------------------------------------------------
; Write the .O file once the code is generated. Code buffer = code_buffer_start..code_write_pointer.
; Builds the symbol table after the code (free_memory_pointer): STARTADR (text), BssA5 (bss), VARTAB, TYPETAB
; (only when flag_121d3 is set by TYPE / * pointers), DATASTAR, DATAENDE (data) and MEMSIZE (equate,
; option_m_memory_size), then the procedure/label/FN names (add_name_symbols). Relocation words go to a buffer
; at code end + $c000 (a4). Every instruction is passed through relocate_instruction, then the header in
; object_header is filled and the file written: header, text, VARTAB (a5 offset of the indirect area and a size
; byte per indirect variable), TYPETAB (48 bytes: per type the count of indirect then direct variables), the
; string data, the RESUME NEXT table (UUUUTAB, only when resume_next_used_flag is set), the symbols and the
; relocation words; then Fclose.
; Registers during the pass: a0 = instruction, a3 = symbol write pointer, a4 = relocation write pointer, a6 =
; first library symbol, d6 = symbol table length, d7 = address up to which relocation words have been written.
;------------------------------------------------------------------------------
write_object_file:
	move.l	#branch_offset_list,gfa_section_addresses ; RESUME NEXT table buffer
	move.l	code_buffer_start(pc),last_statement_address
	moveq	#84,d6                          ; 6 fixed symbols * 14 bytes
	movea.l	code_buffer_start(pc),a0
	movea.l	code_write_pointer(pc),a1       ; a1 = end of the generated code
	movea.l	a1,a3                           ; a3 = symbol table write pointer, after the code
	move.l	a1,free_memory_pointer          ; memory after the code is used for the tables
	movea.l	a3,a4                           ; a4 = relocation write pointer
	adda.l	#$c000,a4                       ; relocation buffer
	pea	(a4)                            ; keep the relocation buffer start
	move.l	#$53544152,(a3)+                ; 'STARTADR'
	move.l	#$54414452,(a3)+
	move.w	#$a200,(a3)+                    ; type $a200: defined, global, text
	clr.l	(a3)+                           ; value 0: start of the text
	move.l	#$42737341,(a3)+                ; 'BssA5'
	move.l	#$35000000,(a3)+
	move.w	#$a100,(a3)+                    ; type $a100: bss
	clr.l	(a3)+                           ; value 0
	move.l	#$56415254,(a3)+                ; 'VARTAB'
	move.l	#$41420000,(a3)+
	move.w	#$a400,(a3)+                    ; type $a400: data
	clr.l	(a3)+                           ; value 0
	moveq	#6,d0                           ; 6 + indirect variable count, made even
	add.w	indirect_variable_count(pc),d0
	bclr	#$0,d0
	tst.b	flag_121d3                      ; TYPETAB needed (TYPE / pointer variables)?
	beq.s	.string_data_offset
	move.l	#$54595045,(a3)+                ; 'TYPETAB'
	move.l	#$54414200,(a3)+
	move.w	#$a400,(a3)+
	move.l	d0,(a3)+                        ; TYPETAB follows VARTAB in the data
	moveq	#48,d1                          ; TYPETAB is 48 bytes
	add.l	d1,d0
	moveq	#14,d1                          ; one more 14-byte symbol
	add.l	d1,d6
.string_data_offset:
	add.l	data_text_start(pc),d0          ; d0 = data offset of the string data
	sub.l	inline_area_start(pc),d0
	move.l	d0,string_data_offset
	move.l	#$44415441,(a3)+                ; 'DATASTAR'
	move.l	#$53544152,(a3)+
	move.w	#$a400,(a3)+
	move.l	d0,(a3)+                        ; value: data offset of the string data
	move.l	#$44415441,(a3)+                ; 'DATAENDE'
	move.l	#$454e4445,(a3)+
	move.w	#$a400,(a3)+
	add.l	data_area_end_copy(pc),d0       ; plus the length of the data area
	sub.l	data_text_start(pc),d0
	move.l	d0,(a3)+                        ; value: data offset of the end of the data
	move.l	#$4d454d53,(a3)+                ; 'MEMSIZE'
	move.l	#$495a4500,(a3)+
	move.w	#$e000,(a3)+                    ; type $e000: equate
	move.l	option_m_memory_size(pc),(a3)+  ; value: memory size from the M option
	movem.l	a0-a2,-(sp)
	bsr.w	add_name_symbols                ; procedure, label and FN names as symbols
	lea	-$e(a3),a6                      ; first symbol after the fixed ones
	movem.l	(sp)+,a0-a2                     ; a0 = code start, a1 = code end
	clr.l	(a3)                            ; end mark for the symbols
	move.l	a0,d7                           ; d7 = relocation words written up to here
.relocate_loop:
	bsr.w	relocate_instruction            ; relocation words for one instruction
	cmpa.l	a1,a0                           ; until the end of the code
	bcs.s	.relocate_loop
	bsr.w	emit_relocation_gap             ; relocation words up to the end of the code
	lea	object_header(pc),a0
	movea.l	a0,a5                           ; a5 = the header, for the Fwrite
	move.w	#$601a,(a0)+                    ; header magic
	move.l	code_write_pointer(pc),d0
	sub.l	code_buffer_start(pc),d0
	move.l	d0,(a0)+                        ; text length
	moveq	#6,d0                           ; data length: VARTAB, made even
	add.w	indirect_variable_count(pc),d0
	bclr	#$0,d0
	add.l	data_area_end(pc),d0            ; plus the data area
	sub.l	inline_area_start(pc),d0
	addq.l	#1,d0                           ; made even
	bclr	#$0,d0
	tst.b	flag_121d3                      ; TYPETAB present?
	beq.s	.no_typetab
	addi.l	#$30,d0                         ; plus its 48 bytes
.no_typetab:
	tst.b	resume_next_used_flag           ; RESUME NEXT used?
	beq.s	.no_resume_table
	move.l	#$55555555,(a3)+                ; 'UUUUTAB': RESUME NEXT table
	move.l	#$54414200,(a3)+
	move.w	#$a400,(a3)+
	move.l	d0,(a3)+                        ; value: data offset of the table
	moveq	#14,d1                          ; one more 14-byte symbol
	add.l	d1,d6
	move.l	gfa_section_addresses(pc),d1    ; plus the length of the table
	subi.l	#branch_offset_list,d1
	add.l	d1,d0
.no_resume_table:
	move.l	d0,(a0)+                        ; data length
	movea.w	variable_area_end(pc),a1        ; bss length: the variable area ($8000 bias) ...
	adda.l	#$8000,a1
	moveq	#0,d1                           ; ... plus the indirect variables' storage
	move.w	indirect_storage_size(pc),d1
	adda.l	d1,a1
	move.l	a1,(a0)+                        ; bss length
	move.l	d6,(a0)+                        ; symbol table length
	movea.l	(sp),a1                         ; a1 = start of the relocation words
	move.l	a4,d1
	sub.l	a1,d1
	move.l	d1,(a0)+                        ; text relocation length
	moveq	#0,d5                           ; d5 = data relocation length in bytes
	asl.l	#3,d0                           ; n*8+7 run, n = data length in bytes (code runs count words)
	tst.w	d0                              ; low part zero: no remainder run
	beq.s	.data_relocation_runs
	addq.w	#7,d0                           ; low part + 7: a run of untouched units
	move.w	d0,(a4)+                        ; data relocation: all untouched
	addq.w	#2,d5                           ; two relocation bytes
.data_relocation_runs:
	swap	d0                              ; d0 = the high part: that many $ffff runs
	bra.s	.next_data_run
.data_run:
	move.w	#$ffff,(a4)+                    ; $ffff: the largest run
	addq.w	#2,d5                           ; two relocation bytes
.next_data_run:
	dbra	d0,.data_run
	move.l	d5,(a0)+                        ; data relocation length
	clr.w	(a0)+                           ; reserved header word
	movea.l	object_file_name_pointer(pc),a0
	jsr	create_file                     ; create the file
	movea.l	a5,a0                           ; the header
	moveq	#28,d0                          ; 28 bytes
	jsr	write_file                      ; write the header
	movea.l	code_buffer_start(pc),a0
	move.l	2(a5),d0                        ; text length from the header
	jsr	write_file                      ; write the text
	movea.l	code_buffer_start(pc),a0        ; VARTAB is built in the code buffer (already written)
	movea.l	a0,a1
	movea.l	float_variable_table(pc),a2     ; a2 walks the variable entries from the first table
	movea.w	variable_area_end(pc),a3        ; a3 = a5 offset of the indirect storage
	adda.l	#$8000,a3                       ; (variable area end, $8000 bias)
	move.l	a3,(a1)+                        ; VARTAB: offset of the indirect storage
	move.w	indirect_variable_count(pc),d0  ; one byte per indirect variable
	bra.s	.indirect_count_test
.next_indirect:
	move.l	(a2)+,d1                        ; next entry of the variable tables
	bpl.s	.next_indirect                  ; positive: direct variable, skip it
	swap	d1                              ; size byte from the entry's high word
	move.b	d1,(a1)+
.indirect_count_test:
	dbra	d0,.next_indirect
	clr.b	(a1)+                           ; two zero bytes end VARTAB
	clr.b	(a1)+
	move.l	a1,d0
	sub.l	a0,d0                           ; d0 = length, made even
	bclr	#$0,d0
	jsr	write_file                      ; write VARTAB
	tst.b	flag_121d3                      ; TYPETAB needed?
	beq.s	.write_data
	lea	statement_code_buffer(pc),a0    ; TYPETAB is built in statement_code_buffer
	lea	float_variable_table(pc),a3     ; a3 = the list of variable table pointers
	moveq	#11,d0                          ; 12 types
.count_indirect:
	movem.l	(a3),a1-a2                      ; a1 = this table, a2 = the next one (its end)
	moveq	#0,d1                           ; d1 = count
.scan_indirect_entry:
	cmpa.l	a2,a1                           ; end of this table?
	bcc.s	.store_indirect_count
	move.l	(a1)+,d2                        ; next entry
	bpl.s	.scan_indirect_entry            ; positive: direct, not counted
	addq.w	#1,d1                           ; count an indirect variable
	bra.s	.scan_indirect_entry
.store_indirect_count:
	move.w	d1,(a0)+                        ; count of indirect variables of this type
	addq.l	#4,a3
	cmpa.l	#label_line_table,a3            ; after the label table pointer ...
	bne.s	.next_indirect_table
	addq.l	#8,a3                           ; ... skip two pointers that are not variable tables
.next_indirect_table:
	dbra	d0,.count_indirect
	lea	float_variable_table(pc),a3     ; second pass: the direct variables
	moveq	#11,d0                          ; 12 types
.count_direct:
	movem.l	(a3),a1-a2                      ; a1 = this table, a2 = the next one (its end)
	moveq	#0,d1                           ; d1 = count
.scan_direct_entry:
	cmpa.l	a2,a1                           ; end of this table?
	bcc.s	.store_direct_count
	move.l	(a1)+,d2                        ; next entry
	bmi.s	.scan_direct_entry              ; negative: indirect, not counted
	addq.w	#1,d1                           ; count a direct variable
	bra.s	.scan_direct_entry
.store_direct_count:
	move.w	d1,(a0)+                        ; count of direct variables of this type
	addq.l	#4,a3
	cmpa.l	#label_line_table,a3            ; after the label table pointer ...
	bne.s	.next_direct_table
	addq.l	#8,a3                           ; ... skip two pointers that are not variable tables
.next_direct_table:
	dbra	d0,.count_direct
	lea	statement_code_buffer(pc),a0
	moveq	#48,d0                          ; 24 counts = 48 bytes
	jsr	write_file                      ; write TYPETAB
.write_data:
	movea.l	inline_area_start(pc),a0        ; a0 = start of the string data
	move.l	data_area_end(pc),d0            ; d0 = its length, made even
	sub.l	a0,d0
	addq.l	#1,d0
	bclr	#$0,d0
	jsr	write_file                      ; write the string data
	tst.b	resume_next_used_flag           ; RESUME NEXT used?
	beq.s	.write_symbols
	lea	branch_offset_list(pc),a0       ; a0 = start of the table
	move.l	gfa_section_addresses(pc),d0    ; d0 = its length (end pointer kept in gfa_section_addresses)
	sub.l	a0,d0
	jsr	write_file                      ; write the RESUME NEXT table
.write_symbols:
	movea.l	free_memory_pointer(pc),a0      ; a0 = the symbols, after the code
	move.l	d6,d0                           ; d0 = symbol table length
	jsr	write_file                      ; write the symbols
	movea.l	(sp)+,a0                        ; a0 = start of the relocation words
	move.l	$12(a5),d0                      ; text + data relocation lengths from the header
	add.l	$16(a5),d0
	jsr	write_file                      ; write the relocation words
	jmp	close_file                      ; Fclose

;------------------------------------------------------------------------------
; Decode one generated instruction at a0, step a0 past it and fix what it refers to.
; Dispatches on the top 4 bits of the opcode (relocate_line_table). Absolute long operands go to
; relocate_absolute_long; line 6 handles the library call markers $6101/$6001 and threads branches; line 4 handles
; the markers $4af8-$4afe, lea abs.l,a2 of string constants and jsr (a6); line 7 words >= $7f00 are FN markers.
;------------------------------------------------------------------------------
relocate_instruction:
	movea.l	a0,a2                           ; a2 = instruction start
	move.w	(a0)+,d0                        ; d0 = opcode, a0 past it
	move.w	d0,d1
	rol.w	#5,d1                           ; top 4 bits * 2
	andi.w	#$1e,d1
	move.w	relocate_line_table(pc,d1.w),d1 ; self-relative handler offset
	jmp	relocate_line_table(pc,d1.w)

; Self-relative word table: handler for each top opcode nibble (line 0 to line F).
relocate_line_table:
	dc.w	.line_0-relocate_line_table
	dc.w	.line_move-relocate_line_table
	dc.w	.line_move_long-relocate_line_table
	dc.w	.line_move-relocate_line_table
	dc.w	.line_4-relocate_line_table
	dc.w	.line_5-relocate_line_table
	dc.w	.line_6-relocate_line_table
	dc.w	.line_7-relocate_line_table
	dc.w	.line_8-relocate_line_table
	dc.w	.line_9_d-relocate_line_table
	dc.w	.nothing_to_fix-relocate_line_table
	dc.w	.line_b-relocate_line_table
	dc.w	.line_c-relocate_line_table
	dc.w	.line_9_d-relocate_line_table
	dc.w	.line_e-relocate_line_table
	dc.w	.nothing_to_fix-relocate_line_table
.line_0:
	cmpi.w	#$3c,d0                         ; $003c = ori #,ccr
	beq.s	.to_ccr_sr
	cmpi.w	#$7c,d0                         ; $007c = ori #,sr
	beq.s	.to_ccr_sr
	cmpi.w	#$23c,d0                        ; $023c = andi #,ccr
	beq.s	.to_ccr_sr
	cmpi.w	#$27c,d0                        ; $027c = andi #,sr
	beq.s	.to_ccr_sr
	cmpi.w	#$a3c,d0                        ; $0a3c = eori #,ccr
	beq.s	.to_ccr_sr
	cmpi.w	#$a7c,d0                        ; $0a7c = eori #,sr
	beq.s	.to_ccr_sr
	moveq	#56,d1                          ; ea mode 1 in line 0: movep, a displacement word
	and.w	d0,d1
	subq.w	#8,d1
	beq.s	.to_ccr_sr
	btst	#$8,d0                          ; bit 8: btst/bchg/bclr/bset Dn,<ea>: no immediate
	bne.s	.bit_op_ea
	move.w	d0,d1
	andi.w	#$f00,d1                        ; $08xx: static bit op, one immediate word
	cmpi.w	#$800,d1
	beq.s	.skip_immediate_word
	tst.b	d0                              ; size bit 7: long immediate is two words
	bpl.s	.skip_immediate_word
	addq.l	#2,a0                           ; second immediate word
.skip_immediate_word:
	addq.l	#2,a0                           ; skip the immediate word
.bit_op_ea:
	bra.s	.source_ea                      ; then the destination ea
.to_ccr_sr:
	addq.l	#2,a0                           ; one extension word
	rts
.source_ea:
	moveq	#63,d1                          ; d1 = ea mode/register
	and.w	d0,d1
	cmpi.w	#$28,d1                         ; modes 0-4: no extension
	bcs.s	.source_ea_done
	cmpi.w	#$3a,d1                         ; $3a: d16(pc)
	beq.w	skip_pc_relative_extension
	cmpi.w	#$39,d1                         ; $39: abs.l, relocated
	beq.w	relocate_absolute_long
	addq.l	#2,a0                           ; the rest: one extension word
.source_ea_done:
	rts
.source_ea_word:
	moveq	#63,d1                          ; d1 = ea mode/register
	and.w	d0,d1
	cmpi.w	#$28,d1                         ; modes 0-4: no extension
	bcs.s	.word_ea_done
	cmpi.w	#$3a,d1                         ; $3a: d16(pc)
	beq.w	skip_pc_relative_extension
	cmpi.w	#$39,d1                         ; $39: abs.l skipped, not relocated
	bne.s	.skip_one_extension
	addq.l	#2,a0
.skip_one_extension:
	addq.l	#2,a0
.word_ea_done:
	rts
.line_move:
	moveq	#63,d1                          ; d1 = source ea
	and.w	d0,d1
	cmpi.w	#$28,d1                         ; modes 0-4: no extension
	bcs.s	.destination_ea
	cmpi.w	#$3a,d1                         ; $3a: d16(pc)
	bne.s	.source_not_pc_relative
	bsr.w	skip_pc_relative_extension
	bra.s	.destination_ea
.source_not_pc_relative:
	cmpi.w	#$39,d1                         ; $39: abs.l, relocated
	bne.s	.source_one_extension
	bsr.w	relocate_absolute_long
	bra.s	.destination_ea
.source_one_extension:
	addq.l	#2,a0                           ; one extension word
.destination_ea:
	move.w	d0,d1                           ; destination ea, fields reversed: register 9-11, mode 6-8
	lsr.w	#6,d1
	andi.w	#$3f,d1
	moveq	#7,d2                           ; d2 = mode
	and.w	d1,d2
	lsr.w	#3,d1                           ; d1 = register
	asl.w	#3,d2
	or.w	d2,d1                           ; d1 = mode/register in the usual order
	cmpi.w	#$28,d1                         ; modes 0-4: no extension
	bcs.s	.destination_done
	cmpi.w	#$3a,d1                         ; $3a: d16(pc)
	beq.w	skip_pc_relative_extension
	cmpi.w	#$39,d1                         ; $39: abs.l, relocated
	beq.w	relocate_absolute_long
	addq.l	#2,a0                           ; one extension word
.destination_done:
	rts
.line_move_long:
	moveq	#63,d1                          ; d1 = source ea of move.l
	and.w	d0,d1
	cmpi.w	#$28,d1                         ; modes 0-4: no extension
	bcs.s	.long_destination
	cmpi.w	#$39,d1                         ; $39: abs.l, relocated
	beq.s	.long_source_absolute
	cmpi.w	#$3a,d1                         ; $3a: d16(pc)
	beq.s	.long_source_pc_relative
	cmpi.w	#$3c,d1                         ; $3c: #imm long, two words
	bne.s	.long_source_one_extension
	addq.l	#4,a0
	bra.s	.long_destination
.long_source_pc_relative:
	bsr.w	skip_pc_relative_extension
	bra.s	.long_destination
.long_source_absolute:
	bsr.w	relocate_absolute_long
	bra.s	.long_destination
.long_source_one_extension:
	addq.l	#2,a0
.long_destination:
	move.w	d0,d1                           ; destination ea, fields reversed
	lsr.w	#6,d1
	andi.w	#$3f,d1
	moveq	#7,d2                           ; d2 = mode
	and.w	d1,d2
	lsr.w	#3,d1                           ; d1 = register
	asl.w	#3,d2
	or.w	d2,d1                           ; d1 = mode/register in the usual order
.ea_extension:
	andi.w	#$3f,d1                         ; extension words of ea d1
	cmpi.w	#$28,d1                         ; modes 0-4: no extension
	bcs.s	.ea_done
	cmpi.w	#$39,d1                         ; $39: abs.l, relocated
	beq.w	relocate_absolute_long
	cmpi.w	#$3a,d1                         ; $3a: d16(pc)
	beq.w	skip_pc_relative_extension
	addq.l	#2,a0                           ; one extension word
.ea_done:
	rts
.immediate_ea:
	moveq	#63,d1                          ; ea with an immediate whose size the op-mode gives
	and.w	d0,d1
	cmpi.w	#$3c,d1                         ; not #imm: plain ea
	bne.s	.ea_extension
	move.w	d0,d1                           ; op-mode bits 6-8
	andi.w	#$1c0,d1
	cmpi.w	#$1c0,d1                        ; %111: address register long (adda.l etc.)
	beq.s	.long_immediate
	cmpi.w	#$80,d1                         ; %010: long size
	bne.s	.word_immediate
.long_immediate:
	bra.w	relocate_absolute_long          ; long immediate: second word
.word_immediate:
	addq.l	#2,a0                           ; first immediate word
	rts
.line_6:
	cmpi.w	#$6101,d0                       ; library call marker
	beq.w	fix_library_call
	cmpi.w	#$6001,d0                       ; library jump marker
	beq.w	fix_library_jump
	moveq	#100,d5                         ; at most 100 hops
	cmpi.b	#$ff,d0                         ; displacement $ff: marker, becomes 6
	beq.s	.skip_marker
	move.b	d0,d1                           ; d1 = 8-bit displacement
	bne.s	.short_branch                   ; nonzero: short branch
	lsr.w	#8,d0                           ; d0 = condition byte of the branch
	move.w	(a0),d2                         ; d2 = word displacement
.follow_word_branch:
	lea	0(a0,d2.w),a2                   ; a2 = target
	cmpi.b	#$1,1(a2)                       ; target is a library marker
	beq.s	.branch_done
	cmpi.b	#$60,(a2)                       ; target is bra
	beq.s	.thread_word_branch
	cmp.b	(a2),d0                         ; target is the same condition
	beq.s	.thread_word_branch
.branch_done:
	addq.l	#2,a0
	rts
.thread_word_branch:
	move.w	(a2)+,d1                        ; d1 = target's opcode, a2 = its displacement
	subq.w	#1,d5                           ; hop limit
	ble.s	.branch_done
	cmpi.b	#$ff,d1                         ; $ff marker: displacement 6
	bne.s	.target_displacement_fixed
	move.b	#$6,d1
.target_displacement_fixed:
	ext.w	d1
	bne.s	.add_target_displacement        ; 0: word displacement follows
	move.w	(a2),d1                         ; the target's word displacement
.add_target_displacement:
	add.w	d1,d2                           ; displacement to the target's target
	bvs.s	.branch_done                    ; out of word range: stop
	addq.w	#2,d2                           ; +2: the target's displacement is relative to its pc
	bvs.s	.branch_done
	move.w	d2,(a0)                         ; store the threaded displacement
	bne.s	.follow_word_branch             ; follow it further
	move.l	#$4e714e71,-$2(a0)              ; displacement 0: two nops
	bra.s	.branch_done
.skip_marker:
	move.b	#$6,-$1(a0)                     ; the $ff marker becomes displacement 6
	rts
.short_branch:
	lsr.w	#8,d0                           ; d0 = condition byte of the branch
	ext.w	d1                              ; d2 = byte displacement
	move.w	d1,d2
.follow_short_branch:
	lea	0(a0,d2.w),a2                   ; a2 = target
	cmpi.b	#$1,1(a2)                       ; target is a library marker
	beq.s	.short_branch_done
	cmpi.b	#$60,(a2)                       ; target is bra
	beq.s	.thread_short_branch
	cmp.b	(a2),d0                         ; target is the same condition
	beq.s	.thread_short_branch
.short_branch_done:
	rts
.thread_short_branch:
	move.w	(a2)+,d1                        ; d1 = target's opcode, a2 = its displacement
	subq.w	#1,d5                           ; hop limit
	ble.s	.short_branch_done
	cmpi.b	#$ff,d1                         ; $ff marker: displacement 6
	bne.s	.short_target_displacement_fixed
	move.b	#$6,d1
.short_target_displacement_fixed:
	ext.w	d1
	bne.s	.add_short_target_displacement  ; 0: word displacement follows
	move.w	(a2),d1                         ; the target's word displacement
.add_short_target_displacement:
	add.w	d1,d2                           ; displacement to the target's target
	bvs.s	.short_branch_done              ; out of word range: stop
	addq.w	#2,d2                           ; +2: the target's displacement is relative to its pc
	bvs.s	.short_branch_done
	move.w	d2,d1                           ; still fits a byte displacement?
	ext.w	d1
	cmp.w	d1,d2
	bne.s	.short_branch_done              ; no: keep the branch as it is
	move.b	d2,-$1(a0)                      ; store the threaded displacement
	bne.s	.next_hop
	move.w	#$4e71,-$2(a0)                  ; displacement 0: nop
	rts
.next_hop:
	lea	0(a0,d2.w),a2                   ; a2 = the new target
	bra.s	.follow_short_branch
.line_8:
	move.w	d0,d1                           ; line 8: or/div/sbcd
	andi.w	#$1f0,d1
	cmpi.w	#$100,d1                        ; sbcd: no extension
	beq.s	.sbcd_no_extension
	andi.w	#$1c0,d1                        ; op-mode %010: or.l, long immediate
	cmpi.w	#$80,d1
	beq.w	.immediate_ea
	bne.w	.source_ea                      ; the rest: plain ea
.sbcd_no_extension:
	rts
.line_7:
	cmpi.w	#$7f00,d0                       ; line 7: moveq
	bcc.s	.fn_marker                      ; $7f00 and up (bit 8 set): FN markers, not moveq
	rts
.fn_marker:
	subq.b	#2,d0                           ; low byte 0/1: FN bsr
	bmi.w	fix_fn_bsr
	beq.w	fix_fn_jsr_long                 ; 2: FN jsr.l
	subq.b	#2,d0                           ; 3: string FN bsr
	bmi.w	fix_string_fn_bsr
	beq.w	fix_string_fn_jsr_long          ; 4: string FN jsr.l
	subq.b	#2,d0
	subq.l	#2,a0                           ; back to the marker
	beq.w	fix_proc_address_long           ; 6: procedure address long
	addq.l	#2,a0                           ; any other: nothing to fix
.nothing_to_fix:
	rts                                     ; line A, line F and others: nothing to fix
.line_9_d:
	move.w	d0,d1                           ; line 9 (sub) and D (add)
	andi.w	#$130,d1
	cmpi.w	#$100,d1                        ; subx/addx: no extension; else ea with immediate
	bne.w	.immediate_ea
	rts
.line_5:
	move.w	d0,d1                           ; line 5: addq/subq/Scc/DBcc
	andi.w	#$f8,d1
	cmpi.w	#$c8,d1                         ; DBcc: a displacement word
	bne.w	.source_ea                      ; the rest: plain ea
	addq.l	#2,a0                           ; DBcc displacement
.no_extension:
	rts
.line_c:
	move.w	d0,d1                           ; line C: and/mul/abcd/exg
	andi.w	#$1f8,d1
	cmpi.w	#$188,d1                        ; exg Dx,Ay: no extension
	beq.s	.no_extension
	andi.w	#$1f0,d1
	cmpi.w	#$140,d1                        ; exg Dx,Dy / Ax,Ay: no extension
	beq.s	.no_extension
	cmpi.w	#$100,d1                        ; abcd: no extension
	beq.s	.no_extension
	move.w	d0,d1
	andi.w	#$1c0,d1
	cmpi.w	#$80,d1                         ; op-mode %010: and.l, long immediate
	beq.w	.immediate_ea
	bra.w	.source_ea                      ; the rest: plain ea
.line_b:
	move.w	d0,d1                           ; line B: cmp/eor
	andi.w	#$138,d1
	cmpi.w	#$108,d1                        ; cmpm: no extension; else ea with immediate
	bne.w	.immediate_ea
	rts
.line_e:
	moveq	#-64,d1                         ; line E: shifts and rotates
	and.b	d0,d1                           ; size bits 6-7
	cmpi.b	#$c0,d1                         ; %11: memory shift with an ea
	beq.w	.source_ea
	rts                                     ; register shift: no extension
.line_4:
	cmpi.w	#$45f9,d0                       ; lea abs.l,a2 of a string constant
	beq.w	relocate_string_address
	cmpi.w	#$4e96,d0                       ; jsr (a6): a statement start
	beq.w	.statement_start
	cmpi.w	#$4af8,d0                       ; $4af8-$4aff: code generator markers
	bcs.s	.other_line_4
	cmpi.w	#$4aff,d0
	bhi.s	.other_line_4
	cmpi.w	#$4afd,d0                       ; $4afd: procedure jsr.l
	beq.w	fix_proc_jsr_long
	cmpi.w	#$4afe,d0                       ; $4afe: procedure bsr
	beq.w	fix_proc_bsr
	cmpi.w	#$4afa,d0                       ; $4afa: procedure lea d16(pc)
	beq.w	fix_proc_lea_pc
	cmpi.w	#$4afb,d0                       ; $4afb: procedure lea abs.l
	beq.w	fix_proc_lea_long
	cmpi.w	#$4af8,d0                       ; $4af8: GOTO jmp.l
	beq.w	fix_goto_jmp_long
	cmpi.w	#$4af9,d0                       ; $4af9: GOTO bra
	beq.w	fix_goto_bra
.other_line_4:
	btst	#$8,d0                          ; bit 8: chk / lea
	beq.s	.line_4_bit_11
	tst.b	d0                              ; low byte zero: ea from d1 (not set here; unclear)
	beq.w	.ea_extension
	bra.w	.source_ea                      ; chk / lea: source ea
.line_4_bit_11:
	btst	#$b,d0                          ; bit 11 clear: negx/clr/neg/not/move sr,ccr
	beq.w	.source_ea
	cmpi.w	#$4e00,d0                       ; $4e00 and up
	bcc.s	.line_4e
	cmpi.w	#$4afc,d0                       ; $4afc illegal: no extension
	beq.s	.line_4_done
	cmpi.w	#$4c00,d0                       ; $4c00 and up: movem to registers
	bcc.s	.skip_mask_word
	cmpi.w	#$4a00,d0                       ; $4a00 and up: tst/tas
	bcc.w	.source_ea
	tst.b	d0                              ; nbcd/swap/pea: abs.l not relocated
	bpl.w	.source_ea_word
	moveq	#56,d1                          ; movem/ext: ea mode
	and.w	d0,d1
	beq.s	.line_4_done                    ; mode 0: ext, no extension
.skip_mask_word:
	addq.l	#2,a0                           ; movem register mask
	bra.w	.source_ea                      ; then the ea
.line_4e:
	tst.b	d0                              ; jsr/jmp ($4e80 up): ea, abs.l relocated
	bmi.w	.source_ea
	cmpi.w	#$4e70,d0                       ; below $4e70: trap/link/unlk/move usp
	bcs.s	.trap_link_unlk
	cmpi.w	#$4e72,d0                       ; $4e72 stop: an immediate word
	bne.s	.line_4_done
	addq.l	#2,a0                           ; the immediate word
.line_4_done:
	rts
.trap_link_unlk:
	moveq	#56,d1                          ; mode field
	and.w	d0,d1
	cmpi.w	#$10,d1                         ; %010: link, a displacement word
	bne.s	.line_4_done
	addq.l	#2,a0                           ; link displacement
	rts
.statement_start:
	tst.b	resume_next_used_flag           ; RESUME NEXT used?
	beq.s	.statement_done
	move.l	last_statement_address(pc),d0   ; d0 = previous statement start
	movea.l	gfa_section_addresses(pc),a2    ; a2 = RESUME NEXT table write pointer
	move.l	a0,last_statement_address       ; this statement is the next one's base
	sub.l	a0,d0                           ; d0 = distance from the previous statement
	neg.l	d0
	move.l	d0,d1                           ; d1 = 64K steps
	swap	d1
	bra.s	.count_full_steps
.write_full_step:
	move.w	#$ffff,(a2)+                    ; $ffff for each 64K of distance
.count_full_steps:
	dbra	d1,.write_full_step
	move.w	d0,(a2)+                        ; the remaining distance
	move.l	a2,gfa_section_addresses        ; keep the table write pointer
.statement_done:
	rts

;------------------------------------------------------------------------------
; Skip the extension word of a d16(pc) operand.
;------------------------------------------------------------------------------
skip_pc_relative_extension:
	addq.l	#2,a0
	rts

;------------------------------------------------------------------------------
; Library jump marker $6001 nnnn: becomes bra.w ($6000) to library routine nnnn.
;------------------------------------------------------------------------------
fix_library_jump:
	move.w	(a0)+,d4                        ; d4 = library routine number
	move.l	#$60000000,-$4(a0)              ; bra.w, displacement 0 until linked
	bra.s	add_library_reference

;------------------------------------------------------------------------------
; Library call marker $6101 nnnn: becomes bsr.w ($6100) to library routine nnnn.
;------------------------------------------------------------------------------
fix_library_call:
	move.w	(a0)+,d4                        ; d4 = library routine number
	move.l	#$61000000,-$4(a0)              ; bsr.w, displacement 0 until linked

;------------------------------------------------------------------------------
; Find (or add, type $8800 = external) the symbol for library routine d4 (name from library_name_table) and emit
; the relocation word (symbol index * 8 + 6: external PC-relative word) for the displacement.
;------------------------------------------------------------------------------
add_library_reference:
	lea	library_name_table(pc),a2       ; 8-byte name entries
	ext.l	d4
	asl.l	#3,d4                           ; d4 = byte offset of the 8-byte name
	movem.l	0(a2,d4.l),d0-d1                ; d0:d1 = the routine's name
	movea.l	a6,a2                           ; a6 = first library/external symbol
	moveq	#10,d3                          ; 14-byte symbols: 4 read, 10 skipped
	suba.l	d3,a2                           ; start one entry early for the loop
.skip_symbol_rest:
	adda.l	d3,a2                           ; past the rest of this symbol
.search_symbols:
	move.l	(a2)+,d2                        ; first name long; 0 = end of the symbols
	beq.s	.new_symbol
	cmp.l	d0,d2                           ; first half different: next symbol
	bne.s	.skip_symbol_rest
	cmp.l	(a2)+,d1                        ; second half the same?
	addq.l	#6,a2                           ; a2 = next symbol (flags kept from the cmp)
	bne.s	.search_symbols
	bra.s	.emit_external_reference        ; found; a2 is one symbol past it
.new_symbol:
	movem.l	d0-d1,(a3)                      ; append the name
	addq.l	#8,a3
	move.w	#$8800,(a3)+                    ; type $8800: external
	clr.l	(a3)+                           ; value 0
	movea.l	a3,a2                           ; a2 = past the new symbol, as for a found one
	moveq	#14,d0                          ; one more 14-byte symbol
	add.l	d0,d6
	clr.l	(a3)                            ; end mark
.emit_external_reference:
	move.l	a2,d0                           ; d0 = symbol index from the symbol table start
	sub.l	free_memory_pointer(pc),d0
	divu.w	#$e,d0                          ; 14 bytes per symbol
	subq.w	#1,d0                           ; a2 was one symbol past it
	asl.w	#3,d0                           ; index * 8
	addq.w	#6,d0                           ; external PC-relative word
	addq.l	#2,d7                           ; the displacement word is relocated
	bsr.w	emit_relocation_gap             ; untouched words up to it first
	move.w	d0,(a4)+                        ; relocation word for the displacement
	rts

;------------------------------------------------------------------------------
; Absolute long operand at a0. High word $ffff: library routine (external long, relocation 5 then index*8+4);
; $fffe/$fffd/$fffc: external $X procedure / numeric FN / string FN, name taken from the $X line that follows the
; definition line (built at ir_buffer); otherwise a text address (relocation 5, 2).
;------------------------------------------------------------------------------
relocate_absolute_long:
	move.l	(a0)+,d4                        ; d4 = the long, a0 past it
	move.l	d4,d1                           ; d1 = its high word + 1
	swap	d1
	addq.w	#1,d1
	beq.s	.library_absolute               ; $ffff: library routine, low word = number
	addq.w	#1,d1                           ; $fffe: external procedure
	beq.s	.procedure_external
	addq.w	#1,d1                           ; $fffd: external numeric FN
	beq.s	.numeric_fn_external
	addq.w	#1,d1                           ; $fffc: external string FN
	beq.s	.string_fn_external
	addq.l	#4,d7                           ; a text address: one relocated long
	bsr.w	emit_relocation_gap             ; untouched words up to it first
	move.w	#$5,(a4)+                       ; relocation 5, 2: text long
	move.w	#$2,(a4)+
	rts
.library_absolute:
	clr.l	-$4(a0)                         ; the linker supplies the address
	lea	library_name_table(pc),a2
	ext.l	d4
	asl.l	#3,d4                           ; d4 = byte offset of the 8-byte name
	movem.l	0(a2,d4.l),d0-d1                ; d0:d1 = the routine's name
.find_symbol:
	movea.l	a6,a2                           ; a2 = first library/external symbol
.compare_symbol:
	movem.l	(a2)+,d2-d3                     ; d2:d3 = this symbol's name
	tst.l	d2                              ; 0: end of the symbols
	beq.s	.new_symbol
	addq.l	#6,a2                           ; a2 = next symbol
	cmp.l	d0,d2                           ; same name?
	bne.s	.compare_symbol
	cmp.l	d1,d3
	bne.s	.compare_symbol
	bra.s	.emit_external_long             ; found; a2 is one symbol past it
.new_symbol:
	movem.l	d0-d1,(a3)                      ; append the name
	addq.l	#8,a3
	move.w	#$8800,(a3)+
	clr.l	(a3)+                           ; value 0
	movea.l	a3,a2                           ; a2 = past the new symbol, as for a found one
	moveq	#14,d0                          ; one more 14-byte symbol
	add.l	d0,d6
	clr.l	(a3)                            ; end mark
.emit_external_long:
	move.l	a2,d0                           ; d0 = symbol index from the symbol table start
	sub.l	free_memory_pointer(pc),d0
	divu.w	#$e,d0
	subq.w	#1,d0                           ; a2 was one symbol past it
	asl.w	#3,d0                           ; index * 8
	addq.w	#4,d0                           ; external long
	addq.l	#4,d7                           ; the long is relocated
	bsr.s	emit_relocation_gap             ; untouched words up to it first
	move.w	#$5,(a4)+                       ; relocation 5, index*8+4: external long
	move.w	d0,(a4)+
	rts
.string_fn_external:
	movea.l	string_function_line_table(pc),a2 ; a2 = line table of the string FNs
	bra.s	.external_name
.numeric_fn_external:
	movea.l	function_line_table(pc),a2      ; a2 = line table of the numeric FNs
	bra.s	.external_name
.procedure_external:
	movea.l	procedure_line_table(pc),a2     ; a2 = line table of the procedures
.external_name:
	clr.l	-$4(a0)                         ; the linker supplies the address
	asl.w	#2,d4                           ; d4 = number * 4
	movea.l	0(a2,d4.w),a2                   ; a2 = its definition line
	adda.w	(a2),a2                         ; the following line (first word = line length)
	addq.l	#4,a2                           ; past its 4-byte head
.find_x:
	moveq	#-33,d1                         ; look for X (upper case) in the $X line
	and.b	(a2)+,d1
	cmpi.b	#$58,d1
	bne.s	.find_x
	pea	(a0)                            ; keep the operand pointer
	lea	name_buffer_end(pc),a0          ; the name is built in the 8 bytes at ir_buffer
	clr.l	-(a0)                           ; cleared to zeros
	clr.l	-(a0)
.skip_spaces:
	move.b	(a2)+,d1                        ; skip spaces after the X
	cmpi.b	#$20,d1
	beq.s	.skip_spaces
.copy_name:
	move.b	d1,(a0)+                        ; copy the name up to a space or control code
	move.b	(a2)+,d1
	cmpi.b	#$20,d1                         ; (no 8-character limit)
	bhi.s	.copy_name
	movea.l	(sp)+,a0                        ; a0 back to the operand
	movem.l	ir_buffer(pc),d0-d1             ; d0:d1 = the name
	bra.w	.find_symbol                    ; find or add it as an external symbol

;------------------------------------------------------------------------------
; Emit the relocation words for the untouched words between d7 and a0: blocks of 4096 words as $8007, the rest as
; n*8+7. Exit: d7 = a0.
;------------------------------------------------------------------------------
emit_relocation_gap:
	sub.l	a0,d7
	neg.l	d7                              ; d7 = bytes since the last relocated word
	lsr.l	#1,d7                           ; in words
	divu.w	#$1000,d7                       ; quotient = 4096-word blocks, remainder in the high word
	bra.s	.count_gap_blocks
.gap_block:
	move.w	#$8007,(a4)+                    ; 4096 untouched words
.count_gap_blocks:
	dbra	d7,.gap_block
	swap	d7                              ; d7.w = the remaining words
	tst.w	d7                              ; none left
	beq.s	.gap_done
	asl.w	#3,d7                           ; n*8+7
	addq.w	#7,d7                           ; n untouched words
	move.w	d7,(a4)+
.gap_done:
	move.l	a0,d7                           ; relocation words written up to a0
	rts

;------------------------------------------------------------------------------
; lea abs.l,a2 ($45f9) of a string constant: add string_data_offset to the address, relocation 5, 1 (data).
;------------------------------------------------------------------------------
relocate_string_address:
	move.l	string_data_offset(pc),d0       ; d0 = data offset of the string data
	add.l	d0,(a0)+                        ; string address made a data offset; a0 past it
	addq.l	#4,d7                           ; the long is relocated
	bsr.s	emit_relocation_gap             ; untouched words up to it first
	move.w	#$5,(a4)+                       ; relocation 5, 1: data long
	move.w	#$1,(a4)+                       ; relocation 5, 1: data long
	rts

; Offset of the string pool in the data section, set by write_object_file.
string_data_offset:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Marker $4afd: becomes jsr abs.l ($4eb9) to the procedure address.
;------------------------------------------------------------------------------
fix_proc_jsr_long:
	move.w	#$4eb9,-$2(a0)                  ; $4eb9 = jsr (xxx).l
	movea.l	procedure_address_table(pc),a2  ; a2 = procedure addresses

;------------------------------------------------------------------------------
; Replace the number at (a0) with the long address from table a2; relocation 5, 2 unless the entry is -1 (undefined).
;------------------------------------------------------------------------------
fix_absolute_reference:
	move.l	(a0),d0                         ; d0 = number in the low word
	asl.w	#2,d0                           ; 4-byte entries
	move.l	0(a2,d0.w),d1                   ; d1 = the address (text offset)
	not.l	d1                              ; -1: undefined
	beq.s	.undefined
	not.l	d1
	move.l	d1,(a0)+                        ; the address replaces the number
	addq.l	#4,d7                           ; the long is relocated
	bsr.s	emit_relocation_gap             ; untouched words up to it first
	move.w	#$5,(a4)+
	move.w	#$2,(a4)+                       ; relocation 5, 2: text long
	rts
.undefined:
	move.l	d1,(a0)+                        ; -1 stored, no relocation
	rts

;------------------------------------------------------------------------------
; Marker $4afe: becomes bsr.w ($6100) to the procedure.
;------------------------------------------------------------------------------
fix_proc_bsr:
	move.w	#$6100,-$2(a0)                  ; $6100 = bsr.w
	bra.s	fix_proc_pc_relative

;------------------------------------------------------------------------------
; Marker $4afb: becomes lea abs.l,a2 ($45f9) of the procedure.
;------------------------------------------------------------------------------
fix_proc_lea_long:
	move.w	#$45f9,-$2(a0)                  ; $45f9 = lea (xxx).l,a2

;------------------------------------------------------------------------------
; Marker $7f06: the word pair becomes the long address of the procedure.
;------------------------------------------------------------------------------
fix_proc_address_long:
	movea.l	procedure_address_table(pc),a2
	bra.s	fix_absolute_reference

;------------------------------------------------------------------------------
; Marker $4afa: becomes lea d16(pc),a2 ($45fa) of the procedure.
;------------------------------------------------------------------------------
fix_proc_lea_pc:
	move.w	#$45fa,-$2(a0)                  ; $45fa = lea d16(pc),a2

;------------------------------------------------------------------------------
; Marker $4afe/$4afa: a2 = procedure_address_table for fix_pc_relative_reference.
;------------------------------------------------------------------------------
fix_proc_pc_relative:
	movea.l	procedure_address_table(pc),a2  ; a2 = procedure addresses

;------------------------------------------------------------------------------
; Replace the number at (a0) with the PC-relative displacement to the address in table a2.
;------------------------------------------------------------------------------
fix_pc_relative_reference:
	move.w	(a0),d0                         ; d0 = number
	asl.w	#2,d0                           ; 4-byte entries
	move.l	0(a2,d0.w),d0                   ; d0 = text offset of the target
	add.l	code_buffer_start(pc),d0        ; as an address in the code buffer
	sub.l	a0,d0                           ; relative to the displacement word
	move.w	d0,(a0)+                        ; the displacement replaces the number
	rts

;------------------------------------------------------------------------------
; Marker $4af8: becomes jmp abs.l ($4ef9) to the label.
;------------------------------------------------------------------------------
fix_goto_jmp_long:
	move.w	#$4ef9,-$2(a0)                  ; $4ef9 = jmp (xxx).l
	movea.l	label_address_table(pc),a2      ; a2 = label addresses
	bra.s	fix_absolute_reference

;------------------------------------------------------------------------------
; Marker $4af9: becomes bra.w ($6000) to the label.
;------------------------------------------------------------------------------
fix_goto_bra:
	move.w	#$6000,-$2(a0)                  ; $6000 = bra.w
	movea.l	label_address_table(pc),a2      ; a2 = label addresses
	bra.s	fix_pc_relative_reference

;------------------------------------------------------------------------------
; Marker $7f02: jsr abs.l to a numeric FN.
;------------------------------------------------------------------------------
fix_fn_jsr_long:
	move.w	#$4eb9,-$2(a0)                  ; $4eb9 = jsr (xxx).l
	movea.l	numeric_fn_address_table(pc),a2 ; a2 = numeric FN addresses
	bra.s	fix_absolute_reference

;------------------------------------------------------------------------------
; Marker $7f01: bsr.w to a numeric FN.
;------------------------------------------------------------------------------
fix_fn_bsr:
	move.w	#$6100,-$2(a0)                  ; $6100 = bsr.w
	movea.l	numeric_fn_address_table(pc),a2 ; a2 = numeric FN addresses
	bra.s	fix_pc_relative_reference

;------------------------------------------------------------------------------
; Marker $7f04: jsr abs.l to a string FN.
;------------------------------------------------------------------------------
fix_string_fn_jsr_long:
	move.w	#$4eb9,-$2(a0)                  ; $4eb9 = jsr (xxx).l
	movea.l	string_fn_address_table(pc),a2  ; a2 = string FN addresses
	bra.w	fix_absolute_reference

;------------------------------------------------------------------------------
; Marker $7f03: bsr.w to a string FN.
;------------------------------------------------------------------------------
fix_string_fn_bsr:
	move.w	#$6100,-$2(a0)                  ; $6100 = bsr.w
	movea.l	string_fn_address_table(pc),a2  ; a2 = string FN addresses
	bra.s	fix_pc_relative_reference

;------------------------------------------------------------------------------
; Add a text symbol ($a200) for every defined procedure, label, numeric FN and string FN: '_' then the first 7
; characters of its name (from the name lists), value = its address.
;------------------------------------------------------------------------------
add_name_symbols:
	move.l	#$ffff,d3                       ; d3 = $ffff: d0 full above this (3 bytes)
	move.l	#$5f000000,d7                   ; '_' prefix
	moveq	#14,d4                          ; d4 = 14 bytes per symbol
	movem.l	procedure_address_table(pc),a0-a1 ; a0 = procedure address table, a1 = its end
	movea.l	procedure_name_list(pc),a2      ; a2 = their names
	bsr.s	add_table_symbols
	movem.l	label_address_table(pc),a0-a1   ; a0 = label address table, a1 = its end
	movea.l	label_name_list(pc),a2          ; a2 = their names
	bsr.s	add_table_symbols
	movem.l	numeric_fn_address_table(pc),a0-a1 ; a0 = numeric FN address table, a1 = its end
	movea.l	numeric_fn_name_list(pc),a2     ; a2 = their names
	bsr.s	add_table_symbols
	movem.l	string_fn_address_table(pc),a0-a1 ; a0 = string FN address table, a1 = its end
	movea.l	string_fn_name_list(pc),a2      ; a2 = their names
	bra.s	add_table_symbols               ; returns through add_table_symbols

;------------------------------------------------------------------------------
; One symbol: a0 = address table entry, a2 = length-prefixed name. Undefined (negative) entries are skipped.
;------------------------------------------------------------------------------
add_name_symbol:
	moveq	#0,d1                           ; d1 = shift register for the low 4 name bytes
	move.l	(a0)+,d5                        ; d5 = address (text offset)
	bpl.s	.pack_name                      ; defined: make a symbol
	move.b	(a2)+,d1                        ; undefined: skip its name
	adda.w	d1,a2
	bra.s	add_table_symbols
.pack_name:
	moveq	#0,d0                           ; d0 = high 4 name bytes
	moveq	#0,d2                           ; d2 = name length
	move.b	(a2)+,d2
	bra.s	.count_name_chars
.pack_name_char:
	cmp.l	d3,d0                           ; already 7 characters?
	bhi.s	.next_name_char                 ; yes: skip the rest
	asl.l	#8,d0                           ; shift d0:d1 left one byte
	rol.l	#8,d1
	move.b	d1,d0
	move.b	(a2),d1                         ; next character into the low byte
.next_name_char:
	addq.l	#1,a2
.count_name_chars:
	dbra	d2,.pack_name_char              ; for each name character
.pad_name:
	cmp.l	d3,d0                           ; pad with zero bytes until 7 bytes
	bhi.s	.store_symbol
	asl.l	#8,d0                           ; shift d0:d1 left one byte
	rol.l	#8,d1
	move.b	d1,d0
	clr.b	d1
	bra.s	.pad_name
.store_symbol:
	or.l	d7,d0                           ; '_' in the first byte
	move.l	d0,(a3)+
	move.l	d1,(a3)+
	move.w	#$a200,(a3)+                    ; type $a200
	move.l	d5,(a3)+                        ; value = the address
	add.l	d4,d6                           ; one more 14-byte symbol

;------------------------------------------------------------------------------
; Loop over the address table a0 to a1.
;------------------------------------------------------------------------------
add_table_symbols:
	cmpa.l	a1,a0                           ; entries left?
	bcs.s	add_name_symbol
	rts

;------------------------------------------------------------------------------
; Give every variable its a5 offset, starting at -$8000. First the indirect variables (negative entries) get a 4-byte
; pointer slot each (assign_indirect_slots), then the direct ones their own space (assign_direct_offsets).
; Exit: variable_area_end, indirect_storage_size, indirect_variable_count.
;------------------------------------------------------------------------------
assign_variable_offsets:
	move.l	#$ffff8000,d1                   ; a5 offsets start at -$8000
	moveq	#0,d2                           ; d2 = indirect storage size
	moveq	#0,d3                           ; d3 = indirect variable count
	lea	assign_indirect_slots(pc),a3    ; first the indirect variables
	bsr.s	assign_offsets_all_tables
	lea	assign_direct_offsets(pc),a3    ; then the direct ones
	bsr.s	assign_offsets_all_tables
	lea	variable_area_end(pc),a0        ; variable_area_end, indirect_storage_size, indirect_variable_count
	movem.w	d1-d3,(a0)
	rts

;------------------------------------------------------------------------------
; Run the routine in a3 over the 12 variable tables with their element sizes: float 8, string 6, int 4, bool 1,
; float/string/int/bool arrays 6 each, word 2, byte 1, then (after the label and procedure line tables) word and
; byte arrays 6, keeping d1 and d2 even after the odd sizes.
;------------------------------------------------------------------------------
assign_offsets_all_tables:
	lea	float_variable_table(pc),a0     ; a0 = list of table pointers (start, next = end)
	moveq	#8,d0                           ; float variables
	jsr	(a3)
	moveq	#6,d0                           ; string variables
	jsr	(a3)
	moveq	#4,d0                           ; integer variables
	jsr	(a3)
	moveq	#1,d0                           ; boolean variables
	jsr	(a3)
	btst	#$0,d1                          ; offset made even after the bytes
	beq.s	.align_storage_after_bools
	addq.w	#1,d1
.align_storage_after_bools:
	btst	#$0,d2                          ; storage size made even
	beq.s	.array_tables
	addq.w	#1,d2
.array_tables:
	moveq	#6,d0                           ; float, string, int, bool arrays: descriptors
	jsr	(a3)
	jsr	(a3)
	jsr	(a3)
	jsr	(a3)
	moveq	#2,d0                           ; word variables
	jsr	(a3)
	moveq	#1,d0                           ; byte variables
	jsr	(a3)
	btst	#$0,d1                          ; offset made even after the bytes
	beq.s	.align_storage_after_bytes
	addq.w	#1,d1
.align_storage_after_bytes:
	btst	#$0,d2                          ; storage size made even
	beq.s	.skip_line_tables
	addq.w	#1,d2
.skip_line_tables:
	addq.l	#8,a0                           ; skip the label and procedure line tables
	moveq	#6,d0                           ; word arrays
	jsr	(a3)
	jmp	(a3)                            ; byte arrays; returns through the routine

;------------------------------------------------------------------------------
; For each indirect entry of the table at (a0): low word = next 4-byte slot (d1), byte 1 = size d0; d2 += size, d3 += 1.
;------------------------------------------------------------------------------
assign_indirect_slots:
	movem.l	(a0),a1-a2                      ; a1 = this table, a2 = the next one (its end)
.next_indirect_entry:
	cmpa.l	a2,a1                           ; end of the table?
	bcc.s	.indirect_table_done
	tst.l	(a1)+                           ; indirect entries are negative
	bpl.s	.next_indirect_entry
	move.w	d1,-$2(a1)                      ; pointer slot
	addq.l	#4,d1                           ; 4-byte pointer slot each
	move.b	d0,-$3(a1)                      ; size in byte 1
	add.l	d0,d2                           ; storage for the value
	addq.l	#1,d3                           ; count it
	bra.s	.next_indirect_entry
.indirect_table_done:
	addq.l	#4,a0                           ; next table pointer
	rts

;------------------------------------------------------------------------------
; For each direct entry of the table at (a0): low word = offset d1, high word = 1; d1 += size d0.
;------------------------------------------------------------------------------
assign_direct_offsets:
	movem.l	(a0),a1-a2                      ; a1 = this table, a2 = the next one (its end)
.next_direct_entry:
	cmpa.l	a2,a1                           ; end of the table?
	bcc.s	.direct_table_done
	tst.l	(a1)+                           ; indirect entries are skipped
	bmi.s	.next_direct_entry
	move.w	d1,-$2(a1)                      ; offset of the variable
	add.l	d0,d1                           ; next offset
	move.w	#$1,-$4(a1)                     ; direct
	bra.s	.next_direct_entry
.direct_table_done:
	addq.l	#4,a0                           ; next table pointer
	rts

;------------------------------------------------------------------------------
; Copy d0 bytes downwards from a0 to a1 (both point at the end); for overlapping moves to higher memory.
;------------------------------------------------------------------------------
copy_memory_backwards:
	movem.l	d1-d7/a2-a6,-(sp)
	lsr.l	#1,d0                           ; bit 0: one byte
	bcc.s	.test_word_down
	move.b	-(a0),-(a1)
.test_word_down:
	lsr.l	#1,d0                           ; bit 1: a word
	bcc.s	.test_long_down
	move.w	-(a0),-(a1)
.test_long_down:
	lsr.l	#1,d0                           ; bit 2: a long
	bcc.s	.test_8_bytes_down
	move.l	-(a0),-(a1)
.test_8_bytes_down:
	lsr.l	#1,d0                           ; bit 3: 8 bytes
	bcc.s	.test_16_bytes_down
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
.test_16_bytes_down:
	lsr.l	#1,d0                           ; bit 4: 16 bytes
	bcc.s	.test_32_bytes_down
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
.test_32_bytes_down:
	lsr.l	#1,d0                           ; bit 5: 32 bytes
	bcc.s	.test_64_bytes_down
	lea	-$20(a0),a0
	movem.l	(a0),d1-d7/a2
	movem.l	d1-d7/a2,-(a1)
.test_64_bytes_down:
	lsr.l	#1,d0                           ; bit 6: 64 bytes
	bcc.s	.test_128_bytes_down
	lea	-$40(a0),a0
	movem.l	$20(a0),d1-d7/a2
	movem.l	d1-d7/a2,-(a1)
	movem.l	(a0),d1-d7/a2
	movem.l	d1-d7/a2,-(a1)
.test_128_bytes_down:
	lsr.l	#1,d0                           ; bit 7: 128 bytes
	bcc.s	.test_256_bytes_down
	lea	-$80(a0),a0
	movem.l	$60(a0),d1-d7/a2
	movem.l	d1-d7/a2,-(a1)
	movem.l	$30(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
.test_256_bytes_down:
	lsr.l	#1,d0                           ; bit 8: 256 bytes; d0 = 512-byte blocks
	bcc.s	.next_512_block_down
	move.l	-(a0),-(a1)                     ; 16 bytes, then 240 in the block tail
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	lea	-$f0(a0),a0
	bra.s	.copy_240_bytes_down
.copy_512_bytes_down:
	lea	-$200(a0),a0                    ; 512 bytes: 272 here, 240 below
	movem.l	$1e0(a0),d1-d7/a2
	movem.l	d1-d7/a2,-(a1)
	movem.l	$1b0(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	$180(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	$150(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	$120(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	$f0(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
.copy_240_bytes_down:
	movem.l	$c0(a0),d1-d7/a2-a6             ; last 240 bytes of a block
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	$90(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	$60(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	$30(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
	movem.l	(a0),d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,-(a1)
.next_512_block_down:
	dbra	d0,.copy_512_bytes_down         ; next 512-byte block
	movem.l	(sp)+,d1-d7/a2-a6
	rts

;------------------------------------------------------------------------------
; Copy d0 bytes from a0 to a1, upwards.
;------------------------------------------------------------------------------
copy_memory_forwards:
	movem.l	d1-d7/a2-a6,-(sp)
	lsr.l	#1,d0                           ; bit 0: one byte
	bcc.s	.test_word_up
	move.b	(a0)+,(a1)+
.test_word_up:
	lsr.l	#1,d0                           ; bit 1: a word
	bcc.s	.test_long_up
	move.w	(a0)+,(a1)+
.test_long_up:
	lsr.l	#1,d0                           ; bit 2: a long
	bcc.s	.test_8_bytes_up
	move.l	(a0)+,(a1)+
.test_8_bytes_up:
	lsr.l	#1,d0                           ; bit 3: 8 bytes
	bcc.s	.test_16_bytes_up
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.test_16_bytes_up:
	lsr.l	#1,d0                           ; bit 4: 16 bytes
	bcc.s	.test_32_bytes_up
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
.test_32_bytes_up:
	lsr.l	#1,d0                           ; bit 5: 32 bytes
	bcc.s	.test_64_bytes_up
	movem.l	(a0)+,d1-d7/a2
	movem.l	d1-d7/a2,(a1)
	lea	$20(a1),a1
.test_64_bytes_up:
	lsr.l	#1,d0                           ; bit 6: 64 bytes
	bcc.s	.test_128_bytes_up
	movem.l	(a0)+,d1-d7/a2
	movem.l	d1-d7/a2,(a1)
	movem.l	(a0)+,d1-d7/a2
	movem.l	d1-d7/a2,$20(a1)
	lea	$40(a1),a1
.test_128_bytes_up:
	lsr.l	#1,d0                           ; bit 7: 128 bytes
	bcc.s	.test_256_bytes_up
	movem.l	(a0)+,d1-d7/a2
	movem.l	d1-d7/a2,(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$20(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$50(a1)
	lea	$80(a1),a1
.test_256_bytes_up:
	lsr.l	#1,d0                           ; bit 8: 256 bytes; d0 = 512-byte blocks
	bcc.s	.next_512_block_up
	move.l	(a0)+,(a1)+                     ; 16 bytes, then 240 in the block tail
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	move.l	(a0)+,(a1)+
	lea	-$110(a1),a1                    ; a1 set back for the tail's $110 offsets
	bra.s	.copy_240_bytes_up
.copy_512_bytes_up:
	movem.l	(a0)+,d1-d7/a2                  ; 512 bytes: 272 here, 240 below
	movem.l	d1-d7/a2,(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$20(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$50(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$80(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$b0(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$e0(a1)
.copy_240_bytes_up:
	movem.l	(a0)+,d1-d7/a2-a6               ; last 240 bytes of a block
	movem.l	d1-d7/a2-a6,$110(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$140(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$170(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$1a0(a1)
	movem.l	(a0)+,d1-d7/a2-a6
	movem.l	d1-d7/a2-a6,$1d0(a1)
	lea	$200(a1),a1                     ; next 512 bytes
.next_512_block_up:
	dbra	d0,.copy_512_bytes_up           ; next 512-byte block
	movem.l	(sp)+,d1-d7/a2-a6
	rts

	section	data

; Library routine names, 8 bytes each, indexed by routine number (0 blank, 1 BOX, ... $102 MID3STR, ...).
; Used for the external symbols of the .O file.
library_name_table:
	dc.b	'        BOX     CIRCLE  DRAWTO  ELLARC  ELLIPSE FFTOI   FITOF   FADD    FADDV   FDIV    FDIVV   FEQ     FEQEQ   FEVEN   FGE     FGT     FIDIV   FLE     FLT     FMOD    FMUL    FMULV   FNE     FODD    FPOW    FSQUARE FSUB    FSUBV   FXDIV   FXIDIV  FXMOD   FXPOW   FXSUB   ISQUARE LDIV    LINE    LMOD    LMUL    PARC    PBOX    PCIRCLE PELLARC PELLIPSEPLOT    PRBOX   RBOX    TIMER   VFADD   VFDIV   VFMUL   VFSUB   FADDQ1  FSUBQ1  VFADDQ1 VFSUBQ1 XLDIV   XLMOD   INIT    END     PRCR    PRKOMMA PRTICK  PRNUM   PRINUM  BMOVE   ACHAR   ATEXT   PSET    HLINE   ACLIP   PTST    ALINE   ARECT   APOLY   VDI     VDI1    VDI3    VDI4    AES     AES1    COLOR   GRAPHMODDEFLI1  DEFLI2  DEFLI34 ERROR   FILL    FILL3   RANDOMIZRANDOM  RND     RAND    FORI1   ADDRIN  ADDROUT CONTRL  GCONTRL GINTIN  GINTOUT HIMEM   BASEPAGEINTIN   INTOUT  PTSIN   PTSOUT  VDIBASE WINDTAB GB      SWINDTABCRSLIN  CRSCOL  MOUSEX  MOUSEY  MOUSEK  RADDRIN RADDROUTRCONTRL RGCONTRLRGINTIN RGINTOUTRINTIN  RINTOUT RPTSIN  RPTSOUT RWINDTABSADDRIN SADDROUTSCONTRL SGCONTRLSGINTIN SGINTOUTSINTIN  SINTOUT SPTSIN  SPTSOUT SPOKE   SDPOKE  SLPOKE  DELAY   LOCATE  SOBNEXT SOBHEAD SOBTAIL SOBTYPE SOBFLAGSSOBSTATESOBSPEC SOBX    SOBY    SOBW    SOBH    ROBADR  ROBNEXT ROBHEAD ROBTAIL ROBTYPE ROBFLAGSROBSTATEROBSPEC ROBX    ROBY    ROBW    ROBH    EMPSTR  CHRSTR  MKISTR  MKLSTR  PRSTR   PRCHR   PRMKI   PRMKL   LENSTR  ASCSTR  CVISTR  CVLSTR  CPRSTR  CONSTR  FINT    FTRUNC  FFRAC   FSIN    FCOS    FTAN    FATN    FEXP    FLOG    FLOG10  FASIN   FACOS   FSQR    FDEG    FRAD    ROUND   FSINQ   FCOSQ   VFINT   VFTRUNC VFFRAC  VFSIN   VFCOS   VFTAN   VFATN   VFEXP   VFLOG   VFLOG10 VFASIN  VFACOS  VFSQR   VFDEG   VFRAD   VROUND  VFSINQ  VFCOSQ  VFXSUB  VFXDIV  VFEQ    VFNE    VFGE    VFGT    VFLE    VFLT    VFMOD   VFXMOD  VFIDIV  VFXIDIV DIMF    DIMS    DIMI    DIMB    DIMW    DIMC    AFILLF  AFILLI  AFILLW  AFILLC  AFILLB  MOUSE   FREx    FRE     STOS    PXNUM   PXINUM  PXSTR   PXCSTR  EMPSTOS CONSTOS CHRSTOS MKISTOS M