                                                ;   blank-padded; $ff follows the last
	dc.b	$ff                             ; end of the name table
default_gfa_name:
	dc.b	'COMP.GFA',0                    ; source name used when the command line is empty
msg_read_error:
	dc.b	'Read error',0                  ; 'read error'
	dc.b	$00
msg_disk_full:
	dc.b	'Disk full',0                   ; 'disk full': write returned fewer bytes
msg_write_error:
	dc.b	'Write error',0                 ; 'write error'

	section	bss
free_memory_pointer:	ds.b	4               ; start of free memory: the .GFA file, later the code end
free_memory_size:	ds.b	4               ; Malloc'd free memory less 16K
optimise_no_change_flag:	ds.b	2       ; optimiser pass flag: st at the start of a pass, sf on every IR change;
                                                ;   still set = done
gfa_section_addresses:	ds.b	4               ; first .GFA section address; RESUME NEXT table pointer at write time
last_statement_address:	ds.b	36              ; RESUME NEXT: last statement start (jsr (a6)) when writing
label_name_list:	ds.b	4               ; length-prefixed label names
procedure_name_list:	ds.b	12              ; length-prefixed procedure names
numeric_fn_name_list:	ds.b	4               ; length-prefixed numeric FN names
string_fn_name_list:	ds.b	4               ; length-prefixed string FN names
program_start:	ds.b	12                      ; first program line
float_variable_table:	ds.b	4               ; variable tables: 4-byte entries, negative = indirect
string_variable_table:	ds.b	4
int_variable_table:	ds.b	4
bool_variable_table:	ds.b	4
float_array_table:	ds.b	4
string_array_table:	ds.b	4
int_array_table:	ds.b	4
bool_array_table:	ds.b	4
word_variable_table:	ds.b	4
byte_variable_table:	ds.b	4
label_line_table:	ds.b	4               ; line of each label
procedure_line_table:	ds.b	4               ; line of each procedure
word_array_table:	ds.b	4
byte_array_table:	ds.b	4
function_line_table:	ds.b	4               ; line of each numeric FN
string_function_line_table:	ds.b	4       ; line of each string FN
identifier_flag_tables_end:	ds.b	12
gfa_section_addresses_end:	ds.b	28      ; end of the 38 relocated section addresses of the .GFA header (two more
                                                ;   entries follow)
label_address_table:	ds.b	4               ; text offset of each label, -1 undefined
label_data_offsets:	ds.b	4
procedure_address_table:	ds.b	4       ; text offset of each procedure, -1 undefined
numeric_fn_address_table:	ds.b	4       ; text offset of each numeric FN, -1 undefined
string_fn_address_table:	ds.b	4       ; text offset of each string FN, -1 undefined
routine_tables_end:	ds.b	4               ; end of the string FN address table
variable_area_end:	ds.b	2               ; a5 offset after the direct variables ($8000 bias)
indirect_storage_size:	ds.b	2               ; bytes of storage for the indirect variables
indirect_variable_count:	ds.b	2       ; number of indirect variables
code_write_pointer:	ds.b	4               ; end of the generated code
code_buffer_start:	ds.b	4               ; start of the generated code
ext_l_d0_code_address:	ds.b	4               ; address in the code buffer of the last ext.l d0 emitted (0 = none)
ext_w_d0_code_address:	ds.b	4               ; address in the code buffer of the last ext.w d0 emitted (0 = none)
previous_ir_code:	ds.b	2               ; IR code handled before the current one (codegen loop)
current_ir_code:	ds.b	2               ; IR code being generated (codegen loop)
last_library_routine:	ds.b	2               ; number of the library routine last called (emit_library_call)
header_and_text_buffer:	ds.b	256
ir_buffer:	ds.b	2                       ; also the 8-byte name buffer of relocate_absolute_long
ir_buffer_second_word:	ds.b	6
name_buffer_end:	ds.b	992             ; end of the 8-byte name built at ir_buffer
statement_code_buffer:	ds.b	2               ; also the TYPETAB build buffer of write_object_file
statement_code_routine_word:	ds.b	4       ; second word of the statement code: routine number when the code is a
                                                ;   library call ($6101 nnnn)
statement_code_buffer_plus_6:	ds.b	994
source_line_number:	ds.b	4
inline_area_start:	ds.b	4               ; start of the data section contents
data_text_start:	ds.b	4
data_area_end:	ds.b	4                       ; end of the string pool / data area
string_pool_limit:	ds.b	4
data_area_end_copy:	ds.b	4
file_handle:	ds.b	2                       ; handle of the open file
option_m_memory_size:	ds.b	4               ; M option: MEMSIZE symbol value
option_percent_value:	ds.b	1
option_rc_word_flag:	ds.b	1
function_returns_int_flag:	ds.b	1
flag_121d3:	ds.b	1                       ; TYPETAB needed: set by ERASE, TYPE and pointer use
branch_offset_list:	ds.b	16000           ; branch list of the code generator; RESUME NEXT table when writing
program_end:	ds.b	130                     ; Mshrink end and first sp; the .GFA file is loaded here
bss_end:

	end
